def _compact_feedback(items, max_items=None, max_chars=None):
    max_items = max(1, int(max_items or QWEN_HISTORY_WINDOW))
    max_chars = max(500, int(max_chars or QWEN_FEEDBACK_MAX_CHARS))
    selected = list(items or [])[-max_items:]
    text = json.dumps(selected, ensure_ascii=False)
    if len(text) <= max_chars:
        return selected
    out=[]; used=2
    for item in reversed(selected):
        raw=json.dumps(item, ensure_ascii=False)
        if out and used + len(raw) + 1 > max_chars:
            break
        out.append(item); used += len(raw)+1
    return list(reversed(out))

PROJECT_STATE_FILE = "JARVIS_PROJECT_STATE.json"
PROJECT_JOURNAL_FILE = "JARVIS_PROJECT_JOURNAL.jsonl"
PROJECT_JOURNAL_TEXT_FILE = "JARVIS_PROJECT_JOURNAL.txt"
