def _pick_entrypoint(manifest, completed):
    requested = str(manifest.get("entrypoint") or "").replace("\\", "/").strip("/")
    if requested and requested in completed:
        return requested
    priority = ["main.py", "app.py", "calculator.py", "index.html", "src/main.py", "src/app.py", "server.py", "run.py"]
    lower_map = {item.lower(): item for item in completed}
    for name in priority:
        if name.lower() in lower_map:
            return lower_map[name.lower()]
    for item in completed:
        if item.lower().endswith(".py"):
            return item
    for item in completed:
        if item.lower().endswith(".html"):
            return item
    for item in completed:
        if item.lower().endswith(".js"):
            return item
    return completed[0] if completed else ""

def _write_windows_launchers(work, manifest, completed):
    entrypoint = _pick_entrypoint(manifest, completed)
    run_command = str(manifest.get("run_command") or "").strip()
    project_type = str(manifest.get("project_type") or "").lower().strip()

    if not run_command:
        low = entrypoint.lower()
        if low.endswith(".py"):
            run_command = f'python "{entrypoint}"'
            project_type = project_type or "python"
        elif low.endswith(".html"):
            run_command = f'start "" "{entrypoint}"'
            project_type = project_type or "web"
        elif (work / "package.json").exists():
            run_command = "npm start"
            project_type = project_type or "node"

    runner = [
        "@echo off", "setlocal", 'cd /d "%~dp0"', "echo.",
        "echo ========================================",
        "echo   JARVIS GENERATED PROJECT",
        "echo ========================================", "echo.",
    ]
    if project_type == "python" or entrypoint.lower().endswith(".py"):
        runner += [
            "where py >nul 2>nul",
            "if %errorlevel%==0 (",
            f'  py "{entrypoint}"',
            ") else (",
            f'  python "{entrypoint}"',
            ")",
        ]
    elif run_command:
        runner.append(run_command)
    else:
        runner += [
            "echo Jarvis could not infer an automatic run command.",
            "echo Open JARVIS_RUN_INSTRUCTIONS.txt for details.",
        ]
    runner += ["echo.", "pause"]
    (work / "RUN_PROJECT.bat").write_text("\r\n".join(runner) + "\r\n", encoding="utf-8")

    instructions = [
        "JARVIS GENERATED PROJECT - HOW TO RUN", "=====================================", "",
        f"Project: {manifest.get('project_name', 'generated-project')}",
        f"Entry point: {entrypoint or 'not detected'}",
        f"Run command: {run_command or 'not detected'}", "",
        "EASIEST OPTION ON WINDOWS:",
        "1. Extract this ZIP to a normal folder.",
        "2. Double-click RUN_PROJECT.bat.",
    ]
    if project_type == "python" or entrypoint.lower().endswith(".py"):
        instructions += [
            "", "OPTIONAL WINDOWS EXE:",
            "Double-click BUILD_EXE.bat to build a standalone EXE.",
        ]
        safe_name = _slug(manifest.get("project_name") or "jarvis-app").replace("-", "_")[:48]
        build = [
            "@echo off", "setlocal", 'cd /d "%~dp0"',
            "where py >nul 2>nul",
            "if %errorlevel%==0 (set PY=py) else (set PY=python)",
            "%PY% -m PyInstaller --version >nul 2>nul",
            "if errorlevel 1 (",
            "  %PY% -m pip install --user pyinstaller",
            "  if errorlevel 1 goto :fail",
            ")",
            f'%PY% -m PyInstaller --noconfirm --clean --onefile --name "{safe_name}" "{entrypoint}"',
            "if errorlevel 1 goto :fail", "echo.",
            f'echo EXE created: %CD%\\dist\\{safe_name}.exe',
            "explorer dist", "pause", "exit /b 0", ":fail", "echo.",
            "echo EXE build failed.", "pause", "exit /b 1",
        ]
        (work / "BUILD_EXE.bat").write_text("\r\n".join(build) + "\r\n", encoding="utf-8")

    (work / "JARVIS_RUN_INSTRUCTIONS.txt").write_text("\n".join(instructions) + "\n", encoding="utf-8")
    return entrypoint, run_command

def _package_workspace_zip(work, name_stem, stamp=None):
    work = Path(work)
    stamp = stamp or datetime.now().strftime("%Y%m%d_%H%M%S")
    safe = _slug(name_stem or work.name or "project")
    out = GENERATED_DIR / f"{safe}_{stamp}.zip"
    GENERATED_DIR.mkdir(parents=True, exist_ok=True)
    ignore_dirs = {
        ".git", ".svn", ".hg", "node_modules", "vendor", "dist", "build", "target",
        ".next", ".nuxt", ".idea", ".vscode", "__pycache__", ".pytest_cache",
        ".mypy_cache", ".venv", "venv", "env", ".dart_tool", ".gradle", "Pods",
        "DerivedData", ".jarvis_backups", ".jarvis_build", ".jarvis_candidates",
        ".jarvis_runtime", ".jarvis_failures",
    }
    file_count = 0
    with zipfile.ZipFile(out, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for path in sorted(work.rglob("*")):
            if not path.is_file():
                continue
            rel = path.relative_to(work)
            if any(part in ignore_dirs for part in rel.parts):
                continue
            if rel.name.startswith('JARVIS_QWEN_RAW_') or rel.name in {PROJECT_STATE_FILE, PROJECT_JOURNAL_FILE, PROJECT_JOURNAL_TEXT_FILE, V33_ARCHITECTURE_FILE, V33_BUILD_STATUS_FILE}:
                continue
            if rel.as_posix() == RESUME_METADATA_FILE or _is_sensitive_project_rel(rel):
                continue
            archive.write(path, rel.as_posix())
            file_count += 1
    return out, file_count

# V42.11 existing-project ZIP import policy. Resume ZIPs can contain gigabytes of
# rebuildable caches/checkpoints from a prior Jarvis run. Extracting those into an
# already-deep generated_projects/<resume>/working path can exceed Windows' classic
# path limit before Jarvis ever reaches the real source tree. They are not needed to
# repair the project, so prune them while preserving authored source and compact state.
V4211_ZIP_RESUME_IMPORT = True
_V4211_RESUME_SKIP_DIRS = {
    '.git', '.svn', '.hg', 'node_modules', 'vendor', 'dist', 'build', 'target',
    '.next', '.nuxt', '.idea', '.vscode', '__pycache__', '.pytest_cache',
    '.mypy_cache', '.ruff_cache', '.venv', 'venv', 'env', '.dart_tool',
    '.gradle', 'pods', 'deriveddata',
    '.jarvis_runtime', '.jarvis_build', '.jarvis_candidates', '.jarvis_backups',
}
_V4211_RESUME_SKIP_PREFIXES = (
    '.jarvis_failures/model_outputs/',
    '.jarvis_failures/patch_candidates/',
)


def _v4211_zip_common_wrapper(infos):
    """Return one archive wrapper directory when every real member shares it."""
    first = set()
    saw_nested = False
    for info in infos:
        name = str(getattr(info, 'filename', '') or '').replace('\\', '/').strip('/')
        if not name or name.endswith('/'):
            continue
        parts = [x for x in name.split('/') if x not in {'', '.'}]
        if not parts or '..' in parts:
            continue
        first.add(parts[0])
        saw_nested = saw_nested or len(parts) > 1
        if len(first) > 1:
            return ''
    return next(iter(first)) if len(first) == 1 and saw_nested else ''


def _v4211_resume_member_ignored(rel):
    parts = [str(x).lower() for x in Path(rel).parts]
    if any(part in _V4211_RESUME_SKIP_DIRS for part in parts):
        return True
    posix = Path(rel).as_posix().lower().lstrip('/')
    return any(posix.startswith(prefix) for prefix in _V4211_RESUME_SKIP_PREFIXES)


def _v4211_zip_is_symlink(info):
    # Unix mode lives in the upper 16 bits when present. Reject ZIP symlinks rather
    # than following them because a symlink target can escape the resume workspace.
    mode = (int(getattr(info, 'external_attr', 0) or 0) >> 16) & 0o170000
    return mode == 0o120000


def _v4211_windows_fs_path(path):
    """Return an extended-length Windows filesystem path when needed."""
    value = str(Path(path).resolve())
    if os.name != 'nt' or value.startswith('\\\\?\\'):
        return value
    if value.startswith('\\\\'):
        return '\\\\?\\UNC\\' + value.lstrip('\\')
    return '\\\\?\\' + value


def _v4211_mkdir(path):
    try:
        Path(path).mkdir(parents=True, exist_ok=True)
        return
    except (FileNotFoundError, OSError):
        if os.name != 'nt':
            raise
    os.makedirs(_v4211_windows_fs_path(path), exist_ok=True)


def _v4211_open_write(path):
    try:
        return Path(path).open('wb')
    except (FileNotFoundError, OSError):
        if os.name != 'nt':
            raise
    return open(_v4211_windows_fs_path(path), 'wb')


def _safe_extract_zip(source_zip, destination):
    """Safely import a project ZIP for repair/resume.

    V42.11 keeps traversal protection but is tolerant of rebuildable prior-run
    artifacts. It strips one redundant wrapper directory, skips caches and long
    diagnostic mirrors, rejects symlinks, creates parents before every write, and
    uses Windows extended-length paths as a fallback for legitimate authored files.

    Returns an extraction report. Existing callers may ignore the return value.
    """
    source_zip = Path(source_zip).resolve()
    destination = Path(destination).resolve()
    _v4211_mkdir(destination)
    report = {
        'source_zip': source_zip.name,
        'wrapper_stripped': '',
        'extracted': 0,
        'skipped_rebuildable': 0,
        'skipped_directories': 0,
        'rejected_symlinks': 0,
        'bytes_extracted': 0,
        'warnings': [],
    }
    with zipfile.ZipFile(source_zip, 'r') as zf:
        infos = list(zf.infolist())
        wrapper = _v4211_zip_common_wrapper(infos)
        report['wrapper_stripped'] = wrapper
        for info in infos:
            raw_name = str(info.filename or '').replace('\\', '/')
            if re.match(r'^[A-Za-z]:/', raw_name) or raw_name.startswith('//'):
                raise ValueError(f'Unsafe ZIP member: {raw_name}')
            name = raw_name.strip('/')
            if not name:
                continue
            # Validate the original archive path before wrapper manipulation.
            original_rel = _safe_relative(name)
            parts = list(original_rel.parts)
            if wrapper and parts and parts[0] == wrapper:
                parts = parts[1:]
            if not parts:
                report['skipped_directories'] += 1
                continue
            rel = Path(*parts)
            if info.is_dir() or name.endswith('/'):
                report['skipped_directories'] += 1
                continue
            if _v4211_zip_is_symlink(info):
                report['rejected_symlinks'] += 1
                report['warnings'].append(f'Rejected ZIP symlink: {name}')
                continue
            if _v4211_resume_member_ignored(rel):
                report['skipped_rebuildable'] += 1
                continue
            target = (destination / rel).resolve()
            if target != destination and destination not in target.parents:
                raise ValueError(f'Unsafe ZIP member: {name}')
            try:
                _v4211_mkdir(target.parent)
                with zf.open(info, 'r') as src, _v4211_open_write(target) as dst:
                    shutil.copyfileobj(src, dst, length=1024 * 1024)
                report['extracted'] += 1
                report['bytes_extracted'] += int(getattr(info, 'file_size', 0) or 0)
            except (FileNotFoundError, OSError) as exc:
                # Optional diagnostic mirrors must never kill a resume. Authored source
                # remains strict: if the long-path fallback also fails, surface it.
                low = rel.as_posix().lower()
                if _v4211_resume_member_ignored(rel) or (rel.suffix.lower() == '.txt' and '.jarvis_' in low):
                    report['warnings'].append(f'Skipped optional resume artifact {name}: {exc}')
                    report['skipped_rebuildable'] += 1
                    continue
                raise OSError(f'Unable to extract required project member {name}: {exc}') from exc
    try:
        (destination / 'JARVIS_V4211_IMPORT_REPORT.json').write_text(
            json.dumps(report, indent=2), encoding='utf-8'
        )
    except Exception:
        pass
    return report
def _validate_python_files(work):
    failures = []
    checked = 0
    for path in sorted(work.rglob("*.py")):
        checked += 1
        try:
            source = path.read_text(encoding="utf-8")
            compile(source, str(path), "exec")
        except Exception as exc:
            failures.append((path, str(exc)))
    return checked, failures

def _repair_python_file(user_request, manifest, work, path, error, progress_callback=None):
    """Compatibility wrapper: syntax repairs now use the same transactional repair path."""
    path = Path(path)
    try:
        rel = path.relative_to(Path(work)).as_posix()
    except Exception:
        rel = path.name
    if '_repair_file_for_issues' in globals():
        return _repair_file_for_issues(
            user_request, manifest, work, rel,
            [f'Python syntax error requiring a complete full-file rewrite: {error}'],
            progress_callback,
        )
    return False


_SOURCE_SUFFIXES = {
    '.py','.pyw','.js','.mjs','.cjs','.jsx','.ts','.tsx','.java','.cs','.go','.rs','.dart',
    '.php','.rb','.swift','.kt','.kts','.c','.cc','.cpp','.cxx','.h','.hh','.hpp','.hxx',
    '.vue','.svelte','.sol','.zig','.lua','.ex','.exs','.scala','.r','.pl','.hs','.fs','.fsx',
    '.html','.htm','.css','.scss','.less','.sh','.bash','.ps1','.sql',
}


_COMPILED_SOURCE_SUFFIXES = {'.c','.cc','.cpp','.cxx','.cs','.go','.rs','.java','.swift','.kt','.kts'}

_TEXT_EXTENSIONS = {
    '.py','.pyw','.js','.jsx','.ts','.tsx','.html','.htm','.css','.scss','.less',
    '.json','.jsonc','.yaml','.yml','.toml','.ini','.cfg','.conf','.env','.md','.txt',
    '.xml','.svg','.sql','.sh','.bash','.ps1','.bat','.cmd','.c','.h','.cc','.cpp','.hpp',
    '.cs','.java','.kt','.kts','.go','.rs','.rb','.php','.swift','.dart','.vue','.svelte',
    '.gradle','.properties','.lock','.gitignore','.dockerfile'
}
_ANALYSIS_IGNORE_DIRS = {
    '.git','.svn','.hg','node_modules','vendor','dist','build','target','.next','.nuxt',
    '.idea','.vscode','__pycache__','.pytest_cache','.mypy_cache','.ruff_cache','.venv','venv','env',
    '.dart_tool','.gradle','Pods','DerivedData','.jarvis_backups','.jarvis_build','.jarvis_candidates',
    '.jarvis_runtime','.jarvis_failures','.cache','coverage','.turbo','.parcel-cache','.angular','.svelte-kit',
    'out','bin','obj'
}

def _looks_text_file(path):
    path = Path(path)
    if any(part in _ANALYSIS_IGNORE_DIRS for part in path.parts):
        return False
    name = path.name.lower()
    ext = path.suffix.lower()
    if name == RESUME_METADATA_FILE.lower() or _is_sensitive_project_rel(path):
        return False
    if ext in _TEXT_EXTENSIONS or name in {'dockerfile','makefile','cmakelists.txt','requirements.txt','package.json','pubspec.yaml'}:
        return True
    try:
        data = path.read_bytes()[:8192]
    except Exception:
        return False
    if b'\x00' in data:
        return False
    if not data:
        return True
    try:
        data.decode('utf-8')
        return True
    except Exception:
        return False

def _existing_project_text_files(work):
    files=[]
    for path in sorted(Path(work).rglob('*')):
        if not path.is_file():
            continue
        rel = path.relative_to(work)
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel.parts):
            continue
        if rel.name.startswith('JARVIS_') or rel.as_posix() == RESUME_METADATA_FILE:
            continue
        if _is_sensitive_project_rel(rel):
            continue
        if _looks_text_file(path):
            files.append(rel.as_posix())
    return files

def _acceptance_criteria(manifest, user_request):
    values = manifest.get("acceptance_criteria") or manifest.get("requirements") or []
    if isinstance(values, str):
        values = [values]
    criteria = [str(x).strip() for x in values if str(x).strip()]
    if not criteria:
        criteria = [f"The finished project satisfies the complete user request: {user_request}"]
    return criteria[:40]

def _static_project_checks(work, completed, manifest=None):
    work = Path(work)
    issues = []
    completed = list(completed or [])
    
    py_checked, py_failures = _validate_python_files(work)
    for path, error in py_failures:
        issues.append(f'Python syntax: {path.relative_to(work).as_posix()}: {error}')

    real_sources = _existing_real_source_files(work)
    if not real_sources:
        issues.append('No real project source files exist (launchers/instructions do not count).')

    entry = str((manifest or {}).get('entrypoint') or '').replace('\\','/').strip()
    if entry:
        entry_path = work / entry
        if not entry_path.exists():
            issues.append(f'Entrypoint not found: {entry}')
        elif entry_path.stat().st_size == 0:
            issues.append(f'Entrypoint is empty: {entry}')
        elif not _is_real_source_rel(Path(entry)):
            issues.append(f'Entrypoint is not a real source file: {entry}')

    return {
        'complete': not issues,
        'issues': issues,
        'python_files_checked': py_checked,
        'python_failures': py_failures,
    }

_JARVIS_FILE_HEADER_RE = re.compile(
    r'^\s*<<<JARVIS_FILE\s+path\s*=\s*(?:"([^"]+)"|\'([^\']+)\'|([^\s>]+))\s*>>>\s*$'
)
_JARVIS_FILE_END_RE = re.compile(r'^\s*<<<JARVIS_END_FILE>>>\s*$')


def _jarvis_file_transport_instructions(expected_path=None, multi=True):
    """Return the exact raw-source envelope contract used with small local models."""
    if expected_path:
        example_path = str(expected_path).replace('\\', '/')
    else:
        example_path = 'relative/path.ext'
    scope = 'For EACH file' if multi else 'For this ONE file'
    return (
        "JARVIS RAW FILE TRANSPORT v1:\n"
        f"{scope}, emit exactly this envelope:\n"
        f"<<<JARVIS_FILE path=\"{example_path}\">>>\n"
        "<raw UTF-8 file contents, starting at the real first character>\n"
        "<<<JARVIS_END_FILE>>>\n\n"
        "TRANSPORT RULES:\n"
        "- Do not use Markdown fences.\n"
        "- Do not emit prose, summaries, headings, or notes outside file envelopes.\n"
        "- Paths must be relative project paths; never use absolute paths or '..'.\n"
        "- Emit every requested file exactly once. No duplicate path envelopes.\n"
        "- Never abbreviate, elide, or replace code with TODO/pass/ellipsis/rest-of-code comments.\n"
        "- The end marker must be on its own line after the complete file.\n"
        "- Do not place JARVIS_FILE/JARVIS_END_FILE marker lines inside source contents.\n"
    )


def _parse_jarvis_file_blocks(text, expected_paths=None, strict_outside=None):
    """Parse complete JARVIS_FILE envelopes without allowing traversal, duplicates, or truncation.

    Returns ([(relative_path, content), ...], errors). Any structural error means callers should
    treat the envelope response as untrusted and use another generation/recovery strategy instead
    of writing a partial repository.
    """
    raw = str(text or '').replace('\ufeff', '')
    if strict_outside is None:
        strict_outside = JARVIS_FILE_BLOCK_STRICT_OUTSIDE
    expected = None
    if expected_paths is not None:
        expected = set()
        for value in expected_paths:
            try:
                expected.add(_safe_relative(value).as_posix())
            except Exception:
                expected.add(str(value).replace('\\', '/').strip('/'))

    lines = raw.splitlines(keepends=True)
    results = []
    errors = []
    seen = set()
    duplicate = set()
    current = None
    current_lines = []
    outside_nonblank = []

    def start_match(line):
        return _JARVIS_FILE_HEADER_RE.match(line.rstrip('\r\n'))

    for line_no, line in enumerate(lines, 1):
        header = start_match(line)
        is_end = bool(_JARVIS_FILE_END_RE.match(line.rstrip('\r\n')))
        if header:
            if current is not None:
                errors.append(
                    f"Unterminated JARVIS_FILE block for {current!r} before new header at line {line_no}."
                )
                current = None
                current_lines = []
            raw_path = next((g for g in header.groups() if g is not None), '')
            try:
                rel = _safe_relative(raw_path).as_posix()
            except Exception as exc:
                errors.append(f"Unsafe JARVIS_FILE path {raw_path!r} at line {line_no}: {exc}")
                current = '__JARVIS_INVALID_PATH__'
                current_lines = []
                continue
            p = Path(rel)
            if p.name in _RESERVED_OUTPUT_NAMES or p.name.startswith('JARVIS_'):
                errors.append(f"Reserved Jarvis output path is not allowed in model file blocks: {rel}")
                current = '__JARVIS_INVALID_PATH__'
                current_lines = []
                continue
            key = rel.lower()
            if key in seen:
                duplicate.add(key)
                errors.append(f"Duplicate JARVIS_FILE path: {rel}")
            current = rel
            current_lines = []
            continue

        if is_end:
            if current is None:
                errors.append(f"Unexpected {JARVIS_FILE_BLOCK_END} at line {line_no}.")
                continue
            if current == '__JARVIS_INVALID_PATH__':
                current = None
                current_lines = []
                continue
            content = ''.join(current_lines)
            if not content.strip() and not _allows_empty_generated_file(current):
                errors.append(f"JARVIS_FILE block is empty: {current}")
            else:
                key = current.lower()
                seen.add(key)
                results.append((current, content))
            current = None
            current_lines = []
            continue

        if current is not None:
            current_lines.append(line)
        elif line.strip():
            outside_nonblank.append((line_no, line.strip()[:240]))

    if current is not None:
        if current != '__JARVIS_INVALID_PATH__':
            errors.append(f"Unterminated JARVIS_FILE block for {current!r}; final end marker is missing.")
        else:
            errors.append("Unterminated invalid JARVIS_FILE block; final end marker is missing.")

    if strict_outside and outside_nonblank:
        sample = '; '.join(f"line {ln}: {value}" for ln, value in outside_nonblank[:4])
        errors.append(f"Non-whitespace text appeared outside JARVIS_FILE envelopes ({sample}).")

    if duplicate:
        results = [(p, c) for p, c in results if p.lower() not in duplicate]

    if expected is not None:
        actual = {p for p, _ in results}
        unexpected = sorted(actual - expected)
        missing = sorted(expected - actual)
        if unexpected:
            errors.append("Unexpected JARVIS_FILE path(s): " + ', '.join(unexpected[:12]))
        if missing:
            errors.append("Missing expected JARVIS_FILE path(s): " + ', '.join(missing[:12]))

    return results, errors


def _complete_jarvis_file_blocks(text, expected_paths=None, strict_outside=None):
    candidates, errors = _parse_jarvis_file_blocks(text, expected_paths, strict_outside)
    return candidates if candidates and not errors else []


def _parse_multifile_repair(text, fallback_rel=None):
    raw_transport = str(text or '')
    attempted_blocks = '<<<JARVIS_FILE' in raw_transport or JARVIS_FILE_BLOCK_END in raw_transport
    block_candidates, block_errors = _parse_jarvis_file_blocks(text, strict_outside=True)
    if block_candidates and not block_errors:
        return block_candidates, 'JARVIS_FILE transport'
    if attempted_blocks and block_errors:
        return [], 'Malformed JARVIS_FILE transport: ' + '; '.join(block_errors[:6])
    try:
        obj=_extract_json(text)
        files=obj.get('files') or []
        if isinstance(files, dict): files=[files]
        out=[]
        for item in files:
            if not isinstance(item,dict): continue
            path=item.get('path'); content=item.get('content')
            if content is None:
                content = item.get('code') or item.get('source') or item.get('text')
            if path and content is not None:
                out.append((str(path), _strip_fence(str(content))))
        if out:
            return out, str(obj.get('summary') or '')
    except Exception:
        pass
    if fallback_rel:
        return [(str(fallback_rel), _strip_fence(text))], 'legacy single-file repair response'
    return [], ''

_RESERVED_OUTPUT_NAMES = {
    'RUN_PROJECT.bat',
    'BUILD_EXE.bat',
    'JARVIS_RUN_INSTRUCTIONS.txt',
    'JARVIS_QWEN_RAW_bootstrap.txt',
    PROJECT_STATE_FILE,
    PROJECT_JOURNAL_FILE,
    PROJECT_JOURNAL_TEXT_FILE,
    V33_ARCHITECTURE_FILE,
    V33_BUILD_STATUS_FILE,
    V34_TOOLCHAIN_FILE,
}


def _is_real_source_rel(rel):
    rel = Path(rel)
    if rel.name in _RESERVED_OUTPUT_NAMES or rel.name.startswith('JARVIS_QWEN_RAW_'):
        return False
    if any(part in _ANALYSIS_IGNORE_DIRS for part in rel.parts):
        return False
    return rel.suffix.lower() in _SOURCE_SUFFIXES


def _existing_real_source_files(work):
    out = []
    root = Path(work)
    for path in sorted(root.rglob('*')):
        if not path.is_file():
            continue
        rel = path.relative_to(root)
        if _is_real_source_rel(rel) and path.stat().st_size > 0:
            out.append(rel.as_posix())
    return out


def _candidate_files_valid(work, candidates):
    """Validate candidate files but ACCEPT them even with syntax errors - they'll be fixed later."""
    errors=[]; changed=[]
    for rel_raw,content in candidates:
        try: 
            rel=_safe_relative(rel_raw)
        except Exception as exc:
            errors.append(f'{rel_raw}: unsafe path ({exc})'); 
            continue
        
        # Skip empty content
        if not content or not content.strip():
            errors.append(f'{rel_raw}: empty content')
            continue
            
        if rel.name in _RESERVED_OUTPUT_NAMES or rel.name.startswith('JARVIS_QWEN_RAW_'):
            errors.append(f'{rel.as_posix()}: reserved Jarvis output name ignored')
            continue

        target=Path(work)/rel
        
        # Check for Python syntax errors but DON'T skip - just log
        if target.suffix.lower() in {'.py','.pyw'}:
            try: 
                compile(content, str(target), 'exec')
            except Exception as exc:
                errors.append(f'{rel.as_posix()}: Python syntax error (will fix): {exc}')
                # Still include the file - it will be repaired in finish rounds
        
        changed.append((rel,content))
    return changed, errors

def _direct_completion_edit(user_request, manifest, criteria, work, completed, unresolved=None, feedback=None, progress_callback=None):
    """Multi-file edit path using raw JARVIS_FILE envelopes first, schema JSON only as fallback."""
    work = Path(work)
    context_chunks = []
    used = 0
    cap = _optional_positive_limit(DIRECT_PROJECT_CONTEXT_CHARS) if '_optional_positive_limit' in globals() else None

    for rel in completed:
        path = work / rel
        if not path.exists() or not path.is_file() or not _looks_text_file(path):
            continue
        try:
            source = path.read_text(encoding='utf-8', errors='replace')
        except Exception:
            continue
        piece = f'===== EXISTING FILE {rel} =====\n{source}\n===== END EXISTING FILE {rel} =====\n'
        if cap is not None and used + len(piece) > cap:
            continue
        context_chunks.append(piece)
        used += len(piece)

    context = '\n\n'.join(context_chunks)
    base_prompt = (
        "You are editing a software project. Implement the requested changes completely.\n"
        "Return complete replacement source files only; do not emit patches or omitted sections.\n"
        "Do not change unrelated APIs merely to make one failure disappear.\n\n"
        f"USER REQUEST:\n{user_request}\n\n"
        f"UNRESOLVED:\n{json.dumps(unresolved or [], ensure_ascii=False)}\n\n"
        f"AUTHORITATIVE ARCHITECTURE CONTRACT:\n{_v33_contract_index(manifest) if '_v33_contract_index' in globals() else ''}\n\n"
        f"IMPLEMENTED PROJECT API INDEX:\n{_project_api_index(work) if '_project_api_index' in globals() else ''}\n\n"
        f"EXISTING FILES:\n{context}\n"
    )

    candidates = []
    summary = ''
    transport_reason = ''

    if JARVIS_FILE_BLOCK_TRANSPORT:
        block_prompt = base_prompt + "\n" + _jarvis_file_transport_instructions(None, multi=True)
        ok, raw = _qwen_call(
            block_prompt, progress_callback, 'Direct edit FILE transport',
            max_tokens=_qwen_file_output_limit(),
            thinking=False, strict_output=True,
        )
        if ok:
            blocks, block_errors = _parse_jarvis_file_blocks(raw, strict_outside=JARVIS_FILE_BLOCK_STRICT_OUTSIDE)
            if blocks:
                # Complete envelopes that arrived before a truncated final envelope are still valid
                # candidates. Keep them; acceptance/transaction gates will verify each file independently.
                candidates = blocks
                summary = 'JARVIS_FILE transport'
                if block_errors:
                    transport_reason = '; '.join(block_errors[:6])
            else:
                transport_reason = '; '.join(block_errors[:6]) or 'No complete JARVIS_FILE blocks returned.'
        else:
            transport_reason = str(raw)

    if not candidates:
        json_prompt = (
            base_prompt
            + "\nFILE TRANSPORT FALLBACK: Return ONLY JSON matching the requested schema.\n"
            + '{"summary":"changes","files":[{"path":"file.py","content":"complete code"}]}'
        )
        ok, raw = _qwen_call(
            json_prompt, progress_callback, 'Direct edit JSON fallback',
            max_tokens=_qwen_file_output_limit(),
            thinking=False, response_schema=QWEN_SCHEMA_FILE_REPLACEMENTS,
            schema_name='direct_edit', strict_output=True,
        )
        if not ok:
            return {'changed': [], 'reason': transport_reason or str(raw), 'summary': ''}
        candidates, summary = _parse_multifile_repair(raw, None)
        if not candidates:
            return {
                'changed': [],
                'reason': transport_reason or 'Neither JARVIS_FILE nor JSON fallback returned complete files.',
                'summary': summary,
            }

    written = []
    rejected = []
    for rel_raw, content in candidates:
        try:
            rel = _safe_relative(rel_raw)
            if rel.name in _RESERVED_OUTPUT_NAMES or rel.name.startswith('JARVIS_'):
                rejected.append(f'{rel.as_posix()}: reserved Jarvis path')
                continue
            rel_text = rel.as_posix()
            cleaned = _extract_single_file_response(content, rel_text)
            target = work / rel
            target.parent.mkdir(parents=True, exist_ok=True)

            tx_error = _candidate_transaction_error(work, manifest, rel_text, cleaned) if '_candidate_transaction_error' in globals() else _content_validation_error(rel_text, cleaned)
            if tx_error:
                rejected.append(f'{rel_text}: {tx_error}')
                _save_candidate_draft(work, rel_text, cleaned)
                continue

            tmp = target.with_name(target.name + '.jarvis_tmp')
            tmp.write_text(cleaned, encoding='utf-8')
            tmp.replace(target)
            _delete_candidate_draft(work, rel_text)
            written.append(rel_text)
        except Exception as exc:
            rejected.append(f'{rel_raw}: {exc}')
    return {
        'changed': written,
        'reason': '; '.join(rejected[:8]) or ('' if written else transport_reason),
        'summary': summary,
    }


def _recover_complete_json_file_pairs(text):
    raw = str(text or '')
    decoder = json.JSONDecoder()
    out = []
    seen = set()
    path_key = re.compile(r'"(?:path|name|filename|file)"\s*:\s*')
    content_key = re.compile(r'"(?:content|code|source|text)"\s*:\s*')
    pos = 0
    while True:
        match = path_key.search(raw, pos)
        if not match:
            break
        try:
            path, path_end = decoder.raw_decode(raw, match.end())
        except Exception:
            pos = match.end()
            continue
        if not isinstance(path, str):
            pos = max(path_end, match.end() + 1)
            continue
        next_path = path_key.search(raw, path_end)
        content_match = content_key.search(raw, path_end)
        if not content_match or (next_path and content_match.start() > next_path.start()):
            pos = max(path_end, match.end() + 1)
            continue
        try:
            content, content_end = decoder.raw_decode(raw, content_match.end())
        except Exception:
            pos = max(content_match.end(), path_end)
            continue
        if not isinstance(content, str):
            pos = max(content_end, content_match.end() + 1)
            continue
        key = path.replace('\\', '/').lower()
        if key not in seen:
            seen.add(key)
            out.append((path, _strip_fence(content)))
        pos = max(content_end, content_match.end() + 1)
    return out

def _recover_json_string_field(text, field):
    raw = str(text or '')
    match = re.search(r'"' + re.escape(str(field)) + r'"\s*:\s*', raw)
    if not match:
        return ''
    try:
        value, _ = json.JSONDecoder().raw_decode(raw, match.end())
    except Exception:
        return ''
    return value if isinstance(value, str) else ''

def _recover_declared_json_paths(text):
    raw = str(text or '')
    decoder = json.JSONDecoder()
    pattern = re.compile(r'"(?:path|name|filename|file)"\s*:\s*')
    out = []
    pos = 0
    while True:
        match = pattern.search(raw, pos)
        if not match:
            break
        try:
            value, end = decoder.raw_decode(raw, match.end())
        except Exception:
            pos = match.end()
            continue
        pos = max(end, match.end() + 1)
        if not isinstance(value, str):
            continue
        try:
            rel = _safe_relative(value).as_posix()
        except Exception:
            continue
        if rel not in out:
            out.append(rel)
    return out

def _parse_direct_project_bootstrap(text):
    raw = str(text or '')
    attempted_blocks = '<<<JARVIS_FILE' in raw or JARVIS_FILE_BLOCK_END in raw
    block_candidates, block_errors = _parse_jarvis_file_blocks(raw, strict_outside=True)
    if block_candidates and not block_errors:
        return {}, block_candidates
    if attempted_blocks and block_errors:
        return {}, []

    obj = {}
    try:
        obj = _extract_json(text)
    except Exception:
        obj = {}

    candidates = []
    files = obj.get('files') or [] if isinstance(obj, dict) else []
    if isinstance(files, dict):
        files = [files]
    for item in files:
        if not isinstance(item, dict):
            continue
        path = item.get('path') or item.get('name') or item.get('filename') or item.get('file')
        content = item.get('content')
        if content is None:
            content = item.get('code') or item.get('source') or item.get('text')
        if path and content is not None:
            candidates.append((str(path), _strip_fence(str(content))))

    if candidates:
        return obj, candidates

    recovered = _recover_complete_json_file_pairs(_escape_raw_json_control_chars(raw))
    if recovered:
        if not isinstance(obj, dict):
            obj = {}
        declared_paths = _recover_declared_json_paths(raw)
        if declared_paths and not (obj.get('files') or []):
            obj['files'] = [{'path': path} for path in declared_paths]
        if not obj.get('entrypoint'):
            recovered_entry = _recover_json_string_field(raw, 'entrypoint')
            if recovered_entry:
                try:
                    obj['entrypoint'] = _safe_relative(recovered_entry).as_posix()
                except Exception:
                    pass
        if not obj.get('project_name'):
            recovered_name = _recover_json_string_field(raw, 'project_name')
            if recovered_name:
                obj['project_name'] = recovered_name
        return obj, recovered

    patterns = [
        re.compile(r'(?:^|\n)\s*(?:={3,}\s*)?(?:FILE\s*[:=]\s*|FILE\s+)([^\n=]+?)(?:\s*={3,})?\s*\n```[^\n]*\n(.*?)```', re.I | re.S),
        re.compile(r'(?:^|\n)\s*#{1,3}\s*([A-Za-z0-9_./\\-]+\.[A-Za-z0-9]+)\s*\n```[^\n]*\n(.*?)```', re.I | re.S),
        re.compile(r'(?:^|\n)\s*([A-Za-z0-9_./\\-]+\.[A-Za-z0-9]+)\s*\n```[^\n]*\n(.*?)```', re.I | re.S),
        re.compile(r'(?:^|\n)\s*(?://|#)\s*([A-Za-z0-9_./\\-]+\.[A-Za-z0-9]+)\s*\n```[^\n]*\n(.*?)```', re.I | re.S),
    ]

    seen = set()
    for pattern in patterns:
        for match in pattern.finditer(raw):
            path = match.group(1).strip().strip('`"\' ')
            if not path or path.lower() in {'python', 'javascript', 'js', 'ts', 'tsx', 'html', 'css', 'json', 'bash', 'sh', 'text', 'plaintext'}:
                continue
            if '/' not in path and '\\' not in path and '.' not in path:
                continue
            content = match.group(2)
            key = path.replace('\\', '/').lower()
            if key in seen:
                continue
            seen.add(key)
            candidates.append((path, content.rstrip() + '\n'))

    if not isinstance(obj, dict):
        obj = {}
    declared_paths = _recover_declared_json_paths(raw)
    if declared_paths and not (obj.get('files') or []):
        obj['files'] = [{'path': path} for path in declared_paths]
    if not obj.get('entrypoint'):
        recovered_entry = _recover_json_string_field(raw, 'entrypoint')
        if recovered_entry:
            try:
                obj['entrypoint'] = _safe_relative(recovered_entry).as_posix()
            except Exception:
                pass
    if not obj.get('project_name'):
        recovered_name = _recover_json_string_field(raw, 'project_name')
        if recovered_name:
            obj['project_name'] = recovered_name
    return obj, candidates

def _bootstrap_manifest_from_files(user_request, obj, candidates):
    paths = [str(path).replace('\\', '/') for path, _ in candidates]
    names = {Path(x).name.lower(): x for x in paths}
    
    entry = (obj or {}).get('entrypoint') if isinstance(obj, dict) else ''
    if not entry or entry not in paths:
        entry = ''
        for name in ('main.py','app.py','index.py','run.py','server.py','index.html','main.js'):
            if name in names:
                entry = names[name]
                break
        if not entry and paths:
            # Pick first Python or HTML file, or just first file
            for p in paths:
                if p.endswith('.py') or p.endswith('.html'):
                    entry = p
                    break
            if not entry:
                entry = paths[0]
    
    criteria = []
    if isinstance(obj, dict):
        values = obj.get('acceptance_criteria') or []
        if isinstance(values, str):
            values = [values]
        criteria = [str(x).strip() for x in values if str(x).strip()][:40]
    if not criteria:
        criteria = [f"The project works as requested: {user_request}"]
        
    project_name = (obj or {}).get('project_name') if isinstance(obj, dict) else ''
    if not project_name:
        project_name = _slug(Path(paths[0]).stem if paths else 'project')
        
    result = {
        'project_name': project_name,
        'summary': str((obj or {}).get('summary') or 'Generated project') if isinstance(obj, dict) else 'Generated project',
        'project_type': str((obj or {}).get('project_type') or 'software') if isinstance(obj, dict) else 'software',
        'entrypoint': entry,
        'run_command': str((obj or {}).get('run_command') or '') if isinstance(obj, dict) else '',
        'acceptance_criteria': criteria,
        'files': [{'path': path, 'purpose': 'Source file', 'phase': _v33_infer_phase(path,''), 'depends_on': [], 'exports': [], 'contracts': []} for path in paths],
    }
    return _v34_apply_toolchain_defaults(user_request, result)

