def _project_plan_prompt(user_request, max_files):
    return (
        "You are the lead software architect for a GENERAL-PURPOSE autonomous software builder. "
        "The request may be a calculator, web site, iOS/Android app, C++ desktop program, game, API, CLI, Unreal project, or an uncommon stack.\n"
        "Return ONLY strict manifest JSON; do not emit source code yet.\n"
        "V34.1 UNIVERSAL SYSTEMATIC BUILD RULES:\n"
        "- Infer the appropriate platform, language, framework, build system and package manager from the request. Never default to Python merely because a stack is unfamiliar.\n"
        "- project_type is FREE-FORM, not an enum. Populate platform/language/framework/build_system/package_manager/required_tools and dependency/build/test/run commands when known.\n"
        "- Design the complete repository and public contracts BEFORE implementation. Every caller must have a planned provider contract.\n"
        "- For every file specify phase, exact depends_on project paths, exports, and concise language-appropriate contracts/signatures.\n"
        "- Avoid circular dependencies. Foundation/types/config -> persistence/data -> services/domain -> UI/adapters -> integration/entrypoint -> tests/docs.\n"
        "- Follow the CONVENTIONAL repository/build layout for the chosen ecosystem (Cargo, CMake, Gradle, Xcode/SwiftPM, Flutter, npm, UnrealBuildTool, Unity, etc.).\n"
        "- Do not force CMake onto Unreal, dotnet onto Unity, or Xcode validation onto a non-Apple host. Choose the native toolchain.\n"
        "- Include dependency/bootstrap commands that can be executed non-interactively. Build/test commands must prove the project rather than merely inspect files.\n"
        "- Keep modules focused; split responsibilities likely to exceed " + str(V33_MAX_FILE_LINES) + " lines.\n"
        "- Do not include Jarvis-owned RUN_PROJECT.bat, BUILD_EXE.bat, JARVIS_RUN_INSTRUCTIONS.txt, or JARVIS_* files.\n"
        f"Maximum planned files: {max_files}.\n\n"
        f"USER REQUEST:\n{user_request}\n\n"
        f"{_stack_lock_instructions(user_request)}\n"
        "Return a complete manifest object. Example SHAPE only (values must match the requested stack):\n"
        '{"project_name":"name","summary":"summary","project_type":"arbitrary project kind",'
        '"platform":"windows|web|android|ios|cross-platform|...","language":"...","framework":"...",'
        '"build_system":"...","package_manager":"...","required_tools":["..."],'
        '"dependency_command":"...","build_command":"...","test_command":"...",'
        '"entrypoint":"relative/path","run_command":"...","acceptance_criteria":["..."],'
        '"architecture_rules":["..."],"shared_contracts":["..."],'
        '"files":[{"path":"...","purpose":"...","phase":"foundation","depends_on":[],"exports":[],"contracts":[]}]} '
    )

def _allows_empty_generated_file(rel):
    """Some legitimate project files are intentionally empty and must not fail bootstrap."""
    p = Path(str(rel or '').replace('\\', '/'))
    name = p.name.lower()
    return name == '__init__.py'


def _valid_planned_project_path(rel):
    """Reject prose accidentally emitted in a manifest's path field while allowing normal project files."""
    try:
        p = Path(rel)
    except Exception:
        return False
    name = p.name
    if not name or name in {'.', '..'}:
        return False
    if name in _RESERVED_OUTPUT_NAMES or name.startswith('JARVIS_'):
        return False
    # A trailing dot is especially common when the model accidentally places prose in "path".
    if name.endswith('.'):
        return False
    special = {
        'dockerfile', 'makefile', 'cmakelists.txt', 'requirements.txt',
        'package.json', 'package-lock.json', 'pubspec.yaml', 'cargo.toml',
        'go.mod', 'go.sum', '.gitignore', '.env.example', 'pyproject.toml',
        'setup.py', 'setup.cfg', 'readme.md', 'license', 'license.txt', 'gemfile', 'rakefile',
        'podfile', 'package.swift', 'build.gradle', 'settings.gradle', 'build.gradle.kts', 'settings.gradle.kts',
        'composer.json', 'mix.exs', 'stack.yaml', 'cabal.project', 'angular.json',
    }
    low = name.lower()
    if low in special:
        return True
    suffix = p.suffix.lower()
    if not suffix or suffix == '.':
        return False
    # Keep this permissive for normal code/assets/config, but require a real extension.
    return bool(re.fullmatch(r'\.[a-z0-9][a-z0-9._+-]{0,15}', suffix, flags=re.I))


def _normalize_export_contract(values):
    if values is None:
        return []
    if isinstance(values, str):
        values = [values]
    out = []
    for value in values or []:
        name = str(value or "").strip()
        if not name or name.startswith("_"):
            continue
        # Python/JS/C#/etc. public symbol names are normally identifier-like. Keep dotted names out
        # because the contract is for names exported by THIS file/module.
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name) and name not in out:
            out.append(name)
    return out[:80]


def _v33_normalize_contract_lines(values, limit=120):
    if values is None:
        return []
    if isinstance(values, str):
        values = [values]
    out = []
    for value in values or []:
        text = re.sub(r"\s+", " ", str(value or "").strip())
        if text and text not in out:
            out.append(text[:500])
        if len(out) >= limit:
            break
    return out


def _v33_infer_phase(path, purpose=""):
    rel = str(path or "").replace("\\", "/").lower()
    low = (rel + " " + str(purpose or "").lower())
    if any(x in low for x in ("test", "tests/", "spec")):
        return "test"
    if any(x in low for x in ("readme", ".md", "docs/", "license")):
        return "docs"
    if any(x in low for x in ("main.py", "app.py", "entrypoint", "bootstrap", "launcher")):
        return "integration"
    if any(x in low for x in ("ui/", "view", "window", "dialog", "widget", "screen")):
        return "ui"
    if any(x in low for x in ("service", "controller", "manager", "use_case", "usecase")):
        return "service"
    if any(x in low for x in ("database", "repository", "storage", "sqlite", "dao", "persistence")):
        return "data"
    return "foundation"


def _v33_normalize_dep_paths(values, own_path=""):
    if values is None:
        return []
    if isinstance(values, str):
        values = [values]
    out = []
    own = str(own_path or "").replace("\\", "/").strip("/")
    for value in values or []:
        try:
            rel = _safe_relative(value).as_posix()
        except Exception:
            continue
        if rel and rel != own and rel not in out:
            out.append(rel)
    return out[:80]


def _sanitize_manifest_files(files, max_files):
    out = []
    seen = set()
    for item in files or []:
        if not isinstance(item, dict):
            continue
        raw_path = item.get('path') or item.get('name') or item.get('filename')
        if not raw_path:
            continue
        try:
            rel = _safe_relative(raw_path)
        except Exception:
            continue
        if not _valid_planned_project_path(rel):
            continue
        key = rel.as_posix().lower()
        if key in seen:
            continue
        seen.add(key)
        purpose = str(item.get('purpose') or item.get('description') or 'Required project file').strip()
        phase = str(item.get('phase') or '').strip().lower()
        if phase not in V33_PHASE_ORDER:
            phase = _v33_infer_phase(rel.as_posix(), purpose)
        out.append({
            'path': rel.as_posix(),
            'purpose': purpose,
            'phase': phase,
            'depends_on': _v33_normalize_dep_paths(item.get('depends_on') or item.get('dependencies'), rel.as_posix()),
            'exports': _normalize_export_contract(
                item.get('exports') or item.get('public_exports') or item.get('symbols') or item.get('public_api')
            ),
            'contracts': _v33_normalize_contract_lines(
                item.get('contracts') or item.get('signatures') or item.get('interfaces')
            ),
        })
        if len(out) >= max_files:
            break
    return out



def _parse_project_plan(text, user_request, max_files):
    try:
        obj = _extract_json(text)
    except Exception:
        return None
    if not isinstance(obj, dict):
        return None
    raw_files = obj.get('files') or []
    if isinstance(raw_files, dict): raw_files = [raw_files]
    files = _sanitize_manifest_files(raw_files, max_files)
    if not files: return None
    paths = {x['path'] for x in files}
    for item in files:
        item['depends_on'] = [d for d in item.get('depends_on', []) if d in paths and d != item['path']]
    entry = str(obj.get('entrypoint') or '').replace('\\','/').strip('/')
    if entry not in paths:
        entry = _pick_entrypoint({'entrypoint': entry}, list(paths))
    criteria = obj.get('acceptance_criteria') or obj.get('requirements') or []
    if isinstance(criteria, str): criteria=[criteria]
    criteria=[str(x).strip() for x in criteria if str(x).strip()][:80]
    if not criteria: criteria=[f'The finished project satisfies the complete user request: {user_request}']
    result = {
        'project_name': str(obj.get('project_name') or 'project'),
        'summary': str(obj.get('summary') or 'Generated project'),
        'project_type': str(obj.get('project_type') or 'software'),
        'platform': str(obj.get('platform') or ''), 'language': str(obj.get('language') or ''),
        'framework': str(obj.get('framework') or ''), 'build_system': str(obj.get('build_system') or ''),
        'package_manager': str(obj.get('package_manager') or ''),
        'required_tools': [str(x).strip() for x in (obj.get('required_tools') or []) if str(x).strip()][:40],
        'dependency_command': str(obj.get('dependency_command') or ''),
        'build_command': str(obj.get('build_command') or ''), 'test_command': str(obj.get('test_command') or ''),
        'entrypoint': entry, 'run_command': str(obj.get('run_command') or ''),
        'acceptance_criteria': criteria,
        'architecture_rules': _v33_normalize_contract_lines(obj.get('architecture_rules'), 80),
        'shared_contracts': _v33_normalize_contract_lines(obj.get('shared_contracts'), 120),
        'files': files,
    }
    return _v34_apply_toolchain_defaults(user_request, result)

def _optional_positive_limit(value):
    try:
        value = int(value)
    except Exception:
        return None
    return value if value > 0 else None


def _project_api_index(work):
    """Compact cross-file API map so large projects keep interface consistency without needing all code in one prompt."""
    root = Path(work)
    lines = []
    for path in sorted(root.rglob('*')):
        if not path.is_file():
            continue
        rel = path.relative_to(root)
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel.parts):
            continue
        if rel.name.startswith('JARVIS_') or rel.name in _RESERVED_OUTPUT_NAMES:
            continue
        if path.suffix.lower() not in {'.py', '.pyw'}:
            if _looks_text_file(path):
                try:
                    lines.append(f"FILE {rel.as_posix()} ({path.stat().st_size} bytes)")
                except Exception:
                    pass
            continue
        try:
            source = path.read_text(encoding='utf-8', errors='replace')
            if V33_SKELETON_MARKER in source[:400]:
                # Planned contract shells are represented by _v33_contract_index; do not let generic
                # placeholder signatures become stronger than the authoritative architecture plan.
                continue
            tree = ast.parse(source)
        except Exception:
            lines.append(f"PYTHON FILE {rel.as_posix()} (currently not parseable)")
            continue
        lines.append(f"PYTHON FILE {rel.as_posix()}")
        for node in tree.body:
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                try:
                    lines.append('  import: ' + ast.unparse(node))
                except Exception:
                    pass
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                args = [a.arg for a in node.args.args]
                lines.append(f"  function: {node.name}({', '.join(args)})")
            elif isinstance(node, ast.ClassDef):
                methods = []
                for child in node.body:
                    if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        args = [a.arg for a in child.args.args]
                        methods.append(f"{child.name}({', '.join(args)})")
                lines.append(f"  class: {node.name}" + (" -> " + ", ".join(methods) if methods else ""))
    return '\n'.join(lines)


def _v33_contract_index(manifest):
    """Compact authoritative architecture contract available before any implementation exists."""
    lines = ["V33 AUTHORITATIVE PROJECT CONTRACT"]
    for rule in (manifest or {}).get('architecture_rules') or []:
        lines.append(f"RULE: {rule}")
    for contract in (manifest or {}).get('shared_contracts') or []:
        lines.append(f"SHARED: {contract}")
    for item in (manifest or {}).get('files') or []:
        rel = str(item.get('path') or '')
        lines.append(f"FILE {rel} | phase={item.get('phase') or _v33_infer_phase(rel, item.get('purpose'))}")
        lines.append(f"  purpose: {item.get('purpose') or ''}")
        deps = list(item.get('depends_on') or [])
        lines.append("  depends_on: " + (", ".join(deps) if deps else "(none)"))
        exports = _normalize_export_contract(item.get('exports'))
        lines.append("  exports: " + (", ".join(exports) if exports else "(none)"))
        for contract in _v33_normalize_contract_lines(item.get('contracts')):
            lines.append(f"  contract: {contract}")
    text = "\n".join(lines)
    if len(text) > V33_CONTRACT_INDEX_CHARS:
        text = text[:V33_CONTRACT_INDEX_CHARS] + "\n...contract index bounded..."
    return text


def _v33_dependency_context(manifest, rel):
    rel = str(rel or '').replace('\\', '/')
    item = _manifest_file_item(manifest, rel)
    deps = list(item.get('depends_on') or [])
    dependents = []
    for other in (manifest or {}).get('files') or []:
        if rel in list(other.get('depends_on') or []):
            dependents.append(str(other.get('path') or ''))
    return (
        "TARGET DEPENDENCIES: " + (", ".join(deps) if deps else "(none)") + "\n" +
        "DIRECT DEPENDENTS: " + (", ".join(dependents) if dependents else "(none)")
    )


def _v33_dependency_ordered_files(manifest):
    """Stable topological order; phase order breaks incomplete/cyclic planner edges safely."""
    files = [dict(x) for x in (manifest or {}).get('files') or [] if x.get('path')]
    by_path = {str(x['path']): x for x in files}
    remaining = set(by_path)
    done = set()
    ordered = []
    entry = str((manifest or {}).get('entrypoint') or '')

    def rank(path):
        item = by_path[path]
        phase = str(item.get('phase') or _v33_infer_phase(path, item.get('purpose')))
        phase_rank = V33_PHASE_ORDER.get(phase, 3)
        if path == entry:
            phase_rank = max(phase_rank, V33_PHASE_ORDER['integration']) + 1
        return (phase_rank, 1 if path == entry else 0, path.lower())

    while remaining:
        ready = []
        for path in remaining:
            deps = [d for d in by_path[path].get('depends_on', []) if d in by_path]
            if all(d in done for d in deps):
                ready.append(path)
        if not ready:
            # Planner cycle/incomplete edge: pick the lowest architectural layer, never random order.
            ready = [min(remaining, key=rank)]
        for path in sorted(ready, key=rank):
            if path not in remaining:
                continue
            ordered.append(by_path[path])
            remaining.remove(path)
            done.add(path)
    return ordered


def _v33_stub_header_from_contract(contract):
    text = str(contract or '').strip().rstrip(':')
    if text.startswith(('def ', 'async def ', 'class ')):
        return text
    return ''


def _v33_python_contract_skeleton(item):
    """Create importable intermediate declarations so the repository shape/APIs exist immediately."""
    exports = _normalize_export_contract(item.get('exports'))
    contracts = _v33_normalize_contract_lines(item.get('contracts'))
    lines = [
        f"# {V33_SKELETON_MARKER}",
        '"""Intermediate V33 contract shell. Replaced during dependency-ordered implementation."""',
        '',
    ]
    emitted = set()
    for contract in contracts:
        header = _v33_stub_header_from_contract(contract)
        if not header:
            continue
        try:
            name_match = re.match(r'(?:async\s+def|def|class)\s+([A-Za-z_][A-Za-z0-9_]*)', header)
            name = name_match.group(1) if name_match else ''
            if not name or name in emitted:
                continue
            if header.startswith('class '):
                candidate = header + ':\n    __jarvis_contract_skeleton__ = True\n'
            else:
                candidate = header + ':\n    raise RuntimeError("V33 contract shell has not been implemented yet")\n'
            compile(candidate, '<v33-contract>', 'exec')
            lines.extend(candidate.rstrip().splitlines())
            lines.append('')
            emitted.add(name)
        except Exception:
            continue
    for name in exports:
        if name in emitted:
            continue
        if name[:1].isupper():
            lines.extend([f'class {name}:', '    __jarvis_contract_skeleton__ = True', ''])
        else:
            lines.extend([f'def {name}(*args, **kwargs):', '    raise RuntimeError("V33 contract shell has not been implemented yet")', ''])
    return '\n'.join(lines).rstrip() + '\n'


def _v33_is_contract_skeleton(path):
    try:
        path = Path(path)
        if not path.exists() or not path.is_file():
            return False
        return V33_SKELETON_MARKER in path.read_text(encoding='utf-8', errors='replace')[:500]
    except Exception:
        return False


def _v33_materialize_contract_skeletons(work, manifest, progress_callback=None):
    if not (V33_SYSTEMATIC_BUILD and V33_SKELETON_FIRST):
        return []
    root = Path(work)
    created = []
    for item in _v33_dependency_ordered_files(manifest):
        rel = str(item.get('path') or '')
        if not rel:
            continue
        target = root / rel
        if target.exists():
            continue
        suffix = target.suffix.lower()
        if suffix in {'.py', '.pyw'} and str(item.get('phase') or '') != 'test':
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(_v33_python_contract_skeleton(item), encoding='utf-8')
            created.append(rel)
        elif suffix in _SOURCE_SUFFIXES:
            target.parent.mkdir(parents=True, exist_ok=True)
            if suffix in {'.html','.htm','.vue','.svelte'}:
                shell = f"<!-- {V33_SKELETON_MARKER} -->\n"
            elif suffix in {'.css','.scss','.less'}:
                shell = f"/* {V33_SKELETON_MARKER} */\n"
            elif suffix in {'.rb','.py','.pyw','.sh','.bash','.ps1','.r','.pl'}:
                shell = f"# {V33_SKELETON_MARKER}\n"
            else:
                shell = f"// {V33_SKELETON_MARKER}\n"
            target.write_text(shell, encoding='utf-8')
            created.append(rel)
    if created:
        _progress(
            progress_callback,
            f'V33 contract-first skeleton materialized {len(created)} source files; implementation will now follow dependencies.',
            stage='architecting', percent=15,
        )
    return created


def _v33_write_architecture(work, manifest):
    try:
        payload = {
            'version': 'V34.1',
            'toolchain_adapter': manifest.get('toolchain_adapter'),
            'platform': manifest.get('platform'), 'language': manifest.get('language'), 'framework': manifest.get('framework'),
            'build_system': manifest.get('build_system'), 'package_manager': manifest.get('package_manager'),
            'project_name': manifest.get('project_name'),
            'entrypoint': manifest.get('entrypoint'),
            'architecture_rules': manifest.get('architecture_rules') or [],
            'shared_contracts': manifest.get('shared_contracts') or [],
            'implementation_order': [x.get('path') for x in _v33_dependency_ordered_files(manifest)],
            'files': manifest.get('files') or [],
        }
        Path(work, V33_ARCHITECTURE_FILE).write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        pass


def _v33_write_build_status(work, manifest, stage, current_file='', implemented=None):
    try:
        root = Path(work)
        real = _existing_real_source_files(root)
        skeletons = []
        committed_bytes = 0
        visible_bytes = 0
        for rel in real:
            path = root / rel
            size = path.stat().st_size
            visible_bytes += size
            text = path.read_text(encoding='utf-8', errors='replace')
            if V33_SKELETON_MARKER in text[:400]:
                skeletons.append(rel)
            else:
                committed_bytes += size
        payload = {
            'version': 'V34.1', 'stage': stage, 'current_file': current_file,
            'planned_files': len((manifest or {}).get('files') or []),
            'visible_source_files': len(real), 'skeleton_files_remaining': len(skeletons),
            'implemented_source_files': len(real) - len(skeletons) if implemented is None else int(implemented),
            'visible_source_bytes': visible_bytes, 'committed_source_bytes': committed_bytes,
            'updated_at': _utc_stamp(),
        }
        Path(work, V33_BUILD_STATUS_FILE).write_text(json.dumps(payload, indent=2), encoding='utf-8')
    except Exception:
        pass


def _v33_repair_strategy(problems, validation_failure=None):
    text = ('\n'.join(str(x) for x in (problems or [])) + '\n' + str(validation_failure or '')).lower()
    if 'cannot import name' in text or 'missing required export' in text or 'does not define/export' in text:
        return 'MISSING_EXPORT_PROVIDER', (
            'Repair the PROVIDER module. Add/restore the exact required module-level export with the contract expected by real consumers. '
            'Do not edit callers to hide the missing provider API. Preserve every existing required export.'
        )
    if 'circular import' in text or 'partially initialized module' in text:
        return 'CIRCULAR_IMPORT', (
            'Break the import cycle without deleting behavior: move shared types/constants downward, use TYPE_CHECKING for type-only imports, '
            'or use a narrow local import where appropriate. Preserve the public API of both sides.'
        )
    if 'signature' in text or 'positional argument' in text or 'unexpected keyword' in text or 'required positional' in text:
        return 'CALL_SIGNATURE_CONTRACT', (
            'Reconcile the exact declared/called signature. Do not add random compatibility aliases. Preserve correct callers and the architecture contract; '
            'change only the side proven wrong by the supplied evidence.'
        )
    if 'select *' in text or 'row/model' in text or 'column' in text and ('sqlite' in text or 'database' in text):
        return 'DATA_MODEL_CONTRACT', (
            'Reconcile database columns, query projection order, and model constructor fields explicitly. Prefer named columns/mapping over positional SELECT * expansion.'
        )
    if 'syntax' in text or 'syntaxerror' in text or 'indentationerror' in text:
        return 'SYNTAX_LOCAL', 'Fix the parse error with the smallest coherent change; preserve behavior and every public contract.'
    if 'assert' in text or 'test failed' in text or 'pytest' in text or 'unittest' in text:
        return 'FAILING_TEST', (
            'Treat the failing assertion/exception as executable evidence. Fix production behavior when it violates the user/architecture contract; '
            'only change a generated/non-authoritative test when deterministic API evidence proves the test invented the contract.'
        )
    if V33_SKELETON_MARKER.lower() in text or V34_RECOVERY_SEED_MARKER.lower() in text or 'recovery seed' in text or 'contract skeleton' in text or 'contract shell' in text:
        return 'IMPLEMENT_CONTRACT_SKELETON', 'Replace the intermediate shell with real behavior implementing every declared contract for this file.'
    if validation_failure:
        return 'RUNTIME_TRACEBACK_ROOT_CAUSE', (
            'Follow the exception and deepest relevant project frame to the root cause. Make the smallest change that makes replay advance to a different result; '
            'do not rewrite unrelated architecture.'
        )
    return 'LOCAL_ACCEPTANCE_REPAIR', 'Fix every listed defect in this file while preserving all unrelated behavior and public contracts.'


def _context_priority(current_path, rel):
    cur = Path(current_path)
    other = Path(rel)
    score = 0
    if other.parent == cur.parent:
        score += 100
    if cur.parts and other.parts and cur.parts[0] == other.parts[0]:
        score += 50
    if other.name in {'models.py', 'database.py', 'config.py', 'settings.py', '__init__.py'}:
        score += 25
    if other.suffix.lower() in {'.py', '.pyw', '.js', '.ts', '.tsx', '.jsx'}:
        score += 10
    return -score, rel


def _project_context_for_file(work, manifest, current_path, max_chars=None):
    """Return a focused set of COMPLETE related files; never slice source code mid-file."""
    if max_chars is None:
        max_chars = FILE_CONTEXT_CHARS
    try:
        max_chars = int(max_chars)
    except Exception:
        max_chars = 0

    root = Path(work)
    current_file = root / current_path
    current_text = ""
    if current_file.exists():
        try:
            current_text = current_file.read_text(encoding="utf-8", errors="replace")
        except Exception:
            current_text = ""

    current_mods = set()
    for match in re.finditer(r"^\s*(?:from|import)\s+([A-Za-z_][A-Za-z0-9_.]*)", current_text, flags=re.M):
        current_mods.add(match.group(1))

    available = []
    cur = Path(current_path)
    current_item = _manifest_file_item(manifest, current_path)
    explicit_deps = set(current_item.get('depends_on') or [])
    direct_dependents = {
        str(x.get('path') or '') for x in (manifest.get('files') or [])
        if current_path in list(x.get('depends_on') or [])
    }
    for item in manifest.get("files") or []:
        rel = str(item.get("path") or "")
        if not rel or rel == current_path:
            continue
        path = root / rel
        if not path.exists() or not path.is_file() or not _looks_text_file(path):
            continue
        score = 0
        other = Path(rel)
        if rel in explicit_deps:
            score += 320
        if rel in direct_dependents:
            score += 180
        if other.parent == cur.parent:
            score += 100
        if cur.parts and other.parts and cur.parts[0] == other.parts[0]:
            score += 30
        if other.name in {"models.py", "database.py", "config.py", "settings.py", "__init__.py"}:
            score += 25

        parts = list(other.with_suffix("").parts)
        if len(parts) > 1 and parts[0].lower() not in {"app", "src", "lib", "tests"}:
            parts = parts[1:]
        mod = ".".join(parts)
        if any(mod == x or mod.startswith(x + ".") or x.startswith(mod + ".") for x in current_mods):
            score += 150

        try:
            other_text = path.read_text(encoding='utf-8', errors='replace')
        except Exception:
            other_text = ""
        if V33_SKELETON_MARKER in other_text[:400]:
            # Contract shell is useful as a visible checkpoint, but the plan contract is the authority.
            continue

        cur_parts = list(cur.with_suffix("").parts)
        if len(cur_parts) > 1 and cur_parts[0].lower() not in {"app", "src", "lib", "tests"}:
            cur_parts = cur_parts[1:]
        cur_mod = ".".join(cur_parts)
        if cur_mod and re.search(rf"\b(?:from|import)\s+{re.escape(cur_mod)}\b", other_text):
            score += 180

        available.append((-score, rel))

    available.sort()
    selected = [rel for _, rel in available[:RELATED_CONTEXT_FILE_LIMIT]]

    chunks = []
    used = 0
    omitted = []
    for rel in selected:
        path = root / rel
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            continue
        piece = f"===== EXISTING FILE {rel} =====\n{text}\n===== END FILE {rel} =====\n"
        if max_chars > 0 and used + len(piece) > max_chars:
            omitted.append(rel)
            continue
        chunks.append(piece)
        used += len(piece)

    if omitted:
        chunks.append(
            "===== RELATED FILES OMITTED FROM FULL CONTEXT (interfaces remain in API index) =====\n"
            + "\n".join(omitted)
        )
    return "\n\n".join(chunks)


def _extract_single_file_response(text, expected_path):
    """Recover one file from raw model output without leaking markdown/prose wrappers into source."""
    raw = str(text or "").replace("\ufeff", "")
    if not raw.strip():
        return ""

    # V24 preferred raw-source transport. Only trust it when the exact expected path has a
    # complete end marker and no structural envelope errors.
    attempted_blocks = '<<<JARVIS_FILE' in raw or JARVIS_FILE_BLOCK_END in raw
    block_candidates, block_errors = _parse_jarvis_file_blocks(
        raw, expected_paths=[expected_path], strict_outside=True
    )
    if block_candidates and not block_errors:
        block_content = block_candidates[0][1]
        if block_content and not block_content.endswith("\n"):
            block_content += "\n"
        return block_content
    if attempted_blocks and block_errors:
        return ""

    if FILE_COMPLETE_MARKER in raw:
        raw = raw.split(FILE_COMPLETE_MARKER, 1)[0]

    # Recover strict-JSON file responses if the model ignored the raw-file protocol.
    try:
        obj = _extract_json(raw)
        if isinstance(obj, dict):
            files = obj.get("files") or []
            if isinstance(files, dict):
                files = [files]
            for item in files:
                if not isinstance(item, dict):
                    continue
                p = str(item.get("path") or item.get("name") or "").replace("\\", "/")
                content = item.get("content")
                if content is None:
                    content = item.get("code") or item.get("source") or item.get("text")
                if p == expected_path and content is not None:
                    raw = str(content)
                    break
    except Exception:
        pass

    # Prefer a complete fenced block when one exists.
    blocks = re.findall(r"```[A-Za-z0-9_+.-]*[ \t]*\r?\n(.*?)```", raw, flags=re.S)
    if blocks:
        raw = max(blocks, key=len)
    else:
        # Strip an opening fence even when the model was cut off before a closing fence.
        stripped = raw.lstrip()
        if re.match(r"^```[A-Za-z0-9_+.-]*[ \t]*(?:\r?\n|$)", stripped):
            stripped = re.sub(
                r"^```[A-Za-z0-9_+.-]*[ \t]*(?:\r?\n|$)",
                "",
                stripped,
                count=1,
            )
            raw = stripped
        raw = re.sub(r"(?:\r?\n)?```[ \t]*$", "", raw)

    # Strip a model-added FILE: header only when it identifies this exact file.
    raw_lines = raw.splitlines()
    if raw_lines and re.match(r"^\s*FILE\s*:\s*", raw_lines[0], flags=re.I):
        declared = re.sub(r"^\s*FILE\s*:\s*", "", raw_lines[0], flags=re.I).strip().strip("`\"' ")
        if declared.replace("\\", "/") == str(expected_path).replace("\\", "/"):
            raw = "\n".join(raw_lines[1:])

    raw = re.sub(r"^\s*<\|im_start\|>assistant\s*", "", raw)
    raw = re.sub(r"\s*<\|im_end\|>\s*$", "", raw)

    low = raw.lstrip().lower()
    if low.startswith(("here is ", "here's ", "i will ", "plan:", "sure,")):
        # Prose as the first line of a source file is almost always a protocol failure.
        return ""

    body = raw.strip("\r\n")
    return body + ("\n" if body else "")


def _extract_file_chunk(text, expected_path, preserve_leading=False):
    """Compatibility helper. V6 no longer blind-appends source continuations."""
    raw = str(text or "")
    done = FILE_COMPLETE_MARKER in raw
    return _extract_single_file_response(raw, expected_path), done


def _merge_file_chunks(existing, chunk):
    """Merge a continuation fragment without duplicating a repeated tail.

    Qwen is explicitly allowed to repeat a small amount of the previous tail so the join can be
    deterministic. Prefer exact character overlap, then exact whole-line overlap. If neither exists,
    append verbatim rather than guessing and deleting source.
    """
    existing = str(existing or '')
    chunk = str(chunk or '')
    if not existing:
        return chunk
    if not chunk:
        return existing

    # If the model restarted and returned a complete superset, keep the fuller replacement.
    probe = existing[:min(500, len(existing))]
    if probe and chunk.startswith(probe) and len(chunk) >= len(existing):
        return chunk

    # Exact character overlap handles partial final lines and repeated source tails safely.
    max_overlap = min(len(existing), len(chunk), 24000)
    min_overlap = 8
    for size in range(max_overlap, min_overlap - 1, -1):
        if existing[-size:] == chunk[:size]:
            return existing + chunk[size:]

    # Whole-line overlap is useful when whitespace/newline normalization prevented a longer char join.
    left = existing.splitlines(keepends=True)
    right = chunk.splitlines(keepends=True)
    max_lines = min(len(left), len(right), 80)
    for count in range(max_lines, 0, -1):
        if left[-count:] == right[:count]:
            return ''.join(left + right[count:])

    return existing + chunk


def _qwen_file_output_limit():
    """Return an explicit per-call file output budget.

    FILE_MAX_TOKENS=0 means auto, not "omit max_tokens". Omitting it lets an OpenAI-compatible
    provider/server default silently cap generations (commonly around a few thousand tokens), which
    is exactly the failure mode that makes large source files look randomly truncated.
    """
    configured = _optional_positive_limit(FILE_MAX_TOKENS)
    if configured is not None:
        return configured
    context = max(4096, int(_qwen_effective_context_tokens()))
    # V32 intentionally uses shorter emission chunks on Qwen3.5. Continuation is cheaper
    # than losing 16K+ tokens to one malformed envelope, and shorter calls give Jarvis
    # more frequent opportunities to validate/commit progress.
    family = _active_qwen_model_family() if "_active_qwen_model_family" in globals() else "qwen3"
    per_call_cap = QWEN35_FILE_OUTPUT_TOKENS if family == "qwen35" else 16384
    available = max(2048, context - QWEN3_CONTEXT_SAFETY_TOKENS - 4096)
    return max(2048, min(per_call_cap, available))


def _extract_partial_jarvis_file_block(text, expected_path):
    """Recover the body of an exact JARVIS_FILE block even when its final end marker was cut off.

    Returns (content, complete, error). A partial body is never committed directly; it is only fed
    into the continuation engine and later passes normal transaction/acceptance validation.
    """
    raw = str(text or '').replace('\ufeff', '')
    expected = _safe_relative(expected_path).as_posix()
    lines = raw.splitlines(keepends=True)
    current = False
    body = []
    outside = []
    saw_header = False

    for line_no, line in enumerate(lines, 1):
        header = _JARVIS_FILE_HEADER_RE.match(line.rstrip('\r\n'))
        is_end = bool(_JARVIS_FILE_END_RE.match(line.rstrip('\r\n')))
        if header:
            raw_path = next((g for g in header.groups() if g is not None), '')
            try:
                rel = _safe_relative(raw_path).as_posix()
            except Exception as exc:
                return '', False, f'Unsafe JARVIS_FILE path in partial response: {exc}'
            if saw_header:
                return ''.join(body), False, 'A second JARVIS_FILE header appeared before the expected file completed.'
            saw_header = True
            if rel != expected:
                return '', False, f'Partial JARVIS_FILE path mismatch: expected {expected}, got {rel}.'
            current = True
            continue
        if is_end:
            if not current:
                return ''.join(body), False, f'Unexpected {JARVIS_FILE_BLOCK_END} before the expected file body.'
            content = ''.join(body)
            if content and not content.endswith('\n'):
                content += '\n'
            return content, True, ''
        if current:
            body.append(line)
        elif line.strip():
            outside.append((line_no, line.strip()[:160]))

    if not saw_header:
        return '', False, 'No JARVIS_FILE header was found.'
    if outside and JARVIS_FILE_BLOCK_STRICT_OUTSIDE:
        sample = '; '.join(f'line {ln}: {txt}' for ln, txt in outside[:3])
        return ''.join(body), False, f'Non-whitespace text appeared outside the partial JARVIS_FILE envelope ({sample}).'
    return ''.join(body), False, 'JARVIS_FILE response ended before the final end marker.'


def _extract_continuation_fragment(text, expected_path):
    """Parse a continuation envelope, preserving a partial fragment when the continuation itself is cut off."""
    raw = str(text or '').replace('\ufeff', '')
    expected = _safe_relative(expected_path).as_posix()
    header_re = re.compile(
        r'^\s*<<<JARVIS_CONTINUATION\s+path\s*=\s*(?:"([^"]+)"|\'([^\']+)\'|([^\s>]+))\s*>>>\s*$'
    )
    end_re = re.compile(r'^\s*<<<JARVIS_END_CONTINUATION>>>\s*$')
    lines = raw.splitlines(keepends=True)
    saw_header = False
    current = False
    body = []
    outside = []

    for line_no, line in enumerate(lines, 1):
        header = header_re.match(line.rstrip('\r\n'))
        is_end = bool(end_re.match(line.rstrip('\r\n')))
        if header:
            if saw_header:
                return ''.join(body), False, 'Duplicate continuation header.'
            raw_path = next((g for g in header.groups() if g is not None), '')
            try:
                rel = _safe_relative(raw_path).as_posix()
            except Exception as exc:
                return '', False, f'Unsafe continuation path: {exc}'
            if rel != expected:
                return '', False, f'Continuation path mismatch: expected {expected}, got {rel}.'
            saw_header = True
            current = True
            continue
        if is_end:
            if not current:
                return ''.join(body), False, 'Continuation end marker appeared before its header.'
            return ''.join(body), True, ''
        if current:
            body.append(line)
        elif line.strip():
            outside.append((line_no, line.strip()[:160]))

    if not saw_header:
        return '', False, 'No continuation envelope was found.'
    if outside and JARVIS_FILE_BLOCK_STRICT_OUTSIDE:
        sample = '; '.join(f'line {ln}: {txt}' for ln, txt in outside[:3])
        return ''.join(body), False, f'Non-whitespace text appeared outside continuation envelope ({sample}).'
    return ''.join(body), False, 'Continuation response was truncated before its end marker.'


def _continue_truncated_file(expected_path, partial, progress_callback=None, stage='Continuing file', profile='generate'):
    """Continue a token-truncated source file across bounded model calls.

    The live workspace is never touched here. Each fragment is merged into an in-memory candidate,
    and callers still run the normal syntax/API/transaction gates before writing it.
    """
    candidate = str(partial or '')
    if not candidate:
        return False, candidate, 'No partial source was available to continue.'

    max_tokens = _qwen_file_output_limit()
    last_error = ''
    stalled = 0

    for continuation_no in range(1, FILE_CONTINUATION_ROUNDS + 1):
        tail = candidate[-FILE_CONTINUATION_TAIL_CHARS:]
        prompt = (
            "A source-file generation was cut off by the output token limit. Continue the SAME file; do not rewrite it from line 1.\n"
            "Return ONLY one continuation envelope and no Markdown/prose:\n"
            f"<<<JARVIS_CONTINUATION path=\"{expected_path}\">>>\n"
            "<source continuation only>\n"
            "<<<JARVIS_END_CONTINUATION>>>\n\n"
            "CONTINUATION RULES:\n"
            "- Start at or slightly before the cutoff. You MAY repeat the last 1-3 complete source lines so Jarvis can de-duplicate overlap.\n"
            "- Never summarize, omit, use TODO/pass/ellipsis, or restart the whole file.\n"
            "- Finish every still-open block/string/collection and then finish the remaining intended file implementation.\n"
            "- Emit the continuation end marker only when this response has reached a natural continuation boundary; if more source remains, continue as far as possible before the token limit.\n"
            "- Do not emit JARVIS_FILE markers inside the continuation.\n\n"
            f"FILE: {expected_path}\n"
            f"CURRENT PARTIAL FILE LENGTH: {len(candidate)} characters\n"
            f"LAST LOCAL VALIDATION ERROR: {last_error or '(generation envelope ended before completion)'}\n\n"
            "TAIL OF THE ALREADY-KEPT FILE (do not lose this state):\n"
            f"{tail}\n"
        )
        ok, raw = _qwen_call(
            prompt, progress_callback,
            f"{stage} {continuation_no}/{FILE_CONTINUATION_ROUNDS}",
            profile=profile, max_tokens=max_tokens, thinking=False, strict_output=True,
        )
        truncated = not ok and getattr(raw, 'metadata', {}).get('finish_reason') == 'length' and bool(getattr(raw, 'partial_text', ''))
        if truncated:
            raw = raw.partial_text  # Draft fragments stay in memory until completion and validation.
        elif not ok:
            last_error = str(raw or '')[-1200:]
            stalled += 1
            if stalled >= 3:
                break
            continue

        fragment, response_complete, parse_error = _extract_continuation_fragment(raw, expected_path)
        if not fragment and not response_complete:
            last_error = parse_error
            stalled += 1
            if stalled >= 3:
                break
            continue

        merged = _merge_file_chunks(candidate, fragment)
        if len(merged) <= len(candidate) and merged == candidate:
            stalled += 1
        else:
            candidate = merged
            stalled = 0

        local_error = _content_validation_error(expected_path, candidate)
        last_error = local_error or parse_error

        # A parse-clean prefix is not proof the model finished the file. Only a
        # complete continuation can become a candidate for the normal gates.
        if not local_error and response_complete and not truncated:
            if candidate and not candidate.endswith('\n'):
                candidate += '\n'
            return True, candidate, ''

        if stalled >= 3:
            break

    return False, candidate, last_error or 'Continuation budget exhausted before the file became locally complete.'

def _candidate_draft_path(work, rel):
    safe = _safe_relative(rel)
    return Path(work) / CANDIDATE_DIR_NAME / (safe.as_posix() + ".candidate")


def _save_candidate_draft(work, rel, content):
    if work is None or not str(content or "").strip():
        return
    try:
        path = _candidate_draft_path(work, rel)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(str(content), encoding="utf-8")
    except Exception:
        pass


def _load_candidate_draft(work, rel):
    if work is None:
        return ""
    try:
        path = _candidate_draft_path(work, rel)
        if path.exists():
            return path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        pass
    return ""


def _delete_candidate_draft(work, rel):
    if work is None:
        return
    try:
        _candidate_draft_path(work, rel).unlink(missing_ok=True)
    except Exception:
        pass


def _content_validation_error(expected_path, content):
    """Return a concrete local parse error, or empty string when the candidate is structurally usable."""
    text = _extract_single_file_response(content, expected_path)
    if not text.strip():
        return "" if _allows_empty_generated_file(expected_path) else "File is empty or model returned prose instead of source."

    suffix = Path(str(expected_path or "")).suffix.lower()
    if suffix in _SOURCE_SUFFIXES:
        lines = text.count("\n") + 1
        if len(text) > FILE_MAX_SOURCE_CHARS or lines > FILE_MAX_SOURCE_LINES:
            return (
                f"Generated source is runaway/oversized ({len(text)} chars, {lines} lines). "
                "Keep this module focused and move unrelated responsibilities into the other planned files."
            )
    if suffix in {".py", ".pyw"}:
        try:
            compile(text, str(expected_path), "exec")
            return ""
        except SyntaxError as exc:
            line = ""
            src_lines = text.splitlines()
            if exc.lineno and 1 <= exc.lineno <= len(src_lines):
                line = src_lines[exc.lineno - 1].strip()
            return f"Python syntax error at line {exc.lineno}: {exc.msg}. Offending text: {line[:240]}"
        except Exception as exc:
            return f"Python compile error: {exc}"

    if suffix == ".json":
        try:
            json.loads(text)
            return ""
        except Exception as exc:
            return f"JSON parse error: {exc}"

    return ""


def _candidate_progress_score(expected_path, content):
    """Prefer valid candidates; otherwise prefer candidates whose parser gets farther."""
    text = _extract_single_file_response(content, expected_path)
    if not text.strip():
        return -1
    suffix = Path(str(expected_path or "")).suffix.lower()
    if suffix in {".py", ".pyw"}:
        try:
            compile(text, str(expected_path), "exec")
            return 10**12 + len(text)
        except SyntaxError as exc:
            return int(exc.lineno or 0) * 10**6 + len(text)
        except Exception:
            return len(text)
    return len(text)


def _normalize_workspace_model_artifacts(work):
    """Remove harmless model-output wrappers before spending Qwen repair calls."""
    changed = []
    root = Path(work)
    for path in sorted(root.rglob("*")):
        if not path.is_file():
            continue
        rel = path.relative_to(root)
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel.parts):
            continue
        if path.suffix.lower() not in _SOURCE_SUFFIXES:
            continue
        try:
            old = path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            continue
        cleaned = _extract_single_file_response(old, rel.as_posix())
        if cleaned and cleaned != old:
            try:
                path.write_text(cleaned, encoding="utf-8")
                changed.append(rel.as_posix())
            except Exception:
                pass
    return changed


def _generation_content_is_structurally_usable(expected_path, content):
    cleaned = _extract_single_file_response(content, expected_path)
    return _content_validation_error(expected_path, cleaned) == ""


def _qwen_generate_complete_file(base_prompt, expected_path, progress_callback=None, stage="Generating file", profile="generate"):
    """Generate one complete source file, recovering token truncation before attempting full rewrites.

    V27 changes the failure policy: an unterminated JARVIS_FILE envelope is treated as a recoverable
    partial file. Jarvis continues it across bounded calls and validates the merged candidate. Full
    rewrites are reserved for genuinely malformed/non-converging candidates.
    """
    max_tokens = _qwen_file_output_limit()
    best = ""
    best_score = -1
    best_error = ""

    transport_rules = _jarvis_file_transport_instructions(expected_path, multi=False)
    initial_prompt = (
        base_prompt.rstrip() + "\n\n" + transport_rules +
        "\nReturn exactly ONE complete file envelope for the requested path. "
        "Do not emit the legacy JARVIS_FILE_COMPLETE marker when using this envelope.\n"
    )
    prompt = initial_prompt

    for attempt in range(1, FILE_FULL_REWRITE_ROUNDS + 1):
        call_stage = stage if attempt == 1 else f"{stage} recovery rewrite {attempt}/{FILE_FULL_REWRITE_ROUNDS}"
        ok, raw = _qwen_call(
            prompt, progress_callback, call_stage, profile=profile, max_tokens=max_tokens,
            thinking=False, strict_output=True
        )
        truncated = not ok and getattr(raw, 'metadata', {}).get('finish_reason') == 'length' and bool(getattr(raw, 'partial_text', ''))
        if truncated:
            raw = raw.partial_text
        elif not ok:
            best_error = str(raw or '')[-1500:]
            continue

        blocks, block_errors = _parse_jarvis_file_blocks(
            raw, expected_paths=[expected_path], strict_outside=JARVIS_FILE_BLOCK_STRICT_OUTSIDE
        )
        attempted_blocks = '<<<JARVIS_FILE' in str(raw or '') or JARVIS_FILE_BLOCK_END in str(raw or '')

        # Normal complete-envelope path.
        if blocks and not block_errors and not truncated:
            candidate = blocks[0][1]
            if candidate and not candidate.endswith("\n"):
                candidate += "\n"
            score = _candidate_progress_score(expected_path, candidate)
            if score > best_score:
                best, best_score = candidate, score
            error = _content_validation_error(expected_path, candidate)
            if not error:
                return True, candidate
            best_error = error

        # Critical V27 path: preserve and continue a token-truncated envelope instead of rewriting line 1.
        elif attempted_blocks:
            partial, envelope_complete, partial_error = _extract_partial_jarvis_file_block(raw, expected_path)
            if partial:
                score = _candidate_progress_score(expected_path, partial)
                if score > best_score:
                    best, best_score = partial, score

                # If the parser says the envelope was complete but strict validation rejected it, this is
                # malformed transport/structure rather than token truncation; proceed to rewrite feedback.
                if not envelope_complete or truncated:
                    continued_ok, continued, continuation_error = _continue_truncated_file(
                        expected_path, partial, progress_callback,
                        stage=f"Continuing truncated {expected_path}", profile=profile,
                    )
                    if continued:
                        score = _candidate_progress_score(expected_path, continued)
                        if score > best_score:
                            best, best_score = continued, score
                    if continued_ok:
                        return True, continued
                    best_error = continuation_error or partial_error
                else:
                    best_error = '; '.join(block_errors[:5]) or partial_error
            else:
                best_error = '; '.join(block_errors[:5]) or partial_error

        # Legacy/raw recovery for providers that ignore the envelope protocol entirely.
        else:
            if truncated:
                best_error = 'Token-truncated source has no validated file envelope; return a smaller complete file.'
                continue
            candidate = _extract_single_file_response(raw, expected_path)
            if candidate:
                score = _candidate_progress_score(expected_path, candidate)
                if score > best_score:
                    best, best_score = candidate, score
                error = _content_validation_error(expected_path, candidate)
                if not error:
                    return True, candidate
                best_error = error

        previous = best
        prompt = (
            "The previous generation/continuation could not be accepted. Rewrite the ENTIRE requested file once from line 1.\n"
            "This is a recovery rewrite, not the normal response to token truncation. Produce a smaller, focused implementation if possible.\n"
            "Do NOT emit a patch, TODO, placeholder, ellipsis, or omitted section.\n\n"
            f"FILE: {expected_path}\n"
            f"LAST LOCAL/TRANSPORT ERROR:\n{best_error or '(unknown generation failure)'}\n\n"
            + transport_rules +
            "\nPREVIOUS BEST CANDIDATE (repair its behavior/structure, but emit a fresh full envelope):\n"
            + str(previous or '')
        )

    return False, best

def _module_name_from_rel(rel):
    p = Path(str(rel or '').replace('\\', '/'))
    if p.suffix.lower() not in {'.py', '.pyw'}:
        return ''
    parts = list(p.with_suffix('').parts)
    if parts and parts[-1] == '__init__':
        parts = parts[:-1]
    return '.'.join(parts)


def _focused_consumer_context_for_file(work, rel, max_chars=9000):
    """Return exact current consumers of a planned Python module, capped by complete files.

    Small local models follow contracts better when the relevant callers are separated from the
    large generic project context. This is especially useful while the provider itself is missing.
    """
    module = _module_name_from_rel(rel)
    if not module:
        return ''
    root = Path(work)
    pieces = []
    used = 0
    import_re = re.compile(
        rf'(?m)^\s*(?:from\s+{re.escape(module)}\s+import\b|import\s+{re.escape(module)}(?:\s|$|\.))'
    )
    for path in sorted(root.rglob('*.py')):
        if not path.is_file():
            continue
        try:
            consumer_rel = path.relative_to(root).as_posix()
        except Exception:
            continue
        if consumer_rel == str(rel).replace('\\', '/'):
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in Path(consumer_rel).parts):
            continue
        try:
            source = path.read_text(encoding='utf-8', errors='replace')
        except Exception:
            continue
        if not import_re.search(source):
            continue
        piece = f"===== CONSUMER {consumer_rel} =====\n{source}\n===== END CONSUMER {consumer_rel} =====\n"
        if used + len(piece) > max_chars:
            continue
        pieces.append(piece)
        used += len(piece)
    return '\n'.join(pieces)


def _generate_planned_file(user_request, manifest, work, file_item, progress_callback=None):
    rel = str(file_item.get("path") or "")
    purpose = str(file_item.get("purpose") or "Required project file")
    is_entrypoint = str((manifest or {}).get("entrypoint") or "").replace("\\", "/").strip("/") == rel.replace("\\", "/").strip("/")

    if _allows_empty_generated_file(rel):
        try:
            safe = _safe_relative(rel)
        except Exception:
            return False, ""
        target = Path(work) / safe
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text("", encoding="utf-8")
        _delete_candidate_draft(work, rel)
        return True, safe.as_posix()

    context = _project_context_for_file(work, manifest, rel)
    api_index = _project_api_index(work)
    focused_consumers = _focused_consumer_context_for_file(work, rel)
    is_generated_acceptance = (
        _is_jarvis_generated_acceptance_test(rel)
        if '_is_jarvis_generated_acceptance_test' in globals()
        else str(rel).replace('\\', '/').strip('/') == 'tests/test_generated_acceptance.py'
    )
    # A rejected generated test is uniquely dangerous as repair input: small local models anchor on
    # its invented APIs and repeat them. Regenerate these tests from the real API graph every time.
    if is_generated_acceptance:
        _delete_candidate_draft(work, rel)
        draft = ''
    else:
        draft = _load_candidate_draft(work, rel)
    attempts = max(
        1,
        int(os.getenv("JARVIS_QWEN_FILE_GENERATION_ATTEMPTS", str(FILE_GENERATION_ATTEMPTS))),
    )
    if is_generated_acceptance:
        attempts = max(attempts, int(os.getenv('JARVIS_QWEN_GENERATED_TEST_ATTEMPTS', '3')))

    best_content = draft
    best_score = _candidate_progress_score(rel, draft) if draft else -1
    last_generation_error = ""
    file_started = time.monotonic()

    for attempt in range(1, attempts + 1):
        if time.monotonic() - file_started > FILE_GENERATION_WALL_SECONDS:
            last_generation_error = (
                f"Per-file generation budget exceeded {FILE_GENERATION_WALL_SECONDS}s; "
                "materializing/staging the best candidate so the rest of the project can progress."
            )
            _append_project_event(work, 'file_generation_timebox', last_generation_error, file=rel)
            break
        # Final outer attempt drops full related-file context and relies on the compact API index,
        # which is useful if the server rejected an oversized prompt.
        # With V32/V33's normal single outer attempt, DO include implemented dependencies.
        # Only drop full related-file context on the final retry when there was an earlier attempt.
        use_context = context if (attempts == 1 or attempt < attempts) else ""
        required_exports = _required_exports_for_file(work, manifest, rel) if "_required_exports_for_file" in globals() else []
        contract_text = ", ".join(required_exports) if required_exports else "(none known yet)"
        target_contracts = _v33_normalize_contract_lines(file_item.get('contracts'))
        dependency_context = _v33_dependency_context(manifest, rel)
        architecture_contract = _v33_contract_index(manifest)
        prompt = (
            "V33 DEPENDENCY-ORDERED IMPLEMENTATION. Implement exactly ONE planned file.\n"
            "The repository architecture and sibling APIs were designed BEFORE this call. Treat those contracts as authoritative.\n"
            "Return the entire finished file from line 1. No markdown/prose. No TODO/pass/placeholder/omitted behavior.\n"
            f"Keep this module focused and preferably <= {V33_TARGET_FILE_LINES} lines; never bloat it to duplicate sibling responsibilities.\n"
            "Do NOT invent a sibling API. If you need another module, call only interfaces declared in the architecture contract.\n"
            "Do NOT silently rename fields, constructors, methods, return shapes, database columns, or exceptions shared across files.\n\n"
            f"USER REQUEST:\n{user_request}\n\n"
            f"AUTHORITATIVE ARCHITECTURE CONTRACT:\n{architecture_contract}\n\n"
            f"TARGET FILE CONTRACT:\n{json.dumps(file_item, ensure_ascii=False, indent=2)}\n"
            f"{dependency_context}\n"
            f"REQUIRED PUBLIC EXPORTS: {contract_text}\n"
            f"EXACT DECLARED CONTRACTS: {json.dumps(target_contracts, ensure_ascii=False)}\n\n"
            f"IMPLEMENTED PROJECT API INDEX (skeletons excluded):\n{api_index or '(no implemented APIs yet)'}\n\n"
            f"FOCUSED REAL CONSUMERS OF THIS MODULE:\n{focused_consumers or '(none implemented yet)'}\n\n"
            f"IMPLEMENTED DEPENDENCY/RELATED FILES:\n{use_context or '(use architecture contract; dependencies not implemented yet)'}\n"
        )
        if is_entrypoint:
            prompt += (
                "\nENTRYPOINT ARCHITECTURE RULE:\n"
                "- Keep the entrypoint THIN. Do not duplicate UI/service/model classes that belong to other planned modules.\n"
                "- Import the project's real main application/window/provider and launch it.\n"
                "- Define the manifest-required entry function if one is declared.\n"
                "- Do not create a second copy of MainWindow or other application architecture inside the entrypoint.\n"
            )
        if is_generated_acceptance:
            contract_snapshot = (
                _generated_test_contract_snapshot(work, manifest)
                if '_generated_test_contract_snapshot' in globals() else {}
            )
            prompt += (
                "\nGENERATED ACCEPTANCE TEST RULES:\n"
                "- This test is NON-AUTHORITATIVE: never invent production methods, aliases, constructor parameters, "
                "dependency injection hooks, or storage options that are not already present.\n"
                "- Import EVERY stdlib/project symbol the test uses (including modules such as csv).\n"
                "- Match constructor and method signatures exactly as shown in PROJECT API INDEX.\n"
                "- If production hardcodes a relative database/file path and does not accept a path argument, isolate "
                "the test with a TemporaryDirectory/current-working-directory sandbox rather than passing invented "
                "constructor arguments.\n"
                "- Do not create a parallel Database/repository and then assert it changed after mutating a different "
                "service/importer instance. Verify state through the same production object graph that performed the mutation.\n"
                "- Every test must start from clean storage. If a setUp fixture pre-inserts a record, do NOT import/add the "
                "same unique identifier again unless that exact test is intentionally testing duplicate rejection.\n"
                "- For relative SQLite/file storage, create a fresh TemporaryDirectory in setUp, save the original cwd, "
                "os.chdir(tempdir) BEFORE constructing production objects, then restore cwd and cleanup in tearDown.\n"
                "- Jarvis already runs each generated test case in its OWN fresh temporary current-working-directory. "
                "Therefore NEVER invent ':memory:' or path constructor parameters solely for isolation.\n"
                "- Do not launch GUI event loops. Prefer core service/persistence/import-export behavior.\n"
                "\nAUTHORITATIVE LOCAL PYTHON CONTRACT SNAPSHOT (JSON):\n"
                + json.dumps(contract_snapshot, ensure_ascii=False, indent=2)
                + "\nUse this snapshot literally. Instance attribute names are exact; e.g. if it says 'db', do not guess 'database'.\n"
            )
        if last_generation_error:
            prompt += (
                "\nPREVIOUS CANDIDATE WAS REJECTED BY JARVIS:\n"
                f"{last_generation_error}\n"
                "Correct that exact validation failure. Do not repeat the rejected API/structure.\n"
            )
        if draft:
            prompt += (
                "\nA previous candidate for this exact file failed local validation. "
                "Use it only as repair input; return a clean FULL replacement, not a continuation:\n"
                f"{draft}\n"
            )

        ok, content = _qwen_generate_complete_file(
            prompt,
            rel,
            progress_callback,
            f"Generating {rel} ({attempt}/{attempts})",
            profile="generate",
        )

        if content:
            score = _candidate_progress_score(rel, content)
            if score > best_score:
                best_content = content
                best_score = score

        if not ok:
            continue

        try:
            safe = _safe_relative(rel)
        except Exception:
            return False, ""
        if safe.name in _RESERVED_OUTPUT_NAMES or safe.name.startswith("JARVIS_"):
            return False, ""

        cleaned = _extract_single_file_response(content, rel)
        line_count = len(cleaned.splitlines())
        generation_error = (
            _candidate_transaction_error(work, manifest, rel, cleaned)
            if '_candidate_transaction_error' in globals()
            else _content_validation_error(rel, cleaned)
        )
        if not generation_error and line_count > V33_MAX_FILE_LINES and Path(rel).suffix.lower() in _SOURCE_SUFFIXES:
            _append_project_event(
                work, 'v33_large_module_warning',
                f'Generated {rel} is {line_count} lines; accepted because contracts/transaction checks passed, but future planning should split this responsibility.',
                file=rel, lines=line_count, preferred=V33_TARGET_FILE_LINES, soft_max=V33_MAX_FILE_LINES,
            )
        if generation_error:
            last_generation_error = str(generation_error)
            _save_candidate_draft(work, rel, cleaned)
            _append_project_event(
                work,
                'generation_candidate_rejected',
                f'Rejected invalid/incompatible initial generation for {rel}.',
                file=rel,
                reason=generation_error,
            )
            continue

        target = Path(work) / safe
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(cleaned, encoding="utf-8")
        _delete_candidate_draft(work, rel)
        return True, safe.as_posix()

    # If this planned file is still missing, do NOT let strict whole-project validation create a
    # bootstrap deadlock. A syntactically complete, identity-correct candidate may be materialized
    # as REPAIRABLE INTERMEDIATE SOURCE even when sibling planned modules are missing or cross-file
    # contracts are not reconciled yet. The final acceptance gate remains fully strict.
    if best_content.strip():
        target = Path(work) / _safe_relative(rel)
        if (
            not target.exists() or not target.is_file() or target.stat().st_size == 0
            or _v33_is_contract_skeleton(target)
        ):
            materialized, bootstrap_error = _materialize_repairable_bootstrap_candidate(
                work, manifest, rel, best_content
            )
            if materialized:
                _append_project_event(
                    work,
                    "bootstrap_candidate_materialized",
                    f"Materialized repairable missing source {rel} to break a bootstrap dependency deadlock.",
                    file=rel,
                    note=(
                        "This is intermediate source only. Normal deterministic/runtime/test/build acceptance "
                        "must still pass before packaging."
                    ),
                    previous_transaction_error=last_generation_error,
                )
                return True, rel
            last_generation_error = bootstrap_error or last_generation_error

        # If even the bootstrap gate cannot accept it, keep the best work outside the live tree.
        _save_candidate_draft(work, rel, best_content)
        _append_project_event(
            work,
            "candidate_staged",
            f"Staged an incomplete candidate for {rel}; it was not committed to the live project.",
            file=rel,
            validation_error=last_generation_error or _content_validation_error(rel, best_content),
        )
    return False, ""


def _extract_explicit_requested_paths(user_request):
    """Pick up literal file paths named by the user so the planner cannot silently omit them."""
    text = str(user_request or '')
    exts = r'(?:py|pyw|js|mjs|cjs|jsx|ts|tsx|html|htm|css|scss|json|ya?ml|toml|ini|cfg|md|txt|csv|sql|sh|ps1|bat|cmd|c|cc|cpp|cxx|h|hpp|cs|java|kt|go|rs|rb|php|swift|dart|xml|gradle|properties)'
    pattern = re.compile(r'(?<![A-Za-z0-9_.-])((?:[A-Za-z0-9_.-]+[\\/])*[A-Za-z0-9_.-]+\.' + exts + r')\b', re.I)
    out = []
    for match in pattern.finditer(text):
        raw = match.group(1).replace('\\', '/')
        try:
            rel = _safe_relative(raw)
        except Exception:
            continue
        if rel.name in _RESERVED_OUTPUT_NAMES or rel.name.startswith('JARVIS_'):
            continue
        value = rel.as_posix()
        if value not in out:
            out.append(value)
    for special in re.findall(r'(?m)^\s*(?:[│├└─\-\s]*)?(\.gitignore)\s*$', text):
        if special not in out:
            out.append(special)
    return out



def _equivalent_manifest_path(candidate, existing_paths):
    """Resolve tree-display/bare-path duplicates without collapsing genuinely different modules."""
    candidate = str(candidate or '').replace('\\', '/').strip('/')
    if not candidate:
        return ''
    existing = [str(x or '').replace('\\', '/').strip('/') for x in existing_paths if str(x or '').strip()]
    if candidate in existing:
        return candidate

    # A prompt tree commonly contains a project root plus visually-indented bare names.
    # Regex extraction loses the tree indentation and turns "database.py" into a fake root file
    # even when MyApp/app/database.py already represents it. Collapse only when unambiguous.
    matches = []
    if '/' not in candidate:
        matches = [p for p in existing if Path(p).name.lower() == candidate.lower()]
    else:
        suffix = '/' + candidate.lower()
        matches = [p for p in existing if p.lower().endswith(suffix)]
    if len(matches) == 1:
        return matches[0]
    return ''


def _dedupe_manifest_tree_aliases(files):
    """Remove bare/tree-display aliases once the canonical nested path is known.

    Example: a pretty tree in the prompt can yield both ``product_dialog.py`` and
    ``MyApp/app/ui/product_dialog.py``. If there is exactly one nested file with the same
    basename, the bare path is only a display artifact and should not become a second project file.
    """
    items = [dict(x) for x in (files or []) if isinstance(x, dict) and str(x.get('path') or '').strip()]
    nested_by_name = {}
    for item in items:
        path = str(item.get('path') or '').replace('\\', '/').strip('/')
        if '/' in path:
            nested_by_name.setdefault(Path(path).name.lower(), []).append(path)

    out = []
    seen = set()
    for item in items:
        path = str(item.get('path') or '').replace('\\', '/').strip('/')
        key = path.lower()
        if not path or key in seen:
            continue
        if '/' not in path:
            matches = nested_by_name.get(Path(path).name.lower(), [])
            if len(matches) == 1:
                # Canonical nested path already represents this tree entry.
                continue
            if Path(path).name.lower() == '__init__.py' and matches:
                # Root __init__.py extracted from a pretty tree is almost always indentation loss.
                continue
        seen.add(key)
        item['path'] = path
        out.append(item)
    return out


def _merge_manifest(base, reviewed, user_request, max_files):
    result = dict(base or {})
    if reviewed:
        for key in ('project_name','summary','project_type','platform','language','framework','build_system','package_manager','dependency_command','build_command','test_command','entrypoint','run_command','toolchain_adapter'):
            if reviewed.get(key):
                result[key] = reviewed[key]

    req_tools=[]
    for source in ((base or {}).get('required_tools') or [], (reviewed or {}).get('required_tools') or []):
        vals=[source] if isinstance(source,str) else list(source or [])
        for v in vals:
            v=str(v).strip()
            if v and v not in req_tools: req_tools.append(v)
    result['required_tools']=req_tools[:40]

    merged = []
    by_path = {}

    def merge_contract(target, item):
        incoming_purpose = str(item.get('purpose') or '').strip()
        current_purpose = str(target.get('purpose') or '').strip()
        generic = {'', 'Required project file', 'Source file', 'File explicitly requested by the user'}
        if incoming_purpose and (current_purpose in generic or incoming_purpose not in generic):
            target['purpose'] = incoming_purpose
        phase = str(item.get('phase') or '').strip().lower()
        if phase in V33_PHASE_ORDER:
            target['phase'] = phase
        incoming_exports = _normalize_export_contract(item.get('exports'))
        if incoming_exports:
            target['exports'] = incoming_exports
        else:
            target['exports'] = _normalize_export_contract(target.get('exports'))
        incoming_contracts = _v33_normalize_contract_lines(item.get('contracts'))
        if incoming_contracts:
            target['contracts'] = incoming_contracts
        else:
            target['contracts'] = _v33_normalize_contract_lines(target.get('contracts'))
        # A review is a complete corrected manifest, so its dependency list must be able to REMOVE
        # a stale/cyclic planner edge instead of unioning the bad edge forever.
        target['depends_on'] = _v33_normalize_dep_paths(item.get('depends_on'), target.get('path'))

    for item in _sanitize_manifest_files((base or {}).get('files') or [], max_files):
        path = str(item['path']).replace('\\', '/')
        entry = dict(item)
        by_path[path] = entry
        merged.append(entry)

    for item in _sanitize_manifest_files((reviewed or {}).get('files') or [], max_files):
        path = str(item['path']).replace('\\', '/')
        equivalent = _equivalent_manifest_path(path, by_path.keys())
        if equivalent:
            merge_contract(by_path[equivalent], item)
            continue
        if len(merged) >= max_files:
            break
        entry = dict(item)
        by_path[path] = entry
        merged.append(entry)

    for raw_path in _extract_explicit_requested_paths(user_request):
        try:
            rel_obj = _safe_relative(raw_path)
        except Exception:
            continue
        if not _valid_planned_project_path(rel_obj):
            continue
        path = rel_obj.as_posix()
        equivalent = _equivalent_manifest_path(path, by_path.keys())
        if equivalent or len(merged) >= max_files:
            continue
        entry = {
            'path': path, 'purpose': 'File explicitly requested by the user',
            'phase': _v33_infer_phase(path, ''), 'depends_on': [], 'exports': [], 'contracts': []
        }
        by_path[path] = entry
        merged.append(entry)

    merged = _dedupe_manifest_tree_aliases(merged)
    valid_paths = {x['path'] for x in merged}
    for item in merged:
        item.setdefault('phase', _v33_infer_phase(item['path'], item.get('purpose')))
        item.setdefault('contracts', [])
        item['depends_on'] = [d for d in item.get('depends_on', []) if d in valid_paths and d != item['path']]
    result['files'] = merged[:max_files]

    criteria = []
    for source in ((base or {}).get('acceptance_criteria') or [], (reviewed or {}).get('acceptance_criteria') or []):
        vals = [source] if isinstance(source, str) else list(source or [])
        for value in vals:
            value = str(value).strip()
            if value and value not in criteria:
                criteria.append(value)
    result['acceptance_criteria'] = criteria[:40] or [f'The finished project satisfies the complete user request: {user_request}']

    for key, limit in (('architecture_rules', 60), ('shared_contracts', 80)):
        values = []
        for source in ((base or {}).get(key) or [], (reviewed or {}).get(key) or []):
            vals = [source] if isinstance(source, str) else list(source or [])
            for value in _v33_normalize_contract_lines(vals, limit):
                if value not in values:
                    values.append(value)
        result[key] = values[:limit]

    paths = {x['path'] for x in result['files']}
    entry = str(result.get('entrypoint') or '').replace('\\', '/').strip('/')
    equivalent_entry = _equivalent_manifest_path(entry, paths) if entry else ''
    if equivalent_entry:
        result['entrypoint'] = equivalent_entry
    elif entry not in paths:
        result['entrypoint'] = _pick_entrypoint(result, list(paths))
    return result


def _review_project_plan(user_request, manifest, max_files, progress_callback=None):
    current = _merge_manifest(dict(manifest or {}), {}, user_request, max_files)
    for review_no in range(1, PROJECT_PLAN_REVIEW_PASSES + 1):
        prompt = (
            "Review this V35.1 universal architecture/toolchain manifest BEFORE code generation. Return ONLY a corrected COMPLETE manifest JSON.\n"
            "This is an INTERFACE/DEPENDENCY review, not a source-code task.\n"
            "Hard checks:\n"
            "1. Every cross-file call/import the design will need is represented by an export + explicit contract on the provider.\n"
            "2. depends_on uses exact project paths and dependency direction is acyclic whenever possible.\n"
            "3. Models/shared types/config are below persistence/services; services are below UI; entrypoint is thin and last.\n"
            f"4. Split any file likely to exceed about {V33_MAX_FILE_LINES} lines. Prefer focused ~{V33_TARGET_FILE_LINES}-line modules.\n"
            "5. Constructor/method/function signatures must use consistent field names and return types across the whole plan.\n"
            "6. Do not invent tests that require APIs production does not need.\n"
            "7. Verify platform/language/framework/build_system/package_manager and dependency/build/test/run commands match the actual requested ecosystem.\n8. Do not remove files/features required by the user. Do not include Jarvis-owned files.\n\n"
            f"USER REQUEST:\n{user_request}\n\n{_stack_lock_instructions(user_request)}\n"
            f"CURRENT MANIFEST:\n{json.dumps(current, ensure_ascii=False, indent=2)}\n"
        )
        ok, text = _qwen_call(
            prompt, progress_callback, f'V33 architecture review {review_no}/{PROJECT_PLAN_REVIEW_PASSES}',
            profile='plan', max_tokens=6144, thinking=False,
            response_schema=QWEN_SCHEMA_PROJECT_PLAN, schema_name='project_plan_review', strict_output=True
        )
        if not ok:
            continue
        reviewed = _parse_project_plan(text, user_request, max_files)
        if reviewed:
            current = _merge_manifest(current, reviewed, user_request, max_files)
    return current



def _missing_manifest_files(work, manifest):
    missing = []
    for item in manifest.get('files') or []:
        rel = str(item.get('path') or '')
        if not rel:
            continue
        path = Path(work) / rel
        if not path.exists() or not path.is_file():
            missing.append(rel)
            continue
        if path.stat().st_size == 0 and not _allows_empty_generated_file(rel):
            missing.append(rel)
    return missing


def _source_incomplete_issues(work):
    issues = []
    root = Path(work)
    marker_re = re.compile(r'\b(?:TODO|FIXME|placeholder|implement\s+later|implementation\s+goes\s+here|omitted\s+for\s+brevity|not\s+implemented)\b', re.I)
    for path in sorted(root.rglob('*')):
        if not path.is_file():
            continue
        rel = path.relative_to(root)
        if not _is_real_source_rel(rel):
            continue
        try:
            text = path.read_text(encoding='utf-8', errors='replace')
        except Exception:
            continue
        if V33_SKELETON_MARKER in text[:500]:
            issues.append({'file': rel.as_posix(), 'problem': 'V33 intermediate contract skeleton remains and must be fully implemented.'})
        if V34_RECOVERY_SEED_MARKER in text[:800]:
            issues.append({'file': rel.as_posix(), 'problem': 'V34 recovery seed remains and must be replaced by the complete requested implementation.'})
        for line_no, line in enumerate(text.splitlines(), 1):
            if marker_re.search(line):
                issues.append({'file': rel.as_posix(), 'problem': f'Unfinished implementation marker at line {line_no}: {line.strip()[:180]}'})
        if path.suffix.lower() in {'.py', '.pyw'}:
            try:
                tree = ast.parse(text)
            except Exception:
                continue
            for node in ast.walk(tree):
                if isinstance(node, ast.ClassDef):
                    body = list(node.body)
                    if len(body) == 1 and isinstance(body[0], ast.Pass):
                        issues.append({'file': rel.as_posix(), 'problem': f'Class {node.name} at line {node.lineno} is a pass-only stub.'})
                    elif len(body) == 1 and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) and body[0].value.value is Ellipsis:
                        issues.append({'file': rel.as_posix(), 'problem': f'Class {node.name} at line {node.lineno} is an ellipsis-only stub.'})
                    continue
                if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    continue
                decorators = {getattr(d, 'id', '') for d in node.decorator_list if isinstance(d, ast.Name)}
                if 'abstractmethod' in decorators:
                    continue
                body = list(node.body)
                # Empty unittest lifecycle hooks are legitimate no-ops and should not consume
                # repair rounds or block an otherwise valid test suite.
                if node.name in {'setUp', 'tearDown', 'setUpClass', 'tearDownClass'}:
                    continue
                if len(body) == 1 and isinstance(body[0], ast.Pass):
                    issues.append({'file': rel.as_posix(), 'problem': f'Function {node.name} at line {node.lineno} is a pass-only stub.'})
                elif len(body) == 1 and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) and body[0].value.value is Ellipsis:
                    issues.append({'file': rel.as_posix(), 'problem': f'Function {node.name} at line {node.lineno} is an ellipsis-only stub.'})
                elif len(body) == 1 and isinstance(body[0], ast.Raise):
                    exc = body[0].exc
                    name = ''
                    if isinstance(exc, ast.Call):
                        name = getattr(exc.func, 'id', '') or getattr(exc.func, 'attr', '')
                    elif isinstance(exc, ast.Name):
                        name = exc.id
                    if name == 'NotImplementedError':
                        issues.append({'file': rel.as_posix(), 'problem': f'Function {node.name} at line {node.lineno} raises NotImplementedError.'})
    # Deduplicate.
    seen = set(); out = []
    for issue in issues:
        key = (issue['file'], issue['problem'])
        if key not in seen:
            seen.add(key); out.append(issue)
    return out


def _audit_one_file(user_request, manifest, work, rel, progress_callback=None):
    """Evidence-scoped semantic review of ONE file.

    Local 8B models tend to drift into project-wide review when shown the whole manifest. This audit
    intentionally withholds unrelated source and requires a concrete symbol/line/evidence anchor.
    Cross-file import/API consistency is handled deterministically elsewhere.
    """
    path = Path(work) / rel
    if not path.exists() or not path.is_file() or not _looks_text_file(path):
        return []
    try:
        content = path.read_text(encoding='utf-8', errors='replace')
    except Exception:
        return []

    item = next(
        (x for x in manifest.get('files') or [] if str(x.get('path') or '') == rel),
        {},
    )
    purpose = str(item.get('purpose') or '')
    required_exports = _required_exports_for_file(work, manifest, rel) if '_required_exports_for_file' in globals() else []

    local_symbols = []
    if path.suffix.lower() in {'.py', '.pyw'}:
        try:
            tree = ast.parse(content)
            for node in ast.walk(tree):
                if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
                    if node.name not in local_symbols:
                        local_symbols.append(node.name)
        except Exception:
            pass

    prompt = (
        "Review ONLY the single file below. Do NOT audit the rest of the project.\n"
        "Return ONLY strict JSON with this shape:\n"
        '{"complete":true|false,"issues":[{"problem":"specific defect inside this file",'
        '"symbol":"class/function/method involved","line":123,"evidence":"short exact/local evidence"}]}.\n'
        "Rules:\n"
        "- Every issue MUST be physically inside FILE TO REVIEW.\n"
        "- Do NOT report that some other file is missing, incomplete, or incorrectly implemented.\n"
        "- Do NOT report project-wide architecture concerns here.\n"
        "- Do NOT demand optional enhancements the user did not request.\n"
        "- A valid issue must identify a concrete local symbol and/or line/evidence from this file.\n"
        "- Mark incomplete for truncated logic, a genuinely missing required method/behavior for THIS file's purpose, "
        "fake/placeholder behavior, or an obvious local runtime/logic defect.\n"
        "- Cross-file imports/exports are checked by deterministic tools, so do not speculate about them.\n\n"
        f"USER REQUEST:\n{user_request}\n\n"
        f"FILE TO REVIEW: {rel}\n"
        f"FILE PURPOSE: {purpose}\n"
        f"REQUIRED PUBLIC EXPORTS: {', '.join(required_exports) if required_exports else '(none declared)'}\n"
        f"LOCAL SYMBOLS FOUND: {', '.join(local_symbols) if local_symbols else '(none)'}\n\n"
        f"FULL FILE CONTENT:\n{content}\n"
    )
    ok, text = _qwen_call(
        prompt, progress_callback, f'Auditing {rel}', profile='audit', max_tokens=QWEN_AUDIT_MAX_TOKENS,
        thinking=False, response_schema=QWEN_SCHEMA_AUDIT, schema_name='file_audit', strict_output=True
    )
    if not ok:
        # Audit transport/model formatting failure is not proof that source is broken. Real tools remain authoritative.
        _append_project_event(work, 'audit_call_failed', f'Semantic audit call failed for {rel}.', file=rel, reason=str(text)[:1000])
        return []

    try:
        obj = _extract_json(text)
    except Exception:
        _append_project_event(work, 'audit_parse_failed', f'Semantic audit JSON was invalid for {rel}.', file=rel)
        return []

    if not isinstance(obj, dict) or bool(obj.get('complete', False)):
        return []

    vals = obj.get('issues') or []
    if isinstance(vals, (str, dict)):
        vals = [vals]

    issues = []
    for value in vals:
        if isinstance(value, dict):
            problem = str(value.get('problem') or value.get('issue') or '').strip()
            symbol = str(value.get('symbol') or '').strip()
            evidence = str(value.get('evidence') or '').strip()
            line = value.get('line')
            try:
                line = int(line) if line not in (None, '') else None
            except Exception:
                line = None
        else:
            problem = str(value or '').strip()
            symbol = ''
            evidence = ''
            line = None
        if not problem:
            continue

        grounded = bool(symbol or evidence or line)
        if symbol and local_symbols:
            # A symbol that is not in this file is usually the local model drifting to another module.
            base_symbol = symbol.split('.', 1)[0]
            if base_symbol not in local_symbols and not any(base_symbol in s or s in base_symbol for s in local_symbols):
                grounded = False
        if line is not None:
            grounded = grounded and 1 <= line <= max(1, len(content.splitlines()) + 2)

        issues.append({
            'file': rel,
            'problem': problem,
            'symbol': symbol,
            'line': line,
            'evidence': evidence,
            'grounded': grounded,
        })
    return issues



def _python_top_level_exports_from_text(source):
    """Return the public names a Python module defines at top level."""
    try:
        tree = ast.parse(str(source or ''))
    except Exception:
        return set()
    names = set()
    explicit_all = None
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            names.add(node.name)
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    names.add(target.id)
                    if target.id == '__all__' and isinstance(node.value, (ast.List, ast.Tuple, ast.Set)):
                        vals = []
                        valid = True
                        for elt in node.value.elts:
                            if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                                vals.append(elt.value)
                            else:
                                valid = False
                                break
                        if valid:
                            explicit_all = set(vals)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            names.add(node.target.id)
        elif isinstance(node, ast.Import):
            for alias in node.names:
                names.add(alias.asname or alias.name.split('.')[0])
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names:
                if alias.name != '*':
                    names.add(alias.asname or alias.name)
    if explicit_all is not None:
        names.update(explicit_all)
    return names



def _python_defined_public_symbols_from_text(source):
    """Only classes/functions defined by this file; imported names do not establish module identity."""
    try:
        tree = ast.parse(str(source or ''))
    except Exception:
        return set()
    return {
        node.name
        for node in tree.body
        if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef))
        and not node.name.startswith('_')
    }


def _manifest_file_item(manifest, rel):
    rel = str(rel or '').replace('\\', '/')
    return next(
        (x for x in (manifest or {}).get('files') or [] if str(x.get('path') or '').replace('\\', '/') == rel),
        {},
    )


def _manifest_exports_for_file(manifest, rel):
    return _normalize_export_contract(_manifest_file_item(manifest, rel).get('exports'))


def _python_public_symbols_in_file(path):
    try:
        source = Path(path).read_text(encoding='utf-8', errors='replace')
        tree = ast.parse(source)
    except Exception:
        return set()
    names = set()
    for node in tree.body:
        if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith('_'):
            names.add(node.name)
    return names


def _manifest_contract_issues(work, manifest):
    """Deterministically enforce public symbols promised by the manifest."""
    root = Path(work)
    issues = []
    for item in (manifest or {}).get('files') or []:
        rel = str(item.get('path') or '').replace('\\', '/')
        expected = _normalize_export_contract(item.get('exports'))
        if not rel or not expected or Path(rel).suffix.lower() not in {'.py', '.pyw'}:
            continue
        path = root / rel
        if not path.exists() or not path.is_file():
            continue
        actual = _python_public_symbols_in_file(path)
        missing = [name for name in expected if name not in actual]
        if missing:
            issues.append({
                'file': rel,
                'problem': (
                    'Manifest API contract violation: this file must define/export '
                    + ', '.join(missing)
                    + '. Do not substitute a different module responsibility.'
                ),
            })
    return issues


def _camel_words(name):
    text = str(name or '')
    text = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', text)
    text = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', text)
    return [x.lower() for x in re.split(r'[^A-Za-z0-9]+', text) if x]


def _identity_word_related(a, b):
    a = str(a or '').lower()
    b = str(b or '').lower()
    if not a or not b:
        return False
    if a == b:
        return True
    return min(len(a), len(b)) >= 4 and (a.startswith(b) or b.startswith(a))


def _module_identity_problem_for_content(rel, purpose, declared_exports, content):
    """Return a conservative role-mismatch error for one Python candidate, or empty string."""
    if not QWEN_MODULE_IDENTITY_CHECK:
        return ''
    if _normalize_export_contract(declared_exports):
        return ''  # Exact manifest contracts are stronger and checked separately.
    if str(purpose or '').lower().startswith('existing project file'):
        return ''

    role_words = {
        'service', 'dialog', 'view', 'window', 'manager', 'controller', 'repository',
        'client', 'server', 'engine', 'handler', 'worker', 'processor', 'export',
        'import', 'adjustment', 'screen', 'panel', 'widget', 'store', 'router',
    }
    skip_stems = {
        'main', 'app', 'utils', 'util', 'helpers', 'helper', 'common', 'config', 'settings',
        'constants', 'models', 'model', 'validation', 'database', 'db', 'routes', 'tests', 'test',
    }
    stem = Path(rel).stem.lower()
    if stem.startswith('__') or stem in skip_stems:
        return ''
    stem_words = [w for w in stem.split('_') if w]
    if len(stem_words) < 2 or not (set(stem_words) & role_words):
        return ''

    symbols = _python_defined_public_symbols_from_text(content)
    if not symbols:
        return ''
    symbol_words = set()
    for name in symbols:
        symbol_words.update(_camel_words(name))
    meaningful = [w for w in stem_words if len(w) > 2]
    related = any(_identity_word_related(a, b) for a in meaningful for b in symbol_words)
    if meaningful and not related:
        return (
            f"Module identity mismatch: {Path(rel).name} appears to implement unrelated public symbols "
            f"{', '.join(sorted(symbols))}. Keep this file focused on its manifest/path responsibility."
        )
    return ''


def _module_identity_issues(work, manifest):
    """Conservative wrong-module-copy detector for Python files lacking explicit export contracts."""
    if not QWEN_MODULE_IDENTITY_CHECK:
        return []
    root = Path(work)
    issues = []
    for item in (manifest or {}).get('files') or []:
        rel = str(item.get('path') or '').replace('\\', '/')
        if Path(rel).suffix.lower() not in {'.py', '.pyw'}:
            continue
        path = root / rel
        if not path.exists() or not path.is_file():
            continue
        try:
            content = path.read_text(encoding='utf-8', errors='replace')
        except Exception:
            continue
        problem = _module_identity_problem_for_content(
            rel,
            str(item.get('purpose') or ''),
            item.get('exports'),
            content,
        )
        if problem:
            issues.append({'file': rel, 'problem': problem})
    return issues



def _symbol_provider_files(work, manifest=None):
    """Map public symbols to intended providers, preferring manifest contracts over current broken code."""
    manifest_providers = {}
    for item in (manifest or {}).get('files') or []:
        rel = str(item.get('path') or '').replace('\\', '/')
        for symbol in _normalize_export_contract(item.get('exports')):
            manifest_providers.setdefault(symbol, [])
            if rel and rel not in manifest_providers[symbol]:
                manifest_providers[symbol].append(rel)

    actual = {}
    root = Path(work)
    for path in sorted(root.rglob('*.py')):
        if not path.is_file():
            continue
        try:
            rel = path.relative_to(root)
        except Exception:
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel.parts):
            continue
        for symbol in _python_public_symbols_in_file(path):
            actual.setdefault(symbol, []).append(rel.as_posix())

    providers = dict(actual)
    for symbol, rels in manifest_providers.items():
        providers[symbol] = list(rels)
    return providers


def _route_semantic_issues(work, manifest, issues):
    """Re-attribute model audit findings to the file they actually describe and discard ungrounded drift."""
    manifest_paths = [
        str(x.get('path') or '').replace('\\', '/')
        for x in (manifest or {}).get('files') or []
        if str(x.get('path') or '').strip()
    ]
    providers = _symbol_provider_files(work, manifest)

    grouped = {}
    for issue in issues or []:
        source = str(issue.get('file') or '')
        problem = str(issue.get('problem') or '').strip()
        if not problem:
            continue
        low = problem.lower()

        file_targets = []
        for rel in manifest_paths:
            if rel.lower() == source.lower():
                continue
            base = Path(rel).name.lower()
            full_match = rel.lower() in low
            base_match = bool(
                base and re.search(
                    rf'(?<![A-Za-z0-9_]){re.escape(base)}(?![A-Za-z0-9_])',
                    low,
                )
            )
            if full_match or base_match:
                if rel not in file_targets:
                    file_targets.append(rel)

        symbol_targets = []
        for symbol, rels in providers.items():
            symbol_mentioned = (
                str(issue.get('symbol') or '') == symbol
                or bool(re.search(rf'\b{re.escape(symbol)}\b', problem))
            )
            if not symbol_mentioned:
                continue
            for rel in rels:
                # If the mentioned symbol is defined by the file being audited, keep this as a local
                # finding; otherwise route directly to its intended provider.
                if rel != source and rel not in symbol_targets:
                    symbol_targets.append(rel)

        # Semantic QA is intentionally file-local. If the auditor names another project file or a
        # symbol whose provider is another module, that is cross-file speculation. Cross-file defects
        # must be established by deterministic imports, tests, builds, or runtime tracebacks instead.
        cross_targets = symbol_targets or file_targets
        if cross_targets:
            _append_project_event(
                work,
                'semantic_cross_file_discarded',
                f'Discarded cross-file semantic speculation while auditing {source}.',
                file=source,
                mentioned_targets=cross_targets[:12],
                problem=problem[:1000],
            )
            continue

        grounded = bool(issue.get('grounded'))
        if not grounded:
            source_path = Path(work) / source
            local_symbols = _python_public_symbols_in_file(source_path) if source_path.exists() else set()
            grounded = any(re.search(rf'\b{re.escape(name)}\b', problem) for name in local_symbols)
        if QWEN_SEMANTIC_REQUIRE_EVIDENCE and not grounded:
            _append_project_event(
                work,
                'semantic_issue_discarded',
                f'Discarded ungrounded semantic audit drift for {source}.',
                file=source,
                problem=problem[:1000],
            )
            continue
        if source:
            grouped.setdefault(source, [])
            if problem not in grouped[source]:
                grouped[source].append(problem)
    return grouped


def _module_for_project_file(work, manifest, rel):
    """Return the importable local module name represented by a project Python file."""
    work = Path(work).resolve()
    target = (work / rel).resolve()
    root, modules, _ = _python_module_map(work, manifest)
    for module, path in modules.items():
        try:
            if path.resolve() == target:
                return module
        except Exception:
            continue

    # Missing/new provider file fallback: derive module name relative to Python project root.
    try:
        relative = target.relative_to(root)
    except Exception:
        return ''
    if relative.suffix.lower() not in {'.py', '.pyw'}:
        return ''
    parts = list(relative.with_suffix('').parts)
    if parts and parts[-1] == '__init__':
        parts = parts[:-1]
    return '.'.join(parts)


def _required_exports_by_module(work, manifest):
    """Build a consumer-driven contract: local module -> symbols other project files import from it."""
    work = Path(work).resolve()
    root, modules, _ = _python_module_map(work, manifest)
    if not modules:
        return {}
    top_packages = {m.split('.')[0] for m in modules}
    required = {}
    for _module, path in modules.items():
        try:
            tree = ast.parse(path.read_text(encoding='utf-8', errors='replace'))
        except Exception:
            continue
        for node in ast.walk(tree):
            if not isinstance(node, ast.ImportFrom) or node.level != 0 or not node.module:
                continue
            imported_module = node.module
            if imported_module.split('.')[0] not in top_packages:
                continue
            for alias in node.names:
                if alias.name == '*':
                    continue
                # ``from package import child`` may be importing a real child submodule rather than
                # requiring ``child`` to be defined in package/__init__.py. Honor every indexed alias.
                if (imported_module + '.' + alias.name) in modules:
                    continue
                required.setdefault(imported_module, set()).add(alias.name)
    return required


def _required_exports_for_file(work, manifest, rel):
    """Union planner contracts with consumer requirements across every import alias for this file."""
    required = set(_manifest_exports_for_file(manifest, rel))
    target = (Path(work).resolve() / rel).resolve()
    _root, modules, _symbols = _python_module_map(work, manifest)
    by_module = _required_exports_by_module(work, manifest)
    for module, path in modules.items():
        try:
            same = path.resolve() == target
        except Exception:
            same = False
        if same:
            required.update(by_module.get(module, set()))
    return sorted(required)


def _provider_file_for_module(work, manifest, module):
    """Resolve a local module name such as app.inventory_service to its project-relative Python file."""
    work = Path(work).resolve()
    root, modules, _ = _python_module_map(work, manifest)
    path = modules.get(str(module or ''))
    if path is None:
        candidate = root / (str(module or '').replace('.', os.sep) + '.py')
        package_init = root / str(module or '').replace('.', os.sep) / '__init__.py'
        if candidate.exists():
            path = candidate
        elif package_init.exists():
            path = package_init
    if path is None:
        return ''
    try:
        return path.resolve().relative_to(work).as_posix()
    except Exception:
        return ''


def _route_dependency_issues(work, manifest, issues):
    """Route missing-export failures to the provider module, not every consumer that imports it."""
    grouped = {}
    export_re = re.compile(
        r"Imports ['\"]([^'\"]+)['\"] from local module ['\"]([^'\"]+)['\"].*?not defined/exported there\.",
        re.I,
    )
    missing_mod_re = re.compile(r"Imports missing local module ['\"]([^'\"]+)['\"]", re.I)

    for issue in issues or []:
        source_file = str(issue.get('file') or '')
        problem = str(issue.get('problem') or '')
        target = source_file
        routed_problem = problem

        match = export_re.search(problem)
        if match:
            symbol, module = match.group(1), match.group(2)
            provider = _provider_file_for_module(work, manifest, module)
            if provider:
                target = provider
                routed_problem = (
                    f"DEPENDENCY CONTRACT: {source_file} imports {symbol!r} from module {module!r}. "
                    f"This provider file must define/export {symbol!r} while preserving its other required APIs."
                )
        else:
            match = missing_mod_re.search(problem)
            if match:
                module = match.group(1)
                provider = _provider_file_for_module(work, manifest, module)
                if provider:
                    target = provider

        if target:
            grouped.setdefault(target, [])
            if routed_problem not in grouped[target]:
                grouped[target].append(routed_problem)
    return grouped


def _copy_project_for_candidate_validation(work):
    """Create a disposable clone used to validate a repair before committing it to live source."""
    source = Path(work).resolve()
    temp = tempfile.TemporaryDirectory(prefix='jarvis_candidate_')
    clone = Path(temp.name) / 'project'

    ignore_names = set(_ANALYSIS_IGNORE_DIRS) | {
        CANDIDATE_DIR_NAME, '__pycache__', '.pytest_cache', '.mypy_cache',
        'dist', 'build', 'target', 'node_modules', '.git', '.jarvis_build',
    }

    def ignore(_dir, names):
        return [name for name in names if name in ignore_names]

    try:
        copy_source_tree(source, clone, ignore=ignore)
    except BaseException:
        temp.cleanup()
        raise
    return temp, clone



def _bootstrap_candidate_validation_error(work, manifest, rel, content):
    """Minimal gate for materializing a MISSING planned file into the repairable workspace.

    The normal candidate transaction is intentionally strict and assumes the surrounding project
    already exists. During bootstrap that assumption is false: a valid file may import sibling
    modules that are still missing, or may expose a repairable caller/provider mismatch. Rejecting
    such a file keeps the sibling missing forever and creates a dependency deadlock.

    This gate NEVER authorizes packaging. It only decides whether a syntactically complete candidate
    may become live intermediate source so the ordinary deterministic/runtime/test acceptance loop
    can reconcile the project as a whole.
    """
    cleaned = _extract_single_file_response(content, rel)
    error = _content_validation_error(rel, cleaned)
    if error:
        return error

    suffix = Path(rel).suffix.lower()
    if suffix not in {'.py', '.pyw'}:
        return ''

    try:
        tree = ast.parse(cleaned)
    except Exception as exc:
        return f'Bootstrap candidate is not parseable Python: {exc}'

    item = _manifest_file_item(manifest, rel)
    purpose = str(item.get('purpose') or '')
    # Do not enforce every planner-declared export here: planner exports are hypotheses until the
    # source graph exists. Still require at least one declared identity anchor when possible so a
    # completely wrong module cannot be materialized under an unrelated filename.
    declared = _normalize_export_contract(item.get('exports'))
    actual = _python_top_level_exports_from_text(cleaned)
    if declared and not any(name in actual for name in declared):
        return (
            'Bootstrap candidate does not expose any planned identity anchor. Expected at least one of: '
            + ', '.join(declared)
        )

    identity_error = _module_identity_problem_for_content(rel, purpose, [], cleaned)
    if identity_error:
        return identity_error

    # A file that is merely cross-file-inconsistent is repairable. Syntax, empty/stub, path, and
    # module-identity defects are not. All cross-file import/export/signature/member checks remain
    # mandatory in the normal acceptance passes before packaging.
    return ''


def _materialize_repairable_bootstrap_candidate(work, manifest, rel, content):
    """Commit a valid-but-cross-file-incomplete missing candidate for later acceptance repair."""
    target = Path(work) / _safe_relative(rel)
    if target.exists() and target.is_file() and target.stat().st_size > 0:
        return False, 'Target already exists; bootstrap materialization is only for missing files.'
    cleaned = _extract_single_file_response(content, rel)
    error = _bootstrap_candidate_validation_error(work, manifest, rel, cleaned)
    if error:
        return False, error
    target.parent.mkdir(parents=True, exist_ok=True)
    tmp = target.with_name(target.name + '.jarvis_bootstrap_tmp')
    try:
        tmp.write_text(cleaned, encoding='utf-8')
        tmp.replace(target)
    except Exception as exc:
        try:
            tmp.unlink(missing_ok=True)
        except Exception:
            pass
        return False, str(exc)
    _delete_candidate_draft(work, rel)
    return True, ''


def _candidate_transaction_error(work, manifest, rel, content, user_request=None, validation_failure=None, target_problems=None):
    """Validate a repaired file in a cloned project before allowing it to overwrite live source."""
    cleaned = _extract_single_file_response(content, rel)
    error = _content_validation_error(rel, cleaned)
    if error:
        return error

    suffix = Path(rel).suffix.lower()
    if suffix not in {'.py', '.pyw'}:
        return ''

    required = _required_exports_for_file(work, manifest, rel)
    exports = _python_top_level_exports_from_text(cleaned)
    missing = [name for name in required if name not in exports]
    if missing:
        return (
            'Candidate violates the project API contract. It must define/export these names because '
            'the manifest and/or other project files require them: ' + ', '.join(missing)
        )

    item = _manifest_file_item(manifest, rel)
    identity_error = _module_identity_problem_for_content(
        rel, str(item.get('purpose') or ''), item.get('exports'), cleaned,
    )
    if identity_error:
        return identity_error

    # Consumer-derived class-member mismatches are reconcilable across provider + callers.
    # They are validated by the multi-file method-contract transaction, not forced onto every
    # single-file candidate here.

    if _is_jarvis_generated_acceptance_test(rel):
        target = Path(work) / rel
        try:
            current_test_source = target.read_text(encoding="utf-8", errors="replace") if target.exists() else ""
        except Exception:
            current_test_source = ""
        if current_test_source.strip():
            before_metrics = _generated_test_integrity_metrics(current_test_source)
            after_metrics = _generated_test_integrity_metrics(cleaned)
            if after_metrics["tests"] < before_metrics["tests"]:
                return (
                    "Generated-test repair would reduce test coverage by deleting test methods "
                    f"({before_metrics['tests']} -> {after_metrics['tests']}). Repair setup/assumptions instead."
                )
            if after_metrics["asserts"] < before_metrics["asserts"]:
                return (
                    "Generated-test repair would weaken assertions "
                    f"({before_metrics['asserts']} -> {after_metrics['asserts']}). Keep or strengthen assertions."
                )
            if after_metrics["skips"] > before_metrics["skips"]:
                return "Generated-test repair introduced skipped tests. Fix the test or production behavior instead."
            if validation_failure:
                before_assertions = _generated_test_assertion_fingerprints(current_test_source)
                after_assertions = _generated_test_assertion_fingerprints(cleaned)
                if before_assertions != after_assertions:
                    return (
                        "Generated-test runtime triage may not rewrite assertion semantics or expected exceptions. "
                        "Repair imports/setup/fixtures only; if assertions expose a real defect, repair production."
                    )

    baseline = _issue_set(_local_import_api_issues(work, manifest))
    baseline_extra_static = _extra_python_static_issue_set(work, manifest)

    temp = None
    try:
        temp, clone = _copy_project_for_candidate_validation(work)
        candidate_path = clone / _safe_relative(rel)
        candidate_path.parent.mkdir(parents=True, exist_ok=True)
        candidate_path.write_text(cleaned, encoding='utf-8')

        clone_issues = _local_import_api_issues(clone, manifest)
        introduced = []
        for dep_issue in clone_issues:
            key = (
                str(dep_issue.get('file') or ''),
                _stable_issue_problem(dep_issue.get('problem') or ''),
            )
            if key not in baseline:
                introduced.append(f"{key[0]}: {str(dep_issue.get('problem') or '')}")
        if introduced:
            return 'Candidate introduces new local import/API failures: ' + '; '.join(introduced[:12])

        introduced_extra_static = _extra_python_static_issue_set(clone, manifest) - baseline_extra_static
        if introduced_extra_static:
            return 'Candidate introduces new deterministic Python contract failures: ' + '; '.join(
                f"{f}: {p}" for f, p in list(introduced_extra_static)[:12]
            )

        # For deterministic problems with stable semantic identities, require the candidate to
        # actually remove the targeted defect rather than merely changing unrelated code.
        target_text = "\n".join(str(x or "") for x in (target_problems or []))
        if "DEFINITE-NONE MEMBER CALL:" in target_text:
            remaining_none = [
                x for x in _definite_none_member_call_issues(clone, manifest)
                if str(x.get("file") or "") == rel
            ]
            if remaining_none:
                return (
                    "Candidate changed code but did not fix the targeted definite-None member call: "
                    + "; ".join(str(x.get("problem") or "") for x in remaining_none[:6])
                )
        if "SQL ROW/MODEL CONTRACT:" in target_text:
            remaining_sql = [
                x for x in _sqlite_select_star_constructor_issues(clone, manifest)
                if str(x.get("file") or "") == rel
            ]
            if remaining_sql:
                return (
                    "Candidate changed code but did not fix the targeted SQL row/model contract: "
                    + "; ".join(str(x.get("problem") or "") for x in remaining_sql[:6])
                )
        if "GENERATED TEST API CONTRACT:" in target_text:
            remaining_test_contracts = [
                x for x in _generated_acceptance_test_contract_issues(clone, manifest)
                if str(x.get("file") or "") == rel
            ]
            if remaining_test_contracts:
                return (
                    "Candidate changed the generated acceptance test but it still invents local production APIs: "
                    + "; ".join(str(x.get("problem") or "") for x in remaining_test_contracts[:8])
                )
        if (
            "GENERATED TEST UNDEFINED NAME:" in target_text
            or "GENERATED TEST CALL SIGNATURE:" in target_text
            or "GENERATED TEST STORAGE ISOLATION:" in target_text
        ):
            remaining_preflight = [
                x for x in _generated_test_preflight_issues(clone, manifest)
                if str(x.get("file") or "") == rel
            ]
            if remaining_preflight:
                return (
                    "Candidate changed the generated acceptance test but it still fails deterministic test preflight: "
                    + "; ".join(str(x.get("problem") or "") for x in remaining_preflight[:8])
                )
        if "LOCAL CALL SIGNATURE CONTRACT:" in target_text:
            remaining_signature = [
                x for x in _python_local_call_signature_issues(clone, manifest)
                if str(x.get("file") or "") == rel
                and not _is_jarvis_generated_acceptance_test(x.get("file"))
            ]
            if remaining_signature:
                return (
                    "Candidate changed the caller but the local call-signature mismatch remains: "
                    + "; ".join(str(x.get("problem") or "") for x in remaining_signature[:8])
                )

        if validation_failure and RUNTIME_REPAIR_REPLAY:
            replay_ok, replay_output = _replay_validation_for_failure(
                clone, user_request or '', manifest, validation_failure
            )
            if not replay_ok and _runtime_failure_still_present(validation_failure, replay_output):
                excerpt = str(replay_output or '')[-RUNTIME_REPAIR_REPLAY_OUTPUT_CHARS:]
                return (
                    'Candidate compiles but does NOT fix the original real validation failure. '
                    'Jarvis replayed the failing validator in a disposable clone and observed the same failure:\n'
                    + excerpt
                )
    except Exception as exc:
        return f'Candidate sandbox validation failed: {exc}'
    finally:
        if temp is not None:
            temp.cleanup()

    return ''

def _repair_file_for_issues(
    user_request, manifest, work, rel, problems, progress_callback=None, validation_failure=None
):
    """Repair one file transactionally; real-failure repairs must improve replayed validation."""
    path = Path(work) / rel
    required_exports = _required_exports_for_file(work, manifest, rel)

    if not path.exists():
        item = next(
            (x for x in manifest.get("files") or [] if str(x.get("path") or "") == rel),
            {"path": rel, "purpose": "Required project file", "exports": required_exports},
        )
        file_ok, wrote = _generate_planned_file(user_request, manifest, work, item, progress_callback)
        return bool(file_ok and wrote)

    try:
        current = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        current = ""

    context = _project_context_for_file(work, manifest, rel)
    api_index = _project_api_index(work)
    draft = _load_candidate_draft(work, rel)
    manifest_item = _manifest_file_item(manifest, rel)
    required_contract = ", ".join(required_exports) if required_exports else "(no named exports required)"
    observed_methods = _required_methods_for_file(work, manifest, rel)
    observed_method_text = []
    for class_name, methods in sorted(observed_methods.items()):
        for method in sorted(methods):
            observed_method_text.append(f"{class_name}.{method}")
    observed_method_contract = ", ".join(observed_method_text) if observed_method_text else "(none)"

    repair_mode, repair_directive = _v33_repair_strategy(problems, validation_failure)
    dependency_context = _v33_dependency_context(manifest, rel)
    architecture_contract = _v33_contract_index(manifest)
    runtime_focus = ""
    if validation_failure:
        runtime_focus = (
            "\nREAL VALIDATOR REPLAY IS AUTHORITATIVE.\n"
            "Your candidate will be executed in a disposable clone. Success means the exact failure disappears or advances; "
            "an unchanged result will be rejected automatically.\n"
            f"REAL FAILURE TO ELIMINATE:\n{validation_failure}\n"
        )

    prompt = (
        f"V33 TARGETED REPAIR MODE: {repair_mode}\n"
        f"REPAIR DIRECTIVE: {repair_directive}\n"
        "Rewrite ONLY this target file completely. Return source from line 1; no patch/prose/markdown.\n"
        "PRESERVATION RULE: keep every unrelated working behavior and required public API intact.\n"
        "MINIMALITY RULE: make the smallest coherent repair that changes the failing validator/contract result.\n"
        "NO LOOP RULE: do not repeat a previously rejected strategy or return the file unchanged.\n"
        "NO API INVENTION RULE: sibling APIs come only from the authoritative architecture/implemented API evidence below.\n"
        "No TODOs/placeholders/pass-only stubs/omitted code.\n\n"
        f"USER REQUEST:\n{user_request}\n\n"
        f"TARGET FILE: {rel}\n"
        f"TARGET PURPOSE: {str(manifest_item.get('purpose') or '')}\n"
        f"TARGET DECLARED CONTRACTS: {json.dumps(manifest_item.get('contracts') or [], ensure_ascii=False)}\n"
        f"REQUIRED PUBLIC EXPORTS: {required_contract}\n"
        f"CURRENT CONSUMER MEMBER USAGES: {observed_method_contract}\n"
        f"{dependency_context}\n\n"
        f"AUTHORITATIVE ARCHITECTURE CONTRACT:\n{architecture_contract}\n\n"
        f"IMPLEMENTED PROJECT API INDEX:\n{api_index}\n\n"
        f"ISSUES TO FIX:\n{json.dumps(problems, ensure_ascii=False, indent=2)}\n"
        + runtime_focus
        + f"\nCURRENT FILE {rel}:\n{current}\n\n"
        f"FOCUSED IMPLEMENTED RELATED FILES:\n{context}\n"
    )

    if draft:
        prompt += (
            "\nPREVIOUS FAILED REPAIR CANDIDATE (rewrite cleanly from line 1; do not continue it):\n"
            f"{draft}\n"
        )

    best_candidate = ""
    best_error = ""
    rounds = max(2, FILE_FULL_REWRITE_ROUNDS)
    repair_started = time.monotonic()

    for attempt in range(1, rounds + 1):
        if time.monotonic() - repair_started > FILE_REPAIR_WALL_SECONDS:
            _append_project_event(
                work, 'file_repair_timebox',
                f"Repair timebox reached for {rel}; moving to fresh validation evidence instead of looping.",
                file=rel, problems=list(problems or [])[:8],
            )
            break
        attempt_prompt = prompt
        if best_error:
            attempt_prompt += (
                "\nTHE PREVIOUS REPLACEMENT WAS REJECTED BEFORE COMMIT.\n"
                f"TRANSACTION VALIDATION ERROR:\n{best_error}\n\n"
                "Return a NEW full replacement that fixes this exact failure.\n"
            )
            if best_candidate:
                attempt_prompt += f"REJECTED CANDIDATE:\n{best_candidate}\n"

        ok, content = _qwen_generate_complete_file(
            attempt_prompt, rel, progress_callback,
            f"Repairing {rel} transaction {attempt}/{rounds}", profile="repair"
        )
        candidate = _extract_single_file_response(content, rel)
        if candidate:
            best_candidate = candidate
        if not ok and not candidate:
            continue

        if candidate.strip() == current.strip():
            best_error = (
                "Candidate is effectively identical to the current file and therefore cannot fix the reported issue. "
                "Make a concrete code change."
            )
            _save_candidate_draft(work, rel, candidate)
            _append_project_event(
                work, "repair_candidate_rejected", f"Rejected unchanged repair for {rel}.",
                file=rel, reason=best_error,
            )
            continue

        tx_error = _candidate_transaction_error(
            work, manifest, rel, candidate,
            user_request=user_request, validation_failure=validation_failure,
            target_problems=problems
        )
        if tx_error:
            best_error = tx_error
            _save_candidate_draft(work, rel, candidate)
            _append_project_event(
                work, "repair_candidate_rejected", f"Rejected unsafe/incompatible repair for {rel}.",
                file=rel, reason=tx_error,
            )
            continue

        tmp = path.with_name(path.name + ".jarvis_tmp")
        try:
            tmp.write_text(candidate, encoding="utf-8")
            tmp.replace(path)
        except Exception:
            try:
                tmp.unlink(missing_ok=True)
            except Exception:
                pass
            return False

        _delete_candidate_draft(work, rel)
        _append_project_event(
            work, "file_repaired", f"Committed transactional repair for {rel}.",
            file=rel, required_exports=required_exports,
            runtime_replay=bool(validation_failure and RUNTIME_REPAIR_REPLAY),
        )
        return True

    if best_candidate:
        _save_candidate_draft(work, rel, best_candidate)
    return False


def _explicit_tests_requested(user_request):
    """True only when the user themselves explicitly asked for automated tests/testing."""
    low = str(user_request or '').lower()
    phrases = (
        'automated test', 'unit test', 'test suite', 'pytest', 'unittest',
        'write tests', 'add tests', 'include tests', 'run the tests', 'tests/',
    )
    return any(p in low for p in phrases)


def _is_jarvis_generated_manifest_test_item(item):
    if not isinstance(item, dict):
        return False
    purpose = str(item.get('purpose') or '').strip().lower()
    return bool(item.get('jarvis_generated_acceptance')) or purpose.startswith('jarvis-generated, non-authoritative')


def _manifest_authored_test_files(manifest):
    out = []
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item, dict) or _is_jarvis_generated_manifest_test_item(item):
            continue
        rel = str(item.get('path') or '').replace('\\', '/').strip('/')
        parts = [p.lower() for p in Path(rel).parts]
        if 'tests' in parts or 'test' in parts or Path(rel).name.lower().startswith('test_'):
            out.append(rel)
    return out


def _tests_were_requested(user_request, manifest, work=None):
    """Hard test requirement only.

    README/summary claims are deliberately NOT authoritative. They may make tests desirable, but a
    model-authored sentence such as 'Automated tests included' must never create an unfulfillable
    manifest obligation when the user did not request tests.
    """
    if _explicit_tests_requested(user_request):
        return True
    return bool(_manifest_authored_test_files(manifest))


def _tests_are_desirable(user_request, manifest, work=None):
    """Soft signal used to opportunistically generate QA tests without making them a hard blocker."""
    if _tests_were_requested(user_request, manifest, work):
        return True
    if isinstance(manifest, dict) and manifest.get('_jarvis_soft_test_docs_neutralized'):
        return False
    signals = [str((manifest or {}).get('summary') or '')]
    signals.extend(str(x or '') for x in ((manifest or {}).get('acceptance_criteria') or []))
    if work is not None:
        root = Path(work)
        for name in ('README.md', 'README.txt', 'readme.md', 'readme.txt'):
            path = root / name
            if path.exists() and path.is_file():
                try:
                    signals.append(path.read_text(encoding='utf-8', errors='replace'))
                except Exception:
                    pass
    low = '\n'.join(signals).lower()
    return any(p in low for p in (
        'automated test', 'unit test', 'test suite', 'pytest', 'unittest',
        '## testing', '# testing', 'tests/',
    ))


def _any_python_test_files(work):
    root = Path(work)
    for path in root.rglob('test*.py'):
        if path.is_file() and not any(part in _ANALYSIS_IGNORE_DIRS for part in path.relative_to(root).parts):
            return True
    return False


def _generated_acceptance_manifest_item():
    return {
        'path': 'tests/test_generated_acceptance.py',
        'purpose': (
            'Jarvis-generated, non-authoritative automated acceptance tests for core non-GUI behavior. '
            'Exercise ONLY production constructors, attributes, methods, and signatures that already exist. '
            'Use isolated temporary runtime storage; never invent production APIs merely to make a test convenient.'
        ),
        'exports': [],
        'jarvis_generated_acceptance': True,
    }


def _commit_generated_test_manifest_item(manifest, item):
    rel = str(item.get('path') or '').replace('\\', '/').strip('/')
    files = manifest.setdefault('files', [])
    for existing in files:
        if str(existing.get('path') or '').replace('\\', '/').strip('/') == rel:
            existing.update(item)
            existing['jarvis_generated_acceptance'] = True
            return
    files.append(dict(item))


def _drop_generated_test_manifest_item(manifest, rel='tests/test_generated_acceptance.py'):
    rel = str(rel or '').replace('\\', '/').strip('/')
    before = list((manifest or {}).get('files') or [])
    kept = []
    removed = False
    for item in before:
        item_rel = str(item.get('path') or '').replace('\\', '/').strip('/') if isinstance(item, dict) else ''
        if item_rel == rel and _is_jarvis_generated_manifest_test_item(item):
            removed = True
            continue
        kept.append(item)
    if isinstance(manifest, dict):
        manifest['files'] = kept
    return removed


def _neutralize_unverified_soft_test_docs(work):
    """Conservatively remove only explicit bundled-test claims when optional test generation failed.

    This is used only when tests were NOT explicitly requested and no authored test files were planned.
    It prevents README prose generated by the model from becoming a false promise or an infinite QA loop.
    """
    root = Path(work)
    changed = []
    for name in ('README.md', 'README.txt', 'readme.md', 'readme.txt'):
        path = root / name
        if not path.exists() or not path.is_file():
            continue
        try:
            lines = path.read_text(encoding='utf-8', errors='replace').splitlines()
        except Exception:
            continue
        out = []
        i = 0
        touched = False
        while i < len(lines):
            line = lines[i]
            low = line.strip().lower()
            if re.fullmatch(r'[-*]\s*automated tests? included\.?', line.strip(), flags=re.I):
                touched = True
                i += 1
                continue
            if re.match(r'^#{1,6}\s+(?:automated\s+)?testing\s*$', line.strip(), flags=re.I):
                # Replace only this dedicated testing section, preserving all later sections.
                level = len(line) - len(line.lstrip('#'))
                out.append('#' * max(1, level) + ' Verification')
                out.append('This project does not bundle a standalone automated test suite. Run the application normally and use the documented workflow; Jarvis performs compile, contract, import/startup, and build validation before packaging.')
                touched = True
                i += 1
                while i < len(lines):
                    nxt = lines[i]
                    if re.match(r'^#{1,6}\s+', nxt.strip()):
                        break
                    i += 1
                continue
            out.append(line)
            i += 1
        if touched:
            path.write_text('\n'.join(out).rstrip() + '\n', encoding='utf-8')
            changed.append(path.relative_to(root).as_posix())
    return changed


def _maybe_generate_optional_acceptance_test(user_request, manifest, work, progress_callback=None):
    """Try a soft Jarvis QA suite without making a rejected candidate a permanent manifest file."""
    if _any_python_test_files(work) or not _tests_are_desirable(user_request, manifest, work):
        return False
    if _tests_were_requested(user_request, manifest, work):
        return False  # hard requirements are handled by the real-validation repair path

    attempts_done = int(manifest.get('_jarvis_optional_test_attempts', 0) or 0)
    max_attempts = max(1, int(os.getenv('JARVIS_QWEN_OPTIONAL_TEST_GENERATION_ATTEMPTS', '2')))
    if attempts_done >= max_attempts:
        if not manifest.get('_jarvis_soft_test_docs_neutralized'):
            changed = _neutralize_unverified_soft_test_docs(work)
            manifest['_jarvis_soft_test_docs_neutralized'] = True
            if changed:
                _append_project_event(
                    work, 'soft_test_claims_neutralized',
                    'Optional acceptance-test generation could not produce a valid suite; removed unsupported bundled-test claims from documentation.',
                    files=changed,
                )
        return False

    item = _generated_acceptance_manifest_item()
    manifest['_jarvis_optional_test_attempts'] = attempts_done + 1
    _delete_candidate_draft(work, item['path'])
    file_ok, wrote = _generate_planned_file(user_request, manifest, work, item, progress_callback)
    if file_ok and wrote and (Path(work) / wrote).exists():
        _commit_generated_test_manifest_item(manifest, item)
        _append_project_event(
            work, 'optional_generated_test_committed',
            'Committed an optional Jarvis-generated acceptance suite only after deterministic preflight passed.',
            file=wrote,
        )
        return True

    _drop_generated_test_manifest_item(manifest, item['path'])
    _delete_candidate_draft(work, item['path'])
    _append_project_event(
        work, 'optional_generated_test_rejected',
        'Optional generated acceptance suite failed preflight and was NOT added to the manifest.',
        attempt=manifest['_jarvis_optional_test_attempts'],
    )
    if manifest['_jarvis_optional_test_attempts'] >= max_attempts:
        changed = _neutralize_unverified_soft_test_docs(work)
        manifest['_jarvis_soft_test_docs_neutralized'] = True
        if changed:
            _append_project_event(
                work, 'soft_test_claims_neutralized',
                'Removed unsupported bundled-test claims after optional test generation exhausted its retry budget.',
                files=changed,
            )
    return False

def _python_entrypoint_path(work, manifest):
    work = Path(work)
    entry = str((manifest or {}).get('entrypoint') or '').replace('\\', '/').strip('/')
    if entry:
        path = work / entry
        if path.exists() and path.is_file() and path.suffix.lower() in {'.py', '.pyw'}:
            return path
    completed = _existing_project_text_files(work)
    picked = _pick_entrypoint(manifest or {}, completed)
    path = work / picked if picked else None
    return path if path and path.exists() and path.suffix.lower() in {'.py', '.pyw'} else None


def _python_project_root(work, manifest):
    """Best execution root for nested Python projects such as MyApp/main.py."""
    work = Path(work).resolve()
    entry = _python_entrypoint_path(work, manifest)
    if not entry:
        return work
    entry = entry.resolve()
    parent = entry.parent
    # If the entrypoint is nested under a named project folder, that folder is normally
    # the import root (e.g. MyApp/main.py imports app.*).
    if parent != work and work in parent.parents:
        return parent
    return work


def _python_validation_env(work, manifest, cwd=None):
    work = Path(work).resolve()
    root = Path(cwd or _python_project_root(work, manifest)).resolve()
    candidates = []
    for path in (root, work):
        text = str(path)
        if text not in candidates:
            candidates.append(text)
    old = os.environ.get('PYTHONPATH', '')
    if old:
        candidates.append(old)
    env = os.environ.copy()
    env['PYTHONPATH'] = os.pathsep.join(candidates)
    env['PYTHONDONTWRITEBYTECODE'] = '1'
    env['JARVIS_PROJECT_VALIDATION'] = '1'
    return env


def _discover_python_test_groups(work, manifest):
    """Return [(project_root, tests_dir)] for tests anywhere in a nested project."""
    work = Path(work).resolve()
    groups = {}
    for test_file in sorted(work.rglob('test*.py')):
        if not test_file.is_file():
            continue
        rel_parts = [p.lower() for p in test_file.relative_to(work).parts]
        if any(part in _ANALYSIS_IGNORE_DIRS for part in test_file.relative_to(work).parts):
            continue
        # Prefer the nearest ancestor literally named tests; otherwise use the file's parent.
        tests_dir = test_file.parent
        cur = test_file.parent
        while cur != work and work in cur.parents:
            if cur.name.lower() in {'tests', 'test'}:
                tests_dir = cur
                break
            cur = cur.parent
        project_root = tests_dir.parent if tests_dir.name.lower() in {'tests', 'test'} else _python_project_root(work, manifest)
        key = (str(project_root), str(tests_dir))
        groups[key] = (project_root, tests_dir)
    return list(groups.values())



def _generated_unittest_ids_from_source(source, module_name="test_generated_acceptance"):
    """Collect unittest-style test ids without importing/executing the generated test module."""
    try:
        tree = ast.parse(str(source or ""))
    except Exception:
        return []
    ids = []
    for node in tree.body:
        if not isinstance(node, ast.ClassDef):
            continue
        for child in node.body:
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and child.name.startswith("test"):
                ids.append(f"{module_name}.{node.name}.{child.name}")
    return ids


def _generated_pytest_node_ids(test_file, clone, manifest, project_root, tests_dir):
    """Collect pytest node ids for Jarvis's generated acceptance file."""
    env = _python_validation_env(clone, manifest, cwd=project_root)
    py = [str(tests_dir), str(project_root), str(clone)]
    old = env.get("PYTHONPATH", "")
    if old:
        py.append(old)
    env["PYTHONPATH"] = os.pathsep.join(dict.fromkeys(py))
    try:
        proc = subprocess.run(
            [sys.executable, "-m", "pytest", "--collect-only", "-q", str(test_file)],
            cwd=str(clone), env=env, capture_output=True, text=True,
            timeout=min(PROJECT_TEST_TIMEOUT, 30),
        )
    except Exception:
        return []
    raw = ((proc.stdout or "") + "\n" + (proc.stderr or "")).strip()
    out = []
    for line in raw.splitlines():
        s = line.strip()
        if "::" not in s or s.startswith("<"):
            continue
        # pytest -q collect emits path::Class::test_name / path::test_name.
        if s.endswith("collected") or " warnings" in s:
            continue
        out.append(s)
    return list(dict.fromkeys(out))


def _run_one_generated_test_case(clone, manifest, project_root, tests_dir, test_file, test_id, uses_pytest=False):
    """Run ONE Jarvis-generated acceptance test in its own fresh cwd.

    This gives every test its own relative SQLite/filesystem namespace even when production hard-codes
    paths such as `inventory.db`. The project source stays in the disposable clone and is imported via
    PYTHONPATH; only runtime side effects land in the per-test cwd.
    """
    env = _python_validation_env(clone, manifest, cwd=project_root)
    py = [str(tests_dir), str(project_root), str(clone)]
    old = env.get("PYTHONPATH", "")
    if old:
        py.append(old)
    env["PYTHONPATH"] = os.pathsep.join(dict.fromkeys(py))
    env["JARVIS_GENERATED_TEST_ISOLATED"] = "1"

    with tempfile.TemporaryDirectory(prefix="jarvis_testcase_cwd_") as case_cwd:
        if uses_pytest:
            node = str(test_id)
            # Collection may return a relative path. Make it absolute so cwd can be the isolated dir.
            if "::" in node:
                path_part, suffix = node.split("::", 1)
                p = Path(path_part)
                if not p.is_absolute():
                    p = (Path(clone) / p).resolve()
                node = str(p) + "::" + suffix
            cmd = [sys.executable, "-m", "pytest", "-q", node]
        else:
            cmd = [sys.executable, "-m", "unittest", str(test_id), "-v"]
        try:
            proc = subprocess.run(
                cmd, cwd=case_cwd, env=env, capture_output=True, text=True,
                timeout=PROJECT_TEST_TIMEOUT,
            )
        except subprocess.TimeoutExpired as exc:
            partial = ((exc.stdout or "") + "\n" + (exc.stderr or "")).strip()
            return False, f"Test {test_id} timed out after {PROJECT_TEST_TIMEOUT} seconds.\n{partial[-4000:]}"
        except Exception as exc:
            return False, f"Could not run isolated generated test {test_id}: {exc}"
        output = ((proc.stdout or "") + "\n" + (proc.stderr or "")).strip()
        return proc.returncode == 0, output


def _run_python_single_test(work, user_request, manifest, test_id):
    """Replay one named test in isolation. Used by transactional production repairs."""
    work = Path(work).resolve()
    test_id = str(test_id or "").strip()
    if not test_id:
        return False, "Targeted test replay is missing a test id."

    generated = None
    for p in work.rglob("test_generated_acceptance.py"):
        try:
            rel = p.relative_to(work).as_posix()
        except Exception:
            continue
        if _is_jarvis_generated_acceptance_test(rel):
            generated = p
            break
    if generated is None:
        # Fallback to full test validation for non-generated/user-authored test ids.
        return _run_python_tests(work, user_request, manifest)

    tests_dir = generated.parent
    project_root = tests_dir.parent if tests_dir.name.lower() in {"tests", "test"} else _python_project_root(work, manifest)
    uses_pytest = "::" in test_id
    ok, output = _run_one_generated_test_case(
        work, manifest, project_root, tests_dir, generated, test_id, uses_pytest=uses_pytest
    )
    prefix = f"JARVIS_TARGET_TEST_ID: {test_id}\n"
    return ok, prefix + output


def _split_real_test_failures(work, failure):
    """Parse mixed unittest/isolated-test output into independently routable failures."""
    raw = str(failure or "").replace("\r\n", "\n")
    records = []

    # V20 isolated generated-test runner emits an explicit marker for each test case.
    marker_re = re.compile(r"(?m)^===== JARVIS GENERATED TEST CASE: (.+?) =====\s*$")
    matches = list(marker_re.finditer(raw))
    if matches:
        for i, m in enumerate(matches):
            start = m.end()
            end = matches[i + 1].start() if i + 1 < len(matches) else len(raw)
            body = raw[start:end].strip()
            if not body:
                continue
            failed = bool(re.search(r"(?m)^(?:FAILED|ERROR|FAIL:|ERROR:)|\bFAILED \(.*(?:failures|errors)=", body))
            if not failed:
                continue
            test_id = m.group(1).strip()
            frames = _traceback_project_files(work, body)
            exc = ""
            for line in body.splitlines():
                s = line.strip()
                if re.match(r"^[A-Za-z_][A-Za-z0-9_.]*(?:Error|Exception):", s):
                    exc = s
            if re.search(r"(?m)^FAIL:", body):
                status = "FAIL"
            elif re.search(r"(?m)^ERROR:", body):
                status = "ERROR"
            else:
                status = "ERROR" if exc else "FAIL"
            records.append({
                "test_id": test_id, "status": status, "text": body,
                "frames": frames, "deepest": frames[0] if frames else "", "exception": exc,
            })
        return records

    # Compatibility with older aggregate unittest output.
    header = re.compile(r"(?m)^={20,}\n(ERROR|FAIL):\s+(.+?)\n-{20,}\n")
    hm = list(header.finditer(raw))
    for i, m in enumerate(hm):
        start = m.start()
        end = hm[i + 1].start() if i + 1 < len(hm) else len(raw)
        body = raw[start:end].strip()
        label = m.group(2).strip()
        paren = re.search(r"\(([^()]+)\)\s*$", label)
        if paren and "." in paren.group(1):
            test_id = paren.group(1).strip()
        else:
            first = label.split()[0]
            test_id = first
        frames = _traceback_project_files(work, body)
        exc = ""
        for line in body.splitlines():
            s = line.strip()
            if re.match(r"^[A-Za-z_][A-Za-z0-9_.]*(?:Error|Exception):", s):
                exc = s
        records.append({
            "test_id": test_id, "status": m.group(1), "text": body,
            "frames": frames, "deepest": frames[0] if frames else "", "exception": exc,
        })
    return records


def _generated_test_assertion_fingerprints(source):
    """Stable assertion semantics used to stop test triage from changing expected behavior."""
    try:
        tree = ast.parse(str(source or ""))
    except Exception:
        return []
    out = []
    for fn in [n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name.startswith("test")]:
        for node in ast.walk(fn):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr.startswith("assert"):
                out.append((fn.name, ast.dump(node, annotate_fields=True, include_attributes=False)))
    return sorted(out)


def _generated_test_production_target_for_test_id(work, manifest, test_id):
    """Infer a unique production provider exercised by one generated test method.

    Used for assertion failures that contain no production traceback because the method returned the
    wrong result instead of raising. The test assertion stays immutable; Jarvis repairs the production
    provider only when concrete calls in that test resolve to a unique local class/file.
    """
    test_name = str(test_id or "").split("::")[-1].split(".")[-1]
    if not test_name:
        return ""
    root = _python_project_root(work, manifest)
    class_index, _ = _python_local_class_index(work, manifest)
    if not class_index:
        return ""
    constructor_hints = _local_constructor_parameter_type_hints(work, manifest, class_index)

    for path in root.rglob("test_generated_acceptance.py"):
        try:
            rel = path.relative_to(Path(work)).as_posix()
        except Exception:
            continue
        if not _is_jarvis_generated_acceptance_test(rel):
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue
        types = _collect_simple_instance_types(tree, class_index)
        _apply_constructor_parameter_type_hints(tree, class_index, constructor_hints, types)
        target_fn = next(
            (n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name == test_name),
            None,
        )
        if target_fn is None:
            continue
        providers = []
        for call in ast.walk(target_fn):
            if not isinstance(call, ast.Call) or not isinstance(call.func, ast.Attribute):
                continue
            # unittest assertion helpers are not production calls.
            if call.func.attr.startswith("assert"):
                continue
            receiver = _expr_key(call.func.value)
            class_name = types.get(receiver, "")
            if class_name and class_name in class_index:
                provider = str(class_index[class_name].get("file") or "")
                if provider and not _is_jarvis_generated_acceptance_test(provider):
                    providers.append(provider)
        unique = list(dict.fromkeys(providers))
        if len(unique) == 1:
            return unique[0]
    return ""


def _run_python_tests(work, user_request, manifest):
    """Run discovered Python tests in disposable source + per-test runtime isolation.

    The whole project is first copied away from the deliverable. In addition, every Jarvis-generated
    acceptance test method runs in its own fresh current-working-directory so hard-coded relative
    SQLite/filesystem state cannot leak between test methods and create false failures.
    """
    work = Path(work).resolve()
    has_python = any(Path(x).suffix.lower() in {'.py', '.pyw'} for x in _existing_real_source_files(work))
    if not has_python:
        return True, ''

    groups = _discover_python_test_groups(work, manifest)
    if not groups:
        if _tests_were_requested(user_request, manifest, work):
            return False, 'Automated tests were requested/planned but no test*.py files were discovered anywhere in the project.'
        return True, ''

    try:
        with tempfile.TemporaryDirectory(prefix='jarvis_tests_') as tmp:
            clone = Path(tmp) / 'project'
            copy_source_tree(
                work, clone, dirs_exist_ok=True,
                ignore=shutil.ignore_patterns(
                    '__pycache__', '.pytest_cache', '.jarvis_build', '.jarvis_candidates', '.jarvis_backups',
                    '.jarvis_runtime', '.jarvis_failures', '.cache', 'node_modules', 'target', 'dist', 'build'
                ),
            )

            all_output = []
            total_tests_seen = 0
            for project_root, tests_dir in groups:
                try:
                    clone_project_root = clone / project_root.relative_to(work)
                    clone_tests_dir = clone / tests_dir.relative_to(work)
                except Exception:
                    return False, f'Could not map test group {tests_dir} into disposable validation clone.'

                test_files = sorted(clone_tests_dir.rglob('test*.py'))
                generated_files = []
                ordinary_files = []
                for path in test_files:
                    try:
                        rel = path.relative_to(clone).as_posix()
                    except Exception:
                        rel = path.name
                    if _is_jarvis_generated_acceptance_test(rel):
                        generated_files.append(path)
                    else:
                        ordinary_files.append(path)

                # Jarvis-generated acceptance tests: run EACH case separately in a fresh cwd.
                for generated in generated_files:
                    try:
                        source = generated.read_text(encoding='utf-8', errors='replace')
                    except Exception as exc:
                        return False, f'Could not read generated acceptance test {generated}: {exc}'
                    uses_pytest = bool(re.search(r'(^|\n)\s*(?:import\s+pytest|from\s+pytest\s+import)', source))
                    if uses_pytest:
                        ids = _generated_pytest_node_ids(
                            generated, clone, manifest, clone_project_root, clone_tests_dir
                        )
                    else:
                        ids = _generated_unittest_ids_from_source(source, generated.stem)
                    if not ids:
                        return False, f'Generated acceptance test {generated.name} exists but no runnable test cases were discovered.'

                    for test_id in ids:
                        ok, output = _run_one_generated_test_case(
                            clone, manifest, clone_project_root, clone_tests_dir,
                            generated, test_id, uses_pytest=uses_pytest,
                        )
                        total_tests_seen += 1
                        all_output.append(
                            f'===== JARVIS GENERATED TEST CASE: {test_id} =====\n{output}'
                        )
                        # Continue running the remaining generated cases so one validation pass gives the
                        # repair router the whole set of independent real defects.

                # User/project-authored tests retain their native runner/cwd semantics.
                for test_file in ordinary_files:
                    try:
                        source = test_file.read_text(encoding='utf-8', errors='replace')
                    except Exception:
                        source = ''
                    uses_pytest = bool(re.search(r'(^|\n)\s*(?:import\s+pytest|from\s+pytest\s+import)', source))
                    env = _python_validation_env(clone, manifest, cwd=clone_project_root)
                    if uses_pytest:
                        cmd = [sys.executable, '-m', 'pytest', '-q', str(test_file)]
                    else:
                        cmd = [
                            sys.executable, '-m', 'unittest', 'discover',
                            '-s', str(clone_tests_dir), '-p', test_file.name, '-v'
                        ]
                    try:
                        proc = subprocess.run(
                            cmd, cwd=str(clone), env=env, capture_output=True, text=True,
                            timeout=PROJECT_TEST_TIMEOUT,
                        )
                    except subprocess.TimeoutExpired as exc:
                        partial = ((exc.stdout or '') + '\n' + (exc.stderr or '')).strip()
                        return False, f'Test suite timed out after {PROJECT_TEST_TIMEOUT} seconds.\n{partial[-4000:]}'
                    except Exception as exc:
                        return False, f'Could not run test file {test_file}: {exc}'
                    output = ((proc.stdout or '') + '\n' + (proc.stderr or '')).strip()
                    all_output.append(f'===== TEST FILE {test_file.name} =====\n{output}')
                    ran = re.findall(r'Ran\s+(\d+)\s+tests?', output)
                    if ran:
                        total_tests_seen += sum(int(x) for x in ran)
                    elif uses_pytest:
                        m = re.search(r'(\d+)\s+passed', output)
                        if m:
                            total_tests_seen += int(m.group(1))

                # Determine pass/fail after collecting all independent results.
                group_output = '\n'.join(all_output)
                if any(
                    re.search(r'(?m)^(?:FAILED|ERROR|FAIL:|ERROR:)', chunk.split('\n', 1)[1] if '\n' in chunk else chunk)
                    or re.search(r'\bFAILED \(.*(?:failures|errors)=', chunk)
                    for chunk in all_output
                ):
                    return False, 'Test suite failed:\n' + group_output[-20000:]

            if _tests_were_requested(user_request, manifest, work) and total_tests_seen == 0:
                return False, 'Test files exist, but validation could not confirm that any tests actually ran.'
            return True, '\n'.join(all_output)[-8000:]
    except Exception as exc:
        return False, f'Could not prepare disposable Python test sandbox: {exc}'

def _python_module_map(work, manifest):
    """Map every valid local import alias to its Python provider file.

    Nested generated projects are commonly importable in *two* legitimate ways. For example, when
    the workspace contains ``StockPilot/main.py`` the execution root may be ``StockPilot`` (so
    ``app.inventory_service`` is valid), while PYTHONPATH also contains the workspace (so
    ``StockPilot.app.inventory_service`` is valid). Older Jarvis versions indexed only the first
    spelling. That made consumer-driven export contracts disappear whenever generated code used the
    second spelling, allowing a later repair to delete APIs that real callers still imported.

    V30 indexes both root-relative and workspace-relative aliases when they resolve to the same file.
    This keeps static import checks and transactional required-export gates aligned with Python's
    actual validation environment.
    """
    work = Path(work).resolve()
    root = _python_project_root(work, manifest).resolve()
    modules = {}
    symbols = {}

    def module_name_for(path, base):
        try:
            rel = path.relative_to(base)
        except Exception:
            return ""
        parts = list(rel.with_suffix('').parts)
        if parts and parts[-1] == '__init__':
            parts = parts[:-1]
        return '.'.join(parts)

    def bind(module, path, names):
        module = str(module or '').strip('.')
        if not module:
            return
        # If two files somehow claim the same import name, preserve the first deterministic mapping;
        # an ambiguous alias is not safe evidence for provider routing.
        existing = modules.get(module)
        if existing is not None:
            try:
                if existing.resolve() != path.resolve():
                    return
            except Exception:
                return
        modules[module] = path
        symbols[module] = set(names)

    for path in sorted(root.rglob('*.py')):
        if not path.is_file():
            continue
        try:
            rel = path.relative_to(root)
        except Exception:
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel.parts):
            continue

        try:
            tree = ast.parse(path.read_text(encoding='utf-8', errors='replace'))
        except Exception:
            tree = None
        names = set()
        if tree is not None:
            for node in tree.body:
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                    names.add(node.name)
                elif isinstance(node, (ast.Assign, ast.AnnAssign)):
                    targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                    for target in targets:
                        if isinstance(target, ast.Name):
                            names.add(target.id)
                elif isinstance(node, ast.Import):
                    for alias in node.names:
                        names.add(alias.asname or alias.name.split('.')[0])
                elif isinstance(node, ast.ImportFrom):
                    for alias in node.names:
                        if alias.name != '*':
                            names.add(alias.asname or alias.name)

        bind(module_name_for(path, root), path, names)

        # The validation environment deliberately places both root and work on PYTHONPATH. Mirror
        # that behavior in the deterministic graph when the Python project root is nested.
        if root != work:
            bind(module_name_for(path, work), path, names)

    return root, modules, symbols



def _expr_key(node):
    """Conservative dotted key for Name/Attribute expressions such as self.inventory_service."""
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        left = _expr_key(node.value)
        if left:
            return left + "." + node.attr
    return ""


def _python_local_class_index(work, manifest):
    """Map locally defined Python classes to their provider files and public methods."""
    root = _python_project_root(work, manifest)
    by_name = {}
    file_classes = {}
    for path in sorted(root.rglob("*.py")):
        if not path.is_file():
            continue
        try:
            rel_root = path.relative_to(root)
            rel_work = path.relative_to(Path(work)).as_posix()
        except Exception:
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel_root.parts):
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue
        for node in tree.body:
            if not isinstance(node, ast.ClassDef):
                continue
            methods = {
                child.name
                for child in node.body
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef))
            }
            instance_attrs = set()
            for child in ast.walk(node):
                if isinstance(child, (ast.Assign, ast.AnnAssign)):
                    targets = child.targets if isinstance(child, ast.Assign) else [child.target]
                    for target in targets:
                        if (
                            isinstance(target, ast.Attribute)
                            and isinstance(target.value, ast.Name)
                            and target.value.id == "self"
                        ):
                            instance_attrs.add(target.attr)
            base_names = []
            open_base = False
            for base in node.bases:
                if isinstance(base, ast.Name):
                    base_names.append(base.id)
                else:
                    # Dotted/expression bases are usually framework classes. Their members are open-world
                    # to this static checker, so do not invent missing-member errors for inherited APIs.
                    open_base = True
            info = {
                "name": node.name,
                "file": rel_work,
                "path": path,
                "methods": methods,
                "instance_attrs": instance_attrs,
                "bases": base_names,
                "open_base": open_base,
                "dynamic_attrs": "__getattr__" in methods or "__getattribute__" in methods,
                "node": node,
            }
            by_name.setdefault(node.name, []).append(info)
            file_classes.setdefault(rel_work, []).append(info)

    # Only a unique class name is safe to resolve globally without guessing.
    unique = {name: items[0] for name, items in by_name.items() if len(items) == 1}

    # Fold in members from uniquely resolved LOCAL base classes. If a base cannot be resolved locally,
    # leave the class open-world so framework inheritance (tk.Frame, QWidget, ORM models, etc.) does not
    # create false "missing member" findings.
    changed = True
    rounds = 0
    while changed and rounds < 8:
        rounds += 1
        changed = False
        for info in unique.values():
            for base_name in info.get("bases") or []:
                if base_name in {"object"}:
                    continue
                base = unique.get(base_name)
                if base is None:
                    info["open_base"] = True
                    continue
                before_m = len(info["methods"])
                before_a = len(info["instance_attrs"])
                info["methods"].update(base.get("methods") or set())
                info["instance_attrs"].update(base.get("instance_attrs") or set())
                info["dynamic_attrs"] = bool(info.get("dynamic_attrs") or base.get("dynamic_attrs"))
                info["open_base"] = bool(info.get("open_base") or base.get("open_base"))
                if len(info["methods"]) != before_m or len(info["instance_attrs"]) != before_a:
                    changed = True
    return unique, file_classes


def _local_class_constructor_aliases(tree, class_index):
    """Return names in one module that definitely refer to unique local classes."""
    aliases = {}
    local_names = set(class_index)
    for node in tree.body:
        if isinstance(node, ast.ImportFrom) and node.level == 0:
            for alias in node.names:
                if alias.name in local_names:
                    aliases[alias.asname or alias.name] = alias.name
        elif isinstance(node, ast.ClassDef) and node.name in local_names:
            aliases[node.name] = node.name
    return aliases


def _local_annotation_class_name(annotation, aliases, class_index):
    """Resolve a simple local-class type annotation without guessing."""
    if annotation is None:
        return ""
    if isinstance(annotation, ast.Name):
        name = annotation.id
        return aliases.get(name, name if name in class_index else "")
    if isinstance(annotation, ast.Constant) and isinstance(annotation.value, str):
        name = annotation.value.rsplit(".", 1)[-1].strip()
        return aliases.get(name, name if name in class_index else "")
    if isinstance(annotation, ast.Attribute):
        name = annotation.attr
        return aliases.get(name, name if name in class_index else "")
    # Optional[T] / list[T] / Union[T, None] style annotations: accept only when exactly one
    # unique local class appears inside the annotation.
    found = []
    for node in ast.walk(annotation):
        if isinstance(node, ast.Name):
            name = aliases.get(node.id, node.id if node.id in class_index else "")
            if name and name not in found:
                found.append(name)
        elif isinstance(node, ast.Attribute):
            name = aliases.get(node.attr, node.attr if node.attr in class_index else "")
            if name and name not in found:
                found.append(name)
    return found[0] if len(found) == 1 else ""


def _collect_simple_instance_types(tree, class_index):
    """Infer explicit local-class instance bindings, including trustworthy type annotations."""
    aliases = _local_class_constructor_aliases(tree, class_index)
    types = {}

    # Include classes defined in the same module even if not imported.
    for name in class_index:
        aliases.setdefault(name, name)

    # Function/method annotations are stronger evidence than variable-name guesses.
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            args = list(getattr(node.args, "posonlyargs", []) or [])
            args += list(node.args.args or [])
            args += list(node.args.kwonlyargs or [])
            for arg in args:
                inferred = _local_annotation_class_name(arg.annotation, aliases, class_index)
                if inferred:
                    types[arg.arg] = inferred

    changed = True
    rounds = 0
    while changed and rounds < 6:
        rounds += 1
        changed = False
        for node in ast.walk(tree):
            if isinstance(node, (ast.Assign, ast.AnnAssign)):
                value = node.value
                targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                inferred = ""
                if isinstance(value, ast.Call) and isinstance(value.func, ast.Name):
                    inferred = aliases.get(value.func.id, "")
                elif isinstance(value, (ast.Name, ast.Attribute)):
                    inferred = types.get(_expr_key(value), "")
                if not inferred and isinstance(node, ast.AnnAssign):
                    inferred = _local_annotation_class_name(node.annotation, aliases, class_index)
                if inferred:
                    for target in targets:
                        key = _expr_key(target)
                        if key and types.get(key) != inferred:
                            types[key] = inferred
                            changed = True
    return types


def _local_constructor_parameter_type_hints(work, manifest, class_index):
    """Infer constructor parameter types from concrete local-class construction sites.

    Example:
        svc = InventoryService()
        view = InventoryView(root, svc)

    lets Jarvis infer that InventoryView.__init__(..., inventory_service) receives an
    InventoryService even when the generated code omitted the annotation. Only unanimous,
    concrete observations are accepted.
    """
    root = _python_project_root(work, manifest)
    signatures = {}

    for class_name, info in class_index.items():
        node = info.get("node")
        init = None
        for child in getattr(node, "body", []) or []:
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and child.name == "__init__":
                init = child
                break
        if init is None:
            continue
        positional = list(getattr(init.args, "posonlyargs", []) or []) + list(init.args.args or [])
        names = [arg.arg for arg in positional]
        if names and names[0] in {"self", "cls"}:
            names = names[1:]
        kwonly = [arg.arg for arg in (init.args.kwonlyargs or [])]
        signatures[class_name] = names + kwonly

    observations = {}
    for path in sorted(root.rglob("*.py")):
        if not path.is_file():
            continue
        try:
            rel_root = path.relative_to(root)
        except Exception:
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel_root.parts):
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue

        aliases = _local_class_constructor_aliases(tree, class_index)
        for name in class_index:
            aliases.setdefault(name, name)
        types = _collect_simple_instance_types(tree, class_index)

        def expr_type(expr):
            if isinstance(expr, ast.Call) and isinstance(expr.func, ast.Name):
                return aliases.get(expr.func.id, "")
            if isinstance(expr, (ast.Name, ast.Attribute)):
                return types.get(_expr_key(expr), "")
            return ""

        for call in [n for n in ast.walk(tree) if isinstance(n, ast.Call)]:
            target_class = ""
            if isinstance(call.func, ast.Name):
                target_class = aliases.get(call.func.id, "")
            if not target_class or target_class not in signatures:
                continue
            params = signatures[target_class]
            for param, arg in zip(params, call.args):
                inferred = expr_type(arg)
                if inferred:
                    observations.setdefault((target_class, param), set()).add(inferred)
            for kw in call.keywords or []:
                if not kw.arg or kw.arg not in params:
                    continue
                inferred = expr_type(kw.value)
                if inferred:
                    observations.setdefault((target_class, kw.arg), set()).add(inferred)

    return {
        key: next(iter(values))
        for key, values in observations.items()
        if len(values) == 1
    }


def _apply_constructor_parameter_type_hints(tree, class_index, hints, types):
    """Propagate inferred constructor parameter types through `self.attr = parameter` assignments."""
    for class_node in [n for n in tree.body if isinstance(n, ast.ClassDef) and n.name in class_index]:
        init = next(
            (
                n for n in class_node.body
                if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name == "__init__"
            ),
            None,
        )
        if init is None:
            continue
        for node in ast.walk(init):
            if not isinstance(node, (ast.Assign, ast.AnnAssign)):
                continue
            value = node.value
            if not isinstance(value, ast.Name):
                continue
            inferred = hints.get((class_node.name, value.id), "")
            if not inferred:
                continue
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            for target in targets:
                key = _expr_key(target)
                if key:
                    types[key] = inferred
    return types


def _is_jarvis_generated_acceptance_test(rel):
    """Jarvis-authored acceptance tests are QA consumers, never authorities that may redefine production APIs."""
    norm = str(rel or "").replace("\\", "/").strip("/").lower()
    return norm == "tests/test_generated_acceptance.py"


def _python_method_contract_requirements(work, manifest, include_generated_acceptance_tests=False):
    """Infer method requirements from concrete calls on explicitly constructed local class instances.

    This is intentionally conservative: it never guesses a type from a variable name. It only follows
    assignments whose value is a known local class constructor (or a direct alias of one).
    """
    if not QWEN_METHOD_CONTRACT_CHECK:
        return {}

    root = _python_project_root(work, manifest)
    class_index, _ = _python_local_class_index(work, manifest)
    if not class_index:
        return {}

    requirements = {}
    constructor_hints = _local_constructor_parameter_type_hints(work, manifest, class_index)
    for path in sorted(root.rglob("*.py")):
        if not path.is_file():
            continue
        try:
            rel_root = path.relative_to(root)
            consumer_rel = path.relative_to(Path(work)).as_posix()
        except Exception:
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel_root.parts):
            continue
        if (
            _is_jarvis_generated_acceptance_test(consumer_rel)
            and not include_generated_acceptance_tests
        ):
            # Generated tests are non-authoritative consumers. A hallucinated test API must
            # cause the TEST to be repaired, never force production code to implement it.
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue

        types = _collect_simple_instance_types(tree, class_index)
        _apply_constructor_parameter_type_hints(tree, class_index, constructor_hints, types)

        # `self.method()` is a contract on the surrounding local class itself.
        class_ranges = []
        for class_node in [n for n in tree.body if isinstance(n, ast.ClassDef)]:
            if class_node.name in class_index:
                class_ranges.append((class_node, class_node.name))

        call_attribute_ids = {
            id(call.func)
            for call in ast.walk(tree)
            if isinstance(call, ast.Call) and isinstance(call.func, ast.Attribute)
        }

        for node in ast.walk(tree):
            # Attribute access catches both direct calls (`service.refresh()`) and callback references
            # (`command=dialog.show`). Only definitely-typed LOCAL instances are considered.
            if not isinstance(node, ast.Attribute):
                continue
            receiver = _expr_key(node.value)
            member = node.attr
            class_name = types.get(receiver, "")

            if not class_name and receiver == "self":
                lineno = getattr(node, "lineno", -1)
                for class_node, candidate_name in class_ranges:
                    end = getattr(class_node, "end_lineno", 10**9)
                    if getattr(class_node, "lineno", 0) <= lineno <= end:
                        class_name = candidate_name
                        break

            if not class_name or class_name not in class_index:
                continue

            provider = class_index[class_name]
            provider_rel = provider["file"]
            if provider.get("dynamic_attrs") or provider.get("open_base"):
                continue
            available = set(provider.get("methods") or set()) | set(provider.get("instance_attrs") or set())
            if member in available:
                continue

            key = (provider_rel, class_name, member)
            evidence = {
                "provider_file": provider_rel,
                "class": class_name,
                "method": member,
                "consumer_file": consumer_rel,
                "line": getattr(node, "lineno", "?"),
                "usage": "call" if id(node) in call_attribute_ids else "attribute",
            }
            requirements.setdefault(key, []).append(evidence)

    return requirements


def _generated_acceptance_test_contract_issues(work, manifest):
    """Find Jarvis-generated test references to local members that production does not provide.

    These defects belong to the generated TEST, not to the production provider. This prevents
    hallucinated test aliases such as service.get_all() from forcing real code to grow fake APIs.
    """
    issues = []
    all_requirements = _python_method_contract_requirements(
        work, manifest, include_generated_acceptance_tests=True
    )
    for (provider_rel, class_name, member), evidence in all_requirements.items():
        generated_evidence = [
            ev for ev in evidence
            if _is_jarvis_generated_acceptance_test(ev.get("consumer_file"))
        ]
        if not generated_evidence:
            continue
        consumers = sorted({str(ev.get("consumer_file") or "") for ev in generated_evidence if ev.get("consumer_file")})
        first = generated_evidence[0]
        for consumer_rel in consumers:
            consumer_evidence = [ev for ev in generated_evidence if str(ev.get("consumer_file") or "") == consumer_rel]
            issues.append({
                "file": consumer_rel,
                "kind": "generated_test_contract",
                "provider_file": provider_rel,
                "class": class_name,
                "member": member,
                "consumer_files": [consumer_rel],
                "evidence": consumer_evidence,
                "problem": (
                    f"GENERATED TEST API CONTRACT: Jarvis-generated test {consumer_rel} uses "
                    f"{class_name}.{member}, but production class {class_name!r} in {provider_rel} does not "
                    "provide that member. Generated tests are non-authoritative and MUST be rewritten to "
                    "use the real existing production API; do not add a production compatibility method "
                    "only to satisfy this generated test."
                    + (f" First observed at line {first.get('line')}." if first.get("line") else "")
                ),
            })
    return issues


def _local_class_method_api_issues(work, manifest):
    """Find concrete local class/member mismatches.

    These are RECONCILABLE contracts, not immutable provider requirements: the provider may need
    the member, or the consumer may be calling the wrong API. Repair logic evaluates both sides
    transactionally.
    """
    issues = []
    for (provider_rel, class_name, method), evidence in _python_method_contract_requirements(work, manifest).items():
        first = evidence[0]
        consumers = sorted({x["consumer_file"] for x in evidence})
        issues.append({
            "file": provider_rel,
            "kind": "method_contract",
            "provider_file": provider_rel,
            "class": class_name,
            "member": method,
            "consumer_files": consumers,
            "evidence": evidence,
            "problem": (
                f"LOCAL CLASS MEMBER CONTRACT: class {class_name!r} is used with member {method!r}, "
                f"but that member is not provided. Reconcile the provider/caller API across "
                f"{', '.join(consumers[:5])}"
                + (f" (first observed at line {first['line']})." if first.get("line") else ".")
            ),
        })
    return issues


def _required_methods_for_file(work, manifest, rel):
    """Required class members for one provider file, derived from concrete local consumers."""
    out = {}
    for (provider_rel, class_name, method), _evidence in _python_method_contract_requirements(work, manifest).items():
        if provider_rel == rel:
            out.setdefault(class_name, set()).add(method)
    return out


def _candidate_class_methods(content):
    """Class -> concrete members (methods + self attributes) for a Python candidate string."""
    try:
        tree = ast.parse(str(content or ""))
    except Exception:
        return {}
    out = {}
    for node in tree.body:
        if not isinstance(node, ast.ClassDef):
            continue
        members = {
            child.name
            for child in node.body
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef))
        }
        for child in ast.walk(node):
            if isinstance(child, (ast.Assign, ast.AnnAssign)):
                targets = child.targets if isinstance(child, ast.Assign) else [child.target]
                for target in targets:
                    if (
                        isinstance(target, ast.Attribute)
                        and isinstance(target.value, ast.Name)
                        and target.value.id == "self"
                    ):
                        members.add(target.attr)
        out[node.name] = members
    return out


def _runtime_attribute_provider_targets(work, manifest, failure):
    """Route missing-member AttributeErrors to the local class/module that owns the missing API."""
    raw = str(failure or "")
    class_index, _ = _python_local_class_index(work, manifest)
    targets = []

    patterns = [
        r"AttributeError:\s*['\"]?([A-Za-z_][A-Za-z0-9_]*)['\"]?\s*object has no attribute ['\"]([^'\"]+)['\"]",
        r"AttributeError:\s*type object ['\"]([A-Za-z_][A-Za-z0-9_]*)['\"] has no attribute ['\"]([^'\"]+)['\"]",
    ]
    for pattern in patterns:
        match = re.search(pattern, raw)
        if not match:
            continue
        class_name, member = match.group(1), match.group(2)
        provider = class_index.get(class_name)
        if provider:
            targets.append({
                "file": provider["file"],
                "problem": (
                    f"REAL RUNTIME CLASS CONTRACT: {class_name}.{member} is required by executed project code "
                    f"but {class_name!r} does not provide that attribute/method. Implement the missing API in this provider."
                ),
                "class": class_name,
                "member": member,
            })

    module_match = re.search(
        r"AttributeError:\s*module ['\"]([A-Za-z_][A-Za-z0-9_.]*)['\"] has no attribute ['\"]([^'\"]+)['\"]",
        raw,
    )
    if module_match:
        module, member = module_match.group(1), module_match.group(2)
        provider = _provider_file_for_module(work, manifest, module)
        if provider:
            targets.append({
                "file": provider,
                "problem": (
                    f"REAL RUNTIME MODULE CONTRACT: module {module!r} must provide attribute {member!r}; "
                    "executed project code requires it."
                ),
                "module": module,
                "member": member,
            })

    # Keep stable order and no duplicates.
    out = []
    seen = set()
    for item in targets:
        rel = item["file"]
        if rel not in seen:
            seen.add(rel)
            out.append(item)
    return out



def _runtime_import_provider_targets(work, manifest, failure):
    """Route concrete ``cannot import name`` failures to the module that must provide the symbol.

    A traceback's deepest project frame is normally an excellent target, except for ImportError:
    the deepest frame is usually the *consumer* executing ``from provider import name``. The actual
    contract defect lives in the provider module (unless Python explicitly reports a partially
    initialized module, in which case an import cycle may involve both sides).
    """
    raw = str(failure or "")
    targets = []
    pattern = re.compile(
        r"ImportError:\s*cannot import name\s+['\"]([^'\"]+)['\"]\s+from\s+['\"]([^'\"]+)['\"]",
        re.I,
    )
    for match in pattern.finditer(raw):
        symbol, module = match.group(1), match.group(2)
        provider = _provider_file_for_module(work, manifest, module)
        if not provider:
            continue
        circular = "partially initialized module" in raw.lower()
        details = ""
        path = Path(work) / provider
        try:
            source = path.read_text(encoding="utf-8", errors="replace")
            top = _python_top_level_exports_from_text(source)
            if symbol not in top:
                owners = []
                tree = ast.parse(source)
                for node in tree.body:
                    if not isinstance(node, ast.ClassDef):
                        continue
                    if any(
                        isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and child.name == symbol
                        for child in node.body
                    ):
                        owners.append(node.name)
                if owners:
                    details = (
                        f" The name exists as class member {', '.join(x + '.' + symbol for x in owners)}, "
                        "but the module does not expose the top-level symbol required by the consumer."
                    )
        except Exception:
            pass

        if circular:
            problem = (
                f"REAL RUNTIME IMPORT-CYCLE CONTRACT: Python could not import {symbol!r} from partially initialized "
                f"local module {module!r} ({provider}). Inspect and break the concrete import cycle while preserving "
                "the public API; do not merely rewrite the consumer import line."
            )
            kind = "circular_import"
        else:
            problem = (
                f"REAL RUNTIME IMPORT PROVIDER CONTRACT: executed project code imports {symbol!r} from local module "
                f"{module!r}, whose provider is {provider}. The provider must define/export {symbol!r} with behavior "
                f"consistent with its real consumers.{details}"
            )
            kind = "missing_export"
        targets.append({
            "file": provider,
            "problem": problem,
            "module": module,
            "symbol": symbol,
            "kind": kind,
            "strong": not circular,
        })

    out = []
    seen = set()
    for item in targets:
        key = (item.get("file"), item.get("symbol"), item.get("kind"))
        if key not in seen:
            seen.add(key)
            out.append(item)
    return out


def _runtime_history_record(work, failure, increment=False):
    """Persist a bounded stable-failure history so repeat attempts can escalate instead of oscillate."""
    signature = _validation_failure_signature(failure)
    if not signature:
        return {"signature": "", "count": 1, "failed_targets": {}, "successful_targets": {}}
    key = hashlib.sha256(signature.encode("utf-8", errors="replace")).hexdigest()[:20]
    state = _load_project_state(work)
    history = state.get("runtime_failure_history")
    if not isinstance(history, dict):
        history = {}
    rec = history.get(key)
    if not isinstance(rec, dict) or rec.get("signature") != signature:
        rec = {
            "signature": signature,
            "count": 0,
            "failed_targets": {},
            "successful_targets": {},
            "first_seen": _utc_stamp(),
        }
    if increment:
        rec["count"] = int(rec.get("count") or 0) + 1
    rec["last_seen"] = _utc_stamp()
    history[key] = rec

    # Bound the state file. Keep the most recently seen signatures only.
    ordered = sorted(
        history.items(),
        key=lambda kv: str((kv[1] or {}).get("last_seen") or ""),
        reverse=True,
    )[:RUNTIME_FAILURE_HISTORY_LIMIT]
    state["runtime_failure_history"] = dict(ordered)
    state["last_runtime_failure_signature"] = signature
    state["last_runtime_failure_count"] = int(rec.get("count") or 0)
    _save_project_state(work, state)
    return rec


def _record_runtime_target_outcome(work, failure, rel, repaired):
    """Remember which target files failed/succeeded for one stable validation signature."""
    signature = _validation_failure_signature(failure)
    if not signature or not rel:
        return
    key = hashlib.sha256(signature.encode("utf-8", errors="replace")).hexdigest()[:20]
    state = _load_project_state(work)
    history = state.get("runtime_failure_history")
    if not isinstance(history, dict):
        history = {}
    rec = history.get(key)
    if not isinstance(rec, dict):
        rec = _runtime_history_record(work, failure, increment=False)
        state = _load_project_state(work)
        history = state.get("runtime_failure_history") or {}
        rec = history.get(key) or rec
    field = "successful_targets" if repaired else "failed_targets"
    values = rec.get(field)
    if not isinstance(values, dict):
        values = {}
    values[str(rel)] = int(values.get(str(rel)) or 0) + 1
    rec[field] = values
    rec["last_seen"] = _utc_stamp()
    history[key] = rec
    state["runtime_failure_history"] = history
    _save_project_state(work, state)


def _runtime_failed_target_counts(work, failure):
    rec = _runtime_history_record(work, failure, increment=False)
    vals = rec.get("failed_targets") if isinstance(rec, dict) else {}
    return dict(vals) if isinstance(vals, dict) else {}


def _try_runtime_missing_export_repair(user_request, manifest, work, failure, target, progress_callback=None):
    """Surgically restore a proven missing top-level provider export and replay the exact validator.

    The existing export synthesizer already infers signatures from real consumers/tests. This wrapper
    adds the runtime transaction property that matters here: if the exact failure remains, restore the
    original provider rather than leaving a speculative edit in the live project.
    """
    if str(target.get("kind") or "") != "missing_export":
        return False
    rel = str(target.get("file") or "")
    path = Path(work) / rel
    if not rel or not path.exists() or path.suffix.lower() not in {".py", ".pyw"}:
        return False
    try:
        original = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return False

    if not _try_surgical_top_level_export_synthesis(
        user_request, manifest, work, rel, [str(target.get("problem") or "")], progress_callback
    ):
        return False

    replay_ok, replay_output = _replay_validation_for_failure(work, user_request, manifest, failure)
    if replay_ok or not _runtime_failure_still_present(failure, replay_output):
        _append_project_event(
            work,
            "runtime_import_provider_repaired",
            f"Repaired missing runtime import provider export in {rel} and advanced the real validator.",
            file=rel,
            module=target.get("module"),
            symbol=target.get("symbol"),
            replay_ok=bool(replay_ok),
        )
        _record_runtime_target_outcome(work, failure, rel, True)
        return True

    # No measurable progress: rollback exactly this surgical edit.
    try:
        path.write_text(original, encoding="utf-8")
    except Exception:
        pass
    _append_project_event(
        work,
        "runtime_import_provider_repair_rejected",
        f"Rolled back missing-export repair for {rel}; the same runtime failure remained.",
        file=rel,
        module=target.get("module"),
        symbol=target.get("symbol"),
        replay=str(replay_output or "")[-RUNTIME_REPAIR_REPLAY_OUTPUT_CHARS:],
    )
    _record_runtime_target_outcome(work, failure, rel, False)
    return False

def _local_import_api_issues(work, manifest):
    """Catch missing local modules and `from local.module import missing_name` before runtime."""
    root, modules, symbols = _python_module_map(work, manifest)
    if not modules:
        return []
    top_packages = {m.split('.')[0] for m in modules}
    issues = []
    for module, path in modules.items():
        try:
            tree = ast.parse(path.read_text(encoding='utf-8', errors='replace'))
        except Exception:
            continue
        rel = path.relative_to(Path(work)).as_posix()
        for node in ast.walk(tree):
            if not isinstance(node, ast.ImportFrom) or node.level != 0 or not node.module:
                continue
            imported_module = node.module
            top = imported_module.split('.')[0]
            if top not in top_packages:
                continue
            if imported_module not in modules:
                # It can still be a package directory with only __init__.py already mapped under the same name.
                candidate_py = root / (imported_module.replace('.', os.sep) + '.py')
                candidate_pkg = root / imported_module.replace('.', os.sep) / '__init__.py'
                if not candidate_py.exists() and not candidate_pkg.exists():
                    issues.append({
                        'file': rel,
                        'problem': f'Imports missing local module {imported_module!r} at line {getattr(node, "lineno", "?")}.',
                    })
                continue
            exported = symbols.get(imported_module, set())
            for alias in node.names:
                if alias.name == '*':
                    continue
                if alias.name not in exported:
                    # A package may expose a child submodule without explicitly importing it in
                    # __init__.py. The alias-aware module map is authoritative here; path arithmetic
                    # against only one Python root is not, because nested projects can have two valid
                    # import spellings for the same file.
                    if (imported_module + '.' + alias.name) in modules:
                        continue
                    provider_path = modules.get(imported_module)
                    if provider_path is not None and provider_path.name == '__init__.py':
                        possible_py = provider_path.parent / (alias.name + '.py')
                        possible_pkg = provider_path.parent / alias.name / '__init__.py'
                        if possible_py.exists() or possible_pkg.exists():
                            continue
                    issues.append({
                        'file': rel,
                        'problem': (
                            f'Imports {alias.name!r} from local module {imported_module!r} at line '
                            f'{getattr(node, "lineno", "?")}, but that symbol is not defined/exported there.'
                        ),
                    })
    seen = set(); out = []
    for item in issues:
        key = (item['file'], item['problem'])
        if key not in seen:
            seen.add(key); out.append(item)
    return out


def _run_python_import_smoke(work, manifest):
    """Execute top-level entrypoint imports in a temporary copy without entering its __main__ UI loop."""
    if not QWEN_RUNTIME_SMOKE:
        return True, ''
    work = Path(work).resolve()
    entry = _python_entrypoint_path(work, manifest)
    if not entry:
        return True, ''
    project_root = _python_project_root(work, manifest)
    try:
        with tempfile.TemporaryDirectory(prefix='jarvis_import_smoke_') as tmp:
            clone = Path(tmp) / 'project'
            copy_source_tree(work, clone, dirs_exist_ok=True, ignore=shutil.ignore_patterns('__pycache__', '.pytest_cache', '.jarvis_build', '.jarvis_runtime', '.jarvis_failures', '.cache', 'node_modules', 'target', 'dist', 'build'))
            rel_entry = entry.relative_to(work)
            clone_entry = clone / rel_entry
            clone_root = clone / project_root.relative_to(work)
            env = _python_validation_env(clone, manifest, cwd=clone_root)
            code = (
                "import runpy; "
                f"runpy.run_path({str(clone_entry)!r}, run_name='__jarvis_validation_import__')"
            )
            try:
                proc = subprocess.run(
                    [sys.executable, '-c', code], cwd=str(clone), env=env,
                    stdin=subprocess.DEVNULL, capture_output=True, text=True,
                    timeout=max(8, PROJECT_SMOKE_TIMEOUT * 2),
                )
            except subprocess.TimeoutExpired as exc:
                partial = ((exc.stdout or '') + '\n' + (exc.stderr or '')).strip()
                return False, f'Python import smoke test timed out.\n{partial[-5000:]}'
    except Exception as exc:
        return False, f'Could not run Python import smoke test: {exc}'
    output = ((proc.stdout or '') + '\n' + (proc.stderr or '')).strip()
    if proc.returncode != 0:
        return False, 'Python import/startup dependency smoke test failed:\n' + output[-8000:]
    return True, output[-2000:]


def _run_python_startup_smoke(work, manifest):
    """Actually start the Python entrypoint briefly. A long-running GUI/server is a successful smoke start."""
    if not QWEN_RUNTIME_SMOKE:
        return True, ''
    work = Path(work).resolve()
    entry = _python_entrypoint_path(work, manifest)
    if not entry:
        return True, ''
    project_root = _python_project_root(work, manifest)
    env = _python_validation_env(work, manifest, cwd=project_root)
    # Validate a temporary copy so startup code cannot corrupt the generated deliverable's data files.
    try:
        with tempfile.TemporaryDirectory(prefix='jarvis_smoke_') as tmp:
            clone = Path(tmp) / 'project'
            copy_source_tree(work, clone, dirs_exist_ok=True, ignore=shutil.ignore_patterns('__pycache__', '.pytest_cache', '.jarvis_build', '.jarvis_runtime', '.jarvis_failures', '.cache', 'node_modules', 'target', 'dist', 'build'))
            rel_entry = entry.relative_to(work)
            clone_entry = clone / rel_entry
            clone_root = clone / project_root.relative_to(work)
            clone_manifest = dict(manifest or {})
            env = _python_validation_env(clone, clone_manifest, cwd=clone_root)
            cmd = [sys.executable, str(clone_entry)]
            try:
                proc = subprocess.run(
                    cmd, cwd=str(clone), env=env, stdin=subprocess.DEVNULL,
                    capture_output=True, text=True, timeout=PROJECT_SMOKE_TIMEOUT,
                )
            except subprocess.TimeoutExpired as exc:
                # A GUI/event loop/web server that remains alive through the smoke interval has started successfully.
                partial = ((exc.stdout or '') + '\n' + (exc.stderr or '')).strip()
                return True, ('Entrypoint remained alive through smoke interval.\n' + partial[-2000:]).strip()
    except Exception as exc:
        return False, f'Could not prepare/run startup smoke test: {exc}'
    output = ((proc.stdout or '') + '\n' + (proc.stderr or '')).strip()
    if proc.returncode != 0:
        return False, 'Python real startup smoke test failed:\n' + output[-8000:]
    return True, output[-2000:]


def _run_python_runtime_validation(work, manifest):
    ok, output = _run_python_import_smoke(work, manifest)
    if not ok:
        return False, output
    ok, startup = _run_python_startup_smoke(work, manifest)
    if not ok:
        return False, startup
    return True, '\n'.join(x for x in (output, startup) if x)[-4000:]


def _run_command(cmd, cwd, timeout, env=None):
    try:
        proc = subprocess.run(cmd, cwd=str(cwd), env=env, stdin=subprocess.DEVNULL, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired as exc:
        output = ((exc.stdout or '') + '\n' + (exc.stderr or '')).strip()
        return False, f'Command timed out after {timeout}s: {" ".join(map(str, cmd))}\n{output[-6000:]}'
    except Exception as exc:
        return False, f'Could not execute {" ".join(map(str, cmd))}: {exc}'
    output = ((proc.stdout or '') + '\n' + (proc.stderr or '')).strip()
    if proc.returncode != 0:
        return False, f'Command failed ({proc.returncode}): {" ".join(map(str, cmd))}\n{output[-8000:]}'
    return True, output[-3000:]


def _run_nonpython_build_validation(work, manifest):
    """V34.1 native-toolchain dependency/build/test gate with host-aware validation."""
    if not QWEN_REAL_BUILD: return True, ''
    work=Path(work).resolve(); manifest=_v34_apply_toolchain_defaults('', manifest or {})
    adapter=str(manifest.get('toolchain_adapter') or _v34_infer_toolchain('',manifest,work))
    outputs=[]
    def run(parts,cwd=work):
        ok,out=_run_command(parts,cwd,PROJECT_BUILD_TIMEOUT); outputs.append(out); return ok,out
    # Node-family: install first, then declared native scripts.
    package=next(iter(work.rglob('package.json')),None)
    if package:
        root=package.parent; npm=shutil.which('npm');
        if not npm: return False,'Node project detected but npm is not installed/available.'
        try: data=json.loads(package.read_text(encoding='utf-8')); scripts=data.get('scripts') or {}
        except Exception as exc: return False,f'package.json is invalid JSON: {exc}'
        install=[npm,'ci'] if (root/'package-lock.json').exists() else [npm,'install','--no-audit','--no-fund']
        ok,out=run(install,root)
        if not ok: return False,out
        if 'build' in scripts:
            ok,out=run([npm,'run','build'],root)
            if not ok: return False,out
        if 'test' in scripts and 'no test specified' not in str(scripts.get('test','')).lower():
            ok,out=run([npm,'test','--','--runInBand'],root)
            if not ok:
                # Some runners reject Jest's option; replay plain npm test before failing.
                ok,out=run([npm,'test'],root)
                if not ok: return False,out
        return True,'\n'.join(outputs)[-8000:]
    # Unreal must be detected BEFORE ordinary C++/CMake.
    uproject=next(iter(work.rglob('*.uproject')),None)
    if uproject or adapter=='unreal':
        if os.name!='nt': return True,'HOST-LIMITED: Unreal project generated; UnrealBuildTool verification requires an Unreal-capable host/toolchain.'
        ubt=shutil.which('UnrealBuildTool') or shutil.which('UnrealBuildTool.exe')
        if not ubt: return True,'HOST-LIMITED: Unreal project structure detected but UnrealBuildTool is not installed/in PATH; not falsely marking it CMake-verified.'
        return True,'UnrealBuildTool detected. Project descriptor/module rules are present; full engine build requires the installed engine/version-specific target invocation.'
    if adapter=='unity' or (work/'ProjectSettings'/'ProjectVersion.txt').exists():
        unity=shutil.which('Unity') or shutil.which('Unity.exe')
        if not unity: return True,'HOST-LIMITED: Unity project generated; Unity editor is not installed/in PATH for batchmode validation.'
        return _run_command([unity,'-batchmode','-quit','-projectPath',str(work),'-logFile','-'],work,PROJECT_BUILD_TIMEOUT)
    # Android/Gradle/JVM
    gradle_root=None
    for marker in ('settings.gradle.kts','settings.gradle','build.gradle.kts','build.gradle'):
        found=next(iter(work.rglob(marker)),None)
        if found: gradle_root=found.parent; break
    if gradle_root:
        wrapper=(gradle_root/'gradlew.bat' if os.name=='nt' else gradle_root/'gradlew')
        gradle=str(wrapper) if wrapper.exists() else shutil.which('gradle')
        if not gradle: return False,'Gradle project detected but neither gradlew wrapper nor gradle is installed/available.'
        is_android=adapter=='android_gradle' or (gradle_root/'app'/'src'/'main'/'AndroidManifest.xml').exists()
        tasks=['assembleDebug','testDebugUnitTest'] if is_android else ['build','test']
        for task in tasks:
            ok,out=run([gradle,task,'--no-daemon'],gradle_root)
            if not ok: return False,out
        return True,'\n'.join(outputs)[-8000:]
    pom=next(iter(work.rglob('pom.xml')),None)
    if pom:
        root=pom.parent; mvnw=root/('mvnw.cmd' if os.name=='nt' else 'mvnw'); mvn=str(mvnw) if mvnw.exists() else shutil.which('mvn')
        if not mvn: return False,'Maven project detected but Maven/mvnw is not available.'
        return _run_command([mvn,'test','-B'],root,PROJECT_BUILD_TIMEOUT)
    # Swift/Xcode host-aware paths.
    package_swift=next(iter(work.rglob('Package.swift')),None)
    if package_swift:
        swift=shutil.which('swift')
        if not swift: return True,'HOST-LIMITED: Swift package generated but Swift toolchain is not installed on this host.'
        root=package_swift.parent
        ok,out=run([swift,'package','resolve'],root)
        if not ok: return False,out
        ok,out=run([swift,'build'],root)
        if not ok: return False,out
        tests=root/'Tests'
        if tests.exists():
            ok,out=run([swift,'test'],root)
            if not ok:return False,out
        return True,'\n'.join(outputs)[-8000:]
    xcodeproj=next(iter(work.rglob('*.xcodeproj')),None); xcworkspace=next(iter(work.rglob('*.xcworkspace')),None)
    if xcodeproj or xcworkspace or adapter in ('ios_xcode','macos_xcode'):
        xcb=shutil.which('xcodebuild')
        if not xcb: return True,'HOST-LIMITED: Native Apple/Xcode project generated on a non-Xcode host. Source/project structure is validated, but Jarvis does not falsely claim an Xcode compile.'
        target=xcworkspace or xcodeproj
        cmd=[xcb,'-list'] + (['-workspace',str(target)] if xcworkspace else ['-project',str(target)]) if target else [xcb,'-version']
        return _run_command(cmd,work,PROJECT_BUILD_TIMEOUT)
    # CMake C/C++ after Unreal check.
    cmake_file=next(iter(work.rglob('CMakeLists.txt')),None)
    suffixes={Path(x).suffix.lower() for x in _existing_real_source_files(work)}
    if cmake_file or (adapter=='cpp_cmake' and suffixes.intersection({'.c','.cc','.cpp','.cxx'})):
        if not cmake_file:return False,'C/C++ CMake project selected but CMakeLists.txt is missing.'
        cmake=shutil.which('cmake')
        if not cmake:return False,'CMake project detected but cmake is not installed/available.'
        root=cmake_file.parent; b=root/'.jarvis_build'
        ok,out=run([cmake,'-S',str(root),'-B',str(b)],root)
        if not ok:return False,out
        ok,out=run([cmake,'--build',str(b),'--config','Release'],root)
        if not ok:return False,out
        ctest=shutil.which('ctest')
        if ctest and next(iter(root.rglob('CTestTestfile.cmake')),None):
            ok,out=run([ctest,'--test-dir',str(b),'-C','Release','--output-on-failure'],root)
            if not ok:return False,out
        return True,'\n'.join(outputs)[-8000:]
    cargo=next(iter(work.rglob('Cargo.toml')),None)
    if cargo:
        exe=shutil.which('cargo')
        if not exe:return False,'Rust project detected but cargo is not installed/available.'
        root=cargo.parent
        ok,out=run([exe,'fetch'],root)
        if not ok:return False,out
        return _run_command([exe,'test','--no-fail-fast'],root,PROJECT_BUILD_TIMEOUT)
    gomod=next(iter(work.rglob('go.mod')),None)
    if gomod:
        go=shutil.which('go')
        if not go:return False,'Go project detected but go is not installed/available.'
        root=gomod.parent
        ok,out=run([go,'mod','download'],root)
        if not ok:return False,out
        return _run_command([go,'test','./...'],root,PROJECT_BUILD_TIMEOUT)
    sln=next(iter(work.rglob('*.sln')),None); csproj=next(iter(work.rglob('*.csproj')),None)
    if (sln or csproj) and adapter!='unity':
        dotnet=shutil.which('dotnet')
        if not dotnet:return False,'.NET project detected but dotnet is not installed/available.'
        target=sln or csproj; root=target.parent
        ok,out=run([dotnet,'restore',str(target)],root)
        if not ok:return False,out
        ok,out=run([dotnet,'build',str(target),'--no-restore','--nologo'],root)
        if not ok:return False,out
        return True,'\n'.join(outputs)[-8000:]
    pubspec=next(iter(work.rglob('pubspec.yaml')),None)
    if pubspec:
        root=pubspec.parent; flutter=shutil.which('flutter')
        if flutter:
            for args in ([flutter,'pub','get'],[flutter,'analyze']):
                ok,out=run(args,root)
                if not ok:return False,out
            if next(iter(root.rglob('*_test.dart')),None):
                ok,out=run([flutter,'test'],root)
                if not ok:return False,out
            return True,'\n'.join(outputs)[-8000:]
        dart=shutil.which('dart')
        if dart:return _run_command([dart,'analyze'],root,PROJECT_BUILD_TIMEOUT)
        return False,'Flutter/Dart project detected but neither flutter nor dart is installed.'
    composer=next(iter(work.rglob('composer.json')),None)
    if composer:
        exe=shutil.which('composer')
        if not exe:return False,'Composer project detected but composer is unavailable.'
        root=composer.parent
        ok,out=run([exe,'install','--no-interaction','--no-progress'],root)
        if not ok:return False,out
        return _run_command([exe,'validate','--no-check-publish'],root,PROJECT_BUILD_TIMEOUT)
    gemfile=next(iter(work.rglob('Gemfile')),None)
    if gemfile:
        bundle=shutil.which('bundle')
        if not bundle:return False,'Ruby Bundler project detected but bundle is unavailable.'
        root=gemfile.parent
        ok,out=run([bundle,'install'],root)
        if not ok:return False,out
        return True,'\n'.join(outputs)[-8000:]
    # Extensible declared adapter: safe executable only; no shell operators.
    if V34_GENERIC_COMMANDS and adapter=='generic':
        for label,key in (('dependency command','dependency_command'),('build command','build_command'),('test command','test_command')):
            cmd=str(manifest.get(key) or '').strip()
            if not cmd:continue
            ok,out=_v34_run_declared_command(work,cmd,label); outputs.append(out)
            if not ok:return False,out
        if outputs:return True,'\n'.join(outputs)[-8000:]
    return True,

def _run_real_project_validation(work, user_request, manifest):
    """Real execution/build gates. This is the authority, not the model's claim that code is complete."""
    has_python = any(Path(x).suffix.lower() in {'.py', '.pyw'} for x in _existing_real_source_files(work))
    outputs = []
    if has_python:
        import_issues = _local_import_api_issues(work, manifest)
        if import_issues:
            return False, '\n'.join(f"{x['file']}: {x['problem']}" for x in import_issues)
        ok, output = _run_python_runtime_validation(work, manifest)
        if not ok:
            return False, output
        if output:
            outputs.append(output)
        ok, output = _run_python_tests(work, user_request, manifest)
        if not ok:
            return False, output
        if output:
            outputs.append(output)
    ok, output = _run_nonpython_build_validation(work, manifest)
    if not ok:
        return False, output
    if output:
        outputs.append(output)
    return True, '\n'.join(outputs)[-6000:]



def _validation_failure_signature(text):
    """Stable fingerprint for a real validation failure, including test identity when available."""
    raw = str(text or "").replace("\\", "/")
    target_test = ""
    m = re.search(r"JARVIS_TARGET_TEST_ID:\s*([^\n\r]+)", raw)
    if m:
        target_test = m.group(1).strip().lower()
    if not target_test:
        # unittest error/failure header: ERROR: name (module.Class.name)
        m = re.search(r"(?m)^(?:ERROR|FAIL):\s+.*?\(([^()]+)\)\s*$", raw)
        if m:
            target_test = m.group(1).strip().lower()
    if not target_test:
        m = re.search(r"===== JARVIS GENERATED TEST CASE:\s*(.+?)\s*=====", raw)
        if m:
            target_test = m.group(1).strip().lower()

    raw = re.sub(
        r"[A-Za-z]:/[^ \n\r\t\"]*?/Temp/jarvis_[^ \n\r\t\"]*/project/",
        "<project>/", raw, flags=re.I
    )
    raw = re.sub(r"/tmp/[^ \n\r\t\"]*?/project/", "<project>/", raw, flags=re.I)
    raw = re.sub(r"line\s+\d+", "line <n>", raw, flags=re.I)

    project_frames = []
    for match in re.finditer(r'File\s+"([^"]+)"\s*,\s*line\s+<n>', raw, flags=re.I):
        frame = match.group(1).replace("\\", "/")
        if "<project>/" in frame:
            frame = frame.split("<project>/", 1)[1]
        project_frames.append(frame.lower())

    exception_lines = []
    for line in raw.splitlines():
        s = line.strip()
        if re.match(r"^[A-Za-z_][A-Za-z0-9_.]*(?:Error|Exception|Interrupt):\s*.+", s):
            exception_lines.append(re.sub(r"\s+", " ", s).lower())

    prefix = (target_test + "|") if target_test else ""
    if exception_lines:
        deepest = project_frames[-1] if project_frames else ""
        core = f"{deepest}|{exception_lines[-1]}" if deepest else exception_lines[-1]
        return (prefix + core)[-1800:]

    meaningful = [
        re.sub(r"\s+", " ", x.strip()).lower()
        for x in raw.splitlines()
        if x.strip() and not x.lstrip().startswith("File ")
    ]
    deepest = project_frames[-1] if project_frames else ""
    tail = meaningful[-1] if meaningful else raw.strip().lower()
    core = f"{deepest}|{tail}" if deepest else tail
    return (prefix + core)[-1800:]

def _traceback_project_files(work, failure):
    """Map traceback frames from a disposable clone back to live project-relative files."""
    root = Path(work).resolve()
    existing = _existing_project_text_files(root)
    existing_norm = {rel.replace("\\", "/").lower(): rel for rel in existing}
    raw = str(failure or "").replace("\\", "/")
    frames = re.findall(r'File\s+"([^"]+)"\s*,\s*line\s+\d+', raw, flags=re.I)

    mapped = []
    for frame in frames:
        norm = frame.replace("\\", "/").lower()
        for low_rel, rel in existing_norm.items():
            if norm.endswith("/" + low_rel) or norm == low_rel:
                mapped.append(rel)
                break

    out = []
    for rel in reversed(mapped):
        if rel not in out:
            out.append(rel)
    return out


def _replay_validation_for_failure(work, user_request, manifest, failure):
    """Replay the same class of real validator that produced the original failure."""
    low = str(failure or "").lower()
    has_python = any(Path(x).suffix.lower() in {".py", ".pyw"} for x in _existing_real_source_files(work))

    target_match = re.search(r"JARVIS_TARGET_TEST_ID:\s*([^\n\r]+)", str(failure or ""))
    if has_python and target_match:
        return _run_python_single_test(work, user_request, manifest, target_match.group(1).strip())

    if has_python and "python real startup smoke test failed" in low:
        return _run_python_startup_smoke(work, manifest)
    if has_python and "python import/startup dependency smoke test failed" in low:
        return _run_python_import_smoke(work, manifest)
    if has_python and "python import smoke test timed out" in low:
        return _run_python_import_smoke(work, manifest)
    if has_python and any(token in low for token in ("unittest", "pytest", "test failed", "tests failed", "failures=", "errors=")):
        return _run_python_tests(work, user_request, manifest)
    if any(token in low for token in ("cmake", "cargo", "go test", "dotnet", "npm ", "flutter", "dart ", "command failed")):
        return _run_nonpython_build_validation(work, manifest)

    return _run_real_project_validation(work, user_request, manifest)


def _runtime_failure_still_present(original_failure, replay_failure):
    original_sig = _validation_failure_signature(original_failure)
    replay_sig = _validation_failure_signature(replay_failure)
    if original_sig and replay_sig and original_sig == replay_sig:
        return True
    if original_sig and replay_sig and (original_sig in replay_sig or replay_sig in original_sig):
        return True
    return False


def _parse_missing_module_attribute_failure(failure):
    """Return (module_name, attribute_name) for a concrete Python module AttributeError."""
    raw = str(failure or "")
    match = re.search(
        r"AttributeError:\s*module\s+['\"]([^'\"]+)['\"]\s+has\s+no\s+attribute\s+['\"]([^'\"]+)['\"]",
        raw,
        flags=re.I,
    )
    if not match:
        return None
    return match.group(1), match.group(2)


def _discover_unique_submodule_attribute_owner(module_name, attribute_name):
    """Find a unique immediate submodule that statically defines a missing attribute.

    This scans submodule source files through import specs without importing the submodules
    themselves. It is intentionally conservative and returns a result only when exactly one
    immediate submodule clearly defines/exports the requested name.
    """
    module_name = str(module_name or "").strip()
    attribute_name = str(attribute_name or "").strip()
    if not module_name or not attribute_name:
        return ""

    try:
        spec = importlib.util.find_spec(module_name)
    except Exception:
        return ""
    locations = list(getattr(spec, "submodule_search_locations", None) or []) if spec else []
    if not locations:
        return ""

    owners = []
    for loc in locations[:20]:
        root = Path(loc)
        if not root.exists() or not root.is_dir():
            continue
        try:
            children = sorted(root.iterdir(), key=lambda x: x.name.lower())
        except Exception:
            continue
        for child in children[:200]:
            source_path = None
            subname = ""
            if child.is_file() and child.suffix.lower() == ".py" and child.stem != "__init__":
                source_path = child
                subname = child.stem
            elif child.is_dir() and (child / "__init__.py").is_file():
                source_path = child / "__init__.py"
                subname = child.name
            if source_path is None:
                continue

            # Packages frequently expose functionality as an explicit submodule rather than as
            # an attribute on the package root (for example pkg.dialog). If the missing attribute
            # exactly names that immediate submodule, it is a concrete owner candidate.
            if subname == attribute_name:
                owners.append(module_name + "." + subname)
                continue

            try:
                tree = ast.parse(source_path.read_text(encoding="utf-8", errors="replace"))
            except Exception:
                continue

            names = set()
            for node in tree.body:
                if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
                    names.add(node.name)
                elif isinstance(node, ast.Assign):
                    for target in node.targets:
                        if isinstance(target, ast.Name):
                            names.add(target.id)
                elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                    names.add(node.target.id)
                elif isinstance(node, ast.ImportFrom):
                    for alias in node.names:
                        names.add(alias.asname or alias.name)
            if attribute_name in names:
                owners.append(module_name + "." + subname)

    owners = list(dict.fromkeys(owners))
    return owners[0] if len(owners) == 1 else ""

def _python_import_aliases_for_module(source, module_name):
    """Return local names that definitely refer to module_name in one Python source file."""
    try:
        tree = ast.parse(source)
    except Exception:
        return [], None
    aliases = []
    for node in tree.body:
        if isinstance(node, ast.Import):
            for item in node.names:
                if item.name == module_name:
                    local = item.asname or item.name.split(".")[0]
                    if local not in aliases:
                        aliases.append(local)
        elif isinstance(node, ast.ImportFrom):
            base = str(node.module or "")
            for item in node.names:
                full = (base + "." + item.name).strip(".")
                if full == module_name:
                    local = item.asname or item.name
                    if local not in aliases:
                        aliases.append(local)
    return aliases, tree


def _top_level_bound_names(tree):
    names = set()
    for node in getattr(tree, "body", []) or []:
        if isinstance(node, ast.Import):
            for item in node.names:
                names.add(item.asname or item.name.split(".")[0])
        elif isinstance(node, ast.ImportFrom):
            for item in node.names:
                names.add(item.asname or item.name)
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            names.add(node.name)
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    names.add(target.id)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            names.add(node.target.id)
    return names


def _rewrite_missing_module_attribute_source(source, module_name, attribute_name, owner_module):
    """Rewrite a proven module attribute access to its uniquely discovered submodule owner."""
    aliases, tree = _python_import_aliases_for_module(source, module_name)
    if tree is None or not aliases:
        return ""

    owner_alias = ""
    for node in tree.body:
        if isinstance(node, ast.Import):
            for item in node.names:
                if item.name == owner_module:
                    owner_alias = item.asname or item.name.split(".")[0]
                    break
        elif isinstance(node, ast.ImportFrom):
            base = str(node.module or "")
            for item in node.names:
                if (base + "." + item.name).strip(".") == owner_module:
                    owner_alias = item.asname or item.name
                    break
        if owner_alias:
            break

    bound = _top_level_bound_names(tree)
    if not owner_alias:
        leaf = owner_module.rsplit(".", 1)[-1]
        owner_alias = leaf
        if owner_alias in bound:
            base = "_jarvis_" + re.sub(r"[^A-Za-z0-9_]+", "_", leaf)
            owner_alias = base
            suffix = 2
            while owner_alias in bound:
                owner_alias = f"{base}_{suffix}"
                suffix += 1

    alias_set = set(aliases)
    matched = [0]

    class Rewriter(ast.NodeTransformer):
        def visit_Attribute(self, node):
            node = self.generic_visit(node)
            if (
                isinstance(node, ast.Attribute)
                and node.attr == attribute_name
                and isinstance(node.value, ast.Name)
                and node.value.id in alias_set
            ):
                node.value = ast.copy_location(ast.Name(id=owner_alias, ctx=ast.Load()), node.value)
                matched[0] += 1
            return node

    tree = Rewriter().visit(tree)
    ast.fix_missing_locations(tree)
    if not matched[0]:
        return ""

    owner_already_imported = False
    for node in tree.body:
        if isinstance(node, ast.Import):
            for item in node.names:
                if item.name == owner_module and (item.asname or item.name.split(".")[0]) == owner_alias:
                    owner_already_imported = True
        elif isinstance(node, ast.ImportFrom):
            base = str(node.module or "")
            for item in node.names:
                if (base + "." + item.name).strip(".") == owner_module and (item.asname or item.name) == owner_alias:
                    owner_already_imported = True

    if not owner_already_imported:
        import_node = ast.Import(names=[ast.alias(name=owner_module, asname=owner_alias)])
        insert_at = 0
        if tree.body and isinstance(tree.body[0], ast.Expr):
            value = getattr(tree.body[0], "value", None)
            if isinstance(value, ast.Constant) and isinstance(value.value, str):
                insert_at = 1
        while (
            insert_at < len(tree.body)
            and isinstance(tree.body[insert_at], ast.ImportFrom)
            and tree.body[insert_at].module == "__future__"
        ):
            insert_at += 1
        tree.body.insert(insert_at, import_node)
        ast.fix_missing_locations(tree)

    try:
        rendered = ast.unparse(tree)
    except Exception:
        return ""
    return rendered.rstrip() + "\n"


def _deterministic_missing_module_attribute_repair(
    user_request, manifest, work, failure, progress_callback=None
):
    """Repair a proven missing module attribute when a unique submodule owns that attribute."""
    parsed = _parse_missing_module_attribute_failure(failure)
    if not parsed:
        return False
    module_name, attribute_name = parsed

    traceback_targets = _traceback_project_files(work, failure)
    if not traceback_targets:
        return False
    rel = traceback_targets[0]
    path = Path(work) / rel
    if not path.exists() or path.suffix.lower() not in {".py", ".pyw"}:
        return False

    try:
        current = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return False

    owner = _discover_unique_submodule_attribute_owner(module_name, attribute_name)
    if not owner:
        return False

    candidate = _rewrite_missing_module_attribute_source(
        current, module_name, attribute_name, owner
    )
    if not candidate or candidate.strip() == current.strip():
        return False

    tx_error = _candidate_transaction_error(
        work,
        manifest,
        rel,
        candidate,
        user_request=user_request,
        validation_failure=failure,
    )
    if tx_error:
        _append_project_event(
            work,
            "deterministic_runtime_attribute_repair_rejected",
            f"Rejected deterministic runtime repair for {module_name}.{attribute_name}.",
            file=rel,
            owner_module=owner,
            reason=tx_error,
        )
        return False

    tmp = path.with_name(path.name + ".jarvis_tmp")
    try:
        tmp.write_text(candidate, encoding="utf-8")
        tmp.replace(path)
    except Exception:
        try:
            tmp.unlink(missing_ok=True)
        except Exception:
            pass
        return False

    _delete_candidate_draft(work, rel)
    _append_project_event(
        work,
        "deterministic_runtime_attribute_repair",
        f"Resolved missing module attribute {module_name}.{attribute_name} via {owner}.",
        file=rel,
        module=module_name,
        attribute=attribute_name,
        owner_module=owner,
        runtime_replay=True,
    )
    _progress(
        progress_callback,
        f"Deterministically repaired {rel}: {module_name}.{attribute_name} -> {owner}.{attribute_name}",
        stage="repairing",
    )
    return True


def _diagnose_runtime_failure(user_request, manifest, work, failure, progress_callback=None):
    """Diagnose a real failure; V33 prefers deterministic ownership over another LLM round-trip."""
    candidates = _existing_project_text_files(work)
    traceback_targets = _traceback_project_files(work, failure)
    provider_targets = _runtime_attribute_provider_targets(work, manifest, failure)
    import_provider_targets = _runtime_import_provider_targets(work, manifest, failure)

    # If deterministic evidence already identifies existing project files, do not spend another
    # 1-3 minute diagnosis call asking a 9B model to rediscover the same ownership. Provider evidence
    # outranks traceback callers; traceback frames fill in only when no provider was proven.
    deterministic = []
    for item in import_provider_targets + provider_targets:
        rel = str(item.get('file') or '') if isinstance(item, dict) else str(item or '')
        if rel in candidates and rel not in deterministic:
            deterministic.append(rel)
    for rel in traceback_targets:
        rel = str(rel or '')
        if rel in candidates and rel not in deterministic:
            deterministic.append(rel)
    low_failure = str(failure or '').lower()
    needs_creation_reasoning = any(x in low_failure for x in ('modulenotfounderror', 'no such file or directory', 'cannot find module'))
    if deterministic and not needs_creation_reasoning:
        _append_project_event(
            work, 'v33_runtime_diagnosis_bypassed',
            'Skipped model diagnosis because deterministic provider/traceback ownership already identified repair targets.',
            targets=deterministic[:PROJECT_RUNTIME_REPAIR_TARGETS],
        )
        return deterministic[:PROJECT_RUNTIME_REPAIR_TARGETS], []

    prompt = (
        "V33 RUNTIME DIAGNOSIS. A REAL startup/test/build validator failed. Return ONLY strict JSON.\n"
        "Choose the smallest root-cause file set. Provider/import ownership is stronger than a caller frame.\n"
        "Create a new file ONLY when the concrete error proves a required project file is genuinely absent.\n"
        "Do not propose unrelated cleanup, broad rewrites, compatibility aliases, or test weakening.\n"
        "JSON shape: "
        '{"repair_files":["existing/file.py"],"create_files":[{"path":"missing/file.py","purpose":"why","exports":[]}],"reason":"short"}.\n\n'
        f"USER REQUEST:\n{user_request}\n\n"
        f"AUTHORITATIVE ARCHITECTURE CONTRACT:\n{_v33_contract_index(manifest)}\n\n"
        f"IMPLEMENTED API INDEX:\n{_project_api_index(work)}\n\n"
        f"ATTRIBUTE PROVIDERS: {json.dumps(provider_targets, ensure_ascii=False)}\n"
        f"IMPORT PROVIDERS: {json.dumps(import_provider_targets, ensure_ascii=False)}\n"
        f"TRACEBACK TARGETS deepest-first: {json.dumps(traceback_targets, ensure_ascii=False)}\n\n"
        f"REAL VALIDATION FAILURE:\n{failure}\n\n"
        "EXISTING FILES:\n" + "\n".join(candidates)
    )
    ok, text = _qwen_call(
        prompt, progress_callback, "V33 diagnosing ambiguous runtime failure", profile="audit",
        max_tokens=2048, thinking=False, response_schema=QWEN_SCHEMA_RUNTIME_DIAGNOSIS,
        schema_name='runtime_diagnosis', strict_output=True
    )
    if not ok:
        return deterministic[:PROJECT_RUNTIME_REPAIR_TARGETS], []
    try:
        obj = _extract_json(text)
    except Exception:
        return deterministic[:PROJECT_RUNTIME_REPAIR_TARGETS], []

    existing = set(candidates)
    repairs = list(deterministic)
    for raw in obj.get("repair_files") or obj.get("files") or []:
        rel = str(raw).replace("\\", "/")
        if rel in existing and rel not in repairs:
            repairs.append(rel)

    creates = []
    for item in obj.get("create_files") or []:
        if isinstance(item, str):
            item = {"path": item, "purpose": "Required to fix real validation failure.", "exports": []}
        if not isinstance(item, dict):
            continue
        raw = item.get("path") or item.get("name")
        if not raw:
            continue
        try:
            rel = _safe_relative(raw).as_posix()
        except Exception:
            continue
        if Path(rel).name in _RESERVED_OUTPUT_NAMES or Path(rel).name.startswith("JARVIS_"):
            continue
        if rel not in existing and all(str(x.get("path") or "") != rel for x in creates):
            creates.append({
                "path": rel,
                "purpose": str(item.get("purpose") or "Required to fix real validation failure."),
                "phase": _v33_infer_phase(rel, item.get('purpose')),
                "depends_on": [], "contracts": [],
                "exports": _normalize_export_contract(item.get("exports") or []),
            })
    return repairs[:PROJECT_RUNTIME_REPAIR_TARGETS], creates[:PROJECT_RUNTIME_REPAIR_TARGETS]



def _generated_test_integrity_metrics(source):
    """Simple anti-test-dilution metrics for generated acceptance test rewrites."""
    try:
        tree = ast.parse(str(source or ""))
    except Exception:
        return {"tests": 0, "asserts": 0, "skips": 0}
    test_methods = 0
    assert_calls = 0
    skips = 0
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name.startswith("test"):
            test_methods += 1
            for dec in node.decorator_list:
                try:
                    d = ast.unparse(dec).lower()
                except Exception:
                    d = ""
                if "skip" in d:
                    skips += 1
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Attribute) and node.func.attr.startswith("assert"):
                assert_calls += 1
            try:
                ftxt = ast.unparse(node.func).lower()
            except Exception:
                ftxt = ""
            if ftxt.endswith("skiptest") or ".skiptest" in ftxt:
                skips += 1
    return {"tests": test_methods, "asserts": assert_calls, "skips": skips}


def _generated_test_failure_target(work, failure):
    """Any real validation failure whose deepest project frame is Jarvis's generated test."""
    frames = _traceback_project_files(work, failure)
    if frames and _is_jarvis_generated_acceptance_test(frames[0]):
        return frames[0]
    return ""


def _generated_test_runtime_authoring_target(work, failure):
    """Return a generated test file when the concrete runtime error originates in that test.

    Only authoring-style exceptions are claimed here. Assertion failures are deliberately excluded
    because a valid acceptance test may be exposing a real production behavior defect.
    """
    raw = str(failure or "")
    frames = _traceback_project_files(work, raw)
    if not frames:
        return ""
    deepest = frames[0]
    if not _is_jarvis_generated_acceptance_test(deepest):
        return ""
    last_exc = ""
    for line in raw.splitlines():
        s = line.strip()
        if re.match(r"^[A-Za-z_][A-Za-z0-9_.]*(?:Error|Exception):", s):
            last_exc = s
    if re.match(
        r"^(?:NameError|UnboundLocalError|TypeError|AttributeError|ImportError|ModuleNotFoundError):",
        last_exc,
    ):
        return deepest
    return ""




def _traceback_line_for_project_file(failure, rel):
    """Return the deepest concrete traceback line for one project-relative file."""
    rel_norm = str(rel or "").replace("\\", "/").lower()
    raw = str(failure or "").replace("\\", "/")
    found = []
    for path, line in re.findall(r'File\s+"([^"]+)"\s*,\s*line\s+(\d+)', raw, flags=re.I):
        norm = path.lower()
        if norm.endswith("/" + rel_norm) or norm == rel_norm:
            try:
                found.append(int(line))
            except Exception:
                pass
    return found[-1] if found else None


def _callable_info_for_line(source, line_no):
    """Smallest Python function/method containing line_no."""
    try:
        tree = ast.parse(str(source or ""))
    except Exception:
        return None
    parents = {}
    for parent in ast.walk(tree):
        for child in ast.iter_child_nodes(parent):
            parents[id(child)] = parent
    candidates = []
    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        start = getattr(node, "lineno", 0)
        end = getattr(node, "end_lineno", start)
        if start <= int(line_no or -1) <= end:
            class_name = ""
            cur = parents.get(id(node))
            while cur is not None:
                if isinstance(cur, ast.ClassDef):
                    class_name = cur.name
                    break
                cur = parents.get(id(cur))
            candidates.append({
                "name": node.name, "class": class_name, "start": start, "end": end,
                "indent": len((str(source).splitlines()[start-1] if start-1 < len(str(source).splitlines()) else "")) - len((str(source).splitlines()[start-1] if start-1 < len(str(source).splitlines()) else "").lstrip()),
            })
    if not candidates:
        return None
    return sorted(candidates, key=lambda x: (x["end"]-x["start"], -x["start"]))[0]


def _callable_info_by_name(source, method_name, class_name=""):
    try:
        tree = ast.parse(str(source or ""))
    except Exception:
        return None
    for node in tree.body:
        if isinstance(node, ast.ClassDef):
            if class_name and node.name != class_name:
                continue
            for child in node.body:
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and child.name == method_name:
                    line = str(source).splitlines()[child.lineno-1] if child.lineno-1 < len(str(source).splitlines()) else ""
                    return {"name":child.name,"class":node.name,"start":child.lineno,"end":getattr(child,'end_lineno',child.lineno),"indent":len(line)-len(line.lstrip())}
        elif not class_name and isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == method_name:
            line = str(source).splitlines()[node.lineno-1] if node.lineno-1 < len(str(source).splitlines()) else ""
            return {"name":node.name,"class":"","start":node.lineno,"end":getattr(node,'end_lineno',node.lineno),"indent":len(line)-len(line.lstrip())}
    return None


def _extract_replacement_callable(model_text, expected_name):
    raw = _strip_fence(str(model_text or ""))
    # Prefer a directly parseable single function.
    candidates = [raw]
    m = re.search(r"(?ms)^\s*(?:async\s+def|def)\s+" + re.escape(expected_name) + r"\s*\(.*", raw)
    if m:
        candidates.append(raw[m.start():])
    for candidate in candidates:
        try:
            tree = ast.parse(candidate)
        except Exception:
            continue
        funcs = [n for n in tree.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
        if len(funcs) == 1 and funcs[0].name == expected_name:
            try:
                return ast.unparse(funcs[0]).rstrip() + "\n"
            except Exception:
                return candidate.strip() + "\n"
    return ""


def _replace_callable_in_source(source, info, callable_source):
    """Replace exactly one function/method while preserving the rest of the file byte-for-byte-ish."""
    lines = str(source or "").splitlines()
    start = int(info["start"]); end = int(info["end"]); indent = int(info.get("indent") or 0)
    raw_lines = str(callable_source or "").strip("\n").splitlines()
    # ast.unparse returns top-level indentation; restore class/method indentation.
    prefix = " " * indent
    rendered = [prefix + line if line.strip() else "" for line in raw_lines]
    new_lines = lines[:start-1] + rendered + lines[end:]
    out = "\n".join(new_lines)
    if str(source or "").endswith("\n"):
        out += "\n"
    return out


def _generated_test_production_call_for_test_id(work, manifest, test_id):
    """Return (provider_file, class_name, method_name) when a generated test method exercises one provider."""
    test_name = str(test_id or "").split("::")[-1].split(".")[-1]
    root = _python_project_root(work, manifest)
    class_index, _ = _python_local_class_index(work, manifest)
    if not test_name or not class_index:
        return ("", "", "")
    constructor_hints = _local_constructor_parameter_type_hints(work, manifest, class_index)
    for path in root.rglob("test_generated_acceptance.py"):
        try:
            rel = path.relative_to(Path(work)).as_posix()
        except Exception:
            continue
        if not _is_jarvis_generated_acceptance_test(rel):
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue
        types = _collect_simple_instance_types(tree, class_index)
        _apply_constructor_parameter_type_hints(tree, class_index, constructor_hints, types)
        fn = next((n for n in ast.walk(tree) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name==test_name),None)
        if fn is None:
            continue
        calls=[]
        for call in ast.walk(fn):
            if not isinstance(call, ast.Call) or not isinstance(call.func, ast.Attribute):
                continue
            if call.func.attr.startswith("assert"):
                continue
            receiver=_expr_key(call.func.value); cls=types.get(receiver,"")
            if cls and cls in class_index:
                provider=str(class_index[cls].get("file") or "")
                if provider and not _is_jarvis_generated_acceptance_test(provider):
                    calls.append((getattr(call,'lineno',0),provider,cls,call.func.attr))
        providers=list(dict.fromkeys(x[1] for x in calls))
        if len(providers)!=1:
            return ("", "", "")
        # Prefer the last production call in the test method; for assertRaises this is normally the action under test.
        same=[x for x in calls if x[1]==providers[0]]
        if same:
            _,provider,cls,method=sorted(same,key=lambda x:x[0])[-1]
            return provider,cls,method
    return ("", "", "")


def _repair_runtime_callable_for_test_failure(user_request, manifest, work, rel, targeted_failure, problem, progress_callback=None, preferred_method=""):
    """Rewrite only the failing production callable and replay one isolated test before commit."""
    path = Path(work) / rel
    if not path.exists() or path.suffix.lower() not in {".py", ".pyw"}:
        return False
    try:
        current = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return False

    info = None
    if preferred_method:
        info = _callable_info_by_name(current, preferred_method)
    if info is None:
        line = _traceback_line_for_project_file(targeted_failure, rel)
        if line:
            info = _callable_info_for_line(current, line)
    if info is None:
        return False

    current_lines = current.splitlines()
    callable_text = "\n".join(current_lines[info["start"]-1:info["end"]])
    label = (info.get("class") + "." if info.get("class") else "") + info["name"]
    context = _project_context_for_file(work, manifest, rel, max_chars=min(12000, TARGETED_CONTEXT_CHARS))
    prompt = (
        "Repair exactly ONE Python callable that failed a real isolated acceptance test.\n"
        "Return ONLY the complete replacement function/method definition beginning with def/async def.\n"
        "Do not return the class, imports, markdown, explanations, or any other functions.\n"
        "Preserve the callable name and its public signature unless the concrete existing project API requires otherwise.\n"
        "Implement real behavior; no pass/TODO/stub. Jarvis will insert this callable into the unchanged file and replay the exact test before commit.\n\n"
        f"USER REQUEST:\n{user_request}\n\n"
        f"TARGET FILE: {rel}\nTARGET CALLABLE: {label}\n\n"
        f"PROJECT API INDEX:\n{_project_api_index(work)}\n\n"
        f"REAL TEST FAILURE TO FIX:\n{targeted_failure[-9000:]}\n\n"
        f"REPAIR REQUIREMENT:\n{problem}\n\n"
        f"CURRENT CALLABLE:\n{callable_text}\n\n"
        f"RELATED PROJECT CONTEXT:\n{context}\n"
    )
    best_error=""
    for attempt in range(1, max(2, FILE_FULL_REWRITE_ROUNDS)+1):
        ask=prompt
        if best_error:
            ask += f"\nPREVIOUS METHOD CANDIDATE WAS REJECTED:\n{best_error}\nReturn a different implementation.\n"
        ok, raw = _qwen_call(ask, progress_callback, f"Repairing {label} method {attempt}", profile="repair", max_tokens=_optional_positive_limit(QWEN_AUDIT_MAX_TOKENS), thinking=False, strict_output=True)
        if not ok and not raw:
            continue
        replacement=_extract_replacement_callable(raw, info["name"])
        if not replacement:
            best_error="Response did not contain exactly one parseable replacement callable with the required name."
            continue
        candidate=_replace_callable_in_source(current,info,replacement)
        if candidate.strip()==current.strip():
            best_error="Replacement callable is unchanged."
            continue
        tx=_candidate_transaction_error(work,manifest,rel,candidate,user_request=user_request,validation_failure=targeted_failure,target_problems=[problem])
        if tx:
            best_error=tx
            _save_candidate_draft(work,rel,candidate)
            continue
        tmp=path.with_name(path.name+'.jarvis_method_tmp')
        try:
            tmp.write_text(candidate,encoding='utf-8'); tmp.replace(path)
        except Exception:
            try: tmp.unlink(missing_ok=True)
            except Exception: pass
            return False
        _delete_candidate_draft(work,rel)
        _append_project_event(work,'runtime_callable_repaired',f'Committed isolated-test repair for {label}.',file=rel,callable=label)
        return True
    return False

def _repair_real_validation_failure(user_request, manifest, work, failure, progress_callback=None):
    """Repair a real failure using deterministic ownership evidence, replay, then model diagnosis.

    V30 records stable failure signatures and target outcomes. The same failure therefore escalates
    toward provider/dependency owners instead of repeatedly rewriting a caller that merely surfaced it.
    """
    history = _runtime_history_record(work, failure, increment=True)
    repeat_count = int(history.get("count") or 1)
    failed_target_counts = _runtime_failed_target_counts(work, failure)
    provider_targets = _runtime_attribute_provider_targets(work, manifest, failure)
    import_provider_targets = _runtime_import_provider_targets(work, manifest, failure)
    strong_import_targets = [x for x in import_provider_targets if bool(x.get("strong"))]

    if repeat_count >= RUNTIME_REPEAT_ESCALATION:
        _append_project_event(
            work,
            "runtime_failure_escalated",
            f"Real validation failure repeated {repeat_count} times; escalating repair ownership instead of retrying the same caller.",
            failure_signature=_validation_failure_signature(failure),
            failed_targets=failed_target_counts,
            attribute_providers=[x.get("file") for x in provider_targets],
            import_providers=[x.get("file") for x in import_provider_targets],
        )
        _progress(
            progress_callback,
            f"Repeated runtime failure detected ({repeat_count}x) - escalating to provider/root-cause targets.",
            stage="repairing",
        )

    # Cheap, mechanically provable Python framework fix first. Example:
    # module 'tkinter' has no attribute 'Treeview' -> unique owner tkinter.ttk.Treeview.
    # This is generic and only commits after replaying the original failing validator.
    if _deterministic_missing_module_attribute_repair(
        user_request, manifest, work, failure, progress_callback
    ):
        return True

    # ``ImportError: cannot import name X from Y`` points at the consumer in the traceback but at
    # the PROVIDER in the exception text. Restore proven missing module-level exports surgically
    # before any full-file rewrite. The exact failing validator is replayed and non-progress rolls back.
    for target in strong_import_targets:
        if _try_runtime_missing_export_repair(
            user_request, manifest, work, failure, target, progress_callback
        ):
            return True

    low_failure = str(failure or "").lower()

    # V20: split mixed test output before generic test triage. Production tracebacks are stronger
    # evidence than the last assertion printed by an aggregate suite. Repair one independently
    # failing test at a time and replay ONLY that test before committing the candidate.
    test_records = _split_real_test_failures(work, failure)
    if test_records:
        # 1) Concrete production exceptions/errors first.
        for record in test_records:
            deepest = str(record.get("deepest") or "")
            if not deepest or _is_jarvis_generated_acceptance_test(deepest):
                continue
            test_id = str(record.get("test_id") or "")
            targeted_failure = (
                f"JARVIS_TARGET_TEST_ID: {test_id}\n"
                + str(record.get("text") or "")
            )
            owner_target = ""
            owner_problem = ""
            if provider_targets:
                owner_target = str(provider_targets[0].get("file") or "")
                owner_problem = str(provider_targets[0].get("problem") or "")
            elif strong_import_targets:
                owner_target = str(strong_import_targets[0].get("file") or "")
                owner_problem = str(strong_import_targets[0].get("problem") or "")
            target_file = owner_target or deepest
            problem = (
                "REAL TEST EXPOSED PRODUCTION DEFECT: this independently isolated test failed in production. "
                f"Traceback frame={deepest}; deterministic owner target={target_file}. Repair PRODUCTION, not the "
                "generated test. When owner evidence differs from the traceback caller, the provider/root-cause "
                "target wins. Preserve the existing public API unless the concrete project contract requires a "
                "coordinated change. The candidate will be replayed against this exact single test before commit.\n"
                + (f"OWNER CONTRACT: {owner_problem}\n" if owner_problem else "")
                + f"\nTEST ID: {test_id}\nFAILURE:\n{str(record.get('text') or '')[-8000:]}"
            )
            repaired = _repair_runtime_callable_for_test_failure(
                user_request, manifest, work, target_file, targeted_failure, problem, progress_callback
            ) or _repair_file_for_issues(
                user_request, manifest, work, target_file, [problem], progress_callback,
                validation_failure=targeted_failure,
            )
            _record_runtime_target_outcome(work, failure, target_file, repaired)
            if repaired:
                _append_project_event(
                    work, "production_test_failure_repaired",
                    "Repaired a production defect exposed by an independently isolated generated test.",
                    file=target_file, traceback_file=deepest, test_id=test_id,
                )
                return True

        # 2) Assertion-only generated-test failures have no production traceback. If the test method
        # concretely exercises one unique local production provider, route the behavior defect there
        # and keep assertion semantics immutable.
        for record in test_records:
            deepest = str(record.get("deepest") or "")
            if record.get("status") != "FAIL" or not _is_jarvis_generated_acceptance_test(deepest):
                continue
            test_id = str(record.get("test_id") or "")
            provider, provider_class, provider_method = _generated_test_production_call_for_test_id(work, manifest, test_id)
            if not provider:
                continue
            targeted_failure = (
                f"JARVIS_TARGET_TEST_ID: {test_id}\n"
                + str(record.get("text") or "")
            )
            problem = (
                "GENERATED ACCEPTANCE TEST ASSERTION EXPOSED PRODUCTION BEHAVIOR DEFECT: deterministic "
                f"call analysis shows test {test_id} exercises local provider {provider}. The assertion "
                "itself is read-only during runtime triage. Repair production behavior so this exact isolated "
                "test passes; do not change the generated test expectation.\n\n"
                f"FAILURE:\n{str(record.get('text') or '')[-8000:]}"
            )
            if _repair_runtime_callable_for_test_failure(
                user_request, manifest, work, provider, targeted_failure, problem, progress_callback,
                preferred_method=provider_method,
            ) or _repair_file_for_issues(
                user_request, manifest, work, provider, [problem], progress_callback,
                validation_failure=targeted_failure,
            ):
                _append_project_event(
                    work, "production_assertion_failure_repaired",
                    "Repaired production behavior exposed by a generated acceptance assertion.",
                    file=provider, test_id=test_id,
                )
                return True

    # Missing promised tests are deterministic: create the acceptance-test target directly instead
    # of spending a diagnosis call asking the model what file to create.
    generated_test_runtime = _generated_test_runtime_authoring_target(work, failure)
    if generated_test_runtime:
        problem = (
            "GENERATED TEST RUNTIME AUTHORING DEFECT: The real test runner crashed inside this Jarvis-generated "
            "acceptance test before it could validly judge production behavior. Rewrite ONLY the test to use "
            "imports, constructors, object wiring, and APIs that actually exist in PROJECT API INDEX. Do not "
            "change production code merely to satisfy the generated test.\n\nREAL TEST FAILURE:\n"
            + str(failure or "")[-8000:]
        )
        if _repair_file_for_issues(
            user_request,
            manifest,
            work,
            generated_test_runtime,
            [problem],
            progress_callback,
            validation_failure=failure,
        ):
            _append_project_event(
                work,
                "generated_test_runtime_repaired",
                "Repaired a generated acceptance-test authoring crash without changing production code.",
                file=generated_test_runtime,
            )
            return True

    # If a generated acceptance test reaches an assertion/behavior failure, triage the TEST first.
    # The candidate may correct invalid fixture/setup assumptions, but the transaction gate forbids
    # deleting test methods, weakening assertions, or adding skips. If no honest test-only repair
    # improves the replayed suite, fall through and let production diagnosis handle the failure.
    generated_test_failure = _generated_test_failure_target(work, failure)
    if generated_test_failure:
        problem = (
            "GENERATED TEST FAILURE TRIAGE: A Jarvis-generated acceptance test is the deepest failing "
            "project frame. First verify that the TEST setup and assumptions match the real production "
            "API/object lifecycle. Repair ONLY invalid test setup/fixtures/inputs if necessary. Preserve "
            "all test methods and assertions; do not add skips and do not weaken expected behavior. "
            "In particular, isolate persistent storage per test and do not pre-seed the same unique "
            "identifier that the test later imports/adds unless testing duplicate rejection. If the test "
            "is already valid, leave its behavioral expectation intact so production diagnosis can run.\n\n"
            "REAL TEST FAILURE:\n" + str(failure or "")[-8000:]
        )
        if _repair_file_for_issues(
            user_request,
            manifest,
            work,
            generated_test_failure,
            [problem],
            progress_callback,
            validation_failure=failure,
        ):
            _append_project_event(
                work,
                "generated_test_failure_triaged",
                "Repaired invalid generated-test setup/assumptions without weakening coverage.",
                file=generated_test_failure,
            )
            return True

    if (
        "no test*.py files were discovered" in low_failure
        or "automated tests were requested/planned" in low_failure
    ):
        # Tests explicitly requested by the user/project are a hard requirement, but the generated test
        # remains PROVISIONAL until its own API/signature/preflight transaction passes. Never append a
        # missing file to the manifest first; that was the V20 deadlock.
        item = _generated_acceptance_manifest_item()
        test_rel = item['path']
        _drop_generated_test_manifest_item(manifest, test_rel)
        _delete_candidate_draft(work, test_rel)
        file_ok, wrote = _generate_planned_file(
            user_request, manifest, work, item, progress_callback
        )
        if file_ok and wrote and (Path(work) / wrote).exists():
            _commit_generated_test_manifest_item(manifest, item)
            _append_project_event(
                work, 'required_generated_test_committed',
                'Committed a required generated acceptance suite only after deterministic preflight passed.',
                file=wrote,
            )
            return True
        _drop_generated_test_manifest_item(manifest, test_rel)
        _delete_candidate_draft(work, test_rel)
        _append_project_event(
            work, 'required_generated_test_generation_failed',
            'Required generated acceptance test failed preflight; it was not left behind as a missing manifest obligation.',
            file=test_rel,
        )
        return False

    qwen_repairs, creates = _diagnose_runtime_failure(
        user_request, manifest, work, failure, progress_callback
    )
    traceback_targets = []
    if (
        "python real startup smoke test failed" in low_failure
        or "python import/startup dependency smoke test failed" in low_failure
        or "python import smoke test timed out" in low_failure
    ):
        traceback_targets = _traceback_project_files(work, failure)

    missing_mod = re.search(r"ModuleNotFoundError:\s*No module named ['\"]([^'\"]+)['\"]", str(failure))
    if missing_mod:
        module = missing_mod.group(1)
        root = _python_project_root(work, manifest)
        candidate = root / (module.replace('.', os.sep) + '.py')
        package_init = root / module.replace('.', os.sep) / '__init__.py'
        if not candidate.exists() and not package_init.exists():
            try:
                rel = candidate.relative_to(Path(work)).as_posix()
                if all(str(x.get('path') or '') != rel for x in creates):
                    creates.append({
                        'path': rel,
                        'purpose': f'Local module required by runtime import: {module}',
                        'exports': [],
                    })
            except Exception:
                pass


    for item in creates:
        rel = str(item.get('path') or '')
        if not rel:
            continue
        if all(str(x.get('path') or '') != rel for x in manifest.get('files') or []):
            manifest.setdefault('files', []).append(item)
        _generate_planned_file(user_request, manifest, work, item, progress_callback)

    # Build a root-cause-first target pool. Provider ownership outranks traceback location for
    # missing class members and missing imported symbols. On repeated failures, deterministic local
    # dependency providers are added before model guesses/caller frames.
    runtime_problem_by_file = {}
    repairs = []

    def add_target(rel, problem=""):
        rel = str(rel or "")
        if not rel:
            return
        if rel not in repairs:
            repairs.append(rel)
        if problem:
            runtime_problem_by_file.setdefault(rel, [])
            if problem not in runtime_problem_by_file[rel]:
                runtime_problem_by_file[rel].append(problem)

    for item in provider_targets:
        add_target(item.get("file"), item.get("problem"))
    for item in import_provider_targets:
        add_target(item.get("file"), item.get("problem"))

    dep_grouped = _route_dependency_issues(work, manifest, _local_import_api_issues(work, manifest))
    if repeat_count >= RUNTIME_REPEAT_ESCALATION or not repairs:
        for rel, problems in dep_grouped.items():
            for problem in problems or [""]:
                add_target(rel, problem)

    for rel in qwen_repairs:
        add_target(rel)
    for rel in traceback_targets[:max(RUNTIME_TRACEBACK_PRIMARY_TARGETS, 2 if repeat_count >= RUNTIME_REPEAT_ESCALATION else 1)]:
        add_target(rel)

    if not repairs:
        for rel in _existing_real_source_files(work):
            if Path(rel).suffix.lower() in {'.py', '.pyw'}:
                add_target(rel)
                break

    # If this exact failure has already rejected the same target repeatedly, try lower-failure
    # alternatives first. Strong provider ownership is still retained in the pool; it is not discarded.
    if repeat_count >= RUNTIME_REPEAT_ESCALATION and len(repairs) > 1:
        order = {rel: idx for idx, rel in enumerate(repairs)}
        repairs.sort(key=lambda rel: (int(failed_target_counts.get(rel) or 0), order[rel]))
        healthier = [rel for rel in repairs if int(failed_target_counts.get(rel) or 0) < RUNTIME_TARGET_FAILURE_LIMIT]
        if healthier:
            repairs = healthier + [rel for rel in repairs if rel not in healthier]

    attempted = 0
    for rel in repairs[:PROJECT_RUNTIME_REPAIR_TARGETS]:
        attempted += 1
        concrete_problems = list(runtime_problem_by_file.get(rel, []))
        if repeat_count >= RUNTIME_REPEAT_ESCALATION:
            concrete_problems.append(
                f"REPEATED FAILURE ESCALATION: this exact validation signature has occurred {repeat_count} times. "
                f"Target {rel!r} has already failed to fix it {int(failed_target_counts.get(rel) or 0)} time(s). "
                "Fix the root cause shown by provider/dependency evidence; do not make cosmetic caller edits."
            )
        concrete_problems.append(failure)
        repaired = _repair_file_for_issues(
            user_request, manifest, work, rel, concrete_problems, progress_callback,
            validation_failure=failure
        )
        _record_runtime_target_outcome(work, failure, rel, repaired)
        if repaired:
            # Runtime repair candidates are replay-gated. Once one advances the validator, immediately
            # stop using the stale failure as justification for further edits; the next acceptance pass
            # will obtain fresh evidence for the next defect.
            return True

    if attempted and repeat_count >= RUNTIME_REPEAT_ESCALATION:
        _append_project_event(
            work,
            "runtime_escalation_exhausted",
            "Root-cause escalation exhausted its current repair targets without advancing the validator.",
            failure_signature=_validation_failure_signature(failure),
            targets=repairs[:PROJECT_RUNTIME_REPAIR_TARGETS],
        )
    return bool(creates)




def _test_proves_self_attr_non_none(test, attr_name):
    """Conservatively recognize guards that prove `self.<attr_name>` is usable in an if-body."""
    def is_target(node):
        return (
            isinstance(node, ast.Attribute)
            and isinstance(node.value, ast.Name)
            and node.value.id == "self"
            and node.attr == attr_name
        )

    if is_target(test):
        return True

    if isinstance(test, ast.Compare) and len(test.ops) == 1 and len(test.comparators) == 1:
        left = test.left
        right = test.comparators[0]
        op = test.ops[0]
        left_none = isinstance(left, ast.Constant) and left.value is None
        right_none = isinstance(right, ast.Constant) and right.value is None
        if isinstance(op, ast.IsNot):
            if is_target(left) and right_none:
                return True
            if left_none and is_target(right):
                return True

    if isinstance(test, ast.BoolOp) and isinstance(test.op, ast.And):
        return any(_test_proves_self_attr_non_none(value, attr_name) for value in test.values)

    return False


def _node_is_in_if_body(node, if_node, parents):
    """Return True only when node is inside the guarded `if` body, not its else branch."""
    cur = node
    while cur is not None and cur is not if_node:
        parent = parents.get(id(cur))
        if parent is if_node:
            for top in if_node.body:
                if cur is top:
                    return True
            return False
        cur = parent
    return False


def _definite_none_member_call_issues(work, manifest):
    """Catch unguarded calls through instance attributes that are initialized to None and never set.

    This is intentionally conservative. It only treats an attribute as definitely-None when:
      * the class assigns `self.attr = None` at least once,
      * every assignment to that same attribute anywhere in the class is also None,
      * the failing use is a direct `self.attr.some_member(...)` call,
      * no enclosing if-body proves `self.attr` is non-None.

    This catches broken compatibility wrappers such as:
        self.category_filter = None
        ...
        def pack(...):
            self.category_filter.pack(...)
    without guessing about ordinary optional attributes that are assigned a real value elsewhere.
    """
    root = _python_project_root(work, manifest)
    issues = []

    for path in sorted(root.rglob("*.py")):
        if not path.is_file():
            continue
        try:
            rel_root = path.relative_to(root)
            rel_work = path.relative_to(Path(work)).as_posix()
        except Exception:
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel_root.parts):
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue

        for class_node in [n for n in tree.body if isinstance(n, ast.ClassDef)]:
            assignments = {}
            for node in ast.walk(class_node):
                if not isinstance(node, (ast.Assign, ast.AnnAssign)):
                    continue
                value = node.value
                targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                for target in targets:
                    if (
                        isinstance(target, ast.Attribute)
                        and isinstance(target.value, ast.Name)
                        and target.value.id == "self"
                    ):
                        assignments.setdefault(target.attr, []).append(value)

            definitely_none = {
                name
                for name, values in assignments.items()
                if values
                and all(isinstance(value, ast.Constant) and value.value is None for value in values)
            }
            if not definitely_none:
                continue

            parents = {}
            for parent in ast.walk(class_node):
                for child in ast.iter_child_nodes(parent):
                    parents[id(child)] = parent

            for call in [n for n in ast.walk(class_node) if isinstance(n, ast.Call)]:
                func = call.func
                if not isinstance(func, ast.Attribute):
                    continue
                receiver = func.value
                if not (
                    isinstance(receiver, ast.Attribute)
                    and isinstance(receiver.value, ast.Name)
                    and receiver.value.id == "self"
                    and receiver.attr in definitely_none
                ):
                    continue

                attr_name = receiver.attr
                guarded = False
                cur = call
                while cur is not None:
                    parent = parents.get(id(cur))
                    if isinstance(parent, ast.If):
                        if (
                            _node_is_in_if_body(call, parent, parents)
                            and _test_proves_self_attr_non_none(parent.test, attr_name)
                        ):
                            guarded = True
                            break
                    cur = parent
                if guarded:
                    continue

                issues.append({
                    "file": rel_work,
                    "class": class_node.name,
                    "attribute": attr_name,
                    "member": func.attr,
                    "line": getattr(call, "lineno", "?"),
                    "problem": (
                        f"DEFINITE-NONE MEMBER CALL: {class_node.name}.{attr_name} is assigned only None "
                        f"inside this class, but code unconditionally calls self.{attr_name}.{func.attr}(...) "
                        f"at line {getattr(call, 'lineno', '?')}. Assign a real object before use or remove/"
                        "reconcile the invalid wrapper/call."
                    ),
                })

    return issues


def _local_fixed_constructor_arities(work, manifest):
    """Unique local class -> exact positional constructor arity when statically knowable."""
    class_index, _ = _python_local_class_index(work, manifest)
    out = {}
    for class_name, info in class_index.items():
        node = info.get("node")
        init = next(
            (
                child for child in getattr(node, "body", []) or []
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and child.name == "__init__"
            ),
            None,
        )
        if init is None:
            out[class_name] = 0
            continue
        if init.args.vararg is not None:
            continue
        positional = list(getattr(init.args, "posonlyargs", []) or []) + list(init.args.args or [])
        if positional and positional[0].arg in {"self", "cls"}:
            positional = positional[1:]
        defaults = list(init.args.defaults or [])
        required = len(positional) - len(defaults)
        if required == len(positional):
            out[class_name] = len(positional)
    return out


def _sql_create_table_columns(source):
    """Extract simple locally-declared SQL table column names from CREATE TABLE strings."""
    tables = {}
    for match in re.finditer(
        r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\((.*?)\)",
        str(source or ""),
        flags=re.I | re.S,
    ):
        table = match.group(1)
        body = match.group(2)
        columns = []
        for piece in body.split(","):
            item = re.sub(r"\s+", " ", piece.strip())
            if not item:
                continue
            first = item.split(" ", 1)[0].strip('`"[]')
            if first.upper() in {"PRIMARY", "FOREIGN", "UNIQUE", "CHECK", "CONSTRAINT"}:
                continue
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", first):
                columns.append(first)
        if columns:
            tables[table.lower()] = columns
    return tables


def _sqlite_select_star_constructor_issues(work, manifest):
    """Catch a precise SQLite/data-model mismatch hidden by an empty database.

    Pattern required before reporting:
      * this module declares a concrete CREATE TABLE schema,
      * one function executes SELECT * FROM that table,
      * that same function directly expands each fetched row into a unique local class constructor,
      * the table column count and the constructor's exact positional arity disagree.

    This prevents an empty-state GUI smoke test from hiding a guaranteed crash once the first row exists.
    """
    root = _python_project_root(work, manifest)
    arities = _local_fixed_constructor_arities(work, manifest)
    if not arities:
        return []

    issues = []
    for path in sorted(root.rglob("*.py")):
        if not path.is_file():
            continue
        try:
            rel_root = path.relative_to(root)
            rel_work = path.relative_to(Path(work)).as_posix()
        except Exception:
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel_root.parts):
            continue
        try:
            source = path.read_text(encoding="utf-8", errors="replace")
            tree = ast.parse(source)
        except Exception:
            continue

        tables = _sql_create_table_columns(source)
        if not tables:
            continue

        for fn in [
            n for n in ast.walk(tree)
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
        ]:
            selected_tables = set()
            for call in [n for n in ast.walk(fn) if isinstance(n, ast.Call)]:
                if not (
                    isinstance(call.func, ast.Attribute)
                    and call.func.attr == "execute"
                    and call.args
                    and isinstance(call.args[0], ast.Constant)
                    and isinstance(call.args[0].value, str)
                ):
                    continue
                sql = call.args[0].value
                for match in re.finditer(
                    r"\bSELECT\s+\*\s+FROM\s+([A-Za-z_][A-Za-z0-9_]*)\b",
                    sql,
                    flags=re.I,
                ):
                    selected_tables.add(match.group(1).lower())

            if not selected_tables:
                continue

            for comp in [n for n in ast.walk(fn) if isinstance(n, ast.ListComp)]:
                if len(comp.generators) != 1:
                    continue
                gen = comp.generators[0]
                if not isinstance(gen.target, ast.Name):
                    continue
                row_name = gen.target.id
                if not (
                    isinstance(gen.iter, ast.Call)
                    and isinstance(gen.iter.func, ast.Attribute)
                    and gen.iter.func.attr == "fetchall"
                ):
                    continue
                elt = comp.elt
                if not (
                    isinstance(elt, ast.Call)
                    and isinstance(elt.func, ast.Name)
                    and elt.func.id in arities
                    and len(elt.args) == 1
                    and isinstance(elt.args[0], ast.Starred)
                    and isinstance(elt.args[0].value, ast.Name)
                    and elt.args[0].value.id == row_name
                ):
                    continue

                class_name = elt.func.id
                ctor_arity = arities[class_name]
                for table in sorted(selected_tables):
                    columns = tables.get(table)
                    if not columns or len(columns) == ctor_arity:
                        continue
                    issues.append({
                        "file": rel_work,
                        "class": class_name,
                        "table": table,
                        "line": getattr(elt, "lineno", "?"),
                        "problem": (
                            f"SQL ROW/MODEL CONTRACT: SELECT * FROM {table} returns {len(columns)} declared "
                            f"table columns ({', '.join(columns)}), but {class_name} accepts exactly "
                            f"{ctor_arity} positional constructor values. Direct {class_name}(*row) at line "
                            f"{getattr(elt, 'lineno', '?')} is guaranteed to fail once rows exist. Select/map "
                            "only model fields or explicitly translate database rows."
                        ),
                    })

    return issues



def _local_constructor_field_names(work, manifest):
    """Return exact local constructor positional field names for classes safe to map from SQL rows.

    A class is eligible only when __init__ has a fixed positional signature (no *args), because a
    deterministic SQL repair must know the exact row order it is constructing.
    """
    root = _python_project_root(work, manifest)
    out = {}
    for path in sorted(root.rglob("*.py")):
        if not path.is_file():
            continue
        try:
            rel = path.relative_to(root)
        except Exception:
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel.parts):
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue
        for node in tree.body:
            if not isinstance(node, ast.ClassDef):
                continue
            init = next(
                (
                    child for child in node.body
                    if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef))
                    and child.name == "__init__"
                ),
                None,
            )
            if init is None or init.args.vararg is not None:
                continue
            positional = list(init.args.posonlyargs) + list(init.args.args)
            if positional and positional[0].arg in {"self", "cls"}:
                positional = positional[1:]
            # **kwargs does not change the number/order of positional row values, but a positional
            # variadic parameter would, so only *args makes this mapping unsafe.
            names = [arg.arg for arg in positional]
            if names and all(re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", x) for x in names):
                out[node.name] = names
    return out


def _sql_row_model_repair_candidate(work, manifest, rel):
    """Build a surgical candidate that replaces only proven SELECT * -> Model(*row) mappings.

    The existing deterministic checker already proves:
      * a CREATE TABLE schema is present,
      * the function SELECTs * from that table,
      * that same function expands a fetched row directly into a fixed local constructor,
      * row width and constructor width disagree.

    This helper derives the constructor field order and rewrites only the SELECT * expressions in
    those proven functions. It never changes provider method signatures or unrelated SQL.
    """
    path = Path(work) / rel
    if not path.exists() or path.suffix.lower() not in {".py", ".pyw"}:
        return "", []

    issues = [
        x for x in _sqlite_select_star_constructor_issues(work, manifest)
        if str(x.get("file") or "") == str(rel)
    ]
    if not issues:
        return "", []

    try:
        source = path.read_text(encoding="utf-8", errors="replace")
        tree = ast.parse(source)
    except Exception:
        return "", []

    ctor_fields = _local_constructor_field_names(work, manifest)
    tables = _sql_create_table_columns(source)
    if not ctor_fields or not tables:
        return "", []

    # Resolve each reported constructor line to its containing function and remember the exact
    # (table -> model field list) mapping that is safe inside that function.
    targets = {}
    target_problems = []
    for issue in issues:
        class_name = str(issue.get("class") or "")
        table = str(issue.get("table") or "").lower()
        try:
            issue_line = int(issue.get("line"))
        except Exception:
            continue
        fields = list(ctor_fields.get(class_name) or [])
        table_columns = list(tables.get(table) or [])
        if not fields or not table_columns:
            continue
        # Every constructor field must be a declared table column. Otherwise field-name mapping is
        # ambiguous and the deterministic path must decline so the normal model repair can handle it.
        if any(field.lower() not in {c.lower() for c in table_columns} for field in fields):
            continue

        owner = None
        for fn in [
            n for n in ast.walk(tree)
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
        ]:
            end_line = getattr(fn, "end_lineno", fn.lineno)
            if fn.lineno <= issue_line <= end_line:
                if owner is None or fn.lineno >= owner.lineno:
                    owner = fn
        if owner is None:
            continue

        targets.setdefault(owner.name, {})[table] = fields
        target_problems.append(str(issue.get("problem") or ""))

    if not targets:
        return "", []

    class SqlStarRewriter(ast.NodeTransformer):
        def __init__(self):
            self.function_stack = []
            self.replacements = 0

        def visit_FunctionDef(self, node):
            self.function_stack.append(node.name)
            node = self.generic_visit(node)
            self.function_stack.pop()
            return node

        def visit_AsyncFunctionDef(self, node):
            self.function_stack.append(node.name)
            node = self.generic_visit(node)
            self.function_stack.pop()
            return node

        def visit_Call(self, node):
            node = self.generic_visit(node)
            if not self.function_stack:
                return node
            fn_name = self.function_stack[-1]
            mapping = targets.get(fn_name) or {}
            if not mapping:
                return node
            if not (
                isinstance(node.func, ast.Attribute)
                and node.func.attr == "execute"
                and node.args
                and isinstance(node.args[0], ast.Constant)
                and isinstance(node.args[0].value, str)
            ):
                return node

            sql = node.args[0].value
            updated = sql
            for table, fields in mapping.items():
                pattern = re.compile(
                    r"\bSELECT\s+\*\s+FROM\s+" + re.escape(table) + r"\b",
                    flags=re.I,
                )
                replacement = "SELECT " + ", ".join(fields) + " FROM " + table
                updated, count = pattern.subn(replacement, updated)
                self.replacements += count
            if updated != sql:
                node.args[0] = ast.copy_location(ast.Constant(value=updated), node.args[0])
            return node

    transformer = SqlStarRewriter()
    new_tree = transformer.visit(tree)
    if transformer.replacements <= 0:
        return "", []

    ast.fix_missing_locations(new_tree)
    try:
        candidate = ast.unparse(new_tree).rstrip() + "\n"
        compile(candidate, str(path), "exec")
    except Exception:
        return "", []
    if candidate.strip() == source.strip():
        return "", []
    return candidate, target_problems


def _try_deterministic_sql_row_model_repair(
    user_request, manifest, work, rel, progress_callback=None
):
    """Repair proven SELECT * / fixed-constructor row-width mismatches without a model rewrite."""
    candidate, problems = _sql_row_model_repair_candidate(work, manifest, rel)
    if not candidate or not problems:
        return False

    tx_error = _candidate_transaction_error(
        work,
        manifest,
        rel,
        candidate,
        user_request=user_request,
        target_problems=problems,
    )
    if tx_error:
        _save_candidate_draft(work, rel, candidate)
        _append_project_event(
            work,
            "deterministic_sql_row_model_repair_rejected",
            f"Rejected deterministic SQL row/model repair for {rel}.",
            file=rel,
            reason=tx_error,
        )
        return False

    path = Path(work) / rel
    tmp = path.with_name(path.name + ".jarvis_tmp")
    try:
        tmp.write_text(candidate, encoding="utf-8")
        tmp.replace(path)
    except Exception:
        try:
            tmp.unlink(missing_ok=True)
        except Exception:
            pass
        return False

    _delete_candidate_draft(work, rel)
    _append_project_event(
        work,
        "deterministic_sql_row_model_repair",
        f"Replaced proven SELECT * row mappings with exact constructor-field SELECTs in {rel}.",
        file=rel,
        repaired_contracts=len(problems),
    )
    _progress(
        progress_callback,
        f"Repaired SQL row/model mapping in {rel} deterministically.",
        stage="repairing",
    )
    return True


def _generated_test_undefined_name_issues(work, manifest):
    """Detect definitely unresolved names in Jarvis-generated acceptance tests.

    Python compilation does not catch a missing import such as `CSVImporter()` or `csv.writer`.
    `symtable` lets Jarvis distinguish true globals from locals/parameters/imports without executing
    the test. Generated tests are non-authoritative, so every issue is assigned to the test file.
    """
    issues = []
    root = _python_project_root(work, manifest)
    builtin_names = set(dir(builtins))
    implicit = {
        "__name__", "__file__", "__package__", "__loader__", "__spec__", "__builtins__",
        "True", "False", "None",
    }

    for path in sorted(root.rglob("*.py")):
        if not path.is_file():
            continue
        try:
            rel = path.relative_to(Path(work)).as_posix()
        except Exception:
            continue
        if not _is_jarvis_generated_acceptance_test(rel):
            continue
        try:
            source = path.read_text(encoding="utf-8", errors="replace")
            tree = ast.parse(source)
            table = symtable.symtable(source, str(path), "exec")
        except Exception:
            continue

        module_defs = set()
        for symbol in table.get_symbols():
            try:
                if (
                    symbol.is_imported()
                    or symbol.is_assigned()
                    or symbol.is_parameter()
                    or symbol.is_namespace()
                ):
                    module_defs.add(symbol.get_name())
            except Exception:
                continue

        first_load_line = {}
        for node in ast.walk(tree):
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
                first_load_line.setdefault(node.id, getattr(node, "lineno", "?"))

        missing = set()

        def walk_table(tbl):
            for symbol in tbl.get_symbols():
                name = symbol.get_name()
                if name in builtin_names or name in implicit or name in module_defs:
                    continue
                try:
                    if symbol.is_referenced() and symbol.is_global() and not symbol.is_imported():
                        missing.add(name)
                except Exception:
                    pass
            for child in tbl.get_children():
                walk_table(child)

        walk_table(table)

        for name in sorted(missing):
            line = first_load_line.get(name, "?")
            issues.append({
                "file": rel,
                "kind": "generated_test_undefined_name",
                "name": name,
                "problem": (
                    f"GENERATED TEST UNDEFINED NAME: Jarvis-generated test {rel} references name "
                    f"{name!r} at line {line}, but that name is not imported, assigned, declared, or "
                    "provided by Python builtins. Rewrite the TEST to import/use the real dependency; "
                    "do not modify production code to satisfy an undefined test symbol."
                ),
            })
    return issues


def _ast_signature(node, drop_bound_first=False):
    """Return a conservative callable signature description for an ast FunctionDef."""
    if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return None
    args = node.args
    positional_nodes = list(getattr(args, "posonlyargs", []) or []) + list(args.args or [])
    positional = [x.arg for x in positional_nodes]
    defaults = list(args.defaults or [])
    required_count = max(0, len(positional) - len(defaults))

    if drop_bound_first and positional:
        positional = positional[1:]
        required_count = max(0, required_count - 1)

    required_positional = positional[:required_count]
    kwonly = [x.arg for x in (args.kwonlyargs or [])]
    required_kwonly = [
        x.arg
        for x, default in zip(args.kwonlyargs or [], args.kw_defaults or [])
        if default is None
    ]
    return {
        "positional": positional,
        "required_positional": required_positional,
        "kwonly": kwonly,
        "required_kwonly": required_kwonly,
        "vararg": bool(args.vararg),
        "varkw": bool(args.kwarg),
    }


def _python_local_callable_signature_index(work, manifest):
    """Class constructor/method signatures for project-local Python classes."""
    root = _python_project_root(work, manifest)
    index = {}
    for path in sorted(root.rglob("*.py")):
        if not path.is_file():
            continue
        try:
            rel_root = path.relative_to(root)
            rel = path.relative_to(Path(work)).as_posix()
        except Exception:
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel_root.parts):
            continue
        if _is_jarvis_generated_acceptance_test(rel):
            # A generated test must never become the authority for production signatures.
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue

        for cls in [x for x in tree.body if isinstance(x, ast.ClassDef)]:
            methods = {}
            init_sig = {
                "positional": [],
                "required_positional": [],
                "kwonly": [],
                "required_kwonly": [],
                "vararg": False,
                "varkw": False,
            }
            for child in cls.body:
                if not isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    continue
                decorators = {
                    (d.id if isinstance(d, ast.Name) else d.attr if isinstance(d, ast.Attribute) else "")
                    for d in child.decorator_list
                }
                bound = "staticmethod" not in decorators
                sig = _ast_signature(child, drop_bound_first=bound)
                if sig is None:
                    continue
                methods[child.name] = sig
                if child.name == "__init__":
                    init_sig = sig

            index[cls.name] = {
                "file": rel,
                "constructor": init_sig,
                "methods": methods,
            }
    return index


def _signature_call_problem(signature, call, display_name):
    """Return a deterministic call/signature mismatch, or empty string if compatible/unknown."""
    if not signature or not isinstance(call, ast.Call):
        return ""
    # Star expansion makes static arity unknowable; defer it to runtime.
    if any(isinstance(arg, ast.Starred) for arg in call.args):
        return ""
    if any(kw.arg is None for kw in call.keywords):
        return ""

    positional = list(signature.get("positional") or [])
    required_positional = list(signature.get("required_positional") or [])
    kwonly = set(signature.get("kwonly") or [])
    required_kwonly = set(signature.get("required_kwonly") or [])
    has_vararg = bool(signature.get("vararg"))
    has_varkw = bool(signature.get("varkw"))

    supplied_pos = len(call.args)
    supplied_kw = [kw.arg for kw in call.keywords if kw.arg]
    supplied_kw_set = set(supplied_kw)

    if not has_vararg and supplied_pos > len(positional):
        return (
            f"{display_name} accepts at most {len(positional)} positional argument(s), "
            f"but this call supplies {supplied_pos}"
        )

    positional_filled = set(positional[:min(supplied_pos, len(positional))])
    duplicate = sorted(positional_filled & supplied_kw_set)
    if duplicate:
        return f"{display_name} receives duplicate value(s) for {', '.join(duplicate)}"

    allowed_keywords = set(positional) | kwonly
    unexpected = sorted(x for x in supplied_kw_set if x not in allowed_keywords)
    if unexpected and not has_varkw:
        return f"{display_name} does not accept keyword argument(s): {', '.join(unexpected)}"

    missing = [
        name for name in required_positional
        if name not in positional_filled and name not in supplied_kw_set
    ]
    missing += sorted(required_kwonly - supplied_kw_set)
    if missing:
        return f"{display_name} is missing required argument(s): {', '.join(missing)}"
    return ""


def _generated_test_contract_snapshot(work, manifest):
    """Machine-readable production contract for the small local model that authors Jarvis tests."""
    signatures = _python_local_callable_signature_index(work, manifest)
    class_index, _ = _python_local_class_index(work, manifest)
    out = {}
    for class_name, siginfo in sorted(signatures.items()):
        cinfo = class_index.get(class_name) or {}
        attrs = sorted(str(x) for x in (cinfo.get('instance_attrs') or []) if str(x) and not str(x).startswith('_'))
        methods = {}
        for method, sig in sorted((siginfo.get('methods') or {}).items()):
            if method.startswith('_') and method != '__init__':
                continue
            methods[method] = sig
        out[class_name] = {
            'file': siginfo.get('file'),
            'constructor': siginfo.get('constructor') or {},
            'instance_attributes': attrs,
            'methods': methods,
        }
    return out


def _python_local_call_signature_issues(work, manifest):
    """Detect provable constructor/method arity mismatches against local production classes.

    This catches errors Python compilation cannot see, e.g. `Database(":memory:")` when
    `Database.__init__` only accepts `self`, and production calls such as `db.update_item(item)`
    when the provider requires `(sku, updated_data)`.
    """
    issues = []
    root = _python_project_root(work, manifest)
    class_index, _ = _python_local_class_index(work, manifest)
    signatures = _python_local_callable_signature_index(work, manifest)
    if not class_index or not signatures:
        return issues
    constructor_hints = _local_constructor_parameter_type_hints(work, manifest, class_index)

    for path in sorted(root.rglob("*.py")):
        if not path.is_file():
            continue
        try:
            rel_root = path.relative_to(root)
            consumer_rel = path.relative_to(Path(work)).as_posix()
        except Exception:
            continue
        if any(part in _ANALYSIS_IGNORE_DIRS for part in rel_root.parts):
            continue
        try:
            source = path.read_text(encoding="utf-8", errors="replace")
            tree = ast.parse(source)
        except Exception:
            continue

        types = _collect_simple_instance_types(tree, class_index)
        _apply_constructor_parameter_type_hints(tree, class_index, constructor_hints, types)
        generated_test = _is_jarvis_generated_acceptance_test(consumer_rel)

        for call in [n for n in ast.walk(tree) if isinstance(n, ast.Call)]:
            sig = None
            display = ""
            provider_file = ""

            # Direct local class construction.
            if isinstance(call.func, ast.Name) and call.func.id in signatures:
                cls_name = call.func.id
                info = signatures[cls_name]
                sig = info.get("constructor")
                display = f"{cls_name}.__init__"
                provider_file = str(info.get("file") or "")
            elif isinstance(call.func, ast.Attribute):
                receiver = _expr_key(call.func.value)
                cls_name = types.get(receiver, "")
                if cls_name and cls_name in signatures:
                    info = signatures[cls_name]
                    method_sig = (info.get("methods") or {}).get(call.func.attr)
                    if method_sig is not None:
                        sig = method_sig
                        display = f"{cls_name}.{call.func.attr}"
                        provider_file = str(info.get("file") or "")

            if sig is None:
                continue

            problem = _signature_call_problem(sig, call, display)
            if not problem:
                continue
            line = getattr(call, "lineno", "?")
            try:
                call_text = ast.unparse(call)
            except Exception:
                call_text = display + "(...)"

            if generated_test:
                prefix = "GENERATED TEST CALL SIGNATURE"
                explanation = (
                    "Generated tests are non-authoritative. Rewrite the TEST to call the real production "
                    "constructor/method signature; do not change production merely to satisfy the test."
                )
                kind = "generated_test_signature"
            else:
                prefix = "LOCAL CALL SIGNATURE CONTRACT"
                explanation = (
                    "The concrete caller and provider signatures disagree. Repair the caller/provider coherently "
                    "without adding fake compatibility shims."
                )
                kind = "call_signature"

            issues.append({
                "file": consumer_rel,
                "kind": kind,
                "provider_file": provider_file,
                "line": line,
                "problem": (
                    f"{prefix}: {problem}. Caller {consumer_rel} line {line}: {call_text}. {explanation}"
                ),
            })
    return issues



def _relative_sqlite_paths_in_production(work, manifest):
    """Return relative literal sqlite3.connect paths used by production code."""
    root = _python_project_root(work, manifest)
    found = []
    for path in sorted(root.rglob("*.py")):
        if not path.is_file():
            continue
        try:
            rel = path.relative_to(Path(work)).as_posix()
        except Exception:
            continue
        if _is_jarvis_generated_acceptance_test(rel):
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue
        for call in [n for n in ast.walk(tree) if isinstance(n, ast.Call)]:
            func = call.func
            is_sqlite_connect = (
                isinstance(func, ast.Attribute)
                and func.attr == "connect"
                and isinstance(func.value, ast.Name)
                and func.value.id == "sqlite3"
            )
            if not is_sqlite_connect or not call.args:
                continue
            arg = call.args[0]
            if not isinstance(arg, ast.Constant) or not isinstance(arg.value, str):
                continue
            value = arg.value.strip()
            if not value or value == ":memory:":
                continue
            try:
                if Path(value).is_absolute():
                    continue
            except Exception:
                continue
            found.append((rel, value, getattr(call, "lineno", "?")))
    return found



def _generated_test_storage_isolation_issues(work, manifest):
    """V20 isolates every Jarvis-generated test method at the runner level.

    Source-level TemporaryDirectory/chdir fixtures are no longer required. Keeping isolation in the
    harness is stronger: a malformed test cannot accidentally construct production objects before chdir,
    and every test method receives a fresh cwd even when Qwen forgets cleanup code entirely.
    """
    return []

def _generated_test_preflight_issues(work, manifest):
    out = []
    out.extend(_generated_test_undefined_name_issues(work, manifest))
    out.extend(
        x for x in _python_local_call_signature_issues(work, manifest)
        if _is_jarvis_generated_acceptance_test(x.get("file"))
    )
    out.extend(_generated_test_storage_isolation_issues(work, manifest))
    return out



def _extra_python_static_issue_set(work, manifest):
    out = set()
    for item in _definite_none_member_call_issues(work, manifest):
        out.add((str(item.get("file") or ""), _stable_issue_problem(item.get("problem") or "")))
    for item in _sqlite_select_star_constructor_issues(work, manifest):
        out.add((str(item.get("file") or ""), _stable_issue_problem(item.get("problem") or "")))
    for item in _generated_acceptance_test_contract_issues(work, manifest):
        out.add((str(item.get("file") or ""), _stable_issue_problem(item.get("problem") or "")))
    for item in _generated_test_preflight_issues(work, manifest):
        out.add((str(item.get("file") or ""), _stable_issue_problem(item.get("problem") or "")))
    for item in _python_local_call_signature_issues(work, manifest):
        if not _is_jarvis_generated_acceptance_test(item.get("file")):
            out.add((str(item.get("file") or ""), _stable_issue_problem(item.get("problem") or "")))
    return out


def _v34_toolchain_structure_issues(work, manifest):
    root=Path(work); adapter=str((manifest or {}).get('toolchain_adapter') or _v34_infer_toolchain('',manifest,root)); issues=[]
    def need(condition,path,problem):
        if condition and not path: issues.append({'file':'','problem':problem,'kind':'toolchain'})
    package=next(iter(root.rglob('package.json')),None); cmake=next(iter(root.rglob('CMakeLists.txt')),None); cargo=next(iter(root.rglob('Cargo.toml')),None); gomod=next(iter(root.rglob('go.mod')),None)
    gradle=next(iter(root.rglob('settings.gradle.kts')),None) or next(iter(root.rglob('settings.gradle')),None) or next(iter(root.rglob('build.gradle.kts')),None) or next(iter(root.rglob('build.gradle')),None)
    pom=next(iter(root.rglob('pom.xml')),None); pub=next(iter(root.rglob('pubspec.yaml')),None); swiftpm=next(iter(root.rglob('Package.swift')),None); uproject=next(iter(root.rglob('*.uproject')),None)
    if adapter in {'node','react','nextjs','vue','angular','electron','react_native'} and not package: issues.append({'file':'package.json','problem':'Selected JavaScript/TypeScript toolchain requires package.json with runnable scripts.','kind':'toolchain'})
    if adapter=='static_web' and not next(iter(root.rglob('index.html')),None): issues.append({'file':'index.html','problem':'Static web project requires a real index.html entrypoint.','kind':'toolchain'})
    if adapter=='cpp_cmake' and not cmake: issues.append({'file':'CMakeLists.txt','problem':'Selected C/C++ CMake toolchain requires CMakeLists.txt.','kind':'toolchain'})
    if adapter=='rust' and not cargo: issues.append({'file':'Cargo.toml','problem':'Rust project requires Cargo.toml.','kind':'toolchain'})
    if adapter=='go' and not gomod: issues.append({'file':'go.mod','problem':'Go module project requires go.mod.','kind':'toolchain'})
    if adapter=='dotnet' and not (next(iter(root.rglob('*.sln')),None) or next(iter(root.rglob('*.csproj')),None)): issues.append({'file':'','problem':'.NET project requires a .csproj or .sln build target.','kind':'toolchain'})
    if adapter in {'java_gradle','kotlin_gradle','android_gradle'} and not gradle: issues.append({'file':'build.gradle.kts','problem':'Gradle-selected project requires Gradle settings/build files or wrapper.','kind':'toolchain'})
    if adapter=='java_maven' and not pom: issues.append({'file':'pom.xml','problem':'Maven-selected Java project requires pom.xml.','kind':'toolchain'})
    if adapter=='android_gradle' and not next(iter(root.rglob('AndroidManifest.xml')),None): issues.append({'file':'app/src/main/AndroidManifest.xml','problem':'Android project requires AndroidManifest.xml.','kind':'toolchain'})
    if adapter=='flutter' and not pub: issues.append({'file':'pubspec.yaml','problem':'Flutter project requires pubspec.yaml.','kind':'toolchain'})
    if adapter=='swiftpm' and not swiftpm: issues.append({'file':'Package.swift','problem':'Swift Package project requires Package.swift.','kind':'toolchain'})
    if adapter in {'ios_xcode','macos_xcode'} and not (next(iter(root.rglob('*.xcodeproj')),None) or next(iter(root.rglob('*.xcworkspace')),None) or next(iter(root.rglob('project.yml')),None)): issues.append({'file':'project.yml','problem':'Native Apple project requires an Xcode project/workspace or reproducible project.yml specification.','kind':'toolchain'})
    if adapter=='unreal':
        if not uproject: issues.append({'file':'','problem':'Unreal project requires a .uproject descriptor.','kind':'toolchain'})
        if not next(iter(root.rglob('*.Build.cs')),None): issues.append({'file':'','problem':'Unreal project requires at least one module Build.cs file.','kind':'toolchain'})
    if adapter=='unity' and not (root/'ProjectSettings'/'ProjectVersion.txt').exists(): issues.append({'file':'ProjectSettings/ProjectVersion.txt','problem':'Unity project requires ProjectSettings/ProjectVersion.txt.','kind':'toolchain'})
    if adapter=='php_composer' and not next(iter(root.rglob('composer.json')),None): issues.append({'file':'composer.json','problem':'Composer-selected PHP project requires composer.json.','kind':'toolchain'})
    if adapter=='ruby_bundler' and not next(iter(root.rglob('Gemfile')),None): issues.append({'file':'Gemfile','problem':'Bundler-selected Ruby project requires Gemfile.','kind':'toolchain'})
    return issues

def _deterministic_acceptance_issues(work, manifest):
    """All non-model checks that can identify a concrete file defect before runtime."""
    issues = []
    completed = _existing_project_text_files(work)
    checks = _static_project_checks(work, completed, manifest)
    for problem in checks.get('issues') or []:
        m = re.match(r'Python syntax:\s*([^:]+):', str(problem))
        issues.append({'file': m.group(1) if m else '', 'problem': str(problem), 'kind': 'static'})
    issues.extend(
        {'file': rel, 'problem': 'Planned/required file is missing or empty.', 'kind': 'missing'}
        for rel in _missing_manifest_files(work, manifest)
    )
    for item in _source_incomplete_issues(work):
        issues.append({**item, 'kind': 'incomplete'})
    issues.extend(_v34_toolchain_structure_issues(work, manifest))
    for item in _manifest_contract_issues(work, manifest):
        issues.append({**item, 'kind': 'contract'})
    for item in _module_identity_issues(work, manifest):
        issues.append({**item, 'kind': 'identity'})
    for item in _local_import_api_issues(work, manifest):
        issues.append({**item, 'kind': 'dependency'})
    for item in _definite_none_member_call_issues(work, manifest):
        issues.append({**item, 'kind': 'definite_none'})
    for item in _sqlite_select_star_constructor_issues(work, manifest):
        issues.append({**item, 'kind': 'data_contract'})
    # Generated tests are deliberately non-authoritative. Undefined symbols, wrong constructor/
    # method signatures, and invented members are defects in the test itself.
    for item in _generated_test_undefined_name_issues(work, manifest):
        issues.append({**item, 'kind': 'generated_test_undefined_name'})
    for item in _generated_test_storage_isolation_issues(work, manifest):
        issues.append({**item, 'kind': 'generated_test_isolation'})
    for item in _python_local_call_signature_issues(work, manifest):
        if _is_jarvis_generated_acceptance_test(item.get("file")):
            issues.append({**item, 'kind': 'generated_test_signature'})
        else:
            issues.append({**item, 'kind': 'call_signature'})
    for item in _generated_acceptance_test_contract_issues(work, manifest):
        issues.append({**item, 'kind': 'generated_test_contract'})
    for item in _local_class_method_api_issues(work, manifest):
        issues.append({**item, 'kind': 'method_contract'})
    return issues



def _method_contract_key_from_issue(issue):
    provider = str(issue.get("provider_file") or issue.get("file") or "")
    class_name = str(issue.get("class") or "")
    member = str(issue.get("member") or "")
    if provider and class_name and member:
        return (provider, class_name, member)

    problem = str(issue.get("problem") or "")
    match = re.search(
        r"LOCAL CLASS MEMBER CONTRACT:\s*class ['\"]([^'\"]+)['\"].*?member ['\"]([^'\"]+)['\"]",
        problem,
    )
    if match and provider:
        return (provider, match.group(1), match.group(2))
    return None


def _current_method_contract_keys(work, manifest):
    return set(_python_method_contract_requirements(work, manifest).keys())


def _stable_issue_problem(problem):
    """Normalize incidental source positions out of deterministic issue identity.

    Transactional edits routinely add/remove lines. A pre-existing defect moving from line 171 to
    line 170 is the SAME defect and must not be treated as a newly introduced regression.
    """
    text = str(problem or "")
    text = re.sub(r'(?i)\bfirst observed at line\s+\d+\b', 'first observed at line #', text)
    text = re.sub(r'(?i)\bline\s+\d+\b', 'line #', text)
    text = re.sub(r'(?i)\blines\s+\d+\s*-\s*\d+\b', 'lines #-#', text)
    return re.sub(r'\s+', ' ', text).strip()


def _issue_set(items):
    out = set()
    for item in items or []:
        out.add((str(item.get("file") or ""), _stable_issue_problem(item.get("problem") or "")))
    return out


def _method_contract_transaction_error(work, manifest, issue, replacements):
    """Validate a coordinated provider/caller repair in a disposable project clone."""
    key = _method_contract_key_from_issue(issue)
    if not key:
        return "Method-contract transaction is missing provider/class/member identity."

    provider_rel, class_name, member = key
    allowed = {provider_rel}
    allowed.update(str(x) for x in (issue.get("consumer_files") or []))
    for ev in issue.get("evidence") or []:
        if ev.get("consumer_file"):
            allowed.add(str(ev["consumer_file"]))

    clean_replacements = {}
    for rel_raw, content in replacements or []:
        try:
            rel = _safe_relative(rel_raw).as_posix()
        except Exception as exc:
            return f"Unsafe replacement path {rel_raw!r}: {exc}"
        if rel not in allowed:
            return (
                f"Method-contract repair tried to modify unrelated file {rel!r}. "
                f"Allowed files: {', '.join(sorted(allowed))}"
            )
        cleaned = _extract_single_file_response(content, rel)
        err = _content_validation_error(rel, cleaned)
        if err:
            return f"{rel}: {err}"
        if not cleaned.strip():
            return f"{rel}: empty replacement"
        target = Path(work) / rel
        try:
            current = target.read_text(encoding="utf-8", errors="replace") if target.exists() else ""
        except Exception:
            current = ""
        if cleaned.strip() != current.strip():
            clean_replacements[rel] = cleaned

    if not clean_replacements:
        return "Repair returned no effective code changes."

    baseline_method_keys = _current_method_contract_keys(work, manifest)
    baseline_import = _issue_set(_local_import_api_issues(work, manifest))
    baseline_manifest = _issue_set(_manifest_contract_issues(work, manifest))
    baseline_identity = _issue_set(_module_identity_issues(work, manifest))
    baseline_stubs = _issue_set(_source_incomplete_issues(work))
    baseline_extra_static = _extra_python_static_issue_set(work, manifest)

    temp = None
    try:
        temp, clone = _copy_project_for_candidate_validation(work)
        for rel, cleaned in clean_replacements.items():
            path = clone / _safe_relative(rel)
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(cleaned, encoding="utf-8")

        remaining_keys = _current_method_contract_keys(clone, manifest)
        if key in remaining_keys:
            return (
                f"Coordinated repair did not reconcile {class_name}.{member}; "
                "the same concrete provider/caller mismatch still exists."
            )

        introduced_methods = sorted(remaining_keys - baseline_method_keys)
        if introduced_methods:
            shown = ", ".join(f"{c}.{m} ({p})" for p, c, m in introduced_methods[:8])
            return "Repair introduced new local class-member mismatches: " + shown

        introduced_import = _issue_set(_local_import_api_issues(clone, manifest)) - baseline_import
        if introduced_import:
            return "Repair introduced new local import/API failures: " + "; ".join(
                f"{f}: {p}" for f, p in list(introduced_import)[:8]
            )

        introduced_manifest = _issue_set(_manifest_contract_issues(clone, manifest)) - baseline_manifest
        if introduced_manifest:
            return "Repair violated manifest/API contracts: " + "; ".join(
                f"{f}: {p}" for f, p in list(introduced_manifest)[:8]
            )

        introduced_identity = _issue_set(_module_identity_issues(clone, manifest)) - baseline_identity
        if introduced_identity:
            return "Repair introduced module-identity problems: " + "; ".join(
                f"{f}: {p}" for f, p in list(introduced_identity)[:8]
            )

        introduced_stubs = _issue_set(_source_incomplete_issues(clone)) - baseline_stubs
        if introduced_stubs:
            return "Repair introduced incomplete/stub code: " + "; ".join(
                f"{f}: {p}" for f, p in list(introduced_stubs)[:8]
            )

        introduced_extra_static = _extra_python_static_issue_set(clone, manifest) - baseline_extra_static
        if introduced_extra_static:
            return "Repair introduced deterministic Python contract failures: " + "; ".join(
                f"{f}: {p}" for f, p in list(introduced_extra_static)[:8]
            )

        _, syntax_failures = _validate_python_files(clone)
        if syntax_failures:
            return "Repair leaves Python syntax failures: " + "; ".join(
                f"{p.relative_to(clone).as_posix()}: {err}" for p, err in syntax_failures[:8]
            )
    except Exception as exc:
        return f"Method-contract sandbox validation failed: {exc}"
    finally:
        if temp is not None:
            temp.cleanup()

    return ""


def _commit_method_contract_replacements(work, replacements):
    """Commit a small coordinated set, rolling back if any write fails."""
    root = Path(work)
    originals = {}
    temps = []
    try:
        for rel_raw, content in replacements:
            rel = _safe_relative(rel_raw).as_posix()
            target = root / _safe_relative(rel)
            current = target.read_text(encoding="utf-8", errors="replace") if target.exists() else None
            originals[rel] = current
            cleaned = _extract_single_file_response(content, rel)
            if current is not None and cleaned.strip() == current.strip():
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            tmp = target.with_name(target.name + ".jarvis_contract_tmp")
            tmp.write_text(cleaned, encoding="utf-8")
            temps.append((tmp, target, rel))

        for tmp, target, rel in temps:
            tmp.replace(target)
            _delete_candidate_draft(work, rel)
        return [rel for _, _, rel in temps]
    except Exception:
        for tmp, _, _ in temps:
            try:
                tmp.unlink(missing_ok=True)
            except Exception:
                pass
        for rel, old in originals.items():
            target = root / _safe_relative(rel)
            try:
                if old is None:
                    target.unlink(missing_ok=True)
                else:
                    target.write_text(old, encoding="utf-8")
            except Exception:
                pass
        return []



def _strategy_file_context(work, manifest, rels):
    """Render COMPLETE source only for files a reconciliation strategy may actually modify."""
    chunks = []
    for rel in rels or []:
        rel = str(rel or "")
        if not rel:
            continue
        path = Path(work) / rel
        if not path.exists() or not path.is_file():
            continue
        try:
            file_text = path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            continue
        item = _manifest_file_item(manifest, rel)
        chunks.append(
            f"===== FILE {rel} =====\n"
            f"PURPOSE: {item.get('purpose') or ''}\n"
            f"DECLARED EXPORTS: {json.dumps(item.get('exports') or [])}\n"
            f"{file_text}\n"
            f"===== END FILE {rel} ====="
        )
    return "\n\n".join(chunks)


def _find_bare_member_call_span(source, member, preferred_line=None):
    """Find a standalone `receiver.member(...)` expression.

    This deliberately does NOT touch calls whose return value participates in an assignment,
    condition, return statement, argument list, etc. It is only a fallback for an impossible,
    standalone side-effect call already proven by the local class/member graph.
    """
    try:
        tree = ast.parse(source)
    except Exception:
        return None

    matches = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Expr):
            continue
        call = node.value
        if not isinstance(call, ast.Call):
            continue
        func = call.func
        if not isinstance(func, ast.Attribute) or func.attr != member:
            continue

        # Mechanical removal is only safe for a very narrow configuration/layout-like call:
        # no positional data arguments, at least one explicit keyword, and keyword values that are
        # simple literals. This allows cases such as `.pack(fill="both", expand=True)` while refusing
        # business actions such as `.adjust_stock(sku, quantity, mode)` and lifecycle calls like
        # `.mainloop()`.
        if call.args or not call.keywords:
            continue

        def simple_literal(value):
            if isinstance(value, ast.Constant):
                return True
            if isinstance(value, (ast.Tuple, ast.List, ast.Set)):
                return all(simple_literal(x) for x in value.elts)
            if isinstance(value, ast.Dict):
                return all(
                    (k is None or simple_literal(k)) and simple_literal(v)
                    for k, v in zip(value.keys, value.values)
                )
            if isinstance(value, ast.UnaryOp) and isinstance(value.op, (ast.UAdd, ast.USub, ast.Not)):
                return simple_literal(value.operand)
            # Tkinter layout calls commonly use symbolic constants such as tk.BOTH, tk.X, tk.LEFT.
            # These are configuration values, not business data. Allow only a small explicit set so
            # the caller-removal fallback remains incapable of deleting meaningful data operations.
            if (
                isinstance(value, ast.Attribute)
                and isinstance(value.value, ast.Name)
                and value.value.id in {'tk', 'tkinter'}
                and value.attr in {
                    'BOTH','X','Y','LEFT','RIGHT','TOP','BOTTOM',
                    'N','S','E','W','NE','NW','SE','SW','CENTER','END'
                }
            ):
                return True
            return False

        if any(kw.arg is None or not simple_literal(kw.value) for kw in call.keywords):
            continue

        start = int(getattr(node, "lineno", 0) or 0)
        end = int(getattr(node, "end_lineno", start) or start)
        if start <= 0:
            continue
        distance = abs(start - int(preferred_line or start))
        matches.append((distance, start, end))

    if not matches:
        return None
    matches.sort()
    _, start, end = matches[0]
    return start, end


def _remove_source_line_span(source, start_line, end_line):
    lines = source.splitlines(keepends=True)
    start = max(1, int(start_line))
    end = max(start, int(end_line))
    if start > len(lines):
        return source
    del lines[start - 1:min(end, len(lines))]
    return "".join(lines)


def _try_deterministic_attribute_member_rename(user_request, manifest, work, issue, progress_callback=None):
    """Conservatively reconcile a misspelled/renamed local DATA attribute in concrete consumers.

    This is only attempted when:
      * evidence is attribute access, not a method call,
      * the provider has a unique existing instance attribute with a strongly related identifier,
      * the exact evidenced attribute access can be rewritten,
      * the full coordinated transaction gate proves the original mismatch disappears with no new ones.
    """
    key = _method_contract_key_from_issue(issue)
    if not key:
        return False
    provider_rel, class_name, missing = key
    evidence = list(issue.get("evidence") or [])
    if not evidence or any(str(ev.get("usage") or "") == "call" for ev in evidence):
        return False

    class_index, _ = _python_local_class_index(work, manifest)
    info = class_index.get(class_name)
    if not info:
        return False
    candidates = sorted(set(info.get("instance_attrs") or set()))
    if not candidates:
        return False

    def related_score(name):
        ratio = difflib.SequenceMatcher(None, missing.lower(), name.lower()).ratio()
        left = missing.lower().split("_")
        right = name.lower().split("_")
        shared_edge = bool(left and right and (left[0] == right[0] or left[-1] == right[-1]))
        return ratio, shared_edge

    ranked = sorted(
        ((related_score(name)[0], related_score(name)[1], name) for name in candidates),
        reverse=True,
    )
    best_ratio, best_edge, replacement = ranked[0]
    second_ratio = ranked[1][0] if len(ranked) > 1 else 0.0
    if not best_edge or best_ratio < 0.60 or (best_ratio - second_ratio) < 0.10:
        return False

    evidence_by_file = {}
    for ev in evidence:
        rel = str(ev.get("consumer_file") or "")
        try:
            line = int(ev.get("line"))
        except Exception:
            line = -1
        if rel and line > 0:
            evidence_by_file.setdefault(rel, set()).add(line)

    replacements = []
    for rel, target_lines in evidence_by_file.items():
        path = Path(work) / rel
        if not path.exists() or path.suffix.lower() not in {".py", ".pyw"}:
            continue
        try:
            source = path.read_text(encoding="utf-8", errors="replace")
            tree = ast.parse(source)
        except Exception:
            continue

        changed = [0]

        class Rewriter(ast.NodeTransformer):
            def visit_Attribute(self, node):
                node = self.generic_visit(node)
                if (
                    isinstance(node, ast.Attribute)
                    and node.attr == missing
                    and int(getattr(node, "lineno", -1) or -1) in target_lines
                ):
                    node.attr = replacement
                    changed[0] += 1
                return node

        tree = Rewriter().visit(tree)
        ast.fix_missing_locations(tree)
        if not changed[0]:
            continue
        try:
            candidate = ast.unparse(tree).rstrip() + "\n"
        except Exception:
            continue
        replacements.append((rel, candidate))

    if not replacements:
        return False

    tx_error = _method_contract_transaction_error(work, manifest, issue, replacements)
    if tx_error:
        _append_project_event(
            work,
            "method_contract_attribute_rename_rejected",
            f"Rejected deterministic attribute reconciliation {class_name}.{missing} -> {replacement}.",
            provider=provider_rel,
            consumers=sorted(evidence_by_file),
            replacement=replacement,
            reason=tx_error,
        )
        return False

    changed = _commit_method_contract_replacements(work, replacements)
    if not changed:
        return False

    _append_project_event(
        work,
        "method_contract_attribute_renamed",
        f"Reconciled concrete local attribute {class_name}.{missing} to existing {class_name}.{replacement}.",
        provider=provider_rel,
        changed_files=changed,
        replacement=replacement,
        similarity=round(best_ratio, 3),
    )
    _progress(
        progress_callback,
        f"Deterministically reconciled {class_name}.{missing} -> {replacement}.",
        stage="repairing",
    )
    return True


def _try_deterministic_caller_contract_repair(user_request, manifest, work, issue, progress_callback=None):
    """Safely remove a proven impossible standalone configuration/layout member call.

    All safely-removable consumer occurrences are reconciled in ONE coordinated transaction.
    This matters when multiple callers contain the same impossible layout call: removing only one
    would leave the same provider/member contract alive through the other caller and falsely reject
    an otherwise-correct deterministic repair.
    """
    key = _method_contract_key_from_issue(issue)
    if not key:
        return False
    provider_rel, class_name, member = key

    evidence = list(issue.get("evidence") or [])
    if not evidence:
        return False

    spans_by_consumer = {}
    for ev in evidence:
        consumer = str(ev.get("consumer_file") or "")
        if not consumer or consumer == provider_rel:
            continue
        path = Path(work) / consumer
        if not path.exists() or path.suffix.lower() not in {".py", ".pyw"}:
            continue
        try:
            current = path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            continue
        span = _find_bare_member_call_span(current, member, ev.get("line"))
        if span:
            spans_by_consumer.setdefault(consumer, set()).add(tuple(span))

    if not spans_by_consumer:
        return False

    replacements = []
    removed_meta = {}
    for consumer, spans in sorted(spans_by_consumer.items()):
        path = Path(work) / consumer
        try:
            current = path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            return False

        # Remove from bottom to top so earlier line numbers remain stable.
        candidate = current
        ordered = sorted(spans, key=lambda x: (x[0], x[1]), reverse=True)
        for start_line, end_line in ordered:
            candidate = _remove_source_line_span(candidate, start_line, end_line)
        if candidate.strip() == current.strip():
            continue
        replacements.append((consumer, candidate))
        removed_meta[consumer] = [list(x) for x in sorted(spans)]

    if not replacements:
        return False

    tx_error = _method_contract_transaction_error(work, manifest, issue, replacements)
    if tx_error:
        _append_project_event(
            work,
            "method_contract_deterministic_repair_rejected",
            f"Coordinated deterministic caller fallback rejected for {class_name}.{member}.",
            provider=provider_rel,
            consumers=sorted(removed_meta),
            removed_lines=removed_meta,
            reason=tx_error,
        )
        return False

    changed = _commit_method_contract_replacements(work, replacements)
    if not changed:
        return False

    _append_project_event(
        work,
        "method_contract_deterministic_repair",
        f"Removed impossible standalone {class_name}.{member} caller expressions in one coordinated transaction.",
        provider=provider_rel,
        consumers=sorted(removed_meta),
        changed_files=changed,
        removed_lines=removed_meta,
    )
    _progress(
        progress_callback,
        f"Deterministically reconciled {class_name}.{member} across {len(changed)} caller file(s).",
        stage="repairing",
    )
    return True

def _method_test_context(work, class_name, member, max_chars=10000):
    """Return focused tests/usages relevant to one class member without dumping the whole project."""
    chunks = []
    used = 0
    root = Path(work)
    candidates = []
    for path in sorted(root.rglob("test*.py")):
        if path.is_file() and not any(part in _ANALYSIS_IGNORE_DIRS for part in path.relative_to(root).parts):
            candidates.append(path)
    # If tests do not mention the symbol literally, include up to two small test files because behavior
    # contracts are often expressed through the service that delegates to this provider.
    preferred = []
    fallback = []
    for path in candidates:
        try:
            source = path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            continue
        rel = path.relative_to(root).as_posix()
        piece = f"===== TEST {rel} =====\n{source}\n===== END TEST {rel} ====="
        if class_name in source or member in source:
            preferred.append(piece)
        else:
            fallback.append(piece)
    for piece in preferred + fallback[:2]:
        if used + len(piece) > max_chars:
            continue
        chunks.append(piece)
        used += len(piece)
    return "\n\n".join(chunks)


def _extract_single_method_node(raw, expected_member):
    """Parse exactly one complete method definition from a narrow Qwen response."""
    raw_text = str(raw or "").strip()
    snippets = []

    try:
        obj = _extract_json(raw_text)
    except Exception:
        obj = None

    if isinstance(obj, dict):
        for key in ("method_source", "method", "code", "content", "source"):
            value = obj.get(key)
            if isinstance(value, str) and value.strip():
                snippets.append(value)
        methods = obj.get("methods")
        if isinstance(methods, list):
            for value in methods:
                if isinstance(value, str) and value.strip():
                    snippets.append(value)
                elif isinstance(value, dict):
                    for key in ("method_source", "method", "code", "content", "source"):
                        part = value.get(key)
                        if isinstance(part, str) and part.strip():
                            snippets.append(part)

    snippets.append(raw_text)

    for snippet in snippets:
        cleaned = textwrap.dedent(_strip_fence(snippet)).strip()
        if not cleaned:
            continue

        # If the model wrapped the method inside JSON prose, recover the most likely `def` block.
        candidates = [cleaned]
        match = re.search(
            rf"(?ms)^(?:async\s+def|def)\s+{re.escape(expected_member)}\s*\(.*",
            cleaned,
        )
        if match and match.start() > 0:
            candidates.append(cleaned[match.start():])

        for candidate in candidates:
            try:
                tree = ast.parse(candidate)
            except Exception:
                continue

            found = []
            for node in tree.body:
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == expected_member:
                    found.append(node)
                elif isinstance(node, ast.ClassDef):
                    found.extend(
                        child for child in node.body
                        if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef))
                        and child.name == expected_member
                    )
            if len(found) != 1:
                continue

            node = found[0]
            meaningful = []
            for statement in node.body:
                if isinstance(statement, ast.Pass):
                    continue
                if isinstance(statement, ast.Expr) and isinstance(statement.value, ast.Constant) and statement.value.value is Ellipsis:
                    continue
                if (
                    isinstance(statement, ast.Raise)
                    and isinstance(statement.exc, ast.Call)
                    and isinstance(statement.exc.func, ast.Name)
                    and statement.exc.func.id == "NotImplementedError"
                ):
                    continue
                meaningful.append(statement)
            if not meaningful:
                continue
            return node
    return None


def _insert_or_replace_class_method(source, class_name, method_node):
    """Insert one parsed method into an existing class without asking Qwen to rewrite the whole file."""
    try:
        tree = ast.parse(str(source or ""))
    except Exception:
        return ""

    target = next(
        (node for node in tree.body if isinstance(node, ast.ClassDef) and node.name == class_name),
        None,
    )
    if target is None:
        return ""

    replaced = False
    new_body = []
    for child in target.body:
        if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and child.name == method_node.name:
            if not replaced:
                new_body.append(method_node)
                replaced = True
            continue
        new_body.append(child)
    if not replaced:
        new_body.append(method_node)
    target.body = new_body

    ast.fix_missing_locations(tree)
    try:
        rendered = ast.unparse(tree)
    except Exception:
        return ""
    return rendered.rstrip() + "\n"


def _insert_or_replace_top_level_function(source, function_node):
    """Insert one parsed top-level function without rewriting unrelated module structure by hand."""
    try:
        tree = ast.parse(str(source or ""))
    except Exception:
        return ""

    replaced = False
    new_body = []
    for child in tree.body:
        if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and child.name == function_node.name:
            if not replaced:
                new_body.append(function_node)
                replaced = True
            continue
        new_body.append(child)
    if not replaced:
        new_body.append(function_node)
    tree.body = new_body
    ast.fix_missing_locations(tree)
    try:
        return ast.unparse(tree).rstrip() + "\n"
    except Exception:
        return ""


def _try_surgical_top_level_export_synthesis(
    user_request, manifest, work, rel, problems=None, progress_callback=None
):
    """Synthesize only missing module-level FUNCTION exports required by real consumers/manifest.

    This is a late-bootstrap convergence tool for small local models. It deliberately refuses to
    synthesize missing classes/types, and it validates the complete provider after all missing
    function exports have been inserted.
    """
    rel = str(rel or "").replace("\\", "/")
    path = Path(work) / rel
    if not path.exists() or path.suffix.lower() not in {".py", ".pyw"}:
        return False

    try:
        original = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return False

    required = _required_exports_for_file(work, manifest, rel)
    actual = _python_top_level_exports_from_text(original)
    missing = [name for name in required if name not in actual]
    function_missing = [
        name for name in missing
        if re.fullmatch(r"[a-z_][A-Za-z0-9_]*", name or "")
    ]
    if not function_missing:
        return False
    # If there are also missing class/type exports, let the ordinary full-file reconciler handle the
    # architecture instead of creating a partial provider that can never satisfy its contract.
    if any(name not in function_missing for name in missing):
        return False

    consumer_context = _focused_consumer_context_for_file(work, rel, max_chars=16000)
    test_context = _method_test_context(work, "", " ".join(function_missing), max_chars=12000)
    working = original
    feedback = ""

    for function_name in function_missing:
        function_done = False
        for attempt in range(1, 4):
            prompt = (
                "You are repairing ONE missing MODULE-LEVEL Python function export.\n"
                "Do NOT rewrite the provider file. Return ONLY one complete top-level function definition "
                "encoded as strict JSON under method_source.\n"
                "This is NOT a class method: do not include self or cls unless the real consumer contract "
                "explicitly passes such an object as ordinary data.\n"
                "Infer the exact signature and behavior from the concrete consumer source and tests below.\n"
                "Use only existing provider imports, project APIs shown below, or Python standard-library imports "
                "that are already available in the provider; do not invent new production APIs.\n"
                "Implement real behavior; no pass, TODO, NotImplementedError, fake constants, or compatibility "
                "wrapper that merely swallows arguments.\n\n"
                f"USER REQUEST:\n{user_request}\n\n"
                f"PROVIDER FILE: {rel}\nMISSING TOP-LEVEL EXPORT: {function_name}\n"
                f"ALL REQUIRED EXPORTS: {json.dumps(required, ensure_ascii=False)}\n"
                f"DECLARED PROVIDER CONTRACTS: {json.dumps(_manifest_file_item(manifest, rel).get('contracts') or [], ensure_ascii=False)}\n"
                f"{_v33_dependency_context(manifest, rel)}\n\n"
                f"AUTHORITATIVE ARCHITECTURE CONTRACT:\n{_v33_contract_index(manifest)}\n\n"
                f"IMPLEMENTED PROJECT API INDEX:\n{_project_api_index(work)}\n\n"
                f"CURRENT PROVIDER SOURCE (READ ONLY):\n===== FILE {rel} =====\n{working}\n"
                f"===== END FILE {rel} =====\n\n"
                f"CONCRETE CONSUMERS (READ ONLY):\n{consumer_context or '(none)'}\n\n"
                f"RELEVANT TESTS/BEHAVIOR CONTRACTS:\n{test_context or '(none)'}\n\n"
            )
            if feedback:
                prompt += (
                    "PREVIOUS FUNCTION CANDIDATE/TRANSACTION FEEDBACK:\n"
                    + feedback[-6000:]
                    + "\nCorrect that exact issue without changing unrelated APIs.\n\n"
                )
            prompt += (
                '{"method_source":"def '
                + function_name
                + '(...):\\n    ..."}'
            )

            ok, raw = _qwen_call(
                prompt,
                progress_callback,
                f"Synthesizing top-level {function_name} {attempt}/3",
                profile="repair",
                max_tokens=min(3072, _optional_positive_limit(FILE_MAX_TOKENS) or 3072),
                thinking=False,
                response_schema=QWEN_SCHEMA_METHOD_SOURCE,
                schema_name="method_source",
                strict_output=True,
            )
            if not ok:
                feedback = str(raw or "Qwen function synthesis failed.")
                continue

            node = _extract_single_method_node(raw, function_name)
            if node is None:
                feedback = (
                    f"Response did not contain exactly one complete non-placeholder function named {function_name}."
                )
                continue
            positional = list(node.args.posonlyargs) + list(node.args.args)
            if positional and positional[0].arg in {"self", "cls"}:
                feedback = (
                    f"{function_name} must be a module-level function, not a method; first parameter "
                    f"{positional[0].arg!r} is invalid here."
                )
                continue

            candidate = _insert_or_replace_top_level_function(working, node)
            if not candidate or candidate.strip() == working.strip():
                feedback = "Function insertion produced no effective provider change."
                continue

            working = candidate
            function_done = True
            feedback = ""
            break

        if not function_done:
            return False

    tx_error = _candidate_transaction_error(
        work,
        manifest,
        rel,
        working,
        user_request=user_request,
        target_problems=list(problems or []),
    )
    if tx_error:
        _save_candidate_draft(work, rel, working)
        _append_project_event(
            work,
            "surgical_top_level_exports_rejected",
            f"Rejected surgical top-level export synthesis for {rel}.",
            file=rel,
            missing_exports=function_missing,
            reason=tx_error,
        )
        return False

    tmp = path.with_name(path.name + ".jarvis_tmp")
    try:
        tmp.write_text(working, encoding="utf-8")
        tmp.replace(path)
    except Exception:
        try:
            tmp.unlink(missing_ok=True)
        except Exception:
            pass
        return False

    _delete_candidate_draft(work, rel)
    _append_project_event(
        work,
        "surgical_top_level_exports_committed",
        f"Synthesized missing top-level exports in {rel} without rewriting unrelated provider code.",
        file=rel,
        exports=function_missing,
    )
    _progress(
        progress_callback,
        f"Synthesized {len(function_missing)} missing module export(s) in {rel}.",
        stage="repairing",
    )
    return True


def _try_surgical_provider_member_synthesis(
    user_request, manifest, work, issue, progress_callback=None, prior_error=""
):
    """Ask Qwen for ONE missing provider method, then insert/validate it transactionally.

    This avoids late-stage full-file rewrites that frequently damage already-correct provider code
    or produce malformed multiline SQL/strings. The model is responsible only for the method logic;
    Jarvis owns insertion, whole-project contract validation, and commit.
    """
    key = _method_contract_key_from_issue(issue)
    if not key:
        return False
    provider_rel, class_name, member = key
    if key not in _current_method_contract_keys(work, manifest):
        return False

    provider_path = Path(work) / provider_rel
    if not provider_path.exists() or provider_path.suffix.lower() not in {".py", ".pyw"}:
        return False
    try:
        provider_source = provider_path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return False

    consumers = []
    for rel in issue.get("consumer_files") or []:
        rel = str(rel or "")
        if rel and rel not in consumers:
            consumers.append(rel)
    consumer_context = _strategy_file_context(work, manifest, consumers[:METHOD_CONTRACT_CONTEXT_FILES])
    test_context = _method_test_context(work, class_name, member)

    feedback = str(prior_error or "")
    for attempt in range(1, 4):
        prompt = (
            "You are repairing ONE missing member on an existing Python class.\n"
            "DO NOT rewrite the provider file. Return ONLY the complete Python method definition that should "
            "exist inside the named class, encoded as strict JSON.\n"
            "Use only names/imports already available in the provider file or Python builtins.\n"
            "The method must implement real behavior; no pass, ellipsis, TODO, NotImplementedError, fake constant "
            "return, or compatibility shim merely to silence validation.\n"
            "Preserve the project's existing model/field names exactly as shown in PROJECT API INDEX and tests.\n"
            "Keep strings syntactically complete. Prefer simple code over clever code.\n\n"
            f"USER REQUEST:\n{user_request}\n\n"
            f"PROVIDER FILE: {provider_rel}\nCLASS: {class_name}\nMISSING MEMBER: {member}\n\n"
            f"CONCRETE EVIDENCE:\n{json.dumps(issue.get('evidence') or [], ensure_ascii=False)}\n\n"
            f"PROJECT API INDEX:\n{_project_api_index(work)}\n\n"
            f"PROVIDER SOURCE (READ ONLY):\n===== FILE {provider_rel} =====\n{provider_source}\n"
            f"===== END FILE {provider_rel} =====\n\n"
            f"CONSUMER SOURCE (READ ONLY):\n{consumer_context}\n\n"
            f"RELEVANT TESTS/BEHAVIOR CONTRACTS:\n{test_context}\n\n"
        )
        if feedback:
            prompt += (
                "PREVIOUS SURGICAL CANDIDATE WAS REJECTED:\n"
                + feedback[-6000:]
                + "\nCorrect that exact problem in the new method. Do not repeat the rejected implementation.\n\n"
            )
        prompt += (
            'RETURN EXACTLY: {"method_source":"def '
            + member
            + '(self, ...):\\n    ..."}'
        )

        ok, raw = _qwen_call(
            prompt,
            progress_callback,
            f"Synthesizing {class_name}.{member} method {attempt}/3",
            profile="repair",
            max_tokens=min(3072, _optional_positive_limit(FILE_MAX_TOKENS) or 3072),
            thinking=False, response_schema=QWEN_SCHEMA_METHOD_SOURCE, schema_name='method_source', strict_output=True,
        )
        if not ok:
            feedback = str(raw or "Qwen method synthesis failed.")
            continue

        method_node = _extract_single_method_node(raw, member)
        if method_node is None:
            feedback = "Response did not contain exactly one complete, non-placeholder method definition named " + member + "."
            continue

        candidate = _insert_or_replace_class_method(provider_source, class_name, method_node)
        if not candidate or candidate.strip() == provider_source.strip():
            feedback = "Synthesized method produced no effective provider change."
            continue

        tx_error = _method_contract_transaction_error(
            work, manifest, issue, [(provider_rel, candidate)]
        )
        if tx_error:
            feedback = tx_error
            _save_candidate_draft(work, provider_rel, candidate)
            _append_project_event(
                work,
                "surgical_method_candidate_rejected",
                f"Rejected surgical method synthesis for {class_name}.{member}.",
                provider=provider_rel,
                member=member,
                reason=tx_error,
            )
            continue

        # A synthesized method can satisfy the static member graph yet still be a broken wrapper.
        # Probe startup in a disposable clone when possible. If execution reaches the synthesized
        # method itself and crashes there, reject it before it can overwrite live source.
        probe_temp = None
        try:
            probe_temp, probe = _copy_project_for_candidate_validation(work)
            probe_path = probe / _safe_relative(provider_rel)
            probe_path.parent.mkdir(parents=True, exist_ok=True)
            probe_path.write_text(candidate, encoding="utf-8")
            probe_ok, probe_output = _run_python_startup_smoke(probe, manifest)
            if not probe_ok:
                normalized_probe = str(probe_output or "").replace("\\", "/")
                plain_probe = re.sub(r"\x1b\[[0-?]*[ -/]*[@-~]", "", normalized_probe)
                provider_norm = provider_rel.replace("\\", "/").lower()
                provider_in_trace = provider_norm in plain_probe.lower()
                crashes_in_method = bool(
                    re.search(rf"\bin\s+{re.escape(member)}\b", plain_probe)
                )
                if provider_in_trace and crashes_in_method:
                    feedback = (
                        f"Synthesized {class_name}.{member} crashes when exercised during real startup:\n"
                        + normalized_probe[-RUNTIME_REPAIR_REPLAY_OUTPUT_CHARS:]
                    )
                    _save_candidate_draft(work, provider_rel, candidate)
                    _append_project_event(
                        work,
                        "surgical_method_runtime_rejected",
                        f"Rejected synthesized {class_name}.{member} because it crashes during startup.",
                        provider=provider_rel,
                        member=member,
                        reason=feedback,
                    )
                    continue
        except Exception:
            # Runtime probing is an additional safeguard; deterministic transaction validation
            # remains authoritative when a local environment cannot launch the app.
            pass
        finally:
            if probe_temp is not None:
                probe_temp.cleanup()

        changed = _commit_method_contract_replacements(
            work, [(provider_rel, candidate)]
        )
        if not changed:
            feedback = "Validated surgical method could not be committed."
            continue

        _append_project_event(
            work,
            "surgical_method_reconciled",
            f"Inserted validated synthesized method {class_name}.{member} without rewriting the whole provider file.",
            provider=provider_rel,
            changed_files=changed,
            attempt=attempt,
        )
        _progress(
            progress_callback,
            f"Surgically repaired {class_name}.{member} in {provider_rel}.",
            stage="repairing",
        )
        return True

    return False


def _repair_one_method_contract(user_request, manifest, work, issue, progress_callback=None):
    """Reconcile one concrete class-member mismatch across provider + consumers.

    Strategy escalation is enforced in BOTH context and output:
      1) free architectural repair,
      2) caller-only repair with provider source excluded from writable context,
      3) deterministic caller fallback for a proven bare impossible call,
      4) provider-only implementation,
      5+) coordinated both-side repair.
    """
    key = _method_contract_key_from_issue(issue)
    if not key:
        return False
    provider_rel, class_name, member = key

    if key not in _current_method_contract_keys(work, manifest):
        return False

    consumers = []
    for rel in issue.get("consumer_files") or []:
        rel = str(rel)
        if rel and rel not in consumers:
            consumers.append(rel)
    for ev in issue.get("evidence") or []:
        rel = str(ev.get("consumer_file") or "")
        if rel and rel not in consumers:
            consumers.append(rel)

    all_allowed = [provider_rel] + [x for x in consumers if x != provider_rel]
    all_allowed = all_allowed[:METHOD_CONTRACT_CONTEXT_FILES]
    consumers = [x for x in consumers if x in all_allowed and x != provider_rel]
    evidence = issue.get("evidence") or []

    best_error = ""
    rejected_text = ""
    total_attempts = max(4, METHOD_CONTRACT_REPAIR_ROUNDS)

    for attempt in range(1, total_attempts + 1):
        if attempt == 1:
            strategy = "free"
            strategy_files = list(all_allowed)
            strategy_allowed = set(strategy_files)
            strategy_text = (
                "Choose the cleanest architecture. You may repair provider, caller(s), or both. "
                "Prefer an existing valid API over inventing a compatibility shim."
            )
        elif attempt == 2 and consumers:
            strategy = "caller_only"
            strategy_files = list(consumers)
            strategy_allowed = set(strategy_files)
            strategy_text = (
                "CALLER-SIDE ONLY. The provider file is READ-ONLY and intentionally omitted from the writable "
                "source context. Output ONLY consumer file replacements. Reconcile the caller using the provider "
                "API shown in PROJECT API INDEX, or remove a redundant/incorrect standalone call when required "
                "behavior is already performed elsewhere. Preserve the feature."
            )
        elif attempt == 3:
            if _try_deterministic_attribute_member_rename(
                user_request, manifest, work, issue, progress_callback
            ):
                return True

            # First try the extremely narrow deterministic caller repair. It only accepts a bare
            # layout/configuration-like call with NO positional data arguments and literal keyword
            # options, e.g. `.pack(fill="both", expand=True)`. Business actions such as
            # `.adjust_stock(sku, qty, mode)` and lifecycle calls such as `.mainloop()` are not
            # eligible, so this cannot silently delete meaningful work.
            if _try_deterministic_caller_contract_repair(
                user_request, manifest, work, issue, progress_callback
            ):
                return True

            # If the caller cannot be mechanically reconciled, a genuine direct method call is
            # probably real behavior. Synthesize ONLY the missing provider method before any
            # full-file provider rewrite.
            if any(str(ev.get("usage") or "") == "call" for ev in (issue.get("evidence") or [])):
                if _try_surgical_provider_member_synthesis(
                    user_request, manifest, work, issue, progress_callback, prior_error=best_error
                ):
                    return True

            strategy = "provider_only"
            strategy_files = [provider_rel]
            strategy_allowed = {provider_rel}
            strategy_text = (
                "PROVIDER-SIDE ONLY. Consumer files are READ-ONLY. Implement the missing member only if it "
                "genuinely belongs on this class, with complete behavior. No pass/no-op/placeholder method."
            )
        else:
            strategy = "both_sides"
            strategy_files = list(all_allowed)
            strategy_allowed = set(strategy_files)
            strategy_text = (
                "COORDINATED BOTH-SIDE REPAIR. Modify the smallest necessary combination of provider and caller "
                "files so their API agrees and requested behavior remains intact."
            )

        context = _strategy_file_context(work, manifest, strategy_files)
        allowed_list = ", ".join(sorted(strategy_allowed))
        attempt_prompt = (
            "You are reconciling ONE proven local class API mismatch in a multi-file project.\n"
            "The mismatch is real, but the caller OR provider OR both may be wrong.\n"
            "Never add a pass-only method, empty/no-op compatibility wrapper, fake return, TODO, placeholder, "
            "or dead shim merely to silence validation.\n"
            "Return ONLY strict JSON containing COMPLETE replacement files.\n"
            f"THIS ATTEMPT MAY MODIFY ONLY: {allowed_list}\n"
            "Do not output any other file, even unchanged.\n\n"
            f"STRATEGY:\n{strategy_text}\n\n"
            f"USER REQUEST:\n{user_request}\n\n"
            f"MISMATCH:\nProvider file: {provider_rel}\nClass: {class_name}\n"
            f"Missing/invalid member usage: {member}\n"
            f"Concrete evidence: {json.dumps(evidence, ensure_ascii=False)}\n\n"
            f"PROJECT API INDEX (read-only architectural reference):\n{_project_api_index(work)}\n\n"
            f"WRITABLE FILES FOR THIS STRATEGY:\n{context}\n\n"
            'RETURN SHAPE: {"summary":"what was reconciled","files":'
            '[{"path":"relative/file.py","content":"COMPLETE replacement"}]}'
        )

        if best_error:
            attempt_prompt += (
                "\n\nPREVIOUS TRANSACTION WAS REJECTED:\n"
                + best_error
                + "\nDo NOT repeat the rejected approach. Follow THIS attempt's strategy and writable-file list exactly.\n"
            )
            if rejected_text and strategy in {"free", "both_sides"}:
                attempt_prompt += "\nPREVIOUS RAW RESPONSE:\n" + rejected_text[-8000:]

        ok, raw = _qwen_call(
            attempt_prompt,
            progress_callback,
            f"Reconciling {class_name}.{member} {attempt}/{total_attempts} [{strategy}]",
            profile="repair",
            max_tokens=_optional_positive_limit(FILE_MAX_TOKENS),
            thinking=False, response_schema=QWEN_SCHEMA_FILE_REPLACEMENTS, schema_name='contract_repair', strict_output=True,
        )
        rejected_text = str(raw or "")
        if not ok:
            best_error = rejected_text or "Qwen repair call failed."
            continue

        candidates, summary = _parse_multifile_repair(raw, None)
        if not candidates:
            candidates = _recover_complete_json_file_pairs(
                _escape_raw_json_control_chars(str(raw or ""))
            )
        if not candidates:
            best_error = "Qwen returned no parseable complete replacement files."
            continue

        strategy_violation = ""
        for rel_raw, _content in candidates:
            try:
                rel = _safe_relative(rel_raw).as_posix()
            except Exception as exc:
                strategy_violation = f"Unsafe replacement path {rel_raw!r}: {exc}"
                break
            if rel not in strategy_allowed:
                strategy_violation = (
                    f"{strategy} attempt modified {rel!r}, but this strategy permits only: "
                    + ", ".join(sorted(strategy_allowed))
                )
                break
        if strategy_violation:
            best_error = strategy_violation
            _append_project_event(
                work,
                "method_contract_candidate_rejected",
                f"Rejected {strategy} repair for {class_name}.{member}.",
                provider=provider_rel,
                consumers=consumers,
                reason=strategy_violation,
            )
            continue

        tx_error = _method_contract_transaction_error(work, manifest, issue, candidates)
        if tx_error:
            best_error = tx_error
            for rel, content in candidates:
                try:
                    rel_clean = _safe_relative(rel).as_posix()
                    if rel_clean in set(all_allowed):
                        _save_candidate_draft(work, rel_clean, content)
                except Exception:
                    pass
            _append_project_event(
                work,
                "method_contract_candidate_rejected",
                f"Rejected {strategy} coordinated repair for {class_name}.{member}.",
                provider=provider_rel,
                consumers=consumers,
                reason=tx_error,
            )
            continue

        changed = _commit_method_contract_replacements(work, candidates)
        if not changed:
            best_error = "Validated contract repair could not be committed."
            continue

        _append_project_event(
            work,
            "method_contract_reconciled",
            f"Reconciled {class_name}.{member} across provider/caller files.",
            provider=provider_rel,
            consumers=consumers,
            strategy=strategy,
            changed_files=changed,
            summary=summary,
        )
        return True

    if _try_deterministic_attribute_member_rename(
        user_request, manifest, work, issue, progress_callback
    ):
        return True
    return _try_deterministic_caller_contract_repair(
        user_request, manifest, work, issue, progress_callback
    )

def _repair_method_contract_issues(user_request, manifest, work, issues, progress_callback=None):
    """Reconcile method/member mismatches one-by-one, rechecking the graph after each commit."""
    changed = False
    for issue in issues:
        if issue.get("kind") != "method_contract":
            continue
        key = _method_contract_key_from_issue(issue)
        if not key or key not in _current_method_contract_keys(work, manifest):
            continue
        changed = _repair_one_method_contract(
            user_request, manifest, work, issue, progress_callback
        ) or changed
    return changed


def _group_deterministic_repairs(work, manifest, issues):
    """Group ordinary deterministic repairs.

    Local class-member mismatches are intentionally excluded here because they may require changing
    the consumer, provider, or both. `_repair_method_contract_issues` handles them transactionally.
    """
    grouped = {}
    dependency = [x for x in issues if x.get('kind') == 'dependency']
    for rel, problems in _route_dependency_issues(work, manifest, dependency).items():
        grouped.setdefault(rel, []).extend(x for x in problems if x not in grouped.get(rel, []))

    for issue in issues:
        if issue.get('kind') in {'dependency', 'method_contract'}:
            continue
        rel = str(issue.get('file') or '')
        problem = str(issue.get('problem') or '')
        if not rel or not problem:
            continue
        grouped.setdefault(rel, [])
        if problem not in grouped[rel]:
            grouped[rel].append(problem)
    return grouped



def _acceptance_repair_cycle(user_request, manifest, work, progress_callback=None):
    """Tool-first acceptance loop.

    Order matters: deterministic contracts and REAL execution/tests are stronger evidence than an
    LLM semantic opinion. Semantic audit runs last and is evidence-scoped to avoid repair churn.
    """
    last_issues = []
    previous_signature = None
    no_progress = 0
    base_rounds = PROJECT_ACCEPTANCE_ROUNDS
    max_rounds = base_rounds + PROJECT_ACCEPTANCE_EXTRA_CLEAN_ROUNDS

    for round_no in range(1, max_rounds + 1):
        shown_total = base_rounds if round_no <= base_rounds else max_rounds
        _progress(
            progress_callback,
            f'Acceptance pass {round_no}/{shown_total}...',
            stage='verifying',
            percent=min(94, 68 + round_no * 3),
        )

        changed_this_round = False
        if V33_SYSTEMATIC_BUILD:
            _v33_write_build_status(work, manifest, f'acceptance_pass_{round_no}')

        normalized = _normalize_workspace_model_artifacts(work)
        if normalized:
            _append_project_event(
                work,
                'model_wrappers_cleaned',
                'Removed model-output wrappers from generated source files.',
                files=normalized,
            )
            changed_this_round = True

        # 1) Recover every planned file before any project-wide validation.
        for rel in _missing_manifest_files(work, manifest):
            item = next(
                (x for x in manifest.get('files') or [] if str(x.get('path') or '') == rel),
                {'path': rel, 'purpose': 'Required project file', 'exports': []},
            )
            file_ok, wrote = _generate_planned_file(user_request, manifest, work, item, progress_callback)
            if file_ok:
                _append_project_event(work, 'missing_file_recovered', f'Regenerated missing required file {rel}.', file=rel)
            else:
                _append_project_event(
                    work, 'missing_file_retry_failed',
                    f'Could not regenerate missing required file {rel} on acceptance pass {round_no}.',
                    file=rel, pass_no=round_no,
                )
                # A Jarvis-generated QA file is never allowed to become a permanent phantom manifest
                # obligation. If it vanished and cannot be regenerated, release only that Jarvis-owned
                # item. Explicit/user-authored test files remain hard requirements.
                if _is_jarvis_generated_manifest_test_item(item):
                    if _drop_generated_test_manifest_item(manifest, rel):
                        _delete_candidate_draft(work, rel)
                        _append_project_event(
                            work, 'generated_test_manifest_obligation_released',
                            'Released an unmaterialized Jarvis-generated test from the manifest after regeneration failed.',
                            file=rel, pass_no=round_no,
                        )
            changed_this_round = file_ok or changed_this_round

        # V33: finish any remaining contract shells in dependency order BEFORE generic repair.
        # This preserves the architecture-first workflow even when an initial file generation timed out.
        if V33_SYSTEMATIC_BUILD:
            remaining_shells = [
                item for item in _v33_dependency_ordered_files(manifest)
                if _v33_is_contract_skeleton(Path(work) / str(item.get('path') or ''))
            ]
            for item in remaining_shells:
                rel = str(item.get('path') or '')
                _progress(
                    progress_callback, f'V33 completing contract shell: {rel}',
                    stage='generating', percent=min(86, 69 + round_no * 2),
                )
                file_ok, wrote = _generate_planned_file(
                    user_request, manifest, work, item, progress_callback
                )
                if file_ok:
                    changed_this_round = True
                    _append_project_event(
                        work, 'v33_shell_completed',
                        f'Completed remaining V33 contract shell {rel} in dependency order.', file=rel,
                    )

        # 2) Deterministic syntax/stub/manifest/import/module checks first.
        # Method/member mismatches are different: either the provider OR the caller can be wrong,
        # so they are reconciled as coordinated multi-file transactions after ordinary repairs.
        deterministic = _deterministic_acceptance_issues(work, manifest)

        # SQL row/model width mismatches are mechanical once Jarvis has proven the CREATE TABLE
        # schema, fixed constructor fields, SELECT *, and direct Model(*row) expansion. Repair these
        # surgically before asking Qwen for a whole-file rewrite, which can damage unrelated APIs.
        data_contract_files = []
        for issue in deterministic:
            if issue.get("kind") == "data_contract":
                rel = str(issue.get("file") or "")
                if rel and rel not in data_contract_files:
                    data_contract_files.append(rel)
        for rel in data_contract_files:
            if _try_deterministic_sql_row_model_repair(
                user_request, manifest, work, rel, progress_callback
            ):
                changed_this_round = True

        # Recompute after deterministic SQL surgery. Any data contract that could not be repaired
        # safely remains available to the normal Qwen transactional repair path.
        deterministic = _deterministic_acceptance_issues(work, manifest)

        # Missing module-level function exports are another narrow late-bootstrap case where a
        # whole-file rewrite is unnecessarily destructive. Synthesize only those functions first,
        # using real consumers/tests as the contract, then let ordinary repair handle anything that
        # remains (classes/types or rejected function candidates).
        export_problem_files = {}
        dependency_routes = _route_dependency_issues(
            work, manifest, [x for x in deterministic if x.get("kind") == "dependency"]
        )
        for rel, problems in dependency_routes.items():
            export_problem_files.setdefault(rel, []).extend(problems)
        for issue in deterministic:
            if issue.get("kind") == "contract":
                rel = str(issue.get("file") or "")
                if rel:
                    export_problem_files.setdefault(rel, []).append(str(issue.get("problem") or ""))
        for rel, problems in list(export_problem_files.items()):
            if _try_surgical_top_level_export_synthesis(
                user_request, manifest, work, rel, problems, progress_callback
            ):
                changed_this_round = True

        deterministic = _deterministic_acceptance_issues(work, manifest)
        grouped = _group_deterministic_repairs(work, manifest, deterministic)
        for rel, problems in grouped.items():
            changed_this_round = _repair_file_for_issues(
                user_request, manifest, work, rel, problems, progress_callback
            ) or changed_this_round

        # Recompute after ordinary repairs, then reconcile proven local class/member mismatches.
        mid_det = _deterministic_acceptance_issues(work, manifest)
        method_contracts = [x for x in mid_det if x.get("kind") == "method_contract"]
        if method_contracts:
            changed_this_round = _repair_method_contract_issues(
                user_request, manifest, work, method_contracts, progress_callback
            ) or changed_this_round

        # Always re-check AFTER all deterministic repairs. Do not spend semantic tokens on known-broken source.
        post_det = _deterministic_acceptance_issues(work, manifest)
        if post_det:
            last_issues = list(dict.fromkeys(
                f"{x.get('file')}: {x.get('problem')}" if x.get('file') else str(x.get('problem') or '')
                for x in post_det
                if str(x.get('problem') or '').strip()
            ))
            signature = tuple(last_issues)
            if signature == previous_signature and not changed_this_round:
                no_progress += 1
            else:
                no_progress = 0
            previous_signature = signature
            if no_progress >= PROJECT_ACCEPTANCE_NO_PROGRESS_LIMIT:
                return False, last_issues
            continue

        # 3) Optional QA tests are useful, but model-authored README claims are soft evidence. Try to
        # generate a valid acceptance suite without making a rejected candidate a hard manifest blocker.
        if (
            not _any_python_test_files(work)
            and _tests_are_desirable(user_request, manifest, work)
            and not _tests_were_requested(user_request, manifest, work)
        ):
            if _maybe_generate_optional_acceptance_test(
                user_request, manifest, work, progress_callback
            ):
                previous_signature = None
                no_progress = 0
                continue

        # 4) REAL validation comes before model semantic opinion: imports/startup/tests/build/type checks.
        _progress(progress_callback, 'Running real project validation...', stage='testing', percent=88)
        real_ok, real_output = _run_real_project_validation(work, user_request, manifest)
        if not real_ok:
            last_issues = [real_output]
            repaired = _repair_real_validation_failure(
                user_request, manifest, work, real_output, progress_callback
            )
            if repaired:
                previous_signature = None
                no_progress = 0
                continue

            signature = tuple(last_issues)
            if signature == previous_signature:
                no_progress += 1
            else:
                no_progress = 0
            previous_signature = signature
            if no_progress >= PROJECT_ACCEPTANCE_NO_PROGRESS_LIMIT:
                return False, last_issues
            continue

        # 5) Evidence-scoped semantic audit is the final QA layer, not the first authority.
        semantic_raw = []
        if QWEN_FILE_AUDIT:
            audit_files = [r for r in _existing_real_source_files(work) if Path(r).name != '__init__.py']
            for idx, rel in enumerate(audit_files, 1):
                _progress(
                    progress_callback,
                    f'Final semantic QA {idx}/{len(audit_files)}: {rel}',
                    stage='auditing',
                    percent=min(94, 89 + int(5 * idx / max(1, len(audit_files)))),
                )
                semantic_raw.extend(_audit_one_file(user_request, manifest, work, rel, progress_callback))

        semantic_grouped = _route_semantic_issues(work, manifest, semantic_raw)
        if semantic_grouped:
            actionable = []
            changed_semantic = False
            for rel, problems in list(semantic_grouped.items())[:PROJECT_SEMANTIC_REPAIR_TARGETS]:
                actionable.extend(f'{rel}: {p}' for p in problems)
                changed_semantic = _repair_file_for_issues(
                    user_request, manifest, work, rel, problems, progress_callback
                ) or changed_semantic

            last_issues = actionable or [
                f"{x.get('file')}: {x.get('problem')}" for x in semantic_raw if x.get('problem')
            ]
            if changed_semantic:
                # A semantic change invalidates the just-passed runtime result. Start a fresh pass.
                previous_signature = None
                no_progress = 0
                continue

            signature = tuple(last_issues)
            if signature == previous_signature:
                no_progress += 1
            else:
                no_progress = 0
            previous_signature = signature
            if no_progress >= PROJECT_ACCEPTANCE_NO_PROGRESS_LIMIT:
                return False, last_issues
            continue

        # Clean deterministic state + real validation + no actionable semantic findings.
        return True, []

    return False, last_issues or ['Acceptance repair budget exhausted before a clean validation pass.']


def _legacy_direct_bootstrap(user_request, max_files, progress_callback=None):
    attempts = [
        ('fileblocks', _direct_bootstrap_prompt_fileblocks(user_request, max_files), 'Bootstrap JARVIS_FILE blocks'),
        ('json', _direct_bootstrap_prompt_json(user_request, max_files), 'Bootstrap JSON fallback'),
    ]
    last_raw = ''
    last_obj = {}
    max_tokens = max(4096, int(os.getenv('JARVIS_QWEN_BOOTSTRAP_MAX_TOKENS', '16384')))

    for style, prompt, stage in attempts:
        ok, text = _qwen_call(prompt, progress_callback, stage, profile='generate', max_tokens=max_tokens, thinking=False, response_schema=QWEN_SCHEMA_BOOTSTRAP if style == 'json' else None, schema_name='legacy_bootstrap', strict_output=(style == 'json'))
        last_raw = str(text or '')
        if not ok:
            continue
        obj, candidates = _parse_direct_project_bootstrap(last_raw)
        candidates = candidates[:max_files]
        if candidates:
            return True, obj, candidates, last_raw
        last_obj = obj or last_obj
    return False, last_obj, [], last_raw


def _direct_new_project_bootstrap(user_request, max_files, progress_callback=None, work=None):
    """V34.1: universal plan -> contracts/skeleton -> dependency implementation, with non-fatal bootstrap recovery."""
    work=Path(work) if work is not None else None
    if work is None: return _legacy_direct_bootstrap(user_request,max_files,progress_callback)
    plan_tokens=max(3072,int(os.getenv('JARVIS_QWEN_PLAN_MAX_TOKENS','6144')))
    planning_brief=_qwen_reasoning_brief(
        "Architect this arbitrary software request. Decide the correct platform/language/framework/native toolchain, repository layout, dependency direction, shared data contracts and exact public interfaces. Do not assume Python.\\n\\nUSER REQUEST:\\n"+user_request,
        progress_callback,'V34 universal architecture reasoning',max_tokens=min(1800,plan_tokens))
    plan_prompt=_project_plan_prompt(user_request,max_files)
    if planning_brief: plan_prompt+='\\n\\nARCHITECTURE REASONING BRIEF (use it; return manifest JSON only):\\n'+planning_brief
    ok,raw_plan=_qwen_call(plan_prompt,progress_callback,'V34 planning universal toolchain/contracts',profile='plan',max_tokens=plan_tokens,thinking=False,response_schema=QWEN_SCHEMA_PROJECT_PLAN,schema_name='project_plan',strict_output=True)
    manifest=_parse_project_plan(raw_plan,user_request,max_files) if ok else None
    recovered=False
    if manifest:
        manifest=_enforce_request_stack_on_manifest(user_request,manifest)
        manifest=_review_project_plan(user_request,manifest,max_files,progress_callback)
        manifest=_enforce_request_stack_on_manifest(user_request,manifest)
    elif V34_BOOTSTRAP_RECOVERY:
        # Do NOT fall back to a README-only repository. Preserve forward progress deterministically.
        recovered=True; manifest=_v34_recovery_manifest(user_request,max_files)
        _append_project_event(work,'v34_plan_recovery','Strict architecture response was unusable; switched to deterministic native-toolchain recovery manifest.',adapter=manifest.get('toolchain_adapter'),plan_error=str(raw_plan or '')[-1200:])
        _progress(progress_callback,f"V34 recovered architecture using {manifest.get('toolchain_adapter')} adapter; continuing instead of aborting bootstrap.",stage='architecting',percent=12)
    if not manifest:
        return False,{},[],str(raw_plan or '')
    valid_paths={str(x.get('path') or '') for x in manifest.get('files') or []}
    for item in manifest.get('files') or []:
        item.setdefault('phase',_v33_infer_phase(item.get('path'),item.get('purpose'))); item.setdefault('contracts',[]); item.setdefault('depends_on',[])
        item['depends_on']=[d for d in item.get('depends_on',[]) if d in valid_paths and d!=item.get('path')]
    manifest.setdefault('architecture_rules',[]); manifest.setdefault('shared_contracts',[])
    manifest=_v34_apply_toolchain_defaults(user_request,manifest)
    _v33_write_architecture(work,manifest)
    skeletons=_v33_materialize_contract_skeletons(work,manifest,progress_callback)
    if recovered: _v34_materialize_recovery_sources(work,manifest,progress_callback)
    _v33_write_build_status(work,manifest,'skeletonized')
    _append_project_event(work,'v34_architecture_committed','Committed universal project contracts/toolchain and visible skeleton before implementation.',adapter=manifest.get('toolchain_adapter'),skeleton_files=len(skeletons),implementation_order=[x.get('path') for x in _v33_dependency_ordered_files(manifest)])
    ordered=_v33_dependency_ordered_files(manifest); total=max(1,len(ordered)); implemented=0
    for idx,item in enumerate(ordered,1):
        rel=str(item.get('path') or ''); _v33_write_build_status(work,manifest,'implementing',current_file=rel,implemented=implemented)
        _progress(progress_callback,f'V34 implementing {idx}/{total} [{item.get("phase","")}] {rel}',stage='generating',percent=min(70,16+int(52*idx/total)),current=idx,total=total)
        file_ok,wrote=_generate_planned_file(user_request,manifest,work,item,progress_callback)
        if not file_ok:
            _append_project_event(work,'file_generation_failed',f'V34 initial implementation did not converge for {rel}; visible skeleton/recovery source remains for acceptance repair.',file=rel,phase=item.get('phase'),depends_on=item.get('depends_on') or [])
            continue
        implemented+=1; _v33_write_build_status(work,manifest,'implementing',current_file=rel,implemented=implemented)
        try:size=(work/wrote).stat().st_size
        except Exception:size=0
        _append_project_event(work,'v34_file_implemented',f'Implemented dependency-ordered file {rel}.',file=rel,bytes=size,implemented=implemented,total=total)
    visible=[]
    for item in manifest.get('files') or []:
        rel=str(item.get('path') or ''); path=work/rel
        if path.exists() and path.is_file() and _looks_text_file(path):
            try: visible.append((rel,path.read_text(encoding='utf-8',errors='replace')))
            except Exception: pass
    # Last-chance invariant: a valid architecture is a recoverable build state, never README-only hard failure.
    if not _existing_real_source_files(work) and V34_BOOTSTRAP_RECOVERY:
        _v34_materialize_recovery_sources(work,manifest,progress_callback)
        visible=[]
        for item in manifest.get('files') or []:
            path=work/str(item.get('path') or '')
            if path.exists() and path.is_file() and _looks_text_file(path):
                visible.append((str(item.get('path')),path.read_text(encoding='utf-8',errors='replace')))
    _v33_write_build_status(work,manifest,'initial_implementation_complete',implemented=implemented)
    return bool(_existing_real_source_files(work)),manifest,visible,str(raw_plan or '')

def _read_json_dict(path):
    try:
        path = Path(path)
        if path.exists() and path.is_file():
            obj = json.loads(path.read_text(encoding='utf-8', errors='replace'))
            if isinstance(obj, dict):
                return obj
    except Exception:
        pass
    return {}


def _resume_request_is_generic(text):
    """True when the new instruction means 'continue/fix what is already here', not a new feature."""
    low = re.sub(r'\s+', ' ', str(text or '').strip().lower())
    if not low:
        return True
    feature_terms = (
        ' add ', ' implement ', ' new feature', ' change ', ' remove ', ' redesign ',
        ' rename ', ' convert ', ' migrate ', ' integrate ', ' support ', ' create a new ',
    )
    padded = f' {low} '
    if any(term in padded for term in feature_terms):
        return False
    generic_terms = (
        'finish', 'complete', 'repair', 'fix', 'continue', 'resume', 'make it work',
        'make this work', 'finish it', 'complete it', 'repair it', 'fix it',
        'finish this project', 'complete this project', 'keep going', 'pick up where',
    )
    return len(low) <= 240 and any(term in low for term in generic_terms)


def _normalize_resume_manifest_files(raw_files):
    out = []
    seen = set()
    if isinstance(raw_files, dict):
        raw_files = [raw_files]
    for item in raw_files or []:
        if isinstance(item, str):
            rel = item
            obj = {'path': rel, 'purpose': 'Existing project file from resume checkpoint', 'exports': []}
        elif isinstance(item, dict):
            rel = str(item.get('path') or item.get('name') or item.get('filename') or '').strip()
            obj = dict(item)
            obj['path'] = rel
            obj.setdefault('purpose', 'Existing project file from resume checkpoint')
            obj.setdefault('exports', [])
        else:
            continue
        try:
            rel = _safe_relative(rel).as_posix()
        except Exception:
            continue
        if not rel or rel == RESUME_METADATA_FILE or _is_sensitive_project_rel(Path(rel)):
            continue
        if rel not in seen:
            seen.add(rel)
            obj['path'] = rel
            out.append(obj)
    return out



def _strip_jarvis_routing_noise(text):
    """Remove Jarvis IPC/profile wrappers so they are not treated as product requirements."""
    raw = str(text or "")
    raw = re.sub(r"\[JARVIS_QWEN_PROFILE\][^\n]*", " ", raw, flags=re.I)
    raw = re.sub(r"\[JARVIS_ATTACHED_FILE\][^\n]*", " ", raw, flags=re.I)
    raw = re.sub(r"use qwen to\s+", " ", raw, flags=re.I)
    return re.sub(r"\s+", " ", raw).strip()


