def _v34_infer_toolchain(text, manifest=None, work=None):
    low = _strip_jarvis_routing_noise(text).lower()
    mf = {k: str((manifest or {}).get(k) or '').lower() for k in ('project_type','platform','language','framework','build_system','package_manager')}
    blob = ' '.join([low] + list(mf.values()))
    # Specific frameworks/platforms before languages.
    checks = [
        ('unreal', ('unreal engine','ue5','ue 5','.uproject','unrealbuildtool')),
        ('unity', ('unity game','unity3d','unity engine')),
        ('android_gradle', ('android','android studio','android app','native android','android sdk','jetpack compose')),
        ('ios_xcode', ('ios app','iphone app','ipad app','swiftui ios','native iphone','xcode project')),
        ('macos_xcode', ('macos app','mac app','swiftui macos')),
        ('flutter', ('flutter','dart app')),
        ('react_native', ('react native','expo app')),
        ('nextjs', ('next.js','nextjs')),
        ('angular', ('angular','angular-cli')),
        ('vue', ('vue.js','vuejs','vue ')),
        ('react', ('react app','react website','react web','vite react')),
        ('electron', ('electron app','electron desktop')),
        ('rust', ('rust','cargo')),
        ('go', ('golang','go module','go app','go api','go service','go cli','written in go','language go')),
        ('dotnet', ('c#','.net','dotnet','wpf','winforms','maui')),
        ('cpp_cmake', ('c++','cpp','cmake','qt app','qt6','qt5')),
        ('kotlin_gradle', ('kotlin','kotlin/jvm')),
        ('java_maven', ('maven','pom.xml')),
        ('java_gradle', ('java','gradle','spring boot')),
        ('swiftpm', ('swift package','swiftpm','swift application',' swift ')),
        ('php_composer', ('php','composer','laravel','symfony')),
        ('ruby_bundler', ('ruby','rails','sinatra','bundler')),
        ('python_desktop', ('tkinter','pyqt','pyside','python desktop','desktop app in python')),
        ('python', ('python','flask','django','fastapi','pygame')),
        ('node', ('node.js','nodejs','express','javascript server','typescript server')),
        ('static_web', ('web page','webpage','landing page','static website','html css','html/javascript')),
    ]
    for adapter, terms in checks:
        if any(t in blob for t in terms): return adapter
    # Generic product hints when user did not specify a stack.
    if any(t in blob for t in ('website','browser app','web app','calculator web')): return 'static_web'
    if any(t in blob for t in ('mobile app','phone app','cross-platform mobile')): return 'flutter'
    if any(t in blob for t in ('desktop application','desktop app','calculator','utility app')): return 'python_desktop'
    # Workspace evidence wins for recovery/resume.
    if work:
        root=Path(work)
        if next(iter(root.rglob('*.uproject')),None): return 'unreal'
        if (root/'ProjectSettings'/'ProjectVersion.txt').exists(): return 'unity'
        if next(iter(root.rglob('pubspec.yaml')),None): return 'flutter'
        if next(iter(root.rglob('Cargo.toml')),None): return 'rust'
        if next(iter(root.rglob('go.mod')),None): return 'go'
        if next(iter(root.rglob('*.csproj')),None): return 'dotnet'
        if next(iter(root.rglob('Package.swift')),None): return 'swiftpm'
        if next(iter(root.rglob('package.json')),None): return 'node'
    return 'generic'


def _v34_generic_language_info(text, manifest=None):
    blob=(' '.join([_strip_jarvis_routing_noise(text)] + [str((manifest or {}).get(k) or '') for k in ('language','framework','build_system')])).lower()
    choices=[('zig','.zig','zig'),('haskell','.hs','ghc'),('lua','.lua','lua'),('elixir','.exs','elixir'),('scala','.scala','scala'),('solidity','.sol','solc'),('powershell','.ps1','powershell'),('bash','.sh','bash'),('perl','.pl','perl'),('r language','.r','Rscript'),('f#','.fsx','dotnet')]
    for key,ext,exe in choices:
        if key in blob: return key,ext,exe
    lang=str((manifest or {}).get('language') or 'generic').strip() or 'generic'
    return lang,'.txt',''


def _v34_apply_toolchain_defaults(user_request, manifest):
    manifest=dict(manifest or {})
    adapter=_v34_infer_toolchain(user_request, manifest)
    manifest['toolchain_adapter']=adapter
    spec=_v34_toolchain_catalog().get(adapter,{})
    for key in ('platform','language','framework','build_system','package_manager','dependency_command','build_command','test_command','run_command'):
        if not str(manifest.get(key) or '').strip() and spec.get(key) is not None: manifest[key]=spec.get(key,'')
    if not manifest.get('required_tools'): manifest['required_tools']=list(spec.get('required_tools') or [])
    return manifest


