def _v34_seed_source(rel, adapter):
    ext=Path(rel).suffix.lower(); marker=V34_RECOVERY_SEED_MARKER
    if ext in ('.py','.pyw'): return f'# {marker}\\n"""Recovery seed: replace with the complete requested implementation."""\\n\\ndef main():\\n    print("Jarvis recovery seed")\\n\\nif __name__ == "__main__":\\n    main()\\n'
    if ext in ('.js','.mjs','.cjs','.jsx','.ts','.tsx'): return f'// {marker}\\nconsole.log("Jarvis recovery seed");\\n'
    if ext in ('.c','.cc','.cpp','.cxx'): return f'// {marker}\\n#include <iostream>\\nint main() {{ std::cout << "Jarvis recovery seed\\\\n"; return 0; }}\\n'
    if ext=='.rs': return f'// {marker}\\nfn main() {{ println!("Jarvis recovery seed"); }}\\n'
    if ext=='.go': return f'// {marker}\\npackage main\\nimport "fmt"\\nfunc main() {{ fmt.Println("Jarvis recovery seed") }}\\n'
    if ext=='.cs': return f'// {marker}\\nusing System; public static class Program {{ public static void Main() {{ Console.WriteLine("Jarvis recovery seed"); }} }}\\n'
    if ext=='.java': return f'// {marker}\\npackage com.jarvis.app; public class Main {{ public static void main(String[] args) {{ System.out.println("Jarvis recovery seed"); }} }}\\n'
    if ext in ('.kt','.kts'): return f'// {marker}\\nfun main() {{ println("Jarvis recovery seed") }}\\n'
    if ext=='.dart': return f'// {marker}\\nvoid main() {{ print("Jarvis recovery seed"); }}\\n'
    if ext=='.swift': return f'// {marker}\\nimport Foundation\\nprint("Jarvis recovery seed")\\n'
    if ext=='.php': return f'<?php // {marker}\\necho "Jarvis recovery seed";\\n'
    if ext=='.rb': return f'# {marker}\\nputs "Jarvis recovery seed"\\n'
    if ext=='.html': return f'<!-- {marker} --><!doctype html><html><body><main>Jarvis recovery seed</main></body></html>\\n'
    if ext in ('.vue','.svelte'): return f'<!-- {marker} --><template><main>Jarvis recovery seed</main></template>\\n'
    prefix='//' if ext not in ('.sh','.ps1','.r','.pl','.hs','.lua','.ex','.exs') else '#'
    return f'{prefix} {marker}\\n'


def _v34_recovery_config_content(rel, manifest):
    """Minimal syntactically valid native build metadata. Source still carries the hard recovery marker."""
    name=Path(rel).name.lower(); adapter=str(manifest.get('toolchain_adapter') or '')
    project=re.sub(r'[^A-Za-z0-9_]+','_',str(manifest.get('project_name') or 'JarvisProject')).strip('_') or 'JarvisProject'
    if name=='requirements.txt': return ''
    if name=='package.json':
        scripts={'start':'node src/index.js'}
        if adapter in ('react','vue','angular','nextjs'): scripts={'start':'vite','dev':'vite','build':'vite build','test':'echo No tests configured'}
        if adapter=='electron': scripts={'start':'electron .','build':'echo Build configured during implementation','test':'echo No tests configured'}
        if adapter=='react_native': scripts={'start':'react-native start','test':'jest'}
        return json.dumps({'name':_slug(project),'version':'0.1.0','private':True,'scripts':scripts,'dependencies':{},'devDependencies':{}},indent=2)+'\n'
    if name=='cmakelists.txt': return f'cmake_minimum_required(VERSION 3.16)\nproject({project} LANGUAGES CXX)\nset(CMAKE_CXX_STANDARD 17)\nadd_executable({project} src/main.cpp src/app.cpp)\n'
    if name=='cargo.toml': return f'[package]\nname = "{_slug(project)}"\nversion = "0.1.0"\nedition = "2021"\n\n[dependencies]\n'
    if name=='go.mod': return f'module jarvis.local/{_slug(project)}\n\ngo 1.22\n'
    if name.endswith('.csproj'): return '<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net8.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>enable</Nullable></PropertyGroup></Project>\n'
    if name=='settings.gradle.kts': return f'rootProject.name = "{project}"\n' + ('include(":app")\n' if adapter=='android_gradle' else '')
    if name=='settings.gradle': return f'rootProject.name = "{project}"\n' + ('include ":app"\n' if adapter=='android_gradle' else '')
    if name=='build.gradle.kts':
        if '/app/' in ('/'+rel.replace('\\','/').lower()+'/') or rel.replace('\\','/').lower().startswith('app/'):
            return 'plugins { id("com.android.application") }\nandroid { namespace = "com.jarvis.app"; compileSdk = 35\n defaultConfig { applicationId = "com.jarvis.app"; minSdk = 24; targetSdk = 35; versionCode = 1; versionName = "1.0" } }\n'
        if adapter=='android_gradle': return 'plugins { id("com.android.application") version "8.7.0" apply false; kotlin("android") version "2.0.21" apply false }\n'
        if adapter=='kotlin_gradle': return 'plugins { kotlin("jvm") version "2.0.21"; application }\nrepositories { mavenCentral() }\napplication { mainClass.set("com.jarvis.app.MainKt") }\n'
        return 'plugins { application; java }\nrepositories { mavenCentral() }\napplication { mainClass.set("com.jarvis.app.Main") }\n'
    if name=='build.gradle': return 'plugins { id "application"; id "java" }\nrepositories { mavenCentral() }\n'
    if name=='pom.xml': return f'<project xmlns="http://maven.apache.org/POM/4.0.0"><modelVersion>4.0.0</modelVersion><groupId>com.jarvis</groupId><artifactId>{_slug(project)}</artifactId><version>0.1.0</version><properties><maven.compiler.source>17</maven.compiler.source><maven.compiler.target>17</maven.compiler.target></properties></project>\n'
    if name=='pubspec.yaml': return f'name: {_slug(project).replace("-","_")}\ndescription: Jarvis recovery scaffold\nversion: 0.1.0+1\nenvironment:\n  sdk: ">=3.0.0 <4.0.0"\ndependencies:\n  flutter:\n    sdk: flutter\ndev_dependencies:\n  flutter_test:\n    sdk: flutter\nflutter:\n  uses-material-design: true\n'
    if name=='package.swift': return f'// swift-tools-version: 5.9\nimport PackageDescription\nlet package = Package(name: "{project}", targets: [.executableTarget(name: "App")])\n'
    if name.endswith('.uproject'): return json.dumps({'FileVersion':3,'EngineAssociation':'5.0','Category':'','Description':'Jarvis recovery scaffold','Modules':[{'Name':'JarvisProject','Type':'Runtime','LoadingPhase':'Default'}]},indent=2)+'\n'
    if name=='projectversion.txt': return 'm_EditorVersion: 2022.3.0f1\n'
    if name=='composer.json': return json.dumps({'name':'jarvis/'+_slug(project),'require':{}},indent=2)+'\n'
    if name=='gemfile': return 'source "https://rubygems.org"\n'
    if name=='project.yml': return f'name: {project}\noptions:\n  bundleIdPrefix: com.jarvis\ntargets:\n  {project}:\n    type: application\n    platform: iOS\n    sources: [App]\n'
    if name=='angular.json': return json.dumps({'version':1,'projects':{}},indent=2)+'\n'
    if name.endswith('.xml') and 'androidmanifest' in name: return '<manifest xmlns:android="http://schemas.android.com/apk/res/android"><application android:theme="@style/AppTheme"><activity android:name=".MainActivity" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity></application></manifest>\n'
    return None

def _v34_materialize_recovery_sources(work, manifest, progress_callback=None):
    root=Path(work); adapter=str(manifest.get('toolchain_adapter') or _v34_infer_toolchain('',manifest)); created=[]
    # First create source shells and minimal native build metadata; then guarantee real source.
    _v33_materialize_contract_skeletons(root, manifest, progress_callback)
    # Recovery shells carry a second hard marker so acceptance can distinguish model-planned shells from emergency bootstrap recovery.
    for item in manifest.get('files') or []:
        rel=str(item.get('path') or ''); target=root/rel
        if target.exists() and _is_real_source_rel(Path(rel)):
            try:
                txt=target.read_text(encoding='utf-8',errors='replace')
                if V34_RECOVERY_SEED_MARKER not in txt[:800]:
                    suf=target.suffix.lower()
                    prefix=('<!-- '+V34_RECOVERY_SEED_MARKER+' -->\n') if suf in {'.html','.htm','.vue','.svelte'} else (('/* '+V34_RECOVERY_SEED_MARKER+' */\n') if suf in {'.css','.scss','.less'} else (('# '+V34_RECOVERY_SEED_MARKER+'\n') if suf in {'.py','.pyw','.rb','.sh','.bash','.ps1','.r','.pl'} else ('// '+V34_RECOVERY_SEED_MARKER+'\n')))
                    target.write_text(prefix+txt,encoding='utf-8')
            except Exception: pass
    for item in manifest.get('files') or []:
        rel=str(item.get('path') or ''); target=root/rel
        if target.exists(): continue
        cfg=_v34_recovery_config_content(rel, manifest)
        if cfg is not None:
            target.parent.mkdir(parents=True,exist_ok=True); target.write_text(cfg,encoding='utf-8'); created.append(rel)
    for item in manifest.get('files') or []:
        rel=str(item.get('path') or ''); target=root/rel
        if not _is_real_source_rel(Path(rel)): continue
        if target.exists() and target.stat().st_size>0: continue
        target.parent.mkdir(parents=True,exist_ok=True); target.write_text(_v34_seed_source(rel,adapter),encoding='utf-8'); created.append(rel)
    if not _existing_real_source_files(root):
        lang,ext,_=_v34_generic_language_info('',manifest); rel='src/main'+(ext if ext!='.txt' else '.py')
        target=root/rel; target.parent.mkdir(parents=True,exist_ok=True); target.write_text(_v34_seed_source(rel,adapter),encoding='utf-8'); created.append(rel)
        manifest.setdefault('files',[]).append({'path':rel,'purpose':'V34 recovery entrypoint; replace during acceptance','phase':'integration','depends_on':[],'exports':[],'contracts':[]}); manifest['entrypoint']=rel
    try: (root/V34_TOOLCHAIN_FILE).write_text(json.dumps({'version':'V34.1','adapter':adapter,'manifest':{k:manifest.get(k) for k in ('platform','language','framework','build_system','package_manager','required_tools','dependency_command','build_command','test_command','run_command')}},indent=2),encoding='utf-8')
    except Exception: pass
    _append_project_event(root,'v34_bootstrap_recovery','Materialized conventional recovery architecture/source after model bootstrap failure.',adapter=adapter,created=created[:40])
    return created


_V34_SAFE_COMMANDS={'python','python3','py','pip','pip3','npm','npx','node','pnpm','yarn','bun','cmake','ctest','cargo','rustc','go','dotnet','java','javac','gradle','gradlew','gradlew.bat','mvn','mvnw','mvnw.cmd','flutter','dart','swift','xcodebuild','composer','php','bundle','ruby','rake','zig','ghc','cabal','stack','lua','elixir','mix','scala','sbt','rscript','powershell','pwsh','bash','perl','solc'}
def _v34_split_command(command):
    raw=str(command or '').strip()
    if not raw: return []
    if any(x in raw for x in ('&&','||',';','|','>','<','`','$(')): return []
    try: parts=shlex.split(raw,posix=os.name!='nt')
    except Exception: return []
    if not parts: return []
    exe=Path(parts[0].strip('"')).name.lower()
    if exe not in _V34_SAFE_COMMANDS: return []
    return parts


def _v34_run_declared_command(work, command, label):
    parts=_v34_split_command(command)
    if not parts: return False, f'{label} is empty or not allowed for automatic execution: {command}'
    exe=parts[0]
    # Prefer project wrappers.
    if exe.lower() in ('gradlew','gradlew.bat','mvnw','mvnw.cmd'):
        local=Path(work)/exe
        if local.exists(): parts[0]=str(local)
    elif not shutil.which(exe): return False, f'{label} requires tool not installed/available: {exe}'
    return _run_command(parts, work, PROJECT_BUILD_TIMEOUT)

def _infer_tech_stack_from_text(text):
    adapter=_v34_infer_toolchain(text)
    spec=_v34_toolchain_catalog().get(adapter,{})
    return {'adapter':adapter,'language':spec.get('language') or None,'ui':spec.get('framework') or None,'storage':None,'domain':None,'platform':spec.get('platform') or None,'build_system':spec.get('build_system') or None,'forbidden':set(),'required_tokens':[]}

def _infer_tech_stack_from_workspace(work):
    adapter=_v34_infer_toolchain('',{},work)
    spec=_v34_toolchain_catalog().get(adapter,{})
    return {'adapter':adapter,'language':spec.get('language') or None,'ui':spec.get('framework') or None,'storage':None,'domain':None,'platform':spec.get('platform') or None,'build_system':spec.get('build_system') or None,'evidence':[adapter] if adapter!='generic' else []}

def _tech_stack_mismatch(requested, actual):
    if not requested or not actual: return []
    req=str(requested.get('adapter') or 'generic'); act=str(actual.get('adapter') or 'generic')
    if req=='generic' or act=='generic': return []
    families=[{'node','react','nextjs','vue','angular','electron','react_native'},{'java_gradle','java_maven','kotlin_gradle','android_gradle'},{'dotnet','unity'},{'swiftpm','ios_xcode','macos_xcode'}]
    if req==act or any(req in f and act in f for f in families): return []
    return [f'toolchain:{req}!={act}']

def _stack_lock_instructions(user_request):
    adapter=_v34_infer_toolchain(user_request)
    if adapter=='generic':
        return ("TOOLCHAIN POLICY: No familiar stack was explicit. Infer the most appropriate technology from the product requirements; "
                "do not silently default to Python. Declare the chosen language/framework/platform/build system and use its conventional repository layout.\n")
    spec=_v34_toolchain_catalog().get(adapter,{})
    return ("TOOLCHAIN INTENT (preserve explicit user choices; otherwise architecture review may refine):\n"
            f"- Adapter: {adapter}\n- Platform: {spec.get('platform','')}\n- Language: {spec.get('language','')}\n"
            f"- Framework/toolchain: {spec.get('framework','')} / {spec.get('build_system','')}\n"
            "- Use this ecosystem's native build system; do not substitute an unrelated stack.\n")

def _purge_mismatched_stack_files(work, requested_stack, progress_callback=None):
    """Delete workspace files that belong to a contradictory tech stack before rebuild."""
    work = Path(work)
    removed = []
    req_lang = (requested_stack or {}).get("language")
    req_dom = (requested_stack or {}).get("domain")
    for path in sorted(work.rglob("*")):
        if not path.is_file():
            continue
        try:
            rel = path.relative_to(work).as_posix()
        except Exception:
            continue
        if rel.startswith(".jarvis") or path.name.startswith("JARVIS_") or path.name == RESUME_METADATA_FILE:
            continue
        name = path.name.lower()
        suf = path.suffix.lower()
        drop = False
        if req_lang == "python" and suf in {".java", ".class", ".jar"}:
            drop = True
        if req_lang == "python" and name in {"pom.xml", "build.gradle", "build.gradle.kts"}:
            drop = True
        if req_dom == "inventory" and any(
            t in name for t in ("tensorflow", "qwenmodelloader", "stockpredictor", "modelloader")
        ):
            drop = True
        if drop:
            try:
                path.unlink()
                removed.append(rel)
            except Exception:
                pass
    # Remove empty java package dirs
    for path in sorted(work.rglob("*"), reverse=True):
        if path.is_dir():
            try:
                next(path.iterdir())
            except StopIteration:
                try:
                    path.rmdir()
                except Exception:
                    pass
            except Exception:
                pass
    if removed:
        _append_project_event(
            work,
            "stack_mismatch_purged",
            "Removed files from a contradictory tech stack before rebuilding.",
            files=removed[:40],
        )
        _progress(progress_callback, f"Purged {len(removed)} mismatched stack files before rebuild.", stage="resuming")
    return removed



def _enforce_request_stack_on_manifest(user_request, manifest):
    manifest=_v34_apply_toolchain_defaults(user_request, dict(manifest or {}))
    adapter=manifest.get('toolchain_adapter') or 'generic'
    # Only coerce when the user explicitly named a recognizable stack. Generic requests remain architect-driven.
    explicit=_v34_infer_toolchain(user_request)
    if explicit!='generic':
        spec=_v34_toolchain_catalog().get(explicit,{})
        manifest['toolchain_adapter']=explicit
        for key in ('platform','language','framework','build_system','package_manager'):
            if spec.get(key): manifest[key]=spec[key]
        if not manifest.get('required_tools'): manifest['required_tools']=list(spec.get('required_tools') or [])
    return manifest

def _resume_seed_from_workspace(work, source_zip, user_request):
    """Recover the original goal/manifest from a V26 checkpoint or older Jarvis diagnostics."""
    work = Path(work)
    force_rebuild = False
    requested_stack = {}
    actual_stack = {}
    checkpoint = _read_json_dict(work / RESUME_METADATA_FILE)
    generation = _read_json_dict(work / 'JARVIS_GENERATION.json')
    state = _load_project_state(work)

    original_request = str(
        checkpoint.get('original_request')
        or checkpoint.get('user_request')
        or generation.get('request')
        or state.get('user_request')
        or ''
    ).strip()
    latest = str(user_request or '').strip()
    generic = _resume_request_is_generic(latest)

    if original_request and generic:
        effective_request = original_request
    elif original_request and latest and latest != original_request:
        effective_request = (
            original_request
            + '\n\nRESUME / EDIT INSTRUCTION FOR THIS PASS:\n'
            + latest
        )
    elif original_request:
        effective_request = original_request
    elif latest and not generic:
        effective_request = latest
    else:
        effective_request = (
            'Finish and repair the existing project without changing its intended behavior. '
            'Preserve working features, make the project runnable, and make its existing tests/build pass.'
        )

    
    # Detect tech-stack drift (e.g. Java/TF predictor vs requested Python inventory app).
    requested_stack = _infer_tech_stack_from_text(original_request or latest)
    # If the original checkpoint request was itself a generic "finish this", prefer the
    # latest non-generic instruction for stack inference.
    if not requested_stack.get("language") and not requested_stack.get("domain"):
        requested_stack = _infer_tech_stack_from_text(latest)
    actual_stack = _infer_tech_stack_from_workspace(work)
    stack_reasons = _tech_stack_mismatch(requested_stack, actual_stack)
    force_rebuild = bool(stack_reasons)
    if force_rebuild:
        _append_project_event(
            work,
            "stack_mismatch_detected",
            "Workspace tech stack contradicts the user request; forcing rebuild instead of local repair.",
            reasons=stack_reasons,
            requested= {k: (list(v) if isinstance(v, set) else v) for k, v in requested_stack.items()},
            actual=actual_stack,
        )
        # Prefer the richest request text that still encodes the intended product.
        base = original_request if len(original_request) > len(latest) else (latest or original_request)
        # If both are generic finish messages, keep whatever we have but still rebuild after purge.
        effective_request = (
            _strip_jarvis_routing_noise(base)
            + "\n\n"
            + _stack_lock_instructions(base or latest)
            + "\nRebuild the correct project from these requirements. "
              "Delete or ignore any existing files that use the wrong language or domain."
        )
        generic = False  # allow focused rewrite / regeneration path

    raw_manifest = checkpoint.get('manifest') if isinstance(checkpoint.get('manifest'), dict) else {}
    if not raw_manifest:
        raw_manifest = {
            'project_name': generation.get('project_name') or _slug(Path(source_zip).stem),
            'summary': generation.get('summary') or 'Existing project being resumed and revalidated',
            'project_type': generation.get('project_type') or 'other',
            'entrypoint': generation.get('entrypoint') or '',
            'run_command': generation.get('run_command') or '',
            'acceptance_criteria': generation.get('acceptance_criteria') or state.get('acceptance_criteria') or [],
            'files': generation.get('files') or state.get('files_indexed') or [],
        }

    manifest = dict(raw_manifest)
    manifest['project_name'] = _slug(manifest.get('project_name') or Path(source_zip).stem)
    manifest['summary'] = str(manifest.get('summary') or 'Existing project being resumed and revalidated')
    files = _normalize_resume_manifest_files(manifest.get('files') or [])

    # Preserve every real/existing source/text file even if older metadata did not know about it.
    known = {str(x.get('path') or '') for x in files}
    for rel in _existing_project_text_files(work):
        if rel == RESUME_METADATA_FILE or rel in known or _is_sensitive_project_rel(Path(rel)):
            continue
        if Path(rel).name in _RESERVED_OUTPUT_NAMES or Path(rel).name.startswith('JARVIS_'):
            continue
        files.append({'path': rel, 'purpose': 'Existing project file; preserve unless a proven repair requires a change', 'exports': []})
        known.add(rel)
    manifest['files'] = files

    completed = _existing_project_text_files(work)
    if not manifest.get('entrypoint') or not (work / str(manifest.get('entrypoint'))).exists():
        manifest['entrypoint'] = _pick_entrypoint(manifest, completed)

    if not manifest.get('project_type'):
        suffixes = {Path(x).suffix.lower() for x in _existing_real_source_files(work)}
        manifest['project_type'] = 'python' if suffixes.intersection({'.py', '.pyw'}) else 'other'

    criteria = manifest.get('acceptance_criteria') or checkpoint.get('acceptance_criteria') or state.get('acceptance_criteria') or []
    if isinstance(criteria, str):
        criteria = [criteria]
    criteria = [str(x).strip() for x in criteria if str(x).strip()]
    if not criteria:
        criteria = [effective_request]
    if latest and not generic and latest not in criteria:
        criteria.append(latest)
    manifest['acceptance_criteria'] = criteria[:40]

    prior_issues = checkpoint.get('unresolved_issues') or state.get('unresolved_requirements') or []
    if isinstance(prior_issues, str):
        prior_issues = [prior_issues]
    resume_count = int(checkpoint.get('resume_count') or 0) + 1
    return {
        'manifest': manifest,
        'effective_request': effective_request,
        'original_request': original_request or effective_request,
        'latest_instruction': latest,
        'generic_resume': generic,
        'prior_issues': [str(x) for x in prior_issues if str(x).strip()][:50],
        'resume_count': resume_count,
        'checkpoint_found': bool(checkpoint),
    }


def _resume_issue_key(item):
    return (
        str(item.get('file') or ''),
        str(item.get('kind') or ''),
        _stable_issue_problem(item.get('problem') or ''),
    )


def _resume_validation_snapshot(work, manifest, user_request, include_real=True):
    work = Path(work)
    deterministic = _deterministic_acceptance_issues(work, manifest)
    weights = {
        'missing': 120, 'static': 120, 'incomplete': 60, 'contract': 45,
        'identity': 45, 'dependency': 45, 'data_contract': 45,
        'call_signature': 40, 'method_contract': 40, 'definite_none': 40,
        'generated_test_undefined_name': 12, 'generated_test_isolation': 12,
        'generated_test_signature': 12, 'generated_test_contract': 12,
    }
    weighted = sum(weights.get(str(x.get('kind') or ''), 25) for x in deterministic)
    real_ok = None
    real_output = ''
    if include_real and not deterministic:
        try:
            real_ok, real_output = _run_real_project_validation(work, user_request, manifest)
        except Exception as exc:
            real_ok, real_output = False, f'Real validation raised: {exc}'
        if not real_ok:
            weighted += 80

    issue_files = sorted({str(x.get('file') or '') for x in deterministic if str(x.get('file') or '')})
    hashes = {}
    for rel in _existing_real_source_files(work):
        try:
            hashes[rel] = hashlib.sha256((work / rel).read_bytes()).hexdigest()
        except Exception:
            pass
    stable_keys = sorted(_resume_issue_key(x) for x in deterministic)
    # Lower is better. Progress is phase-aware:
    #   0 = deterministic clean + real validation passed
    #   1 = deterministic clean but runtime/tests/build still fail (deeper progress)
    #   2 = deterministic/static defects still remain
    # This lets a resume pass promote a project that moves from syntax/API defects into a
    # narrower runtime failure instead of treating the newly-revealed runtime failure as worse.
    if real_ok is True and not deterministic:
        phase_rank = 0
    elif not deterministic:
        phase_rank = 1
    else:
        phase_rank = 2
    score = (phase_rank, weighted, len(deterministic))
    return {
        'score': score,
        'real_ok': real_ok,
        'real_output': str(real_output or '')[:12000],
        'deterministic_issues': deterministic,
        'stable_issue_keys': stable_keys,
        'issue_files': issue_files,
        'hashes': hashes,
        'weighted_issues': weighted,
        'issue_count': len(deterministic),
    }


def _resume_snapshot_summary(snapshot):
    return {
        'score': list(snapshot.get('score') or ()),
        'real_ok': snapshot.get('real_ok'),
        'weighted_issues': snapshot.get('weighted_issues', 0),
        'issue_count': snapshot.get('issue_count', 0),
        'issue_files': list(snapshot.get('issue_files') or [])[:40],
    }


def _resume_protected_regressions(before, after):
    """Reject only NEW deterministic defects in previously clean files that the trial actually changed."""
    before_issue_files = set(before.get('issue_files') or [])
    before_keys = set(tuple(x) for x in before.get('stable_issue_keys') or [])
    before_hashes = before.get('hashes') or {}
    after_hashes = after.get('hashes') or {}
    changed_clean_files = {
        rel for rel, digest in before_hashes.items()
        if rel not in before_issue_files and after_hashes.get(rel) not in {None, digest}
    }
    regressions = []
    for item in after.get('deterministic_issues') or []:
        key = _resume_issue_key(item)
        rel = str(item.get('file') or '')
        if rel in changed_clean_files and key not in before_keys:
            regressions.append(
                f"{rel}: {item.get('problem') or 'new deterministic defect'}"
            )
    return regressions


def _copy_resume_workspace(src, dst):
    src = Path(src)
    dst = Path(dst)
    if dst.exists():
        shutil.rmtree(dst, ignore_errors=True)
    ignore = shutil.ignore_patterns(
        '.git', '.svn', '.hg', 'node_modules', '__pycache__', '.pytest_cache',
        '.mypy_cache', '.ruff_cache', '.venv', 'venv', 'env', '.jarvis_build', '.jarvis_candidates',
        '.jarvis_runtime', '.jarvis_failures', '.jarvis_backups', '.cache', 'coverage', '.turbo',
        '.parcel-cache', '.angular', '.svelte-kit', 'dist', 'build', 'target', '.next', '.nuxt',
        'DerivedData', 'Pods', 'out', 'bin', 'obj',
    )
    copy_source_tree(src, dst, ignore=ignore)
    return dst


def _commit_resume_trial(trial, work, checkpoint_dir=None):
    trial = Path(trial)
    work = Path(work)
    if checkpoint_dir is not None and RESUME_KEEP_WORKSPACE_CHECKPOINTS and work.exists():
        checkpoint_dir = Path(checkpoint_dir)
        _copy_resume_workspace(work, checkpoint_dir)
    if work.exists():
        shutil.rmtree(work, ignore_errors=True)
    shutil.move(str(trial), str(work))


def _package_resume_checkpoint_zip(
    work, manifest, original_request, latest_instruction, unresolved_issues,
    source_zip_name='', resume_count=1, snapshot=None, stamp=None,
):
    """Package the BEST CURRENT SOURCE as an explicitly incomplete, resumable checkpoint."""
    work = Path(work)
    stamp = stamp or datetime.now().strftime('%Y%m%d_%H%M%S')
    project_name = _slug((manifest or {}).get('project_name') or work.name or 'project')
    out, count = _package_workspace_zip(work, f'{project_name}_CHECKPOINT', stamp)
    snapshot = snapshot or {}
    issue_files = set(snapshot.get('issue_files') or [])
    passing_files = [rel for rel in _existing_real_source_files(work) if rel not in issue_files]
    metadata = {
        'schema_version': RESUME_SCHEMA_VERSION,
        'status': 'checkpoint_incomplete',
        'created_at': _utc_stamp(),
        'resume_count': int(resume_count or 1),
        'source_zip_name': Path(str(source_zip_name or '')).name,
        'original_request': str(original_request or ''),
        'latest_instruction': str(latest_instruction or ''),
        'acceptance_criteria': list((manifest or {}).get('acceptance_criteria') or []),
        'manifest': manifest or {},
        'unresolved_issues': [str(x) for x in (unresolved_issues or []) if str(x).strip()][:80],
        'validation_snapshot': _resume_snapshot_summary(snapshot),
        'passing_real_source_files': passing_files[:200],
        'note': (
            'This is an INCOMPLETE Jarvis checkpoint, not a verified final project. '
            'Attach this ZIP to Jarvis and ask to finish/repair/continue it.'
        ),
    }
    with zipfile.ZipFile(out, 'a', compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr(RESUME_METADATA_FILE, json.dumps(metadata, indent=2, ensure_ascii=False))
    return out, count + 1


def _checkpoint_failure_result(
    prefix, work, manifest, original_request, latest_instruction, issues,
    source_zip_name='', resume_count=1, snapshot=None, stamp=None,
):
    try:
        if not _existing_real_source_files(work):
            return False, f'{prefix} No real source files exist to checkpoint. Diagnostic workspace: {work}', None
        checkpoint, count = _package_resume_checkpoint_zip(
            work, manifest, original_request, latest_instruction, issues,
            source_zip_name=source_zip_name, resume_count=resume_count,
            snapshot=snapshot, stamp=stamp,
        )
        return False, (
            f'{prefix} A RESUMABLE CHECKPOINT ZIP was saved with {count} files. '
            'It is NOT a verified final project. Attach that checkpoint ZIP to Jarvis and say '
            '"finish this project" to continue from this exact codebase. '
            f'Remaining: {"; ".join([str(x) for x in (issues or [])][:12])}. '
            f'Diagnostic workspace: {work}'
        ), checkpoint
    except Exception as exc:
        return False, f'{prefix} Checkpoint packaging also failed: {exc}. Diagnostic workspace: {work}', None


def _v4258_preserve_rejected_trial_evidence(work, trial, sweep, acceptance_issues, trial_snapshot, best_snapshot, regressions):
    """Persist bounded diagnostics from a disposable resume trial before deletion.

    Source from an unpromoted trial is never copied back. Only rejection metadata,
    model-response receipts/hashes and the functional transaction ledger survive,
    so the next resume can diagnose non-progress without treating rejected code as
    authoritative project state.
    """
    work, trial = Path(work), Path(trial)
    payload = {
        'version':'V42.58.0', 'engine':'CONNECTED_CLUSTER_FUNCTIONAL_TRANSACTIONS_FACTORY',
        'updated_at':_utc_stamp(), 'sweep':int(sweep),
        'policy':'retain bounded rejection evidence only; never promote rejected trial source',
        'candidate_snapshot':_resume_snapshot_summary(trial_snapshot or {}),
        'best_snapshot':_resume_snapshot_summary(best_snapshot or {}),
        'regressions':list(regressions or [])[:24],
        'acceptance_issues':[str(x)[:3000] for x in (acceptance_issues or [])[-24:]],
        'transaction_ledger':{}, 'model_responses':[],
    }
    ledger = trial/'JARVIS_V4251_FUNCTIONAL_TRANSACTIONS.json'
    try:
        if ledger.is_file(): payload['transaction_ledger']=json.loads(ledger.read_text(encoding='utf-8',errors='replace'))
    except Exception as exc:
        payload['transaction_ledger_error']=str(exc)[:1200]
    folder = trial/'.jarvis_failures'/'model_outputs'
    if folder.is_dir():
        for path in sorted(folder.glob('v4255_*.json'), key=lambda x:x.stat().st_mtime)[-24:]:
            try:
                row=json.loads(path.read_text(encoding='utf-8',errors='replace'))
                payload['model_responses'].append({
                    'file':path.name, 'target':row.get('target'), 'attempt':row.get('attempt'),
                    'status':row.get('status'), 'error':str(row.get('error') or '')[-3000:],
                    'response_chars':row.get('response_chars'), 'response_sha256':row.get('response_sha256'),
                    'transport':row.get('transport') or {}, 'supplied_source_sha256':row.get('supplied_source_sha256') or {},
                })
            except Exception: pass
    out=work/'JARVIS_V4258_REJECTED_TRIAL_EVIDENCE.json'
    try:
        previous=[]
        if out.is_file():
            old=json.loads(out.read_text(encoding='utf-8',errors='replace'))
            previous=list(old.get('trials') or []) if isinstance(old,dict) else []
        trials=(previous+[payload])[-8:]
        tmp=out.with_suffix(out.suffix+'.tmp')
        tmp.write_text(json.dumps({'version':'V42.58.0','trials':trials},ensure_ascii=False,indent=2,default=str),encoding='utf-8')
        os.replace(tmp,out)
    except Exception:
        pass


def _run_resume_sweeps(
    user_request, manifest, work, job_root, progress_callback=None,
    generic_resume=True, prior_issues=None, max_sweeps=None,
):
    """Run acceptance on disposable copies and only commit successful or objectively improved states."""
    work = Path(work)
    job_root = Path(job_root)
    sweeps = max(1, int(max_sweeps or RESUME_SWEEPS))
    best_snapshot = _resume_validation_snapshot(work, manifest, user_request, include_real=True)
    best_issues = list(prior_issues or [])
    if not best_issues:
        best_issues = [
            f"{x.get('file')}: {x.get('problem')}" if x.get('file') else str(x.get('problem') or '')
            for x in best_snapshot.get('deterministic_issues') or []
        ]
        if best_snapshot.get('real_ok') is False and best_snapshot.get('real_output'):
            best_issues.append(best_snapshot['real_output'])

    _append_project_event(
        work, 'resume_baseline', 'Indexed resume baseline before any new repair sweep.',
        snapshot=_resume_snapshot_summary(best_snapshot), prior_issues=best_issues[:12],
    )

    for sweep in range(1, sweeps + 1):
        _progress(
            progress_callback,
            f'Resume repair sweep {sweep}/{sweeps}: preserving the best checkpoint and repairing only from a disposable copy.',
            stage='resuming', percent=min(90, 8 + sweep * 18),
        )
        trial = job_root / f'trial_{sweep:02d}'
        _copy_resume_workspace(work, trial)
        trial_manifest = json.loads(json.dumps(manifest))

        # A true feature/edit request needs one focused edit before acceptance. A generic
        # "finish/repair/continue" request skips broad rewriting and goes straight to evidence-driven repair.
        if not generic_resume:
            try:
                completed = _existing_project_text_files(trial)
                _direct_completion_edit(
                    user_request, trial_manifest, _acceptance_criteria(trial_manifest, user_request),
                    trial, completed, unresolved=[user_request], feedback=list(best_issues or [])[-8:],
                    progress_callback=progress_callback,
                )
            except Exception as exc:
                _append_project_event(trial, 'resume_requested_edit_failed', f'Focused requested edit raised: {exc}')

        acceptance_ok, acceptance_issues = _acceptance_repair_cycle(
            user_request, trial_manifest, trial, progress_callback,
        )
        trial_snapshot = _resume_validation_snapshot(trial, trial_manifest, user_request, include_real=True)
        regressions = _resume_protected_regressions(best_snapshot, trial_snapshot)

        if (
            acceptance_ok
            and not regressions
            and int(trial_snapshot.get('issue_count') or 0) == 0
            and trial_snapshot.get('real_ok') is True
        ):
            checkpoint_dir = job_root / 'checkpoints' / f'before_success_sweep_{sweep:02d}'
            _commit_resume_trial(trial, work, checkpoint_dir)
            manifest.clear(); manifest.update(trial_manifest)
            best_snapshot = trial_snapshot
            best_issues = []
            _append_project_event(
                work, 'resume_acceptance_passed', f'Resume sweep {sweep} reached a clean acceptance gate.',
                snapshot=_resume_snapshot_summary(best_snapshot),
            )
            return True, [], best_snapshot

        better = tuple(trial_snapshot.get('score') or (999, 999999, 999999)) < tuple(best_snapshot.get('score') or (999, 999999, 999999))
        if better and not regressions:
            checkpoint_dir = job_root / 'checkpoints' / f'before_improvement_sweep_{sweep:02d}'
            _commit_resume_trial(trial, work, checkpoint_dir)
            manifest.clear(); manifest.update(trial_manifest)
            best_snapshot = trial_snapshot
            best_issues = list(acceptance_issues or [])
            _append_project_event(
                work, 'resume_checkpoint_improved', f'Resume sweep {sweep} improved the best known project state.',
                snapshot=_resume_snapshot_summary(best_snapshot), unresolved=best_issues[:12],
            )
            continue

        # No objective improvement: keep the previous known-better workspace intact.
        # V42.58 preserves bounded rejection/model evidence before deleting the
        # disposable source so the next resume knows why convergence failed.
        _v4258_preserve_rejected_trial_evidence(
            work, trial, sweep, acceptance_issues, trial_snapshot, best_snapshot, regressions,
        )
        shutil.rmtree(trial, ignore_errors=True)
        if regressions:
            _append_project_event(
                work, 'resume_trial_rejected_regression',
                f'Rejected resume sweep {sweep} because it introduced a new defect in previously clean changed source.',
                regressions=regressions[:12],
            )
        else:
            _append_project_event(
                work, 'resume_trial_no_improvement',
                f'Rejected resume sweep {sweep} because it did not improve the best validation score.',
                candidate_snapshot=_resume_snapshot_summary(trial_snapshot),
                best_snapshot=_resume_snapshot_summary(best_snapshot),
            )
        # Diagnostics must describe the retained source, not a discarded trial.
        retained_rows = list(best_snapshot.get('deterministic_issues') or []) + list(best_snapshot.get('functional_issues') or [])
        if retained_rows:
            best_issues = retained_rows
        elif best_snapshot.get('real_ok') is False and best_snapshot.get('real_output'):
            best_issues = [best_snapshot['real_output']]

    return False, best_issues or ['Resume repair sweeps exhausted before the project reached a clean acceptance gate.'], best_snapshot

def generate_project_zip(user_request, max_files=None, max_audit_passes=None, progress_callback=None):
    """Generate a complete working project ZIP."""
    if not qwen_status(timeout=2.0):
        return False, 'Local Qwen is offline.', None

    max_files = max(1, min(int(max_files or DEFAULT_MAX_FILES), HARD_MAX_FILES))
    finish_rounds = int(os.getenv('JARVIS_QWEN_FINISH_ROUNDS', '4'))
    if max_audit_passes is not None and int(max_audit_passes) > 0:
        finish_rounds = max(1, min(int(max_audit_passes), 8))
    
    stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    
    _progress(progress_callback, 'V37 freezing requirements, planning bounded components, and resolving semantic dependencies...', stage='architecting', percent=8)
    
    # Create a neutral workspace first. The manifest-first generator needs a real workspace
    # because it writes one file at a time and feeds prior files back into later generations.
    work = GENERATED_DIR / f'project_{stamp}'
    work.mkdir(parents=True, exist_ok=False)
    _write_qwen3_runtime_notes(work)

    ok, obj, candidates, raw = _direct_new_project_bootstrap(
        user_request, max_files, progress_callback, work=work
    )
    manifest_hint = obj if isinstance(obj, dict) else {}
    project_name = _slug(manifest_hint.get('project_name') or 'project')

    # Save raw planning/bootstrap output for diagnostics in the workspace only.
    # _package_workspace_zip intentionally excludes it from the user-facing ZIP.
    if raw:
        (work / 'JARVIS_QWEN_RAW_bootstrap.txt').write_text(raw, encoding='utf-8')

    if not ok or not candidates:
        # V37: architecture/preflight failures are terminal planning results, not bootstrap/source
        # transport failures. Preserve the actionable diagnostic instead of misleadingly reporting
        # "bootstrap recovery exhausted" and do not materialize a fake recovery project.
        if isinstance(obj, dict) and (obj.get('_jarvis_architecture_blocked') or obj.get('_jarvis_execution_blocked')):
            detail = str(obj.get('_jarvis_failure_detail') or obj.get('_jarvis_architecture_error') or raw or 'Project execution did not converge.')
            failure_stage = str(obj.get('_jarvis_failure_stage') or 'planning').strip().lower()
            label = {
                'planning': 'architecture/preflight',
                'milestone': 'current milestone implementation',
                'build_test': 'build/test validation',
                'acceptance': 'acceptance validation',
                'packaging': 'packaging',
            }.get(failure_stage, failure_stage.replace('_', ' ') or 'execution')
            return False, (f'Project {label} did not converge, so Jarvis stopped before publishing an incomplete ZIP. ' + detail[-12000:] + ' Diagnostic workspace: ' + str(work)), None
        # V34.1: a planned/recovered architecture may still have visible source on disk even if the
        # candidate transport list is empty. Recover conventional source instead of aborting.
        if V34_BOOTSTRAP_RECOVERY and isinstance(obj, dict):
            _v34_materialize_recovery_sources(work, obj, progress_callback)
            candidates=[]
            for rel in _existing_project_text_files(work):
                path=work/rel
                if path.is_file() and _looks_text_file(path):
                    candidates.append((rel,path.read_text(encoding='utf-8',errors='replace')))
            ok=bool(_existing_real_source_files(work))
        if not ok or not candidates:
            return False, ('Bootstrap recovery exhausted without any materializable source. Diagnostic workspace: '+str(work)), None

    # Per-file bootstrap already wrote files. The legacy fallback returns in-memory candidates.
    valid, errors = _candidate_files_valid(work, candidates)
    completed = []
    for rel, content in valid:
        target = work / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        # Avoid unnecessary overwrite, but normalize legacy candidates through the same validation path.
        if not target.exists() or target.read_text(encoding='utf-8', errors='replace') != content:
            target.write_text(content, encoding='utf-8')
        completed.append(rel.as_posix())

    real_sources = _existing_real_source_files(work)
    if not real_sources and V34_BOOTSTRAP_RECOVERY:
        obj_has_source_plan = bool(isinstance(obj,dict) and any(_is_real_source_rel(Path(str(x.get('path') or ''))) for x in (obj.get('files') or []) if isinstance(x,dict)))
        recovery_manifest = obj if obj_has_source_plan else _v34_recovery_manifest(user_request,max_files)
        _v34_materialize_recovery_sources(work,recovery_manifest,progress_callback)
        if not obj_has_source_plan: obj=recovery_manifest
        real_sources=_existing_real_source_files(work)
        valid=[]
        for rel in _existing_project_text_files(work):
            path=work/rel
            if path.is_file() and _looks_text_file(path): valid.append((_safe_relative(rel),path.read_text(encoding='utf-8',errors='replace')))
    if not valid or not real_sources:
        return False, ('V37 implementation recovery exhausted without real source files. Errors: '+('; '.join(errors[:8]) if errors else 'none')+'. Diagnostic workspace: '+str(work)), None
    
    if not completed:
        return False, 'Files were validated but failed to write.', None
    
    _progress(progress_callback, f'V37 implementation has {len(completed)} visible files; validating every component and finishing systematically.', stage='generating', percent=68)
    
    # Create/normalize manifest. Manifest-first mode already has the complete plan.
    if isinstance(obj, dict) and obj.get('files') and all(isinstance(x, dict) and 'purpose' in x for x in obj.get('files', [])):
        manifest = dict(obj)
    else:
        manifest = _bootstrap_manifest_from_files(user_request, obj or {}, [(r, c) for r, c in valid])
    criteria = _acceptance_criteria(manifest, user_request)
    
    # Comprehensive acceptance loop. This no longer stops merely because files parse.
    # It checks required files, unfinished stubs, semantic completeness/API consistency, and requested tests.
    acceptance_ok, acceptance_issues = _acceptance_repair_cycle(
        user_request, manifest, work, progress_callback
    )
    if not acceptance_ok:
        snapshot = _resume_validation_snapshot(work, manifest, user_request, include_real=False)
        return _checkpoint_failure_result(
            'Project generation did not reach final acceptance.',
            work, manifest, user_request, user_request, acceptance_issues,
            source_zip_name='', resume_count=1, snapshot=snapshot, stamp=stamp,
        )

    # Final verification
    completed = _existing_project_text_files(work)
    py_checked, py_failures = _validate_python_files(work)
    
    # Ensure we have files
    if not completed:
        return False, f'No files in workspace after generation. Check {work}', None
    
    # Update manifest with detected entrypoint
    manifest['entrypoint'] = _pick_entrypoint(manifest, completed)
    
    # Write launchers
    try:
        _write_windows_launchers(work, manifest, completed)
    except Exception as exc:
        pass
    
    # Final check
    completed = _existing_project_text_files(work)  # Refresh to include launchers
    checks = _static_project_checks(work, completed, manifest)
    
    # HARD PUBLISH GATE: never label a launcher-only or syntactically broken project as successful.
    real_sources = _existing_real_source_files(work)
    completed = _existing_project_text_files(work)
    py_checked, py_failures = _validate_python_files(work)
    checks = _static_project_checks(work, completed, manifest)
    final_issues = list(checks.get('issues') or [])
    if py_failures:
        final_issues.extend(
            f'Python syntax: {path.relative_to(work).as_posix()}: {err}'
            for path, err in py_failures
        )
    if not real_sources:
        final_issues.append('No real source files exist after generation.')
    final_issues.extend(f'Missing required file: {x}' for x in _missing_manifest_files(work, manifest))
    final_issues.extend(f"{x['file']}: {x['problem']}" for x in _source_incomplete_issues(work))
    final_issues.extend(f"{x['file']}: {x['problem']}" for x in _manifest_contract_issues(work, manifest))
    final_issues.extend(f"{x['file']}: {x['problem']}" for x in _module_identity_issues(work, manifest))
    final_issues.extend(f"{x['file']}: {x['problem']}" for x in _local_import_api_issues(work, manifest))
    real_ok, real_output = _run_real_project_validation(work, user_request, manifest)
    if not real_ok:
        final_issues.append(real_output)

    if final_issues:
        final_issues = list(dict.fromkeys(str(x) for x in final_issues))
        snapshot = _resume_validation_snapshot(work, manifest, user_request, include_real=False)
        return _checkpoint_failure_result(
            'Project generation reached final verification but is still incomplete.',
            work, manifest, user_request, user_request, final_issues,
            source_zip_name='', resume_count=1, snapshot=snapshot, stamp=stamp,
        )

    _progress(progress_callback, 'Packaging ZIP...', stage='packaging', percent=95)
    out, file_count = _package_workspace_zip(work, project_name + "_working", stamp)

    # Verify the ZIP itself contains a real source file, not merely launchers/instructions.
    with zipfile.ZipFile(out, 'r') as archive:
        names = [name for name in archive.namelist() if not name.endswith('/')]
        zip_sources = [name for name in names if _is_real_source_rel(Path(name))]
    if not zip_sources:
        try:
            out.unlink(missing_ok=True)
        except Exception:
            pass
        return False, f'Packaging verification failed: ZIP contains no real source files. Workspace: {work}', None

    _progress(progress_callback, 'Complete!', stage='complete', percent=100)
    return True, (
        f"Created project ZIP with {file_count} packaged files and {len(zip_sources)} real source files "
        f"({py_checked} Python files checked, 0 syntax errors). "
        f"Entrypoint: {manifest.get('entrypoint', 'none')}. Extract and run RUN_PROJECT.bat"
    ), out

def analyze_and_edit_project_zip(user_request, source_zip, max_audit_passes=None, progress_callback=None):
    """Resume/edit an existing project ZIP from its best known state.

    V26 treats attached ZIPs as checkpoints. Generic requests such as "finish this" avoid a broad
    rewrite and go straight to evidence-driven repair. Every sweep runs in a disposable clone; Jarvis
    commits it only when acceptance passes or the measurable validation state improves without adding
    a deterministic defect to previously clean source that the sweep changed.
    """
    source_zip = Path(source_zip).resolve()
    if not source_zip.exists() or source_zip.suffix.lower() != '.zip':
        return False, 'ZIP not found.', None
    if not qwen_status(timeout=2.0):
        return False, 'Local Qwen is offline.', None

    stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    job_root = GENERATED_DIR / f"{_slug(source_zip.stem)}_resume_{stamp}"
    work = job_root / 'working'
    work.mkdir(parents=True, exist_ok=True)
    _write_qwen3_runtime_notes(work)

    try:
        import_report = _safe_extract_zip(source_zip, work)
    except Exception as exc:
        return False, f'Could not safely extract ZIP: {exc}', None

    _progress(
        progress_callback,
        (f"Imported existing project ZIP: {int((import_report or {}).get('extracted', 0))} project files; "
         f"pruned {int((import_report or {}).get('skipped_rebuildable', 0))} rebuildable/cache artifacts."),
        stage='resuming', percent=5,
    )
    try:
        _append_project_event(
            work, 'v4211_zip_import', 'Safely imported existing project ZIP for repair.',
            extracted=int((import_report or {}).get('extracted', 0)),
            skipped_rebuildable=int((import_report or {}).get('skipped_rebuildable', 0)),
            wrapper_stripped=str((import_report or {}).get('wrapper_stripped', '') or ''),
            warnings=list((import_report or {}).get('warnings') or [])[:20],
        )
    except Exception:
        pass

    completed = _existing_project_text_files(work)
    if not completed or not _existing_real_source_files(work):
        return False, 'No real project source files were found in the ZIP.', None

    seed = _resume_seed_from_workspace(work, source_zip, user_request)
    manifest = seed['manifest']
    effective_request = seed['effective_request']
    original_request = seed['original_request']
    latest_instruction = seed['latest_instruction']
    generic_resume = bool(seed['generic_resume'])
    resume_count = int(seed['resume_count'])
    prior_issues = list(seed['prior_issues'])
    force_rebuild = bool(seed.get('force_rebuild'))
    requested_stack = seed.get('requested_stack') or {}

    # Hard stack drift: do not waste sweeps repairing Java/ML code when the user asked for
    # a Python inventory app (or other contradictory stack). Purge and re-bootstrap.
    if force_rebuild:
        _progress(
            progress_callback,
            'Tech-stack mismatch detected — rebuilding the correct project instead of repairing the wrong one.',
            stage='resuming', percent=8,
        )
        _purge_mismatched_stack_files(work, requested_stack or _infer_tech_stack_from_text(effective_request), progress_callback)
        # Clear stale resume metadata that encodes the wrong product
        try:
            (work / RESUME_METADATA_FILE).unlink(missing_ok=True)
        except Exception:
            pass
        max_files = max(1, min(int(DEFAULT_MAX_FILES), HARD_MAX_FILES))
        ok, obj, candidates, raw = _direct_new_project_bootstrap(
            effective_request, max_files, progress_callback, work=work,
        )
        if ok and candidates:
            valid, errors = _candidate_files_valid(work, candidates)
            for rel, content in valid:
                target = work / rel
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text(content, encoding='utf-8')
            if isinstance(obj, dict) and obj.get('files'):
                manifest = dict(obj)
            else:
                manifest = _bootstrap_manifest_from_files(effective_request, obj or {}, [(r, c) for r, c in valid])
            generic_resume = False
            prior_issues = []
            _append_project_event(
                work, 'stack_mismatch_rebuilt',
                'Re-bootstrapped project after rejecting contradictory checkpoint stack.',
                files=len(valid),
            )
        else:
            _append_project_event(
                work, 'stack_mismatch_rebuild_failed',
                'Forced rebuild bootstrap failed; continuing with purged workspace and acceptance repair.',
            )

    criteria = _acceptance_criteria(manifest, effective_request)
    _initialize_project_memory(work, source_zip.name, effective_request, criteria, completed)
    state = _load_project_state(work)
    state.update({
        'schema_version': 2,
        'stage': 'resuming',
        'resume_count': resume_count,
        'original_request': original_request,
        'latest_instruction': latest_instruction,
        'manifest': manifest,
        'unresolved_requirements': prior_issues or criteria,
    })
    _save_project_state(work, state)
    _append_project_event(
        work, 'resume_source_loaded',
        'Loaded existing ZIP as a project checkpoint instead of regenerating the repository.',
        source_zip=source_zip.name, checkpoint_metadata=seed['checkpoint_found'],
        generic_resume=generic_resume, resume_count=resume_count,
        files=len(completed), real_source_files=len(_existing_real_source_files(work)),
    )

    max_sweeps = RESUME_SWEEPS
    if max_audit_passes is not None:
        try:
            requested = int(max_audit_passes)
        except Exception:
            requested = 0
        if requested > 0:
            max_sweeps = max(1, min(requested, 8))

    _progress(
        progress_callback,
        f'Resuming existing project from {source_zip.name}; working files will be preserved unless a validated repair changes them.',
        stage='resuming', percent=5,
    )

    acceptance_ok, acceptance_issues, snapshot = _run_resume_sweeps(
        effective_request, manifest, work, job_root, progress_callback,
        generic_resume=generic_resume, prior_issues=prior_issues, max_sweeps=max_sweeps,
    )

    if not acceptance_ok:
        state = _load_project_state(work)
        state.update({
            'stage': 'checkpoint_incomplete',
            'manifest': manifest,
            'last_verification': _resume_snapshot_summary(snapshot or {}),
            'unresolved_requirements': list(acceptance_issues or []),
        })
        _save_project_state(work, state)
        return _checkpoint_failure_result(
            'The resumed project improved/preserved its best known state but did not reach final acceptance in this run.',
            work, manifest, original_request, latest_instruction, acceptance_issues,
            source_zip_name=source_zip.name, resume_count=resume_count,
            snapshot=snapshot, stamp=stamp,
        )

    # Acceptance passed inside a disposable trial and that state is now the live best workspace.
    completed = _existing_project_text_files(work)
    manifest['entrypoint'] = _pick_entrypoint(manifest, completed)
    try:
        _write_windows_launchers(work, manifest, completed)
    except Exception:
        pass

    final_issues = []
    checks = _static_project_checks(work, _existing_project_text_files(work), manifest)
    final_issues.extend(checks.get('issues') or [])
    final_issues.extend(f"{x['file']}: {x['problem']}" for x in _source_incomplete_issues(work))
    final_issues.extend(f"{x['file']}: {x['problem']}" for x in _manifest_contract_issues(work, manifest))
    final_issues.extend(f"{x['file']}: {x['problem']}" for x in _module_identity_issues(work, manifest))
    final_issues.extend(f"{x['file']}: {x['problem']}" for x in _local_import_api_issues(work, manifest))
    real_ok, real_output = _run_real_project_validation(work, effective_request, manifest)
    if not real_ok:
        final_issues.append(real_output)

    if final_issues:
        final_issues = list(dict.fromkeys(str(x) for x in final_issues if str(x).strip()))
        final_snapshot = _resume_validation_snapshot(work, manifest, effective_request, include_real=False)
        return _checkpoint_failure_result(
            'The resumed project passed the main repair cycle but failed the final publish verification.',
            work, manifest, original_request, latest_instruction, final_issues,
            source_zip_name=source_zip.name, resume_count=resume_count,
            snapshot=final_snapshot, stamp=stamp,
        )

    # A completed ZIP deliberately omits .jarvis_resume.json and sensitive local credential files.
    out, count = _package_workspace_zip(work, f"{_slug(manifest.get('project_name') or source_zip.stem)}_COMPLETED", stamp)
    with zipfile.ZipFile(out, 'r') as archive:
        names = [name for name in archive.namelist() if not name.endswith('/')]
        zip_sources = [name for name in names if _is_real_source_rel(Path(name))]
    if not zip_sources:
        try:
            out.unlink(missing_ok=True)
        except Exception:
            pass
        return False, f'Packaging verification failed: ZIP contains no real source files. Workspace: {work}', None

    state = _load_project_state(work)
    state.update({
        'stage': 'complete', 'manifest': manifest, 'unresolved_requirements': [],
        'last_verification': {'complete': True, 'real_sources': len(zip_sources)},
    })
    _save_project_state(work, state)
    _append_project_event(
        work, 'resume_completed', 'Existing project checkpoint reached all acceptance gates and was packaged.',
        output_zip=out.name, files=count, real_source_files=len(zip_sources), resume_count=resume_count,
    )
    _progress(progress_callback, 'Resume complete: verified project ZIP ready.', stage='complete', percent=100)
    return True, (
        f'Resumed the existing project instead of regenerating it. Verified and packaged {count} files '
        f'with {len(zip_sources)} real source files after resume pass {resume_count}. '
        f'Entrypoint: {manifest.get("entrypoint") or "none"}.'
    ), out



