def _v35_explicit_toolchain(text):
    """Return only a stack the USER actually named. Product words like 'desktop app' are not stack locks."""
    low = _strip_jarvis_routing_noise(text).lower()
    checks = [
        ('tauri', ('tauri',)), ('unreal', ('unreal engine','ue5','ue 5','unrealbuildtool')),
        ('unity', ('unity3d','unity engine','unity game')), ('godot', ('godot','gdscript')),
        ('android_gradle', ('android studio','native android','jetpack compose','android sdk','kotlin android')),
        ('ios_xcode', ('swiftui ios','native iphone','native ios','xcode ios','uikit')),
        ('macos_xcode', ('swiftui macos','appkit','native macos')),
        ('flutter', ('flutter','dart app')), ('expo', ('expo','expo react native')),
        ('react_native', ('react native',)), ('sveltekit', ('sveltekit','svelte kit')),
        ('nuxt', ('nuxt','nuxtjs','nuxt.js')), ('nextjs', ('next.js','nextjs')),
        ('angular', ('angular','angular-cli')), ('vue', ('vue.js','vuejs','vue 3')),
        ('react', ('react app','react website','react web','vite react')),
        ('electron', ('electron app','electron desktop','electron.js')), ('vite', ('vite app','vite project')),
        ('rust', ('rust','cargo')), ('go', ('golang','go module','written in go','language go')),
        ('dotnet', ('c#','.net','dotnet','wpf','winforms','maui','avalonia')),
        ('cpp_cmake', ('c++','cpp','cmake','qt app','qt6','qt5')),
        ('kotlin_gradle', ('kotlin/jvm','kotlin desktop')), ('java_maven', ('maven','pom.xml')),
        ('java_gradle', ('java gradle','spring boot','gradle java')), ('swiftpm', ('swift package','swiftpm')),
        ('php_composer', ('php','composer','laravel','symfony')), ('ruby_bundler', ('ruby','rails','sinatra','bundler')),
        ('python_desktop', ('tkinter','pyqt','pyside','python desktop','desktop app in python')),
        ('python', ('python','flask','django','fastapi','pygame')), ('node', ('node.js','nodejs','express','typescript server')),
        ('static_web', ('static website','html css','plain html','vanilla javascript')),
    ]
    for adapter, terms in checks:
        if any(term in low for term in terms):
            return adapter
    return 'generic'


def _v34_infer_toolchain(text, manifest=None, work=None):
    low = _strip_jarvis_routing_noise(text).lower()
    mf = {k: str((manifest or {}).get(k) or '').lower() for k in ('project_type','platform','language','framework','build_system','package_manager')}
    blob = ' '.join([low] + list(mf.values()))
    explicit = _v35_explicit_toolchain(text)
    if explicit != 'generic':
        return explicit
    # Architect/model metadata can identify a stack even if the user's product request was stack-neutral.
    meta_checks = [
        ('tauri', ('tauri',)), ('godot', ('godot','gdscript')), ('sveltekit', ('sveltekit','svelte')),
        ('nuxt', ('nuxt',)), ('expo', ('expo',)), ('unreal', ('unreal','uproject','unrealbuildtool')),
        ('unity', ('unity',)), ('android_gradle', ('android','jetpack compose')), ('ios_xcode', ('ios','iphone','uikit')),
        ('macos_xcode', ('macos','appkit')), ('flutter', ('flutter',)), ('react_native', ('react native',)),
        ('nextjs', ('next.js','nextjs')), ('angular', ('angular',)), ('vue', ('vue',)), ('react', ('react',)),
        ('electron', ('electron',)), ('vite', ('vite',)), ('rust', ('rust','cargo')), ('go', ('golang','go modules')),
        ('dotnet', ('c#','.net','dotnet','wpf','winforms','maui','avalonia')), ('cpp_cmake', ('c++','cmake','qt')),
        ('kotlin_gradle', ('kotlin','gradle')), ('java_maven', ('maven',)), ('java_gradle', ('java','gradle','spring')),
        ('swiftpm', ('swiftpm','swift package')), ('php_composer', ('php','composer')), ('ruby_bundler', ('ruby','bundler')),
        ('python', ('python','django','fastapi','flask')), ('node', ('node','npm','express')),
    ]
    meta = ' '.join(mf.values())
    for adapter, terms in meta_checks:
        if any(term in meta for term in terms):
            return adapter
    # Workspace evidence is component-aware; this function returns a primary adapter only.
    if work:
        root=Path(work)
        if next(iter(root.rglob('*.uproject')),None): return 'unreal'
        if (root/'ProjectSettings'/'ProjectVersion.txt').exists(): return 'unity'
        if (root/'project.godot').exists(): return 'godot'
        if next(iter(root.rglob('src-tauri/Cargo.toml')),None): return 'tauri'
        if next(iter(root.rglob('pubspec.yaml')),None): return 'flutter'
        if next(iter(root.rglob('Package.swift')),None): return 'swiftpm'
        if next(iter(root.rglob('Cargo.toml')),None): return 'rust'
        if next(iter(root.rglob('go.mod')),None): return 'go'
        if next(iter(root.rglob('*.csproj')),None): return 'dotnet'
        if next(iter(root.rglob('package.json')),None): return 'node'
    # Stack-neutral product hints are defaults, never explicit locks.
    if any(t in low for t in ('website','browser app','web app','landing page','web page')): return 'static_web'
    if any(t in low for t in ('mobile app','phone app','cross-platform mobile')): return 'flutter'
    if any(t in low for t in ('desktop application','desktop app','calculator','utility app')): return 'python_desktop'
    return 'generic'


def _enforce_request_stack_on_manifest(user_request, manifest):
    manifest = _v34_apply_toolchain_defaults(user_request, dict(manifest or {}))
    explicit = _v35_explicit_toolchain(user_request)
    # V35: only an explicitly named technology may overwrite the architect's selected stack.
    if explicit != 'generic':
        spec = _v34_toolchain_catalog().get(explicit, {})
        manifest['toolchain_adapter'] = explicit
        for key in ('platform','language','framework','build_system','package_manager'):
            if spec.get(key): manifest[key] = spec[key]
        manifest['required_tools'] = list(dict.fromkeys((manifest.get('required_tools') or []) + list(spec.get('required_tools') or [])))[:40]
    return manifest


def _stack_lock_instructions(user_request):
    explicit = _v35_explicit_toolchain(user_request)
    if explicit == 'generic':
        return (
            "TOOLCHAIN POLICY: The user did not explicitly lock a technology. Choose the best ecosystem from the product requirements. "
            "Do NOT treat generic words such as desktop app, mobile app, web app, calculator, utility, or game as an explicit language lock. "
            "If the product naturally requires multiple toolchains, declare them as separate components.\n"
        )
    spec = _v34_toolchain_catalog().get(explicit,{})
    return (
        "EXPLICIT USER TOOLCHAIN LOCK (preserve it):\n"
        f"- Adapter: {explicit}\n- Platform: {spec.get('platform','')}\n- Language: {spec.get('language','')}\n"
        f"- Framework/toolchain: {spec.get('framework','')} / {spec.get('build_system','')}\n"
        "- Do not substitute an unrelated language/framework. Multi-toolchain support is allowed when required by this stack.\n"
    )


# V35 strict planner schema: components make large/mixed repositories explicit, acceptance_tests make
# completion criteria machine-checkable when a deterministic command/artifact assertion is possible.
QWEN_SCHEMA_PROJECT_PLAN = {
    "type": "object",
    "properties": {
        "project_name": {"type":"string"}, "summary":{"type":"string"}, "project_type":{"type":"string"},
        "platform":{"type":"string"}, "language":{"type":"string"}, "framework":{"type":"string"},
        "build_system":{"type":"string"}, "package_manager":{"type":"string"},
        "required_tools":{"type":"array","items":{"type":"string"}},
        "dependency_command":{"type":"string"}, "build_command":{"type":"string"}, "test_command":{"type":"string"},
        "entrypoint":{"type":"string"}, "run_command":{"type":"string"},
        "acceptance_criteria":{"type":"array","items":{"type":"string"}},
        "acceptance_tests":{"type":"array","items":{"type":"object","properties":{
            "name":{"type":"string"}, "type":{"type":"string"}, "command":{"type":"string"},
            "path":{"type":"string"}, "expected":{"type":"string"}}, "required":["name","type"], "additionalProperties":False}},
        "architecture_rules":{"type":"array","items":{"type":"string"}},
        "shared_contracts":{"type":"array","items":{"type":"string"}},
        "components":{"type":"array","items":{"type":"object","properties":{
            "id":{"type":"string"}, "root":{"type":"string"}, "purpose":{"type":"string"},
            "toolchain_adapter":{"type":"string"}, "depends_on":{"type":"array","items":{"type":"string"}},
            "dependency_command":{"type":"string"}, "build_command":{"type":"string"},
            "test_command":{"type":"string"}, "run_command":{"type":"string"}},
            "required":["id","root","purpose","toolchain_adapter","depends_on"], "additionalProperties":False}},
        "files":{"type":"array","items":{"type":"object","properties":{
            "path":{"type":"string"}, "purpose":{"type":"string"},
            "phase":{"type":"string","enum":["foundation","data","service","ui","integration","test","docs"]},
            "depends_on":{"type":"array","items":{"type":"string"}}, "exports":{"type":"array","items":{"type":"string"}},
            "contracts":{"type":"array","items":{"type":"string"}}},
            "required":["path","purpose","phase","depends_on","exports","contracts"], "additionalProperties":False}}
    },
    "required":["project_name","summary","project_type","entrypoint","run_command","acceptance_criteria","architecture_rules","shared_contracts","components","files"],
    "additionalProperties":False,
}


def _v35_sanitize_components(raw):
    if isinstance(raw, dict): raw=[raw]
    out=[]; seen=set()
    for idx,item in enumerate(raw or []):
        if not isinstance(item,dict): continue
        cid=re.sub(r'[^A-Za-z0-9_.-]+','-',str(item.get('id') or f'component-{idx+1}')).strip('-') or f'component-{idx+1}'
        root=str(item.get('root') or '.').replace('\\','/').strip('/') or '.'
        try:
            if root!='.': root=_safe_relative(root).as_posix()
        except Exception: continue
        key=(cid,root)
        if key in seen: continue
        seen.add(key)
        deps=item.get('depends_on') or []; deps=[deps] if isinstance(deps,str) else deps
        out.append({'id':cid,'root':root,'purpose':str(item.get('purpose') or 'Project component')[:500],
                    'toolchain_adapter':str(item.get('toolchain_adapter') or 'generic').strip() or 'generic',
                    'depends_on':[str(x).strip() for x in deps if str(x).strip()][:40],
                    'dependency_command':str(item.get('dependency_command') or ''), 'build_command':str(item.get('build_command') or ''),
                    'test_command':str(item.get('test_command') or ''), 'run_command':str(item.get('run_command') or '')})
    return out[:80]


def _v35_sanitize_acceptance_tests(raw):
    if isinstance(raw,dict): raw=[raw]
    out=[]
    for item in raw or []:
        if not isinstance(item,dict): continue
        name=str(item.get('name') or '').strip(); typ=str(item.get('type') or '').strip().lower()
        if not name or not typ: continue
        obj={'name':name[:200],'type':typ[:40]}
        for k in ('command','path','expected'):
            if item.get(k) is not None: obj[k]=str(item.get(k))[:1000]
        out.append(obj)
    return out[:60]


def _parse_project_plan(text, user_request, max_files):
    try: obj=_extract_json(text)
    except Exception: return None
    if not isinstance(obj,dict): return None
    raw_files=obj.get('files') or []; raw_files=[raw_files] if isinstance(raw_files,dict) else raw_files
    files=_sanitize_manifest_files(raw_files,max_files)
    if not files: return None
    paths={x['path'] for x in files}
    for item in files: item['depends_on']=[d for d in item.get('depends_on',[]) if d in paths and d!=item['path']]
    entry=str(obj.get('entrypoint') or '').replace('\\','/').strip('/')
    if entry not in paths: entry=_pick_entrypoint({'entrypoint':entry},list(paths))
    criteria=obj.get('acceptance_criteria') or obj.get('requirements') or []; criteria=[criteria] if isinstance(criteria,str) else criteria
    criteria=[str(x).strip() for x in criteria if str(x).strip()][:80] or [f'The finished project satisfies the complete user request: {user_request}']
    result={'project_name':str(obj.get('project_name') or 'project'),'summary':str(obj.get('summary') or 'Generated project'),
        'project_type':str(obj.get('project_type') or 'software'),'platform':str(obj.get('platform') or ''),'language':str(obj.get('language') or ''),
        'framework':str(obj.get('framework') or ''),'build_system':str(obj.get('build_system') or ''),'package_manager':str(obj.get('package_manager') or ''),
        'required_tools':[str(x).strip() for x in (obj.get('required_tools') or []) if str(x).strip()][:40],
        'dependency_command':str(obj.get('dependency_command') or ''),'build_command':str(obj.get('build_command') or ''),'test_command':str(obj.get('test_command') or ''),
        'entrypoint':entry,'run_command':str(obj.get('run_command') or ''),'acceptance_criteria':criteria,
        'acceptance_tests':_v35_sanitize_acceptance_tests(obj.get('acceptance_tests')),
        'architecture_rules':_v33_normalize_contract_lines(obj.get('architecture_rules'),80),
        'shared_contracts':_v33_normalize_contract_lines(obj.get('shared_contracts'),120),
        'components':_v35_sanitize_components(obj.get('components')),'files':files}
    if not result['components']:
        result['components']=[{'id':'app','root':'.','purpose':'Primary application','toolchain_adapter':_v34_infer_toolchain(user_request,result),'depends_on':[],
                              'dependency_command':result['dependency_command'],'build_command':result['build_command'],'test_command':result['test_command'],'run_command':result['run_command']}]
    return _v34_apply_toolchain_defaults(user_request,result)


def _merge_manifest(base, reviewed, user_request, max_files):
    result=_v35_v34_merge_manifest(base,reviewed,user_request,max_files)
    # Prefer a complete reviewed component graph when supplied; otherwise preserve the base graph.
    comps=_v35_sanitize_components((reviewed or {}).get('components')) or _v35_sanitize_components((base or {}).get('components'))
    if comps: result['components']=comps
    tests=[]
    for src in ((base or {}).get('acceptance_tests') or [], (reviewed or {}).get('acceptance_tests') or []):
        for item in _v35_sanitize_acceptance_tests(src):
            key=(item.get('name'),item.get('type'),item.get('command'),item.get('path'))
            if key not in {(x.get('name'),x.get('type'),x.get('command'),x.get('path')) for x in tests}: tests.append(item)
    result['acceptance_tests']=tests[:60]
    return result


def _project_plan_prompt(user_request, max_files):
    return (
        "You are the lead software architect for V35, a GENERAL-PURPOSE autonomous software builder. The user sends ONE product request; internally you may design any number of components/toolchains.\n"
        "Return ONLY strict manifest JSON; do not emit source code yet.\n"
        "V35 SYSTEMATIC COMPLETION RULES:\n"
        "- First decompose the product into coherent COMPONENTS (frontend/backend/native/mobile/database/tooling/etc.). Each component has a root, adapter, dependencies and native commands.\n"
        "- A repository may be multi-toolchain. Examples: Tauri = npm frontend + Cargo native; React Native = npm + Gradle + optional Xcode; full-stack = frontend + API + migrations. Never stop validating after the first manifest you recognize.\n"
        "- Infer stack only when the user did not name one. Generic words such as desktop/mobile/web/game are NOT language locks.\n"
        "- Design public contracts before implementation. Every caller has a planned provider. Avoid cycles.\n"
        "- For large projects use hierarchical architecture: product -> components -> component contracts -> files. Keep each file focused and preferably below " + str(V33_MAX_FILE_LINES) + " lines.\n"
        "- Use conventional native layouts/toolchains. Declare dependency/build/test/run commands that are non-interactive and meaningful; NEVER use echo/true/no-op scripts as validation.\n"
        "- Add acceptance_tests when a requirement can be deterministically verified. Supported useful types are command and artifact_exists; do not invent destructive commands.\n"
        "- The completed ZIP must be reproducible from declared dependencies on a clean machine/toolchain.\n"
        "- Do not include Jarvis-owned RUN_PROJECT.bat, SETUP_AND_RUN.bat, BUILD_PROJECT.bat, JARVIS_RUN_INSTRUCTIONS.txt, or JARVIS_* files.\n"
        f"Maximum planned files: {max_files}. Prefer the smallest complete repository.\n\nUSER REQUEST:\n{user_request}\n\n{_stack_lock_instructions(user_request)}\n"
        "Return the complete manifest with components, acceptance criteria/tests, architecture contracts, and all files."
    )


def _v35_ignored_component_path(path):
    try: parts=Path(path).parts
    except Exception: return False
    ignored={'.git','node_modules','vendor','target','build','dist','.next','.nuxt','.gradle','.dart_tool','Pods','DerivedData','.venv','venv','env','.jarvis_build','.jarvis_candidates','.jarvis_backups'}
    return any(part in ignored for part in parts)


def _v35_relroot(work, root):
    work=Path(work).resolve(); root=Path(root).resolve()
    try: rel=root.relative_to(work).as_posix()
    except Exception: return '.'
    return rel or '.'


def _v35_add_component(out, seen, work, root, adapter, cid=None, purpose='Detected build component', declared=None):
    root=Path(root).resolve(); work=Path(work).resolve()
    try: root.relative_to(work)
    except Exception: return
    rel=_v35_relroot(work,root); key=(rel,adapter)
    if key in seen: return
    seen.add(key)
    spec=_v34_toolchain_catalog().get(adapter,{})
    d=dict(declared or {})
    out.append({'id':str(d.get('id') or cid or (adapter+'-'+re.sub(r'[^A-Za-z0-9]+','-',rel).strip('-'))).strip('-') or adapter,
                'root':rel,'purpose':str(d.get('purpose') or purpose),'toolchain_adapter':adapter,
                'depends_on':list(d.get('depends_on') or []),'dependency_command':str(d.get('dependency_command') or spec.get('dependency_command') or ''),
                'build_command':str(d.get('build_command') or spec.get('build_command') or ''),'test_command':str(d.get('test_command') or spec.get('test_command') or ''),
                'run_command':str(d.get('run_command') or spec.get('run_command') or '')})


def _v35_discover_components(work, manifest):
    """Find ALL independently buildable roots, not merely the first toolchain in the repository."""
    work=Path(work).resolve(); out=[]; seen=set()
    # Planner-declared components first.
    for d in _v35_sanitize_components((manifest or {}).get('components')):
        root=work if d['root']=='.' else work/d['root']
        if not root.exists(): continue
        adapter=str(d.get('toolchain_adapter') or 'generic')
        if adapter=='generic': adapter=_v34_infer_toolchain('',d,root)
        _v35_add_component(out,seen,work,root,adapter,declared=d)
    # Marker-based discovery catches incomplete/wrong planner graphs and mixed stacks.
    marker_specs=[
        ('*.uproject','unreal'), ('project.godot','godot'), ('pubspec.yaml','flutter'), ('Package.swift','swiftpm'),
        ('Cargo.toml','rust'), ('go.mod','go'), ('pom.xml','java_maven'), ('composer.json','php_composer'), ('Gemfile','ruby_bundler')]
    for pattern,adapter in marker_specs:
        for marker in work.rglob(pattern):
            if not marker.is_file() or _v35_ignored_component_path(marker.relative_to(work)): continue
            actual=adapter
            if marker.name=='Cargo.toml' and marker.parent.name=='src-tauri': actual='rust'
            _v35_add_component(out,seen,work,marker.parent,actual,cid=actual,purpose=f'Detected from {marker.name}')
    # package.json roots, identifying framework from file content/path.
    for package in work.rglob('package.json'):
        if not package.is_file() or _v35_ignored_component_path(package.relative_to(work)): continue
        adapter='node'
        try:
            data=json.loads(package.read_text(encoding='utf-8',errors='replace')); blob=' '.join(list((data.get('dependencies') or {}).keys())+list((data.get('devDependencies') or {}).keys())+list((data.get('scripts') or {}).values())).lower()
            if '@tauri-apps/' in blob or 'tauri' in blob: adapter='node'  # Rust half is a separate Cargo component.
            elif 'next' in blob: adapter='nextjs'
            elif '@sveltejs/kit' in blob or 'svelte' in blob: adapter='sveltekit'
            elif 'nuxt' in blob: adapter='nuxt'
            elif 'electron' in blob: adapter='electron'
            elif 'expo' in blob: adapter='expo'
            elif 'react-native' in blob: adapter='react_native'
            elif 'react' in blob: adapter='react'
            elif 'vue' in blob: adapter='vue'
            elif '@angular/core' in blob: adapter='angular'
            elif 'vite' in blob: adapter='vite'
        except Exception: pass
        _v35_add_component(out,seen,work,package.parent,adapter,cid=adapter,purpose='Node/package component')
    # Gradle roots. A settings file is authoritative; otherwise use build file if it is not nested under another detected settings root.
    gradle_roots=[]
    for pat in ('settings.gradle.kts','settings.gradle'):
        for marker in work.rglob(pat):
            if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)): gradle_roots.append(marker.parent.resolve())
    for root in sorted(set(gradle_roots),key=lambda x:len(x.parts)):
        is_android=(root/'app'/'src'/'main'/'AndroidManifest.xml').exists() or next(iter(root.rglob('AndroidManifest.xml')),None) is not None
        _v35_add_component(out,seen,work,root,'android_gradle' if is_android else 'java_gradle',cid='gradle',purpose='Gradle component')
    # CMake roots (Unreal is never coerced into CMake).
    for marker in work.rglob('CMakeLists.txt'):
        if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)):
            if not next(iter(marker.parent.glob('*.uproject')),None): _v35_add_component(out,seen,work,marker.parent,'cpp_cmake',cid='cmake',purpose='CMake component')
    # .NET solutions/projects. Prefer solutions, then standalone projects not under a solution root.
    sln_roots=[]
    for marker in work.rglob('*.sln'):
        if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)):
            sln_roots.append(marker.parent.resolve()); _v35_add_component(out,seen,work,marker.parent,'dotnet',cid='dotnet',purpose='.NET solution')
    for marker in work.rglob('*.csproj'):
        if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)):
            if not any(r==marker.parent.resolve() or r in marker.parent.resolve().parents for r in sln_roots): _v35_add_component(out,seen,work,marker.parent,'dotnet',cid='dotnet',purpose='.NET project')
    # Xcode project/workspace roots and Unity root.
    for marker in list(work.rglob('*.xcodeproj'))+list(work.rglob('*.xcworkspace')):
        if not _v35_ignored_component_path(marker.relative_to(work)): _v35_add_component(out,seen,work,marker.parent,'ios_xcode' if 'ios' in str((manifest or {}).get('platform','')).lower() else 'macos_xcode',cid='xcode',purpose='Xcode component')
    if (work/'ProjectSettings'/'ProjectVersion.txt').exists(): _v35_add_component(out,seen,work,work,'unity',cid='unity',purpose='Unity project')
    # Python roots. A pyproject/requirements file defines a reproducible component; otherwise one root if Python source exists.
    pyroots=[]
    for name in ('pyproject.toml','requirements.txt','setup.py'):
        for marker in work.rglob(name):
            if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)): pyroots.append(marker.parent.resolve())
    if any(Path(x).suffix.lower() in {'.py','.pyw'} for x in _existing_real_source_files(work)):
        root=min(pyroots,key=lambda x:len(x.parts)) if pyroots else _python_project_root(work,manifest)
        _v35_add_component(out,seen,work,root,'python',cid='python',purpose='Python component')
    if not out:
        adapter=str((manifest or {}).get('toolchain_adapter') or _v34_infer_toolchain('',manifest,work))
        _v35_add_component(out,seen,work,work,adapter,cid='app',purpose='Primary project')
    # Stable shallow-first order, with dependencies/build foundations generally before app wrappers.
    out.sort(key=lambda c:(len(Path(c['root']).parts) if c['root']!='.' else 0,c['root'],c['toolchain_adapter']))
    try: (work/V35_COMPONENT_FILE).write_text(json.dumps({'version':V35_VERSION,'components':out},indent=2),encoding='utf-8')
    except Exception: pass
    return out


def _v35_is_noop_command(command):
    low=re.sub(r'\s+',' ',str(command or '').strip().lower())
    if not low: return False
    bad=('echo no test','echo no tests','echo build configured','echo success','echo ok','no test specified','write-host success')
    return low in {'true','exit 0',':','cmd /c exit 0'} or any(x in low for x in bad)


def _v35_component_failure(component, message):
    return f"V35 COMPONENT FAILED [{component.get('id')} | {component.get('toolchain_adapter')} | {component.get('root')}]:\n{message}"


def _v35_host_unverified(component, message):
    prefix='UNVERIFIED_HOST_TOOLCHAIN'
    return False, _v35_component_failure(component, f'{prefix}: {message}') if V35_STRICT_HOST_VERIFICATION else (True, f'{prefix}: {message}')


def _v35_run(parts,cwd,outputs,timeout=None,env=None):
    ok,out=_run_command(parts,cwd,timeout or PROJECT_BUILD_TIMEOUT,env=env); outputs.append(out); return ok,out


def _v35_node_component(root, component):
    package=root/'package.json'; outputs=[]; npm=shutil.which('npm')
    if not npm: return False,'Node component requires npm, but npm is not installed/available.'
    try: data=json.loads(package.read_text(encoding='utf-8')); scripts=data.get('scripts') or {}
    except Exception as exc: return False,f'package.json is invalid JSON: {exc}'
    for key in ('build','test'):
        if key in scripts and _v35_is_noop_command(scripts.get(key)): return False,f'package.json script {key!r} is a no-op and cannot satisfy V35 verification: {scripts.get(key)}'
    install=[npm,'ci'] if (root/'package-lock.json').exists() else [npm,'install','--no-audit','--no-fund']
    ok,out=_v35_run(install,root,outputs)
    if not ok:return False,out
    if 'build' in scripts:
        ok,out=_v35_run([npm,'run','build'],root,outputs)
        if not ok:return False,out
    elif str(component.get('toolchain_adapter')) in {'react','nextjs','vue','angular','sveltekit','nuxt','vite'}:
        return False,'Web framework component has no real package.json build script.'
    if 'test' in scripts and not _v35_is_noop_command(scripts.get('test')):
        ok,out=_v35_run([npm,'test','--','--runInBand'],root,outputs)
        if not ok:
            ok,out=_v35_run([npm,'test'],root,outputs)
            if not ok:return False,out
    return True,'\n'.join(outputs)[-8000:]


def _v35_python_component(root, work, manifest, user_request):
    """Validate Python from a disposable clone + fresh venv so undeclared local packages cannot hide missing dependencies."""
    outputs=[]
    try:
        with tempfile.TemporaryDirectory(prefix='jarvis_v35_py_') as tmp:
            clone_work=Path(tmp)/'project'; copy_source_tree(work,clone_work,dirs_exist_ok=True,ignore=shutil.ignore_patterns('__pycache__','.pytest_cache','.jarvis_build','.jarvis_candidates','.jarvis_backups','.jarvis_runtime','.jarvis_failures','.cache','.venv','venv','env','node_modules','target','build','dist'))
            rel=root.relative_to(work); clone_root=clone_work/rel
            venv_dir=Path(tmp)/'venv'
            ok,out=_run_command([sys.executable,'-m','venv',str(venv_dir)],clone_root,PROJECT_BUILD_TIMEOUT); outputs.append(out)
            if not ok:return False,'Could not create clean Python validation venv:\n'+out
            py=venv_dir/('Scripts/python.exe' if os.name=='nt' else 'bin/python')
            if not py.exists(): return False,'Clean Python venv did not create an interpreter.'
            # Upgrade pip quietly enough to handle modern pyproject metadata; failure is non-fatal if bundled pip works.
            _run_command([str(py),'-m','pip','install','--disable-pip-version-check','-q','--upgrade','pip'],clone_root,PROJECT_BUILD_TIMEOUT)
            req=clone_root/'requirements.txt'; pyproject=clone_root/'pyproject.toml'; setup=clone_root/'setup.py'
            if req.exists() and req.read_text(encoding='utf-8',errors='replace').strip():
                ok,out=_run_command([str(py),'-m','pip','install','--disable-pip-version-check','-r',str(req)],clone_root,PROJECT_BUILD_TIMEOUT); outputs.append(out)
                if not ok:return False,'Clean dependency install failed:\n'+out
            elif pyproject.exists() or setup.exists():
                ok,out=_run_command([str(py),'-m','pip','install','--disable-pip-version-check','-e','.'],clone_root,PROJECT_BUILD_TIMEOUT); outputs.append(out)
                if not ok:return False,'Clean editable dependency install failed:\n'+out
            ok,out=_run_command([str(py),'-m','compileall','-q','.'],clone_root,PROJECT_BUILD_TIMEOUT); outputs.append(out)
            if not ok:return False,out
            test_files=[p for p in clone_root.rglob('test*.py') if not _v35_ignored_component_path(p.relative_to(clone_root))]
            if test_files:
                uses_pytest=any('pytest' in p.read_text(encoding='utf-8',errors='replace') for p in test_files)
                if uses_pytest:
                    probe=subprocess.run([str(py),'-c','import pytest'],cwd=str(clone_root),capture_output=True,text=True)
                    if probe.returncode!=0:return False,'Tests use pytest, but pytest is not declared/installed in the clean project environment.'
                    cmd=[str(py),'-m','pytest','-q']
                else: cmd=[str(py),'-m','unittest','discover','-s','tests','-v'] if (clone_root/'tests').exists() else [str(py),'-m','unittest','discover','-v']
                ok,out=_run_command(cmd,clone_root,PROJECT_TEST_TIMEOUT); outputs.append(out)
                if not ok:return False,out
            elif _tests_were_requested(user_request,manifest,work): return False,'Tests were requested/planned but no Python test files exist.'
            # Startup smoke uses the clean interpreter. A process still alive at timeout is a successful GUI/server start.
            entry=_python_entrypoint_path(work,manifest)
            if V35_RUNTIME_SMOKE and entry:
                try: clone_entry=clone_work/entry.relative_to(work)
                except Exception: clone_entry=None
                if clone_entry and clone_entry.exists():
                    env=os.environ.copy(); env['PYTHONPATH']=os.pathsep.join([str(clone_root),str(clone_work)]); env['PYTHONDONTWRITEBYTECODE']='1'; env['JARVIS_PROJECT_VALIDATION']='1'
                    try:
                        proc=subprocess.run([str(py),str(clone_entry)],cwd=str(clone_root),env=env,stdin=subprocess.DEVNULL,capture_output=True,text=True,timeout=PROJECT_SMOKE_TIMEOUT)
                        text=((proc.stdout or '')+'\n'+(proc.stderr or '')).strip(); outputs.append(text[-3000:])
                        if proc.returncode!=0:return False,'Clean Python startup smoke failed:\n'+text[-8000:]
                    except subprocess.TimeoutExpired as exc:
                        outputs.append('Entrypoint remained alive through V35 clean-environment smoke interval.')
            return True,'\n'.join(x for x in outputs if x)[-8000:]
    except Exception as exc: return False,f'Could not prepare V35 clean Python validation: {exc}'


def _v35_validate_component(work, manifest, component, user_request=''):
    root=work if component.get('root') in ('','.') else work/str(component.get('root'))
    root=root.resolve(); adapter=str(component.get('toolchain_adapter') or 'generic'); outputs=[]
    if not root.exists(): return False,_v35_component_failure(component,'Component root does not exist.')
    if adapter in {'node','react','vite','nextjs','vue','sveltekit','nuxt','angular','electron','react_native','expo'} and (root/'package.json').exists():
        ok,out=_v35_node_component(root,component); return ok, out if ok else _v35_component_failure(component,out)
    if adapter=='python':
        ok,out=_v35_python_component(root,work,manifest,user_request); return ok, out if ok else _v35_component_failure(component,out)
    if adapter=='unreal':
        ubt=shutil.which('UnrealBuildTool') or shutil.which('UnrealBuildTool.exe')
        if not ubt:return _v35_host_unverified(component,'UnrealBuildTool is unavailable; V35 refuses to call the project COMPLETE without an engine build.')
        declared=str(component.get('build_command') or manifest.get('build_command') or '')
        if declared and not _v35_is_noop_command(declared) and declared.lower()!='unrealbuildtool':
            ok,out=_v34_run_declared_command(root,declared,'Unreal build command'); return ok, out if ok else _v35_component_failure(component,out)
        return _v35_host_unverified(component,'UnrealBuildTool exists, but no concrete engine/version target build command was declared.')
    if adapter=='unity':
        unity=shutil.which('Unity') or shutil.which('Unity.exe')
        if not unity:return _v35_host_unverified(component,'Unity editor is unavailable for batchmode compile verification.')
        ok,out=_v35_run([unity,'-batchmode','-quit','-projectPath',str(root),'-logFile','-'],root,outputs)
        return ok, out if ok else _v35_component_failure(component,out)
    if adapter=='godot':
        godot=shutil.which('godot') or shutil.which('godot4')
        if not godot:return _v35_host_unverified(component,'Godot executable is unavailable for headless project validation.')
        ok,out=_v35_run([godot,'--headless','--path',str(root),'--editor','--quit'],root,outputs)
        return ok, out if ok else _v35_component_failure(component,out)
    if adapter in {'android_gradle','java_gradle','kotlin_gradle'}:
        wrapper=root/('gradlew.bat' if os.name=='nt' else 'gradlew'); gradle=str(wrapper) if wrapper.exists() else shutil.which('gradle')
        if not gradle:return False,_v35_component_failure(component,'Gradle component requires gradlew or gradle, but neither is available.')
        if wrapper.exists() and os.name!='nt':
            try: wrapper.chmod(wrapper.stat().st_mode|0o111)
            except Exception: pass
        is_android=adapter=='android_gradle' or next(iter(root.rglob('AndroidManifest.xml')),None) is not None
        tasks=['assembleDebug'] if is_android else ['build']
        # Only run test task when test sources exist; absent tests should not cause Gradle task mismatch failures.
        has_tests=any(p.is_file() for base in ('src/test','app/src/test','src/androidTest','app/src/androidTest') for p in (root/base).rglob('*')) if any((root/base).exists() for base in ('src/test','app/src/test','src/androidTest','app/src/androidTest')) else False
        if has_tests: tasks.append('testDebugUnitTest' if is_android else 'test')
        for task in tasks:
            ok,out=_v35_run([gradle,task,'--no-daemon'],root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        return True,'\n'.join(outputs)[-8000:]
    if adapter=='java_maven' and (root/'pom.xml').exists():
        mvnw=root/('mvnw.cmd' if os.name=='nt' else 'mvnw'); mvn=str(mvnw) if mvnw.exists() else shutil.which('mvn')
        if not mvn:return False,_v35_component_failure(component,'Maven/mvnw is unavailable.')
        ok,out=_v35_run([mvn,'test','-B'],root,outputs); return ok, out if ok else _v35_component_failure(component,out)
    if adapter=='swiftpm' and (root/'Package.swift').exists():
        swift=shutil.which('swift')
        if not swift:return _v35_host_unverified(component,'Swift toolchain is unavailable; source structure alone is not a verified build.')
        for args in ([swift,'package','resolve'],[swift,'build']):
            ok,out=_v35_run(args,root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        if (root/'Tests').exists():
            ok,out=_v35_run([swift,'test'],root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        return True,'\n'.join(outputs)[-8000:]
    if adapter in {'ios_xcode','macos_xcode'}:
        xcb=shutil.which('xcodebuild')
        if not xcb:return _v35_host_unverified(component,'xcodebuild/Xcode is unavailable; V35 marks native Apple projects unverified instead of passing them.')
        target=next(iter(root.glob('*.xcworkspace')),None) or next(iter(root.glob('*.xcodeproj')),None)
        if not target:return False,_v35_component_failure(component,'Xcode adapter selected but no .xcodeproj/.xcworkspace exists.')
        base=[xcb,'-workspace' if target.suffix=='.xcworkspace' else '-project',str(target)]
        ok,out=_v35_run(base+['-list','-json'],root,outputs)
        if not ok:return False,_v35_component_failure(component,out)
        # Require a concrete build command from the planner for native Apple because destination/scheme is project-specific.
        declared=str(component.get('build_command') or manifest.get('build_command') or '')
        if not declared or declared.strip().lower()=='xcodebuild': return _v35_host_unverified(component,'Project is readable by Xcode, but no concrete scheme/destination build command was declared.')
        ok,out=_v34_run_declared_command(root,declared,'Xcode build command'); return ok, out if ok else _v35_component_failure(component,out)
    if adapter=='cpp_cmake' and (root/'CMakeLists.txt').exists():
        cmake=shutil.which('cmake')
        if not cmake:return False,_v35_component_failure(component,'cmake is unavailable.')
        b=root/'.jarvis_build'
        for args in ([cmake,'-S',str(root),'-B',str(b)],[cmake,'--build',str(b),'--config','Release']):
            ok,out=_v35_run(args,root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        ctest=shutil.which('ctest')
        if ctest and next(iter(b.rglob('CTestTestfile.cmake')),None):
            ok,out=_v35_run([ctest,'--test-dir',str(b),'-C','Release','--output-on-failure'],root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        return True,'\n'.join(outputs)[-8000:]
    if adapter=='rust' and (root/'Cargo.toml').exists():
        cargo=shutil.which('cargo')
        if not cargo:return False,_v35_component_failure(component,'cargo is unavailable.')
        for args in ([cargo,'fetch'],[cargo,'build'],[cargo,'test','--no-fail-fast']):
            ok,out=_v35_run(args,root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        return True,'\n'.join(outputs)[-8000:]
    if adapter=='go' and (root/'go.mod').exists():
        go=shutil.which('go')
        if not go:return False,_v35_component_failure(component,'go is unavailable.')
        for args in ([go,'mod','download'],[go,'test','./...'],[go,'build','./...']):
            ok,out=_v35_run(args,root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        return True,'\n'.join(outputs)[-8000:]
    if adapter=='dotnet':
        dotnet=shutil.which('dotnet')
        if not dotnet:return False,_v35_component_failure(component,'dotnet is unavailable.')
        target=next(iter(root.glob('*.sln')),None) or next(iter(root.glob('*.csproj')),None)
        if not target:return False,_v35_component_failure(component,'.NET component has no .sln/.csproj.')
        for args in ([dotnet,'restore',str(target)],[dotnet,'build',str(target),'--no-restore','--nologo']):
            ok,out=_v35_run(args,root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        test_projects=[p for p in root.rglob('*.csproj') if 'test' in p.name.lower() or 'tests' in [x.lower() for x in p.parts]]
        for tp in test_projects:
            ok,out=_v35_run([dotnet,'test',str(tp),'--no-build','--nologo'],tp.parent,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        return True,'\n'.join(outputs)[-8000:]
    if adapter=='flutter' and (root/'pubspec.yaml').exists():
        flutter=shutil.which('flutter')
        if not flutter:return _v35_host_unverified(component,'Flutter SDK is unavailable.')
        for args in ([flutter,'pub','get'],[flutter,'analyze']):
            ok,out=_v35_run(args,root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        if next(iter(root.rglob('*_test.dart')),None):
            ok,out=_v35_run([flutter,'test'],root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        build_args=None
        if (root/'android').exists(): build_args=[flutter,'build','apk','--debug']
        elif (root/'web').exists(): build_args=[flutter,'build','web']
        elif os.name=='nt' and (root/'windows').exists(): build_args=[flutter,'build','windows']
        elif sys.platform=='darwin' and (root/'macos').exists(): build_args=[flutter,'build','macos']
        if build_args:
            ok,out=_v35_run(build_args,root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        return True,'\n'.join(outputs)[-8000:]
    if adapter=='php_composer' and (root/'composer.json').exists():
        exe=shutil.which('composer')
        if not exe:return False,_v35_component_failure(component,'composer is unavailable.')
        for args in ([exe,'install','--no-interaction','--no-progress'],[exe,'validate','--no-check-publish']):
            ok,out=_v35_run(args,root,outputs)
            if not ok:return False,_v35_component_failure(component,out)
        return True,'\n'.join(outputs)[-8000:]
    if adapter=='ruby_bundler' and (root/'Gemfile').exists():
        bundle=shutil.which('bundle')
        if not bundle:return False,_v35_component_failure(component,'bundle is unavailable.')
        ok,out=_v35_run([bundle,'install'],root,outputs)
        if not ok:return False,_v35_component_failure(component,out)
        return True,'\n'.join(outputs)[-8000:]
    if adapter=='static_web':
        html=next(iter(root.rglob('index.html')),None)
        if not html:return False,_v35_component_failure(component,'Static web component has no index.html.')
        return True,'Static web entrypoint exists.'
    # Generic component may use safe declared commands, but no-op commands are rejected.
    ran=False
    for label,key in (('dependency command','dependency_command'),('build command','build_command'),('test command','test_command')):
        cmd=str(component.get(key) or '').strip()
        if not cmd: continue
        if _v35_is_noop_command(cmd): return False,_v35_component_failure(component,f'{label} is a no-op and cannot verify completion: {cmd}')
        ok,out=_v34_run_declared_command(root,cmd,label); outputs.append(out); ran=True
        if not ok:return False,_v35_component_failure(component,out)
    if ran:return True,'\n'.join(outputs)[-8000:]
    return _v35_host_unverified(component,'No supported real build/test adapter or safe declared verification command is available for this component.')


def _v35_run_acceptance_tests(work, manifest):
    if not V35_ACCEPTANCE_COMMANDS:return True,''
    outputs=[]
    for item in _v35_sanitize_acceptance_tests((manifest or {}).get('acceptance_tests')):
        typ=item.get('type'); name=item.get('name')
        if typ=='artifact_exists':
            raw=str(item.get('path') or '').strip()
            if not raw:return False,f'Acceptance test {name!r} has no artifact path.'
            try: target=Path(work)/_safe_relative(raw)
            except Exception:return False,f'Acceptance test {name!r} has an unsafe path: {raw}'
            if not target.exists():return False,f'Acceptance test failed [{name}]: expected artifact does not exist: {raw}'
            outputs.append(f'PASS {name}: {raw} exists')
        elif typ=='command':
            cmd=str(item.get('command') or '').strip()
            if not cmd:return False,f'Acceptance test {name!r} has no command.'
            if _v35_is_noop_command(cmd):return False,f'Acceptance test {name!r} uses a no-op command.'
            ok,out=_v34_run_declared_command(work,cmd,f'acceptance test {name}')
            if not ok:return False,f'Acceptance test failed [{name}]:\n{out}'
            outputs.append(f'PASS {name}\n{out}')
        # Other semantic/manual types remain criteria for the repair/audit loop, not fake executable proof.
    return True,'\n'.join(outputs)[-5000:]


def _v35_compiler_failure_hints(text):
    raw=str(text or '')
    hints=[]
    patterns=[
        r'(?m)^([^\n:]+\.(?:c|cc|cpp|cxx|h|hpp|rs|go|java|kt|kts|cs|ts|tsx|js|jsx|swift)):(\d+)(?::\d+)?:\s*(?:error|warning)?\s*:?(.*)$',
        r'(?m)^([^\n(]+\.(?:cs|vb))\((\d+),(?:\d+)\):\s*error\s+([^:]+):\s*(.*)$',
        r'(?m)^e:\s*file:///([^:]+\.kt):(\d+):\d+\s*(.*)$',
    ]
    for pat in patterns:
        for m in re.finditer(pat,raw,re.I):
            vals=[str(x).strip() for x in m.groups() if x is not None]
            hint=' | '.join(vals)
            if hint and hint not in hints:hints.append(hint)
            if len(hints)>=12:break
    return ('\nV35_COMPILER_DIAGNOSTIC_HINTS:\n'+'\n'.join(hints)) if hints else ''


def _run_nonpython_build_validation(work, manifest):
    if not QWEN_REAL_BUILD:return True,''
    work=Path(work).resolve(); components=_v35_discover_components(work,manifest or {}); outputs=[]
    for component in components:
        if component.get('toolchain_adapter')=='python': continue
        ok,out=_v35_validate_component(work,manifest or {},component,'')
        outputs.append(f"[{component.get('id')}] {out}")
        if not ok:return False,(out+_v35_compiler_failure_hints(out))[-12000:]
    return True,'\n'.join(outputs)[-12000:]


def _run_real_project_validation(work, user_request, manifest):
    """V35 authority: every discovered component, clean Python deps, executable acceptance checks."""
    work=Path(work).resolve(); manifest=_v34_apply_toolchain_defaults(user_request,manifest or {}); outputs=[]
    # Keep deterministic local API checks because they route Python repairs better than raw runtime errors.
    has_python=any(Path(x).suffix.lower() in {'.py','.pyw'} for x in _existing_real_source_files(work))
    if has_python:
        import_issues=_local_import_api_issues(work,manifest)
        if import_issues:return False,'\n'.join(f"{x['file']}: {x['problem']}" for x in import_issues)
    components=_v35_discover_components(work,manifest)
    if not components:return False,'V35 could not discover any buildable project component.'
    report=[]
    for component in components:
        ok,out=_v35_validate_component(work,manifest,component,user_request)
        report.append({'id':component.get('id'),'root':component.get('root'),'adapter':component.get('toolchain_adapter'),'ok':bool(ok),'output':str(out)[-5000:]})
        if out:outputs.append(f"===== {component.get('id')} ({component.get('toolchain_adapter')}) =====\n{out}")
        if not ok:
            try:(work/V35_VALIDATION_FILE).write_text(json.dumps({'version':V35_VERSION,'complete':False,'components':report},indent=2),encoding='utf-8')
            except Exception:pass
            return False,(out+_v35_compiler_failure_hints(out))[-14000:]
    ok,out=_v35_run_acceptance_tests(work,manifest)
    if out:outputs.append('===== EXECUTABLE ACCEPTANCE =====\n'+out)
    if not ok:return False,out
    try:(work/V35_VALIDATION_FILE).write_text(json.dumps({'version':V35_VERSION,'complete':True,'components':report,'acceptance':out},indent=2),encoding='utf-8')
    except Exception:pass
    return True,'\n'.join(outputs)[-14000:]


def _v35_bat_command(command, root='.'):
    cmd=str(command or '').strip()
    if not cmd:return []
    lines=[]
    if root not in ('','.'): lines += [f'pushd "{root.replace("/", "\\\\")}"']
    lines += [cmd, 'if errorlevel 1 goto :fail']
    if root not in ('','.'): lines += ['popd']
    return lines


def _write_windows_launchers(work, manifest, completed):
    """V35 Windows delivery: first-run dependency bootstrap, explicit build script, and normal runner."""
    work=Path(work); entrypoint=_pick_entrypoint(manifest,completed); components=_v35_discover_components(work,manifest)
    run_command=str(manifest.get('run_command') or '').strip(); adapter=str(manifest.get('toolchain_adapter') or _v34_infer_toolchain('',manifest,work))
    if not run_command:
        spec=_v34_toolchain_catalog().get(adapter,{}); run_command=str(spec.get('run_command') or '')
        if entrypoint.lower().endswith('.py'):run_command=f'python "{entrypoint}"'
        elif entrypoint.lower().endswith('.html'):run_command=f'start "" "{entrypoint}"'
    # SETUP_AND_RUN installs every component dependency before launching the primary app.
    setup=['@echo off','setlocal','cd /d "%~dp0"','echo.','echo ========================================','echo   JARVIS V35 - FIRST RUN SETUP','echo ========================================','echo.']
    for comp in components:
        dep=str(comp.get('dependency_command') or '').strip(); root=str(comp.get('root') or '.')
        if dep and not _v35_is_noop_command(dep):
            setup += [f'echo Setting up {comp.get("id")}...'] + _v35_bat_command(dep,root)
    if run_command: setup += ['echo.','echo Setup complete. Starting project...',run_command,'if errorlevel 1 goto :fail']
    else: setup += ['echo Setup complete.','echo No automatic run command was declared. See JARVIS_RUN_INSTRUCTIONS.txt.']
    setup += ['exit /b 0',':fail','echo.','echo Setup/build/run failed. Review the error above.','pause','exit /b 1']
    (work/'SETUP_AND_RUN.bat').write_text('\r\n'.join(setup)+'\r\n',encoding='utf-8')
    # BUILD_PROJECT validates/builds every declared component in sequence.
    build=['@echo off','setlocal','cd /d "%~dp0"','echo.','echo ========================================','echo   JARVIS V35 - BUILD PROJECT','echo ========================================','echo.']
    for comp in components:
        root=str(comp.get('root') or '.'); dep=str(comp.get('dependency_command') or '').strip(); cmd=str(comp.get('build_command') or '').strip(); test=str(comp.get('test_command') or '').strip()
        build.append(f'echo Building {comp.get("id")} ({comp.get("toolchain_adapter")})...')
        for c in (dep,cmd,test):
            if c and not _v35_is_noop_command(c): build += _v35_bat_command(c,root)
    build += ['echo.','echo All declared component build steps completed.','pause','exit /b 0',':fail','echo.','echo Build failed.','pause','exit /b 1']
    (work/'BUILD_PROJECT.bat').write_text('\r\n'.join(build)+'\r\n',encoding='utf-8')
    runner=['@echo off','setlocal','cd /d "%~dp0"','echo.','echo ========================================','echo   JARVIS V35 GENERATED PROJECT','echo ========================================','echo.']
    if run_command: runner += [run_command,'if errorlevel 1 goto :fail']
    elif entrypoint: runner += [f'start "" "{entrypoint}"']
    else: runner += ['echo No automatic run command was declared.','echo Run SETUP_AND_RUN.bat first and read JARVIS_RUN_INSTRUCTIONS.txt.']
    runner += ['exit /b 0',':fail','echo.','echo Project exited with an error.','pause','exit /b 1']
    (work/'RUN_PROJECT.bat').write_text('\r\n'.join(runner)+'\r\n',encoding='utf-8')
    instructions=['JARVIS V35 GENERATED PROJECT - HOW TO RUN','==========================================','',f"Project: {manifest.get('project_name','generated-project')}",f"Entry point: {entrypoint or 'not detected'}",f"Run command: {run_command or 'not detected'}",'',
                  'FIRST RUN ON WINDOWS:','1. Extract the ZIP to a normal folder.','2. Double-click SETUP_AND_RUN.bat.','3. Later launches can use RUN_PROJECT.bat.','',
                  'VERIFY/REBUILD:','Double-click BUILD_PROJECT.bat to execute the declared dependency/build/test sequence for every component.','',
                  'COMPONENTS:']
    for comp in components: instructions.append(f"- {comp.get('id')}: root={comp.get('root')} adapter={comp.get('toolchain_adapter')}")
    instructions += ['', 'A ZIP is labeled COMPLETED only after Jarvis V35 real validation succeeds for every component on the generation host. Host-specific projects may be returned as an incomplete/checkpoint ZIP rather than falsely marked complete.']
    (work/'JARVIS_RUN_INSTRUCTIONS.txt').write_text('\n'.join(instructions)+'\n',encoding='utf-8')
    return entrypoint,run_command


# V35.0.1 launcher/reproducibility refinements.
def _v35_host_unverified(component, message):
    prefix='UNVERIFIED_HOST_TOOLCHAIN'
    text=_v35_component_failure(component, f'{prefix}: {message}')
    if V35_STRICT_HOST_VERIFICATION:
        return False, text
    return True, text


def _v35_discover_components(work, manifest):
    """Find ALL independently buildable roots, with reproducible first-run commands."""
    work=Path(work).resolve(); out=[]; seen=set()
    for d in _v35_sanitize_components((manifest or {}).get('components')):
        root=work if d['root']=='.' else work/d['root']
        if not root.exists(): continue
        adapter=str(d.get('toolchain_adapter') or 'generic')
        if adapter=='generic': adapter=_v34_infer_toolchain('',d,root)
        _v35_add_component(out,seen,work,root,adapter,declared=d)
    marker_specs=[('*.uproject','unreal'),('project.godot','godot'),('pubspec.yaml','flutter'),('Package.swift','swiftpm'),('Cargo.toml','rust'),('go.mod','go'),('pom.xml','java_maven'),('composer.json','php_composer'),('Gemfile','ruby_bundler')]
    for pattern,adapter in marker_specs:
        for marker in work.rglob(pattern):
            if not marker.is_file() or _v35_ignored_component_path(marker.relative_to(work)): continue
            _v35_add_component(out,seen,work,marker.parent,adapter,cid=adapter,purpose=f'Detected from {marker.name}')
    for package in work.rglob('package.json'):
        if not package.is_file() or _v35_ignored_component_path(package.relative_to(work)): continue
        adapter='node'
        try:
            data=json.loads(package.read_text(encoding='utf-8',errors='replace')); blob=' '.join(list((data.get('dependencies') or {}).keys())+list((data.get('devDependencies') or {}).keys())+list((data.get('scripts') or {}).values())).lower()
            if 'next' in blob: adapter='nextjs'
            elif '@sveltejs/kit' in blob or 'svelte' in blob: adapter='sveltekit'
            elif 'nuxt' in blob: adapter='nuxt'
            elif 'electron' in blob: adapter='electron'
            elif 'expo' in blob: adapter='expo'
            elif 'react-native' in blob: adapter='react_native'
            elif '@angular/core' in blob: adapter='angular'
            elif 'vue' in blob: adapter='vue'
            elif 'react' in blob: adapter='react'
            elif 'vite' in blob: adapter='vite'
        except Exception: pass
        _v35_add_component(out,seen,work,package.parent,adapter,cid=adapter,purpose='Node/package component')
    gradle_roots=[]
    for pat in ('settings.gradle.kts','settings.gradle'):
        for marker in work.rglob(pat):
            if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)): gradle_roots.append(marker.parent.resolve())
    for root in sorted(set(gradle_roots),key=lambda x:len(x.parts)):
        is_android=next(iter(root.rglob('AndroidManifest.xml')),None) is not None
        _v35_add_component(out,seen,work,root,'android_gradle' if is_android else 'java_gradle',cid='gradle',purpose='Gradle component')
    for marker in work.rglob('CMakeLists.txt'):
        if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)) and not next(iter(marker.parent.glob('*.uproject')),None):
            _v35_add_component(out,seen,work,marker.parent,'cpp_cmake',cid='cmake',purpose='CMake component')
    sln_roots=[]
    for marker in work.rglob('*.sln'):
        if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)):
            sln_roots.append(marker.parent.resolve()); _v35_add_component(out,seen,work,marker.parent,'dotnet',cid='dotnet',purpose='.NET solution')
    for marker in work.rglob('*.csproj'):
        if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)) and not any(r==marker.parent.resolve() or r in marker.parent.resolve().parents for r in sln_roots):
            _v35_add_component(out,seen,work,marker.parent,'dotnet',cid='dotnet',purpose='.NET project')
    for marker in list(work.rglob('*.xcodeproj'))+list(work.rglob('*.xcworkspace')):
        if not _v35_ignored_component_path(marker.relative_to(work)):
            _v35_add_component(out,seen,work,marker.parent,'ios_xcode' if 'ios' in str((manifest or {}).get('platform','')).lower() else 'macos_xcode',cid='xcode',purpose='Xcode component')
    if (work/'ProjectSettings'/'ProjectVersion.txt').exists(): _v35_add_component(out,seen,work,work,'unity',cid='unity',purpose='Unity project')
    pyroots=[]
    for name in ('pyproject.toml','requirements.txt','setup.py'):
        for marker in work.rglob(name):
            if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)): pyroots.append(marker.parent.resolve())
    if any(Path(x).suffix.lower() in {'.py','.pyw'} for x in _existing_real_source_files(work)):
        root=min(pyroots,key=lambda x:len(x.parts)) if pyroots else _python_project_root(work,manifest)
        _v35_add_component(out,seen,work,root,'python',cid='python',purpose='Python component')
    if not out:
        adapter=str((manifest or {}).get('toolchain_adapter') or _v34_infer_toolchain('',manifest,work)); _v35_add_component(out,seen,work,work,adapter,cid='app',purpose='Primary project')
    # Repair first-run commands based on actual markers instead of blindly assuming a requirements file.
    for comp in out:
        root=work if comp['root']=='.' else work/comp['root']; a=comp['toolchain_adapter']
        if a=='python':
            if (root/'requirements.txt').exists(): comp['dependency_command']='python -m pip install -r requirements.txt'
            elif (root/'pyproject.toml').exists() or (root/'setup.py').exists(): comp['dependency_command']='python -m pip install -e .'
            else: comp['dependency_command']=''
        elif a=='cpp_cmake':
            comp['dependency_command']='cmake -S . -B .jarvis_build'; comp['build_command']='cmake --build .jarvis_build --config Release'
        elif a in {'android_gradle','java_gradle','kotlin_gradle'}:
            wrapper='gradlew.bat' if os.name=='nt' and (root/'gradlew.bat').exists() else ('gradlew' if (root/'gradlew').exists() else 'gradle')
            comp['build_command']=f'{wrapper} '+('assembleDebug' if a=='android_gradle' else 'build')
        elif a=='java_maven':
            wrapper='mvnw.cmd' if os.name=='nt' and (root/'mvnw.cmd').exists() else ('mvnw' if (root/'mvnw').exists() else 'mvn')
            comp['build_command']=f'{wrapper} package -B'; comp['test_command']=f'{wrapper} test -B'
    out.sort(key=lambda c:(len(Path(c['root']).parts) if c['root']!='.' else 0,c['root'],c['toolchain_adapter']))
    try:(work/V35_COMPONENT_FILE).write_text(json.dumps({'version':V35_VERSION,'components':out},indent=2),encoding='utf-8')
    except Exception:pass
    return out


def _v35_bat_command(command, root='.'):
    cmd=str(command or '').strip()
    if not cmd:return []
    # Windows does not search the current directory for these wrappers in the same way as POSIX shells.
    low=cmd.lower()
    if low.startswith('gradlew '): cmd='call gradlew.bat '+cmd[len('gradlew '):]
    elif low.startswith('gradlew.bat '): cmd='call '+cmd
    elif low.startswith('mvnw '): cmd='call mvnw.cmd '+cmd[len('mvnw '):]
    elif low.startswith('mvnw.cmd '): cmd='call '+cmd
    lines=[]
    if root not in ('','.'): lines += [f'pushd "{root.replace("/", chr(92))}"']
    lines += [cmd,'if errorlevel 1 goto :fail']
    if root not in ('','.'): lines += ['popd']
    return lines

# V35 planning capacity: 6k tokens was too small for a componentized 100+ file manifest.
os.environ.setdefault('JARVIS_QWEN_PLAN_MAX_TOKENS', '16384')

_v35_v33_contract_index = _v33_contract_index
def _v33_contract_index(manifest):
    base=_v35_v33_contract_index(manifest)
    comps=_v35_sanitize_components((manifest or {}).get('components'))
    if not comps:return base
    lines=['V35 COMPONENT GRAPH:']
    for c in comps[:40]:
        lines.append(f"- {c.get('id')} root={c.get('root')} adapter={c.get('toolchain_adapter')} depends_on={','.join(c.get('depends_on') or []) or '-'} :: {c.get('purpose')}")
    return '\n'.join(lines)+'\n\n'+base


def _review_project_plan(user_request, manifest, max_files, progress_callback=None):
    current=_merge_manifest(dict(manifest or {}),{},user_request,max_files)
    review_tokens=max(6144,min(int(os.getenv('JARVIS_QWEN_PLAN_MAX_TOKENS','16384')),24576))
    for review_no in range(1,PROJECT_PLAN_REVIEW_PASSES+1):
        prompt=(
            "Review this V35 universal architecture BEFORE code generation. Return ONLY a corrected COMPLETE manifest JSON.\n"
            "This is a component/interface/dependency review, not a source-code task.\n"
            "Hard checks:\n"
            "1. Decompose mixed repositories into components and give each component the correct native toolchain/root/dependency/build/test/run commands.\n"
            "2. Every cross-file call/import has a provider export + explicit contract.\n"
            "3. File and component dependency directions are acyclic whenever possible. Foundation/types/config -> data -> services -> UI/adapters -> integration -> tests/docs.\n"
            f"4. Split files likely to exceed about {V33_MAX_FILE_LINES} lines; keep a hierarchy of product -> components -> files.\n"
            "5. Constructor/method/function signatures and shared data contracts are consistent across components.\n"
            "6. Build/test commands are REAL, non-interactive proof, never echo/true/no-op placeholders.\n"
            "7. Add deterministic acceptance_tests for command/artifact checks where possible.\n"
            "8. Preserve explicit user stack choices, but do not mistake generic product words for language locks.\n"
            "9. Do not remove requested features or include Jarvis-owned output files.\n\n"
            f"USER REQUEST:\n{user_request}\n\n{_stack_lock_instructions(user_request)}\nCURRENT MANIFEST:\n{json.dumps(current,ensure_ascii=False,indent=2)}\n"
        )
        ok,text=_qwen_call(prompt,progress_callback,f'V35 architecture review {review_no}/{PROJECT_PLAN_REVIEW_PASSES}',profile='plan',max_tokens=review_tokens,thinking=False,response_schema=QWEN_SCHEMA_PROJECT_PLAN,schema_name='project_plan_review',strict_output=True)
        if not ok:continue
        reviewed=_parse_project_plan(text,user_request,max_files)
        if reviewed:current=_merge_manifest(current,reviewed,user_request,max_files)
    return current

# V35 runtime/artifact proof for runnable non-Python targets.
_v35_node_component_base = _v35_node_component
_v35_validate_component_base = _v35_validate_component


def _v35_runtime_smoke(parts, cwd, label):
    if not V35_RUNTIME_SMOKE:return True,''
    env=os.environ.copy(); env['JARVIS_PROJECT_VALIDATION']='1'
    try:
        proc=subprocess.run(parts,cwd=str(cwd),env=env,stdin=subprocess.DEVNULL,capture_output=True,text=True,timeout=PROJECT_SMOKE_TIMEOUT)
    except subprocess.TimeoutExpired as exc:
        partial=((exc.stdout or '')+'\n'+(exc.stderr or '')).strip()
        return True,f'{label} remained alive through smoke interval.\n{partial[-2000:]}'
    except Exception as exc:return False,f'{label} could not start: {exc}'
    out=((proc.stdout or '')+'\n'+(proc.stderr or '')).strip()
    if proc.returncode!=0:return False,f'{label} exited with code {proc.returncode}:\n{out[-6000:]}'
    return True,out[-3000:]


def _v35_node_component(root, component):
    ok,out=_v35_node_component_base(root,component)
    if not ok:return ok,out
    adapter=str(component.get('toolchain_adapter') or 'node')
    expected=[]
    if adapter in {'react','vue','sveltekit','vite','angular'}: expected=['dist']
    elif adapter=='nextjs': expected=['.next']
    elif adapter=='nuxt': expected=['.output','.nuxt']
    if expected and not any((root/x).exists() for x in expected):
        return False,f'Build command succeeded but expected framework build artifact is missing (expected one of: {", ".join(expected)}).'
    return True,out


def _v35_validate_component(work, manifest, component, user_request=''):
    ok,out=_v35_validate_component_base(work,manifest,component,user_request)
    if not ok:return ok,out
    if not V35_RUNTIME_SMOKE:return ok,out
    root=Path(work).resolve() if component.get('root') in ('','.') else (Path(work)/str(component.get('root'))).resolve()
    adapter=str(component.get('toolchain_adapter') or 'generic')
    smoke_ok=True; smoke=''
    if adapter=='node' and (root/'package.json').exists():
        try:scripts=(json.loads((root/'package.json').read_text(encoding='utf-8')).get('scripts') or {})
        except Exception:scripts={}
        if 'start' in scripts and not _v35_is_noop_command(scripts.get('start')) and shutil.which('npm'):
            smoke_ok,smoke=_v35_runtime_smoke([shutil.which('npm'),'start'],root,'Node application')
    elif adapter=='rust' and (root/'Cargo.toml').exists() and shutil.which('cargo'):
        smoke_ok,smoke=_v35_runtime_smoke([shutil.which('cargo'),'run','--quiet'],root,'Rust application')
    elif adapter=='go' and (root/'go.mod').exists() and shutil.which('go'):
        smoke_ok,smoke=_v35_runtime_smoke([shutil.which('go'),'run','.'],root,'Go application')
    elif adapter=='dotnet' and shutil.which('dotnet'):
        # Only smoke executable projects; libraries often intentionally have no runnable target.
        projects=list(root.glob('*.csproj'))
        executable=False
        for project in projects:
            txt=project.read_text(encoding='utf-8',errors='replace').lower()
            if '<outputtype>exe</outputtype>' in txt or '<outputtype>winexe</outputtype>' in txt:executable=True;break
        if executable: smoke_ok,smoke=_v35_runtime_smoke([shutil.which('dotnet'),'run','--no-build'],root,'.NET application')
    if not smoke_ok:return False,_v35_component_failure(component,smoke)
    if smoke:return True,(out+'\n'+smoke)[-9000:]
    return True,out

# V35.0.2 delivery commands reflect the repository that actually exists.
_v35_discover_components_base = _v35_discover_components

def _v35_discover_components(work, manifest):
    work=Path(work).resolve(); out=_v35_discover_components_base(work,manifest)
    for comp in out:
        root=work if comp.get('root') in ('','.') else work/str(comp.get('root')); a=str(comp.get('toolchain_adapter') or '')
        if a in {'node','react','vite','nextjs','vue','sveltekit','nuxt','angular','electron','react_native','expo'} and (root/'package.json').exists():
            try:scripts=(json.loads((root/'package.json').read_text(encoding='utf-8',errors='replace')).get('scripts') or {})
            except Exception:scripts={}
            comp['dependency_command']='npm ci' if (root/'package-lock.json').exists() else 'npm install --no-audit --no-fund'
            comp['build_command']='npm run build' if 'build' in scripts and not _v35_is_noop_command(scripts.get('build')) else ''
            comp['test_command']='npm test' if 'test' in scripts and not _v35_is_noop_command(scripts.get('test')) else ''
            if 'start' in scripts:comp['run_command']='npm start'
            elif 'dev' in scripts:comp['run_command']='npm run dev'
        elif a=='python':
            comp['test_command']='python -m unittest discover -s tests -v' if (root/'tests').exists() and next(iter((root/'tests').rglob('test*.py')),None) else ('python -m unittest discover -v' if next(iter(root.glob('test*.py')),None) else '')
        elif a=='flutter':
            comp['test_command']='flutter test' if next(iter(root.rglob('*_test.dart')),None) else ''
    try:(work/V35_COMPONENT_FILE).write_text(json.dumps({'version':V35_VERSION,'components':out},indent=2),encoding='utf-8')
    except Exception:pass
    return out


def _v35_windows_python_setup_lines(root, include_dependencies=True):
    lines=[]
    if root not in ('','.'):lines.append(f'pushd "{root.replace("/", chr(92))}"')
    lines += [
        'if not exist ".venv\\Scripts\\python.exe" (',
        '  where py >nul 2>nul',
        '  if %errorlevel%==0 (py -m venv .venv) else (python -m venv .venv)',
        '  if errorlevel 1 goto :fail',
        ')',
    ]
    if include_dependencies: lines.append('REM Dependencies are installed below when declared by the component.')
    if root not in ('','.'):lines.append('popd')
    return lines


def _v35_python_bat_command(command, root='.'):
    cmd=str(command or '').strip()
    if not cmd:return []
    # Route all Python/pip module commands through the project-local venv.
    repl='".venv\\Scripts\\python.exe"'
    cmd=re.sub(r'^(?:py|python|python3)\b',repl,cmd,flags=re.I)
    cmd=re.sub(r'^pip(?:3)?\b',repl+' -m pip',cmd,flags=re.I)
    lines=[]
    if root not in ('','.'):lines.append(f'pushd "{root.replace("/", chr(92))}"')
    lines += [cmd,'if errorlevel 1 goto :fail']
    if root not in ('','.'):lines.append('popd')
    return lines


def _write_windows_launchers(work, manifest, completed):
    work=Path(work); entrypoint=_pick_entrypoint(manifest,completed); components=_v35_discover_components(work,manifest)
    adapter=str(manifest.get('toolchain_adapter') or _v34_infer_toolchain('',manifest,work)); run_command=str(manifest.get('run_command') or '').strip()
    if not run_command:
        run_command=str(_v34_toolchain_catalog().get(adapter,{}).get('run_command') or '')
        if entrypoint.lower().endswith('.py'):run_command=f'python "{entrypoint}"'
        elif entrypoint.lower().endswith('.html'):run_command=f'start "" "{entrypoint}"'

    setup=['@echo off','setlocal','cd /d "%~dp0"','echo.','echo ========================================','echo   JARVIS V35 - FIRST RUN SETUP','echo ========================================','echo.']
    for comp in components:
        a=str(comp.get('toolchain_adapter') or ''); root=str(comp.get('root') or '.'); dep=str(comp.get('dependency_command') or '').strip()
        setup.append(f'echo Setting up {comp.get("id")} ({a})...')
        if a=='python':
            setup += _v35_windows_python_setup_lines(root)
            if dep:setup += _v35_python_bat_command(dep,root)
        elif dep and not _v35_is_noop_command(dep): setup += _v35_bat_command(dep,root)
    # Prefer the venv for a Python primary app.
    pycomp=next((c for c in components if c.get('toolchain_adapter')=='python'),None)
    if pycomp and entrypoint.lower().endswith(('.py','.pyw')):
        proot=str(pycomp.get('root') or '.'); ep=entrypoint.replace('\\','/')
        if proot not in ('','.') and ep.startswith(proot.rstrip('/')+'/'):ep=ep[len(proot.rstrip('/'))+1:]
        setup += ['echo.','echo Setup complete. Starting project...']
        if proot not in ('','.'):setup.append(f'pushd "{proot.replace("/", chr(92))}"')
        setup += [f'".venv\\Scripts\\python.exe" "{ep.replace("/", chr(92))}"','if errorlevel 1 goto :fail']
        if proot not in ('','.'):setup.append('popd')
    elif run_command:setup += ['echo.','echo Setup complete. Starting project...',run_command,'if errorlevel 1 goto :fail']
    else:setup += ['echo Setup complete.','echo No automatic run command was declared. See JARVIS_RUN_INSTRUCTIONS.txt.']
    setup += ['exit /b 0',':fail','echo.','echo Setup/build/run failed. Review the error above.','pause','exit /b 1']
    (work/'SETUP_AND_RUN.bat').write_text('\r\n'.join(setup)+'\r\n',encoding='utf-8')

    build=['@echo off','setlocal','cd /d "%~dp0"','echo.','echo ========================================','echo   JARVIS V35 - BUILD PROJECT','echo ========================================','echo.']
    for comp in components:
        a=str(comp.get('toolchain_adapter') or ''); root=str(comp.get('root') or '.'); dep=str(comp.get('dependency_command') or '').strip(); cmd=str(comp.get('build_command') or '').strip(); test=str(comp.get('test_command') or '').strip()
        build.append(f'echo Building {comp.get("id")} ({a})...')
        if a=='python':
            build += _v35_windows_python_setup_lines(root)
            for c in (dep,cmd,test):
                if c and not _v35_is_noop_command(c):build += _v35_python_bat_command(c,root)
        else:
            for c in (dep,cmd,test):
                if c and not _v35_is_noop_command(c):build += _v35_bat_command(c,root)
    build += ['echo.','echo All declared component build steps completed.','pause','exit /b 0',':fail','echo.','echo Build failed.','pause','exit /b 1']
    (work/'BUILD_PROJECT.bat').write_text('\r\n'.join(build)+'\r\n',encoding='utf-8')

    runner=['@echo off','setlocal','cd /d "%~dp0"','echo.','echo ========================================','echo   JARVIS V35 GENERATED PROJECT','echo ========================================','echo.']
    if pycomp and entrypoint.lower().endswith(('.py','.pyw')):
        proot=str(pycomp.get('root') or '.'); ep=entrypoint.replace('\\','/')
        if proot not in ('','.') and ep.startswith(proot.rstrip('/')+'/'):ep=ep[len(proot.rstrip('/'))+1:]
        if proot not in ('','.'):runner.append(f'pushd "{proot.replace("/", chr(92))}"')
        runner += ['if not exist ".venv\\Scripts\\python.exe" (','  echo First run setup has not been completed.','  echo Run SETUP_AND_RUN.bat first.','  pause','  exit /b 1',')',f'".venv\\Scripts\\python.exe" "{ep.replace("/", chr(92))}"','if errorlevel 1 goto :fail']
        if proot not in ('','.'):runner.append('popd')
    elif run_command:runner += [run_command,'if errorlevel 1 goto :fail']
    elif entrypoint:runner += [f'start "" "{entrypoint}"']
    else:runner += ['echo No automatic run command was declared.','echo Run SETUP_AND_RUN.bat first and read JARVIS_RUN_INSTRUCTIONS.txt.']
    runner += ['exit /b 0',':fail','echo.','echo Project exited with an error.','pause','exit /b 1']
    (work/'RUN_PROJECT.bat').write_text('\r\n'.join(runner)+'\r\n',encoding='utf-8')

    instructions=['JARVIS V35 GENERATED PROJECT - HOW TO RUN','==========================================','',f"Project: {manifest.get('project_name','generated-project')}",f"Entry point: {entrypoint or 'not detected'}",f"Run command: {run_command or 'not detected'}",'',
                  'FIRST RUN ON WINDOWS:','1. Extract the ZIP to a normal folder.','2. Double-click SETUP_AND_RUN.bat.','3. Python projects use an isolated .venv created inside the project.','4. Later launches can use RUN_PROJECT.bat.','',
                  'VERIFY/REBUILD:','Double-click BUILD_PROJECT.bat. It uses only build/test steps that exist for the generated components.','','COMPONENTS:']
    for comp in components:instructions.append(f"- {comp.get('id')}: root={comp.get('root')} adapter={comp.get('toolchain_adapter')}")
    instructions += ['', 'Jarvis V35 only labels a project COMPLETED after real validation succeeds for every required discovered component on the generation host.']
    (work/'JARVIS_RUN_INSTRUCTIONS.txt').write_text('\n'.join(instructions)+'\n',encoding='utf-8')
    return entrypoint,run_command

# V35.0.3: avoid regex replacement escape handling for Windows venv paths.
def _v35_python_bat_command(command, root='.'):
    cmd=str(command or '').strip()
    if not cmd:return []
    repl='".venv\\Scripts\\python.exe"'
    cmd=re.sub(r'^(?:py|python|python3)\b',lambda _m:repl,cmd,flags=re.I)
    cmd=re.sub(r'^pip(?:3)?\b',lambda _m:repl+' -m pip',cmd,flags=re.I)
    lines=[]
    if root not in ('','.'):lines.append(f'pushd "{root.replace("/", chr(92))}"')
    lines += [cmd,'if errorlevel 1 goto :fail']
    if root not in ('','.'):lines.append('popd')
    return lines

# V35.0.4: broader generic build-tool allowance + multiple Python components + safer runtime smoke targeting.
_V34_SAFE_COMMANDS.update({'make','ninja','meson','godot','godot4','xmake','qmake','msbuild','uv','poetry','pytest'})
_v35_discover_components_v3502 = _v35_discover_components
_v35_validate_component_v3502 = _v35_validate_component

def _v35_discover_components(work, manifest):
    work=Path(work).resolve(); out=_v35_discover_components_v3502(work,manifest)
    existing={(str(c.get('root') or '.'),str(c.get('toolchain_adapter') or '')) for c in out}
    roots=set()
    for name in ('pyproject.toml','requirements.txt','setup.py'):
        for marker in work.rglob(name):
            if marker.is_file() and not _v35_ignored_component_path(marker.relative_to(work)):roots.add(marker.parent.resolve())
    for root in sorted(roots,key=lambda p:(len(p.parts),str(p))):
        rel=_v35_relroot(work,root)
        if (rel,'python') in existing:continue
        has_py=next((p for p in root.rglob('*.py') if p.is_file() and not _v35_ignored_component_path(p.relative_to(work))),None)
        if not has_py:continue
        dep='python -m pip install -r requirements.txt' if (root/'requirements.txt').exists() else ('python -m pip install -e .' if (root/'pyproject.toml').exists() or (root/'setup.py').exists() else '')
        test='python -m unittest discover -s tests -v' if (root/'tests').exists() and next(iter((root/'tests').rglob('test*.py')),None) else ('python -m unittest discover -v' if next(iter(root.glob('test*.py')),None) else '')
        out.append({'id':'python-'+re.sub(r'[^A-Za-z0-9]+','-',rel).strip('-'),'root':rel,'purpose':'Detected Python component','toolchain_adapter':'python','depends_on':[],
                    'dependency_command':dep,'build_command':'python -m compileall .','test_command':test,'run_command':''})
        existing.add((rel,'python'))
    out.sort(key=lambda c:(len(Path(c['root']).parts) if c.get('root') not in ('','.') else 0,str(c.get('root')),str(c.get('toolchain_adapter'))))
    try:(work/V35_COMPONENT_FILE).write_text(json.dumps({'version':V35_VERSION,'components':out},indent=2),encoding='utf-8')
    except Exception:pass
    return out


def _v35_validate_component(work, manifest, component, user_request=''):
    ok,out=_v35_validate_component_v3502(work,manifest,component,user_request)
    # The prior V35 wrapper already performs runtime smoke. Prevent false negatives for pure Rust/Go libraries
    # by converting only the specific "no runnable target" smoke case back to the successful build/test result.
    if not ok:
        low=str(out or '').lower(); adapter=str(component.get('toolchain_adapter') or '')
        if adapter=='rust' and ('a bin target must be available for `cargo run`' in low or 'no bin target available for `cargo run`' in low):
            return True,'Rust library compiled and tested; no runnable binary target exists, so startup smoke is not applicable.'
        if adapter=='go' and ('is not a main package' in low or 'package command-line-arguments is not a main package' in low):
            return True,'Go library/module built and tested; no runnable main package exists, so startup smoke is not applicable.'
    return ok,out

# Final V35 release identity + static-web launcher normalization.
V35_VERSION = '35.0.4'
_v35_write_windows_launchers_release_base = _write_windows_launchers

def _write_windows_launchers(work, manifest, completed):
    adjusted=dict(manifest or {})
    adapter=str(adjusted.get('toolchain_adapter') or _v34_infer_toolchain('',adjusted,work))
    entry=_pick_entrypoint(adjusted,completed)
    if adapter=='static_web' and entry.lower().endswith(('.html','.htm')):
        rc=str(adjusted.get('run_command') or '').strip().lower()
        if not rc or rc in {entry.lower(),'index.html','index.htm'}:
            adjusted['run_command']=f'start "" "{entry}"'
    return _v35_write_windows_launchers_release_base(work,adjusted,completed)

