V35_VERSION = '35.1.0'
V351_REAL_RUN_HARDENING = True
V351_HIERARCHICAL_REFINEMENT = os.getenv('JARVIS_V351_HIERARCHICAL_REFINEMENT', '1') != '0'
V351_HIERARCHICAL_FILE_THRESHOLD = max(24, int(os.getenv('JARVIS_V351_HIERARCHICAL_FILE_THRESHOLD', '60')))
V351_COMPONENT_REFINEMENT_LIMIT = max(1, min(12, int(os.getenv('JARVIS_V351_COMPONENT_REFINEMENT_LIMIT', '8'))))
V351_RUNTIME_PREFLIGHT_ROUNDS = max(0, min(5, int(os.getenv('JARVIS_V351_RUNTIME_PREFLIGHT_ROUNDS', '3'))))

_v351_base_extract_single_file_response = _extract_single_file_response
_v351_base_python_local_class_index = _python_local_class_index
