def _v351_strip_legacy_transport_markers(text, expected_path):
    """Remove only exact model transport wrappers at the outer edges of one expected file.

    V34.1 occasionally produced a complete candidate followed by a line such as
    ``===== END FILE Project/app/database.py =====``. Treating that transport artifact as
    Python source can discard tens of minutes of otherwise valid generation. V35.1 salvages
    it deterministically without asking Qwen to rewrite the file.
    """
    raw = str(text or '').replace('\ufeff', '')
    if not raw:
        return raw
    expected = str(expected_path or '').replace('\\', '/').strip()
    if not expected:
        return raw

    lines = raw.splitlines()
    normalized_expected = re.escape(expected)
    begin_re = re.compile(
        rf'^\s*=+\s*(?:BEGIN\s+)?FILE\s*:?\s*[`"\']?{normalized_expected}[`"\']?\s*=*\s*$', re.I
    )
    end_re = re.compile(
        rf'^\s*=+\s*END\s+FILE\s*:?\s*[`"\']?{normalized_expected}[`"\']?\s*=*\s*$', re.I
    )

    # Only inspect outer non-empty lines so a literal example embedded in real source is preserved.
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    if lines and begin_re.match(lines[0]):
        lines.pop(0)
        while lines and not lines[0].strip():
            lines.pop(0)
    if lines and end_re.match(lines[-1]):
        lines.pop()
        while lines and not lines[-1].strip():
            lines.pop()
    return '\n'.join(lines) + ('\n' if lines else '')


def _extract_single_file_response(text, expected_path):
    precleaned = _v351_strip_legacy_transport_markers(text, expected_path)
    extracted = _v351_base_extract_single_file_response(precleaned, expected_path)
    return _v351_strip_legacy_transport_markers(extracted, expected_path)


def _python_local_class_index(work, manifest):
    """V35.1 extends the conservative class index with real class-level attributes/constants."""
    unique, file_classes = _v351_base_python_local_class_index(work, manifest)
    for info in unique.values():
        node = info.get('node')
        class_attrs = set()
        for child in getattr(node, 'body', []) or []:
            if isinstance(child, ast.Assign):
                for target in child.targets:
                    if isinstance(target, ast.Name):
                        class_attrs.add(target.id)
            elif isinstance(child, ast.AnnAssign) and isinstance(child.target, ast.Name):
                class_attrs.add(child.target.id)
        info['class_attrs'] = class_attrs

    # Inherit class attributes from uniquely resolved local bases, just as the base index already
    # does for methods/self attributes.
    changed = True
    rounds = 0
    while changed and rounds < 8:
        rounds += 1
        changed = False
        for info in unique.values():
            for base_name in info.get('bases') or []:
                base = unique.get(base_name)
                if not base:
                    continue
                before = len(info.get('class_attrs') or set())
                info.setdefault('class_attrs', set()).update(base.get('class_attrs') or set())
                if len(info['class_attrs']) != before:
                    changed = True
    return unique, file_classes


def _python_method_contract_requirements(work, manifest, include_generated_acceptance_tests=False):
    """Filter false missing-member findings for class constants such as InventoryView.COLUMNS."""
    requirements = _v351_base_python_method_contract_requirements(
        work, manifest, include_generated_acceptance_tests=include_generated_acceptance_tests
    )
    if not requirements:
        return requirements
    class_index, _ = _python_local_class_index(work, manifest)
    filtered = {}
    for key, evidence in requirements.items():
        _provider, class_name, member = key
        info = class_index.get(class_name) or {}
        available = set(info.get('class_attrs') or set())
        if member in available:
            continue
        filtered[key] = evidence
    return filtered


def _v351_meaningful_words(text):
    stop = {
        'the','a','an','and','or','for','to','of','in','on','with','from','module','file','layer',
        'application','app','project','provides','provide','handles','handling','implementation','core'
    }
    return {
        x for x in re.findall(r'[a-z0-9]+', str(text or '').lower())
        if len(x) > 2 and x not in stop
    }


def _v351_is_test_path(path):
    low = str(path or '').replace('\\','/').lower()
    name = Path(low).name
    return (
        '/tests/' in '/' + low.strip('/') + '/' or '/test/' in '/' + low.strip('/') + '/'
        or name.startswith('test_') or name.endswith('_test.py') or name.endswith('.test.js')
        or name.endswith('.test.ts') or name.endswith('.spec.js') or name.endswith('.spec.ts')
    )


def _v351_architecture_collision_issues(manifest):
    """Find likely duplicate authoritative providers before expensive implementation begins.

    Duplicate names are legal in software, so this is deliberately conservative: tests and
    __init__ re-exports are ignored, strong provider-type symbols are treated as authoritative,
    and other duplicates require overlapping responsibilities.
    """
    providers = {}
    files = [x for x in (manifest or {}).get('files') or [] if isinstance(x, dict)]
    strong_suffixes = (
        'Service','Manager','Repository','Controller','Gateway','Client','Store','Engine',
        'Coordinator','Orchestrator','Database','Registry','Provider','ViewModel'
    )
    for item in files:
        path = str(item.get('path') or '').replace('\\','/')
        if not path or Path(path).name == '__init__.py' or _v351_is_test_path(path):
            continue
        purpose = str(item.get('purpose') or '')
        words = _v351_meaningful_words(purpose)
        for symbol in _normalize_export_contract(item.get('exports')):
            symbol = str(symbol or '').strip()
            if not symbol or symbol.startswith('_'):
                continue
            providers.setdefault(symbol, []).append((path, purpose, words))

    issues = []
    for symbol, rows in sorted(providers.items()):
        unique_paths = []
        for path, purpose, words in rows:
            if path not in [x[0] for x in unique_paths]:
                unique_paths.append((path, purpose, words))
        if len(unique_paths) < 2:
            continue
        strong = symbol.endswith(strong_suffixes)
        overlap = False
        for i in range(len(unique_paths)):
            for j in range(i + 1, len(unique_paths)):
                a = unique_paths[i][2]; b = unique_paths[j][2]
                if a and b:
                    score = len(a & b) / max(1, min(len(a), len(b)))
                    if score >= 0.5:
                        overlap = True
        if strong or overlap:
            issues.append({
                'symbol': symbol,
                'files': [x[0] for x in unique_paths],
                'problem': (
                    f'DUPLICATE AUTHORITATIVE PROVIDER: export {symbol!r} is owned by multiple planned files: '
                    + ', '.join(x[0] for x in unique_paths)
                    + '. Choose one canonical provider or explicitly rename/split responsibilities.'
                ),
            })
    return issues


def _v351_component_owner_map(manifest):
    comps = _v35_sanitize_components((manifest or {}).get('components'))
    roots = []
    for comp in comps:
        root = str(comp.get('root') or '.').strip('/') or '.'
        roots.append((root, comp))
    roots.sort(key=lambda x: 0 if x[0] == '.' else len(Path(x[0]).parts), reverse=True)
    out = {}
    for item in (manifest or {}).get('files') or []:
        path = str(item.get('path') or '').replace('\\','/').strip('/')
        owner = None
        for root, comp in roots:
            if root == '.' or path == root or path.startswith(root.rstrip('/') + '/'):
                owner = comp
                if root != '.':
                    break
        if owner:
            out[path] = str(owner.get('id') or '')
    return out


QWEN_SCHEMA_V351_COMPONENT_REVIEW = {
    'type': 'object',
    'properties': {
        'component_id': {'type': 'string'},
        'shared_contracts': {'type': 'array', 'items': {'type': 'string'}},
        'files': {'type': 'array', 'items': {'type': 'object', 'properties': {
            'path': {'type': 'string'}, 'purpose': {'type': 'string'},
            'phase': {'type': 'string', 'enum': ['foundation','data','service','ui','integration','test','docs']},
            'depends_on': {'type': 'array', 'items': {'type': 'string'}},
            'exports': {'type': 'array', 'items': {'type': 'string'}},
            'contracts': {'type': 'array', 'items': {'type': 'string'}},
        }, 'required': ['path','purpose','phase','depends_on','exports','contracts'], 'additionalProperties': False}},
    },
    'required': ['component_id','shared_contracts','files'],
    'additionalProperties': False,
}


def _v351_refine_component_plans(user_request, manifest, max_files, progress_callback=None):
    """Bounded second-level planning for large or genuinely multi-component repositories."""
    if not V351_HIERARCHICAL_REFINEMENT:
        return manifest
    files = list((manifest or {}).get('files') or [])
    comps = _v35_sanitize_components((manifest or {}).get('components'))
    if len(files) < V351_HIERARCHICAL_FILE_THRESHOLD and len(comps) <= 1:
        return manifest
    owner = _v351_component_owner_map(manifest)
    current = dict(manifest)
    current['files'] = [dict(x) for x in files]
    by_path = {str(x.get('path') or ''): x for x in current['files']}
    global_paths = set(by_path)

    refined = 0
    for comp in comps:
        if refined >= V351_COMPONENT_REFINEMENT_LIMIT:
            break
        cid = str(comp.get('id') or '')
        subset = [dict(x) for x in current['files'] if owner.get(str(x.get('path') or '')) == cid]
        if not subset:
            continue
        refined += 1
        prompt = (
            'V35.1 HIERARCHICAL COMPONENT REVIEW. Return ONLY strict JSON for this ONE component.\n'
            'Do not redesign unrelated components. Preserve the user request and cross-component public contracts.\n'
            'Correct duplicate responsibilities, dependency direction, exports, method signatures, model fields, and file boundaries inside this component.\n'
            'Every depends_on path must be an existing project path. Do not create files outside this component root.\n'
            f'USER REQUEST:\n{user_request}\n\n'
            f'GLOBAL PROJECT SUMMARY: {current.get("summary", "")}\n'
            f'COMPONENT:\n{json.dumps(comp, ensure_ascii=False, indent=2)}\n\n'
            f'GLOBAL SHARED CONTRACTS:\n{json.dumps(current.get("shared_contracts") or [], ensure_ascii=False, indent=2)}\n\n'
            f'CURRENT COMPONENT FILES:\n{json.dumps(subset, ensure_ascii=False, indent=2)}\n'
        )
        ok, text = _qwen_call(
            prompt, progress_callback, f'V35.1 component plan {refined}/{min(len(comps), V351_COMPONENT_REFINEMENT_LIMIT)}: {cid}',
            profile='plan', max_tokens=8192, thinking=False,
            response_schema=QWEN_SCHEMA_V351_COMPONENT_REVIEW,
            schema_name='v351_component_review', strict_output=True,
        )
        if not ok:
            continue
        try:
            obj = _extract_json(text)
        except Exception:
            continue
        if not isinstance(obj, dict) or str(obj.get('component_id') or '') != cid:
            continue
        reviewed_files = _sanitize_manifest_files(obj.get('files') or [], max_files)
        comp_root = str(comp.get('root') or '.').strip('/') or '.'
        for item in reviewed_files:
            path = str(item.get('path') or '').replace('\\','/').strip('/')
            if comp_root != '.' and not (path == comp_root or path.startswith(comp_root + '/')):
                continue
            if path not in global_paths and len(by_path) >= max_files:
                continue
            if path not in global_paths:
                global_paths.add(path)
                current['files'].append(item)
                by_path[path] = item
            else:
                by_path[path].update(item)
        shared = _v33_normalize_contract_lines(obj.get('shared_contracts'), 80)
        for line in shared:
            if line not in current.setdefault('shared_contracts', []):
                current['shared_contracts'].append(line)

    valid_paths = {str(x.get('path') or '') for x in current['files']}
    for item in current['files']:
        item['depends_on'] = [d for d in _v33_normalize_dep_paths(item.get('depends_on'), item.get('path')) if d in valid_paths and d != item.get('path')]
    return current


def _v351_correct_architecture_collisions(user_request, manifest, max_files, progress_callback=None):
    current = manifest
    for pass_no in range(1, 3):
        collisions = _v351_architecture_collision_issues(current)
        if not collisions:
            break
        prompt = (
            'V35.1 ARCHITECTURE COLLISION GATE. Return ONLY a corrected COMPLETE project manifest JSON.\n'
            'Implementation has NOT started. Resolve these duplicate authoritative providers now instead of generating competing modules.\n'
            'A public service/manager/repository/controller/database provider must have one canonical owner unless the symbols are deliberately renamed.\n'
            'Do not remove user-required behavior. Preserve valid files and toolchain components.\n\n'
            f'USER REQUEST:\n{user_request}\n\n'
            'COLLISIONS:\n' + '\n'.join('- ' + x['problem'] for x in collisions) + '\n\n'
            f'CURRENT MANIFEST:\n{json.dumps(current, ensure_ascii=False, indent=2)}\n'
        )
        ok, text = _qwen_call(
            prompt, progress_callback, f'V35.1 architecture collision repair {pass_no}/2',
            profile='plan', max_tokens=12288, thinking=False,
            response_schema=QWEN_SCHEMA_PROJECT_PLAN, schema_name='v351_collision_repair', strict_output=True,
        )
        if not ok:
            break
        reviewed = _parse_project_plan(text, user_request, max_files)
        if not reviewed:
            break
        current = _merge_manifest(current, reviewed, user_request, max_files)
    return current


def _review_project_plan(user_request, manifest, max_files, progress_callback=None):
    current = _v351_base_review_project_plan(user_request, manifest, max_files, progress_callback)
    current = _v351_refine_component_plans(user_request, current, max_files, progress_callback)
    current = _v351_correct_architecture_collisions(user_request, current, max_files, progress_callback)
    return current


def _v33_write_architecture(work, manifest):
    try:
        payload = {
            'version': f'V{V35_VERSION}',
            'engine': 'UNIVERSAL_COMPLETION_ENGINE',
            'planner_mode': 'hierarchical' if V351_HIERARCHICAL_REFINEMENT else 'single-manifest',
            'toolchain_adapter': manifest.get('toolchain_adapter'),
            'platform': manifest.get('platform'), 'language': manifest.get('language'), 'framework': manifest.get('framework'),
            'build_system': manifest.get('build_system'), 'package_manager': manifest.get('package_manager'),
            'project_name': manifest.get('project_name'), 'entrypoint': manifest.get('entrypoint'),
            'architecture_rules': manifest.get('architecture_rules') or [],
            'shared_contracts': manifest.get('shared_contracts') or [],
            'components': manifest.get('components') or [],
            'acceptance_tests': manifest.get('acceptance_tests') or [],
            'architecture_collisions': _v351_architecture_collision_issues(manifest),
            'implementation_order': [x.get('path') for x in _v33_dependency_ordered_files(manifest)],
            'files': manifest.get('files') or [],
        }
        Path(work, V33_ARCHITECTURE_FILE).write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        pass


def _v33_write_build_status(work, manifest, stage, current_file='', implemented=None):
    """Live status is derived from the filesystem so shell-completion repairs cannot leave stale counts."""
    try:
        root = Path(work)
        real = _existing_real_source_files(root)
        skeletons = []
        committed_bytes = 0
        visible_bytes = 0
        for rel in real:
            path = root / rel
            size = path.stat().st_size
            visible_bytes += size
            text = path.read_text(encoding='utf-8', errors='replace')
            if V33_SKELETON_MARKER in text[:800] or V34_RECOVERY_SEED_MARKER in text[:800]:
                skeletons.append(rel)
            else:
                committed_bytes += size
        actual_implemented = len(real) - len(skeletons)
        try:
            context_capacity = int(qwen_runtime_context_tokens() or 0)
        except Exception:
            context_capacity = 0
        payload = {
            'version': f'V{V35_VERSION}', 'engine': 'UNIVERSAL_COMPLETION_ENGINE',
            'stage': stage, 'current_file': current_file,
            'planner_mode': 'hierarchical' if V351_HIERARCHICAL_REFINEMENT else 'single-manifest',
            'validation_mode': 'strict', 'context_capacity': context_capacity,
            'component_count': len(_v35_sanitize_components((manifest or {}).get('components'))),
            'planned_files': len((manifest or {}).get('files') or []),
            'visible_source_files': len(real), 'skeleton_files_remaining': len(skeletons),
            'implemented_source_files': actual_implemented,
            'visible_source_bytes': visible_bytes, 'committed_source_bytes': committed_bytes,
            'updated_at': _utc_stamp(),
        }
        if implemented is not None and int(implemented) != actual_implemented:
            payload['legacy_reported_implemented_source_files'] = int(implemented)
        Path(work, V33_BUILD_STATUS_FILE).write_text(json.dumps(payload, indent=2), encoding='utf-8')
    except Exception:
        pass


def _v351_node_test_strategy(root, data=None):
    """Return a noninteractive npm test argv + environment for the detected JS test runner."""
    root = Path(root)
    npm = shutil.which('npm') or 'npm'
    if data is None:
        try:
            data = json.loads((root / 'package.json').read_text(encoding='utf-8'))
        except Exception:
            data = {}
    scripts = data.get('scripts') or {}
    test_script = str(scripts.get('test') or '').strip()
    deps = set((data.get('dependencies') or {}).keys()) | set((data.get('devDependencies') or {}).keys())
    blob = (test_script + ' ' + ' '.join(deps)).lower()
    env = os.environ.copy()
    env['CI'] = 'true'
    env['NODE_ENV'] = 'test'

    if '@playwright/test' in deps or re.search(r'\bplaywright\s+test\b', blob):
        return [npm, 'exec', '--', 'playwright', 'test', '--reporter=line'], env, 'playwright'
    if 'vitest' in deps or re.search(r'\bvitest\b', blob):
        return [npm, 'exec', '--', 'vitest', 'run'], env, 'vitest'
    if 'react-scripts' in deps or 'react-scripts test' in blob:
        return [npm, 'test', '--', '--watchAll=false'], env, 'react-scripts'
    if 'jest' in deps or re.search(r'\bjest\b', blob):
        return [npm, 'exec', '--', 'jest', '--runInBand', '--ci'], env, 'jest'
    if '@angular/core' in deps or re.search(r'\bng\s+test\b', blob):
        return [npm, 'test', '--', '--watch=false'], env, 'angular'
    if 'mocha' in deps or re.search(r'\bmocha\b', blob):
        return [npm, 'test'], env, 'mocha'
    if re.search(r'\bnode\s+--test\b', blob):
        return [npm, 'test'], env, 'node-test'
    return [npm, 'test'], env, 'generic-ci'


def _v35_node_component(root, component):
    package = Path(root) / 'package.json'
    outputs = []
    npm = shutil.which('npm')
    if not npm:
        return False, 'Node component requires npm, but npm is not installed/available.'
    try:
        data = json.loads(package.read_text(encoding='utf-8'))
        scripts = data.get('scripts') or {}
    except Exception as exc:
        return False, f'package.json is invalid JSON: {exc}'
    for key in ('build','test'):
        if key in scripts and _v35_is_noop_command(scripts.get(key)):
            return False, f'package.json script {key!r} is a no-op and cannot satisfy V36 verification: {scripts.get(key)}'
    install = [npm, 'ci', '--no-audit', '--no-fund'] if (Path(root) / 'package-lock.json').exists() else [npm, 'install', '--no-audit', '--no-fund']
    ok, out = _v35_run(install, root, outputs)
    if not ok:
        return False, out
    if 'build' in scripts:
        ok, out = _v35_run([npm, 'run', 'build'], root, outputs)
        if not ok:
            return False, out
    elif str(component.get('toolchain_adapter')) in {'react','nextjs','vue','angular','sveltekit','nuxt','vite'}:
        return False, 'Web framework component has no real package.json build script.'
    if 'test' in scripts and not _v35_is_noop_command(scripts.get('test')):
        cmd, env, runner = _v351_node_test_strategy(root, data)
        outputs.append(f'V36 JS test runner: {runner}; command: {" ".join(str(x) for x in cmd)}')
        ok, out = _v35_run(cmd, root, outputs, timeout=PROJECT_TEST_TIMEOUT, env=env)
        if not ok:
            return False, out
    return True, '\n'.join(outputs)[-8000:]


def _v35_discover_components(work, manifest):
    out = _v351_base_discover_components(work, manifest)
    root_work = Path(work).resolve()
    for comp in out:
        if str(comp.get('toolchain_adapter') or '') not in {'node','react','vite','nextjs','vue','sveltekit','nuxt','angular','electron','react_native','expo'}:
            continue
        root = root_work if comp.get('root') in ('','.') else root_work / str(comp.get('root'))
        package = root / 'package.json'
        if not package.exists():
            continue
        try:
            data = json.loads(package.read_text(encoding='utf-8', errors='replace'))
        except Exception:
            continue
        scripts = data.get('scripts') or {}
        if 'test' in scripts and not _v35_is_noop_command(scripts.get('test')):
            cmd, _env, runner = _v351_node_test_strategy(root, data)
            # Launcher commands must not depend on the absolute npm path discovered on Jarvis.
            parts = ['npm' if i == 0 else str(x) for i, x in enumerate(cmd)]
            comp['test_command'] = subprocess.list2cmdline(parts) if os.name == 'nt' else ' '.join(shlex.quote(x) for x in parts)
            comp['test_runner'] = runner
        else:
            comp['test_command'] = ''
    try:
        (root_work / V35_COMPONENT_FILE).write_text(json.dumps({'version': V35_VERSION, 'components': out}, indent=2), encoding='utf-8')
    except Exception:
        pass
    return out


def _v351_hard_deterministic_issues(issues):
    """Static issues that must be resolved before it is meaningful/safe to execute the project."""
    hard = {
        'static','missing','incomplete','toolchain','contract','identity','dependency','definite_none',
        'data_contract','generated_test_undefined_name','generated_test_isolation','generated_test_signature',
        'generated_test_contract','call_signature'
    }
    return [x for x in issues if str(x.get('kind') or '') in hard]


def _acceptance_repair_cycle(user_request, manifest, work, progress_callback=None):
    """V35.1 gives concrete runtime/test failures priority over speculative class-member reconciliation."""
    if V351_RUNTIME_PREFLIGHT_ROUNDS > 0:
        for preflight in range(1, V351_RUNTIME_PREFLIGHT_ROUNDS + 1):
            deterministic = _deterministic_acceptance_issues(work, manifest)
            if _v351_hard_deterministic_issues(deterministic):
                break
            _progress(
                progress_callback,
                f'V35.1 evidence-first runtime preflight {preflight}/{V351_RUNTIME_PREFLIGHT_ROUNDS}...',
                stage='testing', percent=82,
            )
            real_ok, real_output = _run_real_project_validation(work, user_request, manifest)
            if real_ok:
                break
            _append_project_event(
                work, 'v351_runtime_preflight_failure',
                'Prioritizing a real executed test/build/startup failure before lower-confidence static member reconciliation.',
                failure_signature=_validation_failure_signature(real_output), preflight=preflight,
            )
            repaired = _repair_real_validation_failure(
                user_request, manifest, work, real_output, progress_callback
            )
            if not repaired:
                break
            _v33_write_build_status(work, manifest, f'v351_runtime_preflight_{preflight}')
    return _v351_base_acceptance_repair_cycle(user_request, manifest, work, progress_callback)


# Ensure V35.1 identity is visible to launch instructions and future state files.
