# V36 graph/contract caches: keep deterministic repo intelligence cheap even for 100+ files.
_V36_REPO_CACHE = {}
_V36_CONTRACT_CACHE = {}
_v36_uncached_build_repo_graph = _v36_build_repo_graph
_v36_uncached_build_contract_registry = _v36_build_contract_registry


def _v36_repo_state_token(work, manifest=None):
    root=Path(work);parts=[]
    for rel,p in _v36_project_source_files(root,manifest):
        try:
            st=p.stat();parts.append((rel,int(st.st_mtime_ns),int(st.st_size)))
        except Exception:continue
    mf=[]
    for item in (manifest or {}).get('files') or []:
        mf.append((str(item.get('path') or ''),tuple(item.get('depends_on') or []),tuple(_normalize_export_contract(item.get('exports')))))
    raw=json.dumps([parts,mf],ensure_ascii=False,sort_keys=True,default=str)
    return hashlib.sha1(raw.encode('utf-8',errors='replace')).hexdigest()


def _v36_build_repo_graph(work, manifest=None, write=True):
    root=Path(work);token=_v36_repo_state_token(root,manifest);key=(str(root.resolve()),token)
    payload=_V36_REPO_CACHE.get(key)
    if payload is None:
        payload=_v36_uncached_build_repo_graph(root,manifest,write=False)
        # Keep only the newest few states per workspace.
        for old in [k for k in list(_V36_REPO_CACHE) if k[0]==key[0] and k!=key][:-3]:_V36_REPO_CACHE.pop(old,None)
        _V36_REPO_CACHE[key]=payload
    if write:
        try:(root/V36_REPO_GRAPH_FILE).write_text(json.dumps(payload,indent=2,ensure_ascii=False),encoding='utf-8')
        except Exception:pass
    return payload


def _v36_build_contract_registry(work, manifest=None, write=True):
    root=Path(work);token=_v36_repo_state_token(root,manifest);key=(str(root.resolve()),token)
    payload=_V36_CONTRACT_CACHE.get(key)
    if payload is None:
        payload=_v36_uncached_build_contract_registry(root,manifest,write=False)
        for old in [k for k in list(_V36_CONTRACT_CACHE) if k[0]==key[0] and k!=key][:-3]:_V36_CONTRACT_CACHE.pop(old,None)
        _V36_CONTRACT_CACHE[key]=payload
    if write:
        try:(root/V36_CONTRACT_REGISTRY_FILE).write_text(json.dumps(payload,indent=2,ensure_ascii=False),encoding='utf-8')
        except Exception:pass
    return payload

# V36 stronger cross-file Python call checker: follows __init__ type annotations into self attributes.
_v36_base_deterministic_acceptance_issues = _deterministic_acceptance_issues


def _v36_python_provider_method_index(work, manifest):
    classes={}
    for rel,p in _v36_project_source_files(work,manifest):
        if Path(rel).suffix.lower() not in {'.py','.pyw'}:continue
        try:tree=ast.parse(p.read_text(encoding='utf-8',errors='replace'))
        except Exception:continue
        for node in tree.body:
            if not isinstance(node,ast.ClassDef):continue
            methods={}
            for fn in node.body:
                if not isinstance(fn,(ast.FunctionDef,ast.AsyncFunctionDef)):continue
                pos=list(fn.args.posonlyargs)+list(fn.args.args)
                if pos and pos[0].arg in {'self','cls'}:pos=pos[1:]
                defaults=len(fn.args.defaults or [])
                required=max(0,len(pos)-defaults)
                methods[fn.name]={'required':required,'max':None if fn.args.vararg else len(pos),'signature':f"{fn.name}({', '.join(a.arg for a in pos)})",'file':rel,'line':getattr(fn,'lineno',0)}
            classes.setdefault(node.name,[]).append({'file':rel,'methods':methods})
    return {k:v[0] for k,v in classes.items() if len(v)==1}


def _v36_annotation_name(node):
    if isinstance(node,ast.Name):return node.id
    if isinstance(node,ast.Attribute):return node.attr
    if isinstance(node,ast.Subscript):return _v36_annotation_name(node.value)
    if isinstance(node,ast.Constant) and isinstance(node.value,str):return node.value.split('.')[-1]
    return ''


def _v36_bound_member_call_issues(work, manifest):
    providers=_v36_python_provider_method_index(work,manifest);issues=[]
    for rel,p in _v36_project_source_files(work,manifest):
        if Path(rel).suffix.lower() not in {'.py','.pyw'}:continue
        try:tree=ast.parse(p.read_text(encoding='utf-8',errors='replace'))
        except Exception:continue
        for cls in [x for x in tree.body if isinstance(x,ast.ClassDef)]:
            self_types={}
            init=next((x for x in cls.body if isinstance(x,(ast.FunctionDef,ast.AsyncFunctionDef)) and x.name=='__init__'),None)
            if init:
                param_types={a.arg:_v36_annotation_name(a.annotation) for a in list(init.args.posonlyargs)+list(init.args.args) if a.annotation is not None}
                for node in ast.walk(init):
                    if isinstance(node,(ast.Assign,ast.AnnAssign)):
                        targets=node.targets if isinstance(node,ast.Assign) else [node.target]
                        value=node.value
                        for target in targets:
                            if isinstance(target,ast.Attribute) and isinstance(target.value,ast.Name) and target.value.id=='self':
                                typ=''
                                if isinstance(value,ast.Name):typ=param_types.get(value.id,'')
                                elif isinstance(value,ast.Call):
                                    if isinstance(value.func,ast.Name):typ=value.func.id
                                    elif isinstance(value.func,ast.Attribute):typ=value.func.attr
                                if typ:self_types[target.attr]=typ
            for fn in [x for x in cls.body if isinstance(x,(ast.FunctionDef,ast.AsyncFunctionDef))]:
                local_types={}
                # Simple local constructor assignments: db = DatabaseManager(...)
                for node in ast.walk(fn):
                    if isinstance(node,ast.Assign) and isinstance(node.value,ast.Call):
                        typ=''
                        if isinstance(node.value.func,ast.Name):typ=node.value.func.id
                        elif isinstance(node.value.func,ast.Attribute):typ=node.value.func.attr
                        for target in node.targets:
                            if isinstance(target,ast.Name) and typ:local_types[target.id]=typ
                for node in ast.walk(fn):
                    if not isinstance(node,ast.Call) or not isinstance(node.func,ast.Attribute):continue
                    method=node.func.attr;owner=node.func.value;typ=''
                    if isinstance(owner,ast.Attribute) and isinstance(owner.value,ast.Name) and owner.value.id=='self':typ=self_types.get(owner.attr,'')
                    elif isinstance(owner,ast.Name):typ=local_types.get(owner.id,'')
                    if not typ or typ not in providers:continue
                    method_info=providers[typ]['methods'].get(method)
                    if method_info is None:
                        issues.append({'file':rel,'provider_file':providers[typ]['file'],'class':typ,'member':method,'kind':'call_signature','line':getattr(node,'lineno',0),'problem':f'V36 machine contract: {cls.name}.{fn.name} calls {typ}.{method}, but unique local provider {providers[typ]["file"]} has no such method.'})
                        continue
                    actual=len(node.args);required=int(method_info['required']);maximum=method_info['max']
                    if actual<required or (maximum is not None and actual>int(maximum)):
                        range_text=f'{required}..{maximum}' if maximum is not None and maximum!=required else str(required)
                        issues.append({'file':rel,'provider_file':providers[typ]['file'],'class':typ,'member':method,'kind':'call_signature','line':getattr(node,'lineno',0),'problem':f'V36 machine contract: {cls.name}.{fn.name} calls {typ}.{method} with {actual} positional argument(s), but provider signature {method_info["signature"]} accepts {range_text}. Repair caller/provider contract before runtime.'})
    return issues


def _deterministic_acceptance_issues(work, manifest):
    issues=_v36_base_deterministic_acceptance_issues(work,manifest)
    existing={(str(x.get('file') or ''),re.sub(r'\s+',' ',str(x.get('problem') or '')).strip()) for x in issues}
    for item in _v36_bound_member_call_issues(work,manifest):
        key=(str(item.get('file') or ''),re.sub(r'\s+',' ',str(item.get('problem') or '')).strip())
        if key not in existing:
            issues.append(item);existing.add(key)
    return issues


# ============================================================================
# V36.1 REAL-RUN HARDENING
# Fixes learned from the first V36 TaskForge multi-component generation:
# - preserve multiple explicit stacks instead of collapsing to one adapter
# - stop runtime names such as Node.js from becoming fake requested files
# - salvage malformed END FILE continuation artifacts
# - preserve explicit user requirements with deterministic coverage
# - canonicalize repeated shared contracts
# - validate embedded SQLite DDL before source is committed
# - detect async-generator/context-manager contract misuse early
# - sanitize Windows-hostile declared commands and support-only components
# ============================================================================
V36_VERSION = '36.1.0'
V361_REAL_RUN_HARDENING = True
V36_REQUIREMENTS_MAX_CHARS = max(int(V36_REQUIREMENTS_MAX_CHARS), 18000)

_v361_base_strip_transport = _v351_strip_legacy_transport_markers
_v361_base_extract_requested_paths = _extract_explicit_requested_paths
_v361_base_generate_requirements = _v36_generate_requirements
_v361_base_parse_project_plan = _parse_project_plan
_v361_base_merge_manifest = _merge_manifest
_v361_base_review_project_plan = _review_project_plan
_v361_base_enforce_stack = _enforce_request_stack_on_manifest
_v361_base_recovery_manifest = _v34_recovery_manifest
_v361_base_candidate_transaction_error = _candidate_transaction_error
_v361_base_generate_planned_file = _generate_planned_file
_v361_base_deterministic_issues = _deterministic_acceptance_issues
_v361_base_stack_skill_names = _v36_stack_skill_names
_v361_base_write_architecture = _v33_write_architecture
_v361_base_write_build_status = _v33_write_build_status


def _v361_transport_path_pattern(expected_path):
    expected = str(expected_path or '').replace('\\','/').strip('/')
    if not expected:
        return ''
    parts = [re.escape(x) for x in expected.split('/')]
    full = r'[\\/]'.join(parts)
    base = re.escape(Path(expected).name)
    return rf'(?:{full}|{base})'


def _v351_strip_legacy_transport_markers(text, expected_path):
    """V36.1 structurally salvages legacy END FILE contamination.

    V36.0 only removed a perfectly formed marker at the outer edge. Real Qwen output can emit
    variants such as ``===== END FILE backend/tests/test_api.py >>><source continuation only>``
    and then continue duplicating source. For a single-file response, the first matching END FILE
    marker is an unambiguous transport boundary, so everything after it is discarded.
    """
    raw = str(text or '').replace('\ufeff','')
    patt = _v361_transport_path_pattern(expected_path)
    if not raw or not patt:
        return _v361_base_strip_transport(raw, expected_path)
    lines = raw.splitlines()
    begin_re = re.compile(rf'^\s*(?:=+|<{2,})\s*(?:BEGIN\s+)?FILE\s*:?[\s`"\']*{patt}\b.*?(?:=+|>{2,})?\s*$', re.I)
    end_re = re.compile(rf'^\s*(?:=+|<{2,})\s*END\s+FILE\s*:?[\s`"\']*{patt}\b.*$', re.I)
    # Remove a matching transport header only when it is the first non-empty line.
    while lines and not lines[0].strip():
        lines.pop(0)
    if lines and begin_re.match(lines[0]):
        lines.pop(0)
        while lines and not lines[0].strip():
            lines.pop(0)
    # The first matching END marker terminates this file even when the model added malformed
    # suffix text or another source continuation after the marker.
    cut = None
    for i,line in enumerate(lines):
        if end_re.match(line):
            cut = i
            break
    if cut is not None:
        prefix = lines[:cut]
        while prefix and not prefix[-1].strip():
            prefix.pop()
        if prefix:
            return '\n'.join(prefix) + '\n'
    return _v361_base_strip_transport('\n'.join(lines) + ('\n' if lines else ''), expected_path)


_V361_TECH_BARE_NAMES = {
    'node.js','vue.js','next.js','react.js','angular.js','three.js','express.js','electron.js',
    'deno.js','bun.js','jquery.js','socket.io.js','chart.js','nuxt.js'
}


def _extract_explicit_requested_paths(user_request):
    """Only preserve paths the user actually presented as files.

    A technology mention such as ``Node.js installed`` is not a request for a file named Node.js.
    Bare filenames are accepted when quoted/backticked, presented as a tree/list entry, or near
    explicit file/path language. Paths containing a directory separator remain unambiguous.
    """
    text = str(user_request or '')
    exts = r'(?:py|pyw|js|mjs|cjs|jsx|ts|tsx|html|htm|css|scss|json|ya?ml|toml|ini|cfg|md|txt|csv|sql|sh|ps1|bat|cmd|c|cc|cpp|cxx|h|hpp|cs|java|kt|go|rs|rb|php|swift|dart|xml|gradle|properties)'
    pattern = re.compile(r'(?<![A-Za-z0-9_.-])((?:[A-Za-z0-9_.-]+[\\/])*[A-Za-z0-9_.-]+\.' + exts + r')\b', re.I)
    out=[]
    for match in pattern.finditer(text):
        raw=match.group(1).replace('\\','/')
        low=raw.lower()
        before=text[max(0,match.start()-90):match.start()]
        after=text[match.end():min(len(text),match.end()+50)]
        line_start=text.rfind('\n',0,match.start())+1
        line_end=text.find('\n',match.end())
        if line_end<0: line_end=len(text)
        line=text[line_start:line_end].strip()
        explicit_context=bool(re.search(r'(?i)\b(?:file|filename|path|entrypoint|script|module|create|include|named|called|save\s+as)\b[^\n]{0,70}$',before))
        quoted = (match.start()>0 and text[match.start()-1] in '`"\'') or (match.end()<len(text) and text[match.end()] in '`"\'')
        tree_like = bool(re.match(r'^[\s│├└─+*\-]*(?:`|"|\')?'+re.escape(match.group(1))+r'(?:`|"|\')?\s*$', line, re.I))
        has_dir='/' in raw
        if low in _V361_TECH_BARE_NAMES and not (explicit_context or quoted or tree_like or has_dir):
            continue
        if not (has_dir or explicit_context or quoted or tree_like):
            continue
        try: rel=_safe_relative(raw)
        except Exception: continue
        if rel.name in _RESERVED_OUTPUT_NAMES or rel.name.startswith('JARVIS_'): continue
        value=rel.as_posix()
        if value not in out: out.append(value)
    if re.search(r'(?m)^\s*(?:[│├└─\-\s]*)?\.gitignore\s*$', text):
        out.append('.gitignore') if '.gitignore' not in out else None
    return out


def _v361_clean_req_text(value):
    text=re.sub(r'[`*_#]+','',str(value or '')).strip()
    text=re.sub(r'\s+',' ',text)
    return text.strip(' -:\t')


def _v361_extract_source_requirements(user_request):
    """Extract user-authored bullets/numbered requirements without using the model."""
    heading='general'; items=[]
    for raw in str(user_request or '').splitlines():
        line=raw.strip()
        if not line: continue
        hm=re.match(r'^#{1,6}\s+(.+)$',line) or re.match(r'^\*\*(.+?)\*\*\s*$',line)
        if hm:
            heading=_v361_clean_req_text(hm.group(1)).lower() or heading
            continue
        m=re.match(r'^(?:[-*+]\s+|\d+[.)]\s+)(.+)$',line)
        if not m:
            # Preserve explicit MUST requirements even when written as prose.
            if re.search(r'(?i)\b(?:must|must not|required|should|do not|cannot|can not)\b',line) and len(line)<=600:
                value=_v361_clean_req_text(line)
            else:
                continue
        else:
            value=_v361_clean_req_text(m.group(1))
        if not value or len(value)<3: continue
        category='functional'
        h=heading.lower()
        if any(x in h for x in ('acceptance','before declaring','verify')): category='acceptance'
        elif any(x in h for x in ('test','testing')): category='test'
        elif any(x in h for x in ('platform','technology','stack','constraint','database','validation')): category='constraint'
        key=re.sub(r'\W+',' ',value.lower()).strip()
        if not key or any(x['key']==key for x in items): continue
        items.append({'id':f'UR-{len(items)+1:03d}','category':category,'text':value,'key':key})
        if len(items)>=180: break
    return items


def _v361_req_tokens(text):
    stop={'the','a','an','and','or','to','of','in','on','for','with','must','should','be','is','are','as','by','it','this','that','from','using','use','users','user'}
    return {x for x in re.findall(r'[a-z0-9_+#.-]{3,}',str(text or '').lower()) if x not in stop}


def _v361_requirement_represented(requirement, existing):
    rt=_v361_req_tokens(requirement)
    if not rt:return True
    for value in existing:
        vt=_v361_req_tokens(value)
        if not vt:continue
        if rt <= vt:return True
        overlap=len(rt & vt)/max(1,len(rt))
        if overlap>=0.72:return True
    return False


def _v36_generate_requirements(user_request, work, progress_callback=None):
    obj=_v361_base_generate_requirements(user_request,work,progress_callback)
    if not isinstance(obj,dict):obj={}
    source=_v361_extract_source_requirements(user_request)
    fields={
        'functional':'functional_requirements','constraint':'constraints',
        'acceptance':'acceptance_criteria','test':'suggested_test_scenarios'
    }
    all_existing=[]
    for field in ('functional_requirements','constraints','acceptance_criteria','suggested_test_scenarios','nonfunctional_requirements'):
        vals=obj.get(field) or []; vals=[vals] if isinstance(vals,str) else list(vals)
        obj[field]=[str(x).strip() for x in vals if str(x).strip()][:180]
        all_existing.extend(obj[field])
    coverage=[]
    for item in source:
        represented=_v361_requirement_represented(item['text'],all_existing)
        field=fields[item['category']]
        if not represented:
            preserved=f"{item['id']}: {item['text']}"
            obj[field].append(preserved);all_existing.append(preserved)
            mapped=preserved
        else:
            mapped='represented by compiled specification'
        coverage.append({'source_id':item['id'],'category':item['category'],'source':item['text'],'mapped_to':mapped})
    obj['source_requirements']=[{'id':x['id'],'category':x['category'],'text':x['text']} for x in source]
    obj['requirement_coverage']=coverage
    obj['coverage_percent']=100 if source else 100
    obj['version']=V36_VERSION;obj['compiled_at']=_utc_stamp()
    try:(Path(work)/V36_REQUIREMENTS_FILE).write_text(json.dumps(obj,indent=2,ensure_ascii=False),encoding='utf-8')
    except Exception:pass
    return obj


def _v361_detect_adapter(blob, role=''):
    low=str(blob or '').lower()
    if role=='frontend':
        if 'expo' in low:return 'expo'
        if 'react native' in low:return 'react_native'
        if 'sveltekit' in low or 'svelte kit' in low:return 'sveltekit'
        if 'next.js' in low or 'nextjs' in low:return 'nextjs'
        if 'angular' in low:return 'angular'
        if 'vue' in low:return 'vue'
        if 'react' in low:return 'react'
        if 'vite' in low:return 'vite'
        if any(x in low for x in ('html','css','vanilla javascript')):return 'static_web'
    if role=='backend':
        if any(x in low for x in ('fastapi','django','flask','python')):return 'python'
        if any(x in low for x in ('express','node.js','nodejs','node backend','typescript backend')):return 'node'
        if any(x in low for x in ('asp.net','.net backend','dotnet backend','c# backend')):return 'dotnet'
        if any(x in low for x in ('spring boot','java backend')):return 'java_gradle'
        if any(x in low for x in ('go backend','golang backend','go api')):return 'go'
        if any(x in low for x in ('rust backend','axum','actix')):return 'rust'
    return 'generic'


def _v361_explicit_component_locks(user_request):
    text=_strip_jarvis_routing_noise(user_request); low=text.lower();locks=[]
    def labelled(label):
        vals=[]
        for m in re.finditer(rf'(?im)^\s*(?:[-*+]\s*)?(?:\*\*)?{label}(?:\*\*)?\s*:\s*(.+)$',text):vals.append(m.group(1))
        return ' '.join(vals)
    fb=labelled('frontend'); bb=labelled('backend')
    fa=_v361_detect_adapter(fb,'frontend') if fb else 'generic'
    ba=_v361_detect_adapter(bb,'backend') if bb else 'generic'
    # Explicit full-stack prompts frequently name both stacks outside a labeled line.
    if fa=='generic' and any(x in low for x in ('react','vite','sveltekit','next.js','angular','vue')) and any(x in low for x in ('frontend','client','spa')):
        fa=_v361_detect_adapter(low,'frontend')
    if ba=='generic' and any(x in low for x in ('fastapi','django','flask','express','spring boot','.net backend','go backend')) and any(x in low for x in ('backend','api','server')):
        ba=_v361_detect_adapter(low,'backend')
    if fa!='generic':locks.append({'id':'frontend','root':'frontend','purpose':'Explicitly requested frontend','toolchain_adapter':fa})
    if ba!='generic':locks.append({'id':'backend','root':'backend','purpose':'Explicitly requested backend','toolchain_adapter':ba})
    return locks


def _v361_explicit_platform(user_request):
    low=str(user_request or '').lower()
    if re.search(r'\bwindows(?:\s+10|\s+11)?\b',low):return 'windows'
    if re.search(r'\bmacos\b|\bmac os\b',low):return 'macos'
    if re.search(r'\blinux\b',low):return 'linux'
    return ''


def _v361_normalize_component_adapter(adapter):
    low=str(adapter or '').strip().lower()
    aliases={
        'fastapi':'python','uvicorn':'python','pytest':'python','pip':'python','python/fastapi':'python',
        'vite/react':'react','react/vite':'react','reactjs':'react','react.js':'react',
        'nodejs':'node','node.js':'node','npm':'node','cargo':'rust','cmake':'cpp_cmake',
        'gradle':'java_gradle','maven':'java_maven','flutter/dart':'flutter'
    }
    if low in aliases:return aliases[low]
    if 'fastapi' in low or 'aiosqlite' in low and 'sqlite' not in low:return 'python'
    if 'vite' in low and 'react' in low:return 'react'
    return low or 'generic'


def _v361_is_support_component(comp):
    adapter=str(comp.get('toolchain_adapter') or '').lower()
    root=str(comp.get('root') or '').lower()
    if any(x in adapter for x in ('jsonschema','json/json','sqlite3/aiosqlite','aiosqlite/sqlite','sqlite')):
        return True
    if root.endswith('/schemas') or root in {'shared/schemas','schemas'}:
        return adapter not in _v34_toolchain_catalog()
    return False


def _v361_strip_component_cd(command, root):
    cmd=str(command or '').strip(); r=str(root or '.').replace('\\','/').strip('/')
    if not cmd:return ''
    if r and r!='.':
        patt=rf'^\s*cd\s+["\']?{re.escape(r)}["\']?\s*(?:&&|&)\s*'
        cmd=re.sub(patt,'',cmd,flags=re.I)
    return cmd.strip()


def _v361_windows_command_sanitize(command, kind='command'):
    cmd=str(command or '').strip()
    if not cmd:return ''
    # Remove a redundant POSIX shell prefix when the actual executable is cross-platform.
    cmd=re.sub(r'^\s*python3\b','python',cmd,flags=re.I)
    cmd=re.sub(r'^\s*\./gradlew\b','gradlew.bat',cmd,flags=re.I)
    # touch/cat/rm are not meaningful native build/test evidence for a Windows delivery target.
    if re.search(r'(?i)^\s*(?:touch|cat|rm\s+-rf|chmod\b|cp\s+-r|mv\s+)',cmd):
        return ''
    return cmd


def _v361_canonicalize_shared_contracts(values):
    vals=_v33_normalize_contract_lines(values,240);out=[];by_symbol={};seen=set()
    for raw in vals:
        text=str(raw).strip(); norm=re.sub(r'\s+',' ',text).lower()
        if not text or norm in seen:continue
        m=re.match(r'^\s*(?:SC[-_ ]?\d+\s*[:.-]?\s*)?[`"\']?([A-Za-z_][A-Za-z0-9_]*)[`"\']?\s*(?:Schema)?\s*[:\-{]',text,re.I)
        symbol=m.group(1).lower() if m else ''
        if symbol and symbol in by_symbol:
            idx=by_symbol[symbol]
            # Keep the most descriptive canonical form for the same named schema/contract.
            if len(text)>len(out[idx]):out[idx]=text
            seen.add(norm);continue
        if symbol:by_symbol[symbol]=len(out)
        out.append(text);seen.add(norm)
    return out[:160]


def _v361_apply_explicit_component_locks(user_request, manifest):
    m=dict(manifest or {}); locks=_v361_explicit_component_locks(user_request)
    comps=[]
    known=set(_v34_toolchain_catalog())
    for comp in _v35_sanitize_components(m.get('components')):
        comp=dict(comp);comp['toolchain_adapter']=_v361_normalize_component_adapter(comp.get('toolchain_adapter'))
        comp['dependency_command']=_v361_strip_component_cd(comp.get('dependency_command'),comp.get('root'))
        comp['build_command']=_v361_strip_component_cd(comp.get('build_command'),comp.get('root'))
        comp['test_command']=_v361_strip_component_cd(comp.get('test_command'),comp.get('root'))
        comp['run_command']=_v361_strip_component_cd(comp.get('run_command'),comp.get('root'))
        if _v361_is_support_component(comp):continue
        comps.append(comp)
    # Explicit role locks override planner metadata for those roots/ids.
    for lock in locks:
        found=None
        for comp in comps:
            if comp.get('id')==lock['id'] or str(comp.get('root') or '')==lock['root']:
                found=comp;break
        spec=_v34_toolchain_catalog().get(lock['toolchain_adapter'],{})
        if found is None:
            found={'id':lock['id'],'root':lock['root'],'purpose':lock['purpose'],'depends_on':[]}
            comps.append(found)
        found['toolchain_adapter']=lock['toolchain_adapter'];found['purpose']=found.get('purpose') or lock['purpose']
        for key in ('dependency_command','build_command','test_command','run_command'):
            if not str(found.get(key) or '').strip() and spec.get(key):found[key]=spec[key]
    # Remove exact duplicate component roots/adapters while keeping independent mixed roots.
    ded=[];seen=set()
    for comp in comps:
        key=(str(comp.get('root') or '.'),str(comp.get('toolchain_adapter') or 'generic'))
        if key in seen:continue
        seen.add(key);ded.append(comp)
    m['components']=ded[:80]
    if len(locks)>=2:
        specs=[_v34_toolchain_catalog().get(x['toolchain_adapter'],{}) for x in locks]
        m['toolchain_adapter']='multi'
        m['language']=' + '.join(dict.fromkeys(str(s.get('language') or '') for s in specs if s.get('language')))
        m['framework']=' + '.join(dict.fromkeys(str(s.get('framework') or '') for s in specs if s.get('framework')))
        m['build_system']=' + '.join(dict.fromkeys(str(s.get('build_system') or '') for s in specs if s.get('build_system')))
        m['package_manager']=' + '.join(dict.fromkeys(str(s.get('package_manager') or '') for s in specs if s.get('package_manager')))
        tools=[]
        for s in specs:
            for tool in s.get('required_tools') or []:
                if tool not in tools:tools.append(tool)
        m['required_tools']=tools
    elif len(locks)==1:
        spec=_v34_toolchain_catalog().get(locks[0]['toolchain_adapter'],{})
        m['toolchain_adapter']=locks[0]['toolchain_adapter']
        for key in ('language','framework','build_system','package_manager'):
            if spec.get(key):m[key]=spec[key]
    platform=_v361_explicit_platform(user_request)
    if platform:m['platform']=platform
    # Windows delivery target: sanitize executable planner commands instead of retaining POSIX-only commands.
    if str(m.get('platform') or '').lower().startswith('windows'):
        for key in ('dependency_command','build_command','test_command','run_command'):
            m[key]=_v361_windows_command_sanitize(m.get(key),key)
        for comp in m['components']:
            for key in ('dependency_command','build_command','test_command','run_command'):
                comp[key]=_v361_windows_command_sanitize(comp.get(key),key)
        tests=[]
        for test in _v35_sanitize_acceptance_tests(m.get('acceptance_tests')):
            t=dict(test)
            if t.get('command'):
                t['command']=_v361_windows_command_sanitize(t['command'],'acceptance')
            tests.append(t)
        m['acceptance_tests']=tests
    m['shared_contracts']=_v361_canonicalize_shared_contracts(m.get('shared_contracts'))
    return m


