def _stack_lock_instructions(user_request):
    locks=_v361_explicit_component_locks(user_request)
    platform=_v361_explicit_platform(user_request)
    if len(locks)>=2:
        rows=[]
        for lock in locks:
            spec=_v34_toolchain_catalog().get(lock['toolchain_adapter'],{})
            rows.append(f"- {lock['id'].upper()} root={lock['root']}: adapter={lock['toolchain_adapter']}; language={spec.get('language','')}; framework={spec.get('framework','')}; build={spec.get('build_system','')}")
        return (
            'EXPLICIT MULTI-COMPONENT TOOLCHAIN LOCK. These are independent required components; do not collapse or substitute them.\n'
            + ('- Delivery platform: '+platform+'\n' if platform else '') + '\n'.join(rows)
            + '\n- Preserve these component roots and native toolchains. Supporting schemas/database files belong to their owning component and are not separate build toolchains.\n'
        )
    # Reproduce V35 behavior for a single explicit stack, but add explicit platform when present.
    explicit=_v35_explicit_toolchain(user_request)
    if explicit=='generic':
        return ('TOOLCHAIN POLICY: The user did not explicitly lock a technology. Choose the best ecosystem from the product requirements; '
                'do not silently default to Python. If the product requires multiple toolchains, declare separate buildable components.\n')
    spec=_v34_toolchain_catalog().get(explicit,{})
    return ('EXPLICIT USER TOOLCHAIN LOCK (preserve it):\n'
            + (f'- Delivery platform: {platform}\n' if platform else '')
            + f"- Adapter: {explicit}\n- Language: {spec.get('language','')}\n- Framework/toolchain: {spec.get('framework','')} / {spec.get('build_system','')}\n"
            '- Do not substitute an unrelated language/framework.\n')


def _v34_recovery_manifest(user_request, max_files):
    locks=_v361_explicit_component_locks(user_request)
    if len(locks)<2:
        return _v361_apply_explicit_component_locks(user_request,_v361_base_recovery_manifest(user_request,max_files))
    # Deterministic recovery for common full-stack requests; the normal model planner remains preferred.
    files=[]
    def add(path,purpose,phase='foundation',deps=None,exports=None,contracts=None):
        if len(files)<max_files:files.append({'path':path,'purpose':purpose,'phase':phase,'depends_on':deps or [],'exports':exports or [],'contracts':contracts or []})
    adapters={x['id']:x['toolchain_adapter'] for x in locks}
    if adapters.get('backend')=='python':
        add('backend/requirements.txt','Backend Python dependencies','foundation')
        add('backend/app/__init__.py','Backend application package','foundation')
        add('backend/app/main.py','Backend application entrypoint','integration',['backend/requirements.txt'],['app'])
        add('backend/tests/test_smoke.py','Backend smoke tests','test',['backend/app/main.py'])
    if adapters.get('frontend') in {'react','vite'}:
        add('frontend/package.json','Frontend package manifest and scripts','foundation')
        add('frontend/index.html','Vite HTML host','integration',['frontend/src/main.tsx'])
        add('frontend/src/App.tsx','Frontend root application','ui')
        add('frontend/src/main.tsx','Frontend entrypoint','integration',['frontend/src/App.tsx'])
        add('frontend/vite.config.ts','Vite configuration','foundation')
        add('frontend/tsconfig.json','TypeScript configuration','foundation')
    add('README.md','Setup and usage instructions','docs')
    m={'project_name':_slug(str(user_request)[:48]) or 'project','summary':'Recovered explicit multi-component project architecture.',
       'project_type':'multi','entrypoint':'backend/app/main.py','run_command':'','acceptance_criteria':[f'The finished project fully satisfies this request: {user_request}'],
       'architecture_rules':['Preserve independently requested frontend and backend toolchains.','Providers and cross-component API contracts must remain consistent.'],
       'shared_contracts':[],'files':files,'components':locks}
    return _v361_apply_explicit_component_locks(user_request,m)


def _v361_sqlite_ddl_error(rel, content):
    if Path(rel).suffix.lower() not in {'.py','.pyw'}:return ''
    text=str(content or '')
    if 'create table' not in text.lower() and 'create index' not in text.lower():return ''
    try:tree=ast.parse(text)
    except Exception:return ''
    statements=[]
    for node in ast.walk(tree):
        if not isinstance(node,ast.Call):continue
        func=node.func
        name=func.attr if isinstance(func,ast.Attribute) else (func.id if isinstance(func,ast.Name) else '')
        if name.lower() not in {'execute','executescript'} or not node.args:continue
        arg=node.args[0]
        if isinstance(arg,ast.Constant) and isinstance(arg.value,str):
            sql=arg.value.strip()
            if re.search(r'(?i)\bcreate\s+(?:table|index)\b',sql):statements.append(sql)
    if not statements:return ''
    import sqlite3
    con=sqlite3.connect(':memory:')
    try:
        for sql in statements:
            try:con.executescript(sql if sql.rstrip().endswith(';') else sql+';')
            except Exception as exc:return f'V36.2 embedded SQLite DDL gate failed in {rel}: {exc}. Repair the CREATE TABLE/INDEX statement before dependent files are generated.'
    finally:con.close()
    return ''


def _v361_async_generator_context_issues(work, manifest):
    root=Path(work);providers={};module_to_file={}
    for rel,p in _v36_project_source_files(root,manifest):
        if Path(rel).suffix.lower() not in {'.py','.pyw'}:continue
        module=_python_module_name_from_rel(rel) if '_python_module_name_from_rel' in globals() else str(Path(rel).with_suffix('')).replace('\\','.').replace('/','.')
        module_to_file[module]=rel
        try:tree=ast.parse(p.read_text(encoding='utf-8',errors='replace'))
        except Exception:continue
        for node in tree.body:
            if not isinstance(node,ast.AsyncFunctionDef):continue
            yields=any(isinstance(x,(ast.Yield,ast.YieldFrom)) for x in ast.walk(node))
            if not yields:continue
            decorators=[]
            for d in node.decorator_list:
                if isinstance(d,ast.Name):decorators.append(d.id)
                elif isinstance(d,ast.Attribute):decorators.append(d.attr)
                elif isinstance(d,ast.Call):
                    f=d.func;decorators.append(f.id if isinstance(f,ast.Name) else (f.attr if isinstance(f,ast.Attribute) else ''))
            providers[(module,node.name)]={'file':rel,'decorated':any(x in {'asynccontextmanager','contextmanager'} for x in decorators),'line':getattr(node,'lineno',0)}
    issues=[]
    for rel,p in _v36_project_source_files(root,manifest):
        if Path(rel).suffix.lower() not in {'.py','.pyw'}:continue
        try:tree=ast.parse(p.read_text(encoding='utf-8',errors='replace'))
        except Exception:continue
        imports={}
        for node in tree.body:
            if isinstance(node,ast.ImportFrom) and node.module:
                for alias in node.names:imports[alias.asname or alias.name]=(node.module,alias.name)
        for node in ast.walk(tree):
            if not isinstance(node,ast.AsyncWith):continue
            for item in node.items:
                expr=item.context_expr
                call=expr if isinstance(expr,ast.Call) else None
                if not call:continue
                if isinstance(call.func,ast.Name) and call.func.id in imports:
                    key=imports[call.func.id];info=providers.get(key)
                    if info and not info['decorated']:
                        issues.append({'file':rel,'provider_file':info['file'],'kind':'async_context_contract','line':getattr(node,'lineno',0),
                            'problem':f"V36.2 machine contract: {key[1]} is an async generator (contains yield) but {rel} uses it with async with. Decorate the provider with contextlib.asynccontextmanager or consume it with async for; do not build dependent code on this invalid context-manager contract."})
    return issues


def _candidate_transaction_error(work, manifest, rel, content, user_request=None, validation_failure=None, target_problems=None):
    err=_v361_sqlite_ddl_error(rel,content)
    if err:return err
    return _v361_base_candidate_transaction_error(work,manifest,rel,content,user_request=user_request,validation_failure=validation_failure,target_problems=target_problems)


def _deterministic_acceptance_issues(work, manifest):
    issues=_v361_base_deterministic_issues(work,manifest);seen={(str(x.get('file') or ''),str(x.get('problem') or '')) for x in issues}
    for item in _v361_async_generator_context_issues(work,manifest):
        key=(str(item.get('file') or ''),str(item.get('problem') or ''))
        if key not in seen:issues.append(item);seen.add(key)
    # Embedded SQLite in already committed files remains a hard deterministic defect.
    for rel,p in _v36_project_source_files(work,manifest):
        try:text=p.read_text(encoding='utf-8',errors='replace')
        except Exception:continue
        err=_v361_sqlite_ddl_error(rel,text)
        if err:
            key=(rel,err)
            if key not in seen:issues.append({'file':rel,'kind':'data_contract','problem':err});seen.add(key)
    return issues


def _v361_current_file_foundation_issues(work, manifest, rel):
    relevant=[]
    for issue in _deterministic_acceptance_issues(work,manifest):
        if issue.get('file')==rel or issue.get('provider_file')==rel:
            if str(issue.get('kind') or '') in {'data_contract','async_context_contract','call_signature','contract','missing','static'}:
                relevant.append(issue)
    return relevant[:12]


def _generate_planned_file(user_request, manifest, work, file_item, progress_callback=None):
    ok,wrote=_v361_base_generate_planned_file(user_request,manifest,work,file_item,progress_callback)
    if not ok:return ok,wrote
    rel=str(file_item.get('path') or wrote or '').replace('\\','/').strip('/')
    if not rel:return ok,wrote
    issues=_v361_current_file_foundation_issues(work,manifest,rel)
    if issues:
        problems=[str(x.get('problem') or '') for x in issues]
        failure='\n'.join(problems)
        _append_project_event(work,'v361_immediate_foundation_gate',f'V36.2 found {len(issues)} foundation/contract defect(s) immediately after generating {rel}.',file=rel,issues=problems)
        _progress(progress_callback,f'V36.2 immediate foundation repair: {rel}',stage='repairing')
        repaired=_repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback,validation_failure=failure)
        if repaired:
            remaining=_v361_current_file_foundation_issues(work,manifest,rel)
            if not remaining:return True,wrote
        return False,wrote
    return ok,wrote


