# V36.1 planner presentation and stricter multi-stack top-level behavior.
_v361_base_project_plan_prompt = _project_plan_prompt

def _project_plan_prompt(user_request, max_files):
    text=_v361_base_project_plan_prompt(user_request,max_files)
    text=text.replace('V35, a GENERAL-PURPOSE autonomous software builder','V36.1, a GENERAL-PURPOSE autonomous software factory')
    return text + (
        '\nV36.1 REAL-RUN RULES:\n'
        '- If the user explicitly names separate frontend/backend stacks, preserve BOTH as separate buildable components and never replace either with a mobile/Expo stack.\n'
        '- Runtime/tool names mentioned as prerequisites (for example Node.js installed) are NOT filenames.\n'
        '- JSON schemas, SQLite data folders, migrations, and shared contracts normally belong to their owning component; do not invent pseudo-toolchain components such as json/jsonschema or sqlite3/aiosqlite.\n'
        '- For a Windows delivery target, declare commands that work from Windows component roots; do not use touch/cat/rm/chmod or redundant cd <component> && prefixes.\n'
        '- Every explicit user acceptance requirement must remain represented in the manifest/tests.\n'
    )

# Strengthen multi-component top-level normalization after the initial V36.1 section was defined.
_v361_apply_explicit_component_locks_initial = _v361_apply_explicit_component_locks

def _v361_apply_explicit_component_locks(user_request, manifest):
    m=_v361_apply_explicit_component_locks_initial(user_request,manifest)
    locks=_v361_explicit_component_locks(user_request)
    if len(locks)>=2:
        # A multi-component repository has no single meaningful top-level build/test command.
        # Validation runs each component independently, so stale planner commands (e.g. Expo) must not leak through.
        for key in ('dependency_command','build_command','test_command','run_command'):
            m[key]=''
        # Preserve named backend framework hints even when the generic Python adapter has no framework value.
        low=str(user_request or '').lower(); frameworks=[]
        if any(x['toolchain_adapter']=='react' for x in locks):frameworks.append('react/vite')
        elif any(x['toolchain_adapter']=='vite' for x in locks):frameworks.append('vite')
        if any(x['toolchain_adapter']=='python' for x in locks):
            if 'fastapi' in low:frameworks.append('fastapi')
            elif 'django' in low:frameworks.append('django')
            elif 'flask' in low:frameworks.append('flask')
            else:frameworks.append('python')
        if frameworks:m['framework']=' + '.join(frameworks)
    return m


def _v361_windows_command_sanitize(command, kind='command'):
    cmd=str(command or '').strip()
    if not cmd:return ''
    cmd=re.sub(r'^\s*python3\b','python',cmd,flags=re.I)
    cmd=re.sub(r'^\s*\./gradlew\b','gradlew.bat',cmd,flags=re.I)
    if re.search(r'(?i)^\s*(?:touch|cat|rm\s+-rf|chmod\b|cp\s+-r|mv\s+)',cmd):return ''
    # Convert simple POSIX single-quoted curl tokens into cmd.exe-safe double-quoted tokens.
    if re.match(r'(?i)^\s*curl(?:\.exe)?\b',cmd) and "'" in cmd:
        def repl(match):
            inner=match.group(1).replace('"','\\"')
            return '"'+inner+'"'
        cmd=re.sub(r"'([^'\r\n]*)'",repl,cmd)
    return cmd

# ============================================================================
# V36.2 PLANNER COMPLETION / DEPENDENCY-CLOSURE HARDENING
# Fixes learned from the V36.1 TaskForge run:
# - true chunked component architecture instead of one giant planner response
# - never implement a tiny emergency manifest for a complex request
# - freeze source requirements before model compilation and enforce coverage
# - JSONC-aware tsconfig.json validation
# - dependency/provider closure gate before implementation
# - internal-import closure gate on generated candidates
# ============================================================================
V36_VERSION = '36.2.0'
V362_HIERARCHICAL_PLANNER = os.getenv('JARVIS_V362_HIERARCHICAL_PLANNER','1').strip().lower() not in {'0','false','no','off'}
V362_REQUIREMENT_COVERAGE_GATE = True
V362_DEPENDENCY_CLOSURE_GATE = True
V362_JSONC_VALIDATION = True
V362_COMPLEX_REQUIREMENT_THRESHOLD = max(12, int(os.getenv('JARVIS_V362_COMPLEX_REQUIREMENT_THRESHOLD','20')))
V362_COMPONENT_PLAN_MAX_TOKENS = max(2500, int(os.getenv('JARVIS_V362_COMPONENT_PLAN_MAX_TOKENS','4800')))
V362_OVERVIEW_MAX_TOKENS = max(1400, int(os.getenv('JARVIS_V362_OVERVIEW_MAX_TOKENS','2400')))
V362_CLOSURE_MAX_TOKENS = max(1800, int(os.getenv('JARVIS_V362_CLOSURE_MAX_TOKENS','3200')))
V362_ALLOW_LEGACY_TINY_RECOVERY = os.getenv('JARVIS_V362_ALLOW_LEGACY_TINY_RECOVERY','0').strip().lower() in {'1','true','yes','on'}
if not V362_ALLOW_LEGACY_TINY_RECOVERY:
    V34_BOOTSTRAP_RECOVERY = False

_v362_base_precommit_candidate_error = _v36_precommit_candidate_error
_v362_base_candidate_transaction_error = _candidate_transaction_error
_v362_base_write_build_status = _v33_write_build_status
_v362_base_write_architecture = _v33_write_architecture


def _v362_jsonc_to_json(text):
    """Remove JSONC comments/trailing commas without touching string contents."""
    src=str(text or '')
    out=[];i=0;in_string=False;escape=False
    while i < len(src):
        ch=src[i]
        if in_string:
            out.append(ch)
            if escape:
                escape=False
            elif ch=='\\':
                escape=True
            elif ch=='"':
                in_string=False
            i+=1;continue
        if ch=='"':
            in_string=True;out.append(ch);i+=1;continue
        if ch=='/' and i+1<len(src) and src[i+1]=='/':
            i+=2
            while i<len(src) and src[i] not in '\r\n':i+=1
            continue
        if ch=='/' and i+1<len(src) and src[i+1]=='*':
            i+=2
            while i+1<len(src) and not (src[i]=='*' and src[i+1]=='/'):
                if src[i] in '\r\n':out.append(src[i])
                i+=1
            i=min(len(src),i+2);continue
        out.append(ch);i+=1
    cleaned=''.join(out)
    # Remove trailing commas outside strings.
    out=[];i=0;in_string=False;escape=False
    while i<len(cleaned):
        ch=cleaned[i]
        if in_string:
            out.append(ch)
            if escape:escape=False
            elif ch=='\\':escape=True
            elif ch=='"':in_string=False
            i+=1;continue
        if ch=='"':in_string=True;out.append(ch);i+=1;continue
        if ch==',':
            j=i+1
            while j<len(cleaned) and cleaned[j].isspace():j+=1
            if j<len(cleaned) and cleaned[j] in '}]':
                i+=1;continue
        out.append(ch);i+=1
    return ''.join(out)


def _v362_jsonc_loads(text):
    return json.loads(_v362_jsonc_to_json(text))


def _v36_precommit_candidate_error(work, rel, content):
    """V36.2 understands JSONC files such as tsconfig.json while keeping package.json strict."""
    name=Path(str(rel or '')).name.lower();ext=Path(str(rel or '')).suffix.lower()
    if name=='tsconfig.json' or ext=='.jsonc' or name.endswith('.jsonc'):
        try:_v362_jsonc_loads(str(content or ''))
        except Exception as exc:return f'V36.2 JSONC config gate failed for {rel}: {exc}'
        return ''
    return _v362_base_precommit_candidate_error(work,rel,content)


def _v362_section_category(name):
    h=re.sub(r'[^a-z0-9 +/#.-]+',' ',str(name or '').lower()).strip()
    if any(x in h for x in ('acceptance','before declaring','definition of done')):return 'acceptance'
    if any(x in h for x in ('automated test','testing','tests','test coverage')):return 'test'
    if any(x in h for x in ('technology','stack','platform','constraint','validation','persistence','database','security','performance')):return 'constraint'
    if any(x in h for x in ('repair behavior','repair strategy')):return 'constraint'
    return 'functional'


def _v362_heading_like(line):
    s=str(line or '').strip().strip('*#').strip()
    low=s.lower().rstrip(':')
    known=(
        'core functionality','dashboard','backend api','frontend','persistence','validation','automated tests',
        'acceptance tests','acceptance requirements','repair behavior','final project delivery','platform and technology',
        'technology stack','testing','database','stock adjustments','csv support','reports','main interface','final delivery'
    )
    return len(s)<=90 and (low in known or (s.endswith(':') and len(s.split())<=10))


def _v361_extract_source_requirements(user_request):
    """V36.2 freezes a model-independent requirement ledger from prose, bullets and list blocks.

    The V36.1 extractor missed plain one-per-line requirements when copy/paste removed bullets or
    numbering. V36.2 recognizes section/list context and never reports vacuous 100% coverage.
    """
    text=str(user_request or '').replace('\r\n','\n').replace('\r','\n')
    lines=text.split('\n');items=[];heading='general';category='functional';list_mode=False
    def add(value, cat=None):
        value=_v361_clean_req_text(value)
        if not value or len(value)<2:return
        # Ignore pure section labels / lead-in punctuation.
        if _v362_heading_like(value) and not re.search(r'(?i)\b(?:must|should|cannot|do not)\b',value):return
        key=re.sub(r'\W+',' ',value.lower()).strip()
        if not key:return
        if any(x['key']==key for x in items):return
        items.append({'id':f'UR-{len(items)+1:03d}','category':cat or category,'text':value[:1200],'key':key})
    for idx,raw in enumerate(lines):
        line=raw.strip()
        if not line:
            continue
        mdhead=re.match(r'^#{1,6}\s+(.+)$',line) or re.match(r'^\*\*(.+?)\*\*\s*:?[ ]*$',line)
        if mdhead:
            heading=_v361_clean_req_text(mdhead.group(1));category=_v362_section_category(heading);list_mode=(category in {'acceptance','test'} or any(x in heading.lower() for x in ('repair','final delivery','project delivery','core functionality','frontend','backend api','dashboard','validation','persistence')));continue
        if _v362_heading_like(line) and not re.search(r'(?i)\b(?:must|should|do not|cannot)\b',line):
            heading=_v361_clean_req_text(line.rstrip(':'));category=_v362_section_category(heading);list_mode=(line.endswith(':') or category in {'acceptance','test'} or any(x in heading.lower() for x in ('repair','final delivery','project delivery','core functionality','frontend','backend api','dashboard','validation','persistence')));continue
        if not items and re.match(r'(?i)^(?:build|create|make|develop|implement)\b',line):
            add(line,'functional');continue
        if re.search(r'(?i)\bfor\s+(?:windows|macos|mac os|linux)\b',line) and len(line)<=700:
            add(line,'constraint');continue
        # Labeled stack declarations are explicit constraints, not filenames.
        lab=re.match(r'(?i)^\s*(frontend|backend|database|platform|language|framework|build system)\s*:\s*(.+)$',line)
        if lab:
            add(f'{lab.group(1)}: {lab.group(2)}','constraint');continue
        bullet=re.match(r'^(?:[-*+]\s+|\d+[.)]\s+)(.+)$',line)
        if bullet:
            add(bullet.group(1));list_mode=True;continue
        # A lead-in ending in ':' starts a list block; retain the lead-in itself if it carries a MUST.
        if line.endswith(':'):
            if re.search(r'(?i)\b(?:must|should|required|include|contain|support|verify|able to)\b',line):add(line[:-1])
            list_mode=True;continue
        # Acceptance/test sections are inherently list-like until the next section heading.
        if category in {'acceptance','test'}:
            add(line);continue
        # Plain lines following a list lead-in are requirements even if bullets were lost in copy/paste.
        if list_mode and len(line)<=500:
            add(line);continue
        # Strong normative prose is always a requirement.
        if re.search(r'(?i)\b(?:must|must not|required|should|should not|do not|cannot|can not|needs? to|has to)\b',line) and len(line)<=900:
            add(line);continue
    # Never permit a non-empty prompt to become an empty source ledger / false 100% coverage.
    if not items and text.strip():
        summary=re.sub(r'\s+',' ',text.strip())[:1800]
        add('Complete the user request exactly as provided: '+summary,'functional')
    return items[:260]


def _v36_generate_requirements(user_request, work, progress_callback=None):
    """V36.2 freezes source requirements before asking Qwen to compile them."""
    source=_v361_extract_source_requirements(user_request)
    source_blob=json.dumps([{'id':x['id'],'category':x['category'],'text':x['text']} for x in source],ensure_ascii=False,indent=2)
    prompt=(
        'V36.2 REQUIREMENTS COMPILER. The SOURCE REQUIREMENT LEDGER below was extracted deterministically from the user prompt and is authoritative. '
        'Compile it into a concise software specification WITHOUT dropping, weakening, merging-away, or changing explicit stack/platform requirements. '
        'Every source requirement must be represented by at least one functional requirement, constraint, acceptance criterion, or test scenario. '
        'Acceptance criteria must be observable. Return JSON only.\n\nSOURCE REQUIREMENT LEDGER:\n'+source_blob[:24000]+
        '\n\nORIGINAL USER REQUEST:\n'+str(user_request or '')[:18000]
    )
    ok,raw=_qwen_call(prompt,progress_callback,'V36.2 compiling frozen requirements and acceptance specification',profile='plan',max_tokens=4800,thinking=False,response_schema=V36_REQUIREMENTS_SCHEMA,schema_name='v362_requirements',strict_output=True)
    obj=_extract_json(raw) if ok else None
    if not isinstance(obj,dict):
        obj={'project_summary':str(user_request or '')[:1200],'functional_requirements':[],'constraints':[],'acceptance_criteria':[],'suggested_test_scenarios':[],'nonfunctional_requirements':[]}
    fields={'functional':'functional_requirements','constraint':'constraints','acceptance':'acceptance_criteria','test':'suggested_test_scenarios'}
    all_existing=[]
    for field in ('functional_requirements','constraints','acceptance_criteria','suggested_test_scenarios','nonfunctional_requirements'):
        vals=obj.get(field) or [];vals=[vals] if isinstance(vals,str) else list(vals)
        obj[field]=[str(x).strip() for x in vals if str(x).strip()][:220]
        all_existing.extend(obj[field])
    coverage=[];represented_count=0
    for item in source:
        represented=_v361_requirement_represented(item['text'],all_existing)
        field=fields[item['category']]
        if not represented:
            preserved=f"{item['id']}: {item['text']}"
            obj[field].append(preserved);all_existing.append(preserved);mapped=preserved
        else:
            mapped='represented by compiled specification'
        represented_count+=1
        coverage.append({'source_id':item['id'],'category':item['category'],'source':item['text'],'mapped_to':mapped})
    total=len(source);percent=int(round(100.0*represented_count/max(1,total))) if total else 0
    obj['source_requirements']=[{'id':x['id'],'category':x['category'],'text':x['text']} for x in source]
    obj['requirement_coverage']=coverage
    obj['coverage_total']=total;obj['coverage_mapped']=represented_count;obj['coverage_percent']=percent
    obj['coverage_valid']=bool(total) and represented_count==total
    obj['version']=V36_VERSION;obj['compiled_at']=_utc_stamp();obj['source_ledger_frozen']=True
    try:(Path(work)/V36_REQUIREMENTS_FILE).write_text(json.dumps(obj,indent=2,ensure_ascii=False),encoding='utf-8')
    except Exception:pass
    return obj


