V37_GLOBAL_CONSTRAINT_CONTEXT_CHARS = max(1200, int(os.getenv('JARVIS_V37_GLOBAL_CONSTRAINT_CONTEXT_CHARS', '3200')))
V37_REPAIR_WHOLE_FILE_LINE_LIMIT = max(120, int(os.getenv('JARVIS_V37_REPAIR_WHOLE_FILE_LINE_LIMIT', '280')))
V37_PATCH_CANDIDATES = max(2, min(6, int(os.getenv('JARVIS_V37_PATCH_CANDIDATES', '4'))))
V37_LOOP_HISTORY = max(3, min(20, int(os.getenv('JARVIS_V37_LOOP_HISTORY', '8'))))
