def _v37_clean_dep(dep):
    return str(dep or '').replace('\\', '/').strip().strip('`').strip()


def _v37_component_root_for_owner(manifest, owner_path):
    owner = str(owner_path or '').replace('\\', '/').strip('/')
    best = '.'
    for comp in (manifest or {}).get('components') or []:
        root = str(comp.get('root') or '.').replace('\\', '/').strip('/') or '.'
        if root == '.':
            continue
        if owner == root or owner.startswith(root + '/'):
            if best == '.' or len(root) > len(best):
                best = root
    return best


def _v37_manifest_paths(manifest):
    return {str(x.get('path') or '').replace('\\', '/').strip('/') for x in (manifest or {}).get('files') or [] if isinstance(x, dict)}


def _v37_export_index(manifest):
    idx = {}
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item, dict):
            continue
        path = str(item.get('path') or '').replace('\\', '/').strip('/')
        for raw in item.get('exports') or []:
            text = str(raw or '').strip()
            if not text:
                continue
            # Capture a conservative identifier from signatures/descriptions.
            for sym in re.findall(r'\b[A-Za-z_][A-Za-z0-9_]*\b', text):
                idx.setdefault(sym.lower(), []).append(path)
    return idx


def _v37_external_dependency(dep, manifest=None):
    """Return True for tool/package/component dependencies that are not project files.

    V36.2 treated items such as node_modules, fastapi, sqlite3, and component names as if
    each required a source-file provider. In architecture metadata these are valid external
    dependencies but they are not file-graph edges.
    """
    d = _v37_clean_dep(dep)
    if not d:
        return True
    low = d.lower()
    component_ids = {str(c.get('id') or '').lower() for c in (manifest or {}).get('components') or []}
    component_roots = {str(c.get('root') or '').replace('\\', '/').strip('/').lower() for c in (manifest or {}).get('components') or []}
    if low in component_ids or low in component_roots:
        return True
    if any(token in low for token in ('node_modules', 'stdlib', '(stdlib)', 'via proxy', 'via http', 'via direct http', 'system tool', 'runtime package')):
        return True
    if re.match(r'^(?:python|python3|node|npm|npx|pnpm|yarn|pip|pip3|cargo|rustc|go|dotnet|java|javac|maven|gradle|flutter|dart|xcode|swift|cmake|make)(?:\b|$)', low):
        return True
    # Common dependency/package names. A file edge should normally have a path, extension,
    # dotted module shape, explicit symbol provider, or an exact manifest path.
    common = {
        'fastapi','pydantic','uvicorn','sqlite3','aiosqlite','pytest','httpx','starlette','sqlalchemy',
        'react','react-dom','react-router-dom','vite','typescript','axios','zustand','date-fns','vitest','jest',
        '@vitejs/plugin-react','@testing-library/react','@testing-library/jest-dom','@testing-library/user-event',
        'jsdom','ts-jest','express','cors','dotenv','zod','next','vue','svelte','electron'
    }
    if low in common or low.startswith('@'):
        return True
    # Semantic phrases are descriptions, not file paths.
    if ' ' in d and not re.search(r'\.(?:py|pyw|js|jsx|ts|tsx|mjs|cjs|json|css|scss|html|md|toml|ya?ml|sql)$', low):
        return True
    return False


def _v37_python_module_candidates(module_ref, owner_path, manifest):
    """Translate Qwen's common dotted/symbol provider notation into real project paths."""
    paths = _v37_manifest_paths(manifest)
    ref = _v37_clean_dep(module_ref)
    if not ref:
        return []
    # Strip symbol suffix: app.services.projects:project_service -> app.services.projects
    module = ref.split(':', 1)[0].strip()
    root = _v37_component_root_for_owner(manifest, owner_path)
    prefix = '' if root == '.' else root + '/'
    raw_candidates = []

    # Already path-like but package directory: backend/app:App -> backend/app/__init__.py
    slash = module.replace('.', '/') if '/' not in module else None
    if '/' in module:
        raw_candidates += [module, module + '.py', module.rstrip('/') + '/__init__.py']
        # Preserve component prefix, while translating dots after it.
        first, _, rest = module.partition('/')
        if rest and '.' in rest:
            converted = first + '/' + rest.replace('.', '/')
            raw_candidates += [converted + '.py', converted + '/__init__.py']
    elif module:
        converted = module.replace('.', '/')
        raw_candidates += [converted + '.py', converted + '/__init__.py']
        if prefix and not converted.startswith(prefix):
            raw_candidates += [prefix + converted + '.py', prefix + converted + '/__init__.py']

    # Some planners write backend/app.routes.projects. Keep backend/ as the root, convert rest.
    if '/' in module and '.' in module:
        left, _, rest = module.partition('/')
        converted = left + '/' + rest.replace('.', '/')
        raw_candidates += [converted + '.py', converted + '/__init__.py']

    out = []
    for c in raw_candidates:
        c = c.replace('//', '/').strip('/')
        if c in paths and c not in out:
            out.append(c)
    return out


def _v37_resolve_dependency(dep, owner_path, manifest):
    """Resolve one model-authored dependency to an exact project path.

    Returns (path_or_empty, classification). classification is project_file, external, or unresolved.
    """
    d = _v37_clean_dep(dep)
    if not d:
        return '', 'external'
    paths = _v37_manifest_paths(manifest)
    if d in paths:
        return d, 'project_file'
    # Exact path without source suffix can denote a Python package directory.
    for c in (d + '.py', d.rstrip('/') + '/__init__.py'):
        if c in paths:
            return c, 'project_file'

    # A symbol suffix is often a provider hint, not part of a filesystem path.
    symbol = d.split(':', 1)[1].strip() if ':' in d else ''
    if symbol:
        hits = list(dict.fromkeys(_v37_export_index(manifest).get(symbol.lower(), [])))
        if len(hits) == 1:
            return hits[0], 'project_file'

    # Python-style dotted/module provider notation.
    for c in _v37_python_module_candidates(d, owner_path, manifest):
        return c, 'project_file'

    # Basename/path-suffix matching, only when unambiguous.
    clean = d.split(':', 1)[0].replace('.', '/') if ':' in d and '/' not in d.split(':',1)[0] else d.split(':',1)[0]
    basename = Path(clean).name.lower()
    hits = [p for p in paths if Path(p).name.lower() == basename or p.lower().endswith('/' + clean.lower().strip('/'))]
    hits = list(dict.fromkeys(hits))
    if len(hits) == 1:
        return hits[0], 'project_file'

    if _v37_external_dependency(d, manifest):
        return '', 'external'
    return '', 'unresolved'


def _v37_unresolved_looks_internal(dep):
    d = _v37_clean_dep(dep)
    low = d.lower()
    if not d:
        return False
    if re.search(r'\.(?:py|pyw|js|jsx|ts|tsx|mjs|cjs|json|css|scss|html|toml|ya?ml|sql)$', low):
        return True
    if '/' in d and not re.match(r'^(?:https?:)?//', d):
        return True
    # Dotted module plus a symbol is strongly internal-looking; simple package names are not.
    if ':' in d and ('.' in d.split(':',1)[0] or '/' in d.split(':',1)[0]):
        return True
    return False


def _v37_normalize_manifest_dependencies(manifest):
    """Canonicalize advisory Qwen dependency metadata in place.

    File depends_on is a project-file graph only. Toolchain packages, node_modules, component
    names and runtime libraries belong to component/manifests, not the source-file DAG.
    """
    if not isinstance(manifest, dict):
        return manifest
    unresolved = []
    external = []
    # Component dependencies are component IDs only. Preserve relations like 'backend (via HTTP)'
    # while removing package/runtime metadata such as node_modules, sqlite3, fastapi, npm, etc.
    comps = [x for x in (manifest.get('components') or []) if isinstance(x, dict)]
    component_ids = [str(x.get('id') or '').strip() for x in comps if str(x.get('id') or '').strip()]
    for comp in comps:
        cdeps = comp.get('depends_on') or []
        if isinstance(cdeps, str): cdeps = [cdeps]
        kept = []
        for raw_dep in cdeps:
            d = _v37_clean_dep(raw_dep)
            low = d.lower()
            match = next((cid for cid in component_ids if cid != str(comp.get('id') or '') and (low == cid.lower() or re.match(r'^'+re.escape(cid.lower())+r'\b', low))), '')
            if match:
                if match not in kept: kept.append(match)
            elif _v37_external_dependency(d, manifest):
                external.append({'component': str(comp.get('id') or ''), 'dependency': d})
            # Unknown component metadata remains advisory and is intentionally not promoted into the source DAG.
        comp['depends_on'] = kept
    for item in manifest.get('files') or []:
        if not isinstance(item, dict):
            continue
        owner = str(item.get('path') or '').replace('\\', '/').strip('/')
        deps = item.get('depends_on') or []
        if isinstance(deps, str):
            deps = [deps]
        resolved = []
        for dep in deps:
            path, kind = _v37_resolve_dependency(dep, owner, manifest)
            if kind == 'project_file' and path and path != owner:
                if path not in resolved:
                    resolved.append(path)
            elif kind == 'external':
                external.append({'file': owner, 'dependency': _v37_clean_dep(dep)})
            else:
                unresolved.append({'file': owner, 'dependency': _v37_clean_dep(dep), 'internal_like': _v37_unresolved_looks_internal(dep)})
        item['depends_on'] = resolved
    manifest['_v37_external_dependency_metadata'] = external[:300]
    manifest['_v37_unresolved_dependencies'] = unresolved[:300]
    return manifest


def _v37_manifest_completeness_issues(manifest, spec, user_request, max_files):
    """V37 preflight: strict about real project gaps, tolerant of metadata notation/package deps."""
    _v37_normalize_manifest_dependencies(manifest)
    issues = []
    files = list((manifest or {}).get('files') or [])
    paths = _v37_manifest_paths(manifest)
    comps = list((manifest or {}).get('components') or [])
    if not files:
        issues.append('Architecture has no planned files.')
    source = (spec or {}).get('source_requirements') or []
    req_count = len(source)
    floor = max(3 * max(1, len(comps)), min(24, 5 + req_count // 5))
    if _v362_complex_request(user_request, spec) and len(files) < floor:
        issues.append(f'Architecture is suspiciously small for {req_count} frozen requirements and {len(comps)} components: {len(files)} files planned; require at least {floor} before implementation.')

    for comp in comps:
        root = str(comp.get('root') or '.').replace('\\', '/').strip('/') or '.'
        owned = [p for p in paths if root == '.' or p.startswith(root + '/')]
        if len(owned) < 3:
            issues.append(f'Component {comp.get("id")} ({root}) has only {len(owned)} planned files; it is not a complete buildable component.')
        adapter = str(comp.get('toolchain_adapter') or '').lower()
        if adapter == 'python' and not any(p.endswith(('requirements.txt','pyproject.toml','setup.py')) for p in owned):
            issues.append(f'Python component {comp.get("id")} has no dependency manifest.')
        if adapter in {'react','vite','node','nextjs','vue','sveltekit','nuxt','angular','electron','expo','react_native'} and not any(p.endswith('package.json') for p in owned):
            issues.append(f'Node/frontend component {comp.get("id")} has no package.json.')
        entry = str(comp.get('entrypoint') or '').replace('\\', '/').strip('/')
        if entry and entry not in paths:
            issues.append(f'Component {comp.get("id")} entrypoint is not a planned file: {entry}.')

    # Only unresolved dependencies that really look like project-file references are blockers.
    for row in (manifest or {}).get('_v37_unresolved_dependencies') or []:
        if row.get('internal_like'):
            issues.append(f'{row.get("file")} has unresolved internal project dependency {row.get("dependency")}.')

    for requested in _v37_base_extract_paths(user_request):
        if requested not in paths:
            # Runtime names like Node.js are excluded by V36.1 extraction logic, but retain exact-file requests.
            issues.append(f'Explicitly requested file is missing from architecture: {requested}.')
    if V362_REQUIREMENT_COVERAGE_GATE and (not (spec or {}).get('coverage_valid') or int((spec or {}).get('coverage_percent') or 0) < 100):
        issues.append('Frozen source-requirement coverage is not 100%; architecture may not begin.')
    return list(dict.fromkeys(issues))[:100]


# Make the inherited hierarchical planner use V37 semantics.
_v362_manifest_completeness_issues = _v37_manifest_completeness_issues


def _v37_prompt_sections(text):
    """Recover useful requirement boundaries even when the UI/provider flattens newlines."""
    text = str(text or '').replace('\r\n', '\n').replace('\r', '\n')
    # Reinsert boundaries before known headings if a transport layer flattened whitespace.
    headings = [
        'Core functionality','Dashboard','Backend API','Frontend','Persistence','Validation','Automated tests',
        'Acceptance tests','Acceptance requirements','Repair behavior','Final project delivery','Final delivery',
        'Platform and technology','Technology stack','Database','Testing','Reports','CSV support','Stock adjustments',
        'Main interface','Inventory rules'
    ]
    flat = re.sub(r'[ \t]+', ' ', text)
    for h in sorted(headings, key=len, reverse=True):
        flat = re.sub(r'(?i)(?<!\n)(?<!^)(?<![:.!?])\s+(' + re.escape(h) + r')(?=\s|:)', r'\n\1', flat)
    # Common labeled stack declarations are boundaries too.
    flat = re.sub(r'(?i)\s+(?=(?:Frontend|Backend|Database|Platform|Language|Framework|Build system)\s*:)', '\n', flat)
    # Preserve existing newlines; split sentence-style requirements that survived as one long line.
    out = []
    for line in flat.split('\n'):
        line = line.strip()
        if not line:
            continue
        if len(line) <= V37_REQUIREMENT_ITEM_MAX_CHARS:
            out.append(line)
            continue
        parts = re.split(r'(?<=[.!?])\s+(?=[A-Z0-9])', line)
        buf = ''
        for part in parts:
            part = part.strip()
            if not part:
                continue
            if len(buf) + len(part) + 1 > V37_REQUIREMENT_ITEM_MAX_CHARS and buf:
                out.append(buf.strip()); buf = ''
            if len(part) > V37_REQUIREMENT_ITEM_MAX_CHARS:
                words = part.split()
                chunk = ''
                for word in words:
                    if len(chunk) + len(word) + 1 > V37_REQUIREMENT_ITEM_MAX_CHARS and chunk:
                        out.append(chunk.strip()); chunk = ''
                    chunk += (' ' if chunk else '') + word
                if chunk:
                    out.append(chunk.strip())
            else:
                buf += (' ' if buf else '') + part
        if buf:
            out.append(buf.strip())
    return out


def _v361_extract_source_requirements(user_request):
    """V37 requirement ledger: transport-flattening tolerant and traceability-first."""
    segments = _v37_prompt_sections(user_request)
    items = []
    heading = 'general'
    category = 'functional'
    list_mode = False

    def add(value, cat=None):
        nonlocal items
        value = _v361_clean_req_text(value)
        if not value or len(value) < 2:
            return
        if _v362_heading_like(value) and not re.search(r'(?i)\b(?:must|should|cannot|do not|required|verify)\b', value):
            return
        key = re.sub(r'\W+', ' ', value.lower()).strip()
        if not key or any(x['key'] == key for x in items):
            return
        items.append({'id': f'UR-{len(items)+1:03d}', 'category': cat or category, 'text': value[:V37_REQUIREMENT_ITEM_MAX_CHARS], 'key': key})

    for raw in segments:
        line = raw.strip()
        if not line:
            continue
        if _v362_heading_like(line) and not re.search(r'(?i)\b(?:must|should|do not|cannot|required|verify)\b', line):
            heading = _v361_clean_req_text(line.rstrip(':'))
            category = _v362_section_category(heading)
            list_mode = category in {'acceptance','test'} or any(x in heading.lower() for x in ('repair','final delivery','project delivery','core functionality','frontend','backend api','dashboard','validation','persistence'))
            continue
        lab = re.match(r'(?i)^\s*(frontend|backend|database|platform|language|framework|build system)\s*:\s*(.+)$', line)
        if lab:
            add(f'{lab.group(1)}: {lab.group(2)}', 'constraint'); continue
        bullet = re.match(r'^(?:[-*+]\s+|\d+[.)]\s+)(.+)$', line)
        if bullet:
            add(bullet.group(1)); list_mode = True; continue
        if re.search(r'(?i)\b(?:before declaring|before calling|verify:)\b', line) or category in {'acceptance','test'}:
            add(line, 'acceptance' if category == 'acceptance' else category); continue
        if not items and re.match(r'(?i)^(?:build|create|make|develop|implement)\b', line):
            add(line, 'functional'); continue
        if re.search(r'(?i)\bfor\s+(?:windows|macos|mac os|linux)\b', line):
            add(line, 'constraint'); continue
        if list_mode or re.search(r'(?i)\b(?:must|must not|required|should|should not|do not|cannot|can not|needs? to|has to|able to|shall)\b', line):
            add(line); continue
        # A concise domain list under a known section is still a requirement.
        if len(line) <= 500 and heading != 'general':
            add(line)

    if not items and str(user_request or '').strip():
        for chunk in _v37_prompt_sections(user_request)[:20]:
            add(chunk, 'functional')
    return items[:300]


def _v36_generate_requirements(user_request, work, progress_callback=None):
    """V37 freezes the original prompt into independently traceable requirements before model compilation."""
    source = _v361_extract_source_requirements(user_request)
    ledger = [{'id': x['id'], 'category': x['category'], 'text': x['text']} for x in source]
    source_blob = json.dumps(ledger, ensure_ascii=False, indent=2)
    prompt = (
        'V37 REQUIREMENTS COMPILER. Jarvis already extracted the authoritative source ledger. Your job is ONLY to organize it into concise engineering requirements; '
        'do not merge away independently testable behavior, do not alter explicit stacks/platforms, and do not invent a different product. '
        'Acceptance criteria must be observable. Return JSON only.\n\nSOURCE LEDGER:\n' + source_blob[:30000] +
        '\n\nORIGINAL REQUEST (reference only):\n' + str(user_request or '')[:16000]
    )
    ok, raw = _qwen_call(prompt, progress_callback, 'V37 compiling frozen requirements', profile='plan', max_tokens=4200, thinking=False, response_schema=V36_REQUIREMENTS_SCHEMA, schema_name='v37_requirements', strict_output=True)
    obj = _extract_json(raw) if ok else None
    if not isinstance(obj, dict):
        obj = {'project_summary': str(user_request or '')[:1200], 'functional_requirements': [], 'constraints': [], 'acceptance_criteria': [], 'suggested_test_scenarios': [], 'nonfunctional_requirements': []}
    for field in ('functional_requirements','constraints','acceptance_criteria','suggested_test_scenarios','nonfunctional_requirements'):
        vals = obj.get(field) or []
        if isinstance(vals, str): vals = [vals]
        obj[field] = [str(x).strip() for x in vals if str(x).strip()][:220]

    # The source ledger itself is the non-lossy contract. Preserve every item verbatim in its category,
    # even if Qwen's compiled summary is imperfect.
    field_map = {'functional':'functional_requirements','constraint':'constraints','acceptance':'acceptance_criteria','test':'suggested_test_scenarios'}
    coverage = []
    for item in ledger:
        field = field_map.get(item['category'], 'functional_requirements')
        preserved = f"{item['id']}: {item['text']}"
        if not _v361_requirement_represented(item['text'], obj[field]):
            obj[field].append(preserved)
            mapped = preserved
        else:
            mapped = 'represented by compiled specification'
        coverage.append({'source_id': item['id'], 'category': item['category'], 'source': item['text'], 'mapped_to': mapped})
    total = len(ledger)
    obj['source_requirements'] = ledger
    obj['requirement_coverage'] = coverage
    obj['coverage_total'] = total
    obj['coverage_mapped'] = total
    obj['coverage_percent'] = 100 if total else 0
    obj['coverage_valid'] = bool(total)
    obj['original_request_sha256'] = hashlib.sha256(str(user_request or '').encode('utf-8', errors='replace')).hexdigest()
    obj['version'] = V37_VERSION
    obj['compiled_at'] = _utc_stamp()
    obj['source_ledger_frozen'] = True
    obj['source_ledger_transport_flattening_tolerant'] = True
    try:
        (Path(work) / V36_REQUIREMENTS_FILE).write_text(json.dumps(obj, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        pass
    return obj


def _v37_requirement_keywords(text):
    stop = {'the','and','for','with','from','this','that','must','should','shall','into','using','use','user','users','project','application','complete','working','file','files','include'}
    return {w for w in re.findall(r'[A-Za-z_][A-Za-z0-9_+-]{2,}', str(text or '').lower()) if w not in stop}


def _v37_relevant_requirements(work, manifest, file_item):
    p = Path(work) / V36_REQUIREMENTS_FILE
    try:
        spec = json.loads(p.read_text(encoding='utf-8')) if p.exists() else {}
    except Exception:
        spec = {}
    target_text = ' '.join([
        str(file_item.get('path') or ''), str(file_item.get('purpose') or ''),
        ' '.join(str(x) for x in file_item.get('contracts') or []),
        ' '.join(str(x) for x in file_item.get('exports') or [])
    ])
    target_kw = _v37_requirement_keywords(target_text)
    rows = []
    for item in spec.get('source_requirements') or []:
        text = str(item.get('text') or '')
        cat = str(item.get('category') or '')
        kw = _v37_requirement_keywords(text)
        score = len(target_kw & kw)
        # Stack/platform and completion constraints are globally useful.
        if cat == 'constraint' and any(x in text.lower() for x in ('frontend:', 'backend:', 'database:', 'windows', 'offline', 'local')):
            score += 5
        if cat == 'acceptance' and any(x in text.lower() for x in ('compile','build','test','launch','dependency','contract','placeholder')):
            score += 2
        if score > 0:
            rows.append((score, item))
    rows.sort(key=lambda x: (-x[0], str(x[1].get('id') or '')))
    chosen = []
    used = 0
    for _, item in rows:
        line = f"{item.get('id')}: {item.get('text')}"
        if used + len(line) + 1 > V37_FILE_REQUIREMENT_CONTEXT_CHARS:
            continue
        chosen.append(line); used += len(line) + 1
    return '\n'.join(chosen[:24])


def _v37_focused_file_request(user_request, manifest, work, file_item):
    summary = ''
    p = Path(work) / V36_REQUIREMENTS_FILE
    try:
        spec = json.loads(p.read_text(encoding='utf-8')) if p.exists() else {}
        summary = str(spec.get('project_summary') or '')[:900]
    except Exception:
        spec = {}
    relevant = _v37_relevant_requirements(work, manifest, file_item)
    global_constraints = []
    for x in (spec.get('constraints') or []):
        text = str(x)
        if any(k in text.lower() for k in ('windows','frontend','backend','database','offline','local','stack','framework')):
            global_constraints.append(text)
    gc = '\n'.join(global_constraints)[:V37_GLOBAL_CONSTRAINT_CONTEXT_CHARS]
    return (
        'V37 FOCUSED IMPLEMENTATION TASK. Jarvis retains the full original request separately; this call receives only requirements relevant to this file.\n'
        f'PRODUCT SUMMARY: {summary}\n'
        f'TARGET: {file_item.get("path")} — {file_item.get("purpose")}\n'
        + (f'GLOBAL STACK/PLATFORM CONSTRAINTS:\n{gc}\n' if gc else '')
        + (f'RELEVANT SOURCE REQUIREMENTS:\n{relevant}\n' if relevant else '')
        + 'Implement the target contract exactly. Do not invent unrelated product behavior.'
    )


def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    """V37 narrow-role call. Keep a stable short prefix for prompt-cache reuse."""
    role = _v36_role_for_call(profile, stage)
    stage37 = str(stage or '').replace('V36.2', 'V37').replace('V36.1', 'V37').replace('V36 ', 'V37 ')
    body = str(prompt or '').replace('V36.2', 'V37')
    prefix = (
        f'JARVIS V37 ROLE: {role}\n'
        'Jarvis owns repository state, requirements, contracts, validation, and recovery. Work on one bounded engineering step. '
        'Inspect exact evidence, make the smallest correct decision, and do not redesign unrelated parts. '
        'When emitting structured output, stop after the requested structure.\n'
    )
    return _v36_base_qwen_call(prefix + '\n' + body, progress_callback, stage37, profile=profile, **kwargs)


def _v37_agent_state_load(work):
    p = Path(work) / V37_AGENT_STATE_FILE
    try:
        obj = json.loads(p.read_text(encoding='utf-8')) if p.exists() else {}
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}


def _v37_agent_state_save(work, obj):
    try:
        (Path(work) / V37_AGENT_STATE_FILE).write_text(json.dumps(obj, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        pass


def _v37_record_patch_attempt(work, rel, content, error=''):
    state = _v37_agent_state_load(work)
    hist = state.setdefault('patch_history', {}).setdefault(str(rel), [])
    fingerprint = hashlib.sha256(str(content or '').encode('utf-8', errors='replace')).hexdigest()[:20]
    hist.append({'fingerprint': fingerprint, 'error': str(error or '')[-1500:], 'at': _utc_stamp()})
    state['patch_history'][str(rel)] = hist[-V37_LOOP_HISTORY:]
    _v37_agent_state_save(work, state)
    return fingerprint


def _v37_recent_patch_history(work, rel):
    state = _v37_agent_state_load(work)
    return list((state.get('patch_history') or {}).get(str(rel), []))[-V37_LOOP_HISTORY:]


def _v36_patch_repair_candidate(user_request, manifest, work, rel, problems, validation_failure, attempt, progress_callback=None):
    """V37 patch repair adds duplicate-loop detection and exact read-before-edit context."""
    path = Path(work) / rel
    try:
        current = path.read_text(encoding='utf-8', errors='replace')
    except Exception:
        return None, 'Target file could not be read.'
    localization = _v36_localize_failure(work, validation_failure) if validation_failure else {'locations': [], 'symbols': [], 'exception': ''}
    excerpt = _v36_target_excerpt(work, rel, localization)
    repo = _v36_repo_map_context(work, manifest, rel, 7000)
    contracts = _v36_contract_context(work, manifest, rel, 5000)
    skill = _v36_stack_skill_context(manifest, 2200)
    history = _v37_recent_patch_history(work, rel)
    history_text = '\n'.join(f"- {x.get('fingerprint')}: {x.get('error','')[:500]}" for x in history[-4:]) or '(none)'
    # Deliberation-on-failure: do not pay for a second reasoning pass on the common happy path.
    # If the first edit was rejected, use one tiny architect/debugger brief, then let the editor emit only the patch.
    diagnosis = ''
    if attempt >= 2 and (history or validation_failure):
        diagnosis = _qwen_reasoning_brief(
            'V37 REPAIR DIAGNOSIS ONLY. Identify the smallest root-cause change for this failure. Do not write code.\n'
            f'TARGET: {rel}\nISSUES: {json.dumps(problems, ensure_ascii=False)}\n'
            f'FAILURE: {str(validation_failure or "")[-5000:]}\n'
            f'CONTRACTS: {contracts[-3500:]}\nRECENT REJECTIONS: {history_text}',
            progress_callback, f'V37 bounded diagnosis before patch {attempt}: {rel}', max_tokens=900
        )
    prompt = (
        'V37 EDIT MODE. The target file was read immediately before this edit. Return exact SEARCH/REPLACE blocks only; never return the whole file. '
        'Copy SEARCH text exactly from the supplied source/excerpt and make the smallest change that fixes the real evidence. '
        'Do not weaken tests or hide missing behavior. If prior patches repeated, change strategy rather than repeating the same edit.\n\n'
        f'FOCUSED USER/FILE REQUIREMENTS:\n{_v37_focused_file_request(user_request, manifest, work, _manifest_file_item(manifest, rel))}\n\n'
        f'TARGET FILE: {rel}\nISSUES:\n{json.dumps(problems, ensure_ascii=False, indent=2)}\n'
        f'REAL FAILURE:\n{str(validation_failure or "(none)")[-7000:]}\n'
        f'LOCALIZED FAILURE:\n{json.dumps(localization, ensure_ascii=False, indent=2)}\n\n{contracts}\n\n{repo}\n\n{skill}\n'
        f'RECENT REJECTED PATCH FINGERPRINTS/ERRORS:\n{history_text}\n'
        + (f'BOUNDED ROOT-CAUSE BRIEF FROM PRIOR FAILED ATTEMPT:\n{diagnosis}\n' if diagnosis else '')
        + f'\nTARGET SOURCE/EXCERPT:\n{excerpt}\n'
    )
    ok, raw = _qwen_call(prompt, progress_callback, f'V37 patch repair {attempt}/{V37_PATCH_CANDIDATES}: {rel}', profile='repair', max_tokens=min(3200, _qwen_file_output_limit()), thinking=False, response_schema=V36_PATCH_SCHEMA, schema_name='v37_patch', strict_output=True)
    obj = _extract_json(raw) if ok else None
    if not isinstance(obj, dict):
        return None, 'Patch response was not valid JSON.'
    candidate, err = _v36_apply_search_replace(current, obj.get('replacements') or [])
    if err:
        return None, err
    if candidate == current:
        _v37_record_patch_attempt(work, rel, candidate, 'Patch made no change.')
        return None, 'Patch made no change; choose a different strategy.'
    fingerprint = hashlib.sha256(candidate.encode('utf-8', errors='replace')).hexdigest()[:20]
    if any(x.get('fingerprint') == fingerprint for x in history):
        _v37_record_patch_attempt(work, rel, candidate, 'Duplicate patch candidate repeated from recent history.')
        return None, 'Duplicate patch candidate repeated from recent history; choose a different repair.'
    tx = _candidate_transaction_error(work, manifest, rel, candidate, user_request=user_request, validation_failure=validation_failure, target_problems=problems)
    if tx:
        _v37_record_patch_attempt(work, rel, candidate, tx)
        return None, tx
    delta = sum(1 for a, b in zip(current, candidate) if a != b) + abs(len(current) - len(candidate))
    return {'content': candidate, 'delta': delta, 'summary': str(obj.get('summary') or ''), 'fingerprint': fingerprint}, ''


def _repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback=None, validation_failure=None):
    """V37 enforces Edit-over-Write on established files and detects doom loops."""
    path = Path(work) / rel
    if not path.exists() or not V36_PATCH_REPAIRS:
        return _v37_base_repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback, validation_failure)
    try:
        original = path.read_text(encoding='utf-8', errors='replace')
    except Exception:
        original = ''
    valid = []
    errors = []
    for attempt in range(1, V37_PATCH_CANDIDATES + 1):
        cand, err = _v36_patch_repair_candidate(user_request, manifest, work, rel, problems, validation_failure, attempt, progress_callback)
        if cand:
            valid.append(cand)
            # First validated small patch is usually best for a 9B model; no need to fan out.
            break
        errors.append(str(err or ''))
    if valid:
        chosen = min(valid, key=lambda x: (x.get('delta', 10**12), len(x.get('content', ''))))
        _v36_checkpoint_file(work, rel, original, 'before_v37_patch')
        tmp = path.with_name(path.name + '.jarvis_v37_patch_tmp')
        try:
            tmp.write_text(chosen['content'], encoding='utf-8')
            tmp.replace(path)
            _delete_candidate_draft(work, rel)
            _v37_record_patch_attempt(work, rel, chosen['content'], '')
            _v36_build_repo_graph(work, manifest, write=True)
            _v36_build_contract_registry(work, manifest, write=True)
            _append_project_event(work, 'v37_patch_committed', f'Committed read-before-edit minimal patch for {rel}.', file=rel, delta=chosen.get('delta'), fingerprint=chosen.get('fingerprint'), summary=chosen.get('summary'))
            return True
        except Exception:
            try: tmp.unlink(missing_ok=True)
            except Exception: pass

    # Large established files are protected from destructive whole-file rewrites. Skeleton/recovery
    # sources and small files may still use the mature fallback as a last resort.
    line_count = len(original.splitlines())
    is_intermediate = V33_SKELETON_MARKER in original[:800] or V34_RECOVERY_SEED_MARKER in original[:1200]
    syntax_broken = bool(_content_validation_error(rel, original))
    if line_count > V37_REPAIR_WHOLE_FILE_LINE_LIMIT and not is_intermediate and not syntax_broken:
        _append_project_event(work, 'v37_whole_rewrite_refused', f'Refused destructive whole-file rewrite of established {rel}; patch loop will return to fresh validation evidence.', file=rel, lines=line_count, patch_errors=errors[-4:])
        return False

    _v36_checkpoint_file(work, rel, original, 'before_v37_small_full_rewrite_fallback')
    repaired = _v37_base_repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback, validation_failure)
    if repaired:
        _v36_build_repo_graph(work, manifest, write=True); _v36_build_contract_registry(work, manifest, write=True)
    else:
        _append_project_event(work, 'v37_patch_loop_exhausted', f'Patch candidates and bounded fallback did not converge for {rel}.', file=rel, patch_errors=errors[-4:])
    return repaired


def _generate_planned_file(user_request, manifest, work, file_item, progress_callback=None):
    """V37 generates new files from a small relevant requirement slice, then validates immediately."""
    focused = _v37_focused_file_request(user_request, manifest, work, file_item)
    # Call the original systematic generator directly so it does not append the entire requirements file/user prompt.
    ok, wrote = _v36_base_generate_planned_file(focused, manifest, work, file_item, progress_callback)
    if not ok:
        return ok, wrote
    rel = str(file_item.get('path') or wrote or '').replace('\\', '/').strip('/')
    if not rel:
        return ok, wrote
    _v36_build_repo_graph(work, manifest, write=True); _v36_build_contract_registry(work, manifest, write=True)
    issues = _v361_current_file_foundation_issues(work, manifest, rel)
    if issues:
        problems = [str(x.get('problem') or '') for x in issues]
        failure = '\n'.join(problems)
        _append_project_event(work, 'v37_immediate_foundation_gate', f'V37 found {len(issues)} foundation/contract defect(s) immediately after generating {rel}.', file=rel, issues=problems)
        repaired = _repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback, validation_failure=failure)
        if repaired and not _v361_current_file_foundation_issues(work, manifest, rel):
            return True, wrote
        return False, wrote
    return True, wrote


def _v362_dependency_closure_review(user_request, spec, manifest, max_files, progress_callback=None, known_issues=None):
    """V37 closure review: model adds missing files; Jarvis owns dependency classification/resolution."""
    current = dict(manifest or {})
    current['files'] = [dict(x) for x in (manifest or {}).get('files') or []]
    _v37_normalize_manifest_dependencies(current)
    summary = [{'path':x.get('path'),'purpose':x.get('purpose'),'phase':x.get('phase'),'depends_on':x.get('depends_on'),'exports':x.get('exports'),'contracts':x.get('contracts')} for x in current['files']]
    prompt = (
        'V37 DEPENDENCY-CLOSURE REVIEW. Implementation has not started. Add only genuinely missing PROJECT FILES/config/schema/tests needed for a buildable component. '
        'IMPORTANT: file depends_on may contain ONLY repository-relative project file paths. Never put node_modules, npm/pip packages, runtime tools, component IDs, or symbol notation in file depends_on. '
        'External dependencies belong in package.json/requirements/component metadata. Do not remove required behavior. Return JSON only.\n\n'
        f'KNOWN REAL PREFLIGHT ISSUES:\n{json.dumps(known_issues or [], ensure_ascii=False, indent=2)}\n'
        f'COMPONENTS:\n{json.dumps(current.get("components") or [], ensure_ascii=False, indent=2)}\n'
        f'SHARED CONTRACTS:\n{json.dumps(current.get("shared_contracts") or [], ensure_ascii=False, indent=2)}\n'
        f'CURRENT FILE GRAPH:\n{json.dumps(summary, ensure_ascii=False, indent=2)[:26000]}\n'
        f'FROZEN REQUIREMENTS:\n{_v362_compact_requirements(spec, 12000)}\n'
    )
    ok, raw = _qwen_call(prompt, progress_callback, 'V37 dependency closure', profile='plan', max_tokens=min(3600, V362_CLOSURE_MAX_TOKENS), thinking=False, response_schema=V362_CLOSURE_SCHEMA, schema_name='v362_dependency_closure', strict_output=True)
    obj = _extract_json(raw) if ok else None
    if isinstance(obj, dict):
        for row in _sanitize_manifest_files(obj.get('add_files') or [], max_files):
            _v362_add_file_if_missing(current, row, max_files)
        for line in _v33_normalize_contract_lines(obj.get('shared_contracts'), 100):
            if line not in current.setdefault('shared_contracts', []):
                current['shared_contracts'].append(line)
    _v37_normalize_manifest_dependencies(current)
    return current, str(raw or '')


def _direct_new_project_bootstrap(user_request, max_files, progress_callback=None, work=None):
    """V37: frozen requirements -> component planning -> semantic preflight -> focused implementation."""
    if work is None:
        return _legacy_direct_bootstrap(user_request, max_files, progress_callback)
    work = Path(work)
    spec = _v36_generate_requirements(user_request, work, progress_callback) if V36_REQUIREMENTS_COMPILER else {
        'source_requirements':[{'id':'UR-001','category':'functional','text':str(user_request or '')}],
        'coverage_valid':True,'coverage_percent':100,'acceptance_criteria':[]
    }
    if V362_REQUIREMENT_COVERAGE_GATE and (not spec.get('coverage_valid') or int(spec.get('coverage_percent') or 0) < 100):
        msg = f"Frozen requirement coverage failed: {spec.get('coverage_mapped',0)}/{spec.get('coverage_total',0)} mapped."
        _append_project_event(work, 'v37_requirements_gate_failed', msg, coverage=spec.get('requirement_coverage') or [])
        return False, {'_jarvis_architecture_blocked': True, '_jarvis_architecture_error': msg, 'project_name': 'project'}, [], msg
    _progress(progress_callback, 'V37 planning bounded components and semantic dependency closure', stage='architecting', percent=7)
    manifest, raw = _v362_build_hierarchical_manifest(user_request, spec, max_files, progress_callback)
    if not manifest:
        msg = str(raw or 'Architecture did not converge.')
        _append_project_event(work, 'v37_architecture_blocked', 'V37 stopped before implementation because a real architecture/preflight issue remained.', plan_error=msg[-7000:])
        try: (work / 'JARVIS_V37_ARCHITECTURE_FAILURE.txt').write_text(msg, encoding='utf-8')
        except Exception: pass
        return False, {'_jarvis_architecture_blocked': True, '_jarvis_architecture_error': msg, 'project_name': 'project'}, [], msg
    _v37_normalize_manifest_dependencies(manifest)
    manifest['v36_requirements_compiled'] = True
    manifest['v36_repo_map'] = True
    manifest['v36_machine_contracts'] = True
    manifest['v36_patch_repairs'] = bool(V36_PATCH_REPAIRS)
    manifest['planner_mode'] = 'bounded-component-semantic-closure-v37'
    manifest['small_model_engineering_loop'] = True
    return _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback, raw)


