# V37.0.1 prompt-boundary refinement: some UI paths flatten every newline into spaces.
def _v37_prompt_sections(text):
    text = str(text or '').replace('\r\n', '\n').replace('\r', '\n')
    text = re.sub(r'[ \t]+', ' ', text)
    headings = [
        'Platform and technology','Technology stack','Core functionality','Dashboard','Backend API','Frontend',
        'Persistence','Validation','Automated tests','Acceptance tests','Acceptance requirements','Repair behavior',
        'Final project delivery','Final delivery','Database','Testing','Reports','CSV support','Stock adjustments',
        'Main interface','Inventory rules'
    ]
    leadins = [
        'Users must be able to:', 'Each project must contain:', 'Each task must contain:', 'Task status must support:',
        'Priority must support:', 'Create a dashboard showing:', 'Include appropriate endpoints for:', 'Validate at least:',
        'Create meaningful backend tests covering at least:', 'Create meaningful frontend tests',
        'Before declaring the project complete, verify:', 'Before calling the project complete, verify:',
        'The finished ZIP must include:', 'The final ZIP must contain:'
    ]
    # Boundaries are authoritative phrases in the request; insert them even if punctuation was lost.
    for phrase in sorted(headings + leadins, key=len, reverse=True):
        text = re.sub(r'(?i)\s+(' + re.escape(phrase) + r')(?=\s|$)', r'\n\1', text)
    # Stack labels: isolate each value until another label, heading, or strong prose transition.
    text = re.sub(r'(?i)\s+(?=(?:Frontend|Backend|Database|Platform|Language|Framework|Build system)\s*:)', '\n', text)
    transitions = r'(?:The frontend|The backend|The application|Jarvis|Users must|Each project|Each task|Task status|Priority must|Create a dashboard|Include appropriate|Validate at least|Create meaningful|Before declaring|Before calling|The finished ZIP|The final ZIP)\b'
    # Split a stack line before a following prose transition when newline flattening joined them.
    text = re.sub(r'(?i)((?:Frontend|Backend|Database|Platform|Language|Framework|Build system)\s*:[^\n]{1,180}?)(?=\s+' + transitions + r')', r'\1\n', text)

    rough = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        # Sentence boundaries are useful inside prose-heavy flattened lines.
        parts = re.split(r'(?<=[.!?])\s+(?=[A-Z0-9])', line)
        rough.extend(x.strip() for x in parts if x.strip())

    out = []
    for line in rough:
        if len(line) <= V37_REQUIREMENT_ITEM_MAX_CHARS:
            out.append(line); continue
        words = line.split(); chunk = ''
        for word in words:
            if len(chunk) + len(word) + 1 > V37_REQUIREMENT_ITEM_MAX_CHARS and chunk:
                out.append(chunk.strip()); chunk = ''
            chunk += (' ' if chunk else '') + word
        if chunk: out.append(chunk.strip())
    return out

# V37.0.2 boundary protection: keep lead-in phrases intact while isolating section headings.
def _v37_prompt_sections(text):
    text = str(text or '').replace('\r\n', '\n').replace('\r', '\n')
    text = re.sub(r'[ \t]+', ' ', text)
    headings = [
        'Platform and technology','Technology stack','Core functionality','Dashboard','Backend API','Frontend',
        'Persistence','Validation','Automated tests','Acceptance tests','Acceptance requirements','Repair behavior',
        'Final project delivery','Final delivery','Database','Testing','Reports','CSV support','Stock adjustments',
        'Main interface','Inventory rules'
    ]
    leadins = [
        'Users must be able to:', 'Each project must contain:', 'Each task must contain:', 'Task status must support:',
        'Priority must support:', 'Create a dashboard showing:', 'Include appropriate endpoints for:', 'Validate at least:',
        'Create meaningful backend tests covering at least:', 'Create meaningful frontend tests where practical covering important UI or API behavior.',
        'Before declaring the project complete, verify:', 'Before calling the project complete, verify:',
        'The finished ZIP must include:', 'The final ZIP must contain:'
    ]
    protected = {}
    for i, phrase in enumerate(sorted(leadins, key=len, reverse=True)):
        token = f'__J37_LEADIN_{i}__'
        pattern = re.compile(re.escape(phrase), re.I)
        if pattern.search(text):
            protected[token] = phrase
            text = pattern.sub(' ' + token + ' ', text)
    # Isolate known headings on both sides. Protecting lead-ins prevents "dashboard" in
    # "Create a dashboard showing" from being misread as a section header.
    for h in sorted(headings, key=len, reverse=True):
        text = re.sub(r'(?i)(?<![A-Za-z0-9_])(' + re.escape(h) + r')(?=\s|:|$)', r'\n\1\n', text)
    for token, phrase in protected.items():
        text = text.replace(token, phrase)
    # Isolate stack labels. Cut a label value before the next label or strong prose transition.
    text = re.sub(r'(?i)\s+(?=(?:Frontend|Backend|Database|Platform|Language|Framework|Build system)\s*:)', '\n', text)
    transitions = r'(?:The frontend|The backend|The application|Jarvis|Users must|Each project|Each task|Task status|Priority must|Create a dashboard|Include appropriate|Validate at least|Create meaningful|Before declaring|Before calling|The finished ZIP|The final ZIP)\b'
    text = re.sub(r'(?i)((?:Frontend|Backend|Database|Platform|Language|Framework|Build system)\s*:[^\n]{1,180}?)(?=\s+' + transitions + r')', r'\1\n', text)

    rough = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        parts = re.split(r'(?<=[.!?])\s+(?=[A-Z0-9])', line)
        rough.extend(x.strip() for x in parts if x.strip())
    out = []
    for line in rough:
        if len(line) <= V37_REQUIREMENT_ITEM_MAX_CHARS:
            out.append(line); continue
        words = line.split(); chunk = ''
        for word in words:
            if len(chunk) + len(word) + 1 > V37_REQUIREMENT_ITEM_MAX_CHARS and chunk:
                out.append(chunk.strip()); chunk = ''
            chunk += (' ' if chunk else '') + word
        if chunk: out.append(chunk.strip())
    return out

# V37.0.3 robust flattened-prompt tokenizer.
def _v37_prompt_sections(text):
    text = str(text or '').replace('\r\n', '\n').replace('\r', '\n')
    text = re.sub(r'[ \t]+', ' ', text)
    protected = {}
    token_id = 0

    def protect_span(match):
        nonlocal token_id
        token = f'__J37_PROTECTED_{token_id}__'; token_id += 1
        protected[token] = match.group(0).strip()
        return ' ' + token + ' '

    # Protect explicit stack declarations before section-heading detection so "Frontend:" and
    # "Database:" cannot be split by the generic section words.
    label_names = r'(?:Frontend|Backend|Database|Platform|Language|Framework|Build system)'
    transition = r'(?:The frontend|The backend|The application|Jarvis|Core functionality|Dashboard|Backend API|Persistence|Validation|Automated tests|Acceptance tests|Acceptance requirements|Repair behavior|Final project delivery|Final delivery|Users must|Each project|Each task|Task status|Priority must|Create a dashboard|Include appropriate|Validate at least|Create meaningful|Before declaring|Before calling|The finished ZIP|The final ZIP)\b'
    label_re = re.compile(r'(?i)\b' + label_names + r'\s*:\s*.*?(?=(?:\s+\b' + label_names + r'\s*:)|(?:\s+' + transition + r')|$)')
    text = label_re.sub(protect_span, text)

    leadins = [
        'Users must be able to:', 'Each project must contain:', 'Each task must contain:', 'Task status must support:',
        'Priority must support:', 'Create a dashboard showing:', 'Include appropriate endpoints for:', 'Validate at least:',
        'Create meaningful backend tests covering at least:', 'Create meaningful frontend tests where practical covering important UI or API behavior.',
        'Before declaring the project complete, verify:', 'Before calling the project complete, verify:',
        'The finished ZIP must include:', 'The final ZIP must contain:'
    ]
    for phrase in sorted(leadins, key=len, reverse=True):
        text = re.sub(re.escape(phrase), protect_span, text, flags=re.I)

    # Multiword headings are safe to isolate anywhere. Single-word headings use a context lookahead
    # to avoid splitting phrases such as "Frontend dependencies install successfully".
    multi = ['Platform and technology','Technology stack','Core functionality','Backend API','Automated tests','Acceptance tests','Acceptance requirements','Repair behavior','Final project delivery','Final delivery','CSV support','Stock adjustments','Main interface','Inventory rules']
    for h in sorted(multi, key=len, reverse=True):
        text = re.sub(r'(?i)(?<![A-Za-z0-9_])(' + re.escape(h) + r')(?=\s|:|$)', r'\n\1\n', text)
    contextual = {
        'Dashboard': r'(?=\s+(?:Create|Show|Display|The))',
        'Frontend': r'(?=\s+(?:Build|Create|The|Implement|Use))',
        'Persistence': r'(?=\s+(?:SQLite|Data|The|Use|Implement))',
        'Validation': r'(?=\s+(?:Validate|The|Input|Use|Include))',
        'Database': r'(?=\s+(?:SQLite|Use|Create|The|Implement))',
        'Testing': r'(?=\s+(?:Create|Tests|Include|The|Automated))',
        'Reports': r'(?=\s+(?:Include|Create|Generate|The))',
    }
    for h, look in contextual.items():
        text = re.sub(r'(?i)(?<![A-Za-z0-9_])(' + re.escape(h) + r')' + look, r'\n\1\n', text)

    # Restore protected labels and lead-ins as atomic segments surrounded by boundaries.
    for token, phrase in protected.items():
        text = text.replace(token, '\n' + phrase + '\n')

    rough = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        parts = re.split(r'(?<=[.!?])\s+(?=[A-Z0-9])', line)
        rough.extend(x.strip() for x in parts if x.strip())
    out = []
    for line in rough:
        if len(line) <= V37_REQUIREMENT_ITEM_MAX_CHARS:
            out.append(line); continue
        words = line.split(); chunk = ''
        for word in words:
            if len(chunk) + len(word) + 1 > V37_REQUIREMENT_ITEM_MAX_CHARS and chunk:
                out.append(chunk.strip()); chunk = ''
            chunk += (' ' if chunk else '') + word
        if chunk: out.append(chunk.strip())
    return out

# V37.0.4 final flattened-prompt tokenizer: section phrases require section-like followers.
def _v37_prompt_sections(text):
    text = str(text or '').replace('\r\n', '\n').replace('\r', '\n')
    text = re.sub(r'[ \t]+', ' ', text)
    protected = {}; token_id = 0
    def protect_match(match):
        nonlocal token_id
        token=f'__J37P_{token_id}__'; token_id+=1; protected[token]=match.group(0).strip(); return ' '+token+' '

    label_names=r'(?:Frontend|Backend|Database|Platform|Language|Framework|Build system)'
    transition=r'(?:The frontend|The backend|The application|Jarvis|Core functionality|Dashboard|Backend API|Persistence|Validation|Automated tests|Acceptance tests|Acceptance requirements|Repair behavior|Final project delivery|Final delivery|Users must|Each project|Each task|Task status|Priority must|Create a dashboard|Include appropriate|Validate at least|Create meaningful|Before declaring|Before calling|The finished ZIP|The final ZIP)\b'
    label_re=re.compile(r'(?i)\b'+label_names+r'\s*:\s*.*?(?=(?:\s+\b'+label_names+r'\s*:)|(?:\s+'+transition+r')|$)')
    text=label_re.sub(protect_match,text)
    leadins=[
        'Use this technology stack:','Use this technology stack','Users must be able to:','Each project must contain:','Each task must contain:',
        'Task status must support:','Priority must support:','Create a dashboard showing:','Include appropriate endpoints for:',
        'Validate at least:','Create meaningful backend tests covering at least:','Create meaningful frontend tests where practical covering important UI or API behavior.',
        'Before declaring the project complete, verify:','Before calling the project complete, verify:','The finished ZIP must include:','The final ZIP must contain:'
    ]
    for phrase in sorted(leadins,key=len,reverse=True):
        text=re.sub(re.escape(phrase),protect_match,text,flags=re.I)

    # Section names matched only when followed by the kind of phrase that starts that section.
    section_patterns={
        'Core functionality':r'(?=\s+(?:Users|Each|The|Create|Include|Support|Allow))',
        'Dashboard':r'(?=\s+(?:Create|Show|Display|The))',
        'Backend API':r'(?=\s+(?:Create|Include|Use|The|Build|Implement))',
        'Frontend':r'(?=\s+(?:Build|Create|The|Implement|Use))',
        'Persistence':r'(?=\s+(?:SQLite|Data|The|Use|Implement))',
        'Validation':r'(?=\s+(?:Validate|The|Input|Use|Include))',
        'Automated tests':r'(?=\s+(?:Create|Tests|Include|The|Backend|Frontend))',
        'Acceptance tests':r'(?=\s+(?:Before|Verify|The|Jarvis))',
        'Acceptance requirements':r'(?=\s+(?:Before|Verify|The|Jarvis))',
        'Repair behavior':r'(?=\s+(?:If|Prefer|After|Do|Continue|The))',
        'Final project delivery':r'(?=\s+(?:The|Final|Include|A|SETUP))',
        'Final delivery':r'(?=\s+(?:The|Final|Include|A|SETUP))',
        'Platform and technology':r'(?=\s+(?:Build|Use|Frontend|Backend|Platform))',
        'Technology stack':r'(?=\s+(?:Frontend|Backend|Database|Use))',
        'Testing':r'(?=\s+(?:Create|Tests|Include|The|Automated))',
        'Reports':r'(?=\s+(?:Include|Create|Generate|The))',
        'CSV support':r'(?=\s+(?:CSV|Import|Export|The))',
        'Stock adjustments':r'(?=\s+(?:Provide|Stock|Users|The))',
        'Main interface':r'(?=\s+(?:Create|The|Include|Build))',
        'Inventory rules':r'(?=\s+(?:SKU|Product|Quantity|The|Invalid))',
    }
    for h,look in sorted(section_patterns.items(),key=lambda kv:len(kv[0]),reverse=True):
        text=re.sub(r'(?i)(?<![A-Za-z0-9_])('+re.escape(h)+r')'+look,r'\n\1\n',text)
    # A flattened section heading may be immediately followed by a protected lead-in token
    # (e.g. "Dashboard Create a dashboard showing:" or "Acceptance tests Before declaring...").
    for h in sorted(section_patterns, key=len, reverse=True):
        text=re.sub(r'(?i)(?<![A-Za-z0-9_])('+re.escape(h)+r')(?=\s+__J37P_\d+__)',r'\n\1\n',text)
    for token,phrase in protected.items(): text=text.replace(token,'\n'+phrase+'\n')
    rough=[]
    for line in text.split('\n'):
        line=line.strip()
        if not line:continue
        rough.extend(x.strip() for x in re.split(r'(?<=[.!?])\s+(?=[A-Z0-9])',line) if x.strip())
    out=[]
    for line in rough:
        if len(line)<=V37_REQUIREMENT_ITEM_MAX_CHARS:out.append(line);continue
        words=line.split();chunk=''
        for word in words:
            if len(chunk)+len(word)+1>V37_REQUIREMENT_ITEM_MAX_CHARS and chunk:out.append(chunk.strip());chunk=''
            chunk+=(' ' if chunk else '')+word
        if chunk:out.append(chunk.strip())
    return out

