# Component entrypoints are component-local in many model outputs. Normalize them deterministically.
_v37_pre_entrypoint_completeness = _v362_manifest_completeness_issues

def _v362_manifest_completeness_issues(manifest, spec, user_request, max_files):
    paths = _v37_manifest_paths(manifest)
    for comp in (manifest or {}).get('components') or []:
        root = str(comp.get('root') or '.').replace('\\','/').strip('/') or '.'
        entry = str(comp.get('entrypoint') or '').replace('\\','/').strip('/')
        if entry and entry not in paths and root != '.' and root + '/' + entry in paths:
            comp['entrypoint'] = root + '/' + entry
    return _v37_manifest_completeness_issues(manifest, spec, user_request, max_files)

# V37 component planner: enough file budget for real multi-layer components, but still bounded.
def _v362_plan_component(user_request, spec, overview, component, max_files, ordinal, total, progress_callback=None):
    root=str(component.get('root') or '.').strip('/') or '.'
    adapter=str(component.get('toolchain_adapter') or 'generic')
    tool_spec=_v34_toolchain_catalog().get(adapter,{})
    skill=_v36_stack_skill_context({'framework':adapter,'toolchain_adapter':adapter,'components':[component]},3000)
    prompt=(
        f'V37 COMPONENT ARCHITECTURE {ordinal}/{total}. Plan ONE complete buildable component. Return files and public contracts, not source code. '
        'The component must be complete enough to build/test/run and satisfy its owned requirements. Include dependency/build manifests, models/data/repositories/services/routes/UI/tests as needed. '
        'CRITICAL DEPENDENCY RULE: each FILE depends_on entry may contain ONLY an exact repository-relative PROJECT FILE path that is also in this component plan. '
        'Never put node_modules, npm/pip packages, runtime tools, component IDs, dotted Python modules, or :symbol notation in file depends_on. '
        'Put packages in dependency manifests/component metadata and put symbol signatures in exports/contracts. Avoid duplicate providers and keep files focused.\n\n'
        f'COMPONENT LOCK:\n{json.dumps(component,ensure_ascii=False,indent=2)}\n'
        f'ADAPTER DEFAULTS:\n{json.dumps(tool_spec,ensure_ascii=False,indent=2)}\n'
        f'GLOBAL SHARED CONTRACTS:\n{json.dumps(overview.get("shared_contracts") or [],ensure_ascii=False,indent=2)}\n'
        f'FROZEN REQUIREMENTS:\n{_v362_compact_requirements(spec,15000)}\n'
        +(f'ACTIVE STACK SKILL:\n{skill}\n' if skill else '')+
        f'MAXIMUM FILES FOR THIS COMPONENT: {max_files}. Prefer the smallest COMPLETE architecture, never a demo scaffold.'
    )
    ok,raw=_qwen_call(prompt,progress_callback,f'V37 component plan {ordinal}/{total}: {component.get("id")}',profile='plan',max_tokens=min(5200,V362_COMPONENT_PLAN_MAX_TOKENS),thinking=False,response_schema=V362_COMPONENT_PLAN_SCHEMA,schema_name='v362_component_plan',strict_output=True)
    obj=_extract_json(raw) if ok else None
    if not isinstance(obj,dict) or not (obj.get('files') or []):
        retry=(
            'V37 COMPONENT PLAN RETRY. Return ONLY the required JSON. Keep it concise but complete. '
            'Remember: file depends_on contains only exact planned project file paths; packages/tools never belong there.\n\n'+prompt[-24000:]
        )
        ok2,raw2=_qwen_call(retry,progress_callback,f'V37 component plan retry: {component.get("id")}',profile='plan',max_tokens=min(4400,max(3000,V362_COMPONENT_PLAN_MAX_TOKENS-500)),thinking=False,response_schema=V362_COMPONENT_PLAN_SCHEMA,schema_name='v362_component_retry',strict_output=True)
        obj=_extract_json(raw2) if ok2 else None;raw=str(raw or '')+'\n'+str(raw2 or '')
    if not isinstance(obj,dict) or not (obj.get('files') or []):return None,str(raw or '')
    files=_v362_normalize_component_files(obj,component,max_files)
    if not files:return None,str(raw or '')
    # Normalize Qwen dependency notation/packages before preflight.
    temp={'components':[component],'files':files};_v37_normalize_manifest_dependencies(temp);files=temp['files']
    comp=dict(component);comp['root']=root
    for key in ('dependency_command','build_command','test_command','run_command'):
        comp[key]=str(obj.get(key) or tool_spec.get(key) or '')
    comp['required_tools']=[str(x) for x in (obj.get('required_tools') or tool_spec.get('required_tools') or []) if str(x).strip()]
    entry=str(obj.get('entrypoint') or '').replace('\\','/').strip('/')
    if entry and root!='.' and not entry.startswith(root+'/'):entry=root+'/'+entry
    comp['entrypoint']=entry
    return {'component':comp,'entrypoint':entry,'files':files,'shared_contracts':_v33_normalize_contract_lines(obj.get('shared_contracts'),80)},str(raw or '')


def _v362_build_hierarchical_manifest(user_request,spec,max_files,progress_callback=None):
    overview=_v362_plan_overview(user_request,spec,max_files,progress_callback)
    components=list(overview.get('components') or []);all_files=[];planned_components=[];shared=list(overview.get('shared_contracts') or []);raw_parts=[overview.get('_raw_overview','')]
    req_count=len((spec or {}).get('source_requirements') or []);ncomp=max(1,len(components))
    # Small-model agents need smaller calls, not tiny architectures. Give each component enough room
    # for real layering/tests while still capping the plan so the model is not asked for 100 files at once.
    if ncomp>1 or req_count>=18:
        desired=max(24,16+req_count//max(3,3*ncomp))
    else:
        desired=max(14,10+req_count//4)
    per_budget=max(12,min(48,max_files//ncomp,desired))
    entrypoints=[]
    for idx,comp in enumerate(components,1):
        result,raw=_v362_plan_component(user_request,spec,overview,comp,per_budget,idx,len(components),progress_callback);raw_parts.append(raw)
        if not result:return None,'\n'.join(raw_parts)+f'\nV37 component planning failed: {comp.get("id")}'
        planned_components.append(result['component']);all_files.extend(result['files'])
        if result.get('entrypoint'):entrypoints.append(result['entrypoint'])
        for line in result.get('shared_contracts') or []:
            if line not in shared:shared.append(line)
    manifest={
        'project_name':overview.get('project_name') or 'project','summary':overview.get('summary') or '',
        'project_type':overview.get('project_type') or ('multi-component' if len(planned_components)>1 else 'application'),
        'platform':overview.get('platform') or _v361_explicit_platform(user_request),'language':'multi' if len(planned_components)>1 else '',
        'framework':'','build_system':'multi' if len(planned_components)>1 else '','package_manager':'multi' if len(planned_components)>1 else '',
        'required_tools':[],'dependency_command':'','build_command':'','test_command':'','run_command':'','entrypoint':entrypoints[0] if entrypoints else '',
        'acceptance_criteria':list((spec or {}).get('acceptance_criteria') or []),'acceptance_tests':[],
        'architecture_rules':list(overview.get('architecture_rules') or []),'shared_contracts':_v361_canonicalize_shared_contracts(shared),
        'components':planned_components,'files':all_files,'_original_user_request':str(user_request or ''),'planner_mode':'bounded-component-semantic-closure-v37'
    }
    manifest=_v361_apply_explicit_component_locks(user_request,manifest);manifest=_v362_ensure_conventional_markers(manifest,max_files);_v37_normalize_manifest_dependencies(manifest)
    issues=_v362_manifest_completeness_issues(manifest,spec,user_request,max_files)
    manifest,raw=_v362_dependency_closure_review(user_request,spec,manifest,max_files,progress_callback,issues);raw_parts.append(raw)
    manifest=_v361_apply_explicit_component_locks(user_request,manifest);manifest=_v362_ensure_conventional_markers(manifest,max_files);_v37_normalize_manifest_dependencies(manifest)
    collisions=_v351_architecture_collision_issues(manifest)
    if collisions:
        manifest=_v351_correct_architecture_collisions(user_request,manifest,max_files,progress_callback);manifest=_v361_apply_explicit_component_locks(user_request,manifest);_v37_normalize_manifest_dependencies(manifest)
    final_issues=_v362_manifest_completeness_issues(manifest,spec,user_request,max_files)
    if final_issues:
        manifest,raw=_v362_dependency_closure_review(user_request,spec,manifest,max_files,progress_callback,final_issues);raw_parts.append(raw)
        manifest=_v361_apply_explicit_component_locks(user_request,manifest);manifest=_v362_ensure_conventional_markers(manifest,max_files);_v37_normalize_manifest_dependencies(manifest)
        final_issues=_v362_manifest_completeness_issues(manifest,spec,user_request,max_files)
    if final_issues:
        manifest['_architecture_incomplete_issues']=final_issues
        return None,'\n'.join(raw_parts)+'\nV37 ARCHITECTURE INCOMPLETE:\n'+'\n'.join(final_issues)
    manifest=_v34_apply_toolchain_defaults(user_request,manifest);manifest=_v361_apply_explicit_component_locks(user_request,manifest);_v37_normalize_manifest_dependencies(manifest)
    return manifest,'\n'.join(raw_parts)

