# SWE-agent-style focused file viewer: approximately 100 lines around the strongest failure site.
_v37_pre_focused_excerpt = _v36_target_excerpt

def _v36_target_excerpt(work, rel, localization=None, max_chars=None):
    path = Path(work) / rel
    try:
        text = path.read_text(encoding='utf-8', errors='replace')
    except Exception:
        return ''
    limit = int(max_chars or V36_TARGET_EXCERPT_CHARS)
    lines = text.splitlines()
    wanted = []
    for loc in (localization or {}).get('locations') or []:
        if str(loc.get('file') or '').replace('\\','/').endswith(str(rel).replace('\\','/')):
            try: wanted.append(int(loc.get('line') or 1))
            except Exception: pass
    if wanted:
        chunks = []
        for n in wanted[-3:]:
            a = max(0, n - 50); b = min(len(lines), n + 50)
            numbered = [f'{i+1:5d}: {lines[i]}' for i in range(a,b)]
            chunks.append(f'--- exact current file window around line {n} ---\n' + '\n'.join(numbered))
        return '\n'.join(chunks)[:limit]
    if len(text) <= limit:
        return '\n'.join(f'{i+1:5d}: {line}' for i,line in enumerate(lines))[:limit]
    # No known failure line: expose head/tail structure, then require targeted search/repair.
    head = lines[:45]; tail = lines[-45:] if len(lines) > 45 else []
    return ('--- file head ---\n' + '\n'.join(f'{i+1:5d}: {line}' for i,line in enumerate(head)) +
            '\n--- middle omitted; use repository symbols/failure evidence, do not rewrite blindly ---\n' +
            '\n'.join(f'{len(lines)-len(tail)+i+1:5d}: {line}' for i,line in enumerate(tail)))[:limit]

# V37 robust model-family fallback: the runtime profile is authoritative when live, but the
# selected profile still identifies Qwen3.5 before/while the managed server writes runtime state.
_v37_pre_active_model_family = _active_qwen_model_family

def _active_qwen_model_family():
    for profile_path in (JARVIS_DIR / 'qwen_runtime_profile.json', JARVIS_DIR / 'qwen_selected_profile.json'):
        try:
            data = json.loads(profile_path.read_text(encoding='utf-8-sig'))
        except Exception:
            continue
        joined = ' '.join(str(data.get(k) or '').lower() for k in ('model_family','model','profile','version','note'))
        if any(token in joined for token in ('qwen3.8','qwen38','27b38q2')):
            return 'qwen38'
        if any(token in joined for token in ('qwen3.5','qwen35','qwen3_5','9b35')):
            return 'qwen35'
    return _v37_pre_active_model_family()

# ===========================================================================
# V37.1 / V38 resilience patch — malformed-output hardening + root-cause repair
# ===========================================================================
# This block intentionally overrides the mature V37 functions instead of
# duplicating the full builder.  Goals:
#   * malformed Qwen JSON can NEVER terminate an entire project run;
#   * code edits use Aider-style SEARCH/REPLACE blocks instead of JSON strings;
#   * all file-validation paths share JSONC-aware validation;
#   * missing Node packages repair package.json (the owner) rather than source;
#   * obviously-wrong planner export metadata can self-heal from real source;
#   * malformed repair responses are persisted for reproducible diagnostics.

V38_RESILIENCE_PATCH = True
V38_PATCH_PROTOCOL = "search-replace-v1"
V38_MALFORMED_OUTPUT_DIR = ".jarvis_failures/model_outputs"

_v38_legacy_extract_json = _extract_json
_v38_legacy_content_validation_error = _content_validation_error
_v38_base_internal_import_error = _v362_candidate_internal_import_error
_v38_base_manifest_contract_issues = _manifest_contract_issues


def _extract_json(text):
    """Never let imperfect model JSON terminate the project generator.

    Older V37 code could leak the final ``json.loads`` JSONDecodeError from
    ``_extract_json``.  A truncated repair response such as an unterminated
    string then aborted the entire project.  V38 treats malformed structured
    output as a failed *model call* by returning an empty object.  Callers
    already interpret missing required fields as retry/fallback conditions.
    """
    try:
        obj = _v38_legacy_extract_json(text)
        return obj
    except BaseException:
        # Model output is untrusted data.  It must never become a process-level
        # exception, including JSONDecodeError/Unicode-related parser failures.
        return {}


def _v38_persist_model_output_failure(work, stage, rel, raw, error=""):
    """Persist malformed model output without allowing diagnostics to fail the run."""
    try:
        root = Path(work) / V38_MALFORMED_OUTPUT_DIR
        root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
        safe_rel = re.sub(r'[^A-Za-z0-9_.-]+', '__', str(rel or 'unknown').replace('\\', '/'))
        safe_stage = re.sub(r'[^A-Za-z0-9_.-]+', '_', str(stage or 'model'))[:80]
        p = root / f'{stamp}_{safe_stage}_{safe_rel}.txt'
        header = (
            f'JARVIS V38 MALFORMED MODEL OUTPUT\n'
            f'stage: {stage}\nfile: {rel}\nerror: {error}\ncreated_at: {_utc_stamp()}\n\n'
            f'----- RAW MODEL RESPONSE -----\n'
        )
        p.write_text(header + str(raw or ''), encoding='utf-8', errors='replace')
        _append_project_event(
            work, 'v38_malformed_model_output',
            f'Preserved malformed model response for {rel}; project generation continues.',
            file=str(rel or ''), stage_name=str(stage or ''), diagnostic=p.relative_to(Path(work)).as_posix(),
            error=str(error or '')[-1200:],
        )
        return p
    except BaseException:
        return None


def _v38_strip_outer_code_fence(text):
    raw = str(text or '').strip()
    if raw.startswith('```'):
        raw = re.sub(r'^```(?:diff|patch|text|plaintext)?\s*\r?\n?', '', raw, flags=re.I)
        raw = re.sub(r'\r?\n?```\s*$', '', raw)
    return raw.strip()


def _v38_parse_search_replace_blocks(text):
    """Parse Aider-style SEARCH/REPLACE blocks without JSON escaping source code."""
    raw = _v38_strip_outer_code_fence(text)
    # Accept the canonical Aider form and tolerate extra '='/'<'/'>' width.
    pattern = re.compile(
        r'(?ms)^<{5,}\s*SEARCH\s*\r?\n(.*?)^={5,}\s*\r?\n(.*?)^>{5,}\s*REPLACE\s*$'
    )
    replacements = []
    for m in pattern.finditer(raw):
        search = m.group(1)
        replace = m.group(2)
        # Strip only one transport newline immediately before the separator/
        # marker; preserve all other source whitespace exactly.
        if search.endswith('\r\n'):
            search = search[:-2]
        elif search.endswith('\n'):
            search = search[:-1]
        if replace.endswith('\r\n'):
            replace = replace[:-2]
        elif replace.endswith('\n'):
            replace = replace[:-1]
        replacements.append({'search': search, 'replace': replace})
    if replacements:
        return replacements, ''

    # Compatibility fallback for an older V37 JSON patch response.  The safe
    # extractor returns {} rather than throwing if the model truncates JSON.
    obj = _extract_json(raw)
    if isinstance(obj, dict) and isinstance(obj.get('replacements'), list):
        out = []
        for rep in obj.get('replacements') or []:
            if not isinstance(rep, dict):
                continue
            if rep.get('search') is None or rep.get('replace') is None:
                continue
            out.append({'search': str(rep.get('search')), 'replace': str(rep.get('replace'))})
        if out:
            return out, ''
    return [], 'No complete SEARCH/REPLACE block was found in the model response.'


def _content_validation_error(expected_path, content):
    """Single authoritative structural validator for every generation/repair path."""
    rel = str(expected_path or '')
    name = Path(rel).name.lower()
    ext = Path(rel).suffix.lower()
    text = _extract_single_file_response(content, rel)
    if not text.strip():
        return '' if _allows_empty_generated_file(rel) else 'File is empty or model returned prose instead of source.'

    # tsconfig.json and *.jsonc are JSON-with-comments/trailing-commas, not
    # strict RFC JSON.  This override fixes legacy acceptance/bootstrap paths
    # that still reached the original strict JSON validator.
    if name == 'tsconfig.json' or ext == '.jsonc' or name.endswith('.jsonc'):
        try:
            _v362_jsonc_loads(text)
            return ''
        except Exception as exc:
            return f'JSONC parse error: {exc}'

    return _v38_legacy_content_validation_error(rel, text)


def _v38_node_import_packages(content):
    src = str(content or '')
    refs = re.findall(r'(?:from\s+|import\s*\(?\s*)["\']([^"\']+)["\']', src)
    refs += re.findall(r'\brequire\s*\(\s*["\']([^"\']+)["\']\s*\)', src)
    packages = []
    builtins = {
        'assert','buffer','child_process','cluster','console','crypto','dgram','diagnostics_channel','dns','domain',
        'events','fs','http','http2','https','module','net','os','path','perf_hooks','process','punycode','querystring',
        'readline','repl','stream','string_decoder','sys','timers','tls','trace_events','tty','url','util','v8','vm',
        'wasi','worker_threads','zlib','test'
    }
    for ref in refs:
        ref = str(ref or '').strip()
        if not ref or ref.startswith(('.', '/', 'http://', 'https://', '@/','~/','#','node:')):
            continue
        pkg = '/'.join(ref.split('/')[:2]) if ref.startswith('@') else ref.split('/')[0]
        if pkg and pkg not in builtins and pkg not in packages:
            packages.append(pkg)
    return packages


def _v38_node_package_section(pkg, rel=''):
    p = str(pkg or '').lower()
    r = str(rel or '').lower()
    dev_prefixes = ('@types/', '@testing-library/', '@vitejs/', '@eslint/')
    dev_names = {
        'vite','typescript','vitest','jest','mocha','playwright','@playwright/test','eslint','prettier',
        'ts-node','tsx','babel','webpack','rollup','react-scripts'
    }
    if p.startswith(dev_prefixes) or p in dev_names or any(x in r for x in ('vite.config','test.','spec.','/tests/','/test/')):
        return 'devDependencies'
    return 'dependencies'


def _v38_auto_repair_package_manifest(work, manifest, rel, content):
    """Repair the dependency manifest—the owner—when valid source imports a missing package."""
    ext = Path(str(rel or '')).suffix.lower()
    if ext not in {'.ts','.tsx','.js','.jsx','.mjs','.cjs'}:
        return []
    packages = _v38_node_import_packages(content)
    if not packages:
        return []
    root = _v362_component_root_for_rel(manifest, rel)
    package_rel = (root + '/' if root != '.' else '') + 'package.json'
    package_path = Path(work) / package_rel
    if not package_path.exists():
        return []
    try:
        pdata = json.loads(package_path.read_text(encoding='utf-8', errors='replace'))
    except Exception:
        return []
    if not isinstance(pdata, dict):
        return []
    declared = set()
    for key in ('dependencies','devDependencies','peerDependencies','optionalDependencies'):
        vals = pdata.get(key) or {}
        if isinstance(vals, dict):
            declared.update(vals.keys())
    missing = [p for p in packages if p not in declared]
    if not missing:
        return []

    before = package_path.read_text(encoding='utf-8', errors='replace')
    _v36_checkpoint_file(work, package_rel, before, 'before_v38_dependency_manifest_auto_repair')
    for pkg in missing:
        section = _v38_node_package_section(pkg, rel)
        pdata.setdefault(section, {})
        if not isinstance(pdata[section], dict):
            pdata[section] = {}
        pdata[section].setdefault(pkg, '*')
    try:
        package_path.write_text(json.dumps(pdata, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
        _append_project_event(
            work, 'v38_dependency_manifest_auto_repair',
            f'Added source-required package dependencies to {package_rel}: {", ".join(missing)}.',
            file=package_rel, source_file=str(rel), packages=missing,
        )
        return missing
    except Exception:
        try:
            package_path.write_text(before, encoding='utf-8')
        except Exception:
            pass
        return []


def _v38_consumer_required_exports(work, manifest, rel):
    result = set()
    try:
        target = (Path(work).resolve() / str(rel)).resolve()
        _root, modules, _symbols = _python_module_map(work, manifest)
        by_module = _required_exports_by_module(work, manifest)
        for module, path in modules.items():
            try:
                if path.resolve() == target:
                    result.update(by_module.get(module, set()))
            except Exception:
                continue
    except Exception:
        pass
    return result


def _v38_export_equivalent(expected, actual):
    a = re.sub(r'[^a-z0-9]+', '', str(expected or '').lower())
    b = re.sub(r'[^a-z0-9]+', '', str(actual or '').lower())
    if not a or not b:
        return False
    if a == b:
        return True
    aw = _camel_words(expected)
    bw = _camel_words(actual)
    return bool(aw and bw and aw == bw)


def _v38_persist_manifest(work, manifest):
    """Persist only Jarvis architecture metadata after a deterministic self-repair."""
    try:
        p = Path(work) / V33_ARCHITECTURE_FILE
        if not p.exists():
            return
        data = json.loads(p.read_text(encoding='utf-8', errors='replace'))
        by_path = {str(x.get('path') or '').replace('\\','/'): x for x in (manifest or {}).get('files') or []}
        for row in data.get('files') or []:
            rel = str(row.get('path') or '').replace('\\','/')
            if rel in by_path:
                row['exports'] = list(by_path[rel].get('exports') or [])
                row['contracts'] = list(by_path[rel].get('contracts') or [])
        p.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        pass


def _v38_reconcile_manifest_exports(work, manifest, rel, actual_exports):
    """Repair only obvious planner metadata aliases; never override real consumer evidence."""
    if Path(str(rel or '')).suffix.lower() not in {'.py','.pyw'}:
        return []
    item = _manifest_file_item(manifest, rel)
    if not item:
        return []
    planned = _normalize_export_contract(item.get('exports'))
    actual = set(actual_exports or [])
    consumers = _v38_consumer_required_exports(work, manifest, rel)
    changed = []
    new_exports = []
    for expected in planned:
        if expected in actual:
            new_exports.append(expected)
            continue
        # A consumer importing the exact planner name is real evidence; source
        # must satisfy it rather than metadata being silently rewritten.
        if expected in consumers:
            new_exports.append(expected)
            continue
        matches = [name for name in actual if _v38_export_equivalent(expected, name)]
        if len(matches) == 1:
            replacement = matches[0]
            new_exports.append(replacement)
            changed.append((expected, replacement))
        else:
            new_exports.append(expected)
    if changed:
        item['exports'] = list(dict.fromkeys(new_exports))
        _v38_persist_manifest(work, manifest)
        _append_project_event(
            work, 'v38_manifest_contract_self_repair',
            f'Repaired planner export metadata for {rel} from real source/consumer evidence.',
            file=str(rel), replacements=[{'from': a, 'to': b} for a,b in changed],
        )
    return changed


def _manifest_contract_issues(work, manifest):
    """Self-heal conservative planner alias mistakes before emitting source-repair issues."""
    for item in (manifest or {}).get('files') or []:
        rel = str(item.get('path') or '').replace('\\','/')
        if Path(rel).suffix.lower() not in {'.py','.pyw'}:
            continue
        path = Path(work) / rel
        if not path.exists():
            continue
        actual = _python_public_symbols_in_file(path)
        if actual:
            _v38_reconcile_manifest_exports(work, manifest, rel, actual)
    return _v38_base_manifest_contract_issues(work, manifest)


def _candidate_transaction_error(work, manifest, rel, content, user_request=None, validation_failure=None, target_problems=None):
    """V38 transaction: validate source first, then repair the real owner of package/metadata defects."""
    pre = _v36_precommit_candidate_error(work, rel, content)
    if pre:
        return pre

    # Distinguish missing *internal source providers* from missing external npm
    # declarations.  Internal provider gaps remain a hard architecture defect.
    closure = _v38_base_internal_import_error(work, manifest, rel, content)
    package_issue = bool(closure and str(closure).startswith('V36.2 dependency-manifest gate:'))
    if closure and not package_issue:
        return closure

    # Reconcile only planner-only case/camel aliases before the mature strict
    # transaction enforces public APIs.  Consumer-derived names remain exact.
    if Path(str(rel or '')).suffix.lower() in {'.py','.pyw'}:
        try:
            cleaned = _extract_single_file_response(content, rel)
            actual = _python_top_level_exports_from_text(cleaned)
            _v38_reconcile_manifest_exports(work, manifest, rel, actual)
        except Exception:
            pass

    # Use the mature V36.1 transaction for clone/test/API checks after metadata
    # reconciliation.  Its own precommit validator is now JSONC-aware through
    # the global overrides above.
    tx = _v362_base_candidate_transaction_error(
        work, manifest, rel, content,
        user_request=user_request,
        validation_failure=validation_failure,
        target_problems=target_problems,
    )
    if tx:
        return tx

    if package_issue:
        repaired = _v38_auto_repair_package_manifest(work, manifest, rel, content)
        if repaired:
            closure = _v38_base_internal_import_error(work, manifest, rel, content)
        if closure:
            return closure
    return ''


def _v36_patch_repair_candidate(user_request, manifest, work, rel, problems, validation_failure, attempt, progress_callback=None):
    """V38 code edits use plain SEARCH/REPLACE blocks; malformed output is local failure only."""
    path = Path(work) / rel
    try:
        current = path.read_text(encoding='utf-8', errors='replace')
    except Exception:
        return None, 'Target file could not be read.'

    localization = _v36_localize_failure(work, validation_failure) if validation_failure else {'locations': [], 'symbols': [], 'exception': ''}
    excerpt = _v36_target_excerpt(work, rel, localization)
    repo = _v36_repo_map_context(work, manifest, rel, 7000)
    contracts = _v36_contract_context(work, manifest, rel, 5000)
    skill = _v36_stack_skill_context(manifest, 2200)
    history = _v37_recent_patch_history(work, rel)
    history_text = '\n'.join(f"- {x.get('fingerprint')}: {x.get('error','')[:500]}" for x in history[-4:]) or '(none)'
    diagnosis = ''
    if attempt >= 2 and (history or validation_failure):
        diagnosis = _qwen_reasoning_brief(
            'V38 REPAIR DIAGNOSIS ONLY. Identify the smallest root-cause change. Do not write code.\n'
            f'TARGET: {rel}\nISSUES: {json.dumps(problems, ensure_ascii=False)}\n'
            f'FAILURE: {str(validation_failure or "")[-5000:]}\n'
            f'CONTRACTS: {contracts[-3500:]}\nRECENT REJECTIONS: {history_text}',
            progress_callback, f'V38 bounded diagnosis before patch {attempt}: {rel}', max_tokens=900
        )

    prompt = (
        'V38 EDIT MODE. The target file was read immediately before this edit. '
        'Return ONLY one or more exact SEARCH/REPLACE blocks. DO NOT use JSON and DO NOT return the whole file.\n\n'
        'Required format:\n'
        '<<<<<<< SEARCH\n'
        'exact text copied verbatim from the supplied current source\n'
        '=======\n'
        'replacement text\n'
        '>>>>>>> REPLACE\n\n'
        'SEARCH must match the current file exactly once. Make the smallest root-cause fix. '
        'Do not weaken tests, hide missing behavior, or repeat a previously rejected patch.\n\n'
        f'FOCUSED USER/FILE REQUIREMENTS:\n{_v37_focused_file_request(user_request, manifest, work, _manifest_file_item(manifest, rel))}\n\n'
        f'TARGET FILE: {rel}\nISSUES:\n{json.dumps(problems, ensure_ascii=False, indent=2)}\n'
        f'REAL FAILURE:\n{str(validation_failure or "(none)")[-7000:]}\n'
        f'LOCALIZED FAILURE:\n{json.dumps(localization, ensure_ascii=False, indent=2)}\n\n{contracts}\n\n{repo}\n\n{skill}\n'
        f'RECENT REJECTED PATCH FINGERPRINTS/ERRORS:\n{history_text}\n'
        + (f'BOUNDED ROOT-CAUSE BRIEF FROM PRIOR FAILED ATTEMPT:\n{diagnosis}\n' if diagnosis else '')
        + f'\nTARGET SOURCE/EXCERPT:\n{excerpt}\n'
    )

    try:
        ok, raw = _qwen_call(
            prompt, progress_callback,
            f'V38 patch repair {attempt}/{V37_PATCH_CANDIDATES}: {rel}',
            profile='repair', max_tokens=min(3200, _qwen_file_output_limit()),
            thinking=False, response_schema=None, strict_output=False,
        )
    except BaseException as exc:
        _v38_persist_model_output_failure(work, 'patch_call_exception', rel, '', exc)
        return None, f'Patch model call failed safely: {exc}'

    if not ok:
        _v38_persist_model_output_failure(work, 'patch_call_failed', rel, raw, 'provider/model call returned failure')
        return None, 'Patch model call failed; trying another bounded repair strategy.'

    replacements, parse_error = _v38_parse_search_replace_blocks(raw)
    if not replacements:
        _v38_persist_model_output_failure(work, 'patch_parse_failed', rel, raw, parse_error)
        return None, 'Patch response was malformed/incomplete; it was preserved and will not terminate project generation.'

    candidate, err = _v36_apply_search_replace(current, replacements)
    if err:
        _v38_persist_model_output_failure(work, 'patch_apply_failed', rel, raw, err)
        return None, err
    if candidate == current:
        _v37_record_patch_attempt(work, rel, candidate, 'Patch made no change.')
        return None, 'Patch made no change; choose a different strategy.'
    fingerprint = hashlib.sha256(candidate.encode('utf-8', errors='replace')).hexdigest()[:20]
    if any(x.get('fingerprint') == fingerprint for x in history):
        _v37_record_patch_attempt(work, rel, candidate, 'Duplicate patch candidate repeated from recent history.')
        return None, 'Duplicate patch candidate repeated from recent history; choose a different repair.'

    try:
        tx = _candidate_transaction_error(
            work, manifest, rel, candidate,
            user_request=user_request,
            validation_failure=validation_failure,
            target_problems=problems,
        )
    except BaseException as exc:
        _v38_persist_model_output_failure(work, 'patch_transaction_exception', rel, raw, exc)
        return None, f'Patch candidate validation failed safely: {exc}'
    if tx:
        _v37_record_patch_attempt(work, rel, candidate, tx)
        return None, tx
    delta = sum(1 for a,b in zip(current, candidate) if a != b) + abs(len(current)-len(candidate))
    return {
        'content': candidate,
        'delta': delta,
        'summary': f'{len(replacements)} SEARCH/REPLACE block(s)',
        'fingerprint': fingerprint,
    }, ''


# Require test ownership during architecture preflight when the frozen source
# ledger explicitly asks for automated tests.  This is intentionally narrow:
# it does not force tests when the user did not request them.
_v38_base_manifest_completeness_issues = _v362_manifest_completeness_issues

def _v362_manifest_completeness_issues(manifest, spec, user_request, max_files):
    issues = list(_v38_base_manifest_completeness_issues(manifest, spec, user_request, max_files) or [])
    reqs = list((spec or {}).get('source_requirements') or [])
    test_text = ' '.join(str(x.get('text') or '') for x in reqs if str(x.get('category') or '') == 'test').lower()
    if test_text:
        files = [str(x.get('path') or '').replace('\\','/').lower() for x in (manifest or {}).get('files') or []]
        comps = list((manifest or {}).get('components') or [])
        for comp in comps:
            root = str(comp.get('root') or '.').replace('\\','/').strip('/') or '.'
            cid = str(comp.get('id') or root or 'component')
            # Only enforce a component when the source request names it or asks
            # generally for automated tests and it contains executable source.
            component_requested = (root != '.' and root.lower() in test_text) or cid.lower() in test_text
            generic_requested = any(x in test_text for x in ('automated tests','meaningful tests','tests covering','test suite'))
            owned = [p for p in files if root == '.' or p.startswith(root.lower() + '/')]
            code_owned = any(Path(p).suffix.lower() in {'.py','.pyw','.ts','.tsx','.js','.jsx','.rs','.go','.java','.kt','.cs','.cpp','.c'} for p in owned)
            has_test = any(
                '/test' in ('/' + p) or '/tests/' in ('/' + p) or Path(p).name.startswith('test_') or
                any(tag in Path(p).name for tag in ('.test.','.spec.'))
                for p in owned
            )
            if code_owned and not has_test and (component_requested or generic_requested):
                msg = f'Explicit automated-test requirement has no planned test owner in component {cid} ({root}).'
                if msg not in issues:
                    issues.append(msg)
    return issues


# Release/status identity for the drop-in patch.
