    base = {
        'version':'V37.0.0','engine':'SMALL_MODEL_SOFTWARE_FACTORY',
        'requirements_compiler':True,'source_ledger_frozen':True,
        'hierarchical_planner':'bounded-component-v37','semantic_dependency_resolution':True,
        'external_dependency_separation':True,'repo_map':True,'machine_contracts':True,
        'focused_file_context':True,'read_before_edit':True,'patch_repairs':True,
        'patch_protocol':V38_PATCH_PROTOCOL,'malformed_output_isolation':True,
        'dependency_manifest_auto_repair':True,'manifest_contract_self_repair':True,
        'central_jsonc_validation':True,'test_ownership_gate':True,
        'repair_candidates':V37_PATCH_CANDIDATES,'repair_loop_detection':True,
        'large_file_write_guard':True,'green_checkpoints':V36_GREEN_CHECKPOINTS,
        'dynamic_context':True,'strict_host_verification':V35_STRICT_HOST_VERIFICATION,
        'clean_python':V35_CLEAN_PYTHON,'internal_import_closure_gate':True,
    }
    return base


