# ===========================================================================
# V37.2 SUBSYSTEM RECONCILIATION PATCH
# ===========================================================================
# The overnight TaskForge run showed a new bottleneck: file-level safety gates
# correctly rejected bad edits, but related model/repository/service/API/test
# files could disagree about one domain contract and then churn independently
# for hours.  This layer escalates ONE exhausted file repair into a bounded,
# transactional subsystem repair in a disposable clone.  Only a cluster that
# measurably improves deterministic/runtime validation is committed.

V38_SUBSYSTEM_RECONCILIATION = True
V38_SUBSYSTEM_STATE_FILE = 'JARVIS_V38_SUBSYSTEM_REPAIR_STATE.json'
V38_SUBSYSTEM_ESCALATE_AFTER = max(1, int(os.getenv('JARVIS_V38_SUBSYSTEM_ESCALATE_AFTER', '1')))
V38_SUBSYSTEM_MAX_FILES = max(4, min(14, int(os.getenv('JARVIS_V38_SUBSYSTEM_MAX_FILES', '9'))))
V38_SUBSYSTEM_MAX_PATCH_FILES = max(2, min(V38_SUBSYSTEM_MAX_FILES, int(os.getenv('JARVIS_V38_SUBSYSTEM_MAX_PATCH_FILES', '7'))))
V38_SUBSYSTEM_MAX_ESCALATIONS = max(1, min(3, int(os.getenv('JARVIS_V38_SUBSYSTEM_MAX_ESCALATIONS', '1'))))
V38_SUBSYSTEM_BRIEF_TOKENS = max(500, min(1800, int(os.getenv('JARVIS_V38_SUBSYSTEM_BRIEF_TOKENS', '1100'))))

_v381_base_repair_file_for_issues = _repair_file_for_issues
_v381_base_deterministic_acceptance_issues = _deterministic_acceptance_issues


def _v381_load_repair_state(work):
    p = Path(work) / V38_SUBSYSTEM_STATE_FILE
    try:
        data = json.loads(p.read_text(encoding='utf-8', errors='replace')) if p.exists() else {}
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}
    data.setdefault('version', 'V37.2-subsystem')
    data.setdefault('files', {})
    data.setdefault('subsystems', {})
    return data


def _v381_save_repair_state(work, state):
    try:
        p = Path(work) / V38_SUBSYSTEM_STATE_FILE
        state['updated_at'] = _utc_stamp()
        p.write_text(json.dumps(state, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        pass


def _v381_normalized_problem(text):
    value = re.sub(r'\s+', ' ', str(text or '')).strip()
    # Line/column numbers and object addresses should not create a new repair
    # identity every pass when the underlying contract failure is unchanged.
    value = re.sub(r'\bline\s+\d+\b', 'line #', value, flags=re.I)
    value = re.sub(r'\bcolumn\s+\d+\b', 'column #', value, flags=re.I)
    value = re.sub(r'0x[0-9a-fA-F]+', '0x#', value)
    return value[:1800]


def _v381_repair_signature(rel, problems, validation_failure=''):
    parts = [_v381_normalized_problem(x) for x in (problems or []) if str(x or '').strip()]
    if validation_failure:
        try:
            runtime_sig = _validation_failure_signature(validation_failure)
        except Exception:
            runtime_sig = _v381_normalized_problem(validation_failure)[:1200]
        parts.append('RUNTIME:' + str(runtime_sig))
    material = str(rel or '') + '\n' + '\n'.join(sorted(set(parts))[:12])
    return hashlib.sha256(material.encode('utf-8', errors='replace')).hexdigest()[:20]


def _v381_component_root(manifest, rel):
    rel = str(rel or '').replace('\\', '/').strip('/')
    matches = []
    for comp in _v35_sanitize_components((manifest or {}).get('components')):
        root = str(comp.get('root') or '.').replace('\\', '/').strip('/') or '.'
        if root == '.' or rel == root or rel.startswith(root + '/'):
            matches.append((0 if root == '.' else len(root.split('/')), root, comp))
    if matches:
        matches.sort(reverse=True, key=lambda x: x[0])
        return matches[0][1], matches[0][2]
    first = rel.split('/')[0] if '/' in rel else '.'
    return first, {'id': first, 'root': first, 'toolchain_adapter': ''}


def _v381_python_imported_symbol_providers(work, manifest):
    """Return symbol -> provider -> consumer count using real ImportFrom evidence."""
    root = Path(work)
    module_to_rel = {}
    trees = {}
    for rel, path in _v36_project_source_files(root, manifest):
        if Path(rel).suffix.lower() not in {'.py', '.pyw'}:
            continue
        try:
            tree = ast.parse(path.read_text(encoding='utf-8', errors='replace'))
        except Exception:
            continue
        trees[rel] = tree
        try:
            module = _python_module_name_from_rel(rel)
        except Exception:
            module = str(Path(rel).with_suffix('')).replace('\\', '.').replace('/', '.')
        module_to_rel[module] = rel
        if Path(rel).name == '__init__.py':
            module_to_rel[str(Path(rel).parent).replace('\\', '.').replace('/', '.')] = rel

    def resolve(module):
        module = str(module or '').lstrip('.')
        exact = module_to_rel.get(module)
        if exact:
            return exact
        candidates = [(len(k), v) for k, v in module_to_rel.items() if module == k or module.endswith('.' + k) or k.endswith('.' + module)]
        return max(candidates)[1] if candidates else ''

    usage = {}
    for consumer, tree in trees.items():
        for node in tree.body:
            if not isinstance(node, ast.ImportFrom) or not node.module:
                continue
            provider = resolve(node.module)
            if not provider or provider == consumer:
                continue
            for alias in node.names:
                if alias.name == '*':
                    continue
                usage.setdefault(alias.name, {}).setdefault(provider, set()).add(consumer)
    return usage


def _v381_duplicate_python_provider_issues(work, manifest):
    """Flag only *used* ambiguous Python symbols, not every harmless duplicate class name.

    Domain and ORM layers may legitimately have similarly named internal classes.  The dangerous
    case seen overnight is when project consumers actually import the same public symbol from two
    different providers, causing Qwen to reason against two competing contracts.
    """
    root = Path(work)
    defs = {}
    for rel, path in _v36_project_source_files(root, manifest):
        if Path(rel).suffix.lower() not in {'.py', '.pyw'}:
            continue
        try:
            tree = ast.parse(path.read_text(encoding='utf-8', errors='replace'))
        except Exception:
            continue
        for node in tree.body:
            if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith('_'):
                defs.setdefault(node.name, []).append(rel)
    usage = _v381_python_imported_symbol_providers(work, manifest)
    manifest_exports = {}
    for item in (manifest or {}).get('files') or []:
        rel = str(item.get('path') or '').replace('\\', '/')
        for sym in _normalize_export_contract(item.get('exports')):
            manifest_exports.setdefault(sym, []).append(rel)

    issues = []
    for symbol, providers in defs.items():
        providers = sorted(set(providers))
        if len(providers) < 2:
            continue
        used = usage.get(symbol) or {}
        used_providers = [p for p in providers if p in used and used[p]]
        declared = [p for p in providers if p in (manifest_exports.get(symbol) or [])]
        dangerous = len(used_providers) > 1 or len(declared) > 1
        if not dangerous:
            continue
        # Pick a provisional canonical owner from strongest real evidence.  This is guidance for
        # subsystem reconciliation, not an automatic deletion/rename decision.
        def score(rel):
            value = len(used.get(rel) or set()) * 10
            if rel in declared:
                value += 8
            low = rel.lower()
            if any(tag in low for tag in ('/models/', '/model/', '/domain/', '/schemas/', '/schema/')):
                value += 2
            if any(tag in low for tag in ('/tests/', '/test/')):
                value -= 20
            return value
        canonical = sorted(providers, key=lambda p: (-score(p), p))[0]
        for provider in providers:
            if provider == canonical:
                continue
            issues.append({
                'file': provider,
                'provider_file': canonical,
                'kind': 'duplicate_provider',
                'symbol': symbol,
                'problem': (
                    f"V37.2 subsystem contract: public symbol {symbol!r} has competing local providers {providers}. "
                    f"Real import/manifest evidence currently favors {canonical!r} as the canonical owner. "
                    "Reconcile the subsystem so consumers use one coherent contract; do not keep two competing domain APIs."
                ),
            })
    return issues


def _deterministic_acceptance_issues(work, manifest):
    issues = list(_v381_base_deterministic_acceptance_issues(work, manifest) or [])
    seen = {(str(x.get('file') or ''), _v381_normalized_problem(x.get('problem') or '')) for x in issues}
    for item in _v381_duplicate_python_provider_issues(work, manifest):
        key = (str(item.get('file') or ''), _v381_normalized_problem(item.get('problem') or ''))
        if key not in seen:
            issues.append(item)
            seen.add(key)
    return issues


def _v381_layer_priority(rel):
    low = '/' + str(rel or '').replace('\\', '/').lower().strip('/') + '/'
    # Providers before consumers; tests last.  This keeps a reconciliation pass moving in the same
    # direction as the dependency graph instead of repeatedly rewriting callers against stale APIs.
    table = (
        (0, ('/domain/', '/models/', '/model/', '/schemas/', '/schema/')),
        (1, ('/database/', '/db/', '/repositories/', '/repository/', '/repo/')),
        (2, ('/services/', '/service/')),
        (3, ('/api/', '/routes/', '/routers/', '/controllers/', '/controller/')),
        (4, ('/state/', '/hooks/', '/components/', '/ui/', '/views/')),
        (5, ('/tests/', '/test/')),
    )
    for rank, tags in table:
        if any(tag in low for tag in tags):
            return rank
    return 3


def _v381_select_subsystem_files(work, manifest, target_rel, current_issues=None):
    target_rel = str(target_rel or '').replace('\\', '/')
    graph = _v36_build_repo_graph(work, manifest, write=True)
    files = graph.get('files') or {}
    root_name, component = _v381_component_root(manifest, target_rel)
    scores = {}

    def add(rel, score):
        rel = str(rel or '').replace('\\', '/')
        if rel not in files:
            return
        rroot, _ = _v381_component_root(manifest, rel)
        if rroot != root_name:
            return
        if Path(rel).suffix.lower() not in _SOURCE_SUFFIXES:
            return
        scores[rel] = max(float(score), scores.get(rel, float('-inf')))

    add(target_rel, 1000)
    info = files.get(target_rel) or {}
    for edge in info.get('edges') or []:
        add(edge.get('to'), 760 + float(edge.get('weight') or 0))
    for rel, finfo in files.items():
        for edge in finfo.get('edges') or []:
            if edge.get('to') == target_rel:
                add(rel, 720 + float(edge.get('weight') or 0))

    # Manifest dependencies/dependents often remain useful even when the current source is broken
    # enough that AST import extraction cannot resolve the edge.
    target_item = _manifest_file_item(manifest or {}, target_rel)
    for dep in target_item.get('depends_on') or []:
        add(dep, 820)
    for item in (manifest or {}).get('files') or []:
        rel = str(item.get('path') or '').replace('\\', '/')
        if target_rel in [str(x).replace('\\', '/') for x in (item.get('depends_on') or [])]:
            add(rel, 790)

    all_issues = list(current_issues or _deterministic_acceptance_issues(work, manifest))
    for issue in all_issues:
        f = str(issue.get('file') or '').replace('\\', '/')
        p = str(issue.get('provider_file') or '').replace('\\', '/')
        if f == target_rel or p == target_rel or f in scores or p in scores:
            add(f, 900)
            add(p, 940)

    # Give nearby core-domain layers a small chance to enter the cluster, but never dump the whole
    # component into Qwen.  Centrality and provider-first layer priority break ties.
    target_parent = Path(target_rel).parent
    for rel, finfo in files.items():
        rroot, _ = _v381_component_root(manifest, rel)
        if rroot != root_name:
            continue
        low = rel.lower()
        if Path(rel).parent == target_parent:
            add(rel, 420 + float(finfo.get('rank') or 0) * 100)
        elif any(tag in ('/' + low) for tag in ('/models/', '/domain/', '/database/', '/db/', '/repositories/', '/services/', '/api/', '/routes/')):
            add(rel, 260 + float(finfo.get('rank') or 0) * 100)

    ranked = sorted(
        scores,
        key=lambda r: (-scores[r], _v381_layer_priority(r), r),
    )[:V38_SUBSYSTEM_MAX_FILES]
    # Reorder the chosen cluster provider-first for actual patch application while always retaining target.
    ranked = sorted(ranked, key=lambda r: (_v381_layer_priority(r), 0 if r == target_rel else 1, -scores[r], r))
    return ranked, root_name, component


def _v381_subsystem_issue_rows(work, manifest, selected):
    selected = set(selected or [])
    rows = []
    for issue in _deterministic_acceptance_issues(work, manifest):
        f = str(issue.get('file') or '').replace('\\', '/')
        p = str(issue.get('provider_file') or '').replace('\\', '/')
        if f in selected or p in selected:
            rows.append(issue)
    return rows


def _v381_issue_set(rows):
    out = set()
    for x in rows or []:
        f = str(x.get('file') or '')
        p = str(x.get('provider_file') or '')
        kind = str(x.get('kind') or '')
        problem = _v381_normalized_problem(x.get('problem') or '')
        out.add((f, p, kind, problem))
    return out


def _v381_subsystem_contract_snapshot(work, manifest, selected, max_chars=12000):
    selected = set(selected or [])
    graph = _v36_build_repo_graph(work, manifest, write=True).get('files') or {}
    registry = _v36_build_contract_registry(work, manifest, write=True).get('contracts') or []
    lines = ['MACHINE SUBSYSTEM SNAPSHOT:']
    for rel in selected:
        info = graph.get(rel) or {}
        syms = []
        for sym in info.get('symbols') or []:
            sig = str(sym.get('signature') or sym.get('name') or '')
            if sig:
                syms.append(sig)
        item = _manifest_file_item(manifest or {}, rel)
        lines.append(f'FILE {rel}')
        lines.append('  manifest exports: ' + ', '.join(_normalize_export_contract(item.get('exports'))) if _normalize_export_contract(item.get('exports')) else '  manifest exports: (none)')
        if syms:
            lines.append('  actual symbols: ' + '; '.join(syms[:24]))
        edges = [str(e.get('to') or '') for e in info.get('edges') or [] if str(e.get('to') or '') in selected]
        if edges:
            lines.append('  depends/calls: ' + ', '.join(edges[:16]))
    lines.append('ACTUAL CONTRACTS:')
    for row in registry:
        if str(row.get('provider') or '') in selected:
            lines.append(f"  {row.get('provider')}: {row.get('symbol')} :: {row.get('signature')}")
        if len('\n'.join(lines)) > max_chars:
            break
    return '\n'.join(lines)[:max_chars]


def _v381_subsystem_reconciliation_brief(user_request, manifest, work, target_rel, selected, issues, validation_failure, progress_callback=None):
    snapshot = _v381_subsystem_contract_snapshot(work, manifest, selected)
    issue_text = '\n'.join(
        f"- {x.get('kind')}: {x.get('file')} -> {x.get('provider_file') or ''}: {x.get('problem')}"
        for x in (issues or [])[:24]
    )
    prompt = (
        'V37.2 SUBSYSTEM ARCHITECT/DEBUGGER. DO NOT WRITE SOURCE CODE. A small model has exhausted file-level repairs, '
        'so choose ONE coherent contract for this bounded subsystem. Use actual AST/import/test evidence over planner guesses. '
        'If duplicate domain/model/repository/service APIs exist, explicitly choose the canonical owner and state which consumers '
        'must follow it. Give a short provider-first repair plan. Do not suggest weakening tests. Keep the answer under 900 words.\n\n'
        f'TARGET THAT EXHAUSTED FILE REPAIR: {target_rel}\n'
        f'FILES IN TRANSACTIONAL SUBSYSTEM: {json.dumps(selected, ensure_ascii=False)}\n\n'
        f'CURRENT DETERMINISTIC ISSUES:\n{issue_text or "(none)"}\n\n'
        f'REAL VALIDATION FAILURE (if any):\n{str(validation_failure or "(none)")[-5000:]}\n\n'
        f'{snapshot}\n'
    )
    try:
        ok, raw = _qwen_call(
            prompt, progress_callback, f'V37.2 reconciling subsystem contracts around {target_rel}',
            profile='repair', max_tokens=V38_SUBSYSTEM_BRIEF_TOKENS, thinking=False,
            response_schema=None, strict_output=False,
        )
        if ok and str(raw or '').strip():
            return str(raw).strip()[:9000]
    except BaseException as exc:
        _v38_persist_model_output_failure(work, 'subsystem_brief_exception', target_rel, '', exc)
    # Deterministic fallback still gives subsequent patch calls a shared objective.
    return (
        'Jarvis subsystem reconciliation fallback: preserve one canonical provider per public symbol; '
        'repair providers before services/callers and tests last; use actual current signatures/imports as authority; '
        'do not create compatibility duplicates merely to satisfy stale planner metadata.'
    )


def _v381_commit_subsystem_clone(work, clone, selected, changed_files, brief):
    committed = []
    for rel in changed_files:
        src = Path(clone) / rel
        dst = Path(work) / rel
        if not src.exists() or not src.is_file():
            continue
        try:
            before = dst.read_text(encoding='utf-8', errors='replace') if dst.exists() else ''
            after = src.read_text(encoding='utf-8', errors='replace')
        except Exception:
            continue
        if before == after:
            continue
        _v36_checkpoint_file(work, rel, before, 'before_v372_subsystem_commit')
        dst.parent.mkdir(parents=True, exist_ok=True)
        tmp = dst.with_name(dst.name + '.jarvis_subsystem_tmp')
        tmp.write_text(after, encoding='utf-8')
        tmp.replace(dst)
        _delete_candidate_draft(work, rel)
        committed.append(rel)
    if committed:
        _v36_build_repo_graph(work, manifest=None, write=False) if False else None
    return committed


def _v381_reconcile_subsystem(user_request, manifest, work, target_rel, problems, validation_failure='', progress_callback=None):
    """Try one coherent multi-file repair in a disposable clone and commit only measurable progress."""
    selected, component_root, component = _v381_select_subsystem_files(work, manifest, target_rel)
    if len(selected) < 2:
        return False, 'No meaningful related subsystem could be identified.'

    baseline_rows = _v381_subsystem_issue_rows(work, manifest, selected)
    baseline_set = _v381_issue_set(baseline_rows)
    brief = _v381_subsystem_reconciliation_brief(
        user_request, manifest, work, target_rel, selected, baseline_rows,
        validation_failure, progress_callback,
    )
    _append_project_event(
        work, 'v372_subsystem_escalation_started',
        f'Escalating exhausted file repair into one transactional subsystem reconciliation around {target_rel}.',
        file=target_rel, component=str(component.get('id') or component_root), files=selected,
        deterministic_issues=len(baseline_set),
    )
    _progress(
        progress_callback,
        f'V37.2 subsystem reconciliation: {component.get("id") or component_root} ({len(selected)} files)',
        stage='repairing', percent=79,
    )

    temp = None
    try:
        temp, clone = _copy_project_for_candidate_validation(work)
        changed = []
        # Recompute issue routing after each accepted patch because fixing a provider can make several
        # caller defects disappear without editing those callers.
        for rel in selected:
            if len(changed) >= V38_SUBSYSTEM_MAX_PATCH_FILES:
                break
            current_rows = _v381_subsystem_issue_rows(clone, manifest, selected)
            rel_rows = [x for x in current_rows if str(x.get('file') or '') == rel or str(x.get('provider_file') or '') == rel]
            if rel == target_rel and not rel_rows:
                rel_rows = [{'file': rel, 'kind': 'repair_exhausted', 'problem': p} for p in (problems or [])[:8]]
            if not rel_rows:
                continue
            local_problems = [str(x.get('problem') or '') for x in rel_rows if str(x.get('problem') or '').strip()]
            local_problems.append(
                'SUBSYSTEM RECONCILIATION AUTHORITY: ' + brief[:6500]
            )
            local_problems.append(
                'Provider-first transaction rule: align this file to the one canonical subsystem contract. '
                'Do not create duplicate aliases/classes/services merely to preserve conflicting old implementations.'
            )
            candidate = None
            last_err = ''
            # Two focused edit attempts per file inside the cluster are enough; a third/fourth failed
            # local strategy is exactly the loop this escalation is designed to avoid.
            for attempt in range(1, 3):
                candidate, last_err = _v36_patch_repair_candidate(
                    user_request, manifest, clone, rel, local_problems,
                    None, attempt, progress_callback,
                )
                if candidate:
                    break
            if not candidate:
                _append_project_event(
                    work, 'v372_subsystem_file_skipped',
                    f'Subsystem reconciliation could not produce a safe focused patch for {rel}; leaving it unchanged in clone.',
                    file=rel, reason=str(last_err or '')[-1600:],
                )
                continue
            p = Path(clone) / rel
            try:
                p.write_text(candidate['content'], encoding='utf-8')
                changed.append(rel)
                _v36_build_repo_graph(clone, manifest, write=True)
                _v36_build_contract_registry(clone, manifest, write=True)
            except Exception as exc:
                _append_project_event(work, 'v372_subsystem_clone_write_failed', f'Could not stage subsystem candidate {rel}.', file=rel, reason=str(exc))
                continue

        if not changed:
            return False, 'Subsystem escalation produced no safe staged changes.'

        candidate_rows = _v381_subsystem_issue_rows(clone, manifest, selected)
        candidate_set = _v381_issue_set(candidate_rows)
        introduced = candidate_set - baseline_set
        removed = baseline_set - candidate_set

        runtime_advanced = False
        replay_output = ''
        if validation_failure:
            try:
                replay_ok, replay_output = _replay_validation_for_failure(clone, user_request, manifest, validation_failure)
                runtime_advanced = bool(replay_ok or not _runtime_failure_still_present(validation_failure, replay_output))
            except Exception as exc:
                replay_output = f'replay unavailable: {exc}'

        # Do not require zero remaining issues.  A multi-file repair is accepted when it demonstrably
        # moves the project forward and does not introduce more deterministic defects than it removes.
        deterministic_improved = len(candidate_set) < len(baseline_set) and len(introduced) <= max(1, len(removed) // 2)
        if not (runtime_advanced or deterministic_improved):
            _append_project_event(
                work, 'v372_subsystem_candidate_rejected',
                'Transactional subsystem candidate did not advance runtime validation or reduce deterministic contract defects.',
                file=target_rel, files=changed, baseline_issues=len(baseline_set), candidate_issues=len(candidate_set),
                introduced=[x[-1] for x in list(introduced)[:8]], replay=str(replay_output or '')[-2500:],
            )
            return False, 'Subsystem candidate did not measurably improve validation.'

        committed = []
        for rel in changed:
            src = Path(clone) / rel
            dst = Path(work) / rel
            if not src.exists():
                continue
            before = dst.read_text(encoding='utf-8', errors='replace') if dst.exists() else ''
            after = src.read_text(encoding='utf-8', errors='replace')
            if before == after:
                continue
            _v36_checkpoint_file(work, rel, before, 'before_v372_subsystem_commit')
            dst.parent.mkdir(parents=True, exist_ok=True)
            tmp = dst.with_name(dst.name + '.jarvis_v372_tmp')
            tmp.write_text(after, encoding='utf-8')
            tmp.replace(dst)
            _delete_candidate_draft(work, rel)
            committed.append(rel)

        if not committed:
            return False, 'Subsystem candidate validated but contained no committable changes.'
        _v36_build_repo_graph(work, manifest, write=True)
        _v36_build_contract_registry(work, manifest, write=True)
        _append_project_event(
            work, 'v372_subsystem_reconciled',
            f'Committed one provider-first subsystem reconciliation across {len(committed)} file(s).',
            file=target_rel, files=committed, baseline_issues=len(baseline_set),
            remaining_issues=len(candidate_set), removed_issues=len(removed), runtime_advanced=runtime_advanced,
            component=str(component.get('id') or component_root),
        )
        return True, f'Committed subsystem reconciliation: {committed}'
    except BaseException as exc:
        _append_project_event(
            work, 'v372_subsystem_exception',
            'Subsystem reconciliation failed safely; live workspace was not partially committed.',
            file=target_rel, error=str(exc)[-2200:],
        )
        return False, f'Subsystem reconciliation failed safely: {exc}'
    finally:
        if temp is not None:
            try:
                temp.cleanup()
            except Exception:
                pass


def _repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback=None, validation_failure=None):
    """V37.2: one exhausted file repair escalates once to a bounded subsystem transaction.

    Repeated attempts for an already-exhausted identical failure are skipped so the acceptance loop can
    obtain fresh evidence/terminate instead of spending another night asking the model for the same edit.
    """
    sig = _v381_repair_signature(rel, problems, validation_failure or '')
    state = _v381_load_repair_state(work)
    files = state.setdefault('files', {})
    entry = files.setdefault(str(rel), {}).setdefault(sig, {
        'failures': 0, 'successes': 0, 'subsystem_escalations': 0, 'subsystem_exhausted': False,
    })

    if entry.get('subsystem_exhausted') and int(entry.get('failures') or 0) >= V38_SUBSYSTEM_ESCALATE_AFTER:
        _append_project_event(
            work, 'v372_repeat_repair_suppressed',
            f'Suppressed repeated expensive repair for {rel}; identical file + subsystem strategies already exhausted.',
            file=rel, signature=sig, failures=entry.get('failures'),
        )
        return False

    repaired = _v381_base_repair_file_for_issues(
        user_request, manifest, work, rel, problems, progress_callback, validation_failure
    )
    if repaired:
        entry['successes'] = int(entry.get('successes') or 0) + 1
        entry['failures'] = 0
        entry['subsystem_exhausted'] = False
        _v381_save_repair_state(work, state)
        return True

    entry['failures'] = int(entry.get('failures') or 0) + 1
    entry['last_failure_at'] = _utc_stamp()
    _v381_save_repair_state(work, state)

    if not V38_SUBSYSTEM_RECONCILIATION or entry['failures'] < V38_SUBSYSTEM_ESCALATE_AFTER:
        return False
    if int(entry.get('subsystem_escalations') or 0) >= V38_SUBSYSTEM_MAX_ESCALATIONS:
        entry['subsystem_exhausted'] = True
        _v381_save_repair_state(work, state)
        return False

    entry['subsystem_escalations'] = int(entry.get('subsystem_escalations') or 0) + 1
    _v381_save_repair_state(work, state)
    ok, detail = _v381_reconcile_subsystem(
        user_request, manifest, work, rel, problems, validation_failure or '', progress_callback
    )
    state = _v381_load_repair_state(work)
    entry = state.setdefault('files', {}).setdefault(str(rel), {}).setdefault(sig, {})
    if ok:
        entry['successes'] = int(entry.get('successes') or 0) + 1
        entry['failures'] = 0
        entry['subsystem_exhausted'] = False
        entry['last_subsystem_result'] = detail
        _v381_save_repair_state(work, state)
        return True
    entry['subsystem_exhausted'] = True
    entry['last_subsystem_result'] = detail
    _v381_save_repair_state(work, state)
    return False


# Surface the escalation state in diagnostics without renaming the user's V37 drop-in release.
_v381_release_identity_base = _v36_release_identity

def _v36_release_identity():
    data = dict(_v381_release_identity_base() or {})
    data.update({
        'subsystem_reconciliation': True,
        'subsystem_transactional_clone': True,
        'duplicate_provider_detection': True,
        'repair_escalate_after_exhausted_file': V38_SUBSYSTEM_ESCALATE_AFTER,
        'subsystem_max_files': V38_SUBSYSTEM_MAX_FILES,
        'repeat_repair_suppression': True,
    })
    return data


_v381_write_build_status_base = _v33_write_build_status

def _v33_write_build_status(work, manifest, stage, current_file='', implemented=None):
    _v381_write_build_status_base(work, manifest, stage, current_file=current_file, implemented=implemented)
    try:
        p = Path(work) / V33_BUILD_STATUS_FILE
        data = json.loads(p.read_text(encoding='utf-8', errors='replace')) if p.exists() else {}
        data.update({
            'subsystem_reconciliation': True,
            'subsystem_transactional_clone': True,
            'duplicate_provider_detection': True,
            'repeat_repair_suppression': True,
        })
        p.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        pass

# V37.2.1 convergence guards: one broken component may surface through many files.  Do not let
# each leaf independently trigger another expensive subsystem reconciliation unless repository
# state has actually changed since the last subsystem attempt.
V38_SUBSYSTEM_COMPONENT_MAX_ATTEMPTS = max(1, min(3, int(os.getenv('JARVIS_V38_SUBSYSTEM_COMPONENT_MAX_ATTEMPTS', '1'))))


def _v381_subsystem_state_key(work, manifest, rel):
    selected, root, component = _v381_select_subsystem_files(work, manifest, rel)
    material = str(component.get('id') or root) + '|' + '|'.join(sorted(selected))
    return hashlib.sha256(material.encode('utf-8', errors='replace')).hexdigest()[:18], selected, root, component


def _v381_repo_token_safe(work, manifest):
    try:
        return str(_v36_repo_state_token(Path(work), manifest))
    except Exception:
        # Fallback changes whenever substantive source mtimes/sizes change.
        rows = []
        try:
            for rel, p in _v36_project_source_files(work, manifest):
                st = p.stat(); rows.append((rel, int(st.st_mtime_ns), int(st.st_size)))
        except Exception:
            pass
        return hashlib.sha256(repr(sorted(rows)).encode()).hexdigest()[:24]


# Replace only the final wrapper with a component-aware convergence guard.  The actual file repair
# and transactional subsystem implementation above remain unchanged.
_v381_file_repair_with_subsystem = _repair_file_for_issues


def _repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback=None, validation_failure=None):
    sig = _v381_repair_signature(rel, problems, validation_failure or '')
    state = _v381_load_repair_state(work)
    file_entry = state.setdefault('files', {}).setdefault(str(rel), {}).setdefault(sig, {
        'failures': 0, 'successes': 0, 'subsystem_escalations': 0, 'subsystem_exhausted': False,
    })

    # If this exact file/signature already exhausted both local and subsystem strategies, do not
    # call the model again.  Fresh validation or another committed file change must alter the
    # signature/repository state before expensive work resumes.
    if file_entry.get('subsystem_exhausted') and int(file_entry.get('failures') or 0) >= V38_SUBSYSTEM_ESCALATE_AFTER:
        _append_project_event(
            work, 'v372_repeat_repair_suppressed',
            f'Suppressed repeated expensive repair for {rel}; identical strategies already exhausted.',
            file=rel, signature=sig,
        )
        return False

    # Run the normal V37 read-before-edit + transactional file repair exactly once.
    repaired = _v381_base_repair_file_for_issues(
        user_request, manifest, work, rel, problems, progress_callback, validation_failure
    )
    if repaired:
        file_entry['successes'] = int(file_entry.get('successes') or 0) + 1
        file_entry['failures'] = 0
        file_entry['subsystem_exhausted'] = False
        _v381_save_repair_state(work, state)
        return True

    file_entry['failures'] = int(file_entry.get('failures') or 0) + 1
    file_entry['last_failure_at'] = _utc_stamp()
    if not V38_SUBSYSTEM_RECONCILIATION or file_entry['failures'] < V38_SUBSYSTEM_ESCALATE_AFTER:
        _v381_save_repair_state(work, state)
        return False

    subkey, selected, root_name, component = _v381_subsystem_state_key(work, manifest, rel)
    token = _v381_repo_token_safe(work, manifest)
    sub = state.setdefault('subsystems', {}).setdefault(subkey, {
        'component': str(component.get('id') or root_name), 'files': selected,
        'repo_token': token, 'attempts': 0, 'exhausted': False,
    })
    # Any committed change in the cluster permits one fresh subsystem attempt.  No-change repeated
    # acceptance passes do not.
    if str(sub.get('repo_token') or '') != token:
        sub.update({'repo_token': token, 'attempts': 0, 'exhausted': False, 'files': selected})
    if sub.get('exhausted') or int(sub.get('attempts') or 0) >= V38_SUBSYSTEM_COMPONENT_MAX_ATTEMPTS:
        file_entry['subsystem_exhausted'] = True
        _v381_save_repair_state(work, state)
        _append_project_event(
            work, 'v372_subsystem_repeat_suppressed',
            f'Suppressed another subsystem reconciliation for {component.get("id") or root_name}; no repository change since the exhausted transaction.',
            file=rel, subsystem_files=selected, repo_token=token,
        )
        return False

    sub['attempts'] = int(sub.get('attempts') or 0) + 1
    file_entry['subsystem_escalations'] = int(file_entry.get('subsystem_escalations') or 0) + 1
    _v381_save_repair_state(work, state)
    ok, detail = _v381_reconcile_subsystem(
        user_request, manifest, work, rel, problems, validation_failure or '', progress_callback
    )
    state = _v381_load_repair_state(work)
    file_entry = state.setdefault('files', {}).setdefault(str(rel), {}).setdefault(sig, {})
    sub = state.setdefault('subsystems', {}).setdefault(subkey, {})
    if ok:
        file_entry.update({'failures': 0, 'subsystem_exhausted': False, 'last_subsystem_result': detail})
        file_entry['successes'] = int(file_entry.get('successes') or 0) + 1
        # Source changed; record the new token and allow a future *different* failure to escalate.
        sub.update({'repo_token': _v381_repo_token_safe(work, manifest), 'attempts': 0, 'exhausted': False, 'last_result': detail})
        _v381_save_repair_state(work, state)
        return True

    file_entry['subsystem_exhausted'] = True
    file_entry['last_subsystem_result'] = detail
    sub.update({'repo_token': token, 'exhausted': True, 'last_result': detail})
    _v381_save_repair_state(work, state)
    return False


# Expand V36.1's immediate generation gate to include the architecture problems that caused the
# overnight cascade.  Dependency/import and duplicate-provider errors are safe to catch here once
# their referenced provider is already materialized; the normal bootstrap gate still tolerates
# genuinely not-yet-generated siblings.
_v381_foundation_issues_base = _v361_current_file_foundation_issues


def _v361_current_file_foundation_issues(work, manifest, rel):
    relevant = list(_v381_foundation_issues_base(work, manifest, rel) or [])
    seen = {(str(x.get('file') or ''), _v381_normalized_problem(x.get('problem') or '')) for x in relevant}
    hard_more = {'duplicate_provider', 'identity', 'definite_none'}
    for issue in _deterministic_acceptance_issues(work, manifest):
        if str(issue.get('kind') or '') not in hard_more:
            continue
        if str(issue.get('file') or '') != rel and str(issue.get('provider_file') or '') != rel:
            continue
        key = (str(issue.get('file') or ''), _v381_normalized_problem(issue.get('problem') or ''))
        if key not in seen:
            relevant.append(issue); seen.add(key)
    return relevant[:16]


# Tighten default no-progress behavior without preventing genuine progress.  Users can explicitly
# raise these environment settings before launch if they prefer longer experimentation.
if 'JARVIS_QWEN_ACCEPTANCE_NO_PROGRESS_LIMIT' not in os.environ:
    PROJECT_ACCEPTANCE_NO_PROGRESS_LIMIT = min(PROJECT_ACCEPTANCE_NO_PROGRESS_LIMIT, 3)
if 'JARVIS_QWEN_ACCEPTANCE_EXTRA_CLEAN_ROUNDS' not in os.environ:
    PROJECT_ACCEPTANCE_EXTRA_CLEAN_ROUNDS = min(PROJECT_ACCEPTANCE_EXTRA_CLEAN_ROUNDS, 2)

# V37.2.2 targeted deterministic ORM/storage semantics learned from the overnight TaskForge run.
_v3821_deterministic_base = _deterministic_acceptance_issues


def _v382_sqlalchemy_semantic_issues(work, manifest):
    issues = []
    for rel, path in _v36_project_source_files(work, manifest):
        if Path(rel).suffix.lower() not in {'.py', '.pyw'}:
            continue
        try:
            text = path.read_text(encoding='utf-8', errors='replace')
            tree = ast.parse(text)
        except Exception:
            continue
        sqlalchemy_enum_aliases = set()
        sqlalchemy_create_engine_aliases = {'create_engine'}
        for node in tree.body:
            if isinstance(node, ast.ImportFrom) and str(node.module or '').startswith('sqlalchemy'):
                for alias in node.names:
                    if alias.name == 'Enum':
                        sqlalchemy_enum_aliases.add(alias.asname or alias.name)
                    if alias.name == 'create_engine':
                        sqlalchemy_create_engine_aliases.add(alias.asname or alias.name)
        for node in tree.body:
            if isinstance(node, ast.ClassDef):
                bad_base = False
                for base in node.bases:
                    if isinstance(base, ast.Name) and base.id in sqlalchemy_enum_aliases:
                        bad_base = True
                    elif isinstance(base, ast.Attribute) and base.attr == 'Enum' and isinstance(base.value, ast.Name) and base.value.id.lower().startswith('sqlalchemy'):
                        bad_base = True
                if bad_base:
                    issues.append({
                        'file': rel, 'kind': 'orm_contract', 'line': getattr(node, 'lineno', 0),
                        'problem': (
                            f"V37.2 ORM contract: class {node.name!r} subclasses SQLAlchemy Enum, which is a column/type object, "
                            "not a Python application enum base. Define domain values with enum.Enum/str+Enum and map them through "
                            "SQLAlchemy Enum in the ORM column instead."
                        ),
                    })

        # Detect the common doubled SQLite URL construction deterministically: a variable whose
        # default/already-assigned value starts with sqlite: is interpolated into another sqlite:/// prefix.
        url_vars = set()
        for node in ast.walk(tree):
            if not isinstance(node, (ast.Assign, ast.AnnAssign)):
                continue
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            value = node.value
            is_sqlite_url = False
            if isinstance(value, ast.Constant) and isinstance(value.value, str) and value.value.lower().startswith('sqlite:'):
                is_sqlite_url = True
            elif isinstance(value, ast.Call) and isinstance(value.func, ast.Attribute) and value.func.attr == 'getenv':
                for arg in value.args[1:2]:
                    if isinstance(arg, ast.Constant) and isinstance(arg.value, str) and arg.value.lower().startswith('sqlite:'):
                        is_sqlite_url = True
            if is_sqlite_url:
                for target in targets:
                    if isinstance(target, ast.Name):
                        url_vars.add(target.id)
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            fname = ''
            if isinstance(node.func, ast.Name):
                fname = node.func.id
            elif isinstance(node.func, ast.Attribute):
                fname = node.func.attr
            if fname not in sqlalchemy_create_engine_aliases and fname != 'create_engine':
                continue
            if not node.args or not isinstance(node.args[0], ast.JoinedStr):
                continue
            joined = node.args[0]
            literal_prefix = ''.join(str(v.value) for v in joined.values if isinstance(v, ast.Constant) and isinstance(v.value, str))
            formatted_names = {
                v.value.id for v in joined.values
                if isinstance(v, ast.FormattedValue) and isinstance(v.value, ast.Name)
            }
            bad_vars = sorted(formatted_names & url_vars)
            if literal_prefix.lower().startswith('sqlite:') and bad_vars:
                issues.append({
                    'file': rel, 'kind': 'data_contract', 'line': getattr(node, 'lineno', 0),
                    'problem': (
                        f"V37.2 SQLite URL contract: create_engine adds a sqlite: URL prefix around variable(s) {bad_vars} that already "
                        "contain a sqlite: URL. Pass the URL variable directly, or store only a filesystem path before adding the prefix."
                    ),
                })
    return issues


def _deterministic_acceptance_issues(work, manifest):
    issues = list(_v3821_deterministic_base(work, manifest) or [])
    seen = {(str(x.get('file') or ''), _v381_normalized_problem(x.get('problem') or '')) for x in issues}
    for item in _v382_sqlalchemy_semantic_issues(work, manifest):
        key = (str(item.get('file') or ''), _v381_normalized_problem(item.get('problem') or ''))
        if key not in seen:
            issues.append(item); seen.add(key)
    return issues


# Include the new deterministic ORM issue in immediate foundation repair.
_v3821_foundation_base = _v361_current_file_foundation_issues

def _v361_current_file_foundation_issues(work, manifest, rel):
    relevant = list(_v3821_foundation_base(work, manifest, rel) or [])
    seen = {(str(x.get('file') or ''), _v381_normalized_problem(x.get('problem') or '')) for x in relevant}
    for issue in _deterministic_acceptance_issues(work, manifest):
        if str(issue.get('kind') or '') != 'orm_contract':
            continue
        if str(issue.get('file') or '') != rel and str(issue.get('provider_file') or '') != rel:
            continue
        key = (str(issue.get('file') or ''), _v381_normalized_problem(issue.get('problem') or ''))
        if key not in seen:
            relevant.append(issue); seen.add(key)
    return relevant[:18]

# ===========================================================================
# V37.3 PERSISTENT PROJECT KNOWLEDGE BASE + WINDOWS PATH IDENTITY PATCH
# ===========================================================================
# The 2026-08-29 TaskForge run exposed two coupled failure sources:
#   1) Qwen could legitimately see two spellings of one Windows path (Backend/... vs backend/...)
#      as separate files/providers because Jarvis staged/reasoned about them case-sensitively.
#   2) Project knowledge lived across several transient graph/contract/state files, but Qwen did not
#      receive one durable, authoritative source of truth for canonical models/signatures/owners.
#
# V37.3 introduces a persistent project Knowledge Base (KB). The KB stores the whole project as
# compact machine state and injects only the relevant slice into each Qwen call. Jarvis, not Qwen,
# owns canonical path identity and canonical contract ownership.

V373_VERSION = '37.3.0'
V373_PROJECT_KB_FILE = 'JARVIS_V37_PROJECT_KB.json'
V373_KB_CONTEXT_CHARS = max(6000, min(24000, int(os.getenv('JARVIS_V37_PROJECT_KB_CONTEXT_CHARS', '14000'))))
V373_KB_FULL_INDEX_CHARS = max(2500, min(10000, int(os.getenv('JARVIS_V37_PROJECT_KB_INDEX_CHARS', '6500'))))
V373_KB_MAX_EVENTS = max(8, min(80, int(os.getenv('JARVIS_V37_PROJECT_KB_EVENTS', '24'))))
V373_KB_MAX_CONTRACTS = max(200, min(10000, int(os.getenv('JARVIS_V37_PROJECT_KB_MAX_CONTRACTS', '5000'))))


def _v373_clean_rel(rel):
    """Normalize a repository-relative path without assuming filesystem case semantics."""
    raw = str(rel or '').replace('\\', '/').strip().strip('`').strip('"').strip("'")
    while raw.startswith('./'):
        raw = raw[2:]
    raw = re.sub(r'/+', '/', raw).strip('/')
    parts = []
    for part in raw.split('/') if raw else []:
        if part in ('', '.'):
            continue
        if part == '..':
            if parts:
                parts.pop()
            continue
        parts.append(part)
    return '/'.join(parts)


def _v373_case_insensitive_paths(manifest=None, user_request=''):
    override = os.getenv('JARVIS_PROJECT_CASE_INSENSITIVE_PATHS')
    if override is not None:
        return str(override).strip().lower() not in {'0', 'false', 'no', 'off'}
    if os.name == 'nt':
        return True
    blob = ' '.join([
        str((manifest or {}).get('platform') or ''),
        str((manifest or {}).get('_original_user_request') or ''),
        str(user_request or ''),
    ]).lower()
    return bool(re.search(r'\bwindows\b|\bwin32\b|\bwin64\b', blob))


def _v373_path_identity(rel, manifest=None, user_request=''):
    clean = _v373_clean_rel(rel)
    return clean.casefold() if _v373_case_insensitive_paths(manifest, user_request) else clean


def _v373_component_root_map(manifest):
    roots = {}
    for comp in (manifest or {}).get('components') or []:
        if not isinstance(comp, dict):
            continue
        root = _v373_clean_rel(comp.get('root') or '.') or '.'
        if root == '.':
            continue
        key = root.casefold()
        # Prefer the architect's first spelling, but normalize the common component roots to the
        # conventional lowercase spelling on Windows. This prevents Backend/Frontend drift.
        canonical = root
        if _v373_case_insensitive_paths(manifest):
            first = root.split('/')[0]
            if first.casefold() in {'backend', 'frontend', 'shared', 'server', 'client', 'tests', 'test'}:
                canonical = '/'.join([first.casefold()] + root.split('/')[1:])
        roots.setdefault(key, canonical)
    return roots


def _v373_apply_component_root_case(manifest, rel):
    clean = _v373_clean_rel(rel)
    if not clean:
        return clean
    if not _v373_case_insensitive_paths(manifest):
        return clean
    roots = _v373_component_root_map(manifest)
    # Longest component root wins in case a component is nested under another component.
    for key, canonical in sorted(roots.items(), key=lambda kv: len(kv[0]), reverse=True):
        low = clean.casefold()
        if low == key:
            return canonical
        if low.startswith(key + '/'):
            return canonical + clean[len(key):]
    return clean


def _v373_merge_file_rows(a, b):
    """Merge two manifest rows that are the same file under Windows path identity."""
    a = dict(a or {}); b = dict(b or {})
    out = dict(a)
    # Keep the most descriptive textual metadata.
    for key in ('purpose', 'phase'):
        av = str(out.get(key) or '')
        bv = str(b.get(key) or '')
        if len(bv.strip()) > len(av.strip()):
            out[key] = b.get(key)
    out['required'] = bool(out.get('required', True) or b.get('required', True))
    for key in ('depends_on', 'exports', 'contracts', 'acceptance_criteria', 'requirements'):
        vals = []
        raw = out.get(key) or []
        if isinstance(raw, str): raw = [raw]
        vals.extend(raw)
        raw = b.get(key) or []
        if isinstance(raw, str): raw = [raw]
        vals.extend(raw)
        uniq = []
        seen = set()
        for x in vals:
            text = str(x or '').strip()
            if not text:
                continue
            k = text.casefold() if key == 'depends_on' else text
            if k in seen:
                continue
            seen.add(k); uniq.append(x)
        if uniq:
            out[key] = uniq
    return out


def _v373_canonicalize_manifest_paths(manifest, user_request='', work=None):
    """Normalize one manifest around a single case-aware repository identity.

    On Windows, case aliases are merged before implementation. On case-sensitive target platforms,
    distinct casing remains distinct unless the component root itself declares a canonical spelling.
    """
    if not isinstance(manifest, dict):
        return manifest
    m = manifest
    if user_request and not m.get('_original_user_request'):
        m['_original_user_request'] = str(user_request)
    insensitive = _v373_case_insensitive_paths(m, user_request)

    # Canonicalize component roots first; they anchor all later file identities.
    comps = []
    seen_comp_roots = {}
    for raw in m.get('components') or []:
        if not isinstance(raw, dict):
            continue
        comp = dict(raw)
        root = _v373_clean_rel(comp.get('root') or '.') or '.'
        if insensitive and root != '.':
            first = root.split('/')[0]
            if first.casefold() in {'backend', 'frontend', 'shared', 'server', 'client', 'tests', 'test'}:
                root = '/'.join([first.casefold()] + root.split('/')[1:])
        comp['root'] = root
        key = root.casefold() if insensitive else root
        if key in seen_comp_roots and root != '.':
            # Same filesystem component under another case spelling: merge metadata rather than
            # allowing two logical components to own the same directory.
            old = comps[seen_comp_roots[key]]
            for k in ('purpose', 'toolchain_adapter', 'entrypoint', 'dependency_command', 'build_command', 'test_command', 'run_command'):
                if not old.get(k) and comp.get(k): old[k] = comp[k]
            deps = list(old.get('depends_on') or []) + list(comp.get('depends_on') or [])
            old['depends_on'] = list(dict.fromkeys(str(x) for x in deps if str(x).strip()))
            continue
        seen_comp_roots[key] = len(comps); comps.append(comp)
    if comps:
        m['components'] = comps

    aliases = {}
    rows_by_key = {}
    order = []
    for raw in m.get('files') or []:
        if not isinstance(raw, dict):
            continue
        row = dict(raw)
        original = _v373_clean_rel(row.get('path'))
        if not original:
            continue
        canonical = _v373_apply_component_root_case(m, original)
        key = canonical.casefold() if insensitive else canonical
        aliases[original] = canonical
        aliases[original.casefold()] = canonical
        row['path'] = canonical
        if key not in rows_by_key:
            rows_by_key[key] = row; order.append(key)
        else:
            rows_by_key[key] = _v373_merge_file_rows(rows_by_key[key], row)
            rows_by_key[key]['path'] = canonical

    files = [rows_by_key[k] for k in order]
    canonical_paths = {(_v373_clean_rel(x.get('path')).casefold() if insensitive else _v373_clean_rel(x.get('path'))): _v373_clean_rel(x.get('path')) for x in files}

    def canon_ref(value):
        raw = _v373_clean_rel(value)
        if not raw:
            return ''
        rooted = _v373_apply_component_root_case(m, raw)
        key = rooted.casefold() if insensitive else rooted
        return canonical_paths.get(key, rooted)

    for row in files:
        deps = row.get('depends_on') or []
        if isinstance(deps, str): deps = [deps]
        clean_deps = []
        for dep in deps:
            c = canon_ref(dep)
            if c and c != row['path'] and c not in clean_deps:
                clean_deps.append(c)
        row['depends_on'] = clean_deps
    m['files'] = files

    # Normalize component entrypoints and top-level entrypoint to the same file identity.
    if m.get('entrypoint'):
        m['entrypoint'] = canon_ref(m.get('entrypoint'))
    for comp in m.get('components') or []:
        if comp.get('entrypoint'):
            comp['entrypoint'] = canon_ref(comp.get('entrypoint'))

    # Normalize explicit file-backed acceptance paths where present.
    for test in m.get('acceptance_tests') or []:
        if isinstance(test, dict) and test.get('path'):
            test['path'] = canon_ref(test.get('path'))

    # Windows shell commands should use the canonical component spelling too. This is cosmetic on
    # NTFS but prevents the model/KB from learning two identities from commands and paths.
    if insensitive:
        replacements = _v373_component_root_map(m)
        for obj in [m] + [x for x in m.get('components') or [] if isinstance(x, dict)]:
            for key in ('dependency_command', 'build_command', 'test_command', 'run_command'):
                cmd = str(obj.get(key) or '')
                for low, canonical in replacements.items():
                    cmd = re.sub(r'(?i)(?<![A-Za-z0-9_])' + re.escape(low) + r'(?=[/\\\s&|]|$)', canonical, cmd)
                obj[key] = cmd

    # Persist alias evidence for diagnostics/KB but do not treat this as user source.
    nice_aliases = {}
    for raw, canonical in aliases.items():
        if raw.casefold() == raw and raw in aliases and raw != canonical:
            continue
        if raw != canonical:
            nice_aliases[raw] = canonical
    if nice_aliases:
        existing = dict(m.get('_v373_path_aliases') or {})
        existing.update(nice_aliases)
        m['_v373_path_aliases'] = existing
    m['_v373_case_insensitive_paths'] = bool(insensitive)
    m['_v373_path_identity_version'] = 1
    return m


def _v373_manifest_path_lookup(manifest):
    insensitive = _v373_case_insensitive_paths(manifest)
    lookup = {}
    for row in (manifest or {}).get('files') or []:
        if not isinstance(row, dict): continue
        rel = _v373_apply_component_root_case(manifest, row.get('path'))
        if not rel: continue
        lookup[rel.casefold() if insensitive else rel] = rel
    return lookup


def _v373_canonical_manifest_rel(manifest, rel):
    clean = _v373_apply_component_root_case(manifest, rel)
    lookup = _v373_manifest_path_lookup(manifest)
    key = clean.casefold() if _v373_case_insensitive_paths(manifest) else clean
    return lookup.get(key, clean)


def _v373_load_work_manifest(work):
    p = Path(work) / V33_ARCHITECTURE_FILE
    try:
        obj = json.loads(p.read_text(encoding='utf-8', errors='replace')) if p.exists() else {}
        if isinstance(obj, dict):
            return _v373_canonicalize_manifest_paths(obj, obj.get('_original_user_request') or '', work=None)
    except Exception:
        pass
    return {}


def _v373_source_quality(path, rel=''):
    try:
        text = Path(path).read_text(encoding='utf-8', errors='replace')
    except Exception:
        return (-10, 0, 0)
    intermediate = V33_SKELETON_MARKER in text[:1000] or V34_RECOVERY_SEED_MARKER in text[:1200]
    syntax_ok = not bool(_content_validation_error(rel or Path(path).name, text))
    substantive = bool(text.strip()) and not intermediate
    return (10 if substantive else 0, 5 if syntax_ok else 0, len(text))


def _v373_reconcile_workspace_case_aliases(work, manifest, reason='path_canonicalization'):
    """Merge/rename case aliases in a staging workspace without losing the better candidate."""
    if not _v373_case_insensitive_paths(manifest):
        return []
    root = Path(work)
    lookup = _v373_manifest_path_lookup(manifest)
    groups = {}
    skip_dirs = {'.git', 'node_modules', 'vendor', 'dist', 'build', 'target', '.next', '.nuxt', '.venv', 'venv', 'env', '__pycache__', '.pytest_cache', '.jarvis_backups', '.jarvis_candidates', '.jarvis_failures'}
    try:
        for p in root.rglob('*'):
            if not p.is_file(): continue
            rel = p.relative_to(root).as_posix()
            if any(part in skip_dirs for part in Path(rel).parts): continue
            if Path(rel).name.startswith('JARVIS_') or rel in {PROJECT_STATE_FILE, PROJECT_JOURNAL_FILE, PROJECT_JOURNAL_TEXT_FILE, RESUME_METADATA_FILE}:
                continue
            groups.setdefault(rel.casefold(), []).append((rel, p))
    except Exception:
        return []
    changed = []
    for key, entries in groups.items():
        canonical = lookup.get(key)
        if not canonical:
            # If no manifest path exists, keep the first filesystem spelling; this function's job is
            # to enforce planned repository identity, not rewrite arbitrary user assets.
            continue
        target = root / canonical
        if len(entries) == 1 and entries[0][0] == canonical:
            continue
        # Choose the highest-quality implementation, then normalize it to the manifest spelling.
        winner_rel, winner_path = max(entries, key=lambda rp: _v373_source_quality(rp[1], canonical))
        try:
            content = winner_path.read_bytes()
            target.parent.mkdir(parents=True, exist_ok=True)
            conflict_dir = root / '.jarvis_failures' / 'case_aliases'
            for rel, p in entries:
                if p == winner_path and p == target:
                    continue
                if p.exists():
                    conflict_dir.mkdir(parents=True, exist_ok=True)
                    safe = re.sub(r'[^A-Za-z0-9_.-]+', '__', rel)
                    backup = conflict_dir / f'{datetime.now().strftime("%Y%m%d_%H%M%S_%f")}_{safe}'
                    try: shutil.copy2(p, backup)
                    except Exception: pass
            target.write_bytes(content)
            for rel, p in entries:
                if p != target and p.exists():
                    try: p.unlink()
                    except Exception: pass
            changed.append({'aliases': [x[0] for x in entries], 'canonical': canonical, 'winner': winner_rel})
        except Exception:
            continue
    if changed:
        try:
            _append_project_event(work, 'v373_case_aliases_reconciled', f'Canonicalized {len(changed)} case-insensitive project path collision(s).', reason=reason, collisions=changed[:30])
        except Exception:
            pass
    return changed


def _v373_kb_path(work):
    return Path(work) / V373_PROJECT_KB_FILE


def _v373_json_read(path, default=None):
    try:
        obj = json.loads(Path(path).read_text(encoding='utf-8', errors='replace'))
        return obj
    except Exception:
        return {} if default is None else default


def _v373_atomic_json_write(path, obj):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + '.tmp')
    tmp.write_text(json.dumps(obj, indent=2, ensure_ascii=False), encoding='utf-8')
    os.replace(str(tmp), str(path))


def _v373_kb_token(work, manifest):
    h = hashlib.sha256()
    try:
        h.update(json.dumps({
            'files': [{'path': x.get('path'), 'depends_on': x.get('depends_on'), 'exports': x.get('exports'), 'contracts': x.get('contracts')} for x in (manifest or {}).get('files') or [] if isinstance(x, dict)],
            'components': manifest.get('components') or [],
            'platform': manifest.get('platform'),
        }, sort_keys=True, ensure_ascii=False).encode('utf-8'))
    except Exception:
        pass
    for rel, p in _v36_project_source_files(work, manifest):
        try:
            st = p.stat(); h.update(rel.encode('utf-8')); h.update(str(st.st_size).encode()); h.update(str(st.st_mtime_ns).encode())
        except Exception:
            pass
    return h.hexdigest()[:32]


def _v373_snake(name):
    text = re.sub(r'(?<!^)(?=[A-Z])', '_', str(name or '')).lower()
    return re.sub(r'[^a-z0-9_]+', '_', text).strip('_')


def _v373_choose_canonical_provider(symbol, providers, previous, graph):
    providers = list(dict.fromkeys(providers))
    if not providers:
        return ''
    old = str(((previous or {}).get(symbol) or {}).get('provider') or '')
    if old in providers:
        return old
    if len(providers) == 1:
        return providers[0]
    base_symbol = symbol.split('.', 1)[0]
    snake = _v373_snake(base_symbol)
    scored = []
    for p in providers:
        stem = Path(p).stem.lower()
        score = 0.0
        if stem == snake or stem == base_symbol.lower(): score += 8
        # Shared enum/value objects conventionally belong in a shared base/types/enums module;
        # prefer that stable owner over per-entity copies when the symbol itself is shared.
        if base_symbol.lower().endswith('enum') and stem in {'base', 'core', 'enums', 'types', 'constants'}: score += 9
        if '/models/' in ('/' + p.lower()) and '.' not in symbol: score += 1
        info = (graph.get('files') or {}).get(p) or {}
        score += float(info.get('rank') or 0) * 100.0
        # Prefer narrower domain owner over generic base/core when symbol name itself identifies it.
        if stem in {'base', 'core', '__init__'} and snake not in {'base', 'core'}: score -= 2
        scored.append((score, p))
    scored.sort(reverse=True)
    if scored and (len(scored) == 1 or scored[0][0] >= scored[1][0] + 2.0):
        return scored[0][1]
    return ''


def _v373_refresh_project_kb(work, manifest=None, reason='refresh', force=False):
    root = Path(work)
    manifest = _v373_canonicalize_manifest_paths(manifest or _v373_load_work_manifest(root), (manifest or {}).get('_original_user_request') if isinstance(manifest, dict) else '', work=None) or {}
    if manifest:
        _v373_reconcile_workspace_case_aliases(root, manifest, reason=reason)
    token = _v373_kb_token(root, manifest)
    kb_path = _v373_kb_path(root)
    previous = _v373_json_read(kb_path, {}) if kb_path.exists() else {}
    if not force and isinstance(previous, dict) and previous.get('source_token') == token:
        return previous

    # The graph/registry are machine-derived memory sources. They now see canonical file identities
    # through the V37.3 source-file/path wrappers below.
    try: graph = _v36_build_repo_graph(root, manifest, write=True)
    except Exception: graph = _v373_json_read(root / V36_REPO_GRAPH_FILE, {})
    try: registry = _v36_build_contract_registry(root, manifest, write=True)
    except Exception: registry = _v373_json_read(root / V36_CONTRACT_REGISTRY_FILE, {})
    try: reqs = _v373_json_read(root / V36_REQUIREMENTS_FILE, {})
    except Exception: reqs = {}
    build = _v373_json_read(root / V33_BUILD_STATUS_FILE, {})
    state = _load_project_state(root)
    agent = _v37_agent_state_load(root)
    subsystem = _v381_load_repair_state(root) if '_v381_load_repair_state' in globals() else {}

    files = {}
    manifest_items = {}
    for row in manifest.get('files') or []:
        if not isinstance(row, dict): continue
        rel = _v373_canonical_manifest_rel(manifest, row.get('path'))
        manifest_items[rel] = row
    graph_files = graph.get('files') or {}
    for rel, row in manifest_items.items():
        p = root / rel
        status = 'missing'
        sha = ''
        size = 0
        if p.exists() and p.is_file():
            try:
                text = p.read_text(encoding='utf-8', errors='replace'); size = len(text.encode('utf-8', errors='replace'))
                sha = hashlib.sha256(text.encode('utf-8', errors='replace')).hexdigest()[:20]
                status = 'skeleton' if (V33_SKELETON_MARKER in text[:1000] or V34_RECOVERY_SEED_MARKER in text[:1200]) else 'implemented'
            except Exception:
                status = 'present'
        info = graph_files.get(rel) or {}
        files[rel] = {
            'path': rel, 'status': status, 'size': size, 'sha256': sha,
            'purpose': str(row.get('purpose') or ''), 'phase': str(row.get('phase') or ''),
            'depends_on': [_v373_canonical_manifest_rel(manifest, x) for x in (row.get('depends_on') or [])],
            'exports': [str(x) for x in (row.get('exports') or [])],
            'contracts': [str(x) for x in (row.get('contracts') or [])],
            'rank': float(info.get('rank') or 0),
            'imports': list(info.get('imports') or [])[:80],
            'edges': list(info.get('edges') or [])[:80],
            'symbols': list(info.get('symbols') or [])[:120],
        }

    # Include materialized source that is not yet in the manifest as unplanned evidence rather than
    # letting Qwen silently treat it as another authoritative provider.
    for rel, p in _v36_project_source_files(root, manifest):
        if rel in files: continue
        info = graph_files.get(rel) or {}
        files[rel] = {'path': rel, 'status': 'unplanned_source', 'purpose': '', 'phase': '', 'depends_on': [], 'exports': [], 'contracts': [], 'rank': float(info.get('rank') or 0), 'imports': list(info.get('imports') or [])[:80], 'edges': list(info.get('edges') or [])[:80], 'symbols': list(info.get('symbols') or [])[:120]}

    # Canonical contract memory. Same-file case aliases are already collapsed. Real multi-provider
    # conflicts remain visible and cannot be silently reinterpreted by Qwen.
    groups = {}
    for row in (registry.get('contracts') or [])[:V373_KB_MAX_CONTRACTS]:
        if not isinstance(row, dict): continue
        symbol = str(row.get('symbol') or '').strip()
        provider = _v373_canonical_manifest_rel(manifest, row.get('provider'))
        if not symbol or not provider: continue
        item = dict(row); item['provider'] = provider
        groups.setdefault(symbol, []).append(item)
    previous_canonical = dict(previous.get('canonical_symbols') or {}) if isinstance(previous, dict) else {}
    canonical_symbols = {}
    provider_conflicts = []
    for symbol, rows in groups.items():
        providers = list(dict.fromkeys(str(x.get('provider') or '') for x in rows if x.get('provider')))
        chosen = _v373_choose_canonical_provider(symbol, providers, previous_canonical, graph)
        selected_rows = [x for x in rows if not chosen or x.get('provider') == chosen]
        # AST signature wins over manifest prose for the chosen provider.
        selected_rows.sort(key=lambda x: (0 if x.get('source') == 'ast' else 1, -len(str(x.get('signature') or ''))))
        best = selected_rows[0] if selected_rows else rows[0]
        canonical_symbols[symbol] = {
            'provider': chosen,
            'signature': str(best.get('signature') or symbol),
            'source': str(best.get('source') or ''),
            'providers': providers,
            'conflict': len(providers) > 1,
        }
        if len(providers) > 1:
            provider_conflicts.append({'symbol': symbol, 'canonical_provider': chosen, 'providers': providers})

    latest_green = ''
    try:
        greens = sorted((root / '.jarvis_backups' / 'v36_checkpoints' / 'green').glob('*.zip'), key=lambda p: p.stat().st_mtime, reverse=True)
        latest_green = greens[0].name if greens else ''
    except Exception:
        pass

    revision = int(previous.get('revision') or 0) + 1 if isinstance(previous, dict) else 1
    kb = {
        'schema_version': 1, 'version': 'V37.3.0', 'engine': 'PERSISTENT_PROJECT_KNOWLEDGE_BASE',
        'generated_at': _utc_stamp(), 'revision': revision, 'source_token': token,
        'project': {
            'name': str(manifest.get('project_name') or root.name), 'summary': str(manifest.get('summary') or ''),
            'platform': str(manifest.get('platform') or ''), 'project_type': str(manifest.get('project_type') or ''),
            'case_insensitive_paths': _v373_case_insensitive_paths(manifest),
            'components': manifest.get('components') or [], 'entrypoint': str(manifest.get('entrypoint') or ''),
        },
        'path_aliases': dict(manifest.get('_v373_path_aliases') or {}),
        'files': files,
        'canonical_symbols': canonical_symbols,
        'provider_conflicts': provider_conflicts[:300],
        'requirements': list((reqs or {}).get('source_requirements') or [])[:300],
        'acceptance_criteria': list((reqs or {}).get('acceptance_criteria') or manifest.get('acceptance_criteria') or [])[:300],
        'validation_state': {'build_status': build, 'project_state': state.get('last_verification') or {}, 'stage': build.get('stage') or state.get('stage') or ''},
        'repair_memory': {
            'patch_history': dict((agent.get('patch_history') or {})),
            'subsystems': dict((subsystem.get('subsystems') or {})),
            'files': dict((subsystem.get('files') or {})),
        },
        'green_checkpoint': latest_green,
        'recent_events': _recent_project_events(root, V373_KB_MAX_EVENTS),
        'rules': [
            'Canonical path identity is authoritative. On Windows, path casing does not create another file.',
            'Do not create a second provider for a canonical public symbol. If a provider conflict is listed, repair/reconcile the provider before changing consumers.',
            'Exact AST signatures in canonical_symbols override remembered/guessed signatures.',
            'Existing green contracts may only change through a validated provider-first transaction; consumers must follow the canonical provider.',
        ],
    }
    try: _v373_atomic_json_write(kb_path, kb)
    except Exception: pass
    return kb


def _v373_kb_context(work, manifest, current_path='', max_chars=None):
    max_chars = int(max_chars or V373_KB_CONTEXT_CHARS)
    kb = _v373_refresh_project_kb(work, manifest, reason='context')
    if not kb:
        return ''
    current = _v373_canonical_manifest_rel(manifest, current_path)
    files = kb.get('files') or {}
    current_info = files.get(current) or {}
    related = {current}
    related.update(str(x) for x in current_info.get('depends_on') or [])
    for edge in current_info.get('edges') or []:
        if edge.get('to'): related.add(str(edge.get('to')))
    for rel, info in files.items():
        if current and current in (info.get('depends_on') or []): related.add(rel)
        if any(str(e.get('to') or '') == current for e in info.get('edges') or []): related.add(rel)

    out = [
        'V37.3 PERSISTENT PROJECT KNOWLEDGE BASE (JARVIS-OWNED, AUTHORITATIVE):',
        'Use this memory instead of guessing or redefining project APIs. Path aliases/casing are NOT separate files.',
        f"Project={kb.get('project',{}).get('name','')} platform={kb.get('project',{}).get('platform','')} revision={kb.get('revision',0)} target={current or '(none)'}",
    ]
    aliases = kb.get('path_aliases') or {}
    if aliases:
        out.append('CANONICAL PATH ALIASES:')
        for a, c in list(aliases.items())[:30]: out.append(f'- {a} => {c}')

    out.append('FULL PROJECT FILE INDEX (compact memory; this is the authoritative repository plan/state):')
    used_index = 0
    for rel, info in sorted(files.items(), key=lambda kv: kv[0].casefold()):
        line = f"- {rel} [{info.get('status')}/{info.get('phase')}] :: {str(info.get('purpose') or '')[:120]}"
        if used_index + len(line) > V373_KB_FULL_INDEX_CHARS: break
        out.append(line); used_index += len(line)

    if related:
        out.append('TARGET DEPENDENCY/CONSUMER MEMORY:')
        for rel in sorted(x for x in related if x in files):
            info = files[rel]
            out.append(f"- {rel}: depends_on={info.get('depends_on') or []}; exports={info.get('exports') or []}")

    # Include canonical symbols owned by or directly relevant to the target cluster. Always include
    # real conflicts so the model cannot accidentally choose a different definition.
    canon = kb.get('canonical_symbols') or {}
    rows = []
    for symbol, info in canon.items():
        providers = info.get('providers') or []
        if info.get('conflict') or any(p in related for p in providers):
            rows.append((0 if info.get('conflict') else 1, symbol, info))
    if rows:
        out.append('CANONICAL SYMBOL/SIGNATURE MEMORY:')
        for _, symbol, info in sorted(rows)[:160]:
            provider = info.get('provider') or 'UNRESOLVED-CONFLICT'
            suffix = f" CONFLICT providers={info.get('providers')}" if info.get('conflict') else ''
            out.append(f"- {symbol} -> {provider} :: {info.get('signature')}{suffix}")

    patch_hist = ((kb.get('repair_memory') or {}).get('patch_history') or {}).get(current) or []
    if patch_hist:
        out.append('FAILED/RECENT STRATEGY MEMORY FOR TARGET:')
        for row in patch_hist[-6:]: out.append(f"- {row.get('fingerprint')}: {str(row.get('error') or '')[:500]}")
    if kb.get('green_checkpoint'):
        out.append(f"LAST GREEN CHECKPOINT: {kb.get('green_checkpoint')}")
    out.append('MANDATORY: Match canonical providers/signatures above. If memory shows a provider conflict, do not invent a third definition; reconcile the provider layer first.')
    text = '\n'.join(out)
    return text[:max_chars]


# ---- Late-bound wrappers: make every downstream subsystem use canonical path identity. ----
_v373_base_manifest_file_item = _manifest_file_item

def _manifest_file_item(manifest, rel):
    target = _v373_canonical_manifest_rel(manifest or {}, rel)
    insensitive = _v373_case_insensitive_paths(manifest or {})
    key = target.casefold() if insensitive else target
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item, dict): continue
        p = _v373_apply_component_root_case(manifest or {}, item.get('path'))
        if (p.casefold() if insensitive else p) == key:
            return item
    return {}


_v373_base_v37_manifest_paths = _v37_manifest_paths

def _v37_manifest_paths(manifest):
    # IMPORTANT: this is a read-only lookup helper. Dependency normalization iterates the live
    # manifest list and calls this function for each dependency; replacing manifest['files'] here
    # would detach the item currently being normalized. Canonicalize identities without mutating.
    out = set()
    for x in (manifest or {}).get('files') or []:
        if not isinstance(x, dict) or not x.get('path'):
            continue
        out.add(_v373_apply_component_root_case(manifest or {}, x.get('path')))
    return out


_v373_base_v37_component_root = _v37_component_root_for_owner

def _v37_component_root_for_owner(manifest, owner_path):
    owner = _v373_canonical_manifest_rel(manifest or {}, owner_path)
    best = '.'
    for comp in (manifest or {}).get('components') or []:
        root = _v373_apply_component_root_case(manifest or {}, comp.get('root') or '.') or '.'
        if root != '.' and (owner == root or owner.startswith(root + '/')):
            if best == '.' or len(root) > len(best): best = root
    return best


_v373_base_v37_export_index = _v37_export_index

def _v37_export_index(manifest):
    idx = {}
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item, dict): continue
        path = _v373_canonical_manifest_rel(manifest or {}, item.get('path'))
        for raw in item.get('exports') or []:
            text = str(raw or '').strip()
            for sym in re.findall(r'\b[A-Za-z_][A-Za-z0-9_]*\b', text):
                arr = idx.setdefault(sym.lower(), [])
                if path not in arr: arr.append(path)
    return idx


_v373_base_project_source_files = _v36_project_source_files

def _v36_project_source_files(work, manifest=None):
    m = _v373_canonicalize_manifest_paths(manifest or {}, (manifest or {}).get('_original_user_request') or '') if isinstance(manifest, dict) else (manifest or {})
    try:
        if m: _v373_reconcile_workspace_case_aliases(work, m, reason='source_scan')
    except Exception: pass
    raw = _v373_base_project_source_files(work, m)
    insensitive = _v373_case_insensitive_paths(m)
    chosen = {}
    for rel, p in raw:
        canonical = _v373_canonical_manifest_rel(m, rel) if m else _v373_clean_rel(rel)
        key = canonical.casefold() if insensitive else canonical
        cur = chosen.get(key)
        if cur is None or _v373_source_quality(p, canonical) > _v373_source_quality(cur[1], canonical):
            chosen[key] = (canonical, p)
    return list(chosen.values())


_v373_base_candidate_draft_path = _candidate_draft_path

def _candidate_draft_path(work, rel):
    manifest = _v373_load_work_manifest(work)
    canonical = _v373_canonical_manifest_rel(manifest, rel) if manifest else _v373_clean_rel(rel)
    safe = _safe_relative(canonical)
    return Path(work) / CANDIDATE_DIR_NAME / (safe.as_posix() + '.candidate')


_v373_base_normalize_component_files = _v362_normalize_component_files

def _v362_normalize_component_files(obj, component, max_files):
    rows = _v373_base_normalize_component_files(obj, component, max_files)
    temp = {'platform': 'windows' if os.name == 'nt' else '', 'components': [dict(component or {})], 'files': rows}
    return _v373_canonicalize_manifest_paths(temp).get('files') or []


_v373_base_merge_manifest = _merge_manifest

def _merge_manifest(base, reviewed, user_request, max_files):
    result = _v373_base_merge_manifest(base, reviewed, user_request, max_files)
    return _v373_canonicalize_manifest_paths(result, user_request)


_v373_base_hierarchical_manifest = _v362_build_hierarchical_manifest

def _v362_build_hierarchical_manifest(user_request, spec, max_files, progress_callback=None):
    manifest, raw = _v373_base_hierarchical_manifest(user_request, spec, max_files, progress_callback)
    if isinstance(manifest, dict):
        manifest = _v373_canonicalize_manifest_paths(manifest, user_request)
        # Case aliases must be collapsed before the final completeness/collision gate. Re-run the
        # deterministic checks on the normalized graph so 72 logical paths cannot hide 52 files.
        issues = _v362_manifest_completeness_issues(manifest, spec, user_request, max_files)
        collisions = _v351_architecture_collision_issues(manifest)
        if issues or collisions:
            detail = []
            if issues: detail.extend(issues)
            if collisions: detail.extend(str(x) for x in collisions[:30])
            manifest['_v373_postcanonical_issues'] = detail
            return None, str(raw or '') + '\nV37.3 POST-CANONICAL ARCHITECTURE GATE:\n' + '\n'.join(detail)
    return manifest, raw


_v373_base_execute_manifest = _v362_execute_manifest

def _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback=None, raw_plan=''):
    manifest = _v373_canonicalize_manifest_paths(dict(manifest or {}), user_request, work)
    _v373_reconcile_workspace_case_aliases(work, manifest, reason='before_implementation')
    _v373_refresh_project_kb(work, manifest, reason='architecture_committed', force=True)
    return _v373_base_execute_manifest(user_request, manifest, work, max_files, progress_callback, raw_plan)


_v373_base_write_architecture = _v33_write_architecture

def _v33_write_architecture(work, manifest):
    manifest = _v373_canonicalize_manifest_paths(manifest or {}, (manifest or {}).get('_original_user_request') or '', work)
    _v373_base_write_architecture(work, manifest)
    try:
        _v373_reconcile_workspace_case_aliases(work, manifest, reason='architecture_write')
        _v373_refresh_project_kb(work, manifest, reason='architecture_write', force=True)
        p = Path(work) / V33_ARCHITECTURE_FILE
        data = _v373_json_read(p, {})
        if isinstance(data, dict):
            data.update({'version': 'V37.3.0', 'persistent_project_kb': True, 'project_kb_file': V373_PROJECT_KB_FILE, 'windows_case_canonicalization': True, 'canonical_contract_memory': True})
            _v373_atomic_json_write(p, data)
    except Exception:
        pass


_v373_base_write_build_status = _v33_write_build_status

def _v33_write_build_status(work, manifest, stage, current_file='', implemented=None):
    manifest = _v373_canonicalize_manifest_paths(manifest or {}, (manifest or {}).get('_original_user_request') or '')
    current_file = _v373_canonical_manifest_rel(manifest, current_file) if current_file else ''
    _v373_base_write_build_status(work, manifest, stage, current_file=current_file, implemented=implemented)
    try:
        p = Path(work) / V33_BUILD_STATUS_FILE
        data = _v373_json_read(p, {})
        if isinstance(data, dict):
            data.update({'version': 'V37.3.0', 'engine': 'SMALL_MODEL_SOFTWARE_FACTORY', 'persistent_project_kb': True, 'windows_case_canonicalization': True, 'project_kb_revision': int((_v373_json_read(_v373_kb_path(work), {}) or {}).get('revision') or 0)})
            _v373_atomic_json_write(p, data)
    except Exception:
        pass


_v373_base_project_context_for_file = _project_context_for_file

def _project_context_for_file(work, manifest, current_path, max_chars=None):
    manifest = _v373_canonicalize_manifest_paths(manifest or {}, (manifest or {}).get('_original_user_request') or '')
    current = _v373_canonical_manifest_rel(manifest, current_path)
    total_budget = int(max_chars or max(22000, V36_RELATED_FULL_CONTEXT_CHARS + V373_KB_CONTEXT_CHARS))
    kb_budget = min(V373_KB_CONTEXT_CHARS, max(5000, int(total_budget * 0.45)))
    base_budget = max(5000, total_budget - kb_budget - 4)
    kb = _v373_kb_context(work, manifest, current, kb_budget)
    base = _v373_base_project_context_for_file(work, manifest, current, base_budget)
    if not kb:
        return base[:total_budget]
    # Keep the authoritative memory first, but honor the caller's context budget so adding persistent
    # memory improves consistency without undoing V37's small-model bounded-context strategy.
    return (kb[:kb_budget] + '\n\n' + base[:base_budget])[:total_budget]


_v373_base_repo_map_context = _v36_repo_map_context

def _v36_repo_map_context(work, manifest, current_path='', max_chars=None):
    manifest = _v373_canonicalize_manifest_paths(manifest or {}, (manifest or {}).get('_original_user_request') or '')
    current = _v373_canonical_manifest_rel(manifest, current_path)
    base = _v373_base_repo_map_context(work, manifest, current, max_chars)
    # Keep this addition compact because repair prompts already include the contract context too.
    kb = _v373_kb_context(work, manifest, current, min(6500, V373_KB_CONTEXT_CHARS))
    return base + ('\n\n' + kb if kb else '')


_v373_base_contract_context = _v36_contract_context

def _v36_contract_context(work, manifest, current_path='', max_chars=8000):
    manifest = _v373_canonicalize_manifest_paths(manifest or {}, (manifest or {}).get('_original_user_request') or '')
    current = _v373_canonical_manifest_rel(manifest, current_path)
    base = _v373_base_contract_context(work, manifest, current, max_chars)
    kb = _v373_refresh_project_kb(work, manifest, reason='contract_context')
    lines = ['V37.3 CANONICAL CONTRACT MEMORY (persistent across Qwen calls):']
    related = {current}
    info = (kb.get('files') or {}).get(current) or {}
    related.update(info.get('depends_on') or [])
    for symbol, row in (kb.get('canonical_symbols') or {}).items():
        providers = row.get('providers') or []
        if row.get('conflict') or any(p in related for p in providers):
            owner = row.get('provider') or 'UNRESOLVED-CONFLICT'
            extra = f" [CONFLICT: {providers}]" if row.get('conflict') else ''
            lines.append(f"- {symbol}: {row.get('signature')} owner={owner}{extra}")
        if sum(len(x) + 1 for x in lines) > 4500: break
    return base + '\n\n' + '\n'.join(lines)


_v373_base_generate_planned_file = _generate_planned_file

def _generate_planned_file(user_request, manifest, work, file_item, progress_callback=None):
    manifest = _v373_canonicalize_manifest_paths(manifest or {}, user_request)
    item = dict(file_item or {})
    item['path'] = _v373_canonical_manifest_rel(manifest, item.get('path'))
    item['depends_on'] = [_v373_canonical_manifest_rel(manifest, x) for x in (item.get('depends_on') or [])]
    _v373_reconcile_workspace_case_aliases(work, manifest, reason='before_file_generation')
    _v373_refresh_project_kb(work, manifest, reason='before_file_generation')
    ok, wrote = _v373_base_generate_planned_file(user_request, manifest, work, item, progress_callback)
    if ok:
        _v373_reconcile_workspace_case_aliases(work, manifest, reason='after_file_generation')
        _v373_refresh_project_kb(work, manifest, reason='file_committed', force=True)
    return ok, _v373_canonical_manifest_rel(manifest, wrote) if wrote else wrote


_v373_base_repair_file_for_issues = _repair_file_for_issues

def _repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback=None, validation_failure=None):
    manifest = _v373_canonicalize_manifest_paths(manifest or {}, user_request)
    rel = _v373_canonical_manifest_rel(manifest, rel)
    _v373_reconcile_workspace_case_aliases(work, manifest, reason='before_repair')
    _v373_refresh_project_kb(work, manifest, reason='before_repair')
    result = _v373_base_repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback, validation_failure)
    if result:
        _v373_reconcile_workspace_case_aliases(work, manifest, reason='after_repair')
        _v373_refresh_project_kb(work, manifest, reason='repair_committed', force=True)
    return result


def _v373_kb_provider_conflict_issues(work, manifest):
    """Turn dangerous same-component public class conflicts from memory into repair evidence.

    We intentionally restrict this to class-like public symbols. Functions with common names may
    legitimately repeat across modules, and frontend/backend representations may intentionally share
    a domain name. Within one component, multiple Project/Task/*Service/*Repository/*Enum providers
    are almost always the exact contract drift this patch is meant to prevent.
    """
    kb = _v373_refresh_project_kb(work, manifest, reason='provider_conflict_scan')
    out = []
    for row in kb.get('provider_conflicts') or []:
        symbol = str(row.get('symbol') or '')
        if not symbol or '.' in symbol or not symbol[:1].isupper():
            continue
        providers = [str(x) for x in row.get('providers') or [] if str(x)]
        providers = [p for p in providers if '/tests/' not in ('/' + p.lower()) and not Path(p).name.lower().startswith('test_')]
        if len(providers) < 2:
            continue
        roots = {_v37_component_root_for_owner(manifest, p) for p in providers}
        if len(roots) != 1:
            continue
        canonical = str(row.get('canonical_provider') or '')
        if not canonical:
            canonical = str((kb.get('canonical_symbols') or {}).get(symbol, {}).get('provider') or '')
        # Do not invent a canonical owner when the KB cannot choose with evidence; still surface the
        # conflict so subsystem reconciliation can choose one transactionally.
        targets = [p for p in providers if not canonical or p != canonical]
        if not targets:
            targets = providers[:1]
        for provider in targets:
            problem = (
                f"V37.3 persistent contract memory: public symbol {symbol!r} has competing providers {providers} "
                + (f"and canonical project memory currently owns it at {canonical!r}. " if canonical else "with no safely resolved owner yet. ")
                + "Do not add another definition. Reconcile the provider layer first, then align repositories/services/APIs/tests to that one contract."
            )
            out.append({'file': provider, 'provider_file': canonical or provider, 'kind': 'duplicate_provider', 'symbol': symbol, 'problem': problem})
    return out


# Add exact deterministic checks for the missing enum imports seen in the live TaskForge run. These
# are foundation errors; they should be repaired before services/tests pile on top of the models.
_v373_base_deterministic_acceptance_issues = _deterministic_acceptance_issues

def _v373_missing_enum_import_issues(work, manifest):
    issues = []
    for rel, p in _v36_project_source_files(work, manifest):
        if Path(rel).suffix.lower() not in {'.py', '.pyw'}: continue
        try:
            text = p.read_text(encoding='utf-8', errors='replace'); tree = ast.parse(text)
        except Exception:
            continue
        imported_enum = False; imported_enum_module = False
        for node in tree.body:
            if isinstance(node, ast.ImportFrom) and node.module == 'enum':
                if any(alias.name == 'Enum' for alias in node.names): imported_enum = True
            elif isinstance(node, ast.Import):
                if any(alias.name == 'enum' for alias in node.names): imported_enum_module = True
        for node in tree.body:
            if not isinstance(node, ast.ClassDef): continue
            for base in node.bases:
                if isinstance(base, ast.Name) and base.id == 'Enum' and not imported_enum:
                    issues.append({'file': rel, 'kind': 'missing_import', 'line': getattr(node, 'lineno', 0), 'problem': "Python model uses Enum as a class base but does not import 'Enum' from the enum module."})
                elif isinstance(base, ast.Attribute) and base.attr == 'Enum' and isinstance(base.value, ast.Name) and base.value.id == 'enum' and not imported_enum_module:
                    issues.append({'file': rel, 'kind': 'missing_import', 'line': getattr(node, 'lineno', 0), 'problem': "Python model uses enum.Enum but does not import the enum module."})
    return issues


def _deterministic_acceptance_issues(work, manifest):
    manifest = _v373_canonicalize_manifest_paths(manifest or {}, (manifest or {}).get('_original_user_request') or '')
    issues = list(_v373_base_deterministic_acceptance_issues(work, manifest) or [])
    seen = {(str(x.get('file') or '').casefold(), _v381_normalized_problem(x.get('problem') or '')) for x in issues}
    for item in _v373_missing_enum_import_issues(work, manifest) + _v373_kb_provider_conflict_issues(work, manifest):
        key = (str(item.get('file') or '').casefold(), _v381_normalized_problem(item.get('problem') or ''))
        if key not in seen:
            issues.append(item); seen.add(key)
    return issues


# Make release/status diagnostics explicit so the UI can distinguish the persistent-memory patch.
_v373_base_release_identity = _v36_release_identity

def _v36_release_identity():
    data = dict(_v373_base_release_identity() or {})
    data.update({
        'version': 'V37.3.0', 'engine': 'SMALL_MODEL_SOFTWARE_FACTORY',
        'persistent_project_kb': True, 'project_kb_file': V373_PROJECT_KB_FILE,
        'canonical_path_identity': True, 'windows_case_canonicalization': True,
        'canonical_contract_memory': True, 'provider_conflict_memory': True,
        'read_before_edit': True, 'subsystem_reconciliation': True,
    })
    return data


# Final user ZIP must never include Jarvis's persistent memory/diagnostic internals.
_v373_base_package_workspace_zip = _package_workspace_zip

def _package_workspace_zip(work, name_stem, stamp=None):
    # Base packager already excludes most JARVIS_* diagnostics; temporarily moving the KB is safer
    # than relying on its internal name set because older packagers may not know the new filename.
    root = Path(work); kb = root / V373_PROJECT_KB_FILE; temp = None
    if kb.exists():
        try:
            temp = root / '.jarvis_build' / V373_PROJECT_KB_FILE
            temp.parent.mkdir(parents=True, exist_ok=True); shutil.copy2(kb, temp); kb.unlink()
        except Exception:
            temp = None
    try:
        return _v373_base_package_workspace_zip(work, name_stem, stamp)
    finally:
        if temp and temp.exists():
            try: shutil.copy2(temp, kb); temp.unlink()
            except Exception: pass

# =============================================================================
# V38.0 SMALL-MODEL CONVERGENCE + PROJECT MEMORY CONTROL LOOP
# =============================================================================
# Research-driven hardening based on Aider's surgical edit recovery, SWE-agent's
# edit-time validation / small file windows, and little-coder's runtime-enforced
# Read-before-Edit, bounded reasoning, state-aware loop prevention, micro-skills,
# and read-only diagnostic roles. Jarvis remains the authoritative owner of the
# project state; Qwen receives only a bounded, revision-pinned task view.

V38_VERSION = 'V38.0.0'
V38_COMPONENT_SCOPED_EXPORTS = True
V38_TOOLCHAIN_COHERENCE = True
V38_REVISION_BOUND_EDITS = True
V38_STATE_AWARE_LOOP_GUARD = True
V38_MICRO_SKILLS = True
V38_READONLY_SUBAGENTS = os.getenv('JARVIS_V38_READONLY_SUBAGENTS', '1').strip().lower() not in {'0','false','no','off'}
V38_LOOP_SAME_STATE_LIMIT = max(2, min(6, int(os.getenv('JARVIS_V38_SAME_STATE_LOOP_LIMIT', '3'))))
V38_REPAIR_OUTPUT_TOKENS = max(1200, min(4096, int(os.getenv('JARVIS_V38_REPAIR_OUTPUT_TOKENS', '2800'))))
V38_REASONING_TOKEN_BUDGET = max(700, min(3000, int(os.getenv('JARVIS_V38_REASONING_TOKEN_BUDGET', '1800'))))
V38_MICRO_SKILL_CHARS = max(500, min(4000, int(os.getenv('JARVIS_V38_MICRO_SKILL_CHARS', '1800'))))
V38_READ_RECEIPTS_KEY = 'v38_read_receipts'
V38_REPAIR_REQUESTS_KEY = 'v38_repair_requests'


def _v38_component_for_path(manifest, rel):
    rel = str(rel or '').replace('\\','/').strip('/')
    best = None
    best_len = -1
    for comp in _v35_sanitize_components((manifest or {}).get('components')):
        root = str(comp.get('root') or '.').replace('\\','/').strip('/') or '.'
        if root == '.' or rel == root or rel.startswith(root.rstrip('/') + '/'):
            score = 0 if root == '.' else len(root.split('/'))
            if score > best_len:
                best = comp; best_len = score
    return best or {}


def _v38_component_scope(manifest, rel):
    comp = _v38_component_for_path(manifest, rel)
    return str(comp.get('id') or comp.get('root') or '.').strip() or '.'


def _v38_is_testish(rel):
    low = ('/' + str(rel or '').replace('\\','/').lower().strip('/') + '/')
    name = Path(str(rel or '')).name.lower()
    return '/tests/' in low or '/test/' in low or name.startswith('test_') or any(x in name for x in ('.test.','.spec.'))


# ---- Component-scoped symbol ownership --------------------------------------
# Public names are only globally exclusive inside the same component. A React
# vitest_config and a different component's vitest_config are ordinary local
# configuration symbols, not competing project-wide providers.
_v38_prev_architecture_collision_issues = _v351_architecture_collision_issues

def _v351_architecture_collision_issues(manifest):
    files = [x for x in (manifest or {}).get('files') or [] if isinstance(x, dict)]
    strong_suffixes = (
        'Service','Manager','Repository','Controller','Gateway','Client','Store','Engine',
        'Coordinator','Orchestrator','Database','Registry','Provider','ViewModel'
    )
    groups = {}
    for item in files:
        path = str(item.get('path') or '').replace('\\','/').strip('/')
        if not path or Path(path).name.lower() == '__init__.py' or _v38_is_testish(path):
            continue
        scope = _v38_component_scope(manifest, path)
        purpose = str(item.get('purpose') or '')
        words = _v351_meaningful_words(purpose)
        for symbol in _normalize_export_contract(item.get('exports')):
            symbol = str(symbol or '').strip()
            if not symbol or symbol.startswith('_'):
                continue
            groups.setdefault((scope, symbol), []).append((path, purpose, words))

    issues = []
    for (scope, symbol), rows in sorted(groups.items()):
        unique = []
        seen = set()
        for path, purpose, words in rows:
            key = path.casefold() if os.name == 'nt' else path
            if key in seen: continue
            seen.add(key); unique.append((path, purpose, words))
        if len(unique) < 2:
            continue
        strong = symbol.endswith(strong_suffixes)
        overlap = False
        for i in range(len(unique)):
            for j in range(i + 1, len(unique)):
                a, b = unique[i][2], unique[j][2]
                if a and b and len(a & b) / max(1, min(len(a), len(b))) >= 0.5:
                    overlap = True
        if strong or overlap:
            issues.append({
                'scope': scope,
                'symbol': symbol,
                'files': [x[0] for x in unique],
                'problem': (
                    f'DUPLICATE AUTHORITATIVE PROVIDER inside component {scope!r}: export {symbol!r} '
                    f'is owned by multiple planned files: ' + ', '.join(x[0] for x in unique)
                    + '. Choose one canonical provider inside this component or explicitly rename/split responsibilities.'
                ),
            })
    return issues


# ---- Component/toolchain coherence -----------------------------------------
def _v38_component_adapter_blob(comp):
    return ' '.join(str(comp.get(k) or '') for k in (
        'toolchain_adapter','language','framework','build_system','purpose','dependency_command','build_command','test_command','run_command'
    )).lower()


def _v38_component_is_python_only(comp, owned_rows):
    blob = _v38_component_adapter_blob(comp)
    says_python = any(x in blob for x in ('python','fastapi','flask','django','pytest','uvicorn','pip '))
    says_node = any(x in blob for x in ('node','npm','react','vite','vitest','typescript','javascript','next','svelte','vue','angular'))
    actual_nonpython = any(Path(str(x.get('path') or '')).suffix.lower() in {'.ts','.tsx','.js','.jsx','.mjs','.cjs'} for x in owned_rows)
    # Foreign config files alone do not make a Python component polyglot; they are exactly what this
    # sanitizer is intended to remove. Only real non-config JS/TS source counts as evidence.
    actual_nonpython = any(
        Path(str(x.get('path') or '')).suffix.lower() in {'.ts','.tsx','.js','.jsx','.mjs','.cjs'}
        and Path(str(x.get('path') or '')).name.lower() not in {
            'vite.config.ts','vite.config.js','vitest.config.ts','vitest.config.js','jest.config.ts','jest.config.js'
        }
        for x in owned_rows
    )
    return says_python and not says_node and not actual_nonpython


def _v38_toolchain_sanitize_manifest(manifest):
    if not isinstance(manifest, dict):
        return manifest
    files = [dict(x) for x in (manifest.get('files') or []) if isinstance(x, dict)]
    comps = _v35_sanitize_components(manifest.get('components'))
    if not comps or not files:
        return manifest
    removed = set(); reasons = []
    for comp in comps:
        root = str(comp.get('root') or '.').replace('\\','/').strip('/') or '.'
        owned = [x for x in files if root == '.' or str(x.get('path') or '').replace('\\','/').strip('/') == root or str(x.get('path') or '').replace('\\','/').strip('/').startswith(root.rstrip('/') + '/')]
        if not _v38_component_is_python_only(comp, owned):
            continue
        foreign_names = {
            'package.json','package-lock.json','pnpm-lock.yaml','yarn.lock','tsconfig.json','tsconfig.app.json','tsconfig.node.json',
            'vite.config.ts','vite.config.js','vitest.config.ts','vitest.config.js','jest.config.ts','jest.config.js'
        }
        for row in owned:
            rel = str(row.get('path') or '').replace('\\','/').strip('/')
            name = Path(rel).name.lower()
            purpose = str(row.get('purpose') or '').lower()
            if name in foreign_names and any(x in (name + ' ' + purpose) for x in ('vite','vitest','typescript','node','npm','javascript','jest')):
                removed.add(rel)
                reasons.append({'component': str(comp.get('id') or root), 'path': rel, 'reason': 'foreign Node/TypeScript config in Python-only component'})
    if not removed:
        return manifest
    kept = []
    removed_fold = {x.casefold() for x in removed}
    for row in files:
        rel = str(row.get('path') or '').replace('\\','/').strip('/')
        if rel.casefold() in removed_fold:
            continue
        deps = []
        for dep in row.get('depends_on') or []:
            d = str(dep or '').replace('\\','/').strip('/')
            if d.casefold() in removed_fold:
                continue
            deps.append(d)
        row['depends_on'] = deps
        kept.append(row)
    manifest['files'] = kept
    hist = list(manifest.get('_v38_toolchain_sanitized') or [])
    hist.extend(reasons)
    manifest['_v38_toolchain_sanitized'] = hist[-100:]
    return manifest


_v38_prev_canonicalize_manifest_paths = _v373_canonicalize_manifest_paths

def _v373_canonicalize_manifest_paths(manifest, user_request='', work=None):
    result = _v38_prev_canonicalize_manifest_paths(manifest, user_request, work)
    if isinstance(result, dict):
        result = _v38_toolchain_sanitize_manifest(result)
    return result


# ---- Persistent KB: per-file revisions and accepted hashes -----------------
_v38_prev_refresh_project_kb = _v373_refresh_project_kb

def _v373_refresh_project_kb(work, manifest=None, reason='refresh', force=False):
    kb_path = _v373_kb_path(work)
    before = _v373_json_read(kb_path, {}) if kb_path.exists() else {}
    kb = _v38_prev_refresh_project_kb(work, manifest, reason, force)
    if not isinstance(kb, dict):
        return kb
    old_files = (before.get('files') or {}) if isinstance(before, dict) else {}
    for rel, row in (kb.get('files') or {}).items():
        if not isinstance(row, dict): continue
        old = old_files.get(rel) or {}
        old_rev = int(old.get('revision') or 0)
        same = bool(old and old.get('sha256') == row.get('sha256') and old.get('status') == row.get('status'))
        row['revision'] = old_rev if same and old_rev else max(1, old_rev + 1)
        row['accepted_sha256'] = row.get('sha256') if row.get('status') == 'implemented' else str(old.get('accepted_sha256') or '')
        if not same:
            row['last_state_change_at'] = _utc_stamp()
        else:
            row['last_state_change_at'] = str(old.get('last_state_change_at') or '')
    kb['schema_version'] = max(2, int(kb.get('schema_version') or 1))
    kb['version'] = V38_VERSION
    kb['engine'] = 'REVISIONED_PROJECT_KNOWLEDGE_BASE'
    kb.setdefault('memory_invariants', [])
    for line in (
        'Existing files must be read at their current revision before edit.',
        'Only accepted/committed source becomes authoritative project memory.',
        'Canonical public providers are scoped by component; same names across components are legal.',
        'A patch targeting a stale file hash/revision is rejected and must be re-read.',
    ):
        if line not in kb['memory_invariants']:
            kb['memory_invariants'].append(line)
    try:
        _v373_atomic_json_write(kb_path, kb)
    except Exception:
        pass
    return kb


def _v38_file_hash_text(text):
    return hashlib.sha256(str(text or '').encode('utf-8', errors='replace')).hexdigest()[:20]


def _v38_issue_read_receipt(work, manifest, rel, text=None):
    rel = _v373_canonical_manifest_rel(manifest or {}, rel)
    path = Path(work) / rel
    if text is None:
        try: text = path.read_text(encoding='utf-8', errors='replace')
        except Exception: text = ''
    kb = _v373_refresh_project_kb(work, manifest, reason='read_before_edit')
    row = (kb.get('files') or {}).get(rel) or {}
    receipt = {
        'file': rel,
        'revision': int(row.get('revision') or 0),
        'sha256': _v38_file_hash_text(text),
        'repo_token': str(kb.get('source_token') or ''),
        'read_at': _utc_stamp(),
    }
    state = _v37_agent_state_load(work)
    state.setdefault(V38_READ_RECEIPTS_KEY, {})[rel] = receipt
    _v37_agent_state_save(work, state)
    return receipt


def _v38_current_read_receipt(work, rel):
    state = _v37_agent_state_load(work)
    return dict((state.get(V38_READ_RECEIPTS_KEY) or {}).get(str(rel), {}) or {})


def _v38_receipt_still_current(work, rel, receipt):
    if not receipt: return False
    p = Path(work) / rel
    try: now = p.read_text(encoding='utf-8', errors='replace')
    except Exception: return False
    return _v38_file_hash_text(now) == str(receipt.get('sha256') or '')


# ---- State-aware repair loop detector --------------------------------------
def _v38_repo_state_token(work, manifest):
    try:
        kb = _v373_refresh_project_kb(work, manifest, reason='loop_state')
        return str(kb.get('source_token') or '')
    except Exception:
        try: return _v373_kb_token(work, manifest)
        except Exception: return ''


def _v38_failure_key(problems, validation_failure=''):
    text = str(validation_failure or '') + '\n' + '\n'.join(str(x) for x in (problems or []))
    text = _v381_normalized_problem(text) if '_v381_normalized_problem' in globals() else re.sub(r'\s+', ' ', text.lower()).strip()
    return hashlib.sha256(text.encode('utf-8', errors='replace')).hexdigest()[:18]


def _v38_register_repair_request(work, manifest, rel, problems, validation_failure=''):
    state = _v37_agent_state_load(work)
    rows = state.setdefault(V38_REPAIR_REQUESTS_KEY, {}).setdefault(str(rel), [])
    entry = {
        'repo_token': _v38_repo_state_token(work, manifest),
        'failure_key': _v38_failure_key(problems, validation_failure),
        'at': _utc_stamp(),
    }
    rows.append(entry)
    state[V38_REPAIR_REQUESTS_KEY][str(rel)] = rows[-20:]
    _v37_agent_state_save(work, state)
    same = [x for x in rows if x.get('repo_token') == entry['repo_token'] and x.get('failure_key') == entry['failure_key']]
    return entry, len(same)


_v38_prev_record_patch_attempt = _v37_record_patch_attempt

def _v37_record_patch_attempt(work, rel, content, error=''):
    fp = _v38_prev_record_patch_attempt(work, rel, content, error)
    try:
        state = _v37_agent_state_load(work)
        rows = (state.get('patch_history') or {}).get(str(rel), [])
        if rows:
            p = Path(work) / rel
            current = p.read_text(encoding='utf-8', errors='replace') if p.exists() else ''
            rows[-1]['source_sha256'] = _v38_file_hash_text(current)
            rows[-1]['error_key'] = hashlib.sha256(_v381_normalized_problem(error).encode('utf-8', errors='replace')).hexdigest()[:16] if error else ''
            rows[-1]['repo_token'] = ''  # filled cheaply from the KB if available below
            try:
                kb = _v373_json_read(_v373_kb_path(work), {})
                rows[-1]['repo_token'] = str(kb.get('source_token') or '')
            except Exception: pass
            state['patch_history'][str(rel)] = rows[-V37_LOOP_HISTORY:]
            _v37_agent_state_save(work, state)
    except Exception:
        pass
    return fp


# ---- Aider-style SEARCH/REPLACE recovery -----------------------------------
def _v38_normalized_lines(text, mode='rstrip'):
    lines = str(text or '').replace('\r\n','\n').replace('\r','\n').splitlines(keepends=True)
    if mode == 'rstrip':
        return [x.rstrip() for x in lines]
    return [x.strip() for x in lines]


def _v38_find_unique_relaxed_block(candidate, search):
    cand_lines = str(candidate).replace('\r\n','\n').replace('\r','\n').splitlines(keepends=True)
    search_lines = str(search).replace('\r\n','\n').replace('\r','\n').splitlines(keepends=True)
    if not search_lines or len(search_lines) > len(cand_lines):
        return None
    matches = []
    target = [x.rstrip() for x in search_lines]
    for i in range(0, len(cand_lines)-len(search_lines)+1):
        window = cand_lines[i:i+len(search_lines)]
        if [x.rstrip() for x in window] == target:
            matches.append((i, i+len(search_lines)))
    if len(matches) == 1:
        i,j = matches[0]
        return ''.join(cand_lines[:i]), ''.join(cand_lines[i:j]), ''.join(cand_lines[j:])
    return None


def _v38_closest_source(search, candidate, max_lines=18):
    try:
        import difflib
        s_lines = str(search).replace('\r\n','\n').splitlines()
        c_lines = str(candidate).replace('\r\n','\n').splitlines()
        n = max(1, len(s_lines)); best = (0.0, [])
        lo_n, hi_n = max(1,n-2), min(len(c_lines), n+2)
        for size in range(lo_n, hi_n+1):
            for i in range(0, len(c_lines)-size+1):
                w = c_lines[i:i+size]
                ratio = difflib.SequenceMatcher(None, '\n'.join(s_lines), '\n'.join(w)).ratio()
                if ratio > best[0]: best = (ratio, w)
        if best[1] and best[0] >= 0.45:
            return '\n'.join(best[1][:max_lines])
    except Exception:
        pass
    return ''


def _v36_apply_search_replace(current, replacements):
    candidate = str(current); changed = 0
    for idx, rep in enumerate(replacements or [], 1):
        search = str(rep.get('search') or ''); replace = str(rep.get('replace') or '')
        if not search:
            return '', f'SEARCH/REPLACE block {idx} has an empty SEARCH section.'
        count = candidate.count(search)
        if count == 1:
            candidate = candidate.replace(search, replace, 1); changed += 1; continue
        if count > 1:
            return '', (
                f'SEARCH/REPLACE block {idx} matched {count} locations. Narrow SEARCH with more unique surrounding lines; '
                'do not rewrite the whole file.'
            )
        relaxed = _v38_find_unique_relaxed_block(candidate, search)
        if relaxed:
            before, actual, after = relaxed
            candidate = before + replace + after; changed += 1; continue
        closest = _v38_closest_source(search, candidate)
        hint = f'\nClosest current source lines (copy these verbatim in the next SEARCH):\n{closest}' if closest else ''
        return '', (
            f'SEARCH/REPLACE block {idx} did not match the current file. The file may have changed or whitespace/content was guessed. '
            'Re-read the current revision and retry ONLY the failed edit block.' + hint
        )
    if not changed or candidate == current:
        return '', 'Patch made no change; do not repeat it.'
    return candidate, ''


# ---- Per-file micro-skills --------------------------------------------------
def _v38_micro_skill_names(manifest, rel):
    rel = str(rel or '').replace('\\','/').strip('/')
    comp = _v38_component_for_path(manifest, rel)
    blob = _v38_component_adapter_blob(comp) + ' ' + rel.lower()
    names = []
    def add(name):
        if name not in names: names.append(name)
    ext = Path(rel).suffix.lower()
    if ext in {'.py','.pyw'} or any(x in blob for x in ('python','fastapi','flask','django','pytest')): add('python')
    if ext in {'.ts','.tsx','.js','.jsx','.mjs','.cjs'} or any(x in blob for x in ('node','npm','typescript','javascript')): add('node')
    if ext in {'.tsx','.jsx'} or 'react' in blob or 'vite' in blob: add('react')
    if ext == '.rs' or 'rust' in blob: add('rust')
    if ext in {'.cpp','.cc','.cxx','.h','.hpp','.c'} or 'cmake' in blob or 'c++' in blob: add('cpp')
    if 'flutter' in blob or ext == '.dart': add('flutter')
    if 'android' in blob or 'gradle' in blob or ext in {'.kt','.kts'}: add('android')
    if 'tauri' in blob: add('tauri')
    if 'unreal' in blob: add('unreal')
    if 'godot' in blob or ext == '.gd': add('godot')
    if 'dotnet' in blob or ext == '.cs': add('dotnet')
    if 'ios' in blob or 'swift' in blob or ext == '.swift': add('ios')
    return names[:3]


def _v38_micro_skill_context(manifest, rel, max_chars=V38_MICRO_SKILL_CHARS):
    chunks=[]; used=0
    for name in _v38_micro_skill_names(manifest, rel):
        p = V36_SKILLS_DIR / f'{name}.md'
        if not p.exists(): continue
        try: raw = p.read_text(encoding='utf-8', errors='replace').strip()
        except Exception: continue
        # Small-model skill cards should be tiny. Prefer the opening rules and avoid a huge global
        # framework manual that competes with actual project contracts.
        raw = raw[:750]
        piece = f'\n--- MICRO-SKILL {name.upper()} ---\n{raw}\n'
        if used + len(piece) > max_chars: break
        chunks.append(piece); used += len(piece)
    return ''.join(chunks)


