_v38_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    stage_text = str(stage or '')
    for old in ('V37.3','V37.2','V37.1','V37','V36.2','V36.1','V36'):
        stage_text = stage_text.replace(old, 'V38')
    if kwargs.get('thinking'):
        if kwargs.get('max_tokens') is None:
            kwargs['max_tokens'] = V38_REASONING_TOKEN_BUDGET
        else:
            kwargs['max_tokens'] = min(int(kwargs['max_tokens']), V38_REASONING_TOKEN_BUDGET)
    elif str(profile or '').lower() == 'repair':
        if kwargs.get('max_tokens') is None:
            kwargs['max_tokens'] = V38_REPAIR_OUTPUT_TOKENS
        else:
            kwargs['max_tokens'] = min(int(kwargs['max_tokens']), V38_REPAIR_OUTPUT_TOKENS)
    return _v38_prev_qwen_call(prompt, progress_callback, stage_text, profile=profile, **kwargs)


