# ---- Read-only diagnostic subagents for hard subsystem failures ------------
_v38_prev_subsystem_brief = _v381_subsystem_reconciliation_brief

def _v381_subsystem_reconciliation_brief(user_request, manifest, work, target_rel, selected, issues, validation_failure, progress_callback=None):
    if not V38_READONLY_SUBAGENTS or len(selected or []) < 4:
        return _v38_prev_subsystem_brief(user_request, manifest, work, target_rel, selected, issues, validation_failure, progress_callback)
    snapshot = _v381_subsystem_contract_snapshot(work, manifest, selected, max_chars=10500)
    issue_text = '\n'.join(
        f"- {x.get('kind')}: {x.get('file')} -> {x.get('provider_file') or ''}: {x.get('problem')}"
        for x in (issues or [])[:20]
    )
    shared = (
        f'TARGET: {target_rel}\nFILES: {json.dumps(selected, ensure_ascii=False)}\n'
        f'ISSUES:\n{issue_text or "(none)"}\nFAILURE:\n{str(validation_failure or "(none)")[-3500:]}\n{snapshot}'
    )
    reports=[]
    prompts=[
        ('contracts', 'READ-ONLY CONTRACT ANALYST. Do not write source. Identify the canonical provider/model/signature choices and the smallest provider-first ordering that removes contradictions.'),
        ('runtime', 'READ-ONLY TEST/RUNTIME ANALYST. Do not write source. Identify which current deterministic/runtime evidence is root cause versus downstream symptom and which layer should be repaired first.'),
    ]
    for label, instruction in prompts:
        try:
            ok, raw = _qwen_call(
                instruction + '\nKeep the report under 450 tokens.\n\n' + shared,
                progress_callback, f'V38 read-only {label} analysis: {target_rel}',
                profile='audit', max_tokens=520, thinking=False, response_schema=None, strict_output=False,
            )
            if ok and str(raw or '').strip():
                reports.append(f'[{label.upper()} ANALYST]\n{str(raw).strip()[:3000]}')
        except Exception as exc:
            _v38_persist_model_output_failure(work, f'v38_{label}_subagent_exception', target_rel, '', exc)
    if reports:
        return (
            'V38 BOUNDED READ-ONLY SUBAGENT CONSENSUS. These reports cannot edit files and are advisory; '
            'machine contracts/runtime validation remain authoritative.\n' + '\n\n'.join(reports)
        )[:7500]
    return _v38_prev_subsystem_brief(user_request, manifest, work, target_rel, selected, issues, validation_failure, progress_callback)


