# ---- V38 scoped contract memory (frontend Project != backend Project) ------
_v38_prev_refresh_project_kb_scoped = _v373_refresh_project_kb

def _v373_refresh_project_kb(work, manifest=None, reason='refresh', force=False):
    kb = _v38_prev_refresh_project_kb_scoped(work, manifest, reason, force)
    if not isinstance(kb, dict): return kb
    manifest = _v373_canonicalize_manifest_paths(manifest or _v373_load_work_manifest(work), (manifest or {}).get('_original_user_request') if isinstance(manifest,dict) else '', work=None) or {}
    try: registry = _v373_json_read(Path(work) / V36_CONTRACT_REGISTRY_FILE, {})
    except Exception: registry = {}
    try: graph = _v373_json_read(Path(work) / V36_REPO_GRAPH_FILE, {})
    except Exception: graph = {}
    groups = {}
    for row in (registry.get('contracts') or [])[:V373_KB_MAX_CONTRACTS]:
        if not isinstance(row, dict): continue
        symbol = str(row.get('symbol') or '').strip()
        provider = _v373_canonical_manifest_rel(manifest, row.get('provider'))
        if not symbol or not provider: continue
        scope = _v38_component_scope(manifest, provider)
        item = dict(row); item['provider']=provider; item['scope']=scope
        groups.setdefault((scope,symbol), []).append(item)
    old_scoped = dict(kb.get('scoped_canonical_symbols') or {})
    scoped = {}; conflicts=[]
    for (scope,symbol), rows in groups.items():
        providers=list(dict.fromkeys(str(x.get('provider') or '') for x in rows if x.get('provider')))
        previous_for_symbol = {symbol: old_scoped.get(f'{scope}::{symbol}') or {}}
        chosen = _v373_choose_canonical_provider(symbol, providers, previous_for_symbol, graph)
        selected=[x for x in rows if not chosen or x.get('provider')==chosen]
        selected.sort(key=lambda x:(0 if x.get('source')=='ast' else 1,-len(str(x.get('signature') or ''))))
        best=selected[0] if selected else rows[0]
        key=f'{scope}::{symbol}'
        scoped[key]={
            'scope':scope,'symbol':symbol,'provider':chosen,'signature':str(best.get('signature') or symbol),
            'source':str(best.get('source') or ''),'providers':providers,'conflict':len(providers)>1,
        }
        if len(providers)>1:
            conflicts.append({'scope':scope,'symbol':symbol,'canonical_provider':chosen,'providers':providers})
    kb['scoped_canonical_symbols']=scoped
    # Provider conflicts are authoritative only within one component. Cross-component names are legal.
    kb['provider_conflicts']=conflicts[:300]
    kb['contract_scope_rule']='Public symbol ownership is canonical within a component. Same names in separate components are separate contracts unless an explicit shared contract links them.'
    try:_v373_atomic_json_write(_v373_kb_path(work),kb)
    except Exception:pass
    return kb


# Replace V37.3's unscoped contract-memory prompt with V38's component-scoped view.
def _v36_contract_context(work, manifest, current_path='', max_chars=8000):
    manifest = _v373_canonicalize_manifest_paths(manifest or {}, (manifest or {}).get('_original_user_request') or '')
    current = _v373_canonical_manifest_rel(manifest, current_path)
    # Use the mature machine-derived contract context that predates V37.3's global symbol-memory overlay.
    base = _v373_base_contract_context(work, manifest, current, max_chars)
    kb = _v373_refresh_project_kb(work, manifest, reason='v38_scoped_contract_context')
    scope = _v38_component_scope(manifest, current) if current else '.'
    info = (kb.get('files') or {}).get(current) or {}
    related={current}; related.update(info.get('depends_on') or [])
    lines=[f'V38 COMPONENT-SCOPED CANONICAL CONTRACT MEMORY (scope={scope!r}):']
    for key,row in (kb.get('scoped_canonical_symbols') or {}).items():
        if str(row.get('scope') or '') != scope: continue
        providers=row.get('providers') or []
        if row.get('conflict') or any(p in related for p in providers):
            owner=row.get('provider') or 'UNRESOLVED-CONFLICT'
            extra=f" [CONFLICT INSIDE COMPONENT: {providers}]" if row.get('conflict') else ''
            lines.append(f"- {row.get('symbol')}: {row.get('signature')} owner={owner}{extra}")
        if sum(len(x)+1 for x in lines)>4300: break
    row=(kb.get('files') or {}).get(current) or {}
    receipt=_v38_current_read_receipt(work,current) if current else {}
    if current:
        lines.extend([
            'V38 REVISION-BOUND EDIT MEMORY:',
            f"- target: {current}",
            f"- current KB revision: {row.get('revision',0)}",
            f"- current accepted hash: {row.get('accepted_sha256') or row.get('sha256') or ''}",
            f"- latest read receipt: revision={receipt.get('revision',0)} sha256={receipt.get('sha256','')}",
            '- SEARCH text must come from this exact current revision; stale edits are rejected.',
        ])
        micro=_v38_micro_skill_context(manifest,current,1100)
        if micro: lines.append(micro)
    return base + '\n\n' + '\n'.join(lines)


# Final V38 model-call wrapper: call the stable pre-V36 provider wrapper directly so Qwen does not
# receive stacked V36/V37 role headers. One short stable prefix improves prompt-cache reuse.
def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    stage_text=str(stage or '')
    for old in ('V37.3','V37.2','V37.1','V37','V36.2','V36.1','V36','V35.1','V35','V34.1','V34'):
        stage_text=stage_text.replace(old,'V38')
    role=_v36_role_for_call(profile,stage_text)
    if kwargs.get('thinking'):
        kwargs['max_tokens']=min(int(kwargs.get('max_tokens') or V38_REASONING_TOKEN_BUDGET),V38_REASONING_TOKEN_BUDGET)
    elif str(profile or '').lower()=='repair':
        kwargs['max_tokens']=min(int(kwargs.get('max_tokens') or V38_REPAIR_OUTPUT_TOKENS),V38_REPAIR_OUTPUT_TOKENS)
    prefix=(
        f'JARVIS V38 ROLE: {role}\n'
        'Jarvis owns the persistent project knowledge base, current file revisions, canonical component-scoped contracts, requirements, tests, and validation. '
        'Work on one bounded engineering action using current evidence only. Do not redefine existing public models/APIs unless Jarvis explicitly requests a provider-first reconciliation. '
        'Existing files are edit-only: use the exact current revision supplied by Jarvis; never reconstruct a file from memory.\n'
    )
    return _v36_base_qwen_call(prefix+'\n'+str(prompt or ''),progress_callback,stage_text,profile=profile,**kwargs)

# =============================================================================
# V38.1 CANONICAL TOPOLOGY + PRE-IMPLEMENTATION DOMAIN MEMORY
# =============================================================================
# Harden the V38 small-model loop using failures observed in the HomeLedger run:
# - one canonical Tauri topology (one package.json + one src-tauri/Cargo.toml)
# - binary assets are materialized deterministically, never text-generated by Qwen
# - component roots must own their native dependency manifest
# - Cargo manifests receive a small semantic typo gate in addition to TOML syntax validation
# - a canonical domain-contract pass runs BEFORE architecture/source generation
# - the persistent KB can derive canonical symbol ownership from the repo graph + planned contracts,
#   even when the legacy contract-registry parser has not yet learned that language
# - canonical model candidates are checked against required domain fields before they are accepted

V381_VERSION = '38.1.0'
V38_VERSION = V381_VERSION
V36_VERSION = V381_VERSION
V381_DOMAIN_CONTRACTS_FILE = 'JARVIS_V381_DOMAIN_CONTRACTS.json'
V381_BINARY_ASSET_EXTS = {'.ico', '.png'}
V381_FORBIDDEN_MODEL_BINARY_EXTS = {
    '.jpg', '.jpeg', '.gif', '.webp', '.bmp', '.icns', '.ttf', '.otf', '.woff', '.woff2',
    '.exe', '.dll', '.so', '.dylib', '.zip', '.7z', '.rar', '.pdf', '.mp3', '.wav', '.mp4', '.mov'
}
V381_DOMAIN_SCHEMA = {
    'type': 'object',
    'properties': {
        'entities': {
            'type': 'array',
            'items': {
                'type': 'object',
                'properties': {
                    'name': {'type': 'string'},
                    'purpose': {'type': 'string'},
                    'fields': {
                        'type': 'array',
                        'items': {
                            'type': 'object',
                            'properties': {
                                'name': {'type': 'string'},
                                'type': {'type': 'string'},
                                'required': {'type': 'boolean'},
                            },
                            'required': ['name', 'type', 'required'],
                            'additionalProperties': False,
                        },
                    },
                },
                'required': ['name', 'purpose', 'fields'],
                'additionalProperties': False,
            },
        },
        'enums': {
            'type': 'array',
            'items': {
                'type': 'object',
                'properties': {
                    'name': {'type': 'string'},
                    'values': {'type': 'array', 'items': {'type': 'string'}},
                },
                'required': ['name', 'values'],
                'additionalProperties': False,
            },
        },
        'shared_rules': {'type': 'array', 'items': {'type': 'string'}},
    },
    'required': ['entities', 'enums', 'shared_rules'],
    'additionalProperties': False,
}


def _v381_is_tauri_request(user_request):
    low = str(user_request or '').lower()
    return 'tauri' in low and ('rust' in low or 'cargo' in low) and any(x in low for x in ('react', 'vite', 'typescript', 'frontend', 'desktop'))


def _v381_tauri_component_locks():
    return [
        {
            'id': 'ui', 'root': '.',
            'purpose': 'Canonical React/TypeScript/Vite desktop UI for the Tauri application.',
            'toolchain_adapter': 'react', 'depends_on': ['tauri-core'],
            'dependency_command': 'npm install', 'build_command': 'npm run build',
            'test_command': 'npm test', 'run_command': 'npm run tauri dev',
        },
        {
            'id': 'tauri-core', 'root': 'src-tauri',
            'purpose': 'Canonical Rust/Tauri backend and SQLite application core.',
            'toolchain_adapter': 'rust', 'depends_on': [],
            'dependency_command': 'cargo fetch', 'build_command': 'cargo build',
            'test_command': 'cargo test', 'run_command': 'cargo run',
        },
    ]


_v381_prev_normalize_component_adapter = _v361_normalize_component_adapter

def _v361_normalize_component_adapter(adapter):
    low = str(adapter or '').strip().lower()
    if low.startswith('tauri://'):
        if any(x in low for x in ('core', 'rust', 'backend', 'native')):
            return 'rust'
        return 'react'
    if low in {'tauri-core', 'tauri-rust', 'rust/tauri'}:
        return 'rust'
    if low in {'tauri-ui', 'tauri-react', 'react/tauri', 'vite/tauri'}:
        return 'react'
    return _v381_prev_normalize_component_adapter(adapter)


_v381_prev_explicit_component_locks = _v361_explicit_component_locks

def _v361_explicit_component_locks(user_request):
    if _v381_is_tauri_request(user_request):
        return _v381_tauri_component_locks()
    return _v381_prev_explicit_component_locks(user_request)


_v381_prev_apply_explicit_component_locks = _v361_apply_explicit_component_locks

def _v361_apply_explicit_component_locks(user_request, manifest):
    result = _v381_prev_apply_explicit_component_locks(user_request, manifest)
    if not _v381_is_tauri_request(user_request) or not isinstance(result, dict):
        return result
    # Standard Tauri is one application root: package.json/src at repo root and Cargo under src-tauri.
    # Do not allow planner-created frontend/backend/shared applications to survive as parallel products.
    result['components'] = _v381_tauri_component_locks()
    result['project_type'] = result.get('project_type') or 'tauri-desktop'
    result['platform'] = _v361_explicit_platform(user_request) or result.get('platform') or 'windows'
    rules = list(result.get('architecture_rules') or [])
    for rule in (
        'TAURI_TOPOLOGY: one application root only; package.json and React src/ live at repository root.',
        'TAURI_TOPOLOGY: the only Rust application manifest is src-tauri/Cargo.toml and Rust application code lives under src-tauri/src/.',
        'TAURI_TOPOLOGY: shared frontend/backend contracts are definitions, not a third executable application or third package/Cargo root.',
    ):
        if rule not in rules:
            rules.append(rule)
    result['architecture_rules'] = rules
    return result


_v381_prev_plan_component = _v362_plan_component

def _v362_plan_component(user_request, spec, overview, component, max_files, ordinal, total, progress_callback=None):
    request = str(user_request or '')
    if _v381_is_tauri_request(request):
        request += (
            '\n\nJARVIS V38.1 CANONICAL TAURI TOPOLOGY (MANDATORY): '
            'There is ONE Tauri application, not separate frontend/backend/shared applications. '
            'The React/Vite component root is repository root `.` and owns package.json, index.html, src/, tests/config. '
            'The Rust component root is `src-tauri` and owns src-tauri/Cargo.toml, tauri.conf.json, src/, migrations/tests as appropriate. '
            'Do not create frontend/, backend/, shared/ application roots, another package.json, or another Cargo.toml. '
            'Cross-language shared contracts are definitions inside the two canonical components, not a third buildable component.'
        )
    return _v381_prev_plan_component(request, spec, overview, component, max_files, ordinal, total, progress_callback)


def _v381_clean_symbol_name(value):
    text = str(value or '').strip().strip('`"\'')
    m = re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', text)
    return text if m else ''


def _v381_domain_contract_lines(domain):
    lines = []
    if not isinstance(domain, dict):
        return lines
    for ent in domain.get('entities') or []:
        if not isinstance(ent, dict):
            continue
        name = _v381_clean_symbol_name(ent.get('name'))
        if not name:
            continue
        fields = []
        for f in ent.get('fields') or []:
            if not isinstance(f, dict):
                continue
            fn = _v381_clean_symbol_name(f.get('name'))
            if not fn:
                continue
            typ = str(f.get('type') or 'value').strip()[:80]
            fields.append(f"{fn}: {typ}{'' if f.get('required', True) else '?'}")
        lines.append(f"DOMAIN_ENTITY {name} ({', '.join(fields)})")
    for enum in domain.get('enums') or []:
        if not isinstance(enum, dict):
            continue
        name = _v381_clean_symbol_name(enum.get('name'))
        vals = [str(x).strip() for x in enum.get('values') or [] if str(x).strip()]
        if name and vals:
            lines.append(f"DOMAIN_ENUM {name} ({', '.join(vals[:40])})")
    for rule in domain.get('shared_rules') or []:
        rule = str(rule or '').strip()
        if rule:
            lines.append('DOMAIN_RULE ' + rule[:600])
    return lines[:160]


def _v381_generate_domain_contracts(user_request, spec, progress_callback=None):
    # This pass intentionally sees the compiled requirements, not the evolving source tree. It freezes
    # domain names/field names before Rust/TypeScript/Python get independent opportunities to invent them.
    req = {
        'project_summary': (spec or {}).get('project_summary') or '',
        'functional_requirements': (spec or {}).get('functional_requirements') or [],
        'constraints': (spec or {}).get('constraints') or [],
        'acceptance_criteria': (spec or {}).get('acceptance_criteria') or [],
        'source_requirements': (spec or {}).get('source_requirements') or [],
    }
    prompt = (
        'V38.1 CANONICAL DOMAIN CONTRACT PASS. Return ONLY JSON. Extract the minimum canonical data entities and enums '
        'that are necessary to implement the compiled requirements. These names and field names will be authoritative across '
        'all languages/components, so do not create duplicate representations with different field names. Include only fields '
        'needed by explicit requirements or necessary identity/relationship/persistence for those requirements; do not invent speculative features. '
        'Use portable identifier-style field names (snake_case preferred when cross-language). Mark a field required only when the application logic '
        'cannot satisfy the requirement without it. This is a contract/spec task, not source code.\n\n'
        'COMPILED REQUIREMENTS:\n' + json.dumps(req, ensure_ascii=False, indent=2)[:18000] +
        '\n\nUSER REQUEST:\n' + str(user_request or '')[:8000]
    )
    try:
        ok, raw = _qwen_call(
            prompt, progress_callback, 'V38.1 freezing canonical domain contracts', profile='plan',
            max_tokens=2400, thinking=False, response_schema=V381_DOMAIN_SCHEMA,
            schema_name='v381_domain_contracts', strict_output=True,
        )
        obj = _extract_json(raw) if ok else None
    except Exception:
        obj = None
    if not isinstance(obj, dict):
        obj = {'entities': [], 'enums': [], 'shared_rules': []}
    # Defensive normalization.
    entities = []
    seen = set()
    for ent in obj.get('entities') or []:
        if not isinstance(ent, dict):
            continue
        name = _v381_clean_symbol_name(ent.get('name'))
        if not name or name.casefold() in seen:
            continue
        seen.add(name.casefold())
        fields = []
        fseen = set()
        for f in ent.get('fields') or []:
            if not isinstance(f, dict):
                continue
            fn = _v381_clean_symbol_name(f.get('name'))
            if not fn or fn.casefold() in fseen:
                continue
            fseen.add(fn.casefold())
            fields.append({'name': fn, 'type': str(f.get('type') or 'value')[:100], 'required': bool(f.get('required', True))})
        entities.append({'name': name, 'purpose': str(ent.get('purpose') or '')[:300], 'fields': fields[:50]})
    enums = []
    eseen = set()
    for row in obj.get('enums') or []:
        if not isinstance(row, dict):
            continue
        name = _v381_clean_symbol_name(row.get('name'))
        if not name or name.casefold() in eseen:
            continue
        eseen.add(name.casefold())
        values = list(dict.fromkeys(str(x).strip() for x in row.get('values') or [] if str(x).strip()))[:40]
        enums.append({'name': name, 'values': values})
    return {
        'version': V381_VERSION,
        'entities': entities,
        'enums': enums,
        'shared_rules': [str(x).strip()[:600] for x in obj.get('shared_rules') or [] if str(x).strip()][:80],
        'generated_at': _utc_stamp(),
    }


_v381_prev_generate_requirements = _v36_generate_requirements

def _v36_generate_requirements(user_request, work, progress_callback=None):
    spec = _v381_prev_generate_requirements(user_request, work, progress_callback)
    if not isinstance(spec, dict):
        spec = {}
    domain = _v381_generate_domain_contracts(user_request, spec, progress_callback)
    spec['canonical_domain_contracts'] = domain
    spec['version'] = V381_VERSION
    try:
        Path(work, V36_REQUIREMENTS_FILE).write_text(json.dumps(spec, indent=2, ensure_ascii=False), encoding='utf-8')
        Path(work, V381_DOMAIN_CONTRACTS_FILE).write_text(json.dumps(domain, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        pass
    return spec


_v381_prev_compact_requirements = _v362_compact_requirements

def _v362_compact_requirements(spec, max_chars=16000):
    if not isinstance(spec, dict):
        return _v381_prev_compact_requirements(spec, max_chars)
    keep = {
        k: spec.get(k) for k in (
            'project_summary', 'functional_requirements', 'constraints', 'acceptance_criteria',
            'suggested_test_scenarios', 'source_requirements', 'canonical_domain_contracts'
        )
    }
    raw = json.dumps(keep, ensure_ascii=False, indent=2)
    return raw[:max_chars]


def _v381_contract_field_expectations(manifest, rel):
    domain = (manifest or {}).get('canonical_domain_contracts') or {}
    entities = {str(x.get('name') or ''): x for x in domain.get('entities') or [] if isinstance(x, dict) and x.get('name')}
    if not entities:
        return {}
    item = next((x for x in (manifest or {}).get('files') or [] if str(x.get('path') or '').replace('\\','/').strip('/') == str(rel or '').replace('\\','/').strip('/')), None)
    if not isinstance(item, dict):
        return {}
    blob = ' '.join([
        str(item.get('purpose') or ''),
        ' '.join(str(x) for x in item.get('contracts') or []),
        ' '.join(str(x) for x in item.get('exports') or []),
    ])
    out = {}
    for name, ent in entities.items():
        if re.search(rf'(?<![A-Za-z0-9_]){re.escape(name)}(?![A-Za-z0-9_])', blob, re.I):
            out[name] = [str(f.get('name') or '') for f in ent.get('fields') or [] if isinstance(f, dict) and f.get('required', True) and f.get('name')]
    return out


def _v381_source_model_fields(content, ext):
    text = str(content or '')
    found = {}
    if ext == '.rs':
        for m in re.finditer(r'(?ms)\b(?:pub\s+)?struct\s+([A-Za-z_][A-Za-z0-9_]*)\s*(?:<[^>{}]+>)?\s*\{(.*?)\}', text):
            name, body = m.group(1), m.group(2)
            fields = set()
            # Rust fields may be one-per-line or emitted compactly on one line. Parse comma/line chunks.
            for chunk in re.split(r'[,\n]', body):
                chunk = re.sub(r'#\[[^]]+\]', ' ', chunk).strip()
                fm = re.match(r'^(?:pub(?:\([^)]*\))?\s+)?(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\s*:', chunk)
                if fm:
                    fields.add(fm.group(1))
            found[name] = fields
    elif ext in {'.ts', '.tsx'}:
        for m in re.finditer(r'(?ms)\b(?:export\s+)?interface\s+([A-Za-z_][A-Za-z0-9_]*)[^\{]*\{(.*?)\}', text):
            fields = set(re.findall(r'(?m)^\s*(?:readonly\s+)?([A-Za-z_][A-Za-z0-9_]*)\??\s*:', m.group(2)))
            found[m.group(1)] = fields
        for m in re.finditer(r'(?ms)\b(?:export\s+)?type\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*\{(.*?)\}', text):
            fields = set(re.findall(r'(?m)^\s*(?:readonly\s+)?([A-Za-z_][A-Za-z0-9_]*)\??\s*:', m.group(2)))
            found.setdefault(m.group(1), set()).update(fields)
    elif ext in {'.py', '.pyw'}:
        try:
            tree = ast.parse(text)
            for node in tree.body:
                if not isinstance(node, ast.ClassDef):
                    continue
                fields = set()
                for child in node.body:
                    if isinstance(child, ast.AnnAssign) and isinstance(child.target, ast.Name):
                        fields.add(child.target.id)
                    elif isinstance(child, ast.Assign):
                        for target in child.targets:
                            if isinstance(target, ast.Name):
                                fields.add(target.id)
                found[node.name] = fields
        except Exception:
            pass
    return found


def _v381_candidate_domain_contract_error(manifest, rel, content):
    expected = _v381_contract_field_expectations(manifest, rel)
    if not expected:
        return ''
    actual = _v381_source_model_fields(content, Path(str(rel or '')).suffix.lower())
    problems = []
    for symbol, fields in expected.items():
        if symbol not in actual:
            problems.append(f'{symbol} is the canonical planned entity for this file but the candidate does not define it')
            continue
        missing = [f for f in fields if f not in actual.get(symbol, set())]
        if missing:
            problems.append(f'{symbol} is missing required canonical field(s): {", ".join(missing)}')
    if problems:
        return 'V38.1 canonical-domain gate: ' + '; '.join(problems[:8]) + '. Match the frozen project domain contract instead of inventing a different definition.'
    return ''


def _v381_tauri_topology_issues(manifest, user_request=''):
    if not _v381_is_tauri_request(user_request or (manifest or {}).get('_original_user_request') or ''):
        return []
    files = [str(x.get('path') or '').replace('\\','/').strip('/') for x in (manifest or {}).get('files') or [] if isinstance(x, dict)]
    issues = []
    package_files = [p for p in files if Path(p).name.lower() == 'package.json']
    cargo_files = [p for p in files if Path(p).name == 'Cargo.toml']
    if package_files != ['package.json']:
        issues.append('Tauri topology requires exactly one repository-root package.json; planned: ' + ', '.join(package_files or ['NONE']))
    if cargo_files != ['src-tauri/Cargo.toml']:
        issues.append('Tauri topology requires exactly one src-tauri/Cargo.toml; planned: ' + ', '.join(cargo_files or ['NONE']))
    app_roots = []
    for p in files:
        low = p.lower()
        if low.endswith('/src/app.tsx') or low == 'src/app.tsx':
            app_roots.append(p)
    if len(app_roots) > 1:
        issues.append('Tauri topology planned multiple React application roots: ' + ', '.join(app_roots))
    for bad in ('frontend/package.json', 'backend/package.json', 'shared/package.json', 'frontend/src-tauri/Cargo.toml', 'backend/src-tauri/Cargo.toml', 'shared/src-tauri/Cargo.toml'):
        if bad in files:
            issues.append(f'Tauri topology contains forbidden parallel application root {bad}; use repository root + src-tauri only.')
    return list(dict.fromkeys(issues))


_v381_prev_manifest_completeness_issues = _v362_manifest_completeness_issues

def _v362_manifest_completeness_issues(manifest, spec, user_request, max_files):
    issues = list(_v381_prev_manifest_completeness_issues(manifest, spec, user_request, max_files) or [])
    for issue in _v381_tauri_topology_issues(manifest, user_request):
        if issue not in issues:
            issues.append(issue)
    files = [str(x.get('path') or '').replace('\\','/').strip('/') for x in (manifest or {}).get('files') or [] if isinstance(x, dict)]
    for comp in _v35_sanitize_components((manifest or {}).get('components')):
        root = str(comp.get('root') or '.').replace('\\','/').strip('/') or '.'
        adapter = _v361_normalize_component_adapter(comp.get('toolchain_adapter'))
        prefix = '' if root == '.' else root + '/'
        if adapter in {'react','vite','node','nextjs','vue','sveltekit','angular'}:
            marker = prefix + 'package.json'
            if marker not in files:
                msg = f'Component {comp.get("id") or root} ({adapter}) root {root!r} does not own required {marker}.'
                if msg not in issues: issues.append(msg)
        if adapter == 'rust':
            marker = prefix + 'Cargo.toml'
            if marker not in files:
                msg = f'Component {comp.get("id") or root} (rust) root {root!r} does not own required {marker}; cargo commands would run from the wrong working directory.'
                if msg not in issues: issues.append(msg)
    # Non-text artifacts should never consume a model generation slot. Unsupported binary artifacts are rejected at architecture time.
    for rel in files:
        ext = Path(rel).suffix.lower()
        if ext in V381_FORBIDDEN_MODEL_BINARY_EXTS:
            msg = f'Binary artifact {rel} must be generated/copied by deterministic tooling or removed from the source manifest; Qwen text generation is not allowed for {ext}.'
            if msg not in issues: issues.append(msg)
    return issues


_v381_prev_build_hierarchical_manifest = _v362_build_hierarchical_manifest

def _v362_build_hierarchical_manifest(user_request, spec, max_files, progress_callback=None):
    manifest, raw = _v381_prev_build_hierarchical_manifest(user_request, spec, max_files, progress_callback)
    if not isinstance(manifest, dict):
        return manifest, raw
    manifest['canonical_domain_contracts'] = (spec or {}).get('canonical_domain_contracts') or {}
    manifest = _v361_apply_explicit_component_locks(user_request, manifest)
    shared = list(manifest.get('shared_contracts') or [])
    for line in _v381_domain_contract_lines(manifest['canonical_domain_contracts']):
        if line not in shared:
            shared.append(line)
    manifest['shared_contracts'] = shared[:240]
    manifest.setdefault('architecture_rules', [])
    if _v381_is_tauri_request(user_request):
        for rule in (
            'Canonical Tauri topology is repository-root React/Vite plus src-tauri Rust; no parallel frontend/backend/shared applications.',
            'Binary icons/assets are Jarvis-owned deterministic artifacts and are not generated as model text files.',
        ):
            if rule not in manifest['architecture_rules']:
                manifest['architecture_rules'].append(rule)
    final = _v362_manifest_completeness_issues(manifest, spec, user_request, max_files)
    if final:
        manifest['_v381_post_domain_topology_issues'] = final
        return None, str(raw or '') + '\nV38.1 CANONICAL TOPOLOGY/DOMAIN GATE:\n' + '\n'.join(final)
    return manifest, raw


def _v381_write_placeholder_png(path):
    # Valid 1x1 transparent RGBA PNG, deterministic and tiny.
    import base64
    payload = base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M/wHwAF/gL+RZz6WQAAAABJRU5ErkJggg==')
    Path(path).write_bytes(payload)


def _v381_write_placeholder_ico(path):
    # Minimal 1x1 32-bit ICO containing a BMP/DIB image. Sufficient as a deterministic placeholder
    # so a language model never spends minutes trying to emit binary bytes as text.
    import struct
    header = struct.pack('<HHH', 0, 1, 1)
    width = height = 1
    dib = struct.pack('<IIIHHIIIIII', 40, width, height * 2, 1, 32, 0, 4, 0, 0, 0, 0)
    pixel = bytes((0, 0, 0, 0))
    mask = bytes((0, 0, 0, 0))
    image = dib + pixel + mask
    entry = bytes((1, 1, 0, 0)) + struct.pack('<HHII', 1, 32, len(image), 6 + 16)
    Path(path).write_bytes(header + entry + image)


def _v381_materialize_binary_asset(work, rel):
    path = Path(work) / _safe_relative(rel)
    path.parent.mkdir(parents=True, exist_ok=True)
    ext = path.suffix.lower()
    if ext == '.png':
        _v381_write_placeholder_png(path)
        return True
    if ext == '.ico':
        _v381_write_placeholder_ico(path)
        return True
    return False


_v381_prev_generate_planned_file = _generate_planned_file

def _generate_planned_file(user_request, manifest, work, file_item, progress_callback=None):
    rel = str((file_item or {}).get('path') or '').replace('\\','/').strip('/')
    ext = Path(rel).suffix.lower()
    if ext in V381_BINARY_ASSET_EXTS:
        try:
            if _v381_materialize_binary_asset(work, rel):
                _append_project_event(work, 'v381_binary_asset_materialized', f'Materialized deterministic binary asset {rel} without a Qwen call.', file=rel)
                try: _v373_refresh_project_kb(work, manifest, reason='binary_asset_materialized', force=True)
                except Exception: pass
                _progress(progress_callback, f'V38.1 deterministic asset: {rel}', stage='generating')
                return True, rel
        except Exception as exc:
            _append_project_event(work, 'v381_binary_asset_failed', f'Deterministic asset generation failed for {rel}: {exc}', file=rel)
            return False, rel
    if ext in V381_FORBIDDEN_MODEL_BINARY_EXTS:
        _append_project_event(work, 'v381_binary_asset_blocked', f'Refused to send unsupported binary artifact {rel} to Qwen.', file=rel)
        return False, rel
    return _v381_prev_generate_planned_file(user_request, manifest, work, file_item, progress_callback)


_v381_prev_precommit_candidate_error = _v36_precommit_candidate_error

def _v36_precommit_candidate_error(work, rel, content):
    base = _v381_prev_precommit_candidate_error(work, rel, content)
    if base:
        return base
    rels = str(rel or '').replace('\\','/').strip('/')
    if Path(rels).name == 'Cargo.toml':
        text = str(content or '')
        # Exact real-run typo and close misspellings of sqlx's common Tokio runtime feature.
        for bad in re.findall(r'["\'](runtime-[A-Za-z0-9_-]+)["\']', text):
            low = bad.lower()
            if low.startswith('runtime-tok') and low not in {
                'runtime-tokio', 'runtime-tokio-native-tls', 'runtime-tokio-rustls'
            }:
                return f"V38.1 Cargo semantic gate: suspicious SQL/runtime feature {bad!r} in {rels}; likely expected 'runtime-tokio' (or a documented Cargo feature)."
    return ''


_v381_prev_candidate_transaction_error = _candidate_transaction_error

def _candidate_transaction_error(work, manifest, rel, content, user_request=None, validation_failure=None, target_problems=None):
    domain = _v381_candidate_domain_contract_error(manifest or {}, rel, content)
    if domain:
        return domain
    return _v381_prev_candidate_transaction_error(
        work, manifest, rel, content, user_request=user_request,
        validation_failure=validation_failure, target_problems=target_problems,
    )


def _v381_planned_symbol_contracts(manifest):
    rows = []
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item, dict):
            continue
        provider = str(item.get('path') or '').replace('\\','/').strip('/')
        scope = _v38_component_scope(manifest, provider)
        declared = []
        for symbol in _normalize_export_contract(item.get('exports')):
            symbol = _v381_clean_symbol_name(symbol)
            if symbol:
                declared.append((symbol, symbol, 'planned_export'))
        for line in item.get('contracts') or []:
            text = str(line or '').strip()
            m = re.search(r'(?i)\b(?:entity|model|interface|class|struct|enum)\s*:\s*([A-Za-z_][A-Za-z0-9_]*)\s*(\([^)]*\))?', text)
            if not m:
                m = re.search(r'(?i)\b(?:entity|model|interface|class|struct|enum)\s+([A-Za-z_][A-Za-z0-9_]*)\s*(\([^)]*\))?', text)
            if m:
                declared.append((m.group(1), m.group(1) + (m.group(2) or ''), 'planned_contract'))
        for symbol, signature, source in declared:
            rows.append({'scope': scope, 'symbol': symbol, 'provider': provider, 'signature': signature, 'source': source})
    # Domain contract pass is cross-component. It doesn't choose a provider by itself, but it gives a
    # pre-source signature that the component-local planned provider can inherit when names match.
    domain = (manifest or {}).get('canonical_domain_contracts') or {}
    domain_signatures = {}
    for ent in domain.get('entities') or []:
        if isinstance(ent, dict) and ent.get('name'):
            fields = [str(f.get('name') or '') for f in ent.get('fields') or [] if isinstance(f, dict) and f.get('name')]
            domain_signatures[str(ent.get('name'))] = f"{ent.get('name')}({', '.join(fields)})"
    for row in rows:
        if row['symbol'] in domain_signatures:
            row['signature'] = domain_signatures[row['symbol']]
            row['source'] = 'canonical_domain_contract'
    return rows


_v381_prev_refresh_project_kb = _v373_refresh_project_kb

def _v373_refresh_project_kb(work, manifest=None, reason='refresh', force=False):
    kb = _v381_prev_refresh_project_kb(work, manifest, reason, force)
    if not isinstance(kb, dict):
        return kb
    manifest = _v373_canonicalize_manifest_paths(manifest or _v373_load_work_manifest(work), (manifest or {}).get('_original_user_request') if isinstance(manifest, dict) else '', work=None) or {}
    graph = _v373_json_read(Path(work) / V36_REPO_GRAPH_FILE, {}) if Path(work, V36_REPO_GRAPH_FILE).exists() else {}
    candidates = []
    # Planned contracts populate memory BEFORE implementation.
    candidates.extend(_v381_planned_symbol_contracts(manifest))
    # Actual repo-graph symbols upgrade planned signatures as soon as accepted source exists.
    graph_files = graph.get('files') or {}
    if isinstance(graph_files, dict):
        for provider, info in graph_files.items():
            provider = _v373_canonical_manifest_rel(manifest, provider)
            scope = _v38_component_scope(manifest, provider)
            rank = float((info or {}).get('rank') or 0.0)
            for sym in (info or {}).get('symbols') or []:
                if not isinstance(sym, dict):
                    continue
                symbol = _v381_clean_symbol_name(sym.get('name'))
                if not symbol:
                    continue
                candidates.append({
                    'scope': scope, 'symbol': symbol, 'provider': provider,
                    'signature': str(sym.get('signature') or symbol), 'source': 'repo_graph', 'rank': rank,
                })
    groups = {}
    for row in candidates:
        key = (str(row.get('scope') or '.'), str(row.get('symbol') or ''))
        if key[1]:
            groups.setdefault(key, []).append(row)
    old = dict(kb.get('scoped_canonical_symbols') or {})
    scoped = {}
    conflicts = []
    for (scope, symbol), rows in groups.items():
        providers = list(dict.fromkeys(str(x.get('provider') or '') for x in rows if str(x.get('provider') or '')))
        planned = [x for x in rows if str(x.get('source') or '').startswith(('planned_', 'canonical_domain'))]
        actual = [x for x in rows if x.get('source') == 'repo_graph']
        preferred = ''
        # Architecture-owned provider beats incidental duplicate definitions; otherwise preserve the prior owner.
        if planned:
            preferred = str(planned[0].get('provider') or '')
        prev = old.get(f'{scope}::{symbol}') or {}
        if not preferred and str(prev.get('provider') or '') in providers:
            preferred = str(prev.get('provider'))
        if not preferred and providers:
            scored = sorted(rows, key=lambda x: (float(x.get('rank') or 0.0), 1 if x.get('source') == 'repo_graph' else 0), reverse=True)
            preferred = str(scored[0].get('provider') or providers[0])
        best = next((x for x in actual if x.get('provider') == preferred), None) or next((x for x in planned if x.get('provider') == preferred), None) or rows[0]
        key = f'{scope}::{symbol}'
        scoped[key] = {
            'scope': scope, 'symbol': symbol, 'provider': preferred,
            'signature': str(best.get('signature') or symbol), 'source': str(best.get('source') or ''),
            'providers': providers, 'conflict': len(providers) > 1,
            'state': 'implemented' if any(x.get('source') == 'repo_graph' and x.get('provider') == preferred for x in rows) else 'planned',
        }
        if len(providers) > 1:
            conflicts.append({'scope': scope, 'symbol': symbol, 'canonical_provider': preferred, 'providers': providers})
    kb['scoped_canonical_symbols'] = scoped
    kb['provider_conflicts'] = conflicts[:400]
    # Global table is intentionally conservative: only symbols with one scoped owner are globally unambiguous.
    by_symbol = {}
    for row in scoped.values():
        by_symbol.setdefault(row['symbol'], []).append(row)
    kb['canonical_symbols'] = {
        symbol: dict(rows[0]) for symbol, rows in by_symbol.items() if len(rows) == 1
    }
    kb['canonical_domain_contracts'] = (manifest or {}).get('canonical_domain_contracts') or {}
    kb['version'] = V381_VERSION
    kb['engine'] = 'SMALL_MODEL_CONVERGENCE_FACTORY'
    kb['canonical_memory_rule'] = 'Architecture/domain contracts establish planned ownership before source generation; accepted repo-graph symbols upgrade, but do not silently redefine, that ownership.'
    try:
        _v373_atomic_json_write(_v373_kb_path(work), kb)
    except Exception:
        pass
    return kb


_v381_prev_execute_manifest = _v362_execute_manifest

def _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback=None, raw_plan=''):
    manifest = dict(manifest or {})
    manifest['canonical_domain_contracts'] = manifest.get('canonical_domain_contracts') or {}
    if _v381_is_tauri_request(user_request):
        topology = _v381_tauri_topology_issues(manifest, user_request)
        if topology:
            msg = 'V38.1 refused implementation because Tauri topology is not canonical: ' + '; '.join(topology)
            _append_project_event(work, 'v381_tauri_topology_blocked', msg, issues=topology)
            return False, {'_jarvis_architecture_blocked': True, '_jarvis_architecture_error': msg}, [], msg
    try:
        Path(work, V381_DOMAIN_CONTRACTS_FILE).write_text(json.dumps(manifest.get('canonical_domain_contracts') or {}, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        pass
    return _v381_prev_execute_manifest(user_request, manifest, work, max_files, progress_callback, raw_plan)


# Keep V38.1 internal memory/spec files out of user-facing project ZIPs.
_v381_prev_package_workspace_zip = _package_workspace_zip

def _package_workspace_zip(work, name_stem, stamp=None):
    root = Path(work)
    hidden = []
    for name in (V381_DOMAIN_CONTRACTS_FILE,):
        p = root / name
        if p.exists():
            try:
                tmp = root / '.jarvis_build' / name
                tmp.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(p, tmp); p.unlink(); hidden.append((p, tmp))
            except Exception:
                pass
    try:
        return _v381_prev_package_workspace_zip(work, name_stem, stamp)
    finally:
        for p, tmp in hidden:
            try:
                if tmp.exists(): shutil.copy2(tmp, p); tmp.unlink()
            except Exception:
                pass


