def _progress(callback, text=None, **fields):
    if text is not None:
        text = str(text)
        for old in ('V38.0.0', 'V38', 'V37.3', 'V37.2', 'V37.1', 'V37', 'V36.2', 'V36.1', 'V36', 'V35.1', 'V35', 'V34.1', 'V34'):
            text = text.replace(old, 'V38.1')
