# Final provider wrapper only changes the visible role/version label; the bounded V38 behavior remains.
_v381_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    stage_text = re.sub(r'V38(?:\.0\.0)?(?!\.1)', 'V38.1', str(stage or ''))
    body = str(prompt or '').replace('JARVIS V38 ROLE:', 'JARVIS V38.1 ROLE:')
    body = re.sub(r'V38(?:\.0\.0)?(?!\.1)(?=\s)', 'V38.1', body)
    return _v381_prev_qwen_call(body, progress_callback, stage_text, profile=profile, **kwargs)

# ---- V38.1.1 tolerant component-local path normalization -------------------
# Small models may understand the topology but still prefix a component path with words like
# frontend/ or backend/. Normalize those harmless path-shape mistakes before the topology gate.
_v381_prev_normalize_component_files = _v362_normalize_component_files

def _v362_normalize_component_files(obj, component, max_files):
    comp = dict(component or {})
    cid = str(comp.get('id') or '').lower()
    root = str(comp.get('root') or '.').replace('\\','/').strip('/') or '.'
    purpose = str(comp.get('purpose') or '').lower()
    if cid not in {'ui', 'tauri-core'} and 'canonical react/typescript/vite desktop ui' not in purpose and 'canonical rust/tauri backend' not in purpose:
        return _v381_prev_normalize_component_files(obj, component, max_files)
    patched = dict(obj or {})
    rows = []
    for raw in (obj or {}).get('files') or []:
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        path = str(item.get('path') or '').replace('\\','/').strip('/')
        deps = [str(x or '').replace('\\','/').strip('/') for x in item.get('depends_on') or []]
        def canon_path(p):
            p = str(p or '').replace('\\','/').strip('/')
            if cid == 'ui' or root == '.':
                for prefix in ('frontend/', 'app/', 'ui/'):
                    if p.lower().startswith(prefix):
                        tail = p[len(prefix):]
                        if tail.lower().startswith(('src/', 'public/', 'tests/')) or Path(tail).name.lower() in {
                            'package.json','package-lock.json','pnpm-lock.yaml','yarn.lock','index.html','vite.config.ts','vite.config.js',
                            'vitest.config.ts','vitest.config.js','tsconfig.json','tsconfig.app.json','tsconfig.node.json'
                        }:
                            p = tail
                            break
                return p
            # canonical Rust root
            low = p.lower()
            idx = low.find('src-tauri/')
            if idx >= 0:
                return p[idx:]
            for prefix in ('backend/', 'native/', 'rust/', 'shared/'):
                if low.startswith(prefix):
                    p = p[len(prefix):]
                    break
            if p == 'Cargo.toml' or p.startswith(('src/', 'tests/', 'migrations/', 'icons/')) or Path(p).name == 'tauri.conf.json':
                return 'src-tauri/' + p
            if not p.startswith('src-tauri/'):
                return 'src-tauri/' + p
            return p
        item['path'] = canon_path(path)
        item['depends_on'] = [canon_path(d) for d in deps if d]
        rows.append(item)
    patched['files'] = rows
    # root is already represented by normalized paths; sanitize without the old root-prefixing step.
    return _sanitize_manifest_files(rows, max_files)


# ---- Canonical Tauri manifest contract checks -------------------------------
def _v381_tauri_manifest_candidate_error(manifest, rel, content):
    request = str((manifest or {}).get('_original_user_request') or '')
    if not _v381_is_tauri_request(request):
        return ''
    rel = str(rel or '').replace('\\','/').strip('/')
    if rel == 'package.json':
        try:
            data = json.loads(str(content or ''))
        except Exception:
            return ''  # strict JSON gate owns syntax failures
        deps = {}
        for key in ('dependencies', 'devDependencies', 'optionalDependencies'):
            deps.update(data.get(key) or {})
        missing = [x for x in ('@tauri-apps/api', '@tauri-apps/cli') if x not in deps]
        scripts = data.get('scripts') or {}
        if '@tauri-apps/cli' in missing:
            # CLI belongs in devDependencies, but report one concise root-cause error.
            pass
        if missing:
            return 'V38.1 Tauri manifest gate: package.json is missing required Tauri package(s): ' + ', '.join(missing) + '. Keep React/Vite dependencies and add the Tauri API/CLI instead of creating another application root.'
        if not any(str(k).lower() == 'tauri' or 'tauri' in str(v).lower() for k, v in scripts.items()):
            return "V38.1 Tauri manifest gate: package.json needs a Tauri CLI script (for example `\"tauri\": \"tauri\"`) so setup/run launchers can invoke the desktop app."
    elif rel == 'src-tauri/Cargo.toml':
        text = str(content or '')
        try:
            import tomllib
            data = tomllib.loads(text)
        except Exception:
            return ''
        deps = data.get('dependencies') or {}
        if 'tauri' not in deps:
            return "V38.1 Tauri manifest gate: src-tauri/Cargo.toml must declare the `tauri` crate; this is the canonical native backend, not a standalone generic Rust app."
    return ''


_v3811_prev_candidate_transaction_error = _candidate_transaction_error

def _candidate_transaction_error(work, manifest, rel, content, user_request=None, validation_failure=None, target_problems=None):
    manifest = dict(manifest or {})
    if user_request and not manifest.get('_original_user_request'):
        manifest['_original_user_request'] = str(user_request)
    terr = _v381_tauri_manifest_candidate_error(manifest, rel, content)
    if terr:
        return terr
    return _v3811_prev_candidate_transaction_error(
        work, manifest, rel, content, user_request=user_request,
        validation_failure=validation_failure, target_problems=target_problems,
    )

