_v40_prev_progress = _progress

def _progress(callback, text=None, **fields):
    if text is not None:
        text=str(text).replace('V39','V40').replace('V38.1','V40').replace('V38','V40')
    return _v40_prev_progress(callback,text,**fields)


_v40_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    body=str(prompt or '')
    body += (
        '\n\nV40 UNIVERSAL OWNERSHIP RULE: Canonical domain contracts have one OWNER per component/language. '
        'If the target file is an owner, define the exact frozen shape. If it is a consumer (UI, service, repository, route, test, command), '
        'IMPORT/USE the canonical definition and do not redefine it. Cross-language components may each have their own serialization-compatible owner. '
        'Work only against files materialized in the current milestone and the authoritative Project KB. Prefer actual compiler/test evidence over guesses.'
    )
    return _v40_prev_qwen_call(body,progress_callback,str(stage or '').replace('V39','V40').replace('V38.1','V40').replace('V38','V40'),profile=profile,**kwargs)


# Keep V40 ownership diagnostics out of the final user project ZIP.
_v40_prev_package_workspace_zip = _package_workspace_zip

def _package_workspace_zip(work, name_stem, stamp=None):
    root=Path(work); hidden=[]
    for name in (V40_OWNER_MEMORY_FILE,):
        p=root/name
        if p.exists():
            try:
                tmp=root/'.jarvis_build'/name; tmp.parent.mkdir(parents=True,exist_ok=True)
                shutil.copy2(p,tmp); p.unlink(); hidden.append((p,tmp))
            except Exception:pass
    try:return _v40_prev_package_workspace_zip(work,name_stem,stamp)
    finally:
        for p,tmp in hidden:
            try:
                if tmp.exists():shutil.copy2(tmp,p);tmp.unlink()
            except Exception:pass

# Empty text files can be semantically complete (notably Python package markers and a project with
# no third-party requirements). Do not keep a milestone red just because such a file has zero bytes.
_v40_prev_file_is_implemented = _v39_file_is_implemented

def _v39_file_is_implemented(work, rel):
    p=Path(work)/str(rel)
    if p.exists() and p.is_file() and p.stat().st_size == 0:
        name=p.name.lower()
        if name == '__init__.py' or name in {'requirements.txt','requirements-dev.txt','.gitkeep'}:
            return True
    return _v40_prev_file_is_implemented(work,rel)

# =============================================================================
# V40.1 CONVERGENCE / COMMIT-GATE HARDENING
# =============================================================================
# Lessons from the final V39 GearTrack run:
# - Foundation is substrate + a genuinely dependency-closed boot shell, never the full app.
# - current-milestone files are generated directly; contract skeletons are not materialized first.
# - every generation/repair result must pass one deterministic commit/green gate.
# - a "repairable bootstrap candidate" is intermediate evidence, never success by itself.
# - architecture metadata must never overwrite the actual canonical-domain contract object.
# - casual one-paragraph prompts are deterministically atomized into independently traceable requirements.
# - failure reporting distinguishes planning, milestone, build/test, acceptance, and packaging stages.

V401_VERSION = '40.1.0'
V401_ENGINE = 'UNIVERSAL_MILESTONE_CONVERGENCE_FACTORY'
V401_NO_CURRENT_SKELETONS = os.getenv('JARVIS_V401_NO_CURRENT_SKELETONS', '1').strip().lower() not in {'0','false','no','off'}
V401_CENTRAL_COMMIT_GATE = os.getenv('JARVIS_V401_CENTRAL_COMMIT_GATE', '1').strip().lower() not in {'0','false','no','off'}
V401_ATOMIC_REQUIREMENTS = os.getenv('JARVIS_V401_ATOMIC_REQUIREMENTS', '1').strip().lower() not in {'0','false','no','off'}
V401_MAX_ATOMIC_REQUIREMENTS = max(40, int(os.getenv('JARVIS_V401_MAX_ATOMIC_REQUIREMENTS', '320')))
V401_MAX_FOUNDATION_SOURCE_FILES = max(1, int(os.getenv('JARVIS_V401_MAX_FOUNDATION_SOURCE_FILES', '6')))

# Keep inherited milestone/status functions coherent with the final release identity.
V40_VERSION = V401_VERSION
V39_VERSION = V401_VERSION
V39_ENGINE = V401_ENGINE


def _v401_is_textual_empty_allowed(rel):
    name = Path(str(rel or '')).name.lower()
    return name == '__init__.py' or name in {'requirements.txt','requirements-dev.txt','.gitkeep'}


def _v401_file_green_error(work, manifest, rel):
    """Single deterministic source-of-truth for whether one live file may be called accepted/green.

    This intentionally does not run a whole-project compiler.  It is the commit gate for a candidate;
    milestone/component build-test gates remain the authority for executable integration evidence.
    """
    rel = _v40_norm_rel(rel)
    path = Path(work) / rel
    if not path.exists() or not path.is_file():
        return 'candidate was not materialized to the live workspace'
    if _v39_binary_asset_rel(rel):
        return '' if path.stat().st_size > 0 else 'binary artifact is empty'
    if not _looks_text_file(path):
        return '' if path.stat().st_size > 0 else 'generated artifact is empty'
    try:
        text = path.read_text(encoding='utf-8', errors='replace')
    except Exception as exc:
        return f'could not read committed candidate: {exc}'
    if V33_SKELETON_MARKER in text or V34_RECOVERY_SEED_MARKER in text:
        return 'contract/recovery skeleton is intermediate source, not an accepted implementation'
    if not text.strip() and not _v401_is_textual_empty_allowed(rel):
        return 'generated text file is empty'
    syntax = _content_validation_error(rel, text)
    if syntax:
        return str(syntax)
    try:
        tx = _candidate_transaction_error(
            work, manifest or {}, rel, text,
            user_request=(manifest or {}).get('_original_user_request') or '',
            validation_failure='', target_problems=[]
        )
        if tx:
            return str(tx)
    except Exception as exc:
        # The commit validator itself must never kill a project.  A validator exception is evidence
        # that the candidate cannot safely be called green until the deterministic path is healthy.
        return f'commit validator exception: {exc}'
    try:
        for row in _v361_current_file_foundation_issues(work, manifest or {}, rel) or []:
            file_name = _v40_norm_rel(row.get('file') or rel)
            provider = _v40_norm_rel(row.get('provider_file') or '')
            if file_name == rel or provider == rel:
                problem = str(row.get('problem') or '').strip()
                if problem:
                    return problem
    except Exception as exc:
        return f'foundation/contract validator exception: {exc}'
    return ''


def _v401_snapshot_file(path):
    path = Path(path)
    if not path.exists() or not path.is_file():
        return {'exists': False, 'bytes': b''}
    try:
        return {'exists': True, 'bytes': path.read_bytes()}
    except Exception:
        return {'exists': True, 'bytes': b''}


def _v401_restore_file(path, snap):
    path = Path(path)
    try:
        if snap.get('exists'):
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(snap.get('bytes') or b'')
        elif path.exists():
            path.unlink()
    except Exception:
        pass


# ---- One commit/green gate for full generations --------------------------------
_v401_prev_generate_planned_file = _generate_planned_file

def _generate_planned_file(user_request, manifest, work, file_item, progress_callback=None):
    rel = _v40_norm_rel((file_item or {}).get('path'))
    target = Path(work) / rel
    snap = _v401_snapshot_file(target)
    try:
        ok, wrote = _v401_prev_generate_planned_file(user_request, manifest, work, file_item, progress_callback)
    except Exception as exc:
        _v401_restore_file(target, snap)
        _append_project_event(work, 'v401_generation_exception', f'Generation failed safely for {rel}.', file=rel, error=str(exc))
        return False, rel
    if not V401_CENTRAL_COMMIT_GATE:
        return ok, wrote
    err = _v401_file_green_error(work, manifest, rel) if target.exists() else 'candidate was not materialized'
    if ok and not err:
        _append_project_event(work, 'v401_commit_gate_pass', f'Central commit gate accepted {rel}.', file=rel)
        return True, wrote or rel
    # Bootstrap/recovery may have placed repairable intermediate source in the live tree.  Never let
    # that become authoritative memory or a green milestone task; restore the last accepted state.
    _v401_restore_file(target, snap)
    _append_project_event(
        work, 'v401_commit_gate_rejected', f'Central commit gate rejected {rel}; live state restored.',
        file=rel, previous_result=bool(ok), validation_error=err or 'underlying generation reported failure'
    )
    return False, wrote or rel


# ---- One commit/green gate for edits/repairs -----------------------------------
_v401_prev_repair_file_for_issues = _repair_file_for_issues

def _repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback=None, validation_failure=None):
    rel = _v40_norm_rel(rel)
    target = Path(work) / rel
    snap = _v401_snapshot_file(target)
    try:
        ok = _v401_prev_repair_file_for_issues(
            user_request, manifest, work, rel, problems, progress_callback,
            validation_failure=validation_failure
        )
    except Exception as exc:
        _v401_restore_file(target, snap)
        _append_project_event(work, 'v401_repair_exception', f'Repair failed safely for {rel}.', file=rel, error=str(exc))
        return False
    if not V401_CENTRAL_COMMIT_GATE:
        return bool(ok)
    err = _v401_file_green_error(work, manifest, rel) if target.exists() else 'repair removed or failed to materialize the target file'
    if ok and not err:
        _append_project_event(work, 'v401_commit_gate_pass', f'Central commit gate accepted repair for {rel}.', file=rel)
        return True
    _v401_restore_file(target, snap)
    if ok or err:
        _append_project_event(
            work, 'v401_commit_gate_rejected', f'Central commit gate rejected repair for {rel}; live state restored.',
            file=rel, previous_result=bool(ok), validation_error=err or 'underlying repair reported failure'
        )
    return False


# ---- Do not create current-milestone skeleton files -----------------------------
_v401_prev_milestone_manifest = _v39_milestone_manifest

def _v39_milestone_manifest(manifest, active_paths):
    scoped = _v401_prev_milestone_manifest(manifest, active_paths)
    scoped['_v401_current_milestone_scope'] = True
    return scoped


_v401_prev_materialize_contract_skeletons = _v33_materialize_contract_skeletons

def _v33_materialize_contract_skeletons(work, manifest, progress_callback=None):
    if V401_NO_CURRENT_SKELETONS and isinstance(manifest, dict) and manifest.get('_v401_current_milestone_scope'):
        _append_project_event(
            work, 'v401_current_skeletons_skipped',
            'Current milestone will be generated directly from manifest/Project-KB contracts; no contract skeleton files were pre-created.'
        )
        return []
    return _v401_prev_materialize_contract_skeletons(work, manifest, progress_callback)


# ---- Skeleton/missing files use full generation, implemented files use edits ----
_v401_prev_repair_milestone = _v39_repair_milestone

def _v39_repair_milestone(user_request, manifest, work, milestone, progress_callback=None):
    paths = list((milestone or {}).get('files') or [])
    item_map = {str(x.get('path') or ''): dict(x) for x in (manifest or {}).get('files') or [] if isinstance(x, dict)}
    for round_no in range(1, V39_MILESTONE_REPAIR_ROUNDS + 1):
        issues = _v39_milestone_issues(work, manifest, paths)
        if not issues:
            return True, []
        by_file = {}
        for row in issues:
            by_file.setdefault(str(row.get('file') or ''), []).append(row)
        changed = False
        for rel, rows in list(by_file.items())[:10]:
            if not rel or _v39_binary_asset_rel(rel):
                continue
            target = Path(work) / rel
            kinds = {str(x.get('kind') or '') for x in rows}
            is_skeleton = False
            if target.exists() and target.is_file() and _looks_text_file(target):
                try:
                    txt = target.read_text(encoding='utf-8', errors='replace')
                    is_skeleton = V33_SKELETON_MARKER in txt or V34_RECOVERY_SEED_MARKER in txt
                except Exception:
                    pass
            # Missing/skeleton files have no trustworthy old source to patch. Generate the entire file
            # from current milestone contracts/KB instead of burning SEARCH/REPLACE retries on a marker.
            if not target.exists() or is_skeleton or 'missing' in kinds or 'skeleton' in kinds:
                item = item_map.get(rel) or {
                    'path': rel, 'purpose': 'Current milestone implementation', 'phase': 'integration',
                    'depends_on': [], 'exports': [], 'contracts': []
                }
                _progress(
                    progress_callback,
                    f'V40.1 milestone full generation {round_no}/{V39_MILESTONE_REPAIR_ROUNDS}: {rel}',
                    stage='generating', milestone=(milestone or {}).get('id')
                )
                ok, _ = _generate_planned_file(user_request, manifest, work, item, progress_callback)
                changed = changed or bool(ok)
                continue
            problems = [str(x.get('problem') or '') for x in rows if str(x.get('problem') or '').strip()]
            _progress(
                progress_callback,
                f'V40.1 milestone targeted repair {round_no}/{V39_MILESTONE_REPAIR_ROUNDS}: {rel}',
                stage='repairing', milestone=(milestone or {}).get('id')
            )
            try:
                if _repair_file_for_issues(
                    user_request, manifest, work, rel, problems, progress_callback,
                    validation_failure='\n'.join(problems)
                ):
                    changed = True
            except Exception as exc:
                _append_project_event(work, 'v401_milestone_repair_exception', f'Milestone repair failed safely for {rel}.', file=rel, error=str(exc))
        try:
            _v373_refresh_project_kb(work, manifest, reason=f'v401_milestone_repair_{(milestone or {}).get("id")}', force=True)
        except Exception:
            pass
        final_now = _v39_milestone_issues(work, manifest, paths)
        if not final_now:
            return True, []
        if not changed:
            return False, final_now
    final = _v39_milestone_issues(work, manifest, paths)
    return not final, final


# ---- Deterministically atomize conversational requirements ----------------------
_v401_prev_extract_source_requirements = _v361_extract_source_requirements

_V401_REQ_ACTIONS = {
    'add','create','make','build','develop','implement','edit','update','delete','remove','view','show','display','list',
    'search','filter','sort','organize','group','track','check','checkout','return','assign','unassign','import','export',
    'save','store','persist','load','open','close','start','launch','run','compile','test','validate','verify','calculate',
    'support','include','allow','prevent','reject','handle','keep','use','work','package','install','record','manage','sync',
}


def _v401_req_category(text):
    low = str(text or '').lower()
    if any(x in low for x in ('compile','build','test','tests pass','starts correctly','launch','package','zip','verify','validation')):
        return 'acceptance'
    if any(x in low for x in ('use react','use rust','use python','use java','use kotlin','use c#','use c++','use go','sqlite','offline','windows','linux','macos','framework','language')):
        return 'constraint'
    return 'functional'


def _v401_requirementish(fragment):
    low = str(fragment or '').lower().strip()
    if len(low) < 3:
        return False
    words = set(re.findall(r'[a-z][a-z0-9_-]*', low))
    if words & _V401_REQ_ACTIONS:
        return True
    if re.search(r'\b(?:must|should|needs? to|has to|able to|do not|cannot|can\'t|with|without)\b', low):
        return True
    # Dashboard/report metric fragments are requirements even when they are noun phrases.
    if any(x in low for x in ('total','overdue','recent activity','history','balance','status','condition','location','category','budget','dashboard')):
        return True
    return False


def _v401_atomic_fragments(user_request):
    text = str(user_request or '').replace('\r', '\n')
    text = re.sub(r'[\t ]+', ' ', text)
    # Preserve path-like slash tokens but make common action lists such as add/edit/delete independently visible.
    text = re.sub(r'\b(add|edit|delete|create|update|import|export|build|test)/(?=[A-Za-z])', r'\1, ', text, flags=re.I)
    sentences = [x.strip(' \t\n-•') for x in re.split(r'(?<=[.!?])\s+|\n+', text) if x.strip()]
    out = []

    def add(value, prefix=''):
        value = re.sub(r'\s+', ' ', str(value or '')).strip(' ,;:.')
        value = re.sub(r'^(?:and|also|plus|then)\s+', '', value, flags=re.I)
        if prefix and value and not re.match(r'(?i)^(?:i |users? |the |it |app |application |jarvis |qwen |make |build |use )', value):
            value = prefix + value
        if _v401_requirementish(value) and 3 <= len(value) <= V37_REQUIREMENT_ITEM_MAX_CHARS:
            out.append(value)

    for sentence in sentences:
        # First preserve the sentence when it is independently meaningful.
        add(sentence)
        low = sentence.lower()
        # User-style capability lists: "I want to add..., organize..., search..., check..., ..."
        m = re.search(r'(?i)\b(?:i\s+want\s+to|users?\s+(?:must\s+)?be\s+able\s+to|should\s+be\s+able\s+to)\s+(.+)', sentence)
        if m:
            body = m.group(1)
            for part in re.split(r'\s*;\s*|\s*,\s*(?=(?:and\s+)?[A-Za-z])', body):
                add(part, 'Users must be able to ')
        # General comma/semicolon clauses with an explicit action/modality.
        for part in re.split(r'\s*;\s*|\s*,\s*', sentence):
            if part != sentence:
                add(part)
        # Metrics after "dashboard with" / "report with" are independently testable output requirements.
        dm = re.search(r'(?i)\b(dashboard|report(?:s)?)\s+with\s+(.+)', sentence)
        if dm:
            subject = dm.group(1).capitalize()
            tail = dm.group(2)
            # Strip trailing capability clause beginning with a clear action such as import/export.
            tail = re.split(r'(?i)\s*,\s*(?:and\s+)?(?=import\b|export\b|build\b|test\b|keep\b)', tail)[0]
            for metric in re.split(r'\s*,\s*|\s+and\s+', tail):
                metric = metric.strip(' ,;.')
                if metric:
                    add(f'{subject} includes {metric}')
    return out


def _v361_extract_source_requirements(user_request):
    base = list(_v401_prev_extract_source_requirements(user_request) or [])
    if not V401_ATOMIC_REQUIREMENTS:
        return base
    rows = []
    seen = set()

    def add(text, category='functional'):
        clean = _v361_clean_req_text(text)
        if not clean or len(clean) < 2:
            return
        key = re.sub(r'\W+', ' ', clean.lower()).strip()
        if not key or key in seen:
            return
        seen.add(key)
        rows.append({'id':'', 'category':category, 'text':clean[:V37_REQUIREMENT_ITEM_MAX_CHARS], 'key':key})

    for item in base:
        if isinstance(item, dict):
            add(item.get('text') or '', item.get('category') or _v401_req_category(item.get('text') or ''))
    for fragment in _v401_atomic_fragments(user_request):
        add(fragment, _v401_req_category(fragment))
    for i, row in enumerate(rows[:V401_MAX_ATOMIC_REQUIREMENTS], 1):
        row['id'] = f'UR-{i:03d}'
    return rows[:V401_MAX_ATOMIC_REQUIREMENTS]


# ---- Smaller Foundation: substrate + only dependency-closed boot source --------
_v401_prev_build_milestones = _v39_build_milestones

def _v401_boot_source_candidate(item):
    rel = _v40_norm_rel((item or {}).get('path')).lower()
    name = Path(rel).name.lower()
    # App/View/Screen files are integration/feature code, not Foundation entrypoints.
    if name in {'app.tsx','app.jsx','app.ts','app.js','app.vue','app.svelte'}:
        return False
    return _v39_is_entrypoint(item) and name in {
        'main.py','main.rs','lib.rs','main.tsx','main.ts','main.jsx','main.js','index.tsx','index.ts','index.jsx','index.js','program.cs'
    }


def _v39_build_milestones(manifest, user_request=''):
    manifest = dict(manifest or {})
    files = [dict(x) for x in (manifest.get('files') or []) if isinstance(x, dict) and x.get('path')]
    if not files:
        return []
    item_map = {str(x.get('path') or ''): x for x in files}
    domains = _v39_domain_names(manifest, user_request)
    groups = []
    assigned = set()

    def add_group(mid, title, rows, kind='feature'):
        clean = []
        for r in rows:
            p = str(r.get('path') or '')
            if p and p not in assigned:
                assigned.add(p); clean.append(r)
        if clean:
            groups.append({'id':mid,'title':title,'kind':kind,'files':[str(r.get('path') or '') for r in clean]})

    # Intrinsic Foundation is build/config/storage substrate only.  Add a tiny boot source only when
    # its DECLARED dependencies are already inside Foundation, preventing App/UI feature trees from
    # being dragged into milestone 1 by dependency promotion.
    foundation_rows = [x for x in files if _v39_is_foundation_item(x)]
    foundation_paths = {str(x.get('path') or '') for x in foundation_rows}
    boot_rows = []
    for item in files:
        if len(boot_rows) >= V401_MAX_FOUNDATION_SOURCE_FILES:
            break
        rel = str(item.get('path') or '')
        if rel in foundation_paths or not _v401_boot_source_candidate(item):
            continue
        deps = set(_v33_normalize_dep_paths(item.get('depends_on') or [], rel))
        if not deps or deps.issubset(foundation_paths):
            boot_rows.append(item); foundation_paths.add(rel)
    add_group('foundation', 'Project foundation and build substrate', foundation_rows + boot_rows, 'foundation')

    # Domain vertical slices.
    for domain in domains:
        pat = re.compile(r'(?<![a-z0-9])' + re.escape(domain) + r's?(?![a-z0-9])', re.I)
        rows = [x for x in files if str(x.get('path') or '') not in assigned and pat.search(_v39_file_blob(x))]
        add_group(f'feature-{_slug(domain)}', f'{domain.title()} vertical feature', rows, 'feature')

    # Cross-cutting capabilities.
    caps = []
    for item in files:
        if str(item.get('path') or '') in assigned:
            continue
        cap = _v39_capability_name(item)
        if cap and cap not in caps:
            caps.append(cap)
    for cap in caps[:6]:
        rows = [x for x in files if str(x.get('path') or '') not in assigned and _v39_capability_name(x) == cap]
        add_group(f'cap-{_slug(cap)}', cap.replace('-', ' ').title(), rows, 'feature')

    # Integration/UI shells and any entrypoints not safe for the Foundation bootstrap.
    integration = [x for x in files if str(x.get('path') or '') not in assigned and (
        _v39_is_entrypoint(x) or str(x.get('phase') or '').lower() in {'ui','integration'}
    )]
    add_group('integration', 'Application integration and UI shell', integration, 'integration')

    tests = [x for x in files if str(x.get('path') or '') not in assigned and (
        str(x.get('phase') or '').lower() == 'test' or _v38_is_testish(str(x.get('path') or ''))
    )]
    add_group('verification', 'Cross-feature verification', tests, 'test')
    docs = [x for x in files if str(x.get('path') or '') not in assigned and str(x.get('phase') or '').lower() == 'docs']
    add_group('delivery', 'Documentation and delivery', docs, 'docs')
    remaining = [x for x in files if str(x.get('path') or '') not in assigned]
    add_group('remaining-integration', 'Remaining planned integration', remaining, 'integration')

    # Merge tiny adjacent feature groups, but never merge Foundation/test/integration barriers.
    compact = []
    for group in groups:
        if compact and len(group['files']) <= 1 and len(compact[-1]['files']) < 8 and group['kind'] == 'feature' and compact[-1].get('kind') == 'feature':
            compact[-1]['files'].extend(group['files']); compact[-1]['title'] += ' + ' + group['title']
        else:
            compact.append(group)
    groups = compact

    if len(groups) > V39_MAX_MILESTONES:
        overflow = []
        for g in groups[V39_MAX_MILESTONES-1:]: overflow.extend(g['files'])
        groups = groups[:V39_MAX_MILESTONES-1] + [{
            'id':'final-integration','title':'Final integration','kind':'integration','files':list(dict.fromkeys(overflow))
        }]

    # Dependency closure.  Never pull a feature provider INTO Foundation.  If a Foundation boot file
    # depends on later source, move that CONSUMER out to the provider's milestone.  Everywhere else,
    # provider-before-consumer promotion remains useful.
    loops = 0; changed = True
    while changed and loops < 30:
        changed = False; loops += 1
        owner = {p:i for i,g in enumerate(groups) for p in g['files']}
        for ci, group in list(enumerate(groups)):
            for rel in list(group['files']):
                item = item_map.get(rel) or {}
                for dep in _v33_normalize_dep_paths(item.get('depends_on') or [], rel):
                    di = owner.get(str(dep or ''))
                    if di is None or di <= ci:
                        continue
                    if ci == 0 and group.get('kind') == 'foundation':
                        # Move the source consumer out of Foundation rather than dragging the app into it.
                        try: group['files'].remove(rel)
                        except ValueError: pass
                        if rel not in groups[di]['files']:
                            groups[di]['files'].append(rel)
                        changed = True
                        break
                    try: groups[di]['files'].remove(dep)
                    except ValueError: pass
                    if dep not in group['files']:
                        group['files'].insert(0, dep); changed = True
                if changed:
                    break
            if changed:
                break
        groups = [g for g in groups if g.get('files')]

    # Every file exactly once.
    seen = set()
    for g in groups:
        dedup=[]
        for p in g.get('files') or []:
            if p not in seen:
                dedup.append(p); seen.add(p)
        g['files']=dedup
    missing=[str(x.get('path') or '') for x in files if str(x.get('path') or '') not in seen]
    if missing:
        groups.append({'id':'final-unclassified','title':'Final planned files','kind':'integration','files':missing})
    for i,g in enumerate(groups,1):
        g['index']=i; g['status']='planned'; g['green_checkpoint']=''
    return groups


