# ---- Preserve the domain-contract object in persisted architecture -------------
_v401_prev_release_identity = _v36_release_identity

def _v36_release_identity():
    data = dict(_v401_prev_release_identity() or {})
    # The previous V39 feature flag used the same key as the actual contract object and could overwrite it.
    data.pop('canonical_domain_contracts', None)
    data.update({
        'version': V401_VERSION,
        'engine': V401_ENGINE,
        'planner_mode': 'universal-milestone-convergence-v40.1',
        'canonical_domain_contracts_enabled': True,
        'ownership_aware_contracts': True,
        'minimal_foundation_milestone': True,
        'current_milestone_skeletons_disabled': V401_NO_CURRENT_SKELETONS,
        'central_commit_gate': V401_CENTRAL_COMMIT_GATE,
        'atomic_source_requirement_ledger': V401_ATOMIC_REQUIREMENTS,
        'failure_stage_reporting': True,
    })
    return data


_v401_prev_arch_writer = _v33_write_architecture

def _v33_write_architecture(work, manifest):
    contract_obj = (manifest or {}).get('canonical_domain_contracts')
    _v401_prev_arch_writer(work, manifest)
    try:
        p = Path(work) / V33_ARCHITECTURE_FILE
        data = json.loads(p.read_text(encoding='utf-8', errors='replace')) if p.exists() else {}
        # Apply release metadata without allowing a boolean feature flag to destroy the real contract payload.
        meta = _v36_release_identity()
        meta.pop('canonical_domain_contracts', None)
        data.update(meta)
        if isinstance(contract_obj, dict):
            data['canonical_domain_contracts'] = contract_obj
        elif isinstance(data.get('canonical_domain_contracts'), bool):
            data['canonical_domain_contracts'] = {}
        data['canonical_domain_contracts_enabled'] = True
        data['version'] = V401_VERSION
        data['engine'] = V401_ENGINE
        data['planner_mode'] = 'universal-milestone-convergence-v40.1'
        p.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')
    except Exception:
        pass


# ---- Failure-stage classification for honest user-visible diagnostics ----------
_v401_prev_execute_manifest = _v362_execute_manifest

def _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback=None, raw_plan=''):
    result = _v401_prev_execute_manifest(user_request, manifest, work, max_files, progress_callback, raw_plan)
    try:
        ok, obj, candidates, raw = result
    except Exception:
        return result
    if not ok and isinstance(obj, dict):
        detail = str(obj.get('_jarvis_architecture_error') or raw or '')
        low = detail.lower()
        if 'milestone blocked' in low or 'could not reach deterministic green' in low:
            stage = 'milestone'
        elif 'build/test' in low or 'build test' in low or 'component failed real build' in low or 'component_validation' in low:
            stage = 'build_test'
        elif 'acceptance' in low:
            stage = 'acceptance'
        elif 'packag' in low:
            stage = 'packaging'
        else:
            stage = 'planning'
        obj['_jarvis_failure_stage'] = stage
        obj['_jarvis_execution_blocked'] = stage != 'planning'
        obj['_jarvis_failure_detail'] = detail
    return ok, obj, candidates, raw


