_v401_prev_progress = _progress

def _progress(callback, text=None, **fields):
    if text is not None:
        text = str(text)
        for old in ('V40.0','V40','V39','V38.1','V38'):
            text = text.replace(old, 'V40.1')
    return _v401_prev_progress(callback, text, **fields)


_v401_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    body = str(prompt or '') + (
        '\n\nV40.1 CONVERGENCE RULE: A file is not accepted merely because source was materialized. '
        'Only the central commit gate may make it authoritative. Missing/skeleton files are generated whole; '
        'implemented files use revision-bound targeted edits. Foundation must remain a minimal build/storage substrate, '
        'and no early boot shell may import future feature files. Use the frozen atomic requirement ledger and current Project KB.'
    )
    stage_text = str(stage or '').replace('V40','V40.1').replace('V39','V40.1').replace('V38.1','V40.1').replace('V38','V40.1')
    return _v401_prev_qwen_call(body, progress_callback, stage_text, profile=profile, **kwargs)

# ---- V40.1.1 planner quality amendments ----------------------------------------
# Build manifests/configuration are substrate, not consumers of application source, even if a model
# mistakenly wrote descriptive source paths into depends_on.  Also require a real provider-shaped
# canonical model/type file per component instead of guessing that a dashboard/CSV utility owns a model.

V401_STRICT_DOMAIN_OWNER_PLANNING = os.getenv('JARVIS_V401_STRICT_DOMAIN_OWNER_PLANNING', '1').strip().lower() not in {'0','false','no','off'}


def _v401_is_build_manifest_or_config(rel):
    rel = _v40_norm_rel(rel)
    name = Path(rel).name.lower()
    if name in {
        'package.json','cargo.toml','go.mod','pom.xml','build.gradle','build.gradle.kts','settings.gradle','settings.gradle.kts',
        'cmakelists.txt','pubspec.yaml','package.swift','composer.json','gemfile','pyproject.toml','requirements.txt',
        'vite.config.ts','vite.config.js','vitest.config.ts','vitest.config.js','tsconfig.json','tsconfig.app.json','tsconfig.node.json',
        'tauri.conf.json','project.godot','mix.exs','build.zig','deno.json','deno.jsonc','index.html'
    }:
        return True
    return name.endswith(('.csproj','.fsproj','.vbproj','.sln','.uproject'))


_v401_base_definition_mention_score = _v40_definition_mention_score

def _v40_definition_mention_score(item, symbol):
    rel = _v40_norm_rel((item or {}).get('path'))
    low = '/' + rel.lower() + '/'
    purpose = str((item or {}).get('purpose') or '')
    contracts = ' '.join(str(x) for x in (item or {}).get('contracts') or [])
    exports = [_v381_clean_symbol_name(x) for x in _normalize_export_contract((item or {}).get('exports'))]
    blob = f'{purpose} {contracts}'
    score = 0
    if symbol in exports:
        score += 140
    # "provides metrics ... category" is not proof that the file defines Category. Require a direct
    # declaration/ownership phrase or a declaration noun adjacent to the symbol.
    direct_patterns = (
        rf'(?i)\b(?:defines?|declares?|owns?|exports?)\s+(?:the\s+)?{re.escape(symbol)}\b',
        rf'(?i)\b(?:entity|model|interface|struct|class|record|schema|enum|type)\s*[:=-]?\s*{re.escape(symbol)}\b',
        rf'(?i)\b{re.escape(symbol)}\s+(?:entity|model|interface|struct|class|record|schema|enum|type)\b',
        rf'(?i)\bcanonical\s+(?:domain\s+)?(?:entity|model|interface|struct|class|record|schema|enum|type)?\s*{re.escape(symbol)}\b',
    )
    if any(re.search(p, blob) for p in direct_patterns):
        score += 95
    stem = re.sub(r'[^a-z0-9]+', '', Path(rel).stem.lower())
    sym = re.sub(r'[^a-z0-9]+', '', symbol.lower())
    if sym and (stem == sym or stem == sym + 's' or stem == sym.rstrip('s')):
        score += 65
    provider_path = any(tag in low for tag in ('/models/','/model/','/domain/','/entities/','/entity/','/schemas/','/schema/','/types/','/contracts/'))
    provider_purpose = bool(re.search(r'(?i)\b(?:definitions?|domain entities|domain models|data models|shared types|canonical types|schemas?)\b', purpose))
    if provider_path:
        score += 40
    if provider_purpose:
        score += 35
    # A general canonical container such as types/inventory.ts may own several entities even when its
    # manifest prose doesn't repeat each entity name.
    if provider_path and provider_purpose and re.search(r'(?i)\b(?:canonical|domain|entities|models|types|schemas)\b', blob):
        score += 35
    consumer = any(tag in low for tag in (
        '/services/','/service/','/repositories/','/repository/','/repo/','/api/','/routes/','/routers/','/controllers/',
        '/commands/','/components/','/views/','/ui/','/hooks/','/tests/','/test/','/utils/'
    ))
    if consumer:
        score -= 55
    if _v38_is_testish(rel):
        score -= 70
    return score


def _v401_component_domain_usage(manifest):
    defs = _v40_domain_definitions(manifest)
    usage = {}
    if not defs:
        return usage
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item, dict):
            continue
        rel = _v40_norm_rel(item.get('path'))
        scope = _v38_component_scope(manifest, rel)
        blob = _v39_file_blob(item)
        for symbol in defs:
            if re.search(r'(?<![a-z0-9])' + re.escape(symbol.lower()) + r's?(?![a-z0-9])', blob, flags=re.I):
                usage.setdefault(scope, set()).add(symbol)
    return usage


def _v401_domain_owner_architecture_issues(manifest):
    if not V401_STRICT_DOMAIN_OWNER_PLANNING:
        return []
    defs = _v40_domain_definitions(manifest)
    if not defs:
        return []
    owners = _v40_domain_owner_map(manifest)
    usage = _v401_component_domain_usage(manifest)
    issues = []
    for scope, symbols in sorted(usage.items()):
        for symbol in sorted(symbols):
            if (scope, symbol) not in owners:
                issues.append(
                    f'Component {scope!r} uses canonical domain {symbol!r} but has no clear authoritative model/type/schema owner. '
                    'Plan exactly one provider-shaped file in that component/language to DEFINE the canonical contract; '
                    'services/repositories/commands/UI/tests must consume it rather than becoming accidental providers.'
                )
    return issues


_v401_prev_manifest_completeness_issues = _v362_manifest_completeness_issues

def _v362_manifest_completeness_issues(manifest, spec, user_request, max_files):
    issues = list(_v401_prev_manifest_completeness_issues(manifest, spec, user_request, max_files) or [])
    for issue in _v401_domain_owner_architecture_issues(manifest):
        if issue not in issues:
            issues.append(issue)
    return issues


_v401_prev_plan_component = _v362_plan_component

def _v362_plan_component(user_request, spec, overview, component, max_files, ordinal, total, progress_callback=None):
    request = str(user_request or '') + (
        '\n\nV40.1 UNIVERSAL DOMAIN-OWNER PLANNING RULE: For every canonical domain entity/enum that this component uses, '
        'plan exactly one provider-shaped model/type/schema/header file in THIS component/language that defines it. '
        'Repositories, services, routes/commands, UI, utilities and tests are consumers and must not be the only planned provider. '
        'Cross-language components may each have one serialization-compatible owner.'
    )
    return _v401_prev_plan_component(request, spec, overview, component, max_files, ordinal, total, progress_callback)


# Re-override milestone planner with build-manifest dependency sanitation.  This wrapper temporarily
# removes descriptive source dependencies from build/config files so they remain Foundation substrate.
_v401_prev_build_milestones_sanitized = _v39_build_milestones

def _v39_build_milestones(manifest, user_request=''):
    patched = dict(manifest or {})
    patched_files = []
    for raw in (manifest or {}).get('files') or []:
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        if _v401_is_build_manifest_or_config(item.get('path')):
            item['depends_on'] = [
                d for d in (item.get('depends_on') or [])
                if _v401_is_build_manifest_or_config(d)
            ]
        patched_files.append(item)
    patched['files'] = patched_files
    return _v401_prev_build_milestones_sanitized(patched, user_request)


# Sanitize the executable manifest too, not only the milestone planner view.
_v401_prev_execute_manifest_sanitized = _v362_execute_manifest

def _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback=None, raw_plan=''):
    patched = dict(manifest or {})
    rows=[]
    for raw in (manifest or {}).get('files') or []:
        if not isinstance(raw,dict):
            continue
        item=dict(raw)
        if _v401_is_build_manifest_or_config(item.get('path')):
            removed=[]; kept=[]
            for dep in item.get('depends_on') or []:
                if _v401_is_build_manifest_or_config(dep): kept.append(dep)
                else: removed.append(dep)
            item['depends_on']=kept
            if removed:
                item.setdefault('contracts',[])
                item['contracts']=list(item['contracts'])+[f'Jarvis ignored non-build ordering dependency {d!r} from this build/config file.' for d in removed]
        rows.append(item)
    patched['files']=rows
    return _v401_prev_execute_manifest_sanitized(user_request,patched,work,max_files,progress_callback,raw_plan)


# Avoid unnatural "Users must be able to overdue tools" fragments from conversational metric lists.
_v401_prev_atomic_fragments = _v401_atomic_fragments

def _v401_atomic_fragments(user_request):
    rows = _v401_prev_atomic_fragments(user_request)
    cleaned=[]; seen=set()
    for row in rows:
        text=str(row or '').strip()
        m=re.match(r'(?i)^Users must be able to\s+(.+)$',text)
        if m:
            first=(re.findall(r'[A-Za-z]+',m.group(1)) or [''])[0].lower()
            if first not in _V401_REQ_ACTIONS:
                text=m.group(1).strip()
        key=re.sub(r'\W+',' ',text.lower()).strip()
        if key and key not in seen:
            seen.add(key);cleaned.append(text)
    return cleaned

# Consumer-shaped files may mention "Tool entity" in CRUD prose, but that is not ownership.  Unless
# the planner explicitly says such a file DEFINES/DECLARES/OWNS/EXPORTS the symbol, cap it below the
# owner threshold so preflight asks for a proper model/type/schema provider instead of freezing a command/UI utility.
_v401_prev_owner_score_strict = _v40_definition_mention_score

def _v40_definition_mention_score(item, symbol):
    score = _v401_prev_owner_score_strict(item, symbol)
    rel = _v40_norm_rel((item or {}).get('path'))
    low = '/' + rel.lower() + '/'
    purpose = str((item or {}).get('purpose') or '')
    contracts = ' '.join(str(x) for x in (item or {}).get('contracts') or [])
    blob = purpose + ' ' + contracts
    exports = [_v381_clean_symbol_name(x) for x in _normalize_export_contract((item or {}).get('exports'))]
    consumer = any(tag in low for tag in (
        '/services/','/service/','/repositories/','/repository/','/repo/','/api/','/routes/','/routers/','/controllers/',
        '/commands/','/components/','/views/','/ui/','/hooks/','/tests/','/test/','/utils/'
    ))
    explicit_owner = symbol in exports or bool(re.search(
        rf'(?i)\b(?:defines?|declares?|owns?|exports?)\s+(?:the\s+)?{re.escape(symbol)}\b', blob
    ))
    if consumer and not explicit_owner:
        score = min(score, 20)
    return score

_v401_prev_component_domain_usage = _v401_component_domain_usage

def _v401_component_domain_usage(manifest):
    usage = {}
    defs = _v40_domain_definitions(manifest)
    if not defs:
        return usage
    noncode = {'.sql','.json','.jsonc','.toml','.yaml','.yml','.xml','.md','.txt','.css','.scss','.html','.lock'}
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item, dict):
            continue
        rel = _v40_norm_rel(item.get('path'))
        if Path(rel).suffix.lower() in noncode or _v401_is_build_manifest_or_config(rel):
            continue
        scope = _v38_component_scope(manifest, rel)
        blob = _v39_file_blob(item)
        for symbol in defs:
            if re.search(r'(?<![a-z0-9])' + re.escape(symbol.lower()) + r's?(?![a-z0-9])', blob, flags=re.I):
                usage.setdefault(scope, set()).add(symbol)
    return usage


# =============================================================================
# V40.2 UNIVERSAL PREFLIGHT SELF-HEALING / CANONICAL PROVIDER SYNTHESIS
# =============================================================================
# A small local model is allowed to omit an obvious model/type/schema owner in its
# first architecture pass. Jarvis repairs that architecture deterministically instead
# of spending another long planner call or blocking the entire project. This is
# language/toolchain-aware but domain/project-agnostic.

V402_VERSION = '40.2.0'
V402_ENGINE = 'UNIVERSAL_MILESTONE_SELF_HEALING_FACTORY'
V402_AUTO_DOMAIN_OWNER_PREFLIGHT = os.getenv('JARVIS_V402_AUTO_DOMAIN_OWNER_PREFLIGHT', '1').strip().lower() not in {'0','false','no','off'}
V402_AUTO_OWNER_MAX_FILES = max(1, int(os.getenv('JARVIS_V402_AUTO_OWNER_MAX_FILES', '24')))
V402_DEDUPE_ARCHITECTURE_PATHS = os.getenv('JARVIS_V402_DEDUPE_ARCHITECTURE_PATHS', '1').strip().lower() not in {'0','false','no','off'}


def _v402_merge_unique(values):
    out=[]; seen=set()
    for value in values or []:
        s=str(value or '').replace('\\','/').strip()
        if not s: continue
        key=s.casefold() if os.name == 'nt' else s
        if key in seen: continue
        seen.add(key); out.append(s)
    return out


def _v402_dedupe_manifest_files(manifest):
    """Merge duplicate architecture rows by canonical path instead of letting closure review create parallel entries."""
    if not isinstance(manifest, dict) or not V402_DEDUPE_ARCHITECTURE_PATHS:
        return manifest
    merged={}; order=[]
    for raw in manifest.get('files') or []:
        if not isinstance(raw, dict):
            continue
        item=dict(raw)
        rel=_v40_norm_rel(item.get('path'))
        if not rel:
            continue
        key=rel.casefold() if os.name == 'nt' else rel
        if key not in merged:
            item['path']=rel
            item['depends_on']=_v402_merge_unique(item.get('depends_on'))
            item['exports']=_v402_merge_unique(_normalize_export_contract(item.get('exports')))
            item['contracts']=_v402_merge_unique(item.get('contracts'))
            merged[key]=item; order.append(key)
            continue
        cur=merged[key]
        # Keep the more descriptive purpose and the earliest useful implementation phase.
        if len(str(item.get('purpose') or '')) > len(str(cur.get('purpose') or '')):
            cur['purpose']=str(item.get('purpose') or '')
        phase_rank={'foundation':0,'data':1,'service':2,'ui':3,'integration':4,'test':5,'docs':6}
        cp=str(cur.get('phase') or 'integration').lower(); np=str(item.get('phase') or cp).lower()
        if phase_rank.get(np,4) < phase_rank.get(cp,4): cur['phase']=np
        cur['depends_on']=_v402_merge_unique(list(cur.get('depends_on') or [])+list(item.get('depends_on') or []))
        cur['exports']=_v402_merge_unique(list(cur.get('exports') or [])+list(_normalize_export_contract(item.get('exports'))))
        cur['contracts']=_v402_merge_unique(list(cur.get('contracts') or [])+list(item.get('contracts') or []))
    manifest['files']=[merged[k] for k in order]
    return manifest


def _v402_component_by_scope(manifest, scope):
    scope=str(scope or '')
    comps=_v35_sanitize_components((manifest or {}).get('components'))
    for comp in comps:
        cid=str(comp.get('id') or '').strip(); root=str(comp.get('root') or '.').strip('/') or '.'
        if scope in {cid, root}:
            return comp
    return {}


def _v402_component_paths(manifest, comp):
    root=str((comp or {}).get('root') or '.').replace('\\','/').strip('/') or '.'
    rows=[]
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item,dict): continue
        rel=_v40_norm_rel(item.get('path'))
        if root=='.' or rel==root or rel.startswith(root.rstrip('/')+'/'):
            rows.append(rel)
    return rows


def _v402_infer_component_adapter(manifest, comp):
    adapter=_v361_normalize_component_adapter((comp or {}).get('toolchain_adapter'))
    if adapter and adapter!='generic':
        return adapter
    exts={}
    for rel in _v402_component_paths(manifest, comp):
        ext=Path(rel).suffix.lower()
        if ext: exts[ext]=exts.get(ext,0)+1
    preferred=sorted(exts.items(), key=lambda kv:(-kv[1],kv[0]))
    ext=preferred[0][0] if preferred else ''
    return {
        '.py':'python','.rs':'rust','.ts':'typescript','.tsx':'react','.js':'node','.jsx':'react',
        '.go':'go','.java':'java_gradle','.kt':'kotlin','.kts':'kotlin','.cs':'dotnet',
        '.cpp':'cpp_cmake','.cc':'cpp_cmake','.cxx':'cpp_cmake','.c':'c','.h':'c','.hpp':'cpp_cmake',
        '.swift':'swift','.dart':'flutter','.php':'php','.rb':'ruby','.ex':'elixir','.exs':'elixir','.zig':'zig'
    }.get(ext, adapter or 'generic')


def _v402_join_root(root, tail):
    root=str(root or '.').replace('\\','/').strip('/') or '.'
    tail=str(tail or '').replace('\\','/').lstrip('/')
    return tail if root=='.' else root.rstrip('/')+'/'+tail


def _v402_owner_plan_for_component(manifest, scope, symbols):
    """Return [(path,[symbols...])] using conventional provider locations for the component toolchain."""
    comp=_v402_component_by_scope(manifest,scope)
    if not comp: return []
    root=str(comp.get('root') or '.').replace('\\','/').strip('/') or '.'
    adapter=_v402_infer_component_adapter(manifest,comp)
    symbols=sorted(dict.fromkeys(str(x) for x in symbols if str(x).strip()))
    if not symbols: return []
    # Java public top-level classes/records conventionally require one file per public symbol.
    if adapter in {'java','java_gradle','java_maven'}:
        return [(_v402_join_root(root,f'src/main/java/domain/{sym}.java'),[sym]) for sym in symbols]
    grouped={
        'rust':'src/domain.rs',
        'python':'models/domain.py',
        'react':'src/types/domain.ts', 'typescript':'src/types/domain.ts', 'vite':'src/types/domain.ts',
        'node':'src/types/domain.ts', 'nextjs':'src/types/domain.ts', 'vue':'src/types/domain.ts', 'sveltekit':'src/types/domain.ts',
        'go':'internal/domain/models.go',
        'kotlin':'src/main/kotlin/domain/DomainModels.kt',
        'dotnet':'Domain/DomainModels.cs', 'csharp':'Domain/DomainModels.cs',
        'cpp_cmake':'include/domain/models.hpp', 'cpp':'include/domain/models.hpp',
        'c':'include/domain/models.h',
        'swift':'Sources/Domain/DomainModels.swift',
        'flutter':'lib/models/domain.dart', 'dart':'lib/models/domain.dart',
        'php':'src/Domain/Models.php', 'ruby':'lib/domain/models.rb',
        'elixir':'lib/domain/models.ex', 'zig':'src/domain.zig',
    }
    tail=grouped.get(adapter)
    if not tail:
        return []
    return [(_v402_join_root(root,tail),symbols)]


def _v402_domain_contract_text(defs, symbols):
    contracts=[]
    for symbol in symbols:
        spec=defs.get(symbol) or {}
        if spec.get('kind')=='entity':
            fields=', '.join(spec.get('all_fields') or spec.get('fields') or [])
            contracts.append(f'DEFINES canonical {symbol} entity/model with fields: {fields}.')
        elif spec.get('kind')=='enum':
            vals=', '.join(spec.get('values') or [])
            contracts.append(f'DEFINES canonical {symbol} enum/type with values: {vals}.')
        else:
            contracts.append(f'DEFINES canonical {symbol} domain contract.')
    contracts.append('This is an authoritative provider file. Repositories/services/commands/UI/tests consume these definitions and must not redefine them in this component.')
    return contracts


def _v402_ensure_domain_owner_files(manifest, max_files=None):
    """Deterministically repair missing canonical provider rows before architecture can block.

    This edits architecture metadata only. Qwen still implements the source later and the normal
    candidate/compile/test gates remain authoritative.
    """
    if not isinstance(manifest,dict) or not V402_AUTO_DOMAIN_OWNER_PREFLIGHT:
        return manifest, []
    _v402_dedupe_manifest_files(manifest)
    defs=_v40_domain_definitions(manifest)
    if not defs:
        return manifest, []
    usage=_v401_component_domain_usage(manifest)
    owners=_v40_domain_owner_map(manifest)
    limit=max(1,int(max_files or HARD_MAX_FILES))
    added=[]
    by_path={_v40_norm_rel(x.get('path')):x for x in manifest.get('files') or [] if isinstance(x,dict) and x.get('path')}
    auto_count=0
    for scope,symbols in sorted(usage.items()):
        missing=[s for s in sorted(symbols) if (scope,s) not in owners]
        if not missing: continue
        plans=_v402_owner_plan_for_component(manifest,scope,missing)
        for rel,owned_symbols in plans:
            rel=_v40_norm_rel(rel)
            if not rel: continue
            if rel in by_path:
                item=by_path[rel]
            else:
                if len(manifest.get('files') or []) >= limit or auto_count >= V402_AUTO_OWNER_MAX_FILES:
                    continue
                item={
                    'path':rel,
                    'purpose':'Authoritative canonical domain model/type/schema provider for '+', '.join(owned_symbols)+'.',
                    'phase':'data', 'depends_on':[], 'exports':[], 'contracts':[]
                }
                manifest.setdefault('files',[]).append(item); by_path[rel]=item; added.append(rel); auto_count+=1
            item['purpose']='Authoritative canonical domain model/type/schema provider for '+', '.join(owned_symbols)+'.'
            item['phase']='data'
            item['exports']=_v402_merge_unique(list(item.get('exports') or [])+owned_symbols)
            item['contracts']=_v402_merge_unique(list(item.get('contracts') or [])+_v402_domain_contract_text(defs,owned_symbols))
            # Make same-component consumers explicitly depend on their provider. Build/config files are substrate.
            for consumer in manifest.get('files') or []:
                if not isinstance(consumer,dict): continue
                crel=_v40_norm_rel(consumer.get('path'))
                if crel==rel or _v38_component_scope(manifest,crel)!=scope or _v401_is_build_manifest_or_config(crel):
                    continue
                blob=_v39_file_blob(consumer)
                if any(re.search(r'(?<![a-z0-9])'+re.escape(sym.lower())+r's?(?![a-z0-9])',blob,re.I) for sym in owned_symbols):
                    consumer['depends_on']=_v402_merge_unique(list(consumer.get('depends_on') or [])+[rel])
    _v402_dedupe_manifest_files(manifest)
    # Annotate the architecture so later prompts understand that Jarvis repaired planner omissions itself.
    if added:
        rules=list(manifest.get('architecture_rules') or [])
        note='V40.2 PREFLIGHT SELF-HEAL: Jarvis synthesized missing provider-shaped canonical domain files deterministically; these are authoritative owners and consumers must import/use them.'
        if note not in rules: rules.append(note)
        manifest['architecture_rules']=rules
        manifest['v402_auto_domain_owner_files']=added
    return manifest, added


# Heal before the completeness gate asks Qwen for another closure rewrite.
_v402_prev_manifest_completeness_issues = _v362_manifest_completeness_issues

def _v362_manifest_completeness_issues(manifest, spec, user_request, max_files):
    try:
        _v402_ensure_domain_owner_files(manifest,max_files)
    except Exception:
        pass
    return _v402_prev_manifest_completeness_issues(manifest,spec,user_request,max_files)


# Also heal the final executable manifest so resumed/older plans receive the same repair.
_v402_prev_execute_manifest = _v362_execute_manifest

def _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback=None, raw_plan=''):
    patched=dict(manifest or {})
    patched['files']=[dict(x) for x in (manifest or {}).get('files') or [] if isinstance(x,dict)]
    try:
        patched,added=_v402_ensure_domain_owner_files(patched,max_files)
        if added:
            _append_project_event(work,'v402_preflight_self_healed','Jarvis added missing canonical domain provider files before milestone execution.',files=added)
    except Exception as exc:
        _append_project_event(work,'v402_preflight_self_heal_failed','Canonical provider self-heal failed safely; normal preflight remains authoritative.',error=str(exc))
    return _v402_prev_execute_manifest(user_request,patched,work,max_files,progress_callback,raw_plan)


