def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    body=str(prompt or '')+(
        '\n\nV40.2 PREFLIGHT RULE: Jarvis may deterministically add a missing provider-shaped canonical model/type/schema file '
        'when architecture usage proves a component needs a frozen domain contract. Treat any such file in the current manifest/KB '
        'as authoritative. Do not delete it, replace it with a command/service/UI file, or redefine the same canonical type elsewhere in that component.'
    )
    stage_text=str(stage or '').replace('V40.1','V40.2').replace('V40','V40.2').replace('V39','V40.2')
    return _v402_prev_qwen_call(body,progress_callback,stage_text,profile=profile,**kwargs)


# V40.2 usage alias refinement: canonical CamelCase names may appear in architecture prose as
# human words or snake/kebab identifiers (UserAssignment -> "user assignments"/user_assignments).
def _v402_symbol_usage_regex(symbol):
    raw=str(symbol or '').strip()
    words=re.findall(r'[A-Z]?[a-z]+|[A-Z]+(?=[A-Z]|$)|\d+',raw)
    if not words:
        words=[raw]
    words=[re.escape(w.lower()) for w in words if w]
    if not words:
        return re.compile(r'(?!x)x')
    if len(words)==1:
        pat=words[0]+r's?'
    else:
        pat=r'[\s_\-]*'.join(words[:-1])+r'[\s_\-]*'+words[-1]+r's?'
    return re.compile(r'(?<![a-z0-9])'+pat+r'(?![a-z0-9])',re.I)


def _v401_component_domain_usage(manifest):
    defs=_v40_domain_definitions(manifest)
    usage={}
    if not defs:
        return usage
    patterns={symbol:_v402_symbol_usage_regex(symbol) for symbol in defs}
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item,dict):
            continue
        rel=_v40_norm_rel(item.get('path'))
        scope=_v38_component_scope(manifest,rel)
        blob=_v39_file_blob(item)
        for symbol,pat in patterns.items():
            if pat.search(blob):
                usage.setdefault(scope,set()).add(symbol)
    return usage


