def _v411_load_toolchains():
    try:
        data=json.loads(V411_TOOLCHAIN_FILE.read_text(encoding='utf-8',errors='replace'))
        adapters=data.get('adapters') or {}
        if isinstance(adapters,dict) and len(adapters)==V411_REGISTERED_TOOLCHAINS:
            return {str(k):dict(v) for k,v in adapters.items() if isinstance(v,dict)}
    except Exception:
        pass
    # Never break an existing Jarvis install just because the optional registry file was moved.
    return dict(_v411_previous_catalog() or {})

def _v34_toolchain_catalog():
    return _v411_load_toolchains()

def _v411_clean_request(text):
    return _strip_jarvis_routing_noise(str(text or '')).lower()

def _v35_explicit_toolchain(text):
    """Framework/engine/build-system specificity always outranks the underlying language."""
    low=_v411_clean_request(text)
    checks=[
      ('tauri',('tauri',)),('unreal',('unreal','unreal engine','unrealbuildtool','ue5','ue 5','.uproject')),
      ('unity',('unity3d','unity engine','unity game','in unity','with unity')),('godot',('godot','gdscript')),
      ('qt_cmake',('qt6','qt 6','qt5','qt 5','qt app','qt desktop')),('xmake',('xmake','xmake.lua')),
      ('meson',('meson.build','meson project','using meson')),
      ('android_gradle',('android studio','native android','jetpack compose','android sdk','kotlin android','android app in kotlin')),
      ('ios_xcode',('native ios','native iphone','swiftui ios','uikit','xcode ios','iphone app in swift')),
      ('macos_xcode',('native macos','swiftui macos','appkit','xcode macos')),
      ('wpf',('wpf',)),('winforms',('winforms','windows forms')),
      ('flutter',('flutter','flutter app')),('dart',('dart cli','dart package','written in dart')),
      ('expo',('expo','expo react native')),('react_native',('react native',)),
      ('nextjs',('next.js','nextjs')),('sveltekit',('sveltekit','svelte kit')),('angular',('angular','angular-cli')),
      ('vue',('vue.js','vuejs','vue 3')),('react',('react app','react website','react web','vite react')),
      ('electron',('electron app','electron desktop','electron.js','with electron')),('vite',('vite app','vite project')),
      ('platformio',('platformio','platformio.ini')),('esp_idf',('esp-idf','esp idf','idf.py')),
      ('terraform',('terraform','.tf files','hcl terraform')),
      ('rails',('ruby on rails','rails app','rails application')),('php_composer',('composer','laravel','symfony','php app')),
      ('elixir_mix',('elixir','phoenix','mix.exs')),('erlang_rebar3',('erlang','rebar3')),
      ('haskell_cabal',('haskell','cabal')),('ocaml_dune',('ocaml','dune-project','dune build')),('scala_sbt',('scala','sbt')),
      ('zig',('zig','build.zig')),('nim',('nim','nimble')),('odin',('odin language','written in odin')),
      ('rust',('rust','cargo')),('go',('golang','go module','written in go','language go')),
      ('dotnet',('c#','.net','dotnet','maui','avalonia')),
      ('cpp_cmake',('c++','cpp','cmake')),('c_make',('written in c','language c',' c program')),
      ('kotlin_gradle',('kotlin/jvm','kotlin desktop')),('java_maven',('maven','pom.xml')),('java_gradle',('java gradle','spring boot','gradle java')),
      ('swiftpm',('swift package','swiftpm')),('ruby_bundler',('ruby','bundler','sinatra')),
      ('python_desktop',('tkinter','pyqt','pyside','python desktop','desktop app in python')),
      ('python',('python','flask','django','fastapi','pygame')),('node',('node.js','nodejs','express','typescript server')),
      ('static_web',('static website','plain html','html css','vanilla javascript')),
      ('lua',('written in lua','lua app')),('perl',('written in perl','perl script')),('julia',('written in julia','julia package')),
      ('r',('written in r','r project')),
    ]
    for adapter,terms in checks:
        if any(term in low for term in terms):
            return adapter
    return 'generic'

def _v411_infer_project_kinds(text, manifest=None):
    low=_v411_clean_request(text)+' '+str((manifest or {}).get('project_type') or '').lower()
    kinds=[]
    def add(v):
        if v not in kinds:kinds.append(v)
    if any(x in low for x in ('game','unreal','unity','godot')): add('game')
    if any(x in low for x in ('android','ios','iphone','ipad','mobile app','phone app','react native','flutter')): add('mobile')
    if any(x in low for x in ('desktop app','desktop application','wpf','winforms','electron','tauri','qt','macos app')): add('desktop')
    if any(x in low for x in ('website','web app','frontend','browser app','react','vue','angular','next.js','svelte')): add('web')
    if any(x in low for x in ('api','backend','server','microservice','rest','graphql')): add('backend')
    if any(x in low for x in ('cli','command line','terminal tool')): add('cli')
    if any(x in low for x in ('library','sdk','package','crate')): add('library')
    if any(x in low for x in ('database','sqlite','postgres','mysql','sql ')): add('database')
    if any(x in low for x in ('embedded','firmware','esp32','microcontroller','platformio','esp-idf')): add('embedded')
    if any(x in low for x in ('terraform','infrastructure as code','iac')): add('infrastructure')
    if not kinds:add('software')
    return kinds[:6]

def _v411_infer_platform(text, manifest=None):
    low=_v411_clean_request(text)+' '+str((manifest or {}).get('platform') or '').lower()
    if any(x in low for x in ('android','android studio')): return 'android'
    if any(x in low for x in ('ios','iphone','ipad')): return 'ios'
    if any(x in low for x in ('macos','mac os','mac app')): return 'macos'
    if any(x in low for x in ('windows','win32','wpf','winforms')): return 'windows'
    if any(x in low for x in ('linux','ubuntu')): return 'linux'
    if any(x in low for x in ('web app','website','browser app')): return 'web'
    return ''

def _v411_manifest_custom_candidate(manifest):
    m=manifest or {}
    named=str(m.get('toolchain_adapter') or '').strip().lower()
    if named=='custom': return True
    if named and named not in _v34_toolchain_catalog() and named!='generic': return True
    language=str(m.get('language') or '').strip().lower()
    known=' '.join(str(v.get('language') or '').lower() for v in _v34_toolchain_catalog().values())
    if language and language not in {'software','unknown','generic'} and language not in known:
        return bool(str(m.get('build_command') or m.get('test_command') or '').strip())
    return False

def _v34_infer_toolchain(text, manifest=None, work=None):
    explicit=_v35_explicit_toolchain(text)
    if explicit!='generic': return explicit
    if _v411_manifest_custom_candidate(manifest): return 'custom'
    if work:
        root=Path(work)
        marker_checks=[
          ('unreal',lambda: next(iter(root.rglob('*.uproject')),None)),('unity',lambda:(root/'ProjectSettings'/'ProjectVersion.txt').exists()),
          ('godot',lambda:next(iter(root.rglob('project.godot')),None)),('tauri',lambda:next(iter(root.rglob('src-tauri/Cargo.toml')),None)),
          ('platformio',lambda:next(iter(root.rglob('platformio.ini')),None)),('esp_idf',lambda:next(iter(root.rglob('sdkconfig')),None)),
          ('xmake',lambda:next(iter(root.rglob('xmake.lua')),None)),('meson',lambda:next(iter(root.rglob('meson.build')),None)),
          ('terraform',lambda:next(iter(root.rglob('*.tf')),None)),('zig',lambda:next(iter(root.rglob('build.zig')),None)),
          ('elixir_mix',lambda:next(iter(root.rglob('mix.exs')),None)),('scala_sbt',lambda:next(iter(root.rglob('build.sbt')),None)),
          ('ocaml_dune',lambda:next(iter(root.rglob('dune-project')),None)),('flutter',lambda:next(iter(root.rglob('pubspec.yaml')),None)),
          ('rust',lambda:next(iter(root.rglob('Cargo.toml')),None)),('go',lambda:next(iter(root.rglob('go.mod')),None)),
        ]
        for adapter,probe in marker_checks:
            try:
                if probe(): return adapter
            except Exception: pass
    return _v411_previous_infer_toolchain(text,manifest,work)

def _v34_apply_toolchain_defaults(user_request, manifest):
    manifest=dict(manifest or {})
    adapter=_v34_infer_toolchain(user_request,manifest)
    manifest['toolchain_adapter']=adapter
    spec=_v34_toolchain_catalog().get(adapter,{})
    for key in ('platform','language','framework','build_system','package_manager','dependency_command','build_command','test_command','run_command'):
        if not str(manifest.get(key) or '').strip() and spec.get(key) is not None:
            manifest[key]=spec.get(key,'')
    if not manifest.get('required_tools'): manifest['required_tools']=list(spec.get('required_tools') or [])
    kinds=_v411_infer_project_kinds(user_request,manifest)
    manifest['project_kinds']=kinds
    if not str(manifest.get('project_type') or '').strip() or str(manifest.get('project_type')).lower() in {'software','application','app','project'}:
        manifest['project_type']=kinds[0]
    platform=_v411_infer_platform(user_request,manifest)
    if platform: manifest['platform']=platform
    # Engines/frameworks are project kinds/frameworks, never platform values.
    if str(manifest.get('platform') or '').lower() in {'game','mobile','desktop','backend','cli','library','database'}:
        manifest['platform']=platform or ('cross-platform' if adapter in {'unreal','unity','godot','flutter','react_native','expo'} else str(spec.get('platform') or 'cross-platform'))
    return manifest

# Planner schema gains project_kinds while retaining backward compatibility.
try:
    QWEN_SCHEMA_PROJECT_PLAN.setdefault('properties',{})['project_kinds']={'type':'array','items':{'type':'string'}}
except Exception:
    pass

def _parse_project_plan(text, user_request, max_files):
    result=_v411_previous_parse_plan(text,user_request,max_files)
    if not isinstance(result,dict): return result
    raw={}
    try: raw=_extract_json(text) or {}
    except Exception: pass
    if isinstance(raw,dict) and isinstance(raw.get('project_kinds'),list):
        vals=[str(x).strip().lower() for x in raw.get('project_kinds') if str(x).strip()]
        if vals: result['project_kinds']=list(dict.fromkeys(vals))[:6]
    return _v34_apply_toolchain_defaults(user_request,result)

def _merge_manifest(base, reviewed, user_request, max_files):
    result=_v411_previous_merge_manifest(base,reviewed,user_request,max_files)
    merged=[]
    for src in ((base or {}).get('project_kinds') or [],(reviewed or {}).get('project_kinds') or [],_v411_infer_project_kinds(user_request,result)):
        vals=[src] if isinstance(src,str) else src
        for v in vals or []:
            v=str(v).strip().lower()
            if v and v not in merged: merged.append(v)
    result['project_kinds']=merged[:6] or ['software']
    return _v34_apply_toolchain_defaults(user_request,result)

def _v411_skill_name_for_adapter(adapter):
    return {
      'python_desktop':'python','c_make':'c','cpp_cmake':'cpp','cpp_make':'cpp','meson':'cpp','qt_cmake':'qt',
      'wpf':'dotnet','winforms':'dotnet','java_gradle':'java','java_maven':'maven','kotlin_gradle':'kotlin',
      'android_gradle':'android','ios_xcode':'ios','macos_xcode':'macos','react_native':'react-native',
      'ruby_bundler':'ruby','php_composer':'php','sql_generic':'sql','sqlite':'sql','postgres':'sql','mysql':'sql',
      'elixir_mix':'elixir','platformio':'platformio','esp_idf':'esp-idf'
    }.get(adapter,adapter)

def _v36_stack_skill_names(manifest):
    m=manifest or {}; names=[]
    def add(name):
        name=str(name or '').strip().lower().replace('_','-')
        if name and (V36_SKILLS_DIR/f'{name}.md').exists() and name not in names:names.append(name)
    add('universal')
    components=_v35_sanitize_components(m.get('components'))
    adapters=[]
    for c in components:
        a=str(c.get('toolchain_adapter') or '').strip()
        if a and a not in adapters: adapters.append(a)
    primary=str(m.get('toolchain_adapter') or '').strip()
    if primary and primary not in adapters: adapters.insert(0,primary)
    if len(adapters)>1:add('mixed-repo')
    for kind in m.get('project_kinds') or _v411_infer_project_kinds('',m): add(kind)
    for a in adapters[:5]: add(_v411_skill_name_for_adapter(a))
    blob=' '.join(str(m.get(k) or '').lower() for k in ('language','framework','build_system'))
    for needle,name in [('typescript','typescript'),('javascript','javascript'),('c#','csharp'),('c++','cpp'),('cmake','cmake'),('gradle','gradle'),('swift','swift'),('dart','dart'),('sql','sql')]:
        if needle in blob:add(name)
    return names[:10]

def _v38_micro_skill_names(manifest, rel):
    rel=str(rel or '').replace('\\','/').strip('/'); ext=Path(rel).suffix.lower(); names=[]
    def add(n):
        n=str(n).replace('_','-')
        if (V36_SKILLS_DIR/f'{n}.md').exists() and n not in names:names.append(n)
    comp=_v38_component_for_path(manifest,rel); adapter=str((comp or {}).get('toolchain_adapter') or (manifest or {}).get('toolchain_adapter') or '')
    add(_v411_skill_name_for_adapter(adapter))
    ext_map={'.py':'python','.rs':'rust','.c':'c','.cpp':'cpp','.cc':'cpp','.cxx':'cpp','.hpp':'cpp','.h':'cpp','.cs':'csharp','.go':'go','.java':'java','.kt':'kotlin','.kts':'kotlin','.dart':'dart','.swift':'swift','.ts':'typescript','.tsx':'react','.js':'javascript','.jsx':'react','.rb':'ruby','.php':'php','.sql':'sql','.gd':'godot','.zig':'zig','.tf':'terraform'}
    if ext in ext_map:add(ext_map[ext])
    return names[:4]

def _project_plan_prompt(user_request, max_files):
    base=_v411_previous_plan_prompt(user_request,max_files)
    provisional={'toolchain_adapter':_v34_infer_toolchain(user_request,{}),'project_kinds':_v411_infer_project_kinds(user_request,{}),'platform':_v411_infer_platform(user_request,{})}
    provisional=_v34_apply_toolchain_defaults(user_request,provisional)
    skill=_v36_stack_skill_context(provisional,3800)
    return base + (
      '\nV41.1 CLASSIFICATION RULES:\n'
      '- project_kinds is a list of product kinds such as game/mobile/desktop/web/backend/cli; platform is an OS/runtime target such as Android/iOS/Windows/macOS/Linux/web/cross-platform. Never set platform=game.\n'
      '- Framework/engine specificity outranks language: Unity>C#, Unreal>C++, Qt>C++, Tauri>Rust, Android>Kotlin, iOS>Swift, Electron>TypeScript, xmake>C++.\n'
      '- An unfamiliar explicit ecosystem must remain that ecosystem via a custom adapter with real layout and non-noop build/test commands; never silently fall back to Python.\n'
      + ('\nACTIVE V41.1 PLANNING SKILLS:\n'+skill if skill else '')
    )

def wants_project_zip(text):
    raw=str(text or '').strip(); low=raw.lower()
    if not low:return False
    # Explicit artifact requests always win.
    if any(x in low for x in ('zip','zip file','downloadable project','give me the files','give me the complete code')) and any(x in low for x in ('project','app','application','program','website','game','code','build','create','make','fix')):
        return True
    # Explanatory questions stay conversation, even when they contain the word build.
    if re.match(r'^(how|what|why|when|where|which|can you explain|show me how|tell me how)\b',low):
        return False
    imperative=re.match(r'^(please\s+)?(build|create|make|develop|generate|write|code|implement)\b',low)
    target=any(x in low for x in (' app',' application',' project',' program',' website',' game',' api',' tool',' cli',' library',' plugin',' service'))
    return bool(imperative and target)

def _v411_common_windows_roots():
    roots=[]
    for env in ('ProgramFiles','ProgramFiles(x86)','PROGRAMFILES','PROGRAMFILES(X86)'):
        val=os.getenv(env)
        if val and val not in roots:roots.append(Path(val))
    roots += [Path('C:/Program Files'),Path('C:/Program Files (x86)')]
    out=[]
    for p in roots:
        if str(p).lower() not in {str(x).lower() for x in out}:out.append(p)
    return out

def _v411_find_unreal_build_tool():
    for env in ('JARVIS_UNREAL_BUILD_TOOL','UNREAL_BUILD_TOOL'):
        val=os.getenv(env,'').strip()
        if val and Path(val).is_file():return str(Path(val))
    direct=shutil.which('UnrealBuildTool') or shutil.which('UnrealBuildTool.exe')
    if direct:return direct
    engine_roots=[]
    for env in ('JARVIS_UNREAL_ENGINE_ROOT','UNREAL_ENGINE_ROOT','UE_ENGINE_ROOT'):
        val=os.getenv(env,'').strip()
        if val:engine_roots.append(Path(val))
    for root in _v411_common_windows_roots():
        epic=root/'Epic Games'
        if epic.exists():
            try: engine_roots += sorted(epic.glob('UE_*'),reverse=True)
            except Exception: pass
    candidates=[]
    for eroot in engine_roots:
        candidates += [eroot/'Engine/Binaries/DotNET/UnrealBuildTool/UnrealBuildTool.exe',eroot/'Engine/Binaries/DotNET/UnrealBuildTool.exe']
    for p in candidates:
        if p.is_file():return str(p)
    return ''

def _v411_find_unity_editor():
    for env in ('JARVIS_UNITY_EDITOR','UNITY_EDITOR','UNITY_PATH'):
        val=os.getenv(env,'').strip()
        if val and Path(val).is_file():return str(Path(val))
    direct=shutil.which('Unity') or shutil.which('Unity.exe')
    if direct:return direct
    candidates=[]
    for root in _v411_common_windows_roots():
        hub=root/'Unity/Hub/Editor'
        if hub.exists():
            try:
                for ver in sorted(hub.iterdir(),reverse=True):candidates.append(ver/'Editor/Unity.exe')
            except Exception:pass
    for p in candidates:
        if p.is_file():return str(p)
    return ''

def _v411_unreal_target(root):
    targets=sorted(Path(root).rglob('*.Target.cs'))
    if not targets:return ''
    # Prefer the normal game/program target over Editor for a Development Win64 build.
    non_editor=[p for p in targets if not p.stem.lower().endswith('editor.target')]
    p=(non_editor or targets)[0]
    name=p.name[:-len('.Target.cs')] if p.name.endswith('.Target.cs') else p.stem
    return name

def _v411_custom_component_is_verifiable(root, component, manifest):
    root=Path(root)
    source_exts={'.c','.cc','.cpp','.cxx','.h','.hpp','.rs','.go','.java','.kt','.kts','.cs','.swift','.dart','.js','.ts','.tsx','.jsx','.rb','.php','.ex','.exs','.erl','.hrl','.hs','.ml','.mli','.scala','.lua','.pl','.r','.jl','.zig','.nim','.odin','.tf','.sql'}
    source_exts.update({'.py','.pyw','.fs','.fsx','.clj','.cljs','.lisp','.rkt','.f90','.f95','.d','.pas','.v','.sv','.vhdl'})
    # Custom adapters may declare languages outside the built-in catalog.
    # Their actual build/test commands remain mandatory verification authority.
    for item in (manifest or {}).get('files') or []:
        if isinstance(item,dict) and str(item.get('phase') or '').lower() not in {'docs','documentation'}:
            ext=Path(str(item.get('path') or '')).suffix.lower()
            if ext and ext not in {'.md','.rst','.txt','.json','.yaml','.yml','.toml','.xml'}:
                source_exts.add(ext)
    has_source=any(p.is_file() and p.suffix.lower() in source_exts for p in root.rglob('*'))
    has_manifest=any(p.is_file() for name in ('Makefile','CMakeLists.txt','meson.build','xmake.lua','package.json','Cargo.toml','go.mod','pom.xml','build.gradle','build.gradle.kts','Package.swift','pubspec.yaml','mix.exs','rebar.config','build.sbt','dune-project','Project.toml','platformio.ini') for p in root.rglob(name))
    build=str(component.get('build_command') or (manifest or {}).get('build_command') or '').strip()
    test=str(component.get('test_command') or (manifest or {}).get('test_command') or '').strip()
    return (has_source or has_manifest) and any(cmd and not _v35_is_noop_command(cmd) for cmd in (build,test))

def _v35_validate_component(work, manifest, component, user_request=''):
    root=Path(work) if component.get('root') in ('','.') else Path(work)/str(component.get('root'))
    root=root.resolve(); adapter=str(component.get('toolchain_adapter') or 'generic')
    if adapter=='unreal':
        if os.name!='nt': return _v35_host_unverified(component,'Unreal project generated correctly; full UnrealBuildTool verification requires a Windows Unreal host.')
        ubt=_v411_find_unreal_build_tool()
        if not ubt:return _v35_host_unverified(component,'Unreal Engine/UnrealBuildTool was not found in PATH, environment overrides, or common Epic Games install locations.')
        uproject=next(iter(root.glob('*.uproject')),None) or next(iter(root.rglob('*.uproject')),None)
        target=_v411_unreal_target(root)
        if not uproject or not target:return False,_v35_component_failure(component,'Unreal validation requires a .uproject and at least one concrete *.Target.cs target.')
        outputs=[]; args=[ubt,target,'Win64','Development',f'-Project={uproject}','-WaitMutex','-NoHotReload']
        ok,out=_v35_run(args,root,outputs)
        return ok, ('UnrealBuildTool Win64 Development target passed.\n'+out if ok else _v35_component_failure(component,out))
    if adapter=='unity':
        unity=_v411_find_unity_editor()
        if not unity:return _v35_host_unverified(component,'Unity Editor was not found in PATH, environment overrides, or common Unity Hub install locations.')
        outputs=[]; ok,out=_v35_run([unity,'-batchmode','-quit','-projectPath',str(root),'-logFile','-'],root,outputs)
        return ok, out if ok else _v35_component_failure(component,out)
    if adapter=='custom':
        if not _v411_custom_component_is_verifiable(root,component,manifest):
            return False,_v35_component_failure(component,'Custom adapter requires a real source/manifest layout and at least one non-noop build or test verification command.')
        outputs=[]; ran_build_or_test=False
        for label,key in (('dependency command','dependency_command'),('build command','build_command'),('test command','test_command')):
            cmd=str(component.get(key) or (manifest or {}).get(key) or '').strip()
            if not cmd:continue
            if _v35_is_noop_command(cmd):return False,_v35_component_failure(component,f'{label} is a no-op: {cmd}')
            ok,out=_v34_run_declared_command(root,cmd,label); outputs.append(out)
            if key in {'build_command','test_command'}:ran_build_or_test=True
            if not ok:return False,_v35_component_failure(component,out)
        if not ran_build_or_test:return False,_v35_component_failure(component,'Custom adapter did not execute a build/test verification command.')
        return True,'\n'.join(outputs)[-8000:]
    return _v411_previous_validate_component(work,manifest,component,user_request)

def _v35_discover_components(work, manifest):
    out=list(_v411_previous_discover_components(work,manifest) or []); root=Path(work).resolve()
    by_root={str(c.get('root') or '.').replace('\\','/').strip('/') or '.':c for c in out}
    markers=[('xmake.lua','xmake'),('meson.build','meson'),('platformio.ini','platformio'),('mix.exs','elixir_mix'),('rebar.config','erlang_rebar3'),('build.sbt','scala_sbt'),('dune-project','ocaml_dune'),('build.zig','zig')]
    for marker,adapter in markers:
        for p in root.rglob(marker):
            if not p.is_file() or _v35_ignored_component_path(p.relative_to(root)):continue
            rel=_v35_relroot(root,p.parent)
            existing=by_root.get(rel)
            if existing and str(existing.get('toolchain_adapter') or '') in {'generic','cpp_cmake','node'}:
                existing['toolchain_adapter']=adapter
                sp=_v34_toolchain_catalog().get(adapter,{})
                for k in ('dependency_command','build_command','test_command','run_command'):
                    if sp.get(k):existing[k]=sp[k]
            elif not existing:
                sp=_v34_toolchain_catalog().get(adapter,{})
                c={'id':adapter,'root':rel,'purpose':f'Detected {adapter} component','toolchain_adapter':adapter,'depends_on':[],
                   'dependency_command':sp.get('dependency_command',''),'build_command':sp.get('build_command',''),'test_command':sp.get('test_command',''),'run_command':sp.get('run_command','')}
                out.append(c);by_root[rel]=c
    return out

def _v36_release_identity():
    data=dict(_v411_previous_release_identity() or {})
    data.update({'version':'V'+V411_VERSION,'engine':V411_ENGINE,'registered_toolchain_adapters':V411_REGISTERED_TOOLCHAINS,'skill_cards':V411_SKILL_CARD_COUNT,'project_kind_platform_separation':True,'framework_first_routing':True,'custom_toolchains':True,'common_install_discovery':True})
    return data

