def _progress(callback, text=None, **fields):
    if text is not None:
        text=str(text)
        for old in ('V40.2','V40.1','V40','V39','V38.1','V38'):
            text=text.replace(old,'V41.1')
    return _v411_previous_progress(callback,text,**fields)

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    body=str(prompt or '')+(
      '\n\nV41.1 UNIVERSAL FACTORY RULE: Keep project kind separate from target platform, preserve explicit framework/engine/build-system choices, '
      'use the active stack skill cards, and never replace an unfamiliar explicit ecosystem with Python. A custom toolchain needs real source/layout evidence and a non-noop build/test path before completion.'
    )
    return _v411_previous_qwen_call(body,progress_callback,str(stage or '').replace('V40.2','V41.1').replace('V40','V41.1'),profile=profile,**kwargs)


# V41.1 canonical ownership hardening: build manifests/configuration may carry
# domain-related planning metadata, but they can never be canonical source owners.
def _v411_quarantine_build_metadata(manifest):
    if not isinstance(manifest, dict):
        return manifest
    rows=[]
    for raw in manifest.get('files') or []:
        if not isinstance(raw, dict):
            continue
        item=dict(raw)
        if _v401_is_build_manifest_or_config(item.get('path')):
            exported=_normalize_export_contract(item.get('exports'))
            existing=[str(x).strip() for x in item.get('build_metadata_symbols') or [] if str(x).strip()]
            combined=[]
            for value in list(existing)+list(exported or []):
                value=str(value).strip()
                if value and value not in combined:
                    combined.append(value)
            if combined:
                item['build_metadata_symbols']=combined
            item['exports']=[]
        rows.append(item)
    manifest['files']=rows
    return manifest

_v411_owner_score_before_config_quarantine = _v40_definition_mention_score
def _v40_definition_mention_score(item, symbol):
    if _v401_is_build_manifest_or_config((item or {}).get('path')):
        return -1000
    return _v411_owner_score_before_config_quarantine(item, symbol)

_v411_parse_before_config_quarantine = _parse_project_plan
def _parse_project_plan(text, user_request, max_files):
    return _v411_quarantine_build_metadata(_v411_parse_before_config_quarantine(text,user_request,max_files))

_v411_merge_before_config_quarantine = _merge_manifest
def _merge_manifest(base, reviewed, user_request, max_files):
    return _v411_quarantine_build_metadata(_v411_merge_before_config_quarantine(base,reviewed,user_request,max_files))

_v411_self_heal_before_config_quarantine = _v402_ensure_domain_owner_files
def _v402_ensure_domain_owner_files(manifest, max_files=None):
    _v411_quarantine_build_metadata(manifest)
    return _v411_self_heal_before_config_quarantine(manifest,max_files)


# =============================================================================
# V41.2 REACT/VITE CURRENT-SLICE CONVERGENCE HARDENING
# =============================================================================
# Exact regression fixed by this overlay (GearTrack 2026-08-30):
# - a React/Vite Foundation main.tsx imported ./App and ./index.css even though
#   those providers belonged to later milestones;
# - the generated tsconfig.json omitted compilerOptions.jsx;
# - Vite's canonical root index.html was planned as src/index.html;
# - the V39 active-slice import gate existed, but a later transaction wrapper
#   had captured the older V36.2 import checker, so JS/TS candidates could bypass
#   the current-milestone closure check.
#
# V41.2 fixes the function-chain defect at the final transaction boundary and
# adds deterministic conventional substrate repair before asking the model to
# improvise another patch.

V412_VERSION = '41.2.0'
V412_ENGINE = 'UNIVERSAL_MULTI_TOOLCHAIN_CONVERGENCE_FACTORY'
V412_WEB_FOUNDATION_REPAIR = os.getenv('JARVIS_V412_WEB_FOUNDATION_REPAIR', '1').strip().lower() not in {'0','false','no','off'}
V412_ACTIVE_JS_IMPORT_GATE = os.getenv('JARVIS_V412_ACTIVE_JS_IMPORT_GATE', '1').strip().lower() not in {'0','false','no','off'}
V412_CANONICAL_VITE_ROOT = os.getenv('JARVIS_V412_CANONICAL_VITE_ROOT', '1').strip().lower() not in {'0','false','no','off'}


def _v412_norm_rel(value):
    return str(value or '').replace('\\','/').strip('/')


def _v412_is_react_vite_manifest(manifest):
    files = [_v412_norm_rel(x.get('path')) for x in (manifest or {}).get('files') or [] if isinstance(x, dict)]
    adapters = {str(x.get('toolchain_adapter') or '').strip().lower() for x in (manifest or {}).get('components') or [] if isinstance(x, dict)}
    return bool(
        adapters.intersection({'react','vite'})
        or 'vite.config.ts' in files or 'vite.config.js' in files
        or any('vite' in str(x.get('purpose') or '').lower() for x in (manifest or {}).get('components') or [] if isinstance(x, dict))
    )


def _v412_js_import_refs(content):
    text = str(content or '')
    refs = []
    patterns = (
        r'\bfrom\s+["\']([^"\']+)["\']',
        r'\bimport\s+["\']([^"\']+)["\']',
        r'\bimport\s*\(\s*["\']([^"\']+)["\']\s*\)',
        r'\brequire\s*\(\s*["\']([^"\']+)["\']\s*\)',
    )
    for pat in patterns:
        refs.extend(re.findall(pat, text))
    return list(dict.fromkeys(str(x).strip() for x in refs if str(x).strip()))


def _v412_js_relative_candidates(rel, ref):
    import posixpath
    rel = _v412_norm_rel(rel)
    ref = str(ref or '').strip()
    base = Path(rel).parent.as_posix()
    if ref.startswith('@/'):
        target = 'src/' + ref[2:].lstrip('/')
    elif ref.startswith('./') or ref.startswith('../'):
        target = posixpath.normpath(posixpath.join(base, ref))
    else:
        return []
    suffix = Path(target).suffix.lower()
    if suffix:
        return [_v412_norm_rel(target)]
    exts = ('.ts','.tsx','.js','.jsx','.mjs','.cjs','.json','.css','.scss','.sass','.less','.svg')
    out = [target + ext for ext in exts]
    out += [target + '/index' + ext for ext in exts[:6]]
    return [_v412_norm_rel(x) for x in out]


def _v412_current_slice_import_error(work, manifest, rel, content):
    if not V412_ACTIVE_JS_IMPORT_GATE:
        return ''
    rel = _v412_norm_rel(rel)
    if Path(rel).suffix.lower() not in {'.ts','.tsx','.js','.jsx','.mjs','.cjs'}:
        return ''
    active = {_v412_norm_rel(x) for x in (manifest or {}).get('_v39_active_paths') or [] if str(x or '').strip()}
    if not active:
        return ''
    root = Path(work)
    missing = []
    for ref in _v412_js_import_refs(content):
        candidates = _v412_js_relative_candidates(rel, ref)
        if not candidates:
            continue
        # A provider is legal only when it is part of the current/previous green
        # slice or already exists as a real file. Merely appearing in the full
        # future architecture is not enough.
        legal = False
        for candidate in candidates:
            if candidate in active:
                legal = True
                break
            path = root / candidate
            if path.exists() and path.is_file():
                try:
                    txt = path.read_text(encoding='utf-8', errors='replace') if _looks_text_file(path) else 'binary'
                except Exception:
                    txt = 'present'
                if V33_SKELETON_MARKER not in txt and V34_RECOVERY_SEED_MARKER not in txt:
                    legal = True
                    break
        if not legal:
            missing.append((ref, candidates[0]))
    if missing:
        detail = ', '.join(f'{ref} -> {target}' for ref, target in missing[:8])
        return (
            'V41.2 current-slice JS/TS import gate: ' + rel + ' imports provider(s) outside the current green milestone: ' + detail + '. '
            'For an early boot entrypoint, render a minimal dependency-closed shell now and integrate future App/screens/features only after their milestone is green.'
        )
    return ''


_v412_prev_candidate_transaction_error = _candidate_transaction_error

def _candidate_transaction_error(work, manifest, rel, content, user_request=None, validation_failure=None, target_problems=None):
    # Final late-bound gate: do not route this through a captured V36/V38 alias.
    # That captured alias was the exact reason the GearTrack current-slice guard
    # existed in source but did not execute for main.tsx.
    err = _v412_current_slice_import_error(work, manifest or {}, rel, content)
    if err:
        return err
    return _v412_prev_candidate_transaction_error(
        work, manifest, rel, content, user_request=user_request,
        validation_failure=validation_failure, target_problems=target_problems,
    )


def _v412_manifest_file_map(manifest):
    return {_v412_norm_rel(x.get('path')): x for x in (manifest or {}).get('files') or [] if isinstance(x, dict) and x.get('path')}


def _v412_harden_web_manifest(manifest, user_request='', max_files=None):
    if not isinstance(manifest, dict) or not V412_CANONICAL_VITE_ROOT or not _v412_is_react_vite_manifest(manifest):
        return manifest
    rows = [dict(x) for x in manifest.get('files') or [] if isinstance(x, dict) and x.get('path')]
    # Canonical Vite HTML host lives at component root unless vite.config explicitly
    # chooses another root. Planner mistakes such as src/index.html cause Vite's
    # real build to fail after TypeScript succeeds.
    has_root_index = any(_v412_norm_rel(x.get('path')) == 'index.html' for x in rows)
    for row in rows:
        path = _v412_norm_rel(row.get('path'))
        if path == 'src/index.html' and not has_root_index:
            row['path'] = 'index.html'
            row['purpose'] = str(row.get('purpose') or 'Vite HTML host') + ' (canonical Vite root host)'
            row['phase'] = 'foundation'
            has_root_index = True
    if not has_root_index:
        rows.append({
            'path':'index.html','purpose':'Canonical Vite root HTML host','phase':'foundation',
            'depends_on':['src/main.tsx'] if any(_v412_norm_rel(x.get('path')) == 'src/main.tsx' for x in rows) else [],
            'exports':[],'contracts':[]
        })
    # A TypeScript Vite config is commonly referenced by the root TS project. Plan
    # its config up-front so a generated project reference cannot point to a future/
    # nonexistent file during the Foundation build.
    paths = {_v412_norm_rel(x.get('path')) for x in rows}
    has_ts = any(Path(x).suffix.lower() in {'.ts','.tsx'} for x in paths)
    if has_ts and 'vite.config.ts' in paths and 'tsconfig.node.json' not in paths:
        rows.append({
            'path':'tsconfig.node.json','purpose':'TypeScript configuration for Vite build configuration','phase':'foundation',
            'depends_on':['vite.config.ts'],'exports':[],'contracts':[]
        })
    # Rewrite dependency references to a canonicalized HTML path and dedupe.
    valid_paths = {_v412_norm_rel(x.get('path')) for x in rows}
    clean = []
    seen = set()
    for row in rows:
        path = _v412_norm_rel(row.get('path'))
        if not path or path in seen:
            continue
        seen.add(path)
        row['path'] = path
        deps = []
        for dep in row.get('depends_on') or []:
            dep = _v412_norm_rel(dep)
            if dep == 'src/index.html': dep = 'index.html'
            if dep in valid_paths and dep != path and dep not in deps:
                deps.append(dep)
        row['depends_on'] = deps
        clean.append(row)
    manifest['files'] = clean
    return manifest


_v412_prev_execute_manifest = _v362_execute_manifest

def _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback=None, raw_plan=''):
    manifest = _v412_harden_web_manifest(dict(manifest or {}), user_request, max_files)
    return _v412_prev_execute_manifest(user_request, manifest, work, max_files, progress_callback, raw_plan)


_v412_prev_is_foundation_item = _v39_is_foundation_item

def _v39_is_foundation_item(item):
    rel = _v412_norm_rel((item or {}).get('path')).lower()
    if rel == 'index.html' and ('vite' in _v39_file_blob(item) or 'html host' in _v39_file_blob(item) or 'foundation' == str((item or {}).get('phase') or '').lower()):
        return True
    if Path(rel).name.lower() == 'vite-env.d.ts':
        return True
    return _v412_prev_is_foundation_item(item)


def _v412_tsconfig_load(path):
    try:
        text = Path(path).read_text(encoding='utf-8', errors='replace')
        return _v362_jsonc_loads(text)
    except Exception:
        return None


def _v412_ensure_react_tsconfig(work, manifest):
    if not V412_WEB_FOUNDATION_REPAIR or not _v412_is_react_vite_manifest(manifest):
        return False
    path = Path(work) / 'tsconfig.json'
    data = _v412_tsconfig_load(path)
    if not isinstance(data, dict):
        return False
    options = data.setdefault('compilerOptions', {})
    if not isinstance(options, dict):
        options = {}; data['compilerOptions'] = options
    changed = False
    jsx = str(options.get('jsx') or '').strip().lower()
    if jsx not in {'react-jsx','react-jsxdev','react','preserve'}:
        options['jsx'] = 'react-jsx'; changed = True
    # Keep project references only when their target config is both planned or
    # already materialized. This prevents tsc -b from failing before source repair.
    refs = data.get('references')
    if isinstance(refs, list):
        planned = {_v412_norm_rel(x.get('path')) for x in (manifest or {}).get('files') or [] if isinstance(x, dict)}
        kept = []
        for row in refs:
            if not isinstance(row, dict) or not row.get('path'):
                continue
            raw = str(row.get('path')).replace('\\','/').strip()
            candidate = raw[2:] if raw.startswith('./') else raw
            if not candidate.endswith('.json') and not Path(candidate).suffix:
                candidate += '.json'
            candidate = _v412_norm_rel(candidate)
            if candidate in planned or (Path(work)/candidate).exists():
                kept.append(row)
        if kept != refs:
            data['references'] = kept; changed = True
    if changed:
        path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
        try:
            _append_project_event(work, 'v412_react_tsconfig_hardened', 'Deterministically hardened React/TypeScript compiler substrate.', file='tsconfig.json')
        except Exception:
            pass
    return changed


def _v412_minimal_react_boot_source(existing=''):
    # Avoid JSX in the earliest shell so the bootstrap remains independently
    # compilable even while TypeScript configuration is being repaired.
    return (
        "import React from 'react';\n"
        "import ReactDOM from 'react-dom/client';\n\n"
        "ReactDOM.createRoot(document.getElementById('root')!).render(\n"
        "  React.createElement(React.StrictMode, null,\n"
        "    React.createElement('div', { id: 'app' }, 'Application shell ready')\n"
        "  ),\n"
        ");\n"
    )


def _v412_root_index_html(entry='src/main.tsx'):
    entry = '/' + _v412_norm_rel(entry)
    return (
        '<!doctype html>\n<html lang="en">\n<head>\n'
        '  <meta charset="UTF-8" />\n'
        '  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n'
        '  <title>Application</title>\n</head>\n<body>\n'
        '  <div id="root"></div>\n'
        f'  <script type="module" src="{entry}"></script>\n'
        '</body>\n</html>\n'
    )


def _v412_repair_react_vite_failure(user_request, manifest, work, failure, progress_callback=None):
    if not V412_WEB_FOUNDATION_REPAIR or not _v412_is_react_vite_manifest(manifest):
        return False
    text = str(failure or '')
    low = text.lower()
    root = Path(work)
    changed = False

    if 'ts17004' in low or "cannot use jsx unless the '--jsx' flag is provided" in low:
        changed = _v412_ensure_react_tsconfig(root, manifest) or changed

    # tsc -b project reference failures are substrate defects, not application
    # behavior defects. If the referenced config is current/planned, create a
    # conservative Vite config project so the real build can advance.
    if ('tsconfig.node.json' in low and ('cannot read file' in low or 'ts6053' in low or 'ts5083' in low)):
        p = root / 'tsconfig.node.json'
        if not p.exists():
            p.write_text(json.dumps({
                'compilerOptions': {
                    'target':'ES2022','lib':['ES2023'],'module':'ESNext','skipLibCheck':True,
                    'moduleResolution':'bundler','allowImportingTsExtensions':True,
                    'isolatedModules':True,'moduleDetection':'force','noEmit':True,'strict':True
                },
                'include':['vite.config.ts']
            }, indent=2) + '\n', encoding='utf-8')
            changed = True

    # Exact GearTrack failure class: early boot main imports future App/styles.
    # Do not prematurely generate feature code. Replace only a bootstrap entrypoint
    # with a dependency-closed shell; later integration touchpoints evolve it.
    missing_matches = re.findall(
        r'(?m)^([^\n:(]+\.(?:ts|tsx|js|jsx))\(\d+,\d+\):\s*error\s+TS2307:\s*Cannot find module\s+[\'\"]([^\'\"]+)[\'\"]',
        text
    )
    active = {_v412_norm_rel(x) for x in (manifest or {}).get('_v39_active_paths') or []}
    by_importer = {}
    for importer, ref in missing_matches:
        importer = _v412_norm_rel(importer)
        if ref.startswith(('./','../','@/')):
            by_importer.setdefault(importer, []).append(ref)
    for importer, refs in by_importer.items():
        item = _manifest_file_item(manifest, importer) or {'path':importer,'purpose':'entrypoint'}
        if not _v401_boot_source_candidate(item):
            continue
        future_ref = False
        for ref in refs:
            cands = _v412_js_relative_candidates(importer, ref)
            if cands and not any(c in active for c in cands):
                future_ref = True; break
        if future_ref:
            p = root / importer
            if p.exists():
                p.write_text(_v412_minimal_react_boot_source(p.read_text(encoding='utf-8', errors='replace')), encoding='utf-8')
                changed = True
                try:
                    _append_project_event(work, 'v412_boot_shell_repaired', f'Removed future-milestone imports from early React boot shell {importer}.', file=importer, imports=refs)
                except Exception:
                    pass

    # Vite always needs a host entry at root unless a custom root is configured.
    # Repair this conventional substrate deterministically when absent or when the
    # real build explicitly reports the entry-module failure.
    if not (root/'index.html').exists() and (
        'could not resolve entry module' in low or 'index.html' in low or any(_v412_norm_rel(x.get('path')) == 'index.html' for x in (manifest or {}).get('files') or [] if isinstance(x, dict))
    ):
        entry = 'src/main.tsx' if (root/'src/main.tsx').exists() else ('src/main.jsx' if (root/'src/main.jsx').exists() else 'src/main.ts')
        (root/'index.html').write_text(_v412_root_index_html(entry), encoding='utf-8')
        changed = True

    if changed:
        try:
            _v36_build_repo_graph(root, manifest, write=True)
            _v36_build_contract_registry(root, manifest, write=True)
            _append_project_event(root, 'v412_deterministic_web_substrate_repair', 'Applied deterministic React/Vite build-substrate repair before model fallback.')
        except Exception:
            pass
    return changed


_v412_prev_repair_real_validation_failure = _repair_real_validation_failure

def _repair_real_validation_failure(user_request, manifest, work, failure, progress_callback=None):
    if _v412_repair_react_vite_failure(user_request, manifest or {}, work, failure, progress_callback):
        return True
    return _v412_prev_repair_real_validation_failure(user_request, manifest, work, failure, progress_callback)


