# =============================================================================
# V41.3.2 REPAIR CONVERGENCE / ACCEPTED-REVISION HARDENING
# =============================================================================
# Regression fixed by this overlay (GearTrack 2026-08-30):
# - rejected bootstrap source could temporarily exist on disk and later be
#   mistaken for an accepted/edit-only file;
# - Aider SEARCH blocks could contain copied display line-number prefixes;
# - the milestone repair loop could stop after one no-commit generation attempt;
# - build-required React/Tauri entrypoints needed to remain in Foundation as
#   dependency-closed shells and evolve only after later vertical slices were green.

V413_VERSION = '41.3.2'
V413_ENGINE = 'UNIVERSAL_REPAIR_CONVERGENCE_FACTORY'
V413_ACCEPTED_LEDGER = '.jarvis_v413_accepted_revisions.json'
V413_REGEN_ATTEMPTS = max(2, int(os.getenv('JARVIS_V413_REGEN_ATTEMPTS', '4')))
V413_ACCEPTED_REVISION_GUARD = os.getenv('JARVIS_V413_ACCEPTED_REVISION_GUARD', '1').strip().lower() not in {'0','false','no','off'}
V413_LINE_NUMBER_PATCH_NORMALIZATION = os.getenv('JARVIS_V413_LINE_NUMBER_PATCH_NORMALIZATION', '1').strip().lower() not in {'0','false','no','off'}
V413_DETERMINISTIC_BOOT_SHELLS = os.getenv('JARVIS_V413_DETERMINISTIC_BOOT_SHELLS', '1').strip().lower() not in {'0','false','no','off'}


def _v413_norm_rel(value):
    return str(value or '').replace('\\','/').strip('/')


def _v413_sha256_path(path):
    try:
        return hashlib.sha256(Path(path).read_bytes()).hexdigest()
    except Exception:
        return ''


def _v413_ledger_path(work):
    return Path(work) / V413_ACCEPTED_LEDGER


def _v413_load_accepted(work):
    try:
        data = json.loads(_v413_ledger_path(work).read_text(encoding='utf-8', errors='replace'))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _v413_save_accepted(work, data):
    p = _v413_ledger_path(work)
    try:
        p.write_text(json.dumps(data, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
    except Exception:
        pass


def _v413_mark_accepted(work, rel, reason='commit_gate'):
    if not V413_ACCEPTED_REVISION_GUARD:
        return
    rel = _v413_norm_rel(rel)
    p = Path(work) / rel
    if not p.exists() or not p.is_file():
        return
    data = _v413_load_accepted(work)
    files = data.setdefault('files', {})
    old = files.get(rel) or {}
    sha = _v413_sha256_path(p)
    files[rel] = {
        'sha256': sha,
        'revision': int(old.get('revision') or 0) + (0 if old.get('sha256') == sha else 1),
        'accepted_at': _utc_stamp(),
        'reason': str(reason or 'commit_gate'),
    }
    data.update({'version':'V'+V413_VERSION, 'engine':V413_ENGINE, 'updated_at':_utc_stamp()})
    _v413_save_accepted(work, data)


def _v413_is_accepted(work, rel):
    if not V413_ACCEPTED_REVISION_GUARD:
        return _v39_file_is_implemented(work, rel)
    rel = _v413_norm_rel(rel)
    row = (_v413_load_accepted(work).get('files') or {}).get(rel) or {}
    p = Path(work) / rel
    return bool(row.get('sha256')) and p.exists() and p.is_file() and _v413_sha256_path(p) == str(row.get('sha256') or '')


def _v413_forget_accepted(work, rel):
    rel = _v413_norm_rel(rel)
    data = _v413_load_accepted(work)
    files = data.get('files') or {}
    if rel in files:
        files.pop(rel, None)
        data['files'] = files
        data['updated_at'] = _utc_stamp()
        _v413_save_accepted(work, data)


def _v413_clear_leaf_repair_state(work, rel):
    """A rejected/unaccepted file has no trustworthy edit history."""
    rel = _v413_norm_rel(rel)
    try:
        state = _v37_agent_state_load(work)
        for key in ('patch_history', globals().get('V38_READ_RECEIPTS_KEY','v38_read_receipts'), globals().get('V38_REPAIR_REQUESTS_KEY','v38_repair_requests')):
            bucket = state.get(key)
            if isinstance(bucket, dict):
                bucket.pop(rel, None)
        _v37_agent_state_save(work, state)
    except Exception:
        pass


def _v413_numbered_block(text):
    lines = str(text or '').replace('\r\n','\n').replace('\r','\n').split('\n')
    nonempty = [x for x in lines if x.strip()]
    if len(nonempty) < 2:
        return False
    nums = []
    for line in nonempty:
        m = re.match(r'^\s*(\d{1,6})\s*(?::|\||¦|│)\s?(.*)$', line)
        if m:
            nums.append(int(m.group(1)))
    if len(nums) < max(2, int(len(nonempty) * 0.70)):
        return False
    # Display line numbers are normally monotonic; this avoids rewriting real
    # data formats which happen to contain a few numeric labels.
    return all(b >= a for a, b in zip(nums, nums[1:]))


def _v413_strip_display_line_numbers(text):
    text = str(text or '')
    if not V413_LINE_NUMBER_PATCH_NORMALIZATION or not _v413_numbered_block(text):
        return text
    out = []
    for line in text.replace('\r\n','\n').replace('\r','\n').split('\n'):
        m = re.match(r'^\s*\d{1,6}\s*(?::|\||¦|│)\s?(.*)$', line)
        out.append(m.group(1) if m else line)
    return '\n'.join(out)


_v413_prev_apply_search_replace = _v36_apply_search_replace

def _v36_apply_search_replace(current, replacements):
    candidate, err = _v413_prev_apply_search_replace(current, replacements)
    if not err or not V413_LINE_NUMBER_PATCH_NORMALIZATION:
        return candidate, err
    normalized = []
    changed = False
    for rep in replacements or []:
        search = str((rep or {}).get('search') or '')
        replace = str((rep or {}).get('replace') or '')
        nsearch = _v413_strip_display_line_numbers(search)
        nreplace = _v413_strip_display_line_numbers(replace) if _v413_numbered_block(replace) else replace
        changed = changed or nsearch != search or nreplace != replace
        normalized.append({'search':nsearch, 'replace':nreplace})
    if changed:
        retry, retry_err = _v413_prev_apply_search_replace(current, normalized)
        if not retry_err:
            return retry, ''
    return candidate, err


def _v413_is_react_manifest(manifest):
    try:
        return _v412_is_react_vite_manifest(manifest)
    except Exception:
        return False


def _v413_is_tauri_manifest(manifest):
    files = {_v413_norm_rel(x.get('path')).lower() for x in (manifest or {}).get('files') or [] if isinstance(x, dict)}
    comps = ' '.join(' '.join(str(x.get(k) or '') for k in ('purpose','toolchain_adapter','framework','language')).lower() for x in (manifest or {}).get('components') or [] if isinstance(x, dict))
    return any(p.startswith('src-tauri/') for p in files) or 'tauri' in comps


def _v413_minimal_react_main():
    try:
        return _v412_minimal_react_boot_source()
    except Exception:
        return (
            "import React from 'react';\n"
            "import ReactDOM from 'react-dom/client';\n\n"
            "ReactDOM.createRoot(document.getElementById('root')!).render(\n"
            "  React.createElement(React.StrictMode, null, React.createElement('div', null, 'Application shell ready'))\n"
            ");\n"
        )


def _v413_minimal_tauri_main():
    return (
        "#![cfg_attr(not(debug_assertions), windows_subsystem = \"windows\")]\n\n"
        "fn main() {\n"
        "    tauri::Builder::default()\n"
        "        .run(tauri::generate_context!())\n"
        "        .expect(\"error while running Tauri application\");\n"
        "}\n"
    )


def _v413_minimal_tauri_lib():
    return (
        "pub fn run() {\n"
        "    tauri::Builder::default()\n"
        "        .run(tauri::generate_context!())\n"
        "        .expect(\"error while running Tauri application\");\n"
        "}\n"
    )


def _v413_is_boot_shell(rel, manifest):
    rel = _v413_norm_rel(rel).lower()
    if rel in {'src/main.tsx','src/main.ts','src/main.jsx','src/main.js'} and _v413_is_react_manifest(manifest):
        return True
    if rel in {'src-tauri/src/main.rs','src-tauri/src/lib.rs'} and _v413_is_tauri_manifest(manifest):
        return True
    return False


def _v413_write_boot_shell(work, rel, manifest):
    reln = _v413_norm_rel(rel)
    p = Path(work) / reln
    p.parent.mkdir(parents=True, exist_ok=True)
    low = reln.lower()
    if low == 'src/main.tsx' and _v413_is_react_manifest(manifest):
        p.write_text(_v413_minimal_react_main(), encoding='utf-8')
        return True
    if low == 'src-tauri/src/main.rs' and _v413_is_tauri_manifest(manifest):
        p.write_text(_v413_minimal_tauri_main(), encoding='utf-8')
        return True
    if low == 'src-tauri/src/lib.rs' and _v413_is_tauri_manifest(manifest):
        p.write_text(_v413_minimal_tauri_lib(), encoding='utf-8')
        return True
    return False


# Keep build-required boot entrypoints in Foundation even when their final
# architecture references later features. They start as shells and are evolved
# through the existing integration-touch mechanism.
_v413_prev_is_foundation_item = _v39_is_foundation_item

def _v39_is_foundation_item(item):
    rel = _v413_norm_rel((item or {}).get('path')).lower()
    if rel in {'src/main.tsx','src/main.ts','src/main.jsx','src/main.js','src-tauri/src/main.rs','src-tauri/src/lib.rs','src-tauri/build.rs','src-tauri/tauri.conf.json'}:
        return True
    return _v413_prev_is_foundation_item(item)


# Strip future-source dependencies from boot entrypoints for milestone ordering.
# The final integration pass can still evolve these same files later.
_v413_prev_build_milestones = _v39_build_milestones

def _v39_build_milestones(manifest, user_request=''):
    patched = dict(manifest or {})
    rows = []
    for raw in (manifest or {}).get('files') or []:
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        rel = _v413_norm_rel(item.get('path'))
        if _v413_is_boot_shell(rel, manifest):
            item['phase'] = 'foundation'
            item['depends_on'] = [d for d in (item.get('depends_on') or []) if _v401_is_build_manifest_or_config(d)]
            item.setdefault('contracts', [])
            item['contracts'] = list(item.get('contracts') or []) + [
                'V41.3.2 Foundation boot shell: remain dependency-closed until later green milestones are integrated.'
            ]
        rows.append(item)
    patched['files'] = rows
    return _v413_prev_build_milestones(patched, user_request)


# Whole-generation wrapper: an unaccepted on-disk draft is not an established
# file. Remove it before delegation so inherited code cannot accidentally switch
# into patch/edit mode merely because Path.exists() is true.
_v413_prev_generate_planned_file = _generate_planned_file

def _generate_planned_file(user_request, manifest, work, file_item, progress_callback=None):
    rel = _v413_norm_rel((file_item or {}).get('path'))
    target = Path(work) / rel
    accepted_before = _v413_is_accepted(work, rel)
    accepted_snap = _v401_snapshot_file(target) if accepted_before else {'exists':False,'bytes':b''}

    if V413_ACCEPTED_REVISION_GUARD and target.exists() and not accepted_before:
        try:
            target.unlink()
            _append_project_event(work, 'v413_unaccepted_draft_discarded', f'Discarded unaccepted draft before whole-file regeneration: {rel}.', file=rel)
        except Exception:
            pass
        _v413_forget_accepted(work, rel)
        _v413_clear_leaf_repair_state(work, rel)

    # Conventional boot shells are deterministic in Foundation. This removes a
    # high-frequency failure surface from the small model while later integration
    # still edits the same file after providers become real.
    active = {_v413_norm_rel(x) for x in (manifest or {}).get('_v39_active_paths') or []}
    in_foundation = str((file_item or {}).get('phase') or '').lower() == 'foundation' or rel in active
    if V413_DETERMINISTIC_BOOT_SHELLS and in_foundation and _v413_is_boot_shell(rel, manifest):
        try:
            if _v413_write_boot_shell(work, rel, manifest):
                err = _v401_file_green_error(work, manifest or {}, rel)
                if not err:
                    _v413_mark_accepted(work, rel, 'deterministic_foundation_boot_shell')
                    _append_project_event(work, 'v413_boot_shell_accepted', f'Deterministic dependency-closed boot shell accepted: {rel}.', file=rel)
                    return True, rel
                if accepted_before:
                    _v401_restore_file(target, accepted_snap)
                elif target.exists():
                    target.unlink()
                _append_project_event(work, 'v413_boot_shell_rejected', f'Deterministic boot shell did not pass commit checks: {rel}.', file=rel, validation_error=err)
        except Exception as exc:
            if accepted_before:
                _v401_restore_file(target, accepted_snap)
            _append_project_event(work, 'v413_boot_shell_exception', f'Deterministic boot shell failed safely: {rel}.', file=rel, error=str(exc))

    ok, wrote = _v413_prev_generate_planned_file(user_request, manifest, work, file_item, progress_callback)
    if ok and target.exists():
        err = _v401_file_green_error(work, manifest or {}, rel)
        if not err:
            _v413_mark_accepted(work, rel, 'model_generation_commit_gate')
            return True, wrote or rel
    if not ok and not accepted_before and target.exists() and not _v413_is_accepted(work, rel):
        try:
            target.unlink()
        except Exception:
            pass
    return bool(ok), wrote


# Repairs are edit-only for accepted revisions. A missing/unaccepted target gets
# a fresh whole-file generation instead of wasting SEARCH/REPLACE attempts.
_v413_prev_repair_file_for_issues = _repair_file_for_issues

def _repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback=None, validation_failure=None):
    rel = _v413_norm_rel(rel)
    target = Path(work) / rel
    if V413_ACCEPTED_REVISION_GUARD and (not target.exists() or not _v413_is_accepted(work, rel)):
        _v413_clear_leaf_repair_state(work, rel)
        item = _manifest_file_item(manifest or {}, rel) or {
            'path':rel, 'purpose':'Current milestone implementation', 'phase':'integration',
            'depends_on':[], 'exports':[], 'contracts':[]
        }
        item = dict(item)
        item.setdefault('contracts', [])
        evidence = '; '.join(str(x) for x in (problems or []) if str(x).strip())[:1800]
        item['contracts'] = list(item.get('contracts') or []) + [
            'V41.3.2 regeneration mode: generate the ENTIRE file from current canonical contracts. Do not patch or preserve rejected draft architecture.',
            ('Previous rejection evidence: ' + evidence) if evidence else 'Previous draft was not accepted by the central commit gate.'
        ]
        ok, _ = _generate_planned_file(user_request, manifest, work, item, progress_callback)
        return bool(ok)
    ok = _v413_prev_repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback, validation_failure=validation_failure)
    if ok and target.exists() and not _v401_file_green_error(work, manifest or {}, rel):
        _v413_mark_accepted(work, rel, 'targeted_repair_commit_gate')
    return bool(ok)


# Milestone convergence: a no-commit round is evidence for the next strategy,
# not an immediate terminal condition. Retry bounded whole-file regeneration for
# missing/unaccepted targets and only then declare the milestone blocked.
_v413_prev_milestone_issues = _v39_milestone_issues

def _v39_milestone_issues(work, manifest, milestone_paths):
    issues = list(_v413_prev_milestone_issues(work, manifest, milestone_paths) or [])
    if V413_ACCEPTED_REVISION_GUARD:
        existing = {(str(x.get('file') or ''), str(x.get('kind') or '')) for x in issues}
        for rel in milestone_paths or []:
            rel = _v413_norm_rel(rel)
            p = Path(work) / rel
            if p.exists() and p.is_file() and not _v413_is_accepted(work, rel):
                key = (rel, 'unaccepted')
                if key not in existing:
                    issues.append({'file':rel,'problem':'Milestone file exists only as an unaccepted/rejected revision; regenerate the whole file from current contracts.','kind':'unaccepted'})
    out=[]; seen=set()
    for row in issues:
        key=(str(row.get('file') or ''), re.sub(r'\s+',' ',str(row.get('problem') or '')).strip().lower())
        if key not in seen:
            seen.add(key); out.append(row)
    return out[:100]


def _v39_repair_milestone(user_request, manifest, work, milestone, progress_callback=None):
    paths = [_v413_norm_rel(x) for x in (milestone or {}).get('files') or []]
    item_map = {_v413_norm_rel(x.get('path')): dict(x) for x in (manifest or {}).get('files') or [] if isinstance(x, dict) and x.get('path')}
    rounds = max(int(globals().get('V39_MILESTONE_REPAIR_ROUNDS', 3)), V413_REGEN_ATTEMPTS)
    prior_evidence = {}
    for round_no in range(1, rounds + 1):
        issues = _v39_milestone_issues(work, manifest, paths)
        if not issues:
            return True, []
        by_file = {}
        for row in issues:
            by_file.setdefault(_v413_norm_rel(row.get('file')), []).append(row)
        for rel, rows in list(by_file.items())[:12]:
            if not rel or _v39_binary_asset_rel(rel):
                continue
            target = Path(work) / rel
            kinds = {str(x.get('kind') or '') for x in rows}
            problems = [str(x.get('problem') or '') for x in rows if str(x.get('problem') or '').strip()]
            prior_evidence[rel] = problems
            regenerate = (not target.exists()) or ('missing' in kinds) or ('skeleton' in kinds) or ('unaccepted' in kinds) or not _v413_is_accepted(work, rel)
            if regenerate:
                _v413_clear_leaf_repair_state(work, rel)
                if target.exists() and not _v413_is_accepted(work, rel):
                    try: target.unlink()
                    except Exception: pass
                item = dict(item_map.get(rel) or {'path':rel,'purpose':'Current milestone implementation','phase':'integration','depends_on':[],'exports':[],'contracts':[]})
                item.setdefault('contracts', [])
                item['contracts'] = list(item.get('contracts') or []) + [
                    f'V41.3.2 fresh regeneration attempt {round_no}/{rounds}. Generate a complete dependency-closed implementation; do not patch rejected source.',
                    'Rejection evidence: ' + ' | '.join(problems)[:2200],
                ]
                _progress(progress_callback, f'V41.3 regeneration {round_no}/{rounds}: {rel}', stage='generating', milestone=(milestone or {}).get('id'))
                try:
                    _generate_planned_file(user_request, manifest, work, item, progress_callback)
                except Exception as exc:
                    _append_project_event(work, 'v413_regeneration_exception', f'Fresh regeneration failed safely for {rel}.', file=rel, attempt=round_no, error=str(exc))
                continue
            _progress(progress_callback, f'V41.3 targeted repair {round_no}/{rounds}: {rel}', stage='repairing', milestone=(milestone or {}).get('id'))
            try:
                _repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback, validation_failure='\n'.join(problems))
            except Exception as exc:
                _append_project_event(work, 'v413_targeted_repair_exception', f'Targeted repair failed safely for {rel}.', file=rel, attempt=round_no, error=str(exc))
        try:
            _v373_refresh_project_kb(work, manifest, reason=f'v413_milestone_repair_{(milestone or {}).get("id")}_{round_no}', force=True)
        except Exception:
            pass
        if not _v39_milestone_issues(work, manifest, paths):
            return True, []
    final = _v39_milestone_issues(work, manifest, paths)
    return not final, final


# Make the acceptance ledger authoritative for V39's "implemented" test when a
# ledger exists. This prevents stale rejected temp source from satisfying build
# readiness while retaining backwards compatibility for old workspaces.
_v413_prev_file_is_implemented = _v39_file_is_implemented

def _v39_file_is_implemented(work, rel):
    data = _v413_load_accepted(work)
    if V413_ACCEPTED_REVISION_GUARD and (data.get('files') or {}):
        return _v413_is_accepted(work, rel)
    return _v413_prev_file_is_implemented(work, rel)


# Release identity / prompts / progress.
_v413_prev_release_identity = _v36_release_identity

