_v413_prev_progress = _progress

def _progress(callback, text=None, **fields):
    if text is not None:
        text = str(text).replace('V41.2','V41.3.2').replace('V41.1','V41.3.2')
    return _v413_prev_progress(callback, text, **fields)


_v413_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    body = str(prompt or '') + (
        '\n\nV41.3.2 REPAIR CONVERGENCE RULE: Existing-on-disk is not the same as accepted. '
        'A rejected or unaccepted file must be regenerated whole from the current milestone contracts; do not patch remembered draft source. '
        'For an accepted file, SEARCH text must come from the exact current revision and must not contain copied editor/display line numbers. '
        'Foundation boot entrypoints must stay minimal and dependency-closed; wire later providers only after their milestone is green.'
    )
    stage = str(stage or '').replace('V41.2','V41.3.2').replace('V41.1','V41.3.2')
    return _v413_prev_qwen_call(body, progress_callback, stage, profile=profile, **kwargs)

# ---- V41.3.2 Tauri Foundation / Cargo coherence -------------------------------

def _v413_tauri_major_from_text(text):
    m = re.search(r'(?m)^\s*tauri\s*=\s*(?:\{[^\n]*version\s*=\s*)?["\']\s*([12])(?:\.|["\'])', str(text or ''))
    return int(m.group(1)) if m else 0


def _v413_tauri_major(work):
    p = Path(work) / 'src-tauri' / 'Cargo.toml'
    try:
        return _v413_tauri_major_from_text(p.read_text(encoding='utf-8', errors='replace'))
    except Exception:
        return 0


def _v413_harden_tauri_manifest(manifest):
    if not isinstance(manifest, dict) or not _v413_is_tauri_manifest(manifest):
        return manifest
    patched = dict(manifest)
    rows = [dict(x) for x in (manifest.get('files') or []) if isinstance(x, dict) and x.get('path')]
    paths = {_v413_norm_rel(x.get('path')) for x in rows}
    additions = [
        ('src-tauri/build.rs','Tauri build script'),
        ('src-tauri/tauri.conf.json','Tauri application configuration'),
        ('src-tauri/src/main.rs','Minimal Tauri executable boot entrypoint'),
        ('src-tauri/src/lib.rs','Minimal Tauri library boot shell'),
    ]
    for rel, purpose in additions:
        if rel not in paths:
            rows.append({'path':rel,'purpose':purpose,'phase':'foundation','depends_on':['src-tauri/Cargo.toml'] if rel != 'src-tauri/Cargo.toml' else [],'exports':[],'contracts':[]})
            paths.add(rel)
    for item in rows:
        rel = _v413_norm_rel(item.get('path'))
        if rel in {'src-tauri/build.rs','src-tauri/tauri.conf.json','src-tauri/src/main.rs','src-tauri/src/lib.rs'}:
            item['phase'] = 'foundation'
            item['depends_on'] = ['src-tauri/Cargo.toml'] if rel != 'src-tauri/Cargo.toml' and 'src-tauri/Cargo.toml' in paths else []
            item.setdefault('contracts', [])
            rule = 'V41.3.2 Tauri Foundation substrate: this file must compile without importing future domain/services/UI providers.'
            if rule not in item['contracts']:
                item['contracts'] = list(item['contracts']) + [rule]
    patched['files'] = rows
    return patched


# Re-wrap milestone planner so the deterministic Tauri substrate is part of the
# actual milestone graph, not merely created as an out-of-band file.
_v4132_prev_build_milestones_with_tauri = _v39_build_milestones

def _v39_build_milestones(manifest, user_request=''):
    return _v4132_prev_build_milestones_with_tauri(_v413_harden_tauri_manifest(manifest), user_request)


_v4132_prev_execute_manifest_with_tauri = _v362_execute_manifest

def _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback=None, raw_plan=''):
    hardened = _v413_harden_tauri_manifest(dict(manifest or {}))
    return _v4132_prev_execute_manifest_with_tauri(user_request, hardened, work, max_files, progress_callback, raw_plan)


def _v413_harden_tauri_cargo(work):
    p = Path(work) / 'src-tauri' / 'Cargo.toml'
    if not p.exists():
        return False
    try:
        text = p.read_text(encoding='utf-8', errors='replace')
    except Exception:
        return False
    original = text
    major = _v413_tauri_major_from_text(text)
    if major == 1:
        # Tauri 1 exposes shell/dialog/fs through its built-in allowlist; mixing
        # Tauri-2-style plugin crates with a 1.x core creates an incoherent graph.
        text = re.sub(r'(?m)^\s*tauri-plugin-(?:shell|dialog|fs)\s*=.*\n?', '', text)
        # Tauri 1 uses api-all rather than the invalid generic "all" feature.
        def fix_tauri_features(m):
            body = m.group(0)
            body = re.sub(r'features\s*=\s*\[\s*["\']all["\']\s*\]', 'features = ["api-all"]', body)
            return body
        text = re.sub(r'(?m)^\s*tauri\s*=\s*\{[^\n]*\}', fix_tauri_features, text)
    # sqlx has Tokio/async-std runtime features; runtime-tauri is not a sqlx
    # runtime feature and causes Cargo resolution to fail before any Rust source.
    text = text.replace('"runtime-tauri"', '"runtime-tokio"').replace("'runtime-tauri'", "'runtime-tokio'")

    # Ensure the deterministic build.rs has its matching build dependency.
    if major in {1,2} and not re.search(r'(?m)^\s*tauri-build\s*=', text):
        dep = f'tauri-build = {{ version = "{major}", features = [] }}\n'
        m = re.search(r'(?m)^\[build-dependencies\]\s*$', text)
        if m:
            insert = m.end()
            text = text[:insert] + '\n' + dep + text[insert:]
        else:
            text += '\n[build-dependencies]\n' + dep
    if text != original:
        p.write_text(text, encoding='utf-8')
        try:
            _append_project_event(work, 'v413_tauri_cargo_hardened', 'Repaired deterministic Tauri/Cargo dependency-feature coherence.', file='src-tauri/Cargo.toml', tauri_major=major)
        except Exception:
            pass
        return True
    return False


def _v413_tauri_build_rs():
    return 'fn main() {\n    tauri_build::build()\n}\n'


def _v413_tauri_conf(work):
    major = _v413_tauri_major(work)
    cargo = Path(work) / 'src-tauri' / 'Cargo.toml'
    name = 'Application'
    version = '0.1.0'
    try:
        text = cargo.read_text(encoding='utf-8', errors='replace')
        m = re.search(r'(?m)^\s*name\s*=\s*["\']([^"\']+)', text)
        if m: name = m.group(1).replace('-',' ').title()
        m = re.search(r'(?m)^\s*version\s*=\s*["\']([^"\']+)', text)
        if m: version = m.group(1)
    except Exception:
        pass
    if major == 2:
        return json.dumps({
            '$schema':'https://schema.tauri.app/config/2',
            'productName':name,'version':version,'identifier':'com.jarvis.application',
            'build':{'beforeDevCommand':'npm run dev','devUrl':'http://localhost:5173','beforeBuildCommand':'npm run build','frontendDist':'../dist'},
            'app':{'windows':[{'title':name,'width':1100,'height':760}],'security':{'csp':None}},
        }, indent=2) + '\n'
    return json.dumps({
        'build':{'beforeDevCommand':'npm run dev','beforeBuildCommand':'npm run build','devPath':'http://localhost:5173','distDir':'../dist'},
        'package':{'productName':name,'version':version},
        'tauri':{'allowlist':{'all':False},'windows':[{'title':name,'width':1100,'height':760}],'security':{'csp':None}},
    }, indent=2) + '\n'


# Add deterministic handling for build.rs/config and Cargo post-hardening without
# weakening the central commit gate.
_v4132_prev_generate_with_tauri = _generate_planned_file

def _generate_planned_file(user_request, manifest, work, file_item, progress_callback=None):
    rel = _v413_norm_rel((file_item or {}).get('path'))
    p = Path(work) / rel
    if V413_DETERMINISTIC_BOOT_SHELLS and _v413_is_tauri_manifest(manifest):
        if rel == 'src-tauri/build.rs':
            p.parent.mkdir(parents=True, exist_ok=True)
            _v413_harden_tauri_cargo(work)
            p.write_text(_v413_tauri_build_rs(), encoding='utf-8')
            err = _v401_file_green_error(work, manifest or {}, rel)
            if not err:
                _v413_mark_accepted(work, rel, 'deterministic_tauri_build_script')
                return True, rel
        if rel == 'src-tauri/tauri.conf.json':
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(_v413_tauri_conf(work), encoding='utf-8')
            err = _v401_file_green_error(work, manifest or {}, rel)
            if not err:
                _v413_mark_accepted(work, rel, 'deterministic_tauri_config')
                return True, rel
    ok, wrote = _v4132_prev_generate_with_tauri(user_request, manifest, work, file_item, progress_callback)
    if rel == 'src-tauri/Cargo.toml' and p.exists():
        if _v413_harden_tauri_cargo(work):
            err = _v401_file_green_error(work, manifest or {}, rel)
            if not err:
                _v413_mark_accepted(work, rel, 'cargo_coherence_hardening')
                ok = True
    return ok, wrote


_v4132_prev_real_validation_repair = _repair_real_validation_failure

def _repair_real_validation_failure(user_request, manifest, work, failure, progress_callback=None):
    low = str(failure or '').lower()
    if _v413_is_tauri_manifest(manifest) and any(x in low for x in ('cargo','tauri','sqlx','failed to select a version','feature `','feature "','runtime-tauri')):
        if _v413_harden_tauri_cargo(work):
            return True
    return _v4132_prev_real_validation_repair(user_request, manifest, work, failure, progress_callback)

# =============================================================================
# V42.0 CAPABILITY-FIRST SANDBOX / COMMAND-BROKER FACTORY
# =============================================================================
# V42 moves host/tool discovery and process execution out of the model's guesswork.
# It preserves V41.3 accepted-revision convergence while adding:
# - startup/background capability inventory
# - manifest-to-host readiness resolution
# - controlled command broker + per-project caches/build state
# - optional trusted lightweight tool bootstrap (explicit env opt-in)
# - stronger plan-coverage re-review before implementation
# - canonical owner tie-breaking for split entity/enum providers

V420_VERSION = '42.0.0'
V420_ENGINE = 'CAPABILITY_SANDBOX_CONVERGENCE_FACTORY'
V420_PLAN_COVERAGE_REREVIEW = os.getenv('JARVIS_V42_PLAN_COVERAGE_REREVIEW','1').strip().lower() not in {'0','false','no','off'}
V420_COMMAND_BROKER = os.getenv('JARVIS_V42_COMMAND_BROKER','1').strip().lower() not in {'0','false','no','off'}
V420_CAPABILITY_PREFLIGHT = os.getenv('JARVIS_V42_CAPABILITY_PREFLIGHT','1').strip().lower() not in {'0','false','no','off'}
V420_PLAN_COVERAGE_CORRECTION_ROUNDS = max(1,min(3,int(os.getenv('JARVIS_V42_PLAN_COVERAGE_CORRECTION_ROUNDS','2'))))

try:
    import jarvis_v42_runtime as _v42rt
except Exception:
    _v42rt = None


def _v42_capability_context():
    if not _v42rt:
        return 'V42 capability runtime unavailable; preserve requested stack and use existing host-aware validation.'
    try:
        return _v42rt.planner_capability_context(4200)
    except Exception as exc:
        return f'V42 capability scan unavailable: {exc}'


def _v42_feature_signal_names(user_request):
    if not _v42rt:
        return []
    try:
        return _v42rt.plan_coverage_gaps(user_request, {'files':[]})
    except Exception:
        return []


# Start capability discovery before model architecture work. This is non-blocking
# and writes a deterministic report into the diagnostic workspace when available.
_v42_prev_direct_bootstrap = _direct_new_project_bootstrap

def _direct_new_project_bootstrap(user_request, max_files, progress_callback=None, work=None):
    if _v42rt and V420_CAPABILITY_PREFLIGHT:
        try:
            _v42rt.start_background_startup_scan(JARVIS_DIR)
            if work:
                caps = _v42rt.get_cached_capabilities(refresh=False, probe_versions=False)
                if not caps or not caps.get('tools'):
                    caps = _v42rt.get_cached_capabilities(refresh=True, probe_versions=False)
                _v373_atomic_json_write(Path(work)/_v42rt.CAPABILITY_FILE, caps)
                _append_project_event(work,'v42_capability_preflight_started','V42 discovered host developer capabilities before architecture planning.',available_count=caps.get('available_count'),known_count=caps.get('known_count'))
            _progress(progress_callback,'V42 capability preflight ready; architecture will use real host/tool evidence instead of guessing.',stage='architecting',percent=7)
        except Exception as exc:
            if work:
                try:_append_project_event(work,'v42_capability_preflight_warning',f'Capability preflight fell back safely: {exc}')
                except Exception:pass
    return _v42_prev_direct_bootstrap(user_request,max_files,progress_callback,work=work)


# Inject host evidence + explicit requested behavior clusters into the first plan.
_v42_prev_plan_prompt = _project_plan_prompt

def _project_plan_prompt(user_request, max_files):
    base = _v42_prev_plan_prompt(user_request,max_files)
    signals = _v42_feature_signal_names(user_request)
    coverage = ''
    if signals:
        coverage = (
            '\nV42 REQUESTED-BEHAVIOR COVERAGE LEDGER:\n- Explicit behavior clusters detected: '+', '.join(signals)+'.\n'
            '- Every listed cluster must have at least one concrete implementation owner/consumer file in the plan. '
            'Domain types/schemas alone do not implement user-visible behavior. If tests are requested, plan actual test files.\n'
        )
    return base + '\n\n' + _v42_capability_context() + coverage


# One bounded extra architecture correction only when the normal two review passes
# still omit an explicitly requested behavior cluster. This is cheaper than letting
# a 30-minute generation discover at final acceptance that CSV/tests/etc never existed.
_v42_prev_review_plan = _review_project_plan

def _review_project_plan(user_request, manifest, max_files, progress_callback=None):
    result = _v42_prev_review_plan(user_request,manifest,max_files,progress_callback)
    if not (_v42rt and V420_PLAN_COVERAGE_REREVIEW):
        return result
    previous_gap_signature=None
    for correction_no in range(1,V420_PLAN_COVERAGE_CORRECTION_ROUNDS+1):
        try:
            gaps=_v42rt.plan_coverage_gaps(user_request,result)
            instruction=_v42rt.plan_coverage_instruction(user_request,result)
        except Exception:
            gaps=[];instruction=''
        if not instruction:
            break
        signature=tuple(sorted(gaps))
        _progress(progress_callback,'V42 caught missing requested behaviors in the architecture before code generation: '+', '.join(gaps)+f'. Correcting the plan {correction_no}/{V420_PLAN_COVERAGE_CORRECTION_ROUNDS}.',stage='architecting',percent=min(19,15+correction_no))
        prompt=(
            'V42 FINAL PLAN-COVERAGE CORRECTION. Return ONLY a corrected COMPLETE project manifest JSON using the same requested stack.\n'
            +instruction+'\nThis correction MUST add concrete implementation/test owners for every listed gap; do not merely add the words to a domain contract.\n\nUSER REQUEST:\n'
            +str(user_request)+'\n\n'+_v42_capability_context()+'\n\nCURRENT MANIFEST:\n'+json.dumps(result,ensure_ascii=False,indent=2)
        )
        ok,text=_qwen_call(prompt,progress_callback,f'V42 plan coverage correction {correction_no}/{V420_PLAN_COVERAGE_CORRECTION_ROUNDS}',profile='plan',max_tokens=6144,thinking=False,
                           response_schema=QWEN_SCHEMA_PROJECT_PLAN,schema_name='v42_plan_coverage',strict_output=True)
        if not ok:
            continue
        before_files={str(x.get('path') or '') for x in result.get('files') or [] if isinstance(x,dict)}
        try:
            reviewed=_parse_project_plan(text,user_request,max_files)
            if reviewed:
                result=_merge_manifest(result,reviewed,user_request,max_files)
        except Exception:
            continue
        after_files={str(x.get('path') or '') for x in result.get('files') or [] if isinstance(x,dict)}
        # If a correction neither changes the file set nor reduces gaps, one more
        # iteration is allowed only when configured; the bounded loop still terminates.
        try:new_signature=tuple(sorted(_v42rt.plan_coverage_gaps(user_request,result)))
        except Exception:new_signature=signature
        if new_signature==signature and after_files==before_files and previous_gap_signature==signature:
            break
        previous_gap_signature=signature
    try:result['_v42_plan_coverage_gaps']=_v42rt.plan_coverage_gaps(user_request,result)
    except Exception:pass
    return result


# Strengthen canonical-owner selection when a component intentionally separates
# entities.rs from enums.rs (or analogous model/type files). The older scoring
# could be fooled by a non-owner compatibility alias in a contract line.
_v42_prev_domain_owner_map = _v40_domain_owner_map

def _v40_domain_owner_map(manifest):
    owners = dict(_v42_prev_domain_owner_map(manifest) or {})
    defs = _v40_domain_definitions(manifest)
    files = [x for x in (manifest or {}).get('files') or [] if isinstance(x,dict) and x.get('path')]
    by_scope={}
    for item in files:
        by_scope.setdefault(_v38_component_scope(manifest,item.get('path')),[]).append(item)
    for scope,rows in by_scope.items():
        for symbol,d in defs.items():
            kind=str(d.get('kind') or '')
            ranked=[]
            for item in rows:
                rel=_v40_norm_rel(item.get('path')); low=rel.lower(); purpose=str(item.get('purpose') or '').lower(); contracts=' '.join(str(x) for x in item.get('contracts') or []).lower()
                score=_v40_definition_mention_score(item,symbol)
                if kind=='enum':
                    if any(tag in low for tag in ('enum','enums')): score += 180
                    if 'enum' in purpose and symbol.lower() in purpose: score += 140
                    if re.search(rf'\benum\s+{re.escape(symbol.lower())}\b',contracts): score += 160
                    if re.search(rf'\btype\s+{re.escape(symbol.lower())}\b',contracts): score -= 90
                elif kind=='entity':
                    if any(tag in low for tag in ('entities','entity','models','model')): score += 80
                    if 'enum' in low: score -= 80
                ranked.append((score,rel))
            if ranked:
                ranked.sort(key=lambda x:(-x[0],x[1].casefold()))
                if ranked[0][0] >= 45: owners[(scope,symbol)] = ranked[0][1]
    return owners


def _v42_reconcile_nonowner_contracts(manifest):
    m=dict(manifest or {})
    owners=_v40_domain_owner_map(m)
    defs=_v40_domain_definitions(m)
    rows=[]
    for raw in m.get('files') or []:
        if not isinstance(raw,dict):continue
        item=dict(raw); rel=_v40_norm_rel(item.get('path')); scope=_v38_component_scope(m,rel); kept=[]
        for line in item.get('contracts') or []:
            text=str(line); low=text.lower(); drop=False
            for symbol,d in defs.items():
                owner=owners.get((scope,symbol))
                if not owner or owner==rel: continue
                sym=re.escape(symbol.lower())
                # Only remove explicit provider-definition contracts; consumer prose remains.
                if re.search(rf'\b(?:struct|class|record|interface|enum|type)\s+{sym}\b',low) or re.search(rf'\bpub\s+type\s+{sym}\b',low):
                    drop=True; break
            if not drop: kept.append(line)
        item['contracts']=kept; rows.append(item)
    m['files']=rows
    m['_v40_domain_owners']=_v40_domain_owner_payload(m).get('owners') or []
    return m


# Resolve the final planned toolchains against the real host before implementation.
# Missing SDKs do not silently change the requested language/framework.
_v42_prev_execute_manifest = _v362_execute_manifest

def _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback=None, raw_plan=''):
    manifest=_v42_reconcile_nonowner_contracts(dict(manifest or {}))
    manifest['version']='V'+V420_VERSION; manifest['engine']=V420_ENGINE; manifest['planner_mode']='capability-first-universal-v42'
    if _v42rt and V420_CAPABILITY_PREFLIGHT:
        try:
            readiness=_v42rt.preflight_for_manifest(JARVIS_DIR,Path(work),manifest,try_bootstrap=True)
            manifest['_v42_toolchain_readiness']=readiness
            missing=readiness.get('missing') or []
            msg='V42 toolchain readiness: '+('READY' if not missing else 'host missing '+', '.join(missing))
            _append_project_event(work,'v42_toolchain_readiness',msg,status=readiness.get('status'),missing=missing,bootstrap=readiness.get('bootstrap'))
            _progress(progress_callback,msg+'. Requested stack remains authoritative.',stage='architecting',percent=18)
        except Exception as exc:
            try:_append_project_event(work,'v42_toolchain_readiness_warning',f'Capability resolution fell back safely: {exc}')
            except Exception:pass
    return _v42_prev_execute_manifest(user_request,manifest,work,max_files,progress_callback,raw_plan)


# Route all deterministic build/test/install commands through the V42 broker.
# The broker uses subprocess(shell=False), blocks host-management commands, enforces
# timeouts and records command evidence + project-local dependency/build caches.
_v42_prev_run_command = _run_command

def _run_command(cmd, cwd, timeout, env=None):
    if not (_v42rt and V420_COMMAND_BROKER):
        return _v42_prev_run_command(cmd,cwd,timeout,env=env)
    try:
        broker=_v42rt.CommandBroker(Path(cwd))
        result=broker.run(cmd,cwd=Path(cwd),timeout=timeout,env=env)
        rendered=' '.join(map(str,result.command))
        if result.blocked:
            return False,f'V42 command broker blocked command: {rendered}\nReason: {result.reason}'
        if result.timed_out:
            return False,f'Command timed out after {timeout}s: {rendered}\n{result.combined[-6000:]}'
        if not result.ok:
            suffix=('\nReason: '+result.reason) if result.reason else ''
            return False,f'Command failed ({result.returncode}): {rendered}\n{result.combined[-8000:]}{suffix}'
        return True,result.combined[-3000:]
    except Exception:
        # Broker failure itself must not destroy a working build path.
        return _v42_prev_run_command(cmd,cwd,timeout,env=env)


# Add V42 evidence to every model call without making the model decide whether a
# compiler exists. The active micro-skill/contract context still owns source design.
_v42_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    body=str(prompt or '') + (
        '\n\nV42 EXECUTION RULE: Jarvis owns capability discovery, dependency/build command execution, timeouts, and command evidence. '
        'Do not invent that a compiler/SDK exists and do not change the requested stack because a tool is missing. '
        'Use exact compiler/test diagnostics supplied by Jarvis. Requested behaviors must have concrete implementation owners; domain/schema definitions alone do not satisfy behavior requirements.'
    )
    return _v42_prev_qwen_call(body,progress_callback,str(stage or '').replace('V41.3.2','V42').replace('V41.2','V42').replace('V41.1','V42'),profile=profile,**kwargs)


# Release/status identity.
_v42_prev_release_identity = _v36_release_identity

