_v42_prev_progress = _progress

def _progress(callback, text=None, **fields):
    if text is not None:
        text=str(text).replace('V41.3.2','V42').replace('V41.2','V42').replace('V41.1','V42')
    return _v42_prev_progress(callback,text,**fields)


# Runtime/capability evidence belongs to Jarvis diagnostics, not the generated user ZIP.
_v42_prev_package_workspace_zip = _package_workspace_zip

def _package_workspace_zip(work, name_stem, stamp=None):
    root=Path(work); moved=[]; temp_root=Path(tempfile.mkdtemp(prefix='jarvis_v42_hide_'))
    try:
        candidates=[]
        for p in root.rglob('.jarvis_runtime'):
            if p.is_dir(): candidates.append(p)
        if _v42rt:
            for name in (_v42rt.CAPABILITY_FILE,_v42rt.READINESS_FILE,_v42rt.ENVIRONMENT_FILE):
                p=root/name
                if p.exists(): candidates.append(p)
        # Deepest paths first avoids moving a parent before child enumeration.
        for i,p in enumerate(sorted(set(candidates),key=lambda x:len(x.parts),reverse=True)):
            try:
                rel=p.relative_to(root); dest=temp_root/f'{i}_{p.name}'
                shutil.move(str(p),str(dest)); moved.append((p,dest))
            except Exception:pass
        return _v42_prev_package_workspace_zip(work,name_stem,stamp)
    finally:
        for original,dest in reversed(moved):
            try:
                original.parent.mkdir(parents=True,exist_ok=True)
                if dest.exists():shutil.move(str(dest),str(original))
            except Exception:pass
        shutil.rmtree(temp_root,ignore_errors=True)

# =============================================================================
# V42.1 TAURI/CARGO + MIXED-ROOT PLAN CONVERGENCE HARDENING
# =============================================================================
# Regression fixed from GearTrack 2026-08-30 project_20260830_171300:
# - Tauri 2 Cargo.toml retained the removed v1-era `shell-open` core feature,
#   so `cargo fetch` failed before Rust compilation.
# - the architecture placed TypeScript model files under `src-tauri/src/`, which
#   is the Rust crate source root.  Later owner self-healing then invented .rs
#   providers and canonical ownership drifted across Tool/Category/ToolCondition.
# - Cargo diagnostics already named the exact invalid dependency feature, but
#   the repair loop asked the model to patch instead of applying the deterministic
#   manifest edit and retrying immediately.
#
# V42.1 makes build-system diagnostics authoritative for dependency-resolution
# errors and normalizes mixed Tauri plans before milestone/owner freezing.

V421_VERSION = '42.1.0'
V421_ENGINE = 'CAPABILITY_SANDBOX_CARGO_CONVERGENCE_FACTORY'
V421_TAURI_PLAN_SANITIZER = os.getenv('JARVIS_V421_TAURI_PLAN_SANITIZER','1').strip().lower() not in {'0','false','no','off'}
V421_CARGO_DIAGNOSTIC_REPAIR = os.getenv('JARVIS_V421_CARGO_DIAGNOSTIC_REPAIR','1').strip().lower() not in {'0','false','no','off'}
V421_RUST_ROOT_LANGUAGE_GATE = os.getenv('JARVIS_V421_RUST_ROOT_LANGUAGE_GATE','1').strip().lower() not in {'0','false','no','off'}


def _v421_snake_case(name):
    value = str(name or '').strip()
    value = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', value)
    value = re.sub(r'[^A-Za-z0-9]+', '_', value).strip('_').lower()
    return value or 'module'


def _v421_replace_path_refs(value, rewrites):
    if isinstance(value, str):
        norm = _v40_norm_rel(value)
        return rewrites.get(norm, value)
    if isinstance(value, list):
        return [_v421_replace_path_refs(x, rewrites) for x in value]
    return value


def _v421_merge_file_items(a, b):
    out = dict(a or {})
    other = dict(b or {})
    for key in ('exports','contracts','depends_on','build_metadata_symbols'):
        vals=[]
        for src in (out.get(key) or [], other.get(key) or []):
            if isinstance(src, (list,tuple,set)):
                seq=src
            else:
                seq=[src]
            for x in seq:
                if x not in vals: vals.append(x)
        if vals: out[key]=vals
    if not out.get('purpose') and other.get('purpose'): out['purpose']=other.get('purpose')
    if not out.get('phase') and other.get('phase'): out['phase']=other.get('phase')
    return out


def _v421_sanitize_tauri_manifest(manifest):
    """Normalize a Tauri mixed repo before ownership/milestones are frozen.

    The Rust crate root may contain Rust source and crate assets, but never TS/JS
    implementation files.  Planner mistakes are corrected structurally rather
    than allowed to become competing self-healed providers later.
    """
    if not isinstance(manifest, dict) or not _v413_is_tauri_manifest(manifest) or not V421_TAURI_PLAN_SANITIZER:
        return manifest
    m = dict(manifest)
    defs = _v40_domain_definitions(m)
    raw_rows = [dict(x) for x in (m.get('files') or []) if isinstance(x,dict) and x.get('path')]
    rewrites = {}

    # First pass: canonicalize source paths.  Any JS/TS file under src-tauri/src
    # is a planner root-language mistake; convert it to a Rust module path.
    for item in raw_rows:
        rel = _v40_norm_rel(item.get('path'))
        low = rel.lower()
        p = Path(rel)
        new = rel
        if low.startswith('src-tauri/src/') and p.suffix.lower() in {'.ts','.tsx','.js','.jsx','.mjs','.cjs'}:
            stem = _v421_snake_case(p.stem)
            new = (p.parent / (stem + '.rs')).as_posix()
        elif low.startswith('src-tauri/src/db/migrations/') and p.suffix.lower()=='.sql':
            # SQLx's conventional migration root is crate_root/migrations.
            new = ('src-tauri/migrations/' + p.name)
        elif low.startswith('src-tauri/src/') and p.suffix.lower()=='.rs' and p.name.lower() not in {'main.rs','lib.rs','mod.rs'}:
            # Keep Rust module file names portable and conventional across Windows/Linux.
            stem = _v421_snake_case(p.stem)
            new = (p.parent / (stem + '.rs')).as_posix()
        if new != rel:
            rewrites[rel] = new

    rows_by_path = {}
    order=[]
    for item in raw_rows:
        old = _v40_norm_rel(item.get('path'))
        rel = rewrites.get(old, old)
        item['path'] = rel
        item['depends_on'] = [_v421_replace_path_refs(x, rewrites) for x in (item.get('depends_on') or [])]
        low=rel.lower(); p=Path(rel)
        if low.startswith('src-tauri/migrations/') and p.suffix.lower()=='.sql':
            item['phase']='data'
        if low.startswith('src-tauri/.sqlx/'):
            item['phase']='data'
        if low.startswith('src-tauri/src/') and p.suffix.lower()=='.rs':
            purpose=str(item.get('purpose') or '')
            purpose=re.sub(r'(?i)typescript\s+interface', 'Rust domain model', purpose)
            purpose=re.sub(r'(?i)typescript', 'Rust', purpose)
            item['purpose']=purpose
            # Backend domain implementations are feature/data code, never Foundation
            # merely because a confused planner called a TS interface foundational.
            if '/models/' in low and p.name.lower() not in {'mod.rs'}:
                item['phase']='data'
            if rel=='src-tauri/src/db/mod.rs':
                item['phase']='data'
            # Exact model filename is strong canonical-provider evidence.
            normstem=re.sub(r'[^a-z0-9]+','',p.stem.lower())
            contracts=[str(x) for x in item.get('contracts') or []]
            exports=list(_normalize_export_contract(item.get('exports')))
            for symbol,spec in defs.items():
                symlow=re.sub(r'[^a-z0-9]+','',symbol.lower())
                mentions = any(_v381_clean_symbol_name(x)==symbol for x in contracts)
                if normstem==symlow or mentions:
                    # Drop TS-interface aliases such as ITool and expose the real Rust owner.
                    exports=[x for x in exports if not (str(x).lower()==('i'+symbol).lower())]
                    if symbol not in exports: exports.append(symbol)
                    if symbol not in contracts: contracts.append(symbol)
                    if normstem==symlow:
                        kind='enum' if spec.get('kind')=='enum' else 'entity'
                        item['purpose']=f'Canonical Rust {kind} {symbol} for the Tauri backend.'
            item['exports']=exports; item['contracts']=contracts
        if rel in rows_by_path:
            rows_by_path[rel] = _v421_merge_file_items(rows_by_path[rel], item)
        else:
            rows_by_path[rel]=item; order.append(rel)

    # Ensure every frozen domain contract has an explicit Rust owner in the Tauri
    # component.  This prevents the old self-healer from guessing Category.rs as
    # ToolCondition's owner merely because prose happened to mention the enum.
    existing=set(rows_by_path)
    for symbol,spec in defs.items():
        # Keep an already-explicit Rust provider (for example domain/enums.rs).
        # Add a canonical model file only when the plan has no trustworthy Rust
        # definition owner at all.
        explicit_provider=False
        sym_re=re.escape(symbol)
        for candidate in rows_by_path.values():
            crel=_v40_norm_rel(candidate.get('path'))
            if not (crel.lower().startswith('src-tauri/src/') and Path(crel).suffix.lower()=='.rs'):
                continue
            cblob=' '.join([str(candidate.get('purpose') or '')] + [str(x) for x in candidate.get('contracts') or []])
            cexports=[_v381_clean_symbol_name(x) for x in _normalize_export_contract(candidate.get('exports'))]
            if symbol in cexports or re.search(rf'(?i)\b(?:struct|enum|class|record|type)\s+{sym_re}\b',cblob) or re.search(rf'(?i)\bcanonical\b[^.\n]{{0,80}}\b{sym_re}\b',cblob):
                explicit_provider=True; break
        target=f"src-tauri/src/models/{_v421_snake_case(symbol)}.rs"
        if target not in existing and not explicit_provider:
            phase='data'
            contracts=[symbol]
            if spec.get('kind')=='enum':
                values=', '.join(_v421_snake_case(v).replace('_',' ').title().replace(' ','') for v in spec.get('values') or [])
                contracts.append(f'Canonical enum {symbol} values: {values}')
            rows_by_path[target]={
                'path':target,
                'purpose':f"Canonical Rust {'enum' if spec.get('kind')=='enum' else 'entity'} {symbol} for the Tauri backend.",
                'phase':phase,
                'depends_on':['src-tauri/Cargo.toml'] if 'src-tauri/Cargo.toml' in existing else [],
                'exports':[symbol],
                'contracts':contracts,
            }
            order.append(target); existing.add(target)

    # Plan one late module hub after the individual model providers.  It is safer
    # than letting an early mod.rs declare future modules that do not exist yet.
    model_paths=[p for p in existing if p.startswith('src-tauri/src/models/') and p.endswith('.rs') and not p.endswith('/mod.rs')]
    if model_paths and 'src-tauri/src/models/mod.rs' not in existing:
        rows_by_path['src-tauri/src/models/mod.rs']={
            'path':'src-tauri/src/models/mod.rs','purpose':'Rust domain-model module hub generated after canonical model providers.',
            'phase':'integration','depends_on':sorted(model_paths),'exports':[],'contracts':['Declare only materialized canonical Rust model modules; do not redefine their types.']
        }
        order.append('src-tauri/src/models/mod.rs'); existing.add('src-tauri/src/models/mod.rs')

    # Module aggregators must not be scheduled before the modules they aggregate.
    if 'src-tauri/src/commands/mod.rs' in rows_by_path:
        item=rows_by_path['src-tauri/src/commands/mod.rs']; item['phase']='integration'
        item['purpose']='Late Rust command-module hub for already materialized command providers.'
        item['exports']=[]
        rule='Module hub only: declare already-materialized command modules and import canonical domain definitions; never define domain entities here.'
        item['contracts']=[rule]
    if 'src-tauri/src/db/mod.rs' in rows_by_path:
        item=rows_by_path['src-tauri/src/db/mod.rs']; item['phase']='integration'
        item['purpose']='SQLite pool, migration, and repository integration substrate.'
        item['exports']=[]
        rule='SQLite pool/migration/repository integration module. Import canonical domain definitions from the model module; never declare a nested models module or redefine domain types.'
        # Domain names in a cross-cutting db hub caused V39 to assign it to the
        # first entity feature. Keep only the integration contract here.
        item['contracts']=[rule]

    m['files']=[rows_by_path[p] for p in order]
    if isinstance(m.get('implementation_order'), list):
        seen=[]
        for raw in m.get('implementation_order') or []:
            p=rewrites.get(_v40_norm_rel(raw),_v40_norm_rel(raw))
            if p and p not in seen: seen.append(p)
        for p in order:
            if p not in seen: seen.append(p)
        m['implementation_order']=seen
    m['_v421_path_rewrites']=rewrites
    m['_v421_tauri_plan_sanitized']=True
    return m


# Exact semantic filenames outrank prose mentions for canonical owners.  This is
# especially important for generated Rust model files after Tauri-plan sanitation.
_v421_prev_domain_owner_map = _v40_domain_owner_map

def _v40_domain_owner_map(manifest):
    m=_v421_sanitize_tauri_manifest(dict(manifest or {})) if isinstance(manifest,dict) else manifest
    owners=dict(_v421_prev_domain_owner_map(m) or {})
    defs=_v40_domain_definitions(m or {})
    files=[x for x in (m or {}).get('files') or [] if isinstance(x,dict) and x.get('path')]
    by_scope={}
    for item in files:
        by_scope.setdefault(_v38_component_scope(m,item.get('path')),[]).append(item)
    for scope,rows in by_scope.items():
        for symbol in defs:
            sym=re.sub(r'[^a-z0-9]+','',symbol.lower())
            exact=[]
            for item in rows:
                rel=_v40_norm_rel(item.get('path')); p=Path(rel)
                stem=re.sub(r'[^a-z0-9]+','',p.stem.lower())
                if stem!=sym: continue
                # In Rust component scope, a .rs exact-name provider is stronger
                # than a wrong-language file with the same conceptual name.
                ext_bonus=200 if p.suffix.lower()=='.rs' and rel.lower().startswith('src-tauri/src/') else 0
                exact.append((ext_bonus + _v40_definition_mention_score(item,symbol),rel))
            if exact:
                exact.sort(key=lambda x:(-x[0],x[1].casefold()))
                owners[(scope,symbol)]=exact[0][1]
    return owners


def _v421_remove_feature_from_dependency(text, dependency, feature):
    dep=re.escape(str(dependency or '').strip())
    feat=str(feature or '').strip()
    if not dep or not feat: return text, False
    changed=False

    # Inline dependency table: tauri = { version = "2", features = [..] }
    line_pat=re.compile(rf'(?m)^(\s*{dep}\s*=\s*\{{[^\n]*\}}\s*)$')
    def repl_line(m):
        nonlocal changed
        line=m.group(1)
        fm=re.search(r'features\s*=\s*\[([^\]]*)\]',line)
        if not fm:return line
        vals=re.findall(r'["\']([^"\']+)["\']',fm.group(1))
        kept=[x for x in vals if x!=feat]
        if len(kept)==len(vals):return line
        changed=True
        replacement='features = [' + ', '.join(json.dumps(x) for x in kept) + ']'
        return line[:fm.start()] + replacement + line[fm.end():]
    text=line_pat.sub(repl_line,text)

    # Table dependency style: [dependencies.tauri]\nfeatures = [..]
    table_pat=re.compile(rf'(?ms)(^\s*\[(?:dependencies|build-dependencies)\.{dep}\]\s*$)(.*?)(?=^\s*\[|\Z)')
    def repl_table(m):
        nonlocal changed
        head,body=m.group(1),m.group(2)
        fm=re.search(r'(?m)^\s*features\s*=\s*\[([^\]]*)\]\s*$',body)
        if not fm:return m.group(0)
        vals=re.findall(r'["\']([^"\']+)["\']',fm.group(1)); kept=[x for x in vals if x!=feat]
        if len(kept)==len(vals):return m.group(0)
        changed=True
        replacement='features = [' + ', '.join(json.dumps(x) for x in kept) + ']'
        body=body[:fm.start()] + replacement + body[fm.end():]
        return head+body
    text=table_pat.sub(repl_table,text)
    return text,changed


def _v421_remove_dependency_line(text, dependency):
    dep=re.escape(str(dependency or '').strip())
    if not dep:return text,False
    new,n=re.subn(rf'(?m)^\s*{dep}\s*=.*\n?', '', text)
    # Also handle [dependencies.name] table conservatively.
    new2,n2=re.subn(rf'(?ms)^\s*\[(?:dependencies|build-dependencies)\.{dep}\]\s*$.*?(?=^\s*\[|\Z)', '', new)
    return new2,bool(n or n2)


def _v421_static_tauri_cargo_text(text):
    original=str(text or ''); out=original
    major=_v413_tauri_major_from_text(out)
    if major==2:
        # These are Tauri-1-era core features removed in v2. APIs migrated to
        # plugins/capabilities. Keeping them makes dependency resolution impossible.
        for feat in ('shell-open','shell-open-api','process-command-api','api-all','all'):
            out,_=_v421_remove_feature_from_dependency(out,'tauri',feat)
        # sqlx-build is not a SQLx companion crate and has caused a real crates.io
        # resolution failure in the regression workspace.
        out,_=_v421_remove_dependency_line(out,'sqlx-build')
        # Keep Tauri core/build major versions coherent when simple inline forms exist.
        out=re.sub(r'(?m)^(\s*tauri-build\s*=\s*\{[^\n]*version\s*=\s*)["\']1(?:\.[^"\']*)?["\']',r'\g<1>"2"',out)
    return out, out!=original


_v421_prev_harden_tauri_cargo = _v413_harden_tauri_cargo

def _v413_harden_tauri_cargo(work):
    changed=bool(_v421_prev_harden_tauri_cargo(work))
    p=Path(work)/'src-tauri'/'Cargo.toml'
    if not p.exists():return changed
    try:text=p.read_text(encoding='utf-8',errors='replace')
    except Exception:return changed
    fixed,more=_v421_static_tauri_cargo_text(text)
    if more:
        p.write_text(fixed,encoding='utf-8'); changed=True
        try:_append_project_event(work,'v421_tauri2_cargo_hardened','V42.1 removed obsolete/impossible Cargo dependency features before resolution.',file='src-tauri/Cargo.toml',tauri_major=_v413_tauri_major_from_text(fixed))
        except Exception:pass
    return changed


def _v421_repair_cargo_resolution_failure(work, failure):
    if not V421_CARGO_DIAGNOSTIC_REPAIR:return False
    p=Path(work)/'src-tauri'/'Cargo.toml'
    if not p.exists():
        # Generic Rust projects may use root Cargo.toml.
        p=Path(work)/'Cargo.toml'
    if not p.exists():return False
    try:text=p.read_text(encoding='utf-8',errors='replace')
    except Exception:return False
    original=text; edits=[]; failure=str(failure or '')

    # Cargo gives an exact machine-actionable diagnosis for invalid features.
    for dep,feat in re.findall(r'package\s+`[^`]+`\s+depends on\s+`([^`]+)`\s+with feature\s+`([^`]+)`\s+but\s+`\1`\s+does not have that feature',failure,re.I):
        text,changed=_v421_remove_feature_from_dependency(text,dep,feat)
        if changed:edits.append(f'removed invalid feature {dep}/{feat}')

    # Known impossible SQLx pseudo-build crate from the live regression.  Do not
    # generically delete arbitrary unavailable packages because private registries exist.
    missing=re.findall(r'no matching package named\s+`([^`]+)`\s+found',failure,re.I)
    for dep in missing:
        if dep.lower()=='sqlx-build':
            text,changed=_v421_remove_dependency_line(text,dep)
            if changed:edits.append('removed nonexistent sqlx-build dependency')

    # Apply static coherence too, because one cargo failure can hide the next one.
    text,static_changed=_v421_static_tauri_cargo_text(text)
    if static_changed:edits.append('applied Tauri-2 static dependency coherence')
    if text==original:return False
    p.write_text(text,encoding='utf-8')
    try:_append_project_event(work,'v421_cargo_diagnostic_repair','V42.1 deterministically repaired Cargo dependency resolution from exact Cargo diagnostics.',file=_v40_norm_rel(p.relative_to(Path(work))),edits=edits)
    except Exception:pass
    return True


_v421_prev_real_validation_repair = _repair_real_validation_failure

def _repair_real_validation_failure(user_request, manifest, work, failure, progress_callback=None):
    low=str(failure or '').lower()
    if any(x in low for x in ('does not have that feature','no matching package named','failed to select a version for `tauri`')):
        if _v421_repair_cargo_resolution_failure(work,failure):
            _progress(progress_callback,'V42.1 repaired Cargo dependency resolution deterministically from compiler evidence; retrying the real build/test gate.',stage='repairing')
            return True
    return _v421_prev_real_validation_repair(user_request,manifest,work,failure,progress_callback)


