def _candidate_transaction_error(work, manifest, rel, content, user_request=None, validation_failure=None, target_problems=None):
    rel=_v40_norm_rel(rel); low=rel.lower(); ext=Path(rel).suffix.lower()
    if V421_RUST_ROOT_LANGUAGE_GATE and _v413_is_tauri_manifest(manifest) and low.startswith('src-tauri/src/') and ext in {'.ts','.tsx','.js','.jsx','.mjs','.cjs'}:
        return f'V42.1 Tauri root-language gate: {rel} is JavaScript/TypeScript inside the Rust crate source root. Move frontend source under repository src/ or implement this backend module as .rs.'
    return _v421_prev_candidate_transaction_error(work,manifest,rel,content,user_request=user_request,validation_failure=validation_failure,target_problems=target_problems)


# Deterministic late model module hub.  The hub is integration-stage, so all
# declared providers should already exist when this file is generated.
_v421_prev_generate_planned_file = _generate_planned_file

def _generate_planned_file(user_request, manifest, work, file_item, progress_callback=None):
    rel=_v40_norm_rel((file_item or {}).get('path'))
    if rel=='src-tauri/src/models/mod.rs' and _v413_is_tauri_manifest(manifest):
        p=Path(work)/rel; p.parent.mkdir(parents=True,exist_ok=True)
        rows=[]
        for item in (manifest or {}).get('files') or []:
            if not isinstance(item,dict):continue
            child=_v40_norm_rel(item.get('path'))
            if not child.startswith('src-tauri/src/models/') or not child.endswith('.rs') or child==rel:continue
            if not (Path(work)/child).exists():continue
            mod=Path(child).stem
            rows.append(f'pub mod {mod};')
            for symbol in _normalize_export_contract(item.get('exports')):
                s=_v381_clean_symbol_name(symbol)
                if s: rows.append(f'pub use {mod}::{s};')
        p.write_text('\n'.join(dict.fromkeys(rows))+'\n',encoding='utf-8')
        err=_v401_file_green_error(work,manifest or {},rel)
        if not err:
            try:_v413_mark_accepted(work,rel,'v421_deterministic_model_module_hub')
            except Exception:pass
            return True,rel
    ok,wrote=_v421_prev_generate_planned_file(user_request,manifest,work,file_item,progress_callback)
    if rel=='src-tauri/Cargo.toml' and (Path(work)/rel).exists():
        # Re-run after every generated manifest revision, before the first cargo fetch.
        _v413_harden_tauri_cargo(work)
    return ok,wrote


