# Cargo-resolution failures get semantic loop signatures instead of whichever
# wrapped Cargo line happened to be last in stderr.
_v421_prev_validation_failure_signature = _validation_failure_signature

def _validation_failure_signature(text):
    raw=str(text or '')
    m=re.search(r'package\s+`[^`]+`\s+depends on\s+`([^`]+)`\s+with feature\s+`([^`]+)`\s+but\s+`\1`\s+does not have that feature',raw,re.I)
    if m:return f'cargo-invalid-feature:{m.group(1).lower()}:{m.group(2).lower()}'
    m=re.search(r'no matching package named\s+`([^`]+)`\s+found',raw,re.I)
    if m:return f'cargo-missing-package:{m.group(1).lower()}'
    m=re.search(r'failed to select a version for\s+`([^`]+)`',raw,re.I)
    if m:return f'cargo-version-conflict:{m.group(1).lower()}'
    return _v421_prev_validation_failure_signature(text)

# =============================================================================
# V42.2 UNIVERSAL COMPONENT-BOUNDARY + BUILD-SUBSTRATE CONVERGENCE
# =============================================================================
# Regression fixed from GearTrack 2026-08-30 project_20260830_183449:
# - a root React/TypeScript component accepted a package.json whose build script
#   invoked `tsc -p src-tauri/tsconfig.json`, crossing into the nested Rust/Tauri
#   component and referencing a config file that did not exist;
# - the architecture itself omitted the root TypeScript compiler substrate, so
#   the bad script survived until the real build gate;
# - the runtime repair path diagnosed source/Cargo files instead of treating the
#   build command/configuration relationship as first-class build evidence.
#
# V42.2 is intentionally component/toolchain generic.  A build command may only
# consume configuration owned by its component (unless explicitly declared as
# shared), and conventional component substrate is closed before source work.

V422_VERSION = '42.2.0'
V422_ENGINE = 'UNIVERSAL_COMPONENT_BOUNDARY_CONVERGENCE_FACTORY'
V422_COMPONENT_COMMAND_GATE = os.getenv('JARVIS_V422_COMPONENT_COMMAND_GATE','1').strip().lower() not in {'0','false','no','off'}
V422_SUBSTRATE_CLOSURE = os.getenv('JARVIS_V422_SUBSTRATE_CLOSURE','1').strip().lower() not in {'0','false','no','off'}
V422_DETERMINISTIC_CONFIG_REPAIR = os.getenv('JARVIS_V422_DETERMINISTIC_CONFIG_REPAIR','1').strip().lower() not in {'0','false','no','off'}

_V422_NODE_ADAPTERS = {'node','react','vite','nextjs','vue','sveltekit','nuxt','angular','electron','react_native','expo'}
_V422_VITE_ADAPTERS = {'react','vite','vue'}
_V422_TS_EXTS = {'.ts','.tsx','.mts','.cts'}


def _v422_norm_rel(value):
    return str(value or '').replace('\\','/').strip('/')


def _v422_component_root(component):
    return _v422_norm_rel((component or {}).get('root')) or '.'


def _v422_join(root, rel):
    root=_v422_norm_rel(root); rel=_v422_norm_rel(rel)
    return rel if root in {'','.'} else f'{root}/{rel}'


def _v422_component_rows(manifest, component):
    """Return only files owned by component, excluding nested component roots."""
    root=_v422_component_root(component)
    nested=[]
    for other in (manifest or {}).get('components') or []:
        if not isinstance(other,dict) or other is component: continue
        r=_v422_component_root(other)
        if r=='.': continue
        if root=='.' or r.startswith(root.rstrip('/')+'/'):
            nested.append(r)
    out=[]
    for row in (manifest or {}).get('files') or []:
        if not isinstance(row,dict): continue
        p=_v422_norm_rel(row.get('path'))
        if not p: continue
        if root!='.' and not (p==root or p.startswith(root+'/')): continue
        if any(p==n or p.startswith(n+'/') for n in nested): continue
        out.append(row)
    return out


def _v422_component_for_path(manifest, rel):
    rel=_v422_norm_rel(rel)
    comps=[x for x in (manifest or {}).get('components') or [] if isinstance(x,dict)]
    best=None; best_len=-1
    for comp in comps:
        root=_v422_component_root(comp)
        match=(root=='.') or rel==root or rel.startswith(root+'/')
        if not match: continue
        score=0 if root=='.' else len(root)
        if score>best_len: best,best_len=comp,score
    return best


def _v422_registry():
    try:
        p=Path(__file__).resolve().parent/'project_builder_skills'/'toolchains.json'
        data=json.loads(p.read_text(encoding='utf-8',errors='replace'))
        return data if isinstance(data,dict) else {}
    except Exception:
        return {}


def _v422_config_flag_rules():
    fallback={
        'tsc':['-p','--project'], 'vite':['-c','--config'], 'vitest':['--config'],
        'jest':['-c','--config'], 'eslint':['-c','--config'], 'pytest':['-c','--config-file'],
        'cargo':['--manifest-path'], 'mvn':['-f','--file'], 'mvnw':['-f','--file'],
        'gradle':['-b','--build-file','-c','--settings-file'], 'gradlew':['-b','--build-file','-c','--settings-file'],
        'dotnet':['--project'], 'composer':['--working-dir'],
    }
    raw=(_v422_registry().get('command_path_rules') or {})
    for tool,flags in raw.items():
        if isinstance(flags,list) and flags: fallback[str(tool).lower()]=[str(x) for x in flags]
    return fallback


def _v422_split_script(script):
    # We do not execute the fragments. This only gives the configuration-boundary
    # checker a conservative view of ordinary npm/Make-style chained commands.
    return [x.strip() for x in re.split(r'\s*(?:&&|\|\||;)\s*',str(script or '')) if x.strip()]


def _v422_extract_config_refs(script):
    """Return (tool, flag, path) references from known config-path flags."""
    refs=[]; rules=_v422_config_flag_rules()
    for segment in _v422_split_script(script):
        try: toks=shlex.split(segment,posix=(os.name!='nt'))
        except Exception: toks=segment.split()
        if not toks: continue
        tool=Path(str(toks[0])).name.lower()
        if tool in {'npx','pnpm','yarn','bunx'} and len(toks)>1:
            tool=Path(str(toks[1])).name.lower(); toks=toks[1:]
        flags=rules.get(tool) or []
        for i,tok in enumerate(toks):
            for flag in flags:
                if tok==flag and i+1<len(toks):
                    refs.append((tool,flag,str(toks[i+1]).strip('"\'')))
                elif tok.startswith(flag+'='):
                    refs.append((tool,flag,str(tok.split('=',1)[1]).strip('"\'')))
    return refs


def _v422_nested_component_roots(manifest, component):
    root=_v422_component_root(component); out=[]
    for other in (manifest or {}).get('components') or []:
        if not isinstance(other,dict) or other is component: continue
        r=_v422_component_root(other)
        if r=='.': continue
        if root=='.' or r.startswith(root.rstrip('/')+'/'): out.append(r)
    return sorted(set(out),key=len,reverse=True)


def _v422_ref_to_project_path(component, ref):
    ref=str(ref or '').replace('\\','/').strip()
    if not ref or ref.startswith(('/', '~')) or re.match(r'^[A-Za-z]:/',ref): return ''
    base=_v422_component_root(component)
    combined=Path('.' if base=='.' else base)/ref
    parts=[]
    for part in combined.as_posix().split('/'):
        if part in ('','.'): continue
        if part=='..':
            if parts: parts.pop()
            else: return ''
        else: parts.append(part)
    return '/'.join(parts)


def _v422_config_ref_problem(work, manifest, component, script):
    root=Path(work); planned={_v422_norm_rel(x.get('path')) for x in (manifest or {}).get('files') or [] if isinstance(x,dict)}
    nested=_v422_nested_component_roots(manifest,component)
    for tool,flag,ref in _v422_extract_config_refs(script):
        p=_v422_ref_to_project_path(component,ref)
        if not p: continue
        if any(p==n or p.startswith(n+'/') for n in nested):
            return f'{tool} {flag} references {ref}, which belongs to nested component {next(n for n in nested if p==n or p.startswith(n+"/"))}'
        if p not in planned and not (root/p).exists():
            return f'{tool} {flag} references missing/unplanned config {ref}'
    return ''


def _v422_add_file(rows, path, purpose, phase='foundation', depends_on=None):
    path=_v422_norm_rel(path)
    if any(_v422_norm_rel(x.get('path'))==path for x in rows if isinstance(x,dict)): return False
    rows.append({'path':path,'purpose':purpose,'phase':phase,'depends_on':list(depends_on or []),'exports':[],'contracts':[]})
    return True


def _v422_close_component_substrate_plan(manifest):
    if not isinstance(manifest,dict) or not V422_SUBSTRATE_CLOSURE: return manifest
    m=dict(manifest); rows=[dict(x) for x in m.get('files') or [] if isinstance(x,dict) and x.get('path')]
    m['files']=rows
    added=[]
    for comp in [x for x in m.get('components') or [] if isinstance(x,dict)]:
        adapter=_v361_normalize_component_adapter(comp.get('toolchain_adapter'))
        owned=_v422_component_rows(m,comp)
        owned_paths={_v422_norm_rel(x.get('path')) for x in owned}
        has_ts=any(Path(p).suffix.lower() in _V422_TS_EXTS for p in owned_paths)
        if adapter in _V422_NODE_ADAPTERS and has_ts:
            target=_v422_join(_v422_component_root(comp),'tsconfig.json')
            if _v422_add_file(rows,target,'TypeScript compiler configuration owned by this component','foundation'):
                added.append(target)
        if adapter in _V422_VITE_ADAPTERS:
            # Vite needs one component-root host. Root component behavior preserves the
            # V41.2 canonical index.html rule; this also works for nested Vite packages.
            target=_v422_join(_v422_component_root(comp),'index.html')
            entry=_v422_join(_v422_component_root(comp),'src/main.tsx')
            deps=[entry] if any(_v422_norm_rel(x.get('path'))==entry for x in rows) else []
            if _v422_add_file(rows,target,'Vite HTML host owned by this component','foundation',deps): added.append(target)
    # Dedupe after additions while preserving order.
    clean=[]; seen=set()
    for row in rows:
        p=_v422_norm_rel(row.get('path'))
        if not p or p in seen: continue
        seen.add(p); row['path']=p; clean.append(row)
    m['files']=clean
    if added: m['_v422_substrate_added']=added
    return m


def _v422_default_react_tsconfig():
    return {
        'compilerOptions':{
            'target':'ES2020','useDefineForClassFields':True,
            'lib':['ES2020','DOM','DOM.Iterable'],'allowJs':False,'skipLibCheck':True,
            'esModuleInterop':True,'allowSyntheticDefaultImports':True,'strict':True,
            'forceConsistentCasingInFileNames':True,'module':'ESNext','moduleResolution':'Bundler',
            'resolveJsonModule':True,'isolatedModules':True,'noEmit':True,'jsx':'react-jsx'
        },
        'include':['src']
    }


def _v422_component_has_ts(manifest, component):
    return any(Path(_v422_norm_rel(x.get('path'))).suffix.lower() in _V422_TS_EXTS for x in _v422_component_rows(manifest,component))


def _v422_ensure_component_tsconfig(work, manifest, component):
    adapter=_v361_normalize_component_adapter((component or {}).get('toolchain_adapter'))
    if adapter not in _V422_NODE_ADAPTERS or not _v422_component_has_ts(manifest,component): return False
    rel=_v422_join(_v422_component_root(component),'tsconfig.json'); p=Path(work)/rel
    if p.exists():
        if adapter == 'react':
            try:
                data=_v362_jsonc_loads(p.read_text(encoding='utf-8',errors='replace'))
                if isinstance(data,dict):
                    options=data.setdefault('compilerOptions',{})
                    if isinstance(options,dict) and str(options.get('jsx') or '').lower() not in {'react-jsx','react-jsxdev','react','preserve'}:
                        options['jsx']='react-jsx'; p.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
                        try:_v413_mark_accepted(work,rel,'v422_deterministic_tsconfig_hardening')
                        except Exception:pass
                        return True
            except Exception: pass
        return False
    planned={_v422_norm_rel(x.get('path')) for x in (manifest or {}).get('files') or [] if isinstance(x,dict)}
    if rel not in planned: return False
    # Only synthesize a config when the semantics are stable enough to be safe.
    # Framework-owned configs (Angular/Next/SvelteKit/Vue/Expo/etc.) remain model/
    # framework generated; planning still requires them, but Jarvis does not invent
    # a generic config that could silently break framework conventions.
    if adapter == 'react':
        data=_v422_default_react_tsconfig()
    elif adapter == 'vite':
        data={'compilerOptions':{'target':'ES2020','lib':['ES2020','DOM','DOM.Iterable'],'module':'ESNext','moduleResolution':'Bundler','strict':True,'noEmit':True,'skipLibCheck':True,'isolatedModules':True},'include':['src']}
    elif adapter == 'node':
        data={'compilerOptions':{'target':'ES2022','module':'NodeNext','moduleResolution':'NodeNext','strict':True,'noEmit':True,'skipLibCheck':True},'include':['src/**/*.ts','src/**/*.tsx','tests/**/*.ts','tests/**/*.tsx']}
    else:
        return False
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    try:_v413_mark_accepted(work,rel,'v422_deterministic_component_tsconfig')
    except Exception:pass
    try:_append_project_event(work,'v422_component_tsconfig_materialized','V42.2 deterministically materialized missing component-owned TypeScript compiler substrate.',file=rel,component=component.get('id'))
    except Exception:pass
    return True


def _v422_rewrite_tsc_project_refs(script, component, manifest, work):
    """Rewrite only invalid/cross-component tsc project refs to this component's tsconfig."""
    original=str(script or ''); result=original
    target_rel=_v422_join(_v422_component_root(component),'tsconfig.json')
    target_arg='tsconfig.json'
    if not ((Path(work)/target_rel).exists() or target_rel in {_v422_norm_rel(x.get('path')) for x in (manifest or {}).get('files') or [] if isinstance(x,dict)}):
        return original,False
    nested=_v422_nested_component_roots(manifest,component)
    def repl(m):
        nonlocal result
        quote=m.group('q') or ''; ref=m.group('ref')
        project_path=_v422_ref_to_project_path(component,ref)
        invalid=not project_path or any(project_path==n or project_path.startswith(n+'/') for n in nested) or not ((Path(work)/project_path).exists() or project_path in {_v422_norm_rel(x.get('path')) for x in (manifest or {}).get('files') or [] if isinstance(x,dict)})
        if not invalid: return m.group(0)
        return f"{m.group('prefix')}{quote}{target_arg}{quote}"
    # Covers `tsc -p foo`, `tsc --project foo`, and wrappers such as `npx tsc`.
    pat=re.compile(r'(?P<prefix>\btsc\b[^&|;\n]*?(?:-p|--project)(?:\s+|=))(?P<q>["\']?)(?P<ref>[^"\'\s&|;]+)(?P=q)',re.I)
    result=pat.sub(repl,result)
    return result,result!=original


def _v422_harden_package_scripts(work, manifest, component):
    if not V422_DETERMINISTIC_CONFIG_REPAIR: return False
    adapter=_v361_normalize_component_adapter((component or {}).get('toolchain_adapter'))
    if adapter not in _V422_NODE_ADAPTERS: return False
    rel=_v422_join(_v422_component_root(component),'package.json'); p=Path(work)/rel
    if not p.exists(): return False
    try:data=json.loads(p.read_text(encoding='utf-8',errors='replace'))
    except Exception:return False
    scripts=data.get('scripts') or {}
    if not isinstance(scripts,dict): return False
    changed=False; rewrites=[]
    for key,value in list(scripts.items()):
        fixed,did=_v422_rewrite_tsc_project_refs(str(value or ''),component,manifest,work)
        if did:
            scripts[key]=fixed; changed=True; rewrites.append({'script':key,'from':value,'to':fixed})
    if changed:
        data['scripts']=scripts; p.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
        try:_v413_mark_accepted(work,rel,'v422_deterministic_package_script_hardening')
        except Exception:pass
        try:_append_project_event(work,'v422_package_script_hardened','V42.2 rewrote build-script configuration references back to their owning component.',file=rel,component=component.get('id'),rewrites=rewrites)
        except Exception:pass
    return changed


def _v422_prepare_component_substrate(work, manifest, component):
    changed=False
    changed=_v422_ensure_component_tsconfig(work,manifest,component) or changed
    changed=_v422_harden_package_scripts(work,manifest,component) or changed
    return changed


def _v422_component_command_issue(work, manifest, component):
    if not V422_COMPONENT_COMMAND_GATE:return ''
    adapter=_v361_normalize_component_adapter((component or {}).get('toolchain_adapter'))
    scripts=[]
    if adapter in _V422_NODE_ADAPTERS:
        p=Path(work)/_v422_join(_v422_component_root(component),'package.json')
        if p.exists():
            try:
                raw=json.loads(p.read_text(encoding='utf-8',errors='replace'))
                for k,v in (raw.get('scripts') or {}).items(): scripts.append((f'package.json script {k}',str(v or '')))
            except Exception:pass
    for key in ('dependency_command','build_command','test_command','run_command'):
        cmd=str((component or {}).get(key) or '').strip()
        if cmd:scripts.append((key,cmd))
    for label,script in scripts:
        problem=_v422_config_ref_problem(work,manifest,component,script)
        if problem:return f'V42.2 component-command boundary gate: {label}: {problem}. Build/test configuration must be owned by this component or explicitly planned as shared.'
    return ''


# Close required component substrate after plan review and again immediately
