    closed['version']='V'+V422_VERSION; closed['engine']=V422_ENGINE; closed['planner_mode']='universal-component-boundary-v42.2'
    return _v422_prev_execute_manifest(user_request,closed,work,max_files,progress_callback,raw_plan)


