_v422_prev_validate_component = _v35_validate_component

def _v35_validate_component(work, manifest, component, user_request=''):
    _v422_prepare_component_substrate(work,manifest or {},component or {})
    issue=_v422_component_command_issue(work,manifest or {},component or {})
