_v422_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    body=str(prompt or '') + (
        '\n\nV42.2 UNIVERSAL COMPONENT RULE: A component build/test command may reference only configuration owned by that component or an explicitly planned shared config. '
        'Never point a frontend compiler at a backend/native component config (or vice versa) merely to satisfy a build command. '
        'Before writing package/build manifests, keep compiler config, manifest, source root, and build working directory coherent for the selected ecosystem.'
    )
    return _v422_prev_qwen_call(body,progress_callback,str(stage or '').replace('V42.1','V42.2').replace('V42','V42.2'),profile=profile,**kwargs)

# V42.2 late-bound direct self-reference guard. A relative module import that
# resolves to the consumer itself is never a valid way to satisfy a provider
# dependency and can otherwise slip through because "the provider is planned".
def _v422_direct_self_reference_error(rel, content):
    rel=_v422_norm_rel(rel); ext=Path(rel).suffix.lower(); text=str(content or '')
    if ext in {'.ts','.tsx','.js','.jsx','.mjs','.cjs'}:
        import posixpath
        base=Path(rel).parent.as_posix()
        refs=re.findall(r'(?:from\s+|import\s*\(?\s*)["\']([^"\']+)["\']',text)
        for ref in refs:
            if not ref.startswith('.'): continue
            target=posixpath.normpath(posixpath.join(base,ref))
            candidates=[target] if Path(target).suffix else [target+x for x in ('.ts','.tsx','.js','.jsx','.mjs','.cjs')]+[target+'/index'+x for x in ('.ts','.tsx','.js','.jsx')]
            if rel in candidates:
                return f'V42.2 direct self-reference gate: {rel} imports itself through {ref!r}. Import the actual provider or implement/export this module directly.'
    elif ext in {'.py','.pyw'}:
        try: tree=ast.parse(text)
        except Exception: return ''
        current=Path(rel).with_suffix('').as_posix().split('/')
        for node in ast.walk(tree):
            if isinstance(node,ast.ImportFrom) and node.level:
                base=current[:-1]
                if node.level>1: base=base[:-(node.level-1)] if node.level-1<=len(base) else []
                parts=base+((str(node.module or '')).split('.') if node.module else [])
                candidate='/'.join(parts)+'.py' if parts else ''
                if candidate==rel:
                    return f'V42.2 direct self-reference gate: {rel} imports itself through a relative import. Import the intended sibling/provider instead.'
    return ''

_v422_prev_candidate_transaction_error = _candidate_transaction_error

def _candidate_transaction_error(work, manifest, rel, content, user_request=None, validation_failure=None, target_problems=None):
    self_err=_v422_direct_self_reference_error(rel,content)
    if self_err:return self_err
    return _v422_prev_candidate_transaction_error(work,manifest,rel,content,user_request=user_request,validation_failure=validation_failure,target_problems=target_problems)

# V42.2 final requested-behavior barrier. Earlier V42 coverage correction is a
# review aid; this is the late-bound authority immediately before implementation.
# If a later plan merge/sanitizer drops requested behavior (as happened to real
# tests in project_20260830_183449), Jarvis re-reviews once more and refuses to
# spend generation time on an architecturally incomplete repository.
V422_FINAL_PLAN_COVERAGE_BARRIER = os.getenv('JARVIS_V422_FINAL_PLAN_COVERAGE_BARRIER','1').strip().lower() not in {'0','false','no','off'}


def _v422_plan_gaps(user_request, manifest):
    if not _v42rt:return []
    try:return list(_v42rt.plan_coverage_gaps(user_request,manifest) or [])
    except Exception:return []


_v422_coverage_prev_execute_manifest = _v362_execute_manifest

def _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback=None, raw_plan=''):
    current=_v422_close_component_substrate_plan(dict(manifest or {}))
    gaps=_v422_plan_gaps(user_request,current) if V422_FINAL_PLAN_COVERAGE_BARRIER else []
    if gaps:
        _progress(progress_callback,'V42.2 final plan barrier caught requested behavior missing after all plan merges: '+', '.join(gaps)+'. Re-reviewing before source generation.',stage='architecting',percent=20)
        try:
            reviewed=_review_project_plan(user_request,current,max_files,progress_callback)
            if isinstance(reviewed,dict):current=_v422_close_component_substrate_plan(reviewed)
        except Exception:pass
        gaps=_v422_plan_gaps(user_request,current)
    current['_v42_plan_coverage_gaps']=gaps
    if gaps:
        msg='V42.2 refused implementation because the final architecture still omits explicitly requested behavior/test ownership: '+', '.join(gaps)+'. Correct the plan before generating source.'
        try:_append_project_event(work,'v422_final_plan_coverage_blocked',msg,gaps=gaps)
        except Exception:pass
        return False,{'_jarvis_architecture_blocked':True,'_jarvis_architecture_error':msg,**current},[],msg
    return _v422_coverage_prev_execute_manifest(user_request,current,work,max_files,progress_callback,raw_plan)


_v422_coverage_prev_release_identity = _v36_release_identity

def _v36_release_identity():
    data=dict(_v422_coverage_prev_release_identity() or {})
    data['final_plan_coverage_barrier']=V422_FINAL_PLAN_COVERAGE_BARRIER
    return data

# =============================================================================
# V42.3 PROGRESSIVE BUILD-DEBT + GLOBAL CONVERGENCE FACTORY
# =============================================================================
# V42.2 correctly detected incomplete architecture, but it was too strict about
# *when* that incompleteness had to be resolved.  V42.3 keeps the early gates as
# evidence, automatically expands missing requirement ownership, allows bounded
# intermediate build debt when useful future work can still be materialized, and
# leaves the existing whole-project acceptance loop as the ruthless publish gate.
#
# Philosophy: flexible while building, strict before publishing.

V423_VERSION = '42.3.0'
V423_ENGINE = 'PROGRESSIVE_GLOBAL_CONVERGENCE_FACTORY'
V423_REQUIREMENT_DEBT = os.getenv('JARVIS_V423_REQUIREMENT_DEBT','1').strip().lower() not in {'0','false','no','off'}
V423_AUTO_AUGMENT_PLAN = os.getenv('JARVIS_V423_AUTO_AUGMENT_PLAN','1').strip().lower() not in {'0','false','no','off'}
V423_PROGRESSIVE_BUILD_DEBT = os.getenv('JARVIS_V423_PROGRESSIVE_BUILD_DEBT','1').strip().lower() not in {'0','false','no','off'}
V423_MAX_DEBT_CONTINUATION_FILES = max(8, min(1000, int(os.getenv('JARVIS_V423_MAX_DEBT_CONTINUATION_FILES','240'))))
V423_DEBT_FILE = '.jarvis_build/V423_REQUIREMENT_DEBT.json'

# The earlier V38 loop guard intentionally became conservative after an overnight
# runaway. V42.3 restores a little more final-convergence budget without permitting
# unbounded retries. Environment overrides remain authoritative.
if 'JARVIS_QWEN_ACCEPTANCE_ROUNDS' not in os.environ:
    PROJECT_ACCEPTANCE_ROUNDS = max(PROJECT_ACCEPTANCE_ROUNDS, 10)
if 'JARVIS_QWEN_ACCEPTANCE_EXTRA_CLEAN_ROUNDS' not in os.environ:
    PROJECT_ACCEPTANCE_EXTRA_CLEAN_ROUNDS = max(PROJECT_ACCEPTANCE_EXTRA_CLEAN_ROUNDS, 4)
if 'JARVIS_QWEN_ACCEPTANCE_NO_PROGRESS_LIMIT' not in os.environ:
    PROJECT_ACCEPTANCE_NO_PROGRESS_LIMIT = max(PROJECT_ACCEPTANCE_NO_PROGRESS_LIMIT, 4)

# Qwen3.5 has a much larger live context than the routine 32K working set. Planning,
# diagnosis and acceptance get additional headroom so evidence is not compacted to
# ~90% of the window before the answer even begins. Generation stays compact/fast.
if 'JARVIS_QWEN35_WORKING_CONTEXT_PLAN' not in os.environ:
    QWEN35_WORKING_CONTEXT_PLAN = max(QWEN35_WORKING_CONTEXT_PLAN, 49152)
if 'JARVIS_QWEN35_WORKING_CONTEXT_REPAIR' not in os.environ:
    QWEN35_WORKING_CONTEXT_REPAIR = max(QWEN35_WORKING_CONTEXT_REPAIR, 49152)
if 'JARVIS_QWEN35_WORKING_CONTEXT_AUDIT' not in os.environ:
    QWEN35_WORKING_CONTEXT_AUDIT = max(QWEN35_WORKING_CONTEXT_AUDIT, 49152)

_V423_SOURCE_EXT_BY_ADAPTER = {
    'python':'.py','python_desktop':'.py','rust':'.rs','tauri':'.rs','go':'.go',
    'node':'.ts','react':'.ts','vite':'.ts','nextjs':'.ts','vue':'.ts','sveltekit':'.ts','angular':'.ts','electron':'.ts','react_native':'.ts','expo':'.ts',
    'dotnet':'.cs','wpf':'.cs','winforms':'.cs','fsharp':'.fs',
    'java_gradle':'.java','java_maven':'.java','android_gradle':'.kt','kotlin_gradle':'.kt',
    'flutter':'.dart','dart':'.dart','swiftpm':'.swift','ios_xcode':'.swift','macos_xcode':'.swift',
    'cpp_cmake':'.cpp','cpp_make':'.cpp','c_make':'.c','qt_cmake':'.cpp','meson':'.cpp','xmake':'.cpp',
    'ruby_bundler':'.rb','rails':'.rb','php_composer':'.php','elixir_mix':'.ex','erlang_rebar3':'.erl',
    'zig':'.zig','nim':'.nim','odin':'.odin','julia':'.jl','lua':'.lua','perl':'.pl','r':'.R',
    'deno':'.ts','bun':'.ts','powershell':'.ps1','shell_bash':'.sh','clojure':'.clj','crystal':'.cr','racket':'.rkt',
}

_V423_BACKEND_PREFERENCE = {
    'tauri','rust','python','python_desktop','go','dotnet','wpf','winforms','fsharp',
    'java_gradle','java_maven','android_gradle','kotlin_gradle','php_composer','ruby_bundler','rails',
    'elixir_mix','erlang_rebar3','cpp_cmake','cpp_make','c_make','qt_cmake','zig','nim','odin','crystal','clojure'
}


def _v423_components(manifest):
    comps=[x for x in (manifest or {}).get('components') or [] if isinstance(x,dict)]
    if comps:return comps
    return [{'id':'root','root':'.','toolchain_adapter':str((manifest or {}).get('toolchain_adapter') or 'custom'),'purpose':'root project'}]


def _v423_adapter(comp, manifest=None):
    return _v361_normalize_component_adapter((comp or {}).get('toolchain_adapter') or (manifest or {}).get('toolchain_adapter') or 'custom')


def _v423_component_ext(manifest, comp):
    adapter=_v423_adapter(comp,manifest)
    rows=_v422_component_rows(manifest,comp) if '_v422_component_rows' in globals() else list((manifest or {}).get('files') or [])
    counts={}
    ignored={'.json','.toml','.yaml','.yml','.md','.txt','.html','.css','.scss','.xml','.gradle','.properties','.lock'}
    for row in rows:
        p=Path(str(row.get('path') or '')); ext=p.suffix
        if not ext or ext.lower() in ignored:continue
        counts[ext]=counts.get(ext,0)+1
    if counts:
        # Prefer the adapter's native extension when it is already present; otherwise
        # use the dominant implementation extension in this component.
        native=_V423_SOURCE_EXT_BY_ADAPTER.get(adapter)
        if native and native in counts:return native
        return sorted(counts,key=lambda x:(-counts[x],x))[0]
    return _V423_SOURCE_EXT_BY_ADAPTER.get(adapter,'.txt')


def _v423_choose_component(manifest, gap, prefer_backend=False):
    comps=_v423_components(manifest)
    if prefer_backend:
        ranked=[]
        for i,c in enumerate(comps):
            adapter=_v423_adapter(c,manifest); purpose=str(c.get('purpose') or '').lower()
            score=(4 if adapter in _V423_BACKEND_PREFERENCE else 0)+(2 if any(x in purpose for x in ('backend','server','native','core','service','data')) else 0)-(2 if any(x in purpose for x in ('frontend','ui','web')) else 0)
            ranked.append((score,-i,c))
        return max(ranked,key=lambda x:(x[0],x[1]))[2]
    return comps[0]


def _v423_component_has_dir(manifest, comp, dirname):
    root=_v422_component_root(comp) if '_v422_component_root' in globals() else str(comp.get('root') or '.').strip('/') or '.'
    needle=('/'+dirname.strip('/')+'/')
    for row in (manifest or {}).get('files') or []:
        p='/'+str(row.get('path') or '').replace('\\','/').strip('/')+'/'
        if root!='.' and not p.startswith('/'+root.strip('/')+'/'):continue
        if needle in p:return True
    return False


def _v423_join_component(comp, rel):
    root=_v422_component_root(comp) if '_v422_component_root' in globals() else str(comp.get('root') or '.').replace('\\','/').strip('/') or '.'
    rel=str(rel or '').replace('\\','/').strip('/')
    return rel if root=='.' else root+'/'+rel


def _v423_test_path(manifest, comp, ordinal=0):
    adapter=_v423_adapter(comp,manifest); ext=_v423_component_ext(manifest,comp)
    suffix='' if ordinal==0 else f'_{ordinal+1}'
    if adapter in {'rust','tauri'}:return _v423_join_component(comp,f'tests/acceptance{suffix}.rs')
    if adapter in {'python','python_desktop'}:return _v423_join_component(comp,f'tests/test_acceptance{suffix}.py')
    if adapter=='go':return _v423_join_component(comp,f'acceptance{suffix}_test.go')
    if adapter in {'flutter','dart'}:return _v423_join_component(comp,f'test/acceptance{suffix}_test.dart')
    if adapter in {'node','react','vite','nextjs','vue','sveltekit','angular','electron','react_native','expo','deno','bun'}:
        e='.tsx' if any(Path(str(x.get('path') or '')).suffix.lower()=='.tsx' for x in _v422_component_rows(manifest,comp)) else '.ts'
        return _v423_join_component(comp,f'tests/acceptance{suffix}.test{e}')
    if adapter in {'java_gradle','java_maven'}:return _v423_join_component(comp,f'src/test/java/Acceptance{ordinal+1}Test.java')
    if adapter in {'kotlin_gradle','android_gradle'}:return _v423_join_component(comp,f'src/test/kotlin/Acceptance{ordinal+1}Test.kt')
    if adapter in {'dotnet','wpf','winforms'}:return _v423_join_component(comp,f'tests/Acceptance{ordinal+1}Tests.cs')
    if adapter=='fsharp':return _v423_join_component(comp,f'tests/Acceptance{ordinal+1}Tests.fs')
    if adapter in {'cpp_cmake','cpp_make','qt_cmake','meson','xmake'}:return _v423_join_component(comp,f'tests/acceptance{suffix}.cpp')
    if adapter=='c_make':return _v423_join_component(comp,f'tests/acceptance{suffix}.c')
    if adapter in {'ruby_bundler','rails'}:return _v423_join_component(comp,f'test/acceptance{suffix}_test.rb')
    if adapter=='php_composer':return _v423_join_component(comp,f'tests/Acceptance{ordinal+1}Test.php')
    if adapter=='swiftpm':return _v423_join_component(comp,f'Tests/Acceptance{ordinal+1}Tests.swift')
    return _v423_join_component(comp,f'tests/acceptance{suffix}{ext}')


def _v423_feature_owner_path(manifest, gap):
    comp=_v423_choose_component(manifest,gap,prefer_backend=(gap in {'csv_import_export','checkout','authentication','upload_download'}))
    adapter=_v423_adapter(comp,manifest); ext=_v423_component_ext(manifest,comp)
    safe=re.sub(r'[^a-z0-9_]+','_',str(gap or 'feature').lower()).strip('_') or 'feature'
    if adapter in {'rust','tauri'}: rel=f'src/services/{safe}.rs'
    elif adapter in {'python','python_desktop'}: rel=f'src/services/{safe}.py' if _v423_component_has_dir(manifest,comp,'src') else f'{safe}.py'
    elif adapter=='go': rel=f'internal/services/{safe}.go'
    elif adapter in {'java_gradle','java_maven'}: rel='src/main/java/'+''.join(x.title() for x in safe.split('_'))+'Service.java'
    elif adapter in {'kotlin_gradle','android_gradle'}: rel='src/main/kotlin/'+''.join(x.title() for x in safe.split('_'))+'Service.kt'
    elif adapter in {'dotnet','wpf','winforms'}: rel='Services/'+''.join(x.title() for x in safe.split('_'))+'Service.cs'
    elif adapter=='fsharp': rel='Services/'+''.join(x.title() for x in safe.split('_'))+'Service.fs'
    elif adapter in {'node','react','vite','nextjs','vue','sveltekit','angular','electron','react_native','expo','deno','bun'}: rel=f'src/features/{safe}.ts'
    elif adapter in {'flutter','dart'}: rel=f'lib/features/{safe}.dart'
    elif adapter in {'ruby_bundler','rails'}: rel=f'app/services/{safe}.rb' if adapter=='rails' else f'lib/{safe}.rb'
    elif adapter=='php_composer': rel='src/'+''.join(x.title() for x in safe.split('_'))+'Service.php'
    elif adapter in {'cpp_cmake','cpp_make','qt_cmake','meson','xmake'}: rel=f'src/{safe}.cpp'
    elif adapter=='c_make': rel=f'src/{safe}.c'
    else: rel=f'src/{safe}{ext}'
    return comp,_v423_join_component(comp,rel)


def _v423_add_manifest_item(manifest, comp, path, purpose, gap):
    rows=manifest.setdefault('files',[]); path=_v422_norm_rel(path) if '_v422_norm_rel' in globals() else str(path).replace('\\','/').strip('/')
    if not path or any(str(x.get('path') or '').replace('\\','/').strip('/')==path for x in rows if isinstance(x,dict)):return False
    item={'path':path,'purpose':purpose,'phase':'test' if gap=='tests' else 'integration','depends_on':[],'exports':[],'contracts':[f'V42.3 requirement debt owner for {gap}.'],'requirements':[gap],'v423_requirement_debt':gap}
    rows.append(item)
    if isinstance(comp,dict) and isinstance(comp.get('files'),list):comp['files'].append(dict(item))
    return True


def _v423_autoaugment_manifest(user_request, manifest):
    m=json.loads(json.dumps(manifest or {}))
    gaps=_v422_plan_gaps(user_request,m) if '_v422_plan_gaps' in globals() else []
    added=[]
    if not (V423_AUTO_AUGMENT_PLAN and gaps):return m,added,gaps
    for gap in gaps:
        if gap=='tests':
            comps=_v423_components(m)
            # A mixed repository should have at least one real test owner for each of
            # the first few implementation components rather than one token test file.
            source_comps=[]
            for c in comps:
                ext=_v423_component_ext(m,c)
                if ext!='.txt':source_comps.append(c)
            for idx,c in enumerate((source_comps or comps)[:3]):
                p=_v423_test_path(m,c,idx)
                if _v423_add_manifest_item(m,c,p,'Real automated acceptance/integration tests for explicitly requested project behavior. Tests must execute through this component native test runner.',gap):added.append(p)
        else:
            c,p=_v423_feature_owner_path(m,gap)
            if _v423_add_manifest_item(m,c,p,f'Concrete implementation owner for explicitly requested {gap.replace("_"," ")} behavior; integrate with the project public API/UI as applicable.',gap):added.append(p)
    # Re-close conventional substrate because new test/feature owners may make a
    # compiler/test config mandatory in a component that previously looked empty.
    try:m=_v422_close_component_substrate_plan(m)
    except Exception:pass
    remaining=_v422_plan_gaps(user_request,m) if '_v422_plan_gaps' in globals() else []
    m['_v423_autoaugmented_files']=added;m['_v42_plan_coverage_gaps']=remaining
    return m,added,remaining


def _v423_debt_path(work):return Path(work)/V423_DEBT_FILE


def _v423_write_debt(work, manifest, user_request, requirement_gaps=None, build_debt=None, status='open'):
    if not V423_REQUIREMENT_DEBT:return {}
    p=_v423_debt_path(work);p.parent.mkdir(parents=True,exist_ok=True)
    old={}
    try:
        if p.exists():old=json.loads(p.read_text(encoding='utf-8',errors='replace'))
    except Exception:old={}
    payload={
        'version':'V'+V423_VERSION,'engine':V423_ENGINE,'updated_at':_utc_stamp(),'status':status,
        'requirement_gaps':list(requirement_gaps if requirement_gaps is not None else _v422_plan_gaps(user_request,manifest) if '_v422_plan_gaps' in globals() else []),
        'autoaugmented_files':list((manifest or {}).get('_v423_autoaugmented_files') or old.get('autoaugmented_files') or []),
        'build_debt':list(build_debt if build_debt is not None else old.get('build_debt') or []),
        'planned_files':len((manifest or {}).get('files') or []),
    }
    try:_v373_atomic_json_write(p,payload)
    except Exception:
        try:p.write_text(json.dumps(payload,indent=2,ensure_ascii=False),encoding='utf-8')
        except Exception:pass
    return payload


def _v423_recoverable_execution_failure(detail):
    low=str(detail or '').lower()
    if any(x in low for x in ('unsafe path','security boundary','canonical tauri topology did not converge','contradictory requirements')):return False
    return any(x in low for x in (
        'milestone blocked','current vertical slice failed','build/test','build test','component failed','component_validation',
        'did not converge','does not converge','file does not exist','missing implementation','validation failed','compile','compiler'
    ))


def _v423_visible_files(work, manifest):
    out=[];root=Path(work)
    for item in (manifest or {}).get('files') or []:
        rel=str(item.get('path') or '');p=root/rel
        if not p.exists() or not p.is_file():continue
        if _looks_text_file(p):
            try:out.append((rel,p.read_text(encoding='utf-8',errors='replace')))
            except Exception:pass
        elif p.stat().st_size>0:out.append((rel,''))
    return out


def _v423_continue_with_build_debt(user_request, manifest, work, failure_detail, progress_callback=None):
    """Materialize the rest of the intended repository after a bounded intermediate
    failure, then hand the whole project to the existing strict acceptance engine.
    This never publishes debt: generate_project_zip still requires final acceptance,
    real validation and the hard publish gate before packaging.
    """
    work=Path(work);m=dict(manifest or {})
    files=[dict(x) for x in m.get('files') or [] if isinstance(x,dict) and x.get('path')][:V423_MAX_DEBT_CONTINUATION_FILES]
    if not files:return False,m,[],failure_detail
    paths=[str(x.get('path') or '') for x in files]
    m['_v39_active_paths']=sorted(set(paths))
    debt=[{'type':'intermediate_build_failure','detail':str(failure_detail or '')[-7000:],'recorded_at':_utc_stamp()}]
    _v423_write_debt(work,m,user_request,build_debt=debt,status='materializing_remaining')
    _append_project_event(work,'v423_build_debt_opened','V42.3 preserved an intermediate failure as build debt and continued materializing independent/future planned work. Final publication still requires zero debt.',failure=str(failure_detail or '')[-3500:])
    _progress(progress_callback,'V42.3 intermediate gate did not converge; preserving it as build debt and materializing the rest of the planned repository before global convergence.',stage='generating',percent=72)
    try:ordered=[x for x in _v33_dependency_ordered_files(m) if isinstance(x,dict)]
    except Exception:ordered=files
    seen={str(x.get('path') or '') for x in ordered};ordered += [x for x in files if str(x.get('path') or '') not in seen]
    unresolved=[];attempted=0
    for item in ordered:
        rel=str(item.get('path') or '');
        if not rel:continue
        if _v413_is_accepted(work,rel) and _v39_file_is_implemented(work,rel):continue
        attempted+=1
        _progress(progress_callback,f'V42.3 debt continuation {attempted}: {rel}',stage='generating',percent=min(84,72+attempted//3),current_file=rel)
        try:
            ok,_=_generate_planned_file(user_request,m,work,item,progress_callback)
        except Exception as exc:
            ok=False;unresolved.append({'file':rel,'problem':str(exc)})
        if not ok and not any(x.get('file')==rel for x in unresolved):
            unresolved.append({'file':rel,'problem':'File did not reach accepted revision during debt continuation.'})
    m.pop('_v39_active_paths',None)
    remaining_gaps=_v422_plan_gaps(user_request,m) if '_v422_plan_gaps' in globals() else []
    debt.append({'type':'materialization_debt','unresolved_files':unresolved[:80],'recorded_at':_utc_stamp()})
    _v423_write_debt(work,m,user_request,requirement_gaps=remaining_gaps,build_debt=debt,status='ready_for_global_convergence')
    try:_v373_refresh_project_kb(work,m,reason='v423_debt_continuation_complete',force=True)
    except Exception:pass
    _append_project_event(work,'v423_global_convergence_ready',f'V42.3 materialized the repository after intermediate debt; normal whole-project acceptance will now own all remaining repairs.',attempted=attempted,unresolved=len(unresolved),requirement_gaps=remaining_gaps)
    visible=_v423_visible_files(work,m)
    return bool(_existing_real_source_files(work)),m,visible,str(failure_detail or '')


# Keep V42.2's complete chain, but turn its final coverage barrier into automatic
# architecture expansion and convert recoverable intermediate aborts into a debt
# continuation. The outer generate_project_zip acceptance/publish gates remain
# unchanged and therefore remain the final authority.
_v423_prev_execute_manifest = _v362_execute_manifest

def _v362_execute_manifest(user_request, manifest, work, max_files, progress_callback=None, raw_plan=''):
    current=dict(manifest or {})
    try:current=_v422_close_component_substrate_plan(current)
    except Exception:pass
    current,added,remaining=_v423_autoaugment_manifest(user_request,current)
    if added:
        _progress(progress_callback,'V42.3 automatically expanded missing requirement ownership instead of aborting preflight: '+', '.join(added[:10]),stage='architecting',percent=21)
        try:_append_project_event(work,'v423_plan_autoaugmented','V42.3 converted final coverage gaps into concrete planned implementation/test owners and continued.',files=added,remaining_gaps=remaining)
        except Exception:pass
    _v423_write_debt(work,current,user_request,requirement_gaps=remaining,status='planning' if remaining else 'plan_covered')
    # If a rare custom gap remains, implementation is still allowed; the generated
    # debt owner + global acceptance is safer than throwing away an otherwise useful
    # architecture. Remove the V42.2 barrier signal only from metadata; the original
    # requirements ledger remains authoritative throughout generation/acceptance.
    current['_v42_plan_coverage_gaps']=remaining
    result=_v423_prev_execute_manifest(user_request,current,work,max_files,progress_callback,raw_plan)
    try:ok,obj,candidates,raw=result
    except Exception:return result
    if ok:
        _v423_write_debt(work,obj if isinstance(obj,dict) else current,user_request,status='implementation_complete')
        return result
    detail=str((obj or {}).get('_jarvis_failure_detail') or (obj or {}).get('_jarvis_architecture_error') or raw or '') if isinstance(obj,dict) else str(raw or '')
    # V42.2 can still return its old coverage-block result if a custom coverage
    # classifier does not recognize our synthetic owner. Retry once with any newly
    # discovered gaps materialized before treating it as a real architecture failure.
    if isinstance(obj,dict) and 'final architecture still omits explicitly requested' in detail.lower():
        retry,more,remain=_v423_autoaugment_manifest(user_request,obj)
        if more:
            try:return _v423_prev_execute_manifest(user_request,retry,work,max_files,progress_callback,raw_plan)
            except Exception:pass
    if V423_PROGRESSIVE_BUILD_DEBT and isinstance(obj,dict) and obj.get('files') and _v423_recoverable_execution_failure(detail):
        return _v423_continue_with_build_debt(user_request,obj,work,detail,progress_callback)
    return result


# Requirement debt is also visible to deterministic final acceptance. Planned debt
# owners must actually exist and be implemented; a manifest mention alone never
# satisfies publication.
_v423_prev_deterministic_acceptance_issues = _deterministic_acceptance_issues

def _deterministic_acceptance_issues(work, manifest):
    issues=list(_v423_prev_deterministic_acceptance_issues(work,manifest) or [])
    seen={(str(x.get('file') or ''),str(x.get('problem') or '')) for x in issues}
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item,dict) or not item.get('v423_requirement_debt'):continue
        rel=str(item.get('path') or '');gap=str(item.get('v423_requirement_debt') or '')
        if not _v39_file_is_implemented(work,rel):
            row={'file':rel,'kind':'missing','problem':f'V42.3 requirement debt unresolved: {gap} owner is not a real implemented file.'}
            key=(rel,row['problem'])
            if key not in seen:issues.append(row);seen.add(key)
    return issues


# Add universal + process skills alongside stack-specific cards.  These are small
# engineering constraints, not giant per-language prompts.
_v423_prev_stack_skill_names = _v36_stack_skill_names

def _v36_stack_skill_names(manifest):
    names=[]
    def add(x):
        if x and x not in names and (V36_SKILLS_DIR/f'{x}.md').exists():names.append(x)
    add('universal')
    comps=[x for x in (manifest or {}).get('components') or [] if isinstance(x,dict)]
    if len(comps)>1:add('mixed-repo')
    for n in _v423_prev_stack_skill_names(manifest):add(n)
    blob=' '.join(str((manifest or {}).get(k) or '') for k in ('toolchain_adapter','framework','language','platform','build_system')).lower()
    blob+=' '+' '.join(' '.join(str(c.get(k) or '') for k in ('toolchain_adapter','framework','language','purpose')).lower() for c in comps)
    mapping=[
        ('deno','deno'),('bun','bun'),('powershell','powershell'),('pwsh','powershell'),('bash','shell'),('docker','docker'),('kubernetes','kubernetes'),('helm','kubernetes'),
        ('clojure','clojure'),('f#','fsharp'),('fsharp','fsharp'),('crystal','crystal'),('racket','racket'),('fastapi','fastapi'),('django','django'),
        ('api','api'),('database','database'),('sql','database'),('test','testing'),('csv','data-import-export')
    ]
    for needle,name in mapping:
        if needle in blob:add(name)
    # Process skills are broadly useful but kept bounded for the 9B model.
    for n in ('build-systems','diagnostics','integration-testing'):
        add(n)
    return names[:8]


# Merge disk registry adapters into the legacy built-in catalog so adding an adapter
# does not require another monolithic Python if/elif branch.
_v423_prev_toolchain_catalog = _v34_toolchain_catalog

