_v423_prev_progress = _progress

def _progress(callback, text=None, **fields):
    if text is not None:
        text=str(text).replace('V42.2','V42.3').replace('V42.1','V42.3').replace('V42.0','V42.3')
    return _v423_prev_progress(callback,text,**fields)


_v423_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    body=str(prompt or '') + (
        '\n\nV42.3 PROGRESSIVE CONVERGENCE RULE: Treat the architecture as repairable, not sacred. '
        'If an explicit requirement lacks an owner, add the smallest real implementation/test owner and continue. '
        'During implementation, resolve blockers when practical but do not throw away the whole project merely because one intermediate slice is not green if independent planned work can still be materialized. '
        'After all intended files exist, the whole-repository acceptance/build/test/startup gates become strict: no missing requested behavior, no placeholders, no unresolved names/imports/types/dependencies, and no publish until real validation passes.'
    )
    return _v423_prev_qwen_call(body,progress_callback,str(stage or '').replace('V42.2','V42.3').replace('V42.1','V42.3'),profile=profile,**kwargs)

# V42.3 registry-first inference for newly registered ecosystems. Existing explicit
# framework rules remain first authority; this only recognizes adapters/languages
# that older hard-coded inference could not know about.
_v423_prev_infer_toolchain = _v34_infer_toolchain

def _v34_infer_toolchain(text, manifest=None, work=None):
    low=(' '+_v411_clean_request(text)+' ').lower()
    registry=_v34_toolchain_catalog()
    aliases={
        'deno':['deno'], 'bun':['bun runtime','using bun','bun '], 'powershell':['powershell','pwsh'], 'shell_bash':[' bash ','bash script'],
        'docker_compose':['docker compose','docker-compose'], 'kubernetes_helm':['kubernetes',' helm chart','helm chart'],
        'clojure':['clojure'], 'fsharp':['f#','fsharp'], 'crystal':['crystal language','using crystal','in crystal'], 'racket':['racket language','using racket'],
        'fortran_cmake':['fortran'], 'cuda_cmake':['cuda','nvcc'], 'wasm_rust':['rust wasm','rust webassembly','wasm-pack'],
    }
    # Framework/engine rules from the mature inferencer stay stronger.
    old=_v423_prev_infer_toolchain(text,manifest,work)
    if old not in {'generic','custom'}:return old
    named=str((manifest or {}).get('toolchain_adapter') or '').strip().lower()
    if named in registry:return named
    if work:
        root=Path(work)
        # Registry-driven marker detection lets newly added ecosystems work for
        # resume/imported repositories without another Python routing patch.
        specific=[]
        for adapter,row in registry.items():
            markers=list((row or {}).get('markers') or [])
            score=sum(2 if any(ch in str(m) for ch in '*?[') else 3 for m in markers)
            specific.append((score,adapter,markers))
        for _score,adapter,markers in sorted(specific,reverse=True):
            for marker in markers:
                try:
                    if any(ch in str(marker) for ch in '*?['):
                        if next(iter(root.rglob(str(marker))),None):return adapter
                    elif next(iter(root.rglob(str(marker))),None):return adapter
                except Exception:pass
    language=str((manifest or {}).get('language') or '').strip().lower()
    for adapter,row in registry.items():
        if adapter in aliases and any(a in low for a in aliases[adapter]):return adapter
        lang=str((row or {}).get('language') or '').lower()
        if language and adapter in aliases and (language==lang or language in lang.split('/')):return adapter
    return old

# Explicitly label the already-mature acceptance engine as V42.3 global convergence
# and close the debt ledger only after that engine reports clean. generate_project_zip
# still performs its independent hard final verification after this returns.
_v423_prev_acceptance_repair_cycle = _acceptance_repair_cycle

def _acceptance_repair_cycle(user_request, manifest, work, progress_callback=None):
    _v423_write_debt(work,manifest,user_request,status='global_convergence')
    _progress(progress_callback,'V42.3 global convergence: repairing the complete repository against deterministic checks, real build/tests/runtime evidence, and requested behavior.',stage='verifying',percent=80)
    ok,issues=_v423_prev_acceptance_repair_cycle(user_request,manifest,work,progress_callback)
    gaps=_v422_plan_gaps(user_request,manifest) if '_v422_plan_gaps' in globals() else []
    if ok and not gaps:
        _v423_write_debt(work,manifest,user_request,requirement_gaps=[],build_debt=[],status='closed_clean')
        try:_append_project_event(work,'v423_global_convergence_green','V42.3 whole-repository convergence reached clean acceptance; hard final publish verification remains.',remaining_requirement_debt=[])
        except Exception:pass
    else:
        _v423_write_debt(work,manifest,user_request,requirement_gaps=gaps,build_debt=[{'type':'acceptance_remaining','issues':[str(x) for x in (issues or [])[:40]]}],status='global_convergence_blocked')
    return ok,issues

# =============================================================================
# V42.4 PROVIDER-FIRST FAST GLOBAL CONVERGENCE FACTORY
# =============================================================================
# Live regression (GearTrack overnight convergence, 2026-08-31): several UI
# consumers were repeatedly repaired while their canonical provider (src/types.ts)
# was planned but had never reached an accepted revision.  The subsystem graph
# could omit that provider because missing/unaccepted files have weak/no live graph
# edges.  This caused hours of leaf patch churn.
#
# V42.4 makes provider health authoritative before consumer repair, includes
# planned canonical providers in subsystem transactions even when they are absent
# from the live repo graph, understands transpiled JS/TS source-extension aliases,
# and shortens repeated leaf strategies before escalating to a coherent subsystem
# repair.  Final acceptance remains unchanged: no ZIP is published with debt.

V424_VERSION = '42.4.0'
V424_ENGINE = 'PROVIDER_FIRST_FAST_GLOBAL_CONVERGENCE_FACTORY'
V424_PROVIDER_FIRST = os.getenv('JARVIS_V424_PROVIDER_FIRST','1').strip().lower() not in {'0','false','no','off'}
V424_FAST_REPAIR = os.getenv('JARVIS_V424_FAST_REPAIR','1').strip().lower() not in {'0','false','no','off'}
V424_PROVIDER_PREPASS_MAX = max(1, min(16, int(os.getenv('JARVIS_V424_PROVIDER_PREPASS_MAX','8'))))
V424_REPAIR_PROMPT_TOKENS = max(14000, min(40000, int(os.getenv('JARVIS_V424_REPAIR_PROMPT_TOKENS','24000'))))
V424_SUBSYSTEM_PROMPT_TOKENS = max(V424_REPAIR_PROMPT_TOKENS, min(48000, int(os.getenv('JARVIS_V424_SUBSYSTEM_PROMPT_TOKENS','30000'))))

# Faster bounded defaults.  Explicit environment overrides remain authoritative.
if V424_FAST_REPAIR:
    if 'JARVIS_V37_PATCH_CANDIDATES' not in os.environ:
        V37_PATCH_CANDIDATES = min(int(V37_PATCH_CANDIDATES), 2)
    if 'JARVIS_V36_REPAIR_CANDIDATES' not in os.environ:
        V36_REPAIR_CANDIDATES = min(int(V36_REPAIR_CANDIDATES), 2)
    if 'JARVIS_QWEN_RUNTIME_REPAIR_TARGETS' not in os.environ:
        PROJECT_RUNTIME_REPAIR_TARGETS = min(int(PROJECT_RUNTIME_REPAIR_TARGETS), 3)
    if 'JARVIS_QWEN_FILE_REPAIR_WALL_SECONDS' not in os.environ:
        FILE_REPAIR_WALL_SECONDS = min(int(FILE_REPAIR_WALL_SECONDS), 480)
    if 'JARVIS_V413_REGEN_ATTEMPTS' not in os.environ:
        V413_REGEN_ATTEMPTS = min(int(V413_REGEN_ATTEMPTS), 3)

_V424_PROVIDER_GUARD = set()


def _v424_component_scope(manifest, rel):
    rel = _v40_norm_rel(rel)
    best = None
    for comp in (manifest or {}).get('components') or []:
        if not isinstance(comp, dict):
            continue
        root = _v40_norm_rel(comp.get('root')) or '.'
        if root == '.' or rel == root or rel.startswith(root + '/'):
            if best is None or len(root) > len(best[0]):
                best = (root, str(comp.get('id') or root))
    return best[1] if best else 'root'


def _v424_owner_rows(manifest):
    try:
        return list(_v40_domain_owner_payload(manifest or {}).get('owners') or [])
    except Exception:
        return []


def _v424_provider_paths_for_consumer(manifest, rel, problems=None):
    """Return canonical providers relevant to one consumer, provider-first.

    This uses the frozen owner table, not only the live repo graph.  That matters
    when the provider is planned but missing/unaccepted and therefore has no graph
    edges yet.
    """
    scope = _v424_component_scope(manifest, rel)
    text = '\n'.join(str(x or '') for x in (problems or [])).lower()
    explicit = []
    for m in re.finditer(r'canonical owner(?:\s+for\s+component\s+[^;,.]+)?\s+(?:is|at)\s+([^;,.\s]+)', text, re.I):
        explicit.append(_v40_norm_rel(m.group(1).strip('`\'"')))
    ranked = []
    for row in _v424_owner_rows(manifest):
        provider = _v40_norm_rel(row.get('provider'))
        if not provider or provider == _v40_norm_rel(rel):
            continue
        row_scope = str(row.get('scope') or '')
        if row_scope and row_scope != scope:
            continue
        symbol = str(row.get('symbol') or '')
        score = 0
        if provider in explicit:
            score += 100
        if symbol and symbol.lower() in text:
            score += 40
        # If this is a consumer in a component with one shared provider, allow an
        # unhealthy provider to be considered even when the compiler message only
        # mentions a derived generic/type mismatch.
        score += 5
        ranked.append((score, provider))
    out = []
    for _score, provider in sorted(ranked, key=lambda x: (-x[0], x[1])):
        if provider not in out:
            out.append(provider)
    for provider in explicit:
        if provider and provider not in out:
            out.insert(0, provider)
    return out


def _v424_provider_state_problem(work, manifest, provider):
    provider = _v40_norm_rel(provider)
    item = _manifest_file_item(manifest or {}, provider)
    if not item:
        return ''
    p = Path(work) / provider
    if not p.exists() or not p.is_file():
        return 'canonical provider is missing from the workspace'
    if not _v413_is_accepted(work, provider):
        return 'canonical provider exists only as an unaccepted/rejected revision'
    if not _v39_file_is_implemented(work, provider):
        return 'canonical provider is still a skeleton/incomplete implementation'
    try:
        err = _v401_file_green_error(work, manifest or {}, provider)
        if err:
            return str(err)
    except Exception:
        pass
    return ''


def _v424_repair_one_provider(user_request, manifest, work, provider, progress_callback=None, reason=''):
    provider = _v40_norm_rel(provider)
    key = (str(Path(work).resolve()), provider)
    if key in _V424_PROVIDER_GUARD:
        return False
    problem = _v424_provider_state_problem(work, manifest, provider)
    if not problem:
        return False
    item = _manifest_file_item(manifest or {}, provider)
    if not item:
        return False
    _V424_PROVIDER_GUARD.add(key)
    try:
        _progress(progress_callback, f'V42.4 provider-first repair: {provider}', stage='repairing', percent=79, current_file=provider)
        _append_project_event(
            work, 'v424_provider_first_started',
            f'Repairing canonical provider {provider} before downstream consumers.',
            file=provider, reason=reason or problem,
        )
        # Missing/unaccepted/skeleton providers get a clean whole-file generation.
        if (not (Path(work)/provider).exists()) or (not _v413_is_accepted(work, provider)) or (not _v39_file_is_implemented(work, provider)):
            fresh = dict(item)
            fresh.setdefault('contracts', [])
            fresh['contracts'] = list(fresh.get('contracts') or []) + [
                'V42.4 PROVIDER-FIRST AUTHORITY: this file is the canonical provider for multiple consumers. Generate the COMPLETE provider first; consumers must import/use it rather than redefine its contracts.',
                'Provider-health evidence: ' + str(problem)[:1800],
            ]
            ok, _ = _generate_planned_file(user_request, manifest, work, fresh, progress_callback)
        else:
            # Accepted but locally unhealthy provider: use the mature transactional
            # repair chain directly.  Avoid re-entering this V42.4 wrapper.
            ok = _v424_prev_repair_file_for_issues(
                user_request, manifest, work, provider,
                [f'CANONICAL PROVIDER ROOT CAUSE: {problem}', str(reason or '')[:1800]],
                progress_callback,
                validation_failure=None,
            )
        if ok and not _v424_provider_state_problem(work, manifest, provider):
            _append_project_event(work, 'v424_provider_first_green', f'Canonical provider {provider} is now accepted/implemented before consumer repair.', file=provider)
            try:
                _v373_refresh_project_kb(work, manifest, reason='v424_provider_first_green', force=True)
            except Exception:
                pass
            return True
        _append_project_event(work, 'v424_provider_first_unresolved', f'Canonical provider {provider} still needs convergence after provider-first attempt.', file=provider)
        return bool(ok)
    finally:
        _V424_PROVIDER_GUARD.discard(key)


def _v424_provider_health_prepass(user_request, manifest, work, progress_callback=None, focus_rel='', focus_problems=None):
    if not V424_PROVIDER_FIRST:
        return False
    providers = []
    if focus_rel:
        providers.extend(_v424_provider_paths_for_consumer(manifest, focus_rel, focus_problems))
    # Add every unhealthy frozen canonical provider.  Shared providers are cheap to
    # fix once and can collapse many downstream compiler errors simultaneously.
    for row in _v424_owner_rows(manifest):
        p = _v40_norm_rel(row.get('provider'))
        if p and p not in providers and _v424_provider_state_problem(work, manifest, p):
            providers.append(p)
    changed = False
    attempted = 0
    for provider in providers:
        if attempted >= V424_PROVIDER_PREPASS_MAX:
            break
        if not _v424_provider_state_problem(work, manifest, provider):
            continue
        attempted += 1
        if _v424_repair_one_provider(
            user_request, manifest, work, provider, progress_callback,
            reason=('consumer '+_v40_norm_rel(focus_rel)+' failed around this canonical contract') if focus_rel else 'global canonical-provider health prepass',
        ):
            changed = True
    if changed:
        try:
            _v36_build_repo_graph(work, manifest, write=True)
            _v36_build_contract_registry(work, manifest, write=True)
        except Exception:
            pass
    return changed


# Provider-first leaf rerouting.  If a consumer error points at an unhealthy
# canonical provider, spend the model call on the provider and obtain fresh
# compiler evidence before touching the consumer.
_v424_prev_repair_file_for_issues = _repair_file_for_issues

def _repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback=None, validation_failure=None):
    rel = _v40_norm_rel(rel)
    if V424_PROVIDER_FIRST and _v424_provider_health_prepass(user_request, manifest, work, progress_callback, rel, problems):
        _append_project_event(work, 'v424_consumer_repair_rerouted', f'Deferred consumer repair for {rel}; a canonical provider changed first, so stale consumer diagnostics will be revalidated.', file=rel)
        return True
    return _v424_prev_repair_file_for_issues(user_request, manifest, work, rel, problems, progress_callback, validation_failure=validation_failure)


# Subsystem selection must include planned canonical providers even when those
# providers are absent/unaccepted and therefore missing from the live repo graph.
_v424_prev_select_subsystem_files = _v381_select_subsystem_files

def _v381_select_subsystem_files(work, manifest, target_rel, current_issues=None):
    selected, root_name, component = _v424_prev_select_subsystem_files(work, manifest, target_rel, current_issues)
    scope = str((component or {}).get('id') or root_name)
    provider_paths = []
    for row in _v424_owner_rows(manifest):
        if str(row.get('scope') or '') != scope:
            continue
        p = _v40_norm_rel(row.get('provider'))
        if p and _manifest_file_item(manifest or {}, p) and p not in provider_paths:
            provider_paths.append(p)
    # Providers first, then the mature graph-ranked cluster.  Keep the same bound.
    merged = []
    for p in provider_paths + list(selected or []):
        if p and p not in merged:
            merged.append(p)
    return merged[:V38_SUBSYSTEM_MAX_FILES], root_name, component


# TypeScript/JavaScript emit often imports `./types.js` from TS source while the
# repository provider is `./types.ts`/`.tsx`.  Treat same-stem transpiled source
# aliases as the same planned internal provider instead of rejecting a valid
# candidate as an architecture violation.
_v424_prev_internal_import_error = _v362_candidate_internal_import_error

def _v424_planned_source_alias(manifest, rel):
    rel = _v40_norm_rel(rel)
    paths = {_v40_norm_rel(x.get('path')) for x in (manifest or {}).get('files') or [] if isinstance(x,dict)}
    if rel in paths:
        return rel
    p = Path(rel); suffix = p.suffix.lower(); stem = p.with_suffix('').as_posix()
    aliases = {
        '.js':('.ts','.tsx','.jsx','.mts','.cts'),
        '.mjs':('.mts','.ts','.tsx','.js'),
        '.cjs':('.cts','.ts','.js'),
        '.jsx':('.tsx','.ts','.js'),
    }.get(suffix,())
    for ext in aliases:
        candidate = stem + ext
        if candidate in paths:
            return candidate
    return ''


def _v362_candidate_internal_import_error(work, manifest, rel, content):
    err = _v424_prev_internal_import_error(work, manifest, rel, content)
    if not err or 'imports internal provider(s) not present in the frozen architecture:' not in str(err):
        return err
    try:
        body = str(err).split('architecture:',1)[1].split('. Architecture must plan',1)[0]
        missing = [_v40_norm_rel(x.strip()) for x in body.split(',') if x.strip()]
    except Exception:
        return err
    unresolved = [x for x in missing if not _v424_planned_source_alias(manifest, x)]
    if not unresolved:
        return ''
    if len(unresolved) != len(missing):
        return 'V42.4 dependency-closure gate: generated source still imports unplanned internal provider(s): '+', '.join(unresolved)+'. Same-stem transpiled source aliases were resolved against the frozen architecture.'
    return err


# Root-cause pass before global acceptance and before model diagnosis of a real
# compiler/build failure.  If it changes a provider, immediately rerun validation
# instead of diagnosing stale consumer errors.
_v424_prev_acceptance_repair_cycle = _acceptance_repair_cycle

def _acceptance_repair_cycle(user_request, manifest, work, progress_callback=None):
    if V424_PROVIDER_FIRST:
        _v424_provider_health_prepass(user_request, manifest, work, progress_callback)
    return _v424_prev_acceptance_repair_cycle(user_request, manifest, work, progress_callback)


_v424_prev_real_validation_repair = _repair_real_validation_failure

def _repair_real_validation_failure(user_request, manifest, work, failure, progress_callback=None):
    if V424_PROVIDER_FIRST and _v424_provider_health_prepass(user_request, manifest, work, progress_callback):
        _progress(progress_callback, 'V42.4 repaired an unhealthy canonical provider before compiler-error leaf diagnosis; retrying real validation once with fresh evidence.', stage='repairing')
        return True
    return _v424_prev_real_validation_repair(user_request, manifest, work, failure, progress_callback)


# Compact only repair prompts, not planning/generation/audit.  Focused repair
# prompts do not need to prefill almost the entire working window, and smaller
# prefill materially improves local-model throughput.
def _v424_trim_repair_prompt(prompt, token_cap):
    raw = str(prompt or '')
    if _qwen_estimated_tokens(raw) <= token_cap:
        return raw
    marker = '\n\n[... V42.4 FAST REPAIR COMPACTION: repeated/background context omitted; target instructions, canonical contracts, failure evidence, and current source boundaries preserved ...]\n\n'
    char_cap = max(32000, int(token_cap * QWEN3_CHARS_PER_TOKEN))
    usable = max(12000, char_cap-len(marker))
    # Repair instructions/architecture are usually in the head; current source and
    # related evidence are usually in the tail.
    head_n = int(usable*0.55); tail_n = usable-head_n
    return raw[:head_n] + marker + raw[-tail_n:]


_v424_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    body = str(prompt or '')
    low = str(stage or '').lower()
    if V424_FAST_REPAIR and str(profile or '').lower() == 'repair':
        cap = V424_SUBSYSTEM_PROMPT_TOKENS if any(x in low for x in ('subsystem','reconcil','architect/debugger')) else V424_REPAIR_PROMPT_TOKENS
        before = _qwen_estimated_tokens(body)
        body = _v424_trim_repair_prompt(body, cap)
        after = _qwen_estimated_tokens(body)
        if after < before:
            _progress(progress_callback, f'V42.4 fast repair context: focused {before:,} -> {after:,} estimated tokens before local-model prefill.', stage='repairing')
    body += (
        '\n\nV42.4 PROVIDER-FIRST REPAIR RULE: Before editing a consumer, honor the frozen canonical provider map. '
        'If several consumers disagree around the same model/type/interface/schema/header/module, repair or regenerate the canonical provider first, then revalidate before touching consumers. '
        'Do not redefine canonical types in stores/controllers/UI merely to silence compiler errors. For TypeScript source, prefer extensionless internal imports unless the project module mode intentionally uses .js specifiers that resolve to planned .ts/.tsx providers. '
        'Use the smallest root-cause change that collapses the largest error family.'
    )
    return _v424_prev_qwen_call(body, progress_callback, str(stage or '').replace('V42.3','V42.4').replace('V42.2','V42.4'), profile=profile, **kwargs)


# Add focused process skills without turning the main prompt into a huge manual.
_v424_prev_stack_skill_names = _v36_stack_skill_names

def _v36_stack_skill_names(manifest):
    names = list(_v424_prev_stack_skill_names(manifest) or [])
    for n in ('dependency-graph-repair','type-contracts','fast-convergence'):
        if (V36_SKILLS_DIR/f'{n}.md').exists() and n not in names:
            names.append(n)
    return names[:10]


_v424_prev_release_identity = _v36_release_identity

def _v36_release_identity():
    data = dict(_v424_prev_release_identity() or {})
    data.update({
        'version':'V'+V424_VERSION,
        'engine':V424_ENGINE,
        'planner_mode':'provider-first-fast-global-convergence-v42.4',
        'provider_first_global_convergence':V424_PROVIDER_FIRST,
        'planned_provider_injection':True,
        'transpiled_source_import_aliases':True,
        'fast_leaf_patch_candidates':int(V37_PATCH_CANDIDATES),
        'runtime_repair_targets':int(PROJECT_RUNTIME_REPAIR_TARGETS),
        'repair_wall_seconds':int(FILE_REPAIR_WALL_SECONDS),
        'focused_repair_prompt_tokens':int(V424_REPAIR_PROMPT_TOKENS),
        'strict_zero_debt_publish_gate':True,
        'skill_cards':len(list(V36_SKILLS_DIR.glob('*.md'))),
        'registered_toolchain_adapters':len(_v34_toolchain_catalog()),
    })
    return data


_v424_prev_progress = _progress

def _progress(callback, text=None, **fields):
    if text is not None:
        text = str(text).replace('V42.3','V42.4').replace('V42.2','V42.4').replace('V42.1','V42.4')
    return _v424_prev_progress(callback, text, **fields)

# ============================================================
# V42.6 - AUTO HYBRID 9B WORKER + NEW QWEN3.8 27B SPECIALIST
# ============================================================
# AUTO is intentionally limited to exactly two local models:
#   * 9b35     = Qwen3.5-9B HauhauCS Aggressive Q4_K_M (fast worker)
#   * 27b38q2  = Qwen3.8-27B HauhauCS Aggressive Q2_K_P (hard-work specialist)
# The legacy 27B OBLITERATED and 8B profiles remain manual-only choices.
# Manual selections are strict project locks and are NEVER promoted/demoted.
import threading as _v426_threading
from qwen_model_manager import (
    ensure_qwen_profile as _v426_ensure_qwen_profile,
    normalize_profile as _v426_normalize_profile,
    active_profile as _v426_active_profile,
    _runtime_matches as _v426_runtime_matches,
)

V426_VERSION = '42.6'
V426_ENGINE = 'auto-hybrid-model-router'
V426_AUTO_WORKER = '9b35'
V426_AUTO_SPECIALIST = '27b38q2'
V426_HARD_PROMPT_TOKENS = max(8000, int(os.getenv('JARVIS_V426_HARD_PROMPT_TOKENS', '18000')))
V426_REPEAT_PROMOTE_AT = max(2, int(os.getenv('JARVIS_V426_REPEAT_PROMOTE_AT', '2')))
V426_AUTO_ROUTING = os.getenv('JARVIS_V426_AUTO_ROUTING', '1').strip().lower() not in {'0','false','no','off'}
_V426_ROUTE = _v426_threading.local()


def configure_project_qwen_routing(selection='auto'):
    """Capture one project's model policy in thread-local state.

    AUTO may route between the 9B worker and the *new* 27B38 Q2_K_P specialist.
    Any explicit dropdown selection is a strict model lock for the whole project.
    """
    mode = _v426_normalize_profile(selection)
    _V426_ROUTE.mode = mode
    _V426_ROUTE.repeat = {}
    _V426_ROUTE.last_target = ''
    _V426_ROUTE.last_reason = ''
    _V426_ROUTE.startup_failures = {}
    return mode


def clear_project_qwen_routing():
    for name in ('mode','repeat','last_target','last_reason','startup_failures'):
        try: delattr(_V426_ROUTE, name)
        except Exception: pass


def _v426_mode():
    mode = _v426_normalize_profile(getattr(_V426_ROUTE, 'mode', 'auto'))
    return mode if mode in {'auto','8b','9b35','27b38q2','27b'} else 'auto'


def _v426_repeat_key(stage):
    s = str(stage or '').lower()
    s = re.sub(r'\b\d+\s*/\s*\d+\b', '#/#', s)
    s = re.sub(r'\b(?:attempt|pass|round|retry)\s*\d+\b', lambda m: re.sub(r'\d+','#',m.group(0)), s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s[:220]


def _v426_record_stage(stage):
    key = _v426_repeat_key(stage)
    repeat = getattr(_V426_ROUTE, 'repeat', None)
    if not isinstance(repeat, dict):
        repeat = {}; _V426_ROUTE.repeat = repeat
    repeat[key] = int(repeat.get(key) or 0) + 1
    # Keep routing memory bounded across very long project runs.
    if len(repeat) > 96:
        for old in list(repeat)[:32]: repeat.pop(old, None)
    return repeat[key]


def _v426_auto_target(stage, call_profile, prompt):
    """Choose the cheapest model that is appropriate for this specific call."""
    stage_low = str(stage or '').lower()
    profile_low = str(call_profile or 'chat').lower()
    repeat_count = _v426_record_stage(stage)
    prompt_tokens = _qwen_estimated_tokens(str(prompt or ''))

    # Architecture is the highest-leverage place to spend the 27B reasoning budget.
    if profile_low == 'plan':
        return V426_AUTO_SPECIALIST, 'architecture/planning specialist'

    hard_markers = (
        'architecture collision', 'architect/debugger', 'ambiguous', 'subsystem',
        'reconcil', 'root cause', 'root-cause', 'global convergence', 'acceptance',
        'dependency closure', 'contract reconciliation', 'canonical provider',
        'provider-first', 'cross-component', 'integration failure', 'diagnos',
        'no progress', 'stalled', 'escalat', 'ownership collision',
    )
    if any(x in stage_low for x in hard_markers):
        return V426_AUTO_SPECIALIST, 'hard diagnostic/root-cause specialist'

    # A second pass on the same repair family is a signal that the fast worker did
    # not collapse the root cause. Promote before burning a whole night on leaves.
    if profile_low == 'repair' and repeat_count >= V426_REPEAT_PROMOTE_AT:
        return V426_AUTO_SPECIALIST, f'repeated repair family ({repeat_count} calls)'

    if profile_low in {'repair','audit','reasoning'} and prompt_tokens >= V426_HARD_PROMPT_TOKENS:
        return V426_AUTO_SPECIALIST, f'large coordinated context (~{prompt_tokens:,} tokens)'

    # Routine source emission and first-pass leaf repairs stay on the much faster 9B.
    return V426_AUTO_WORKER, 'fast routine worker'


def _v426_route_for_call(stage, call_profile, prompt):
    mode = _v426_mode()
    if mode != 'auto' or not V426_AUTO_ROUTING:
        # Explicit dropdown choices are strict locks. This includes the old 27B and 8B.
        return mode if mode != 'auto' else V426_AUTO_WORKER, 'manual strict model lock' if mode != 'auto' else 'AUTO routing disabled'
    return _v426_auto_target(stage, call_profile, prompt)


def _v426_switch_for_call(target, reason, progress_callback=None):
    from jarvis_v4240_repair import _STOP_EVENT, ProjectStopRequested
    def check_stop():
        if _STOP_EVENT.is_set():
            raise ProjectStopRequested('Stop requested while preparing the local model.')
    check_stop()
    mode = _v426_mode()
    # Enforce the dropdown lock even if a caller asks for a rescue peer directly.
    target = mode if mode != 'auto' else _v426_normalize_profile(target)
    if mode == 'auto' and target not in {V426_AUTO_WORKER, V426_AUTO_SPECIALIST}:
        target = V426_AUTO_WORKER
    if target not in {'8b','9b35','27b38q2','27b'}:
        target = V426_AUTO_WORKER
    candidates = [target]
    if mode == 'auto' and V426_AUTO_ROUTING:
        candidates.append(V426_AUTO_WORKER if target == V426_AUTO_SPECIALIST else V426_AUTO_SPECIALIST)
    failures = getattr(_V426_ROUTE, 'startup_failures', None)
    if not isinstance(failures, dict):
        failures = {}; _V426_ROUTE.startup_failures = failures
    errors = []
    for candidate in candidates:
        check_stop()
        # Reuse a live member even if an earlier startup failed and the user has
        # since started it successfully. Never override a healthy manual choice.
        if _v426_runtime_matches(candidate):
            failures.pop(candidate, None)
            _V426_ROUTE.last_target = candidate
            _V426_ROUTE.last_reason = reason
            return True, f'{candidate} already active'
        if mode == 'auto' and candidate in failures:
            errors.append(f'{candidate}: {failures[candidate]}')
            continue
        role = 'locked' if mode != 'auto' else ('specialist' if candidate == V426_AUTO_SPECIALIST else 'worker')
        _progress(progress_callback,
                  f'V42.63 {"AUTO" if mode == "auto" else "LOCKED"} model route: {candidate} — {reason}.',
                  stage='model_routing', model_profile=candidate, model_role=role)
        ok, detail = _v426_ensure_qwen_profile(
            candidate,
            progress=lambda message: _progress(progress_callback, message, stage='model_switch',
                                               model_profile=candidate, model_role=role),
            persist_selection=False,
            cancelled=_STOP_EVENT.is_set,
        )
        check_stop()
        if ok:
            failures.pop(candidate, None)
            _V426_ROUTE.last_target = candidate
            _V426_ROUTE.last_reason = reason if candidate == target else 'AUTO fallback: ' + reason
            return True, detail
        errors.append(f'{candidate}: {detail}')
        if mode == 'auto':
            failures[candidate] = str(detail)
            _progress(progress_callback,
                      f'AUTO startup for {candidate} failed: {detail}. This project will use its other model if available.',
                      stage='model_routing', model_profile=candidate)
    # Exhausted startup attempts are remembered for this project only. Repeating
    # a hard stage must not kill the healthy worker to retry the same failed load.
    return False, ('AUTO could not activate its available models: ' if mode == 'auto' else '') + '; '.join(errors)


def prepare_project_qwen_routing(selection='auto', progress_callback=None):
    """Capture the dropdown policy; actual stage routing chooses hard-work 27B.

    AUTO reuses a healthy pool member or starts the fast worker. This avoids a
    needless specialist load immediately before routine checkpoint/source work.
    Every explicit selection remains a strict lock for the whole project.
    """
    mode = configure_project_qwen_routing(selection)
    target = mode
    if mode == 'auto':
        current = _v426_active_profile()
        target = current if V426_AUTO_ROUTING and current in {V426_AUTO_WORKER, V426_AUTO_SPECIALIST} and qwen_status(timeout=1.2) else V426_AUTO_WORKER
    reason = 'initial ready model; subsequent calls use stage routing' if mode == 'auto' else 'manual strict model lock'
    return _v426_switch_for_call(target, reason, progress_callback)


_v426_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    target, reason = _v426_route_for_call(stage, profile, prompt)
    ok, detail = _v426_switch_for_call(target, reason, progress_callback)
    if not ok:
        return False, f'V42.6 model routing failed before {stage}: {detail}'
    body = str(prompt or '') + (
        '\n\nV42.6 HYBRID MODEL RULE: You are operating inside the same Jarvis universal software factory regardless of which local Qwen is active. '
        'All frozen requirements, skills, toolchain adapters, canonical ownership, sandbox/command broker, compiler-owned repair, build-debt ledger, real build/test evidence, and zero-debt publish gates remain authoritative. '
        'Do not change architecture merely because a different model handled an earlier or later stage; use the shared project state as the source of truth.'
    )
    return _v426_prev_qwen_call(body, progress_callback, str(stage or '').replace('V42.4','V42.6').replace('V42.3','V42.6'), profile=profile, **kwargs)


_v426_prev_release_identity = _v36_release_identity

def _v36_release_identity():
    data = dict(_v426_prev_release_identity() or {})
    data.update({
        'version':'V'+V426_VERSION,
        'engine':V426_ENGINE,
        'planner_mode':'auto-hybrid-9b-worker-new-27b38q2-specialist-v42.6',
        'auto_default':True,
        'auto_worker_profile':V426_AUTO_WORKER,
        'auto_specialist_profile':V426_AUTO_SPECIALIST,
        'legacy_27b_auto_eligible':False,
        'manual_model_selection_strict_lock':True,
        'repeat_repair_promote_at':V426_REPEAT_PROMOTE_AT,
        'hard_prompt_promote_tokens':V426_HARD_PROMPT_TOKENS,
        'shared_strategy_tools_skills_across_models':True,
    })
    return data


_v426_prev_progress = _progress

def _progress(callback, text=None, **fields):
    if text is not None:
        text = str(text).replace('V42.5','V42.6').replace('V42.4','V42.6')
    return _v426_prev_progress(callback, text, **fields)

# ============================================================
# V42.7 - HYBRID WATCHDOG RESCUE + ROLE-SPECIALIZED PLANNING
# ============================================================
# V42.6 proved the two-model AUTO pool works, but the 27B Q2 specialist can be
# substantially slower than the 9B worker on large strict-JSON serialization,
# especially when the hardware-fit llama.cpp slot is only ~6K context. V42.7
# therefore uses the 27B as an architect/adviser/root-cause specialist and keeps
# high-volume structured component-plan emission on the faster 9B worker.
#
# AUTO also gets one bounded cross-model rescue when a local call hits the hard
# watchdog. Manual dropdown selections remain strict and never cross-fallback.
from qwen_model_manager import _runtime_context_tokens as _v427_runtime_context_tokens

V427_VERSION = '42.7'
V427_ENGINE = 'hybrid-watchdog-rescue-role-specialized-planning'
V427_WATCHDOG_RESCUE = os.getenv('JARVIS_V427_WATCHDOG_RESCUE', '1').strip().lower() not in {'0','false','no','off'}
V427_27B_PLAN_TIMEOUT = max(360, int(os.getenv('JARVIS_V427_27B_PLAN_TIMEOUT', '720')))
V427_27B_REPAIR_TIMEOUT = max(360, int(os.getenv('JARVIS_V427_27B_REPAIR_TIMEOUT', '900')))
V427_27B_AUDIT_TIMEOUT = max(360, int(os.getenv('JARVIS_V427_27B_AUDIT_TIMEOUT', '900')))
V427_27B_GENERATE_TIMEOUT = max(360, int(os.getenv('JARVIS_V427_27B_GENERATE_TIMEOUT', '720')))
V427_SPECIALIST_CONTEXT_WARNING = max(4096, int(os.getenv('JARVIS_V427_SPECIALIST_CONTEXT_WARNING', '8192')))

_v427_prev_auto_target = _v426_auto_target

def _v426_auto_target(stage, call_profile, prompt):
    """V42.7 role split for AUTO.

    The 27B reasons about architecture; the 9B serializes large detailed component
    plans and ordinary implementation. This avoids asking a slow 6K-context 27B to
    emit thousands of strict JSON tokens when the 9B is both faster and proven at it.
    """
    stage_low = str(stage or '').lower()
    profile_low = str(call_profile or 'chat').lower()

    # Detailed per-component architecture is mostly schema-constrained serialization
    # after the 27B has already decided the high-level architecture. Keep it on 9B.
    detail_markers = (
        'component plan', 'component architecture', 'component-plan',
        'file plan serialization', 'manifest serialization',
    )
    if profile_low == 'plan' and any(x in stage_low for x in detail_markers):
        _v426_record_stage(stage)
        return V426_AUTO_WORKER, 'structured component-plan serializer'

    return _v427_prev_auto_target(stage, call_profile, prompt)


_v427_prev_profile_hard_timeout = _qwen_profile_hard_timeout

def _qwen_profile_hard_timeout(profile):
    """Keep watchdogs bounded, but give the slower 27B specialist realistic time."""
    try:
        active = _v426_active_profile()
    except Exception:
        active = ''
    if active == V426_AUTO_SPECIALIST:
        p = str(profile or 'generate').strip().lower()
        if p == 'repair': return V427_27B_REPAIR_TIMEOUT
        if p == 'audit': return V427_27B_AUDIT_TIMEOUT
        if p == 'plan': return V427_27B_PLAN_TIMEOUT
        return V427_27B_GENERATE_TIMEOUT
    return _v427_prev_profile_hard_timeout(profile)


def _v427_is_watchdog_failure(result):
    try:
        ok, payload = result
    except Exception:
        return False
    if ok:
        return False
    low = str(payload or '').lower()
    timeout = 'hard watchdog' in low or ('exceeded the configured' in low and 'minute' in low)
    context_failure = any(marker in low for marker in (
        'context window exceeded', 'context size exceeded', 'prompt is too long',
        'requested tokens exceed', 'exceeds the available context', 'context length exceeded',
    ))
    return timeout or context_failure


def _v427_other_auto_model(profile):
    return V426_AUTO_WORKER if _v426_normalize_profile(profile) == V426_AUTO_SPECIALIST else V426_AUTO_SPECIALIST


_v427_prev_qwen_call = _qwen_call

def _qwen_call(prompt, progress_callback=None, stage='Generating', profile='chat', **kwargs):
    """Run the V42.6 router, then rescue an AUTO watchdog once on the peer model."""
    result = _v427_prev_qwen_call(prompt, progress_callback, stage, profile=profile, **kwargs)
    if not V427_WATCHDOG_RESCUE or _v426_mode() != 'auto' or not _v427_is_watchdog_failure(result):
        return result

    first = _v426_normalize_profile(getattr(_V426_ROUTE, 'last_target', '') or _v426_active_profile())
    if first not in {V426_AUTO_WORKER, V426_AUTO_SPECIALIST}:
        first = V426_AUTO_SPECIALIST if str(profile).lower() in {'plan','audit'} else V426_AUTO_WORKER
    alternate = _v427_other_auto_model(first)
    label = 'new Qwen3.8 27B Q2_K_P specialist' if alternate == V426_AUTO_SPECIALIST else 'Qwen3.5 9B worker'
    _progress(
        progress_callback,
        f'V42.7 AUTO watchdog rescue: {first} exceeded its bounded call window during {stage}; retrying once on {label} instead of aborting the project.',
        stage='model_routing', model_profile=alternate, model_role=('specialist' if alternate == V426_AUTO_SPECIALIST else 'worker'),
    )
    switched, detail = _v426_switch_for_call(alternate, 'watchdog rescue for same call', progress_callback)
    if not switched:
        return False, f'{result[1]}\nV42.7 watchdog rescue could not activate {alternate}: {detail}'

    try:
        ctx = int(_v427_runtime_context_tokens(timeout=1.2) or 0)
    except Exception:
        ctx = 0
    if alternate == V426_AUTO_SPECIALIST and ctx and ctx < V427_SPECIALIST_CONTEXT_WARNING:
        _progress(
            progress_callback,
            f'V42.7 specialist context note: new 27B is hardware-fit at {ctx:,} live tokens; keeping this rescue focused and letting 9B handle high-volume structured emission.',
            stage='model_routing', model_profile=alternate,
        )

    rescue_body = str(prompt or '') + (
        '\n\nV42.7 WATCHDOG RESCUE RULE: The peer AUTO model timed out on this exact task. '
        'Continue from the same frozen requirements/project state; do not restart or redesign gratuitously. '
        'Be concise, satisfy the requested output schema exactly, and make the smallest complete decision/output needed to unblock the factory. '
        'All Jarvis skills, toolchains, ownership rules, sandbox/build evidence, progressive debt, compiler-owned repair, and final zero-debt acceptance remain authoritative.'
    )
    # Bypass the V42.6 router for the rescue so it cannot immediately switch back
    # to the model that just timed out. V42.4 and every earlier factory layer remain.
    rescued = _v426_prev_qwen_call(
        rescue_body,
        progress_callback,
        str(stage or '').replace('V42.6','V42.7').replace('V42.5','V42.7').replace('V42.4','V42.7'),
        profile=profile,
        **kwargs,
    )
    if rescued[0]:
        return rescued
    return False, f'{result[1]}\nV42.7 peer-model watchdog rescue also failed: {rescued[1]}'


_v427_prev_release_identity = _v36_release_identity

def _v36_release_identity():
    data = dict(_v427_prev_release_identity() or {})
    data.update({
        'version':'V'+V427_VERSION,
        'engine':V427_ENGINE,
        'planner_mode':'27b-architect-9b-structured-planner-with-watchdog-rescue-v42.7',
        'auto_default':True,
        'auto_worker_profile':V426_AUTO_WORKER,
        'auto_specialist_profile':V426_AUTO_SPECIALIST,
        'legacy_27b_auto_eligible':False,
        'manual_model_selection_strict_lock':True,
        'structured_component_plans_on_9b':True,
        'auto_cross_model_watchdog_rescue':V427_WATCHDOG_RESCUE,
        'auto_watchdog_rescue_attempts':1,
        'new_27b_plan_timeout_seconds':V427_27B_PLAN_TIMEOUT,
        'new_27b_repair_timeout_seconds':V427_27B_REPAIR_TIMEOUT,
        'new_27b_role':'architecture-adviser-root-cause-global-convergence',
        '9b_role':'structured-component-plans-routine-generation-first-pass-repair',
        'strict_zero_debt_publish_gate':True,
    })
    return data


_v427_prev_progress = _progress

def _progress(callback, text=None, **fields):
    if text is not None:
        text = str(text).replace('V42.6','V42.7').replace('V42.5','V42.7').replace('V42.4','V42.7')
    return _v427_prev_progress(callback, text, **fields)
# ============================================================
# V42.8 - CONTRACT GRAPH RECONCILIATION + SPECIALIST TAKEOVER
# ============================================================
# Provider-first repair assumes the frozen owner graph is coherent. A real GearTrack
# run proved that assumption can fail: an unrelated semantic file (category.ts) was
# selected as canonical owner of ToolCondition, so provider-first repair rotated among
# several mutually impossible providers without increasing accepted state. V42.8 makes
# the ownership graph itself repairable while keeping the zero-debt publish gate strict.
#
# Universal policy:
#   * accepted-state progress, not temporary drafts, determines whether a repair loop moves;
#   * exact semantic providers outrank prose/compatibility aliases;
#   * one non-aggregate file may not silently own multiple unrelated contracts;
#   * missing dedicated canonical providers may be inserted into the frozen plan;
#   * simple canonical entities/enums can be materialized deterministically;
#   * repeated provider rotation promotes to the NEW Qwen3.8 27B Q2_K_P in AUTO;
#   * after graph reconciliation, rebuild/retest evidence is authoritative again.
import copy as _v428_copy

V428_VERSION = '42.8'
V428_ENGINE = 'contract-graph-reconciliation-specialist-takeover'
V428_CONTRACT_GRAPH_RECONCILIATION = os.getenv('JARVIS_V428_CONTRACT_GRAPH_RECONCILIATION','1').strip().lower() not in {'0','false','no','off'}
V428_DETERMINISTIC_CONTRACTS = os.getenv('JARVIS_V428_DETERMINISTIC_CONTRACTS','1').strip().lower() not in {'0','false','no','off'}
V428_SPECIALIST_TAKEOVER = os.getenv('JARVIS_V428_SPECIALIST_TAKEOVER','1').strip().lower() not in {'0','false','no','off'}
V428_LOOP_VISITS = max(3, int(os.getenv('JARVIS_V428_LOOP_VISITS','3')))
V428_LOOP_DISTINCT = max(2, int(os.getenv('JARVIS_V428_LOOP_DISTINCT','2')))
V428_STATE_FILE = '.jarvis_build/V428_CONTRACT_GRAPH_STATE.json'
V428_AGGREGATE_STEMS = {'types','type','models','model','domain','entities','entity','enums','enum','contracts','contract','schema','schemas','shared','common'}
V428_DOMAIN_DIRS = {'contracts','contract','models','model','domain','entities','entity','enums','enum','types','type','schema','schemas'}
V428_NODE_ADAPTERS = {'node','react','vite','nextjs','vue','sveltekit','nuxt','angular','electron','react_native','expo','deno','bun'}


def _v428_norm_symbol(value):
    return re.sub(r'[^a-z0-9]+','',str(value or '').lower())


def _v428_snake(value):
    s=re.sub(r'([a-z0-9])([A-Z])',r'\1_\2',str(value or ''))
    s=re.sub(r'[^A-Za-z0-9]+','_',s).strip('_').lower()
    return s or 'contract'


def _v428_accepted_token(work):
    try:
        rows=(_v413_load_accepted(work).get('files') or {})
        payload=[(str(k),str((v or {}).get('sha256') or '')) for k,v in sorted(rows.items())]
        return hashlib.sha256(json.dumps(payload,separators=(',',':')).encode('utf-8')).hexdigest()[:20]
    except Exception:
        return ''


def _v428_state_path(work):
    return Path(work)/V428_STATE_FILE


def _v428_load_state(work):
    try:
        data=json.loads(_v428_state_path(work).read_text(encoding='utf-8',errors='replace'))
        return data if isinstance(data,dict) else {}
    except Exception:
        return {}


def _v428_save_state(work,data):
    p=_v428_state_path(work);p.parent.mkdir(parents=True,exist_ok=True)
    data=dict(data or {});data['updated_at']=_utc_stamp();data['version']='V'+V428_VERSION
    try:p.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    except Exception:pass


def _v428_component_for_scope(manifest,scope):
    comps=[x for x in (manifest or {}).get('components') or [] if isinstance(x,dict)]
    for c in comps:
        if str(c.get('id') or '')==str(scope or ''):
            return c
    # Scope may be root::adapter in older manifests.
    for c in comps:
        root=_v40_norm_rel(c.get('root')) or '.'
        adapter=_v361_normalize_component_adapter(c.get('toolchain_adapter'))
        if str(scope or '') in {root,f'{root}::{adapter}'}:
            return c
    return comps[0] if len(comps)==1 else {}


def _v428_adapter_ext(adapter,current=''):
    adapter=_v361_normalize_component_adapter(adapter)
    try: ext=_V423_SOURCE_EXT_BY_ADAPTER.get(adapter)
    except Exception: ext=None
    if ext:return ext
    if current and Path(current).suffix:return Path(current).suffix.lower()
    if adapter in V428_NODE_ADAPTERS:return '.ts'
    if adapter=='rust':return '.rs'
    if adapter=='python':return '.py'
    if adapter=='go':return '.go'
    if adapter in {'dotnet','wpf','winforms','fsharp'}:return '.cs'
    if adapter in {'java_maven','java_gradle'}:return '.java'
    if adapter in {'kotlin_gradle','android_gradle'}:return '.kt'
    if adapter in {'flutter','dart'}:return '.dart'
    if adapter in {'swiftpm','ios_xcode','macos_xcode'}:return '.swift'
    if adapter in {'cpp_cmake','cpp_make','qt_cmake','meson','xmake'}:return '.hpp'
    if adapter=='c_make':return '.h'
    return ''


def _v428_aggregate_provider(rel):
    return _v428_norm_symbol(Path(_v40_norm_rel(rel)).stem) in {_v428_norm_symbol(x) for x in V428_AGGREGATE_STEMS}


def _v428_scope_rows(manifest,scope):
    out=[]
    for item in (manifest or {}).get('files') or []:
        if isinstance(item,dict) and item.get('path') and _v38_component_scope(manifest,item.get('path'))==scope:
            out.append(item)
    return out


def _v428_exact_owner(rows,symbol,adapter=''):
    sym=_v428_norm_symbol(symbol); candidates=[]
    wanted_ext=_v428_adapter_ext(adapter)
    for item in rows:
        rel=_v40_norm_rel(item.get('path'));p=Path(rel)
        if _v428_norm_symbol(p.stem)!=sym:continue
        score=_v40_definition_mention_score(item,symbol)
        if wanted_ext and p.suffix.lower()==wanted_ext:score+=500
        candidates.append((score,rel))
    return sorted(candidates,key=lambda x:(-x[0],x[1].casefold()))[0][1] if candidates else ''


def _v428_standard_provider_dir(manifest,scope,current=''):
    comp=_v428_component_for_scope(manifest,scope);root=_v40_norm_rel((comp or {}).get('root')) or '.'
    adapter=_v361_normalize_component_adapter((comp or {}).get('toolchain_adapter'))
    cur=_v40_norm_rel(current)
    if cur and Path(cur).parent.name.lower() in V428_DOMAIN_DIRS:
        return Path(cur).parent.as_posix()
    rows=_v428_scope_rows(manifest,scope)
    wanted=_v428_adapter_ext(adapter,current)
    candidates=[]
    for item in rows:
        rel=_v40_norm_rel(item.get('path'));p=Path(rel)
        if p.parent.name.lower() in V428_DOMAIN_DIRS:
            score=100+(50 if wanted and p.suffix.lower()==wanted else 0)
            candidates.append((score,p.parent.as_posix()))
    if candidates:
        return sorted(candidates,key=lambda x:(-x[0],x[1]))[0][1]
    prefix='' if root=='.' else root.rstrip('/')+'/'
    if adapter=='rust':return prefix+'src/models'
    if adapter in V428_NODE_ADAPTERS:return prefix+'src/contracts'
    if adapter in {'python','python_desktop'}:return prefix+'src/models'
    if adapter=='go':return prefix+'internal/domain'
    if adapter in {'dotnet','wpf','winforms','fsharp'}:return prefix+'Models'
    if adapter in {'java_maven','java_gradle','kotlin_gradle','android_gradle'}:return prefix+'src/main'
    if adapter in {'flutter','dart'}:return prefix+'lib/models'
    if adapter in {'swiftpm','ios_xcode','macos_xcode'}:return prefix+'Sources/Models'
    return prefix+'src/domain'


def _v428_provider_filename(symbol,adapter,ext):
    adapter=_v361_normalize_component_adapter(adapter)
    if adapter in {'dotnet','wpf','winforms','fsharp','java_maven','java_gradle','kotlin_gradle','android_gradle','swiftpm','ios_xcode','macos_xcode','flutter','dart'}:
        return str(symbol)+ext
    return _v428_snake(symbol)+ext


def _v428_synth_provider_item(manifest,scope,symbol,spec,current=''):
    comp=_v428_component_for_scope(manifest,scope);adapter=_v361_normalize_component_adapter((comp or {}).get('toolchain_adapter'))
    ext=_v428_adapter_ext(adapter,current)
    if not ext:return None
    directory=_v428_standard_provider_dir(manifest,scope,current)
    rel=_v40_norm_rel(directory+'/'+_v428_provider_filename(symbol,adapter,ext))
    fields=[]
    if spec.get('kind')=='entity':
        fields=[str(f.get('name') or '') for f in (spec.get('raw') or {}).get('fields') or [] if isinstance(f,dict) and f.get('name')]
    values=list(spec.get('values') or [])
    shape=('fields: '+', '.join(fields)) if spec.get('kind')=='entity' else ('values: '+', '.join(values))
    return {
        'path':rel,
        'purpose':f'Canonical {spec.get("kind") or "domain"} provider for {symbol} in component {scope}.',
        'phase':'data', 'depends_on':[], 'exports':[symbol],
        'contracts':[
            f'V42.8 CANONICAL PROVIDER: define {symbol} exactly once in this component; consumers import/use it and must not redefine it.',
            f'Frozen canonical shape for {symbol}: {shape}.',
        ],
        'v428_contract_provider':True,'v428_symbol':symbol,
    }


def _v428_reconcile_contract_manifest(manifest,aggressive=False):
    """Repair contradictory canonical ownership in the plan itself.

    Non-aggressive mode fixes objective contradictions (exact provider exists, or one
    semantic file owns unrelated symbols). Aggressive mode is used only after an
    accepted-state loop and may insert a dedicated provider for a mismatched owner.
    """
    if not isinstance(manifest,dict):return manifest,[]
    m=_v428_copy.deepcopy(manifest)
    defs=_v40_domain_definitions(m)
    if not defs:return m,[]
    baseline=dict(_v428_prev_domain_owner_map(m) or {})
    forced=dict(m.get('_v428_forced_domain_owners') or {})
    files=[x for x in m.get('files') or [] if isinstance(x,dict) and x.get('path')]
    by_path={_v40_norm_rel(x.get('path')):x for x in files}
    provider_pairs={}
    for key,provider in baseline.items():provider_pairs.setdefault(_v40_norm_rel(provider),[]).append(key)
    changes=[];new_items=[];reexports=_v428_copy.deepcopy(m.get('_v428_compat_reexports') or {})
    for (scope,symbol),current in sorted(baseline.items(),key=lambda x:(str(x[0][0]),str(x[0][1]))):
        current=_v40_norm_rel(current);rows=_v428_scope_rows(m,scope);comp=_v428_component_for_scope(m,scope)
        adapter=_v361_normalize_component_adapter((comp or {}).get('toolchain_adapter'))
        exact=_v428_exact_owner(rows,symbol,adapter)
        desired=exact or current
        cur_stem=_v428_norm_symbol(Path(current).stem)
        sym=_v428_norm_symbol(symbol)
        owns_many=len(provider_pairs.get(current) or [])>1
        stem_is_other_symbol=any(cur_stem==_v428_norm_symbol(other) and _v428_norm_symbol(other)!=sym for other in defs)
        ext=_v428_adapter_ext(adapter,current)
        wrong_ext=bool(ext and Path(current).suffix.lower() and Path(current).suffix.lower()!=ext)
        contradictory=(owns_many and not _v428_aggregate_provider(current) and cur_stem!=sym) or stem_is_other_symbol or wrong_ext
        if not exact and (contradictory or (aggressive and cur_stem!=sym and not _v428_aggregate_provider(current))):
            item=_v428_synth_provider_item(m,scope,symbol,defs.get(symbol) or {},current)
            if item:
                desired=_v40_norm_rel(item.get('path'))
                if desired not in by_path:
                    new_items.append(item);by_path[desired]=item
                changes.append(f'{scope}:{symbol} {current or "NONE"} -> {desired}')
        elif exact and exact!=current:
            changes.append(f'{scope}:{symbol} {current or "NONE"} -> {exact}')
        if desired and current and desired!=current:
            rows=reexports.setdefault(current,[])
            if not any(str(x.get('symbol') or '')==symbol and _v40_norm_rel(x.get('provider'))==desired for x in rows if isinstance(x,dict)):
                rows.append({'symbol':symbol,'provider':desired})
        if desired:
            forced[f'{scope}||{symbol}']=desired
    if new_items:
        m['files']=files+new_items
        order=[_v40_norm_rel(x) for x in m.get('implementation_order') or [] if _v40_norm_rel(x)]
        # Canonical providers precede ordinary consumers. Dependency sorting may refine this later.
        prefix=[_v40_norm_rel(x.get('path')) for x in new_items]
        m['implementation_order']=prefix+[x for x in order if x not in prefix]
        active=list(m.get('_v39_active_paths') or [])
        for p in prefix:
            if p not in active:active.append(p)
        if active:m['_v39_active_paths']=active
    m['_v428_forced_domain_owners']=forced
    m['_v428_compat_reexports']=reexports
    # Remove explicit competing provider declarations/exports from non-owners.
    for item in m.get('files') or []:
        if not isinstance(item,dict):continue
        rel=_v40_norm_rel(item.get('path'));scope=_v38_component_scope(m,rel)
        item['exports']=[x for x in _normalize_export_contract(item.get('exports')) if forced.get(f'{scope}||{_v381_clean_symbol_name(x)}',rel)==rel]
        kept=[]
        for line in item.get('contracts') or []:
            text=str(line);drop=False
            for symbol in defs:
                owner=forced.get(f'{scope}||{symbol}')
                if not owner or owner==rel:continue
                if re.search(rf'(?i)\b(?:struct|class|record|interface|enum|type|owns?|defines?|canonical provider)\b[^.\n]{{0,120}}\b{re.escape(symbol)}\b',text):
                    drop=True;break
            if not drop:kept.append(line)
        item['contracts']=kept
    m['_v428_contract_graph_reconciled']=True
    m['_v428_contract_graph_changes']=changes[-80:]
    return m,changes


# The forced map is authoritative after V42.8 reconciliation. Exact semantic files
# are still preferred dynamically, so later plan merges cannot revive a weak owner.
_v428_prev_domain_owner_map = _v40_domain_owner_map

def _v40_domain_owner_map(manifest):
    owners=dict(_v428_prev_domain_owner_map(manifest) or {})
    m=manifest or {};defs=_v40_domain_definitions(m)
    forced=m.get('_v428_forced_domain_owners') or {}
    for key,provider in forced.items():
        if '||' not in str(key):continue
        scope,symbol=str(key).split('||',1)
        if provider:owners[(scope,symbol)]=_v40_norm_rel(provider)
    # Exact semantic providers always outrank compatibility/prose aliases.
    for (scope,symbol),current in list(owners.items()):
        comp=_v428_component_for_scope(m,scope);adapter=_v361_normalize_component_adapter((comp or {}).get('toolchain_adapter'))
        exact=_v428_exact_owner(_v428_scope_rows(m,scope),symbol,adapter)
        if exact:owners[(scope,symbol)]=exact
    return owners


def _v428_type_kind(raw):
    s=str(raw or '').strip().lower()
    if any(x in s for x in ('bool','boolean')):return 'bool'
    if any(x in s for x in ('float','double','decimal','number','real')):return 'float'
    if any(x in s for x in ('int','count','quantity','integer')):return 'int'
    if any(x in s for x in ('list','array','vec','collection','[]')):return 'list'
    return 'string'


def _v428_ts_type(raw):
    k=_v428_type_kind(raw)
    return {'bool':'boolean','float':'number','int':'number','list':'string[]'}.get(k,'string')


def _v428_rust_type(raw):
    k=_v428_type_kind(raw)
    return {'bool':'bool','float':'f64','int':'i64','list':'Vec<String>'}.get(k,'String')


def _v428_render_contract_source(manifest,provider):
    provider=_v40_norm_rel(provider);ext=Path(provider).suffix.lower();scope=_v38_component_scope(manifest,provider)
    defs=_v40_domain_definitions(manifest);owners=_v40_domain_owner_map(manifest)
    symbols=[s for s in defs if owners.get((scope,s))==provider]
    if not symbols:return ''
    chunks=[]
    if ext in {'.ts','.tsx'}:
        for symbol in symbols:
            spec=defs[symbol]
            if spec.get('kind')=='enum':
                vals=[]
                for raw in spec.get('values') or []:
                    key=re.sub(r'[^A-Za-z0-9_]','_',str(raw)).strip('_') or 'UNKNOWN'
                    if key[0].isdigit():key='_'+key
                    vals.append(f'  {key} = {json.dumps(str(raw))},')
                chunks.append(f'export enum {symbol} {{\n'+"\n".join(vals)+'\n}')
            else:
                lines=[]
                for f in (spec.get('raw') or {}).get('fields') or []:
                    if not isinstance(f,dict) or not f.get('name'):continue
                    opt='' if f.get('required',True) else '?'
                    lines.append(f'  {f.get("name")}{opt}: {_v428_ts_type(f.get("type"))};')
                chunks.append(f'export interface {symbol} {{\n'+"\n".join(lines)+'\n}')
        return '\n\n'.join(chunks)+'\n'
    if ext=='.rs':
        for symbol in symbols:
            spec=defs[symbol]
            if spec.get('kind')=='enum':
                vals=[]
                for raw in spec.get('values') or []:
                    key=re.sub(r'[^A-Za-z0-9_]','_',str(raw)).strip('_') or 'Unknown'
                    if key[0].isdigit():key='_'+key
                    vals.append('    '+key+',')
                chunks.append('#[derive(Debug, Clone, Copy, PartialEq, Eq)]\n'+f'pub enum {symbol} {{\n'+"\n".join(vals)+'\n}')
            else:
                lines=[]
                for f in (spec.get('raw') or {}).get('fields') or []:
                    if not isinstance(f,dict) or not f.get('name'):continue
                    typ=_v428_rust_type(f.get('type'))
                    if not f.get('required',True):typ=f'Option<{typ}>'
                    lines.append(f'    pub {f.get("name")}: {typ},')
                chunks.append('#[derive(Debug, Clone, PartialEq)]\n'+f'pub struct {symbol} {{\n'+"\n".join(lines)+'\n}')
        return '\n\n'.join(chunks)+'\n'
    if ext in {'.py','.pyw'}:
        imports=['from dataclasses import dataclass','from enum import Enum','from typing import Optional']
        chunks.append('\n'.join(imports))
        for symbol in symbols:
            spec=defs[symbol]
            if spec.get('kind')=='enum':
                vals=[]
                for raw in spec.get('values') or []:
                    key=re.sub(r'[^A-Za-z0-9_]','_',str(raw)).strip('_').upper() or 'UNKNOWN'
                    if key[0].isdigit():key='_'+key
                    vals.append(f'    {key} = {str(raw)!r}')
                chunks.append(f'class {symbol}(str, Enum):\n'+"\n".join(vals))
            else:
                lines=[]
                for f in (spec.get('raw') or {}).get('fields') or []:
                    if not isinstance(f,dict) or not f.get('name'):continue
                    k=_v428_type_kind(f.get('type'));typ={'bool':'bool','float':'float','int':'int','list':'list[str]'}.get(k,'str')
                    if not f.get('required',True):typ=f'Optional[{typ}]'
                    lines.append(f'    {f.get("name")}: {typ}')
                chunks.append('@dataclass\n'+f'class {symbol}:\n'+("\n".join(lines) if lines else '    pass'))
        return '\n\n'.join(chunks)+'\n'
    if ext=='.go':
        chunks=['package domain']
        for symbol in symbols:
            spec=defs[symbol]
            if spec.get('kind')=='enum':
                chunks.append(f'type {symbol} string\n\nconst (\n'+"\n".join(f'    {re.sub(r"[^A-Za-z0-9_]","_",str(v))} {symbol} = {json.dumps(str(v))}' for v in spec.get('values') or [])+'\n)')
            else:
                lines=[]
                for f in (spec.get('raw') or {}).get('fields') or []:
                    if not isinstance(f,dict) or not f.get('name'):continue
                    k=_v428_type_kind(f.get('type'));typ={'bool':'bool','float':'float64','int':'int64','list':'[]string'}.get(k,'string')
                    name=str(f.get('name'));name=name[:1].upper()+name[1:]
                    lines.append(f'    {name} {typ} `json:"{f.get("name")}"`')
                chunks.append(f'type {symbol} struct {{\n'+"\n".join(lines)+'\n}')
        return '\n\n'.join(chunks)+'\n'
    if ext=='.cs':
        for symbol in symbols:
            spec=defs[symbol]
            if spec.get('kind')=='enum':chunks.append('public enum '+symbol+' { '+', '.join(re.sub(r'[^A-Za-z0-9_]','_',str(v)) for v in spec.get('values') or [])+' }')
            else:
                lines=[]
                for f in (spec.get('raw') or {}).get('fields') or []:
                    if not isinstance(f,dict) or not f.get('name'):continue
                    k=_v428_type_kind(f.get('type'));typ={'bool':'bool','float':'double','int':'long','list':'List<string>'}.get(k,'string')
                    if typ.startswith('List'):pass
                    name=str(f.get('name'));name=name[:1].upper()+name[1:]
                    lines.append(f'    public {typ} {name} {{ get; set; }}')
                prefix='using System.Collections.Generic;\n\n' if any('List<' in x for x in lines) else ''
                chunks.append(prefix+f'public class {symbol}\n{{\n'+"\n".join(lines)+'\n}')
        return '\n\n'.join(chunks)+'\n'
    if ext in {'.h','.hpp'}:
        for symbol in symbols:
            spec=defs[symbol]
            if spec.get('kind')=='enum':chunks.append('enum class '+symbol+' { '+', '.join(re.sub(r'[^A-Za-z0-9_]','_',str(v)) for v in spec.get('values') or [])+' };')
            else:
                lines=[]
                for f in (spec.get('raw') or {}).get('fields') or []:
                    if not isinstance(f,dict) or not f.get('name'):continue
                    k=_v428_type_kind(f.get('type'));typ={'bool':'bool','float':'double','int':'long long','list':'std::vector<std::string>'}.get(k,'std::string')
                    lines.append(f'    {typ} {f.get("name")};')
                chunks.append('#include <string>\n#include <vector>\n\n'+f'struct {symbol} {{\n'+"\n".join(lines)+'\n};')
        return '\n\n'.join(chunks)+'\n'
    return ''


def _v428_commit_deterministic_provider(work,manifest,provider):
    if not V428_DETERMINISTIC_CONTRACTS:return False
    provider=_v40_norm_rel(provider);item=_manifest_file_item(manifest or {},provider)
    if not item:return False
    # Deterministic materialization is limited to pure domain-ish providers.
    low=provider.lower();purpose=str(item.get('purpose') or '').lower()
    if not (item.get('v428_contract_provider') or any('/'+d+'/' in '/'+low+'/' for d in V428_DOMAIN_DIRS)):
        return False
    if any(x in low or x in purpose for x in ('service','repository','controller','command','view','store','hook')):
        return False
    if _v413_is_accepted(work,provider) and not _v401_file_green_error(work,manifest or {},provider):
        return False
    source=_v428_render_contract_source(manifest,provider)
    if not source.strip():return False
    target=Path(work)/provider;snap=_v401_snapshot_file(target);accepted_before=_v413_is_accepted(work,provider)
    try:
        target.parent.mkdir(parents=True,exist_ok=True);target.write_text(source,encoding='utf-8')
        err=_v401_file_green_error(work,manifest or {},provider)
        if err:
            _v401_restore_file(target,snap)
            return False
        _v413_mark_accepted(work,provider,'v428_deterministic_contract_provider')
        _append_project_event(work,'v428_deterministic_provider_green',f'V42.8 deterministically materialized canonical provider {provider} from frozen domain contracts.',file=provider)
        return True
    except Exception:
        _v401_restore_file(target,snap)
        return False


def _v428_specialist_contract_audit(user_request,manifest,work,visits,reason,progress_callback=None):
    if not V428_SPECIALIST_TAKEOVER:return ''
    state=_v428_load_state(work);token=_v428_accepted_token(work)
    if token and token in (state.get('audited_tokens') or []):return str(state.get('last_specialist_audit') or '')
    payload={
        'canonical_domain_contracts':(manifest or {}).get('canonical_domain_contracts') or {},
        'owners':_v40_domain_owner_payload(manifest or {}).get('owners') or [],
        'provider_rotation':list(visits or [])[-12:],
        'reason':str(reason or '')[-3500:],
    }
    prompt=(
        'V42.8 CONTRACT-GRAPH ROOT-CAUSE AUDIT. READ ONLY. Several canonical provider repairs rotated without any new ACCEPTED repository revision. '
        'Audit the ownership graph itself, not leaf source. Identify contradictory owners, symbols assigned to semantically unrelated provider files, duplicate definitions, and the smallest corrected provider mapping. '
        'Do not write application code and do not weaken validation. Prefer one exact semantic owner per component/language; aggregate types/domain files are allowed only when intentional. '
        'Return a concise reconciliation brief under 700 words.\n\nEVIDENCE:\n'+json.dumps(payload,ensure_ascii=False,indent=2)[:22000]
    )
    _progress(progress_callback,'V42.8 contract graph stalled with no accepted-state progress; promoting root-cause ownership reconciliation to the new 27B specialist in AUTO.',stage='model_routing',model_profile='27b38q2',model_role='specialist')
    try:
        ok,text=_qwen_call(prompt,progress_callback,'V42.8 contract graph root-cause reconciliation',profile='audit',max_tokens=1400,thinking=False)
        brief=str(text or '') if ok else ''
    except Exception as exc:
        brief='specialist audit unavailable: '+str(exc)
    state=_v428_load_state(work);aud=list(state.get('audited_tokens') or [])
    if token and token not in aud:aud.append(token)
    state['audited_tokens']=aud[-20:];state['last_specialist_audit']=brief[-7000:];_v428_save_state(work,state)
    _append_project_event(work,'v428_specialist_contract_audit','V42.8 escalated a no-progress provider rotation to contract-graph/root-cause specialist analysis.',audit=brief[-5000:])
    return brief


def _v428_reconcile_live_contract_graph(user_request,manifest,work,progress_callback=None,reason=''):
    if not V428_CONTRACT_GRAPH_RECONCILIATION:return False
    state=_v428_load_state(work);visits=list(state.get('provider_visits') or [])
    brief=_v428_specialist_contract_audit(user_request,manifest,work,visits,reason,progress_callback)
    reconciled,changes=_v428_reconcile_contract_manifest(manifest,aggressive=True)
    if isinstance(manifest,dict):
        manifest.clear();manifest.update(reconciled)
    if changes:
        _append_project_event(work,'v428_contract_graph_reconciled','V42.8 repaired contradictory canonical ownership before further leaf repair.',changes=changes[-80:],specialist_audit=brief[-2500:])
        try:_v40_write_domain_owners(work,manifest)
        except Exception:pass
        try:_v33_write_architecture(work,manifest)
        except Exception:pass
    changed=bool(changes)
    # Materialize every currently unhealthy pure canonical provider once from the
    # frozen contracts. This breaks type/enum naming loops without model roulette.
    providers=[]
    for row in _v40_domain_owner_payload(manifest or {}).get('owners') or []:
        p=_v40_norm_rel(row.get('provider'))
        if p and p not in providers:providers.append(p)
    for p in providers:
        if _v424_provider_state_problem(work,manifest,p) and _v428_commit_deterministic_provider(work,manifest,p):changed=True
    if changed:
        try:_v36_build_repo_graph(work,manifest,write=True);_v36_build_contract_registry(work,manifest,write=True)
        except Exception:pass
        try:_v373_refresh_project_kb(work,manifest,reason='v428_contract_graph_reconciled',force=True)
        except Exception:pass
    state=_v428_load_state(work);state['provider_visits']=[];state['accepted_token']=_v428_accepted_token(work);state['last_reconciliation_at']=_utc_stamp();_v428_save_state(work,state)
    return changed


def _v428_register_provider_visit(work,manifest,provider):
    state=_v428_load_state(work);token=_v428_accepted_token(work)
    if state.get('accepted_token')!=token:
        state['accepted_token']=token;state['provider_visits']=[]
    visits=list(state.get('provider_visits') or []);visits.append(_v40_norm_rel(provider));visits=visits[-16:]
    state['provider_visits']=visits;_v428_save_state(work,state)
    distinct=len(set(visits[-V428_LOOP_VISITS:]))
    return len(visits)>=V428_LOOP_VISITS and distinct>=V428_LOOP_DISTINCT,visits


# Repair the plan at review and execution time before bad ownership can be frozen.
_v428_prev_review_project_plan=_review_project_plan

def _review_project_plan(user_request,manifest,max_files,progress_callback=None):
    result=_v428_prev_review_project_plan(user_request,manifest,max_files,progress_callback)
    reconciled,changes=_v428_reconcile_contract_manifest(result,aggressive=False)
    if changes:
        _progress(progress_callback,f'V42.8 reconciled {len(changes)} canonical ownership conflict(s) before implementation.',stage='architecting',percent=21)
    return reconciled


_v428_prev_execute_manifest=_v362_execute_manifest

def _v362_execute_manifest(user_request,manifest,work,max_files,progress_callback=None,raw_plan=''):
    reconciled,changes=_v428_reconcile_contract_manifest(dict(manifest or {}),aggressive=False)
    if changes:
        try:_append_project_event(work,'v428_preflight_contract_graph_reconciled','V42.8 corrected contradictory canonical owners before source generation.',changes=changes[-80:])
        except Exception:pass
    reconciled['version']='V'+V428_VERSION;reconciled['engine']=V428_ENGINE
    return _v428_prev_execute_manifest(user_request,reconciled,work,max_files,progress_callback,raw_plan)


# Intercept synthesized simple contract providers before spending a model call.
_v428_prev_generate_planned_file=_generate_planned_file

def _generate_planned_file(user_request,manifest,work,file_item,progress_callback=None):
    rel=_v40_norm_rel((file_item or {}).get('path'))
    if V428_DETERMINISTIC_CONTRACTS and (file_item or {}).get('v428_contract_provider'):
        if _v428_commit_deterministic_provider(work,manifest,rel):
            _progress(progress_callback,f'V42.8 deterministic canonical provider accepted: {rel}',stage='generating',current_file=rel)
            return True,rel
    return _v428_prev_generate_planned_file(user_request,manifest,work,file_item,progress_callback)


# Provider rotation detector: accepted revisions, not temporary candidates, are the
# progress clock. On no-progress rotation, reconcile graph + specialist before the
# next ordinary provider repair.
_v428_prev_repair_one_provider=_v424_repair_one_provider

def _v424_repair_one_provider(user_request,manifest,work,provider,progress_callback=None,reason=''):
    stalled,visits=_v428_register_provider_visit(work,manifest,provider)
    if stalled:
        if _v428_reconcile_live_contract_graph(user_request,manifest,work,progress_callback,reason=reason or ('provider rotation: '+', '.join(visits[-8:]))):
            if not _v424_provider_state_problem(work,manifest,provider):return True
            # Ownership may have moved away from this old provider entirely.
            provider_rows={_v40_norm_rel(x.get('provider')) for x in _v40_domain_owner_payload(manifest or {}).get('owners') or []}
            if _v40_norm_rel(provider) not in provider_rows:return True
    return _v428_prev_repair_one_provider(user_request,manifest,work,provider,progress_callback,reason)


# General TS2688 repair: a dependency package that ships module types must not be
# listed as a compiler global type-root. This includes the exact Tauri plugin debt
# observed behind the contract loop. Real global roots such as node/jest are left
# alone for dependency installation/normal diagnosis.
def _v428_package_base(type_name):
    s=str(type_name or '').strip()
    if s.startswith('@'):
        parts=s.split('/')
        return '/'.join(parts[:2]) if len(parts)>=2 else s
    return s.split('/')[0]


def _v428_repair_ts2688(work,manifest,failure):
    names=re.findall(r"Cannot find type definition file for\s*['\"]([^'\"]+)['\"]",str(failure or ''),re.I)
    if not names:return False
    protected={'node','jest','mocha','vitest','vitest/globals','vite/client'};changed=False
    for comp in [x for x in (manifest or {}).get('components') or [] if isinstance(x,dict)]:
        adapter=_v361_normalize_component_adapter(comp.get('toolchain_adapter'))
        if adapter not in V428_NODE_ADAPTERS:continue
        root=_v40_norm_rel(comp.get('root')) or '.';prefix='' if root=='.' else root.rstrip('/')+'/'
        pkg_path=Path(work)/(prefix+'package.json');ts_path=Path(work)/(prefix+'tsconfig.json')
        if not ts_path.exists():continue
        deps=set()
        try:
            pkg=json.loads(pkg_path.read_text(encoding='utf-8',errors='replace')) if pkg_path.exists() else {}
            deps=set((pkg.get('dependencies') or {}).keys())|set((pkg.get('devDependencies') or {}).keys())
        except Exception:pass
        try:data=_v412_tsconfig_load(ts_path)
        except Exception:data={}
        if not isinstance(data,dict):continue
        opts=data.setdefault('compilerOptions',{});types=list(opts.get('types') or []);kept=[];removed=[]
        for t in types:
            base=_v428_package_base(t)
            safe=(str(t).startswith('tauri-plugin-') or (base in deps and str(t) not in protected and not str(t).startswith('@types/')))
            if str(t) in names and safe:removed.append(str(t))
            else:kept.append(t)
        if removed:
            opts['types']=kept
            snap=_v401_snapshot_file(ts_path)
            try:
                ts_path.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
                rel=_v40_norm_rel(prefix+'tsconfig.json')
                err=_v401_file_green_error(work,manifest or {},rel)
                if err:_v401_restore_file(ts_path,snap)
                else:
                    _v413_mark_accepted(work,rel,'v428_ts2688_module_type_cleanup');changed=True
                    _append_project_event(work,'v428_ts2688_repaired',f'V42.8 removed invalid module package(s) from TypeScript global type roots: {", ".join(removed)}.',file=rel)
            except Exception:_v401_restore_file(ts_path,snap)
    return changed


