# V42.9 whole-project audit performance: dependency/build directories are part of
# the development workspace, not authored project source. A true project audit
# scans every planned/source file and every component, but must not recursively
# enumerate millions of files in node_modules/target/dist/caches.
_V429_PRUNE_DIRS = set(_ANALYSIS_IGNORE_DIRS) | {'.jarvis_runtime','.cache','coverage','.turbo','.parcel-cache','.angular','.svelte-kit','out','bin','obj'}


def _v429_pruned_walk(root):
    root=Path(root)
    for dirpath,dirnames,filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in _V429_PRUNE_DIRS and not d.startswith('.jarvis_tmp')]
        base=Path(dirpath)
        for name in filenames:yield base/name


def _existing_project_text_files(work):
    root=Path(work);files=[]
    for path in _v429_pruned_walk(root):
        try:rel=path.relative_to(root)
        except Exception:continue
        if rel.name.startswith('JARVIS_') or rel.as_posix()==RESUME_METADATA_FILE or _is_sensitive_project_rel(rel):continue
        if _looks_text_file(path):files.append(rel.as_posix())
    return sorted(files)


def _existing_real_source_files(work):
    root=Path(work);out=[]
    for path in _v429_pruned_walk(root):
        try:rel=path.relative_to(root)
        except Exception:continue
        try:size=path.stat().st_size
        except Exception:size=0
        if size>0 and _is_real_source_rel(rel):out.append(rel.as_posix())
    return sorted(out)


def _v429_pruned_find(root,name=None,suffix=None):
    low_name=str(name or '').lower();low_suffix=str(suffix or '').lower()
    for path in _v429_pruned_walk(root):
        n=path.name.lower()
        if low_name and n==low_name:return path
        if low_suffix and n.endswith(low_suffix):return path
    return None


def _v34_toolchain_structure_issues(work,manifest):
    root=Path(work);adapter=str((manifest or {}).get('toolchain_adapter') or _v34_infer_toolchain('',manifest,root));issues=[]
    package=_v429_pruned_find(root,name='package.json');cmake=_v429_pruned_find(root,name='cmakelists.txt');cargo=_v429_pruned_find(root,name='cargo.toml');gomod=_v429_pruned_find(root,name='go.mod')
    gradle=next((x for x in (_v429_pruned_find(root,name='settings.gradle.kts'),_v429_pruned_find(root,name='settings.gradle'),_v429_pruned_find(root,name='build.gradle.kts'),_v429_pruned_find(root,name='build.gradle')) if x),None)
    pom=_v429_pruned_find(root,name='pom.xml');pub=_v429_pruned_find(root,name='pubspec.yaml');swiftpm=_v429_pruned_find(root,name='package.swift');uproject=_v429_pruned_find(root,suffix='.uproject')
    if adapter in {'node','react','vite','nextjs','vue','angular','sveltekit','svelte','electron','react_native','expo','typescript','javascript'} and not package:issues.append({'file':'package.json','problem':'Selected JavaScript/TypeScript toolchain requires package.json with runnable scripts.','kind':'toolchain'})
    if adapter=='static_web' and not _v429_pruned_find(root,name='index.html'):issues.append({'file':'index.html','problem':'Static web project requires a real index.html entrypoint.','kind':'toolchain'})
    if adapter in {'cpp_cmake','qt_cmake','fortran_cmake','cuda_cmake'} and not cmake:issues.append({'file':'CMakeLists.txt','problem':'Selected CMake toolchain requires CMakeLists.txt.','kind':'toolchain'})
    if adapter in {'rust','tauri','wasm_rust'} and not cargo:issues.append({'file':'Cargo.toml','problem':'Rust project requires Cargo.toml.','kind':'toolchain'})
    if adapter=='go' and not gomod:issues.append({'file':'go.mod','problem':'Go module project requires go.mod.','kind':'toolchain'})
    if adapter in {'dotnet','wpf','winforms','fsharp'} and not (_v429_pruned_find(root,suffix='.sln') or _v429_pruned_find(root,suffix='.csproj') or _v429_pruned_find(root,suffix='.fsproj')):issues.append({'file':'','problem':'.NET project requires a project/solution build target.','kind':'toolchain'})
    if adapter in {'java_gradle','kotlin_gradle','android_gradle'} and not gradle:issues.append({'file':'build.gradle.kts','problem':'Gradle-selected project requires Gradle settings/build files or wrapper.','kind':'toolchain'})
    if adapter=='java_maven' and not pom:issues.append({'file':'pom.xml','problem':'Maven-selected Java project requires pom.xml.','kind':'toolchain'})
    if adapter=='android_gradle' and not _v429_pruned_find(root,name='androidmanifest.xml'):issues.append({'file':'app/src/main/AndroidManifest.xml','problem':'Android project requires AndroidManifest.xml.','kind':'toolchain'})
    if adapter in {'flutter','dart'} and not pub:issues.append({'file':'pubspec.yaml','problem':'Dart/Flutter project requires pubspec.yaml.','kind':'toolchain'})
    if adapter=='swiftpm' and not swiftpm:issues.append({'file':'Package.swift','problem':'Swift Package project requires Package.swift.','kind':'toolchain'})
    if adapter in {'ios_xcode','macos_xcode'} and not (_v429_pruned_find(root,suffix='.xcodeproj') or _v429_pruned_find(root,suffix='.xcworkspace') or _v429_pruned_find(root,name='project.yml')):issues.append({'file':'project.yml','problem':'Native Apple project requires an Xcode project/workspace or reproducible project.yml specification.','kind':'toolchain'})
    if adapter=='unreal':
        if not uproject:issues.append({'file':'','problem':'Unreal project requires a .uproject descriptor.','kind':'toolchain'})
        if not _v429_pruned_find(root,suffix='.build.cs'):issues.append({'file':'','problem':'Unreal project requires at least one module Build.cs file.','kind':'toolchain'})
    if adapter=='unity' and not (root/'ProjectSettings'/'ProjectVersion.txt').exists():issues.append({'file':'ProjectSettings/ProjectVersion.txt','problem':'Unity project requires ProjectSettings/ProjectVersion.txt.','kind':'toolchain'})
    if adapter=='php_composer' and not _v429_pruned_find(root,name='composer.json'):issues.append({'file':'composer.json','problem':'Composer-selected PHP project requires composer.json.','kind':'toolchain'})
    if adapter in {'ruby_bundler','rails'} and not _v429_pruned_find(root,name='gemfile'):issues.append({'file':'Gemfile','problem':'Bundler-selected Ruby project requires Gemfile.','kind':'toolchain'})
    return issues


def _v429_fast_provider_problem(work,manifest,provider):
    provider=_v40_norm_rel(provider);item=_manifest_file_item(manifest or {},provider)
    if not item:return ''
    p=Path(work)/provider
    if not p.exists() or not p.is_file():return 'canonical provider is missing from the workspace'
    if not _v413_is_accepted(work,provider):return 'canonical provider exists only as an unaccepted/rejected revision'
    if not _v39_file_is_implemented(work,provider):return 'canonical provider is still a skeleton/incomplete implementation'
    # Fast direct definition check. Cross-file conflicts are already collected once
    # by the consolidated deterministic audit instead of recursively re-running it
    # for every provider.
    try:text=p.read_text(encoding='utf-8',errors='replace')
    except Exception:return 'canonical provider could not be read'
    owners=[x for x in _v40_domain_owner_payload(manifest or {}).get('owners') or [] if _v40_norm_rel(x.get('provider'))==provider]
    for row in owners:
        sym=str(row.get('symbol') or '').strip()
        if not sym:continue
        pat=rf'(?m)\b(?:class|struct|enum|interface|type|record|trait)\s+{re.escape(sym)}\b'
        export_pat=rf'(?m)\b(?:export\s+)?(?:type|interface|class|enum)\s+{re.escape(sym)}\b'
        if not (re.search(pat,text) or re.search(export_pat,text)):
            return f'canonical provider does not define required symbol {sym}'
    return ''
# =============================================================================
# V42.10 ENDGAME CONVERGENCE + TEST-DEBT SELF-ACCEPTANCE + TRUE WHOLE-PROJECT AUDIT
# =============================================================================
# V42.9 reached the final 5-10% of real projects but exposed an endgame deadlock:
# a requirement-debt owner (especially a test file) could be rejected because the
# very requirement it was intended to satisfy was not already satisfied.  V42.10
# makes candidate evaluation self-consistent without weakening final acceptance.
# It also closes conventional test/config substrate, forces real Rust module
# reachability, avoids fake npx compiler installs, and validates every component on
# every whole-project convergence round so one subsystem cannot hide another.

V4210_VERSION = '42.10'
V4210_ENGINE = 'endgame-self-accepting-tests-true-whole-project-convergence'
V4210_STATE_FILE = '.jarvis_build/V4210_ENDGAME_STATE.json'
V4210_SELF_DEBT_ACCEPTANCE = os.getenv('JARVIS_V4210_SELF_DEBT_ACCEPTANCE','1').strip().lower() not in {'0','false','no','off'}
V4210_TEST_SUBSTRATE = os.getenv('JARVIS_V4210_TEST_SUBSTRATE','1').strip().lower() not in {'0','false','no','off'}
V4210_CONVENTIONAL_CONFIGS = os.getenv('JARVIS_V4210_CONVENTIONAL_CONFIGS','1').strip().lower() not in {'0','false','no','off'}
V4210_RUST_MODULE_CLOSURE = os.getenv('JARVIS_V4210_RUST_MODULE_CLOSURE','1').strip().lower() not in {'0','false','no','off'}
V4210_TRUE_WHOLE_AUDIT = os.getenv('JARVIS_V4210_TRUE_WHOLE_AUDIT','1').strip().lower() not in {'0','false','no','off'}
V4210_TEST_FALLBACK_AFTER = max(2, min(5, int(os.getenv('JARVIS_V4210_TEST_FALLBACK_AFTER','2'))))


def _v4210_state_path(work):
    return Path(work)/V4210_STATE_FILE


def _v4210_load_state(work):
    try:
        obj=json.loads(_v4210_state_path(work).read_text(encoding='utf-8',errors='replace'))
        return obj if isinstance(obj,dict) else {}
    except Exception:return {}


def _v4210_save_state(work,data):
    p=_v4210_state_path(work);p.parent.mkdir(parents=True,exist_ok=True)
    payload=dict(data or {});payload.update({'version':'V'+V4210_VERSION,'engine':V4210_ENGINE,'updated_at':_utc_stamp()})
    try:p.write_text(json.dumps(payload,indent=2,ensure_ascii=False,default=str)+'\n',encoding='utf-8')
    except Exception:pass


def _v4210_item(manifest,rel):
    try:return _manifest_file_item(manifest or {},_v40_norm_rel(rel)) or {}
    except Exception:return {}


def _v4210_is_requirement_owner(manifest,rel,gap=''):
    item=_v4210_item(manifest,rel);owned=str(item.get('v423_requirement_debt') or '').strip().lower()
    if not owned:return False
    return not gap or owned==str(gap).strip().lower()


# -----------------------------------------------------------------------------
# 1) Requirement-debt owner self-acceptance.
# During evaluation of THE OWNER FILE, ignore only the circular "owner is not yet
# implemented" issue. Final deterministic acceptance is unchanged and still sees
# the debt if the file never becomes a real accepted implementation.
# -----------------------------------------------------------------------------
_v4210_prev_current_file_foundation_issues=_v361_current_file_foundation_issues

def _v361_current_file_foundation_issues(work,manifest,rel):
    rows=list(_v4210_prev_current_file_foundation_issues(work,manifest,rel) or [])
    if not V4210_SELF_DEBT_ACCEPTANCE:return rows
    rel=_v40_norm_rel(rel);item=_v4210_item(manifest,rel);gap=str(item.get('v423_requirement_debt') or '').strip()
    if not gap:return rows
    out=[]
    for row in rows:
        problem=str((row or {}).get('problem') or '')
        file_rel=_v40_norm_rel((row or {}).get('file') or rel)
        circular=(file_rel==rel and problem.lower().startswith('v42.3 requirement debt unresolved:') and gap.lower() in problem.lower())
        if circular:
            try:_append_project_event(work,'v4210_self_debt_candidate_allowed',f'V42.10 allowed {rel} to be evaluated as the implementation that can satisfy its own {gap} requirement debt; final acceptance remains strict.',file=rel,requirement_gap=gap)
            except Exception:pass
            continue
        out.append(row)
    return out


# -----------------------------------------------------------------------------
# 2) Test prompts must use production contracts, never clone them locally.
# -----------------------------------------------------------------------------
_v4210_prev_focused_file_request=_v37_focused_file_request

def _v37_focused_file_request(user_request,manifest,work,file_item):
    text=_v4210_prev_focused_file_request(user_request,manifest,work,file_item)
    rel=_v40_norm_rel((file_item or {}).get('path'))
    if rel and _v38_is_testish(rel):
        scope=_v38_component_scope(manifest,rel);owners=[]
        for row in _v40_domain_owner_payload(manifest or {}).get('owners') or []:
            if str(row.get('scope') or '')!=str(scope):continue
            owners.append({'symbol':row.get('symbol'),'kind':row.get('kind'),'provider':row.get('provider')})
        text += (
            '\n\nV42.10 TEST-OWNER RULE: This test file is itself allowed to satisfy the tests requirement. '
            'Do NOT wait for the tests requirement to already be green. Do NOT redeclare/copy production domain structs, interfaces, enums, records, DTOs, schemas, or models inside a test. '
            'Import/use the canonical production providers below. Exercise production behavior through public functions/modules where possible. '
            'Include meaningful assertions; a comment, TODO, empty test, or local fake copy of production models is not acceptable. '
            'If production visibility/module wiring blocks the test, describe/use the intended public module path rather than cloning the type locally.\n'
            'CANONICAL PROVIDERS FOR THIS COMPONENT:\n'+json.dumps(owners[:40],ensure_ascii=False,indent=2)
        )
    return text


# -----------------------------------------------------------------------------
# 3) Close testing substrate at plan time. Tests need a runner, not just a file.
# -----------------------------------------------------------------------------
def _v4210_component_has_tests(manifest,comp):
    try:rows=_v422_component_rows(manifest,comp)
    except Exception:rows=[]
    for row in rows:
        rel=_v40_norm_rel(row.get('path'))
        if _v38_is_testish(rel) or str(row.get('v423_requirement_debt') or '').lower()=='tests' or str(row.get('phase') or '').lower()=='test':return True
    return False


def _v4210_add_manifest_file(manifest,path,purpose,phase='test',depends=None):
    rows=manifest.setdefault('files',[]);path=_v40_norm_rel(path)
    if any(_v40_norm_rel(x.get('path'))==path for x in rows if isinstance(x,dict)):return False
    rows.append({'path':path,'purpose':purpose,'phase':phase,'depends_on':list(depends or []),'exports':[],'contracts':[]})
    return True


def _v4210_close_test_substrate_plan(manifest):
    if not isinstance(manifest,dict) or not V4210_TEST_SUBSTRATE:return manifest
    m=dict(manifest);m['files']=[dict(x) for x in manifest.get('files') or [] if isinstance(x,dict)]
    for comp in [x for x in m.get('components') or [] if isinstance(x,dict)]:
        if not _v4210_component_has_tests(m,comp):continue
        adapter=_v361_normalize_component_adapter(comp.get('toolchain_adapter'));root=_v422_component_root(comp)
        if adapter in _V422_NODE_ADAPTERS:
            if not str(comp.get('test_command') or '').strip():comp['test_command']='npm test'
            if adapter in _V422_VITE_ADAPTERS or adapter in {'react','vite'}:
                target=_v422_join(root,'vitest.config.ts')
                _v4210_add_manifest_file(m,target,'Vitest test-runner configuration for real automated component tests','test',[_v422_join(root,'vite.config.ts')])
        elif adapter in {'rust','tauri'}:
            if not str(comp.get('test_command') or '').strip():comp['test_command']='cargo test'
        else:
            # Use adapter registry knowledge when the planner forgot a test command.
            if not str(comp.get('test_command') or '').strip():
                try:
                    default=str((_v34_toolchain_catalog().get(adapter) or {}).get('test_command') or '').strip()
                    if default:comp['test_command']=default
                except Exception:pass
    return m


# Apply test substrate before implementation begins.
_v4210_prev_execute_manifest=_v362_execute_manifest

def _v362_execute_manifest(user_request,manifest,work,max_files,progress_callback=None,raw_plan=''):
    m=_v4210_close_test_substrate_plan(dict(manifest or {}))
    return _v4210_prev_execute_manifest(user_request,m,work,max_files,progress_callback,raw_plan)


