def _v4210_harden_node_test_package(work,manifest,component):
    if not V4210_TEST_SUBSTRATE or not _v4210_component_has_tests(manifest,component):return False
    adapter=_v361_normalize_component_adapter(component.get('toolchain_adapter'))
    if adapter not in _V422_NODE_ADAPTERS:return False
    rel=_v422_join(_v422_component_root(component),'package.json');p=Path(work)/rel
    if not p.exists():return False
    try:data=json.loads(p.read_text(encoding='utf-8',errors='replace'))
    except Exception:return False
    scripts=data.setdefault('scripts',{});dev=data.setdefault('devDependencies',{});changed=False
    if not str(scripts.get('test') or '').strip():scripts['test']='vitest run';changed=True
    wanted={'vitest':'^2.1.0','jsdom':'^25.0.0'}
    if adapter=='react':wanted.update({'@testing-library/react':'^16.0.0','@testing-library/jest-dom':'^6.6.0'})
    for name,ver in wanted.items():
        if name not in dev:dev[name]=ver;changed=True
    if changed:
        p.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
        if not _v401_file_green_error(work,manifest,rel):_v413_mark_accepted(work,rel,'v4210_test_runner_substrate')
        try:_append_project_event(work,'v4210_test_runner_substrate','V42.10 closed JavaScript/TypeScript test-runner substrate before acceptance.',file=rel,component=component.get('id'))
        except Exception:pass
    return changed


_v4210_prev_prepare_component_substrate=_v422_prepare_component_substrate

def _v422_prepare_component_substrate(work,manifest,component):
    changed=bool(_v4210_prev_prepare_component_substrate(work,manifest,component))
    changed=_v4210_harden_node_test_package(work,manifest,component) or changed
    return changed


# -----------------------------------------------------------------------------
# 6) Rust module reachability: cargo check must compile ALL planned production
# modules, not only an empty crate root shell.
# -----------------------------------------------------------------------------
def _v4210_rust_top_modules(manifest,component):
    root=_v422_component_root(component);prefix='' if root=='.' else root.rstrip('/')+'/'
    src_prefix=prefix+'src/';mods=set()
    try:rows=_v422_component_rows(manifest,component)
    except Exception:rows=[]
    for row in rows:
        rel=_v40_norm_rel(row.get('path'))
        if not rel.startswith(src_prefix) or not rel.endswith('.rs'):continue
        sub=rel[len(src_prefix):]
        parts=sub.split('/')
        if len(parts)==1:
            stem=Path(parts[0]).stem
            if stem not in {'lib','main','build'} and re.match(r'^[A-Za-z_][A-Za-z0-9_]*$',stem):mods.add(stem)
        elif parts[-1]=='mod.rs':
            stem=parts[0]
            if re.match(r'^[A-Za-z_][A-Za-z0-9_]*$',stem):mods.add(stem)
    return sorted(mods)


def _v4210_harden_rust_crate_root(work,manifest,component):
    if not V4210_RUST_MODULE_CLOSURE:return False
    adapter=_v361_normalize_component_adapter(component.get('toolchain_adapter'))
    if adapter not in {'rust','tauri'}:return False
    root=_v422_component_root(component);rel=_v422_join(root,'src/lib.rs');p=Path(work)/rel
    if not p.exists():return False
    mods=_v4210_rust_top_modules(manifest,component)
    if not mods:return False
    try:text=p.read_text(encoding='utf-8',errors='replace')
    except Exception:return False
    missing=[m for m in mods if not re.search(rf'(?m)^\s*pub\s+mod\s+{re.escape(m)}\s*;',text)]
    if not missing:return False
    lines=[f'pub mod {m};' for m in missing]
    # Preserve crate-level attributes at the very top, insert modules before code.
    pos=0
    attrs=list(re.finditer(r'(?m)^#!\[[^\n]+\]\s*\n?',text))
    if attrs:pos=attrs[-1].end()
    new=text[:pos]+('' if pos==0 or text[:pos].endswith('\n') else '\n')+'\n'.join(lines)+'\n\n'+text[pos:]
    old=text;p.write_text(new,encoding='utf-8')
    err=_content_validation_error(rel,new)
    if err:
        p.write_text(old,encoding='utf-8');return False
    _v413_mark_accepted(work,rel,'v4210_rust_module_reachability')
    try:_append_project_event(work,'v4210_rust_module_reachability','V42.10 exposed every planned top-level Rust production module through the crate root so cargo check/test validates real authored code.',file=rel,modules=missing,component=component.get('id'))
    except Exception:pass
    return True


# Harden all component substrate immediately before any component validator runs.
_v4210_prev_validate_component=_v35_validate_component

def _v35_validate_component(work,manifest,component,user_request=''):
    try:_v422_prepare_component_substrate(work,manifest or {},component or {})
    except Exception:pass
    try:_v4210_harden_rust_crate_root(work,manifest or {},component or {})
    except Exception:pass
    return _v4210_prev_validate_component(work,manifest,component,user_request)


# -----------------------------------------------------------------------------
# 7) Live TypeScript diagnostics use the project's compiler. Never let npx download
# the unrelated deprecated package named "tsc". Restore dependencies once if needed.
# -----------------------------------------------------------------------------
_v4210_prev_live_component_command=_v429_live_component_command

def _v429_live_component_command(work,manifest,comp):
    if isinstance(comp,dict):
        adapter=_v361_normalize_component_adapter(comp.get('toolchain_adapter'));root=_v40_norm_rel(comp.get('root')) or '.';cwd=Path(work) if root=='.' else Path(work)/root
        if adapter in _V422_NODE_ADAPTERS and (cwd/'tsconfig.json').exists():
            local=cwd/'node_modules'/'.bin'/('tsc.cmd' if os.name=='nt' else 'tsc')
            if not local.exists():
                dep='npm ci --no-audit --no-fund' if (cwd/'package-lock.json').exists() else 'npm install --no-audit --no-fund'
                _progress(None,f'V42.10 live diagnostics preparing local TypeScript dependencies for {comp.get("id") or root}.',stage='V42.10 dependency restore')
                ok,out=_run_command(dep,cwd,max(120,V429_LIVE_REAL_TIMEOUT*2))
                try:_append_project_event(work,'v4210_live_dependency_restore',f'V42.10 dependency restore {"passed" if ok else "failed"} before local TypeScript diagnostics.',component=comp.get('id'),output=str(out or '')[-3000:])
                except Exception:pass
            if local.exists():return [str(local),'--noEmit','--pretty','false','-p','tsconfig.json'],cwd
            return None,cwd
    return _v4210_prev_live_component_command(work,manifest,comp)


# -----------------------------------------------------------------------------
# 8) Test quality + real test command are final acceptance evidence.
# -----------------------------------------------------------------------------
_v4210_prev_deterministic_acceptance_issues=_deterministic_acceptance_issues

def _deterministic_acceptance_issues(work,manifest):
    issues=list(_v4210_prev_deterministic_acceptance_issues(work,manifest) or []);seen={(str(x.get('file') or ''),str(x.get('problem') or '')) for x in issues}
    def add(rel,kind,problem):
        key=(rel,problem)
        if key not in seen:seen.add(key);issues.append({'file':rel,'kind':kind,'problem':problem})
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item,dict):continue
        rel=_v40_norm_rel(item.get('path'))
        if not rel or not (_v38_is_testish(rel) or str(item.get('v423_requirement_debt') or '').lower()=='tests'):continue
        p=Path(work)/rel
        if not p.exists() or not _v413_is_accepted(work,rel):continue
        try:text=p.read_text(encoding='utf-8',errors='replace')
        except Exception:text=''
        ext=p.suffix.lower();has_assert=bool(re.search(r'(?:\bassert!?\s*\(|\bexpect\s*\(|\bassert_eq!?\s*\(|\bassert_ne!?\s*\(|\bassertTrue\s*\(|\bassertEqual\s*\()',text))
        has_test=bool(re.search(r'(?m)(?:#\[test\]|\bdescribe\s*\(|\bit\s*\(|\btest\s*\(|\bdef\s+test_|@Test\b|\[Fact\]|\bfunc\s+Test[A-Z])',text))
        has_prod_ref=False
        if ext in {'.ts','.tsx','.js','.jsx'}:has_prod_ref=bool(re.search(r'(?m)^\s*import\s+.*(?:\.\./|\.\./\.\./|/src/)',text))
        elif ext=='.rs':has_prod_ref=bool(re.search(r'(?m)(?:#\[path\s*=\s*"\.\./src/|\buse\s+[A-Za-z_][A-Za-z0-9_]*::)',text))
        else:has_prod_ref=bool(re.search(r'(?m)\b(?:import|from|using|require)\b',text))
        if not (has_test and has_assert and has_prod_ref):add(rel,'test_quality','V42.10 test quality gate: acceptance/integration test must execute a real test, contain an assertion, and reference production code/contracts rather than local fake models.')
    # If tests are planned in a component, the component must have a runnable test command.
    for comp in [x for x in (manifest or {}).get('components') or [] if isinstance(x,dict)]:
        if _v4210_component_has_tests(manifest,comp) and (not str(comp.get('test_command') or '').strip() or _v35_is_noop_command(str(comp.get('test_command') or ''))):
            add(_v40_norm_rel(comp.get('root')),'test_substrate',f'V42.10 test substrate gate: component {comp.get("id") or comp.get("root")} has planned tests but no runnable native test command.')
    return issues


# -----------------------------------------------------------------------------
# 9) TRUE whole-project convergence: every round validates every independently
# discovered component, not just the first one or only after static issues shrink.
# -----------------------------------------------------------------------------
def _v429_whole_project_convergence(user_request,manifest,work,progress_callback=None):
    if not V429_WHOLE_PROJECT_AUDIT:return True,[]
    last_signature='';no_progress=0
    for round_no in range(1,V429_AUDIT_ROUNDS+1):
        _progress(progress_callback,f'V42.10 whole-project audit round {round_no}/{V429_AUDIT_ROUNDS}: checking every planned file/provider AND every component build/test path.',stage='V42.10 true whole-project audit',percent=min(94,80+round_no*2))
        audit=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
        if audit.get('clean'):
            _append_project_event(work,'v4210_whole_project_green','V42.10 whole-project audit found zero unresolved static/provider/component/test issues.',round=round_no)
            return True,[]
        token_before=_v429_progress_token(work)
        sig=hashlib.sha256(json.dumps([_v429_issue_key(x) for x in audit.get('issues') or []],sort_keys=True,default=str).encode()).hexdigest()[:20]
        if sig==last_signature:no_progress+=1
        else:no_progress=0;last_signature=sig
        if no_progress>=1:_v429_specialist_whole_audit(user_request,manifest,work,audit,progress_callback,reason=f'V42.10 full-audit signature repeated on round {round_no}')
        changed=_v429_repair_audit_round(user_request,manifest,work,audit,progress_callback,round_no)
        # Keep conventional substrate/module reachability repaired between rounds.
        for comp in [x for x in (manifest or {}).get('components') or [] if isinstance(x,dict)]:
            try:changed=_v422_prepare_component_substrate(work,manifest,comp) or changed
            except Exception:pass
            try:changed=_v4210_harden_rust_crate_root(work,manifest,comp) or changed
            except Exception:pass
        token_after=_v429_progress_token(work)
        if token_after==token_before and not changed:
            no_progress+=1
            _v429_specialist_whole_audit(user_request,manifest,work,audit,progress_callback,reason=f'V42.10 no accepted-state delta on full-audit round {round_no}')
            try:_v428_reconcile_live_contract_graph(user_request,manifest,work,progress_callback,reason='V42.10 dead whole-project audit round')
            except Exception:pass
    final=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
    return bool(final.get('clean')),list(final.get('issues') or [])


