# =============================================================================
# V42.13 BOUNDED SPECIALIST PROGRESS WATCHDOG / ANTI-OVERNIGHT CONVERGENCE
# =============================================================================
# A real resumed GearTrack run exposed a final convergence failure mode: the
# quarantine/escalation logic was correct, but the NEW 27B specialist itself could
# be called repeatedly against an unchanged accepted repository state.  A model
# response is not progress.  Only an accepted-revision token change or a cleaner
# whole-project audit is progress.
#
# V42.13 gives each unchanged accepted state a strict reasoning budget:
#   * one provider-specialist call per canonical provider
#   * one global-specialist call per identical whole-project issue signature
#   * deterministic graph/provider/config reconciliation immediately after a
#     specialist call that produces no accepted-state delta
#   * a bounded global no-progress circuit breaker instead of overnight loops
# Manual model locks and the AUTO 9B + NEW 27B Q2_K_P pool are unchanged.
V4213_VERSION = '42.13'
V4213_ENGINE = 'bounded-specialist-progress-watchdog'
V4213_STATE_FILE = '.jarvis_build/V4213_PROGRESS_WATCHDOG.json'
V4213_PROVIDER_SPECIALIST_CALL_LIMIT = max(1, min(3, int(os.getenv('JARVIS_V4213_PROVIDER_SPECIALIST_CALL_LIMIT','1'))))
V4213_AUDIT_SPECIALIST_CALL_LIMIT = max(1, min(3, int(os.getenv('JARVIS_V4213_AUDIT_SPECIALIST_CALL_LIMIT','1'))))
V4213_GLOBAL_NO_PROGRESS_LIMIT = max(1, min(4, int(os.getenv('JARVIS_V4213_GLOBAL_NO_PROGRESS_LIMIT','2'))))
V4213_GLOBAL_MAX_ROUNDS = max(2, min(6, int(os.getenv('JARVIS_V4213_GLOBAL_MAX_ROUNDS','4'))))


def _v4213_state_path(work):
    return Path(work)/V4213_STATE_FILE


def _v4213_load_state(work):
    try:
        data=json.loads(_v4213_state_path(work).read_text(encoding='utf-8',errors='replace'))
        return data if isinstance(data,dict) else {}
    except Exception:
        return {}


def _v4213_save_state(work,state):
    p=_v4213_state_path(work);p.parent.mkdir(parents=True,exist_ok=True)
    payload=dict(state or {});payload['version']='V'+V4213_VERSION;payload['updated_at']=_utc_stamp()
    try:p.write_text(json.dumps(payload,indent=2,ensure_ascii=False,default=str)+'\n',encoding='utf-8')
    except Exception:pass


def _v4213_state_for_token(work):
    token=_v429_progress_token(work);state=_v4213_load_state(work)
    if state.get('accepted_token')!=token:
        state={
            'accepted_token':token,
            'provider_specialist_calls':{},
            'audit_specialist_calls':{},
            'provider_stalls':{},
            'global_stalls':0,
        }
        _v4213_save_state(work,state)
    return state,token


def _v4213_audit_signature(audit):
    rows=[]
    for row in (audit or {}).get('issues') or []:
        rows.append(_v429_issue_key(row))
    return hashlib.sha256(json.dumps(sorted(rows),ensure_ascii=False,default=str).encode('utf-8')).hexdigest()[:24]


def _v4213_provider_signature(work,manifest,provider,reason=''):
    provider=_v40_norm_rel(provider)
    owners=[]
    for row in _v40_domain_owner_payload(manifest or {}).get('owners') or []:
        if _v40_norm_rel(row.get('provider'))==provider:
            owners.append((str(row.get('scope') or ''),str(row.get('symbol') or ''),str(row.get('kind') or '')))
    payload={
        'provider':provider,
        'problem':str(_v424_provider_state_problem(work,manifest,provider) or '')[:2500],
        'owners':sorted(owners),
        'reason':re.sub(r'\s+',' ',str(reason or ''))[-1500:],
    }
    return hashlib.sha256(json.dumps(payload,sort_keys=True,ensure_ascii=False).encode('utf-8')).hexdigest()[:24]


def _v4213_deterministic_provider_escape(user_request,manifest,work,provider,progress_callback=None,reason=''):
    """One non-LLM root repair transaction for a specialist that made no progress."""
    provider=_v40_norm_rel(provider);before=_v429_progress_token(work);changed=False
    _progress(
        progress_callback,
        f'V42.13 specialist made no accepted-state progress for {provider}; bypassing repeated model reasoning and running deterministic contract/provider reconciliation.',
        stage='V42.13 deterministic root-cause escape',percent=79,current_file=provider,model_role='orchestrator'
    )
    try:
        if _v428_reconcile_live_contract_graph(user_request,manifest,work,progress_callback,reason=('V42.13 deterministic escape: '+str(reason or ''))[-6000:]):changed=True
    except Exception:pass
    # Synthesize every pure unhealthy canonical provider, foundation first.  This is
    # deliberately broader than the one provider because a moved owner often exposes
    # a sibling provider that must exist before the old file can become a consumer.
    providers=[]
    for row in _v40_domain_owner_payload(manifest or {}).get('owners') or []:
        rp=_v40_norm_rel(row.get('provider'))
        if rp and rp not in providers and _v424_provider_state_problem(work,manifest,rp):providers.append(rp)
    if provider and provider not in providers and _v424_provider_state_problem(work,manifest,provider):providers.insert(0,provider)
    for rp in sorted(providers,key=lambda x:_v429_foundation_rank(manifest,x)):
        try:
            if _v428_commit_deterministic_provider(work,manifest,rp):changed=True
        except Exception:pass
        # A non-owner TypeScript contract path can usually become a compatibility
        # barrel after ownership reconciliation instead of competing with the owner.
        try:
            if _v4210_write_ts_contract_barrel(work,manifest,rp):
                if _v401_file_green_error(work,manifest,rp)=='' or not _v401_file_green_error(work,manifest,rp):
                    _v413_mark_accepted(work,rp,'v4213_deterministic_contract_barrel');changed=True
        except Exception:pass
    # Conventional config and Rust module closure are deterministic too.
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item,dict):continue
        rel=_v40_norm_rel(item.get('path'))
        if not rel or _v413_is_accepted(work,rel):continue
        try:
            if Path(rel).name.lower()=='tsconfig.node.json' and _v4210_write_tsconfig_node(work,rel):
                if _v4210_accept_deterministic_file(user_request,manifest,work,rel,'v4213_deterministic_tsconfig_node',progress_callback):changed=True
        except Exception:pass
    for comp in [x for x in (manifest or {}).get('components') or [] if isinstance(x,dict)]:
        try:changed=_v422_prepare_component_substrate(work,manifest,comp) or changed
        except Exception:pass
        try:changed=_v4210_harden_rust_crate_root(work,manifest,comp) or changed
        except Exception:pass
    try:_v36_build_repo_graph(work,manifest,write=True);_v36_build_contract_registry(work,manifest,write=True);_v373_refresh_project_kb(work,manifest,reason='v4213_deterministic_escape',force=True)
    except Exception:pass
    after=_v429_progress_token(work)
    success=(after!=before) or (not _v424_provider_state_problem(work,manifest,provider))
    _append_project_event(
        work,'v4213_deterministic_provider_escape',
        'V42.13 ran deterministic provider/graph reconciliation after a specialist produced no accepted-state delta.',
        file=provider,accepted_before=before,accepted_after=after,changed=bool(changed),success=bool(success),reason=str(reason or '')[-2500:]
    )
    return bool(success)


# One specialist model call per provider per unchanged accepted state.  If that call
# still leaves the provider unhealthy, deterministic orchestration takes over now --
# not on the tenth revisit hours later.
_v4213_prev_specialist_provider_takeover = _v429_specialist_provider_takeover

def _v429_specialist_provider_takeover(user_request,manifest,work,provider,reason='',progress_callback=None):
    provider=_v40_norm_rel(provider);state,token=_v4213_state_for_token(work)
    calls=dict(state.get('provider_specialist_calls') or {});key=provider or '<unknown>'
    count=int(calls.get(key) or 0)
    if count>=V4213_PROVIDER_SPECIALIST_CALL_LIMIT:
        _progress(progress_callback,f'V42.13 specialist budget reached for {provider} with no accepted-state change; skipping another 27B replay.',stage='V42.13 specialist no-progress circuit breaker',percent=79,current_file=provider,model_profile='27b38q2',model_role='specialist')
        stalls=dict(state.get('provider_stalls') or {});stalls[key]=int(stalls.get(key) or 0)+1;state['provider_stalls']=stalls;_v4213_save_state(work,state)
        return _v4213_deterministic_provider_escape(user_request,manifest,work,provider,progress_callback,reason='specialist call budget reached; '+str(reason or ''))
    calls[key]=count+1;state['provider_specialist_calls']=calls;_v4213_save_state(work,state)
    before=token
    result=_v4213_prev_specialist_provider_takeover(user_request,manifest,work,provider,reason,progress_callback)
    after=_v429_progress_token(work)
    if after!=before or not _v424_provider_state_problem(work,manifest,provider):
        return result
    # The specialist answered but repository authority did not move. Do not wait for
    # another provider-prepass cycle to discover this; escape immediately.
    stalls=dict(_v4213_load_state(work).get('provider_stalls') or {});stalls[key]=int(stalls.get(key) or 0)+1
    s,_=_v4213_state_for_token(work);s['provider_stalls']=stalls;_v4213_save_state(work,s)
    escaped=_v4213_deterministic_provider_escape(user_request,manifest,work,provider,progress_callback,reason='27B specialist returned without accepted-state delta; '+str(reason or ''))
    return bool(result or escaped)


# Avoid repeatedly calling the global 27B clustering pass for an identical issue set
# and accepted repository state.  The previous brief is advisory only; Jarvis owns
# edits, so replaying the same prompt cannot count as progress.
_v4213_prev_specialist_whole_audit = _v429_specialist_whole_audit

def _v429_specialist_whole_audit(user_request,manifest,work,audit,progress_callback=None,reason=''):
    state,token=_v4213_state_for_token(work);sig=_v4213_audit_signature(audit)
    calls=dict(state.get('audit_specialist_calls') or {});count=int(calls.get(sig) or 0)
    if count>=V4213_AUDIT_SPECIALIST_CALL_LIMIT:
        _progress(progress_callback,'V42.13 identical whole-project error signature already received a 27B root-cause brief; skipping repeated specialist reasoning and continuing deterministic/root-ordered repair.',stage='V42.13 global specialist circuit breaker',percent=82,model_profile='27b38q2',model_role='specialist')
        _append_project_event(work,'v4213_global_specialist_suppressed','V42.13 suppressed a repeated 27B whole-project audit for an unchanged accepted state/error signature.',signature=sig,accepted_token=token,reason=str(reason or '')[-2500:])
        return 'V42.13: repeated identical specialist audit suppressed; repair from existing consolidated evidence.'
    calls[sig]=count+1;state['audit_specialist_calls']=calls;_v4213_save_state(work,state)
    return _v4213_prev_specialist_whole_audit(user_request,manifest,work,audit,progress_callback,reason)


# Bounded whole-project convergence.  All components are still validated every round,
# but two unchanged rounds after specialist/deterministic reconciliation trip the
# circuit breaker.  This deliberately fails with consolidated evidence rather than
# allowing an overnight loop that cannot alter accepted state.
def _v429_whole_project_convergence(user_request,manifest,work,progress_callback=None):
    if not V429_WHOLE_PROJECT_AUDIT:return True,[]
    last_sig='';last_token='';no_progress=0
    rounds=min(V4213_GLOBAL_MAX_ROUNDS,max(2,int(globals().get('V429_AUDIT_ROUNDS',5))))
    for round_no in range(1,rounds+1):
        _progress(progress_callback,f'V42.13 whole-project convergence round {round_no}/{rounds}: validating every planned file/provider and every independent component.',stage='V42.13 bounded whole-project audit',percent=min(94,80+round_no*3))
        audit=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
        if audit.get('clean'):
            _append_project_event(work,'v4213_whole_project_green','V42.13 whole-project audit reached zero unresolved static/provider/component/test issues.',round=round_no)
            return True,[]
        token_before=_v429_progress_token(work);sig=_v4213_audit_signature(audit)
        if sig==last_sig and token_before==last_token:no_progress+=1
        else:no_progress=0
        last_sig,last_token=sig,token_before
        if no_progress>=1:
            _v429_specialist_whole_audit(user_request,manifest,work,audit,progress_callback,reason=f'V42.13 unchanged whole-project signature round {round_no}')
        changed=_v429_repair_audit_round(user_request,manifest,work,audit,progress_callback,round_no)
        # Always run deterministic closure after a dead/repeated round; this is cheap
        # compared with another local-model call and often collapses contract/config debt.
        token_mid=_v429_progress_token(work)
        if token_mid==token_before and (no_progress>=1 or not changed):
            try:_v428_reconcile_live_contract_graph(user_request,manifest,work,progress_callback,reason=f'V42.13 whole-project no-progress round {round_no}')
            except Exception:pass
            owners=[]
            for row in _v40_domain_owner_payload(manifest or {}).get('owners') or []:
                p=_v40_norm_rel(row.get('provider'))
                if p and p not in owners and _v424_provider_state_problem(work,manifest,p):owners.append(p)
            for p in sorted(owners,key=lambda x:_v429_foundation_rank(manifest,x)):
                try:_v4213_deterministic_provider_escape(user_request,manifest,work,p,progress_callback,reason=f'global audit round {round_no}')
                except Exception:pass
        token_after=_v429_progress_token(work)
        if token_after==token_before:
            no_progress+=1
        else:
            no_progress=0;last_token=token_after
        if no_progress>=V4213_GLOBAL_NO_PROGRESS_LIMIT:
            final=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
            _append_project_event(work,'v4213_global_no_progress_breaker','V42.13 stopped repeated convergence because specialist + deterministic repair could not change accepted repository state.',round=round_no,signature=_v4213_audit_signature(final),accepted_token=_v429_progress_token(work),issues=(final.get('issues') or [])[:30])
            _progress(progress_callback,f'V42.13 convergence circuit breaker: {len(final.get("issues") or [])} issue(s) remain after bounded specialist + deterministic recovery with no accepted-state progress. Stopping the loop with consolidated evidence instead of running overnight.',stage='V42.13 no-progress circuit breaker',percent=94)
            return False,list(final.get('issues') or [])
    final=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
    return bool(final.get('clean')),list(final.get('issues') or [])


