_v4214_prev_validate_component=_v35_validate_component

def _v35_validate_component(work,manifest,component,user_request=''):
    report={}
    try:_v4214_reconcile_node_manifests(work,manifest or {},report)
    except Exception:pass
    try:_v4214_reconcile_cargo_manifest(work,manifest or {},report)
    except Exception:pass
    ok,out=_v4214_prev_validate_component(work,manifest,component,user_request)
    if ok:return ok,out
    adapter=_v361_normalize_component_adapter((component or {}).get('toolchain_adapter'));text=str(out or '')
    if V4214_NODE_LOCK_REPAIR and adapter in _V4214_NODE_ADAPTERS and ('npm ci' in text.lower() or 'package-lock' in text.lower()) and ('in sync' in text.lower() or 'EUSAGE' in text or 'Invalid: lock file' in text):
        root=_v40_norm_rel((component or {}).get('root')) or '.';cwd=Path(work) if root=='.' else Path(work)/root
        if (cwd/'package.json').exists():
            _progress(None,f'V42.14 detected manifest/lock drift in {component.get("id") or root}; regenerating lock metadata from the reconciled package manifest before retrying validation.',stage='V42.14 deterministic package-lock reconciliation')
            try:
                rok,rout=_run_command('npm install --package-lock-only --ignore-scripts --no-audit --no-fund',cwd,240)
                _append_project_event(work,'v4214_package_lock_reconciled',f'V42.14 package-lock-only regeneration {"passed" if rok else "failed"}.',component=component.get('id'),output=str(rout or '')[-4000:])
                if rok:return _v4214_prev_validate_component(work,manifest,component,user_request)
            except Exception:pass
    return ok,out


