# =============================================================================
# V42.15 RUST MODULE TOPOLOGY / RESUME TOOLCHAIN AUTHORITY / ENDGAME SOURCE GUARD
# =============================================================================
# Regression fixed from the near-complete GearTrack resume (2026-09-01):
# - generic repair wording containing "escalate" was misread as an explicit Scala request
#   because the old adapter matcher used substring checks ("scala" is inside "escalate");
# - an unplanned build.sbt/Scala scaffold could then contaminate a React+Rust/Tauri resume;
# - Rust use paths such as crate::models::tool::Tool were not resolved through
#   src/models/mod.rs + src/models/tool.rs, so a generated flat src/models.rs could become a
#   false high-centrality provider and trigger 27B root-cause repair against a fictional file;
# - stale accepted-revision entries survived topology migration;
# - once every current planned file was accepted, an ambiguous/unplanned provider was still
#   allowed to become a new repair target instead of rerunning the real whole-project audit.
#
# V42.15 makes current repository topology authoritative during resume and convergence.
V4215_VERSION = '42.15'
V4215_ENGINE = 'rust-module-topology-resume-authority-endgame-guard'
V4215_MIGRATION_REPORT = 'JARVIS_V4215_TOPOLOGY_AUTHORITY.json'
V4215_RUST_MODULE_RESOLUTION = os.getenv('JARVIS_V4215_RUST_MODULE_RESOLUTION','1').strip().lower() not in {'0','false','no','off'}
V4215_RESUME_STACK_SANITIZE = os.getenv('JARVIS_V4215_RESUME_STACK_SANITIZE','1').strip().lower() not in {'0','false','no','off'}
V4215_PRUNE_STALE_ACCEPTED = os.getenv('JARVIS_V4215_PRUNE_STALE_ACCEPTED','1').strip().lower() not in {'0','false','no','off'}
V4215_ENDGAME_NO_PHANTOM_PROVIDER = os.getenv('JARVIS_V4215_ENDGAME_NO_PHANTOM_PROVIDER','1').strip().lower() not in {'0','false','no','off'}


def _v4215_word(text, word):
    return bool(re.search(r'(?<![A-Za-z0-9_])'+re.escape(str(word))+r'(?![A-Za-z0-9_])', str(text or ''), re.I))


# Old universal matching intentionally accepted many natural aliases, but bare language names
# must be token matches.  This prevents "escalate" -> Scala and "trust" -> Rust false locks.
_v4215_prev_explicit_toolchain = _v35_explicit_toolchain

def _v35_explicit_toolchain(text):
    result = _v4215_prev_explicit_toolchain(text)
    low = _strip_jarvis_routing_noise(str(text or '')).lower()
    if result == 'scala_sbt':
        if not (_v4215_word(low,'scala') or _v4215_word(low,'sbt') or 'build.sbt' in low):
            return 'generic'
    if result == 'rust':
        if not (_v4215_word(low,'rust') or _v4215_word(low,'cargo')):
            return 'generic'
    if result == 'react':
        # Keep explicit phrases but do not let words such as "reaction" become a stack lock.
        if not (_v4215_word(low,'react') or 'vite react' in low):
            return 'generic'
    return result


def _v4215_manifest_paths(manifest):
    return {_v40_norm_rel(x.get('path')) for x in (manifest or {}).get('files') or [] if isinstance(x,dict) and _v40_norm_rel(x.get('path'))}


def _v4215_all_planned_accepted(work, manifest):
    paths = [p for p in _v4215_manifest_paths(manifest) if not _v4214_is_internal_rel(p)]
    return bool(paths) and all((Path(work)/p).exists() and _v413_is_accepted(work,p) for p in paths)


def _v4215_flat_aggregate_reason(work, rel, manifest=None):
    """Classify a flat source file that conflicts with an already-existing directory module."""
    rel = _v40_norm_rel(rel); p = Path(work)/rel
    if not rel:
        return ''
    low = rel.lower()
    # Rust permits foo.rs OR foo/mod.rs for module foo, not both as competing module roots.
    if low.endswith('.rs') and Path(rel).name.lower() not in {'lib.rs','main.rs','build.rs','mod.rs'}:
        stem = rel[:-3]
        mod = Path(work)/stem/'mod.rs'
        if mod.exists() and mod.is_file():
            return f'Rust directory module {stem}/mod.rs is canonical; competing flat module {rel} must not be synthesized'
    # TypeScript directory-domain topology: only suppress an UNPLANNED flat aggregate when
    # the semantic directory already exists.  Planned barrels such as src/types/index.ts remain valid.
    if Path(rel).suffix.lower() in {'.ts','.tsx','.js','.jsx'}:
        planned = _v4215_manifest_paths(manifest or {})
        if rel not in planned:
            stem = Path(rel).with_suffix('').as_posix()
            d = Path(work)/stem
            if d.is_dir():
                children = [x for x in d.iterdir() if x.is_file() and x.suffix.lower() in {'.ts','.tsx','.js','.jsx'}]
                if len(children) >= 2 or any(x.name.lower().startswith('index.') for x in children):
                    return f'directory module {stem}/ is canonical; unplanned flat aggregate {rel} is stale'
    return ''


# Strengthen V42.14 topology normalization even when a bad prior repair already materialized
# the flat aggregate on disk.
_v4215_prev_obsolete_topology_path = _v4214_obsolete_topology_path

def _v4214_obsolete_topology_path(work, rel, components):
    old = _v4215_prev_obsolete_topology_path(work,rel,components)
    if old:
        return old
    return _v4215_flat_aggregate_reason(work,rel,None)


def _v4215_backup_and_remove(work, rel, reason, bucket='topology'):
    rel = _v40_norm_rel(rel); p = Path(work)/rel
    if not p.exists() or not p.is_file():
        return False
    try:
        dest = Path(work).parent/'.jarvis_v4215_quarantine'/bucket/rel
        dest.parent.mkdir(parents=True,exist_ok=True)
        try: shutil.copy2(p,dest)
        except Exception: pass
        p.unlink()
        try:_v413_forget_accepted(work,rel)
        except Exception:pass
        _append_project_event(work,'v4215_source_quarantined',f'V42.15 quarantined stale/unplanned source {rel}.',file=rel,reason=reason,bucket=bucket)
        return True
    except Exception:
        return False


def _v4215_prune_accepted_ledger(work, manifest, report=None):
    if not V4215_PRUNE_STALE_ACCEPTED:
        return []
    data = _v413_load_accepted(work); files = dict(data.get('files') or {})
    actual = set(_v4214_actual_authored_files(work)); planned = _v4215_manifest_paths(manifest)
    removed=[]
    for rel in list(files):
        n = _v40_norm_rel(rel)
        stale = _v4215_flat_aggregate_reason(work,n,manifest)
        if _v4214_is_internal_rel(n) or stale or (n not in actual and n not in planned):
            files.pop(rel,None);removed.append({'path':n,'reason':stale or 'not present in current authored/planned topology'})
    if removed:
        data['files']=files;data['updated_at']=_utc_stamp();data['v4215_pruned']=removed[:200];_v413_save_accepted(work,data)
    if isinstance(report,dict):report['pruned_stale_accepted_revisions']=removed
    return removed


def _v4215_strip_injected_toolchain_lock(text, actual_adapters=None):
    """Remove old Jarvis-generated explicit-lock blocks that contradict current topology."""
    s = str(text or '')
    adapters = {str(x or '').strip().lower() for x in (actual_adapters or []) if str(x or '').strip()}
    # Blocks created by the legacy forced-rebuild path are recognizable and safe to strip when
    # their adapter conflicts with current component evidence.
    pat = re.compile(
        r'\n*EXPLICIT USER TOOLCHAIN LOCK \(preserve it\):\s*\n'
        r'- Adapter:\s*([^\n]+)\n'
        r'- Language:[^\n]*\n'
        r'- Framework/toolchain:[^\n]*\n'
        r'- Do not substitute an unrelated language/framework\.\s*'
        r'(?:\n*Rebuild the correct project from these requirements\. Delete or ignore any existing files that use the wrong language or domain\.?)?',
        re.I,
    )
    def repl(m):
        adapter = _v361_normalize_component_adapter(str(m.group(1) or '').strip())
        if adapter and adapter not in adapters:
            return '\n'
        return m.group(0)
    s = pat.sub(repl,s)
    return re.sub(r'\n{3,}','\n\n',s).strip()


def _v4215_unplanned_stack_pollution(work, historical, effective_request):
    """Return high-confidence old-agent stack pollution paths; never guess from extension alone."""
    kb = _v4214_json(Path(work)/V373_PROJECT_KB_FILE,{})
    unplanned = { _v40_norm_rel(k) for k,v in (kb.get('files') or {}).items() if isinstance(v,dict) and v.get('status')=='unplanned_source' }
    planned = {_v40_norm_rel(x.get('path')) for x in (historical or {}).get('files') or [] if isinstance(x,dict)}
    trusted = {_v361_normalize_component_adapter(x.get('toolchain_adapter')) for x in (historical or {}).get('components') or [] if isinstance(x,dict)}
    explicit = _v35_explicit_toolchain(_v4215_strip_injected_toolchain_lock(effective_request,trusted))
    if explicit != 'generic':trusted.add(_v361_normalize_component_adapter(explicit))
    out=[]
    # Distinct Scala/sbt artifacts are the exact observed contamination.  Require either old KB
    # unplanned evidence or total absence from the historical plan before quarantine.
    if 'scala_sbt' not in trusted:
        for rel in _v4214_actual_authored_files(work):
            low=rel.lower()
            is_scala = low=='build.sbt' or low.startswith('project/') and low.endswith('.scala') or low.startswith('src/main/scala/') or low.startswith('src/test/scala/')
            if is_scala and (rel in unplanned or rel not in planned):out.append(rel)
    return sorted(dict.fromkeys(out),key=str.casefold)


# Run high-confidence stack pollution cleanup BEFORE current component rediscovery, otherwise a
# stray build.sbt can promote itself into a new real component during resume migration.
_v4215_prev_rebuild_current_state = _v4214_rebuild_current_state

def _v4214_rebuild_current_state(work, seed_manifest, effective_request, source_zip=None):
    historical = _v4214_select_historical_manifest(work,seed_manifest)
    trusted_adapters=[_v361_normalize_component_adapter(x.get('toolchain_adapter')) for x in historical.get('components') or [] if isinstance(x,dict)]
    clean_request = _v4215_strip_injected_toolchain_lock(effective_request,trusted_adapters) if V4215_RESUME_STACK_SANITIZE else str(effective_request or '')
    pre_removed=[]
    if V4215_RESUME_STACK_SANITIZE:
        for rel in _v4215_unplanned_stack_pollution(work,historical,clean_request):
            if _v4215_backup_and_remove(work,rel,'unplanned toolchain artifact contradicts historical/current project components','stack_pollution'):
                pre_removed.append(rel)
    manifest,report = _v4215_prev_rebuild_current_state(work,seed_manifest,clean_request,source_zip)
    report = report if isinstance(report,dict) else {}
    report['v4215_pre_migration_stack_pollution_removed']=pre_removed
    report['v4215_effective_request_sanitized']=bool(clean_request.strip()!=str(effective_request or '').strip())
    # V42.14 intentionally rebuilt architecture, but its imported baseline ledger could still carry
    # entries for already-deleted nested roots.  Prune those now, then rebuild derived intelligence.
    _v4215_prune_accepted_ledger(work,manifest,report)
    try:
        _V36_REPO_CACHE.clear();_V36_CONTRACT_CACHE.clear()
    except Exception:pass
    try:_v36_build_repo_graph(work,manifest,write=True)
    except Exception as exc:report.setdefault('warnings',[]).append(f'V42.15 repo graph rebuild warning: {exc}')
    try:_v36_build_contract_registry(work,manifest,write=True)
    except Exception as exc:report.setdefault('warnings',[]).append(f'V42.15 contract registry rebuild warning: {exc}')
    try:_v373_refresh_project_kb(work,manifest,reason='v4215_topology_authority',force=True)
    except Exception as exc:report.setdefault('warnings',[]).append(f'V42.15 KB rebuild warning: {exc}')
    try:(Path(work)/V4215_MIGRATION_REPORT).write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    except Exception:pass
    return manifest,report


# Sanitize the effective/original request returned by resume bootstrap too.  This is what gets
# written into JARVIS_PROJECT_STATE and model prompts, so an old injected Scala lock must not survive.
_v4215_prev_resume_seed_from_workspace = _resume_seed_from_workspace

def _resume_seed_from_workspace(work,source_zip,user_request):
    seed = _v4215_prev_resume_seed_from_workspace(work,source_zip,user_request)
    if not V4215_RESUME_STACK_SANITIZE:return seed
    manifest=seed.get('manifest') or {}
    adapters=[_v361_normalize_component_adapter(x.get('toolchain_adapter')) for x in manifest.get('components') or [] if isinstance(x,dict)]
    for key in ('effective_request','original_request'):
        seed[key]=_v4215_strip_injected_toolchain_lock(seed.get(key) or '',adapters)
    clean=seed.get('effective_request') or str(user_request or '')
    manifest['_original_user_request']=clean
    criteria=[]
    for row in manifest.get('acceptance_criteria') or []:
        val=_v4215_strip_injected_toolchain_lock(row,adapters)
        if val and val not in criteria:criteria.append(val)
    if criteria:manifest['acceptance_criteria']=criteria
    seed['manifest']=manifest
    return seed


def _v4215_cargo_crates(work):
    out=[];root=Path(work)
    for cargo in root.rglob('Cargo.toml'):
        try:
            rel=cargo.relative_to(root).as_posix()
        except Exception:continue
        if _v4214_is_internal_rel(rel):continue
        cr=cargo.parent;src=cr/'src'
        if not src.exists():continue
        txt=cargo.read_text(encoding='utf-8',errors='replace')
        m=re.search(r'(?ms)^\[package\].*?^\s*name\s*=\s*["\']([^"\']+)',txt)
        name=(m.group(1).replace('-','_') if m else '')
        out.append({'root':cr,'src':src,'name':name})
    return out


def _v4215_rust_module_path(crate_src, file_path):
    p=Path(file_path)
    try:parts=list(p.relative_to(crate_src).parts)
    except Exception:return None
    if not parts or p.suffix.lower()!='.rs':return None
    if parts[-1] in {'lib.rs','main.rs'}:return tuple()
    if parts[-1]=='mod.rs':return tuple(parts[:-1])
    return tuple(parts[:-1]+[Path(parts[-1]).stem])


def _v4215_expand_rust_use(raw):
    s=str(raw or '').strip()
    if not s:return []
    # Keep an aggregate prefix as a valid module dependency and expand simple brace children.
    out=[s]
    m=re.match(r'^(.*?)::\{(.*)\}$',s)
    if m:
        prefix=m.group(1).strip();inside=m.group(2)
        out.append(prefix)
        depth=0;buf='';items=[]
        for ch in inside+',':
            if ch=='{':depth+=1
            elif ch=='}':depth=max(0,depth-1)
            if ch==',' and depth==0:
                if buf.strip():items.append(buf.strip())
                buf=''
            else:buf+=ch
        for item in items:
            item=item.split(' as ')[0].strip()
            if item and item not in {'self','*'}:out.append(prefix+'::'+item)
    return list(dict.fromkeys(out))


def _v4215_resolve_rust_use(work, rel, raw, files):
    root=Path(work);p=root/rel
    crates=_v4215_cargo_crates(work);crate=None
    for c in crates:
        try:p.relative_to(c['src']);crate=c;break
        except Exception:continue
    if not crate:return []
    module_map={}
    for target in files:
        tp=root/target
        if Path(target).suffix.lower()!='.rs':continue
        try:mp=_v4215_rust_module_path(crate['src'],tp)
        except Exception:mp=None
        if mp is not None:
            # If both foo.rs and foo/mod.rs exist, directory module is authoritative.
            old=module_map.get(mp)
            if old and old.endswith('.rs') and not old.endswith('/mod.rs') and target.endswith('/mod.rs'):
                module_map[mp]=target
            elif not old:module_map[mp]=target
    current=_v4215_rust_module_path(crate['src'],p) or tuple()
    out=[]
    for expr in _v4215_expand_rust_use(raw):
        expr=re.sub(r'\s+','',expr.split(' as ')[0])
        parts=[x for x in expr.split('::') if x and x not in {'*'}]
        if not parts:continue
        first=parts[0]
        base=[];rest=[]
        if first=='crate' or (crate.get('name') and first==crate.get('name')):
            rest=parts[1:]
        elif first=='self':
            base=list(current);rest=parts[1:]
        elif first=='super':
            base=list(current[:-1]);i=1
            while i<len(parts) and parts[i]=='super':
                if base:base.pop()
                i+=1
            rest=parts[i:]
        else:
            continue
        candidate=tuple(base+rest)
        # The final segments may be types/functions, so resolve the longest known module prefix.
        for n in range(len(candidate),-1,-1):
            mp=candidate[:n]
            target=module_map.get(mp)
            if target and target!=rel:
                out.append(target);break
    return list(dict.fromkeys(out))


# Repair repo-graph module edges from actual Rust module semantics and remove stale aggregate
# files from graph authority.  This is deterministic and model-independent.
_v4215_prev_build_repo_graph = _v36_build_repo_graph

def _v36_build_repo_graph(work,manifest=None,write=True):
    payload=_v4215_prev_build_repo_graph(work,manifest,write=False)
    try:payload=json.loads(json.dumps(payload,ensure_ascii=False))
    except Exception:payload=dict(payload or {})
    files=payload.get('files') or {};stale=[]
    if V4215_RUST_MODULE_RESOLUTION:
        for rel in list(files):
            reason=_v4215_flat_aggregate_reason(work,rel,manifest)
            if reason:
                stale.append(rel);files.pop(rel,None)
        for rel,info in list(files.items()):
            edges={str(e.get('to')):float(e.get('weight') or 0) for e in (info.get('edges') or []) if e.get('to') in files and e.get('to') not in stale}
            resolved=[]
            if Path(rel).suffix.lower()=='.rs':
                for imp in info.get('imports') or []:
                    for target in _v4215_resolve_rust_use(work,rel,imp,files):
                        edges[target]=max(edges.get(target,0),7.0);resolved.append(target)
            info['edges']=[{'to':k,'weight':int(v) if float(v).is_integer() else v} for k,v in sorted(edges.items())]
            if resolved:info['resolved_rust_imports']=list(dict.fromkeys(resolved))
        # Rebuild provider index only from authoritative graph files.
        providers={}
        for rel,info in files.items():
            for sym in info.get('symbols') or []:
                name=str((sym or {}).get('name') or '')
                if name:providers.setdefault(name,[]).append(rel)
        payload['provider_index']={k:v for k,v in providers.items() if len(v)<=8}
        payload['files']=files
        payload['v4215_stale_aggregates_suppressed']=stale
    if write:
        try:(Path(work)/V36_REPO_GRAPH_FILE).write_text(json.dumps(payload,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
        except Exception:pass
    return payload


