def _v4214_reconcile_node_manifests(work,manifest,report=None):
    changed=bool(_v4215_prev_reconcile_node_manifests(work,manifest,report))
    report=report if isinstance(report,dict) else {};actions=report.setdefault('manifest_repairs',[])
    for comp in (manifest or {}).get('components') or []:
        adapter=_v361_normalize_component_adapter((comp or {}).get('toolchain_adapter'))
        if adapter not in _V4214_NODE_ADAPTERS:continue
        root=_v40_norm_rel((comp or {}).get('root')) or '.';cwd=Path(work) if root=='.' else Path(work)/root
        pkg=cwd/'package.json'
        if not pkg.exists():continue
        data=_v4214_json(pkg,{})
        if not isinstance(data,dict):continue
        deps=dict(data.get('dependencies') or {});dev=dict(data.get('devDependencies') or {})
        api=dev.pop('@tauri-apps/api',None)
        if api is not None and '@tauri-apps/api' not in deps:
            deps['@tauri-apps/api']=api;data['dependencies']=deps;data['devDependencies']=dev
            pkg.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
            changed=True;actions.append({'file':_v40_norm_rel(str(pkg.relative_to(work))),'repair':'moved @tauri-apps/api from devDependencies to runtime dependencies'})
    return changed

# =============================================================================
# V42.16 UNIVERSAL TRANSACTIONAL COMPILE-GATE + PRODUCTION-BEFORE-TESTS
# =============================================================================
# Regression fixed from the 2026-09-01 GearTrack resume:
# - a model transport response containing a shell command was committed as src-tauri/src/lib.rs;
# - the legacy candidate validator explicitly tolerated syntax errors for later repair;
# - the original transactional sandbox/replay path returned early for every non-Python language;
# - acceptance tests were repaired while the production crate still had compiler blockers.
#
# V42.16 makes language/toolchain diagnostics part of the mutation transaction itself.
# The design is deliberately stack-agnostic: parsers/compilers are selected from the actual file
# language and discovered component adapter, and unknown/custom stacks retain the existing declared
# build/test command pathway.  A candidate may advance a red build, but it may never commit malformed
# source or leave the exact proven validator failure unchanged when that failure names the target.

V4216_VERSION = '42.16.0'
V4216_ENGINE = 'UNIVERSAL_TRANSACTIONAL_COMPILE_GATE_FACTORY'
V4216_STRICT_SOURCE_SYNTAX = os.getenv('JARVIS_V4216_STRICT_SOURCE_SYNTAX','1').strip().lower() not in {'0','false','no','off'}
V4216_NONPY_REPLAY = os.getenv('JARVIS_V4216_NONPY_REPLAY','1').strip().lower() not in {'0','false','no','off'}
V4216_PRODUCTION_BEFORE_TESTS = os.getenv('JARVIS_V4216_PRODUCTION_BEFORE_TESTS','1').strip().lower() not in {'0','false','no','off'}
V4216_ATOMIC_DIRECT_EDIT = os.getenv('JARVIS_V4216_ATOMIC_DIRECT_EDIT','1').strip().lower() not in {'0','false','no','off'}
V4216_PARSER_TIMEOUT = max(3, min(30, int(os.getenv('JARVIS_V4216_PARSER_TIMEOUT','12'))))
V4216_PRODUCTION_CHECK_TIMEOUT = max(20, min(600, int(os.getenv('JARVIS_V4216_PRODUCTION_CHECK_TIMEOUT','180'))))
V4216_AUDIT_SYNTAX_MAX_FILES = max(50, min(5000, int(os.getenv('JARVIS_V4216_AUDIT_SYNTAX_MAX_FILES','1200'))))
V4216_REPORT_FILE = 'JARVIS_V4216_TRANSACTIONAL_GATE.json'


def _v4216_is_test_rel(rel):
    rel=_v40_norm_rel(rel);low=('/'+rel.lower().strip('/')+'/').replace('\\','/')
    name=Path(rel).name.lower()
    return (
        '/tests/' in low or '/test/' in low or '/__tests__/' in low
        or name.startswith('test_') or name.endswith('_test.py') or name.endswith('_test.rs')
        or '.test.' in name or '.spec.' in name or name.startswith('acceptance_')
        or 'acceptance' in name and Path(rel).suffix.lower() in _SOURCE_SUFFIXES
    )


def _v4216_source_transport_contamination(rel,text):
    """Reject obvious command/prose/transport material masquerading as source code."""
    rel=_v40_norm_rel(rel);ext=Path(rel).suffix.lower();src=str(text or '')
    if ext not in _SOURCE_SUFFIXES:return ''
    stripped=src.lstrip('\ufeff \t\r\n')
    if stripped.startswith('```'):
        return f'V42.16 source transport gate: {rel} begins with a Markdown code fence instead of raw source.'
    # Shell/batch/powershell source legitimately contains command lines; other languages do not.
    if ext not in {'.sh','.bash','.zsh','.fish','.ps1','.bat','.cmd'}:
        first=''
        for line in stripped.splitlines():
            s=line.strip()
            if s:
                first=s;break
        low=first.lower()
        bad_prefixes=(
            'find . ','find ./','get-childitem ','robocopy ','copy-item ','remove-item ','new-item ',
            'npm ','npx ','pnpm ','yarn ','cargo ','rustc ','python ','python3 ','pip ','pip3 ',
            'rm -','cp -','mv ','mkdir ','powershell ','pwsh ','cmd /c ','winget ','choco ',
        )
        if any(low.startswith(x) for x in bad_prefixes):
            return f'V42.16 source transport gate: {rel} contains a shell/terminal command where {ext or "source"} code is required: {first[:220]}'
        if ext not in {'.html','.htm','.xml','.svg'} and low.startswith(('<!doctype html','<html','<?xml')):
            return f'V42.16 source transport gate: {rel} contains markup instead of {ext or "source"} code.'
    return ''


def _v4216_parser_command(rel,temp_path,work=None,manifest=None):
    """Return an isolated syntax/parser command, never a project build command."""
    ext=Path(rel).suffix.lower();tp=str(temp_path)
    if ext=='.rs':
        exe=shutil.which('rustfmt')
        if exe:return [exe,'--edition','2021','--emit','stdout',tp]
    if ext=='.go':
        exe=shutil.which('gofmt')
        if exe:return [exe,tp]
    if ext in {'.js','.mjs','.cjs'}:
        exe=shutil.which('node')
        if exe:return [exe,'--check',tp]
    if ext=='.rb':
        exe=shutil.which('ruby')
        if exe:return [exe,'-c',tp]
    if ext=='.php':
        exe=shutil.which('php')
        if exe:return [exe,'-l',tp]
    if ext=='.swift':
        exe=shutil.which('swiftc')
        if exe:return [exe,'-parse',tp]
    if ext=='.lua':
        exe=shutil.which('luac')
        if exe:return [exe,'-p',tp]
    if ext in {'.sh','.bash'}:
        exe=shutil.which('bash')
        if exe:return [exe,'-n',tp]
    return None


def _v4216_typescript_syntax_error(work,manifest,rel,text):
    ext=Path(rel).suffix.lower()
    if ext not in {'.ts','.tsx','.mts','.cts'}:return ''
    node=shutil.which('node')
    if not node:return ''
    try:
        root=_v362_component_root_for_rel(manifest or {},rel)
    except Exception:root='.'
    cwd=Path(work) if not root or root=='.' else Path(work)/root
    # Do not invoke npx: it can download the wrong `tsc` package. Only use a local TypeScript runtime.
    tsmod=cwd/'node_modules'/'typescript'
    if not tsmod.exists():return ''
    script=(
        "const fs=require('fs');"
        "const ts=require(require.resolve('typescript',{paths:[process.cwd()]}));"
        "const p=process.argv[1];const s=fs.readFileSync(p,'utf8');"
        "const k=p.endsWith('.tsx')?ts.ScriptKind.TSX:ts.ScriptKind.TS;"
        "const f=ts.createSourceFile(p,s,ts.ScriptTarget.Latest,true,k);"
        "const d=f.parseDiagnostics||[];"
        "if(d.length){for(const x of d.slice(0,12)){console.error(ts.flattenDiagnosticMessageText(x.messageText,' '));}process.exit(2);}" 
    )
    td=tempfile.mkdtemp(prefix='jarvis_v4216_ts_')
    try:
        p=Path(td)/Path(rel).name;p.write_text(str(text or ''),encoding='utf-8')
        ok,out=_run_command([node,'-e',script,str(p)],cwd,V4216_PARSER_TIMEOUT)
        if not ok:return f'V42.16 TypeScript syntax gate: {rel} is not parseable: {str(out or "")[-1800:]}'
    except Exception:return ''
    finally:
        try:shutil.rmtree(td,ignore_errors=True)
        except Exception:pass
    return ''


def _v4216_language_syntax_error(work,manifest,rel,content):
    rel=_v40_norm_rel(rel);text=_extract_single_file_response(content,rel)
    contamination=_v4216_source_transport_contamination(rel,text)
    if contamination:return contamination
    ext=Path(rel).suffix.lower();name=Path(rel).name.lower()
    # Deterministic data/config parsers.
    if ext=='.toml':
        try:
            import tomllib
            tomllib.loads(text)
        except Exception as exc:return f'V42.16 TOML syntax gate: {rel}: {exc}'
    if ext in {'.yaml','.yml'}:
        try:
            import yaml
            yaml.safe_load(text)
        except ImportError:pass
        except Exception as exc:return f'V42.16 YAML syntax gate: {rel}: {exc}'
    if ext in {'.ts','.tsx','.mts','.cts'} and work is not None:
        err=_v4216_typescript_syntax_error(work,manifest or {},rel,text)
        if err:return err
    cmd=None;td=None
    try:
        td=tempfile.mkdtemp(prefix='jarvis_v4216_parse_')
        p=Path(td)/(Path(rel).name or ('candidate'+ext));p.write_text(text,encoding='utf-8')
        cmd=_v4216_parser_command(rel,p,work,manifest)
        if cmd:
            ok,out=_run_command(cmd,Path(td),V4216_PARSER_TIMEOUT)
            if not ok:
                return f'V42.16 language syntax gate: {rel} failed its {Path(cmd[0]).name} parser: {str(out or "")[-1800:]}'
    except Exception as exc:
        # Parser availability/execution problems are not proof that user source is invalid.
        try:_append_project_event(work,'v4216_parser_warning',f'Optional parser could not run for {rel}: {exc}',file=rel)
        except Exception:pass
    finally:
        if td:
            try:shutil.rmtree(td,ignore_errors=True)
            except Exception:pass
    return ''


# Strengthen the universal local structural validator. This is reached by bootstrap,
# generation, central commit-gate and many deterministic repair paths.
_v4216_prev_content_validation_error=_content_validation_error

def _content_validation_error(expected_path,content):
    base=_v4216_prev_content_validation_error(expected_path,content)
    if base:return base
    if not V4216_STRICT_SOURCE_SYNTAX:return ''
    return _v4216_language_syntax_error(None,{},expected_path,content)


# The pre-V42.16 bootstrap helper explicitly accepted Python syntax failures. Replace
# it with a strict transport/local-syntax filter for every source language.
def _candidate_files_valid(work,candidates):
    errors=[];changed=[]
    for rel_raw,content in candidates:
        try:rel=_safe_relative(rel_raw)
        except Exception as exc:
            errors.append(f'{rel_raw}: unsafe path ({exc})');continue
        if rel.name in _RESERVED_OUTPUT_NAMES or rel.name.startswith('JARVIS_QWEN_RAW_'):
            errors.append(f'{rel.as_posix()}: reserved Jarvis output name ignored');continue
        if not content or not str(content).strip():
            errors.append(f'{rel.as_posix()}: empty content');continue
        err=_content_validation_error(rel.as_posix(),content)
        if err:
            errors.append(f'{rel.as_posix()}: {err}');continue
        changed.append((rel,content))
    return changed,errors


def _v4216_failure_names_target(rel,failure):
    rel=_v40_norm_rel(rel);raw=str(failure or '').replace('\\','/').lower()
    if not rel or not raw:return False
    low=rel.lower();name=Path(rel).name.lower()
    return low in raw or ('/'+low) in raw or (name and name in raw)


def _v4216_nonpython_replay_error(work,manifest,rel,content,user_request,validation_failure):
    if not (V4216_NONPY_REPLAY and validation_failure):return ''
    if Path(rel).suffix.lower() in {'.py','.pyw'}:return ''
    if not _v4216_failure_names_target(rel,validation_failure):return ''
    temp=None
    try:
        temp,clone=_copy_project_for_candidate_validation(work)
        p=clone/_safe_relative(rel);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(_extract_single_file_response(content,rel),encoding='utf-8')
        replay_ok,replay_out=_replay_validation_for_failure(clone,user_request or '',manifest or {},validation_failure)
        if not replay_ok and _runtime_failure_still_present(validation_failure,replay_out):
            return (
                'V42.16 transactional compiler gate: candidate is parseable but the exact proven build/test failure remains unchanged in the disposable project. '
                'Jarvis will not commit a no-progress non-Python repair. Replay evidence:\n'+str(replay_out or '')[-3500:]
            )
    except Exception as exc:
        # Failure to construct a disposable replay is not permission to skip syntax safety,
        # but it also must not falsely reject a valid candidate because a host tool is unavailable.
        try:_append_project_event(work,'v4216_replay_warning',f'Non-Python candidate replay unavailable for {rel}: {exc}',file=rel)
        except Exception:pass
    finally:
        if temp is not None:
            try:temp.cleanup()
            except Exception:pass
    return ''


# Late-bound universal transaction wrapper: all inherited ownership/import/config gates
# still run first, then every language gets syntax validation and non-Python real-failure replay.
_v4216_prev_candidate_transaction_error=_candidate_transaction_error

def _candidate_transaction_error(work,manifest,rel,content,user_request=None,validation_failure=None,target_problems=None):
    base=_v4216_prev_candidate_transaction_error(work,manifest,rel,content,user_request=user_request,validation_failure=validation_failure,target_problems=target_problems)
    if base:return base
    err=_v4216_language_syntax_error(work,manifest or {},rel,content)
    if err:return err
    return _v4216_nonpython_replay_error(work,manifest or {},_v40_norm_rel(rel),content,user_request,validation_failure)


def _v4216_component_for_rel(manifest,rel):
    try:return _v429_component_for_rel(manifest or {},rel)
    except Exception:return None


def _v4216_validate_production_component(work,manifest,rel):
    """Fast production-only build check. Returns None when no safe local command is available."""
    comp=_v4216_component_for_rel(manifest,rel)
    if not isinstance(comp,dict):return None
    root=_v40_norm_rel(comp.get('root')) or '.';cwd=Path(work) if root=='.' else Path(work)/root
    if not cwd.exists():return None
    adapter=_v361_normalize_component_adapter(comp.get('toolchain_adapter'))
    cmd=None
    if adapter in {'rust','tauri'} and (cwd/'Cargo.toml').exists():
        cargo=shutil.which('cargo')
        if cargo:cmd=[cargo,'check','--lib','--bins','--message-format','short']
    elif adapter in _V4214_NODE_ADAPTERS and (cwd/'package.json').exists():
        npm=shutil.which('npm')
        try:data=json.loads((cwd/'package.json').read_text(encoding='utf-8',errors='replace'));scripts=data.get('scripts') or {}
        except Exception:scripts={}
        if npm and scripts.get('build'):cmd=[npm,'run','build']
        else:
            tsc=cwd/'node_modules'/'.bin'/('tsc.cmd' if os.name=='nt' else 'tsc')
            if tsc.exists():cmd=[str(tsc),'--noEmit','--pretty','false','-p','tsconfig.json']
    elif adapter=='go' and (cwd/'go.mod').exists():
        go=shutil.which('go')
        if go:cmd=[go,'build','./...']
    elif adapter in {'dotnet','csharp','wpf','winforms','fsharp'}:
        dotnet=shutil.which('dotnet');target=next(iter(cwd.glob('*.sln')),None) or next(iter(cwd.glob('*.csproj')),None)
        if dotnet and target:cmd=[dotnet,'build',str(target),'--no-restore','--nologo']
    elif adapter in {'java_gradle','kotlin_gradle','android_gradle'}:
        wrapper=cwd/('gradlew.bat' if os.name=='nt' else 'gradlew');gradle=str(wrapper) if wrapper.exists() else shutil.which('gradle')
        if gradle:cmd=[gradle,'assembleDebug' if adapter=='android_gradle' else 'classes','--no-daemon']
    elif adapter=='java_maven' and (cwd/'pom.xml').exists():
        mvnw=cwd/('mvnw.cmd' if os.name=='nt' else 'mvnw');mvn=str(mvnw) if mvnw.exists() else shutil.which('mvn')
        if mvn:cmd=[mvn,'-DskipTests','package','-B']
    elif adapter=='swiftpm' and (cwd/'Package.swift').exists():
        swift=shutil.which('swift')
        if swift:cmd=[swift,'build']
    elif adapter=='flutter' and (cwd/'pubspec.yaml').exists():
        flutter=shutil.which('flutter')
        if flutter:cmd=[flutter,'analyze']
    elif adapter=='dart' and (cwd/'pubspec.yaml').exists():
        dart=shutil.which('dart')
        if dart:cmd=[dart,'analyze']
    if not cmd:return None
    return _run_command(cmd,cwd,V4216_PRODUCTION_CHECK_TIMEOUT)


def _v4216_production_blockers(work,manifest,user_request='',limit=20):
    """Concrete non-test blockers that must be resolved before acceptance-test repair."""
    root=Path(work);out=[];seen=set()
    def add(rel,kind,problem):
        rel=_v40_norm_rel(rel);key=(rel,kind,re.sub(r'\s+',' ',str(problem or '')).strip().lower())
        if key in seen:return
        seen.add(key);out.append({'file':rel,'kind':kind,'problem':str(problem or '')})
    rows=[x for x in (manifest or {}).get('files') or [] if isinstance(x,dict) and x.get('path')]
    for item in rows:
        rel=_v40_norm_rel(item.get('path'))
        if _v4216_is_test_rel(rel):continue
        p=root/rel
        phase=str(item.get('phase') or '').lower()
        if phase=='docs':continue
        if not p.exists():add(rel,'missing','Production file is missing.');continue
        if _looks_text_file(p):
            try:text=p.read_text(encoding='utf-8',errors='replace')
            except Exception:continue
            err=_v4216_language_syntax_error(work,manifest or {},rel,text)
            if err:add(rel,'language_syntax',err)
        if len(out)>=limit:return out[:limit]
    # Canonical providers are production authority and outrank tests.
    try:
        for row in _v40_domain_owner_payload(manifest or {}).get('owners') or []:
            rel=_v40_norm_rel(row.get('provider'))
            if not rel or _v4216_is_test_rel(rel):continue
            problem=_v424_provider_state_problem(work,manifest or {},rel)
            if problem:add(rel,'canonical_provider',problem)
            if len(out)>=limit:return out[:limit]
    except Exception:pass
    return out[:limit]


# Tests are consumers. If production is syntactically/build broken, redirect the repair budget
# to the first real production blocker instead of editing assertions around broken code.
_v4216_prev_repair_file_for_issues=_repair_file_for_issues

def _repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback=None,validation_failure=None):
    rel=_v40_norm_rel(rel)
    if V4216_PRODUCTION_BEFORE_TESTS and _v4216_is_test_rel(rel):
        blockers=_v4216_production_blockers(work,manifest or {},user_request)
        prodcheck=_v4216_validate_production_component(work,manifest or {},rel)
        if blockers or (prodcheck is not None and not prodcheck[0]):
            evidence=list(blockers)
            if prodcheck is not None and not prodcheck[0]:
                evidence.append({'file':'','kind':'production_build','problem':str(prodcheck[1] or '')[-6000:]})
            _append_project_event(work,'v4216_test_repair_deferred',f'V42.16 deferred test repair for {rel} because production is not compiler-clean.',file=rel,blockers=evidence[:10])
            _progress(progress_callback,f'V42.16 production-before-tests: deferring {rel}; repairing production/build blockers first.',stage='V42.16 production repair',percent=79,current_file=rel)
            first=next((x for x in blockers if x.get('file') and (Path(work)/x.get('file')).exists()),None)
            if first and _v40_norm_rel(first.get('file'))!=rel:
                return bool(_v4216_prev_repair_file_for_issues(user_request,manifest,work,_v40_norm_rel(first.get('file')),[str(first.get('problem') or '')],progress_callback,validation_failure=str(first.get('problem') or '')))
            if prodcheck is not None and not prodcheck[0]:
                try:return bool(_repair_real_validation_failure(user_request,manifest,work,str(prodcheck[1] or ''),progress_callback))
                except Exception:return False
            return False
    return bool(_v4216_prev_repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback,validation_failure=validation_failure))


# Production issues always sort ahead of test consumers in whole-project convergence.
_v4216_prev_issue_priority=_v429_issue_priority

def _v429_issue_priority(manifest,row):
    base=_v4216_prev_issue_priority(manifest,row)
    rel=_v40_norm_rel((row or {}).get('file'))
    kind=str((row or {}).get('kind') or '')
    if kind=='language_syntax':return (-2,base[1],base[2],rel)
    if _v4216_is_test_rel(rel):return (50,base[1],base[2],rel)
    return base


# Extend whole-project audit with actual language parser evidence for every authored/planned source.
_v4216_prev_whole_project_audit=_v429_whole_project_audit

def _v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=None):
    payload=_v4216_prev_whole_project_audit(work,user_request,manifest,run_components,progress_callback)
    root=Path(work);issues=list(payload.get('issues') or []);seen={_v429_issue_key(x) for x in issues if isinstance(x,dict)}
    paths=[]
    for item in (manifest or {}).get('files') or []:
        if isinstance(item,dict) and item.get('path'):paths.append(_v40_norm_rel(item.get('path')))
    try:paths.extend(_existing_real_source_files(work))
    except Exception:pass
    checked=0
    for rel in list(dict.fromkeys(paths)):
        if checked>=V4216_AUDIT_SYNTAX_MAX_FILES:break
        p=root/rel
        if not p.exists() or not p.is_file() or not _looks_text_file(p):continue
        ext=p.suffix.lower()
        if ext not in _SOURCE_SUFFIXES and ext not in {'.json','.jsonc','.toml','.yaml','.yml'}:continue
        checked+=1
        try:text=p.read_text(encoding='utf-8',errors='replace')
        except Exception:continue
        err=_v4216_language_syntax_error(work,manifest or {},rel,text)
        if not err:continue
        row={'file':rel,'kind':'language_syntax','problem':err}
        key=_v429_issue_key(row)
        if key not in seen:seen.add(key);issues.append(row)
    payload['issues']=issues;payload['issue_count']=len(issues);payload['clean']=bool(not issues and all(x.get('ok') for x in payload.get('components') or []));payload['v4216_language_files_checked']=checked
    try:_v429_write_audit(work,payload)
    except Exception:pass
    try:_append_project_event(work,'v4216_language_audit',f'V42.16 parsed/structurally checked {checked} authored/planned language files; {sum(1 for x in issues if x.get("kind")=="language_syntax")} syntax/transport issue(s) remain.',checked=checked)
    except Exception:pass
    return payload


def _v4216_snapshot_authored(work):
    root=Path(work);snaps={}
    for p in root.rglob('*'):
        if not p.is_file():continue
        try:rel=p.relative_to(root)
        except Exception:continue
        if any(part in _ANALYSIS_IGNORE_DIRS or part in {'.git','node_modules','target','dist','build','.jarvis_runtime','.jarvis_build','.jarvis_candidates','.jarvis_failures'} for part in rel.parts):continue
        if not _looks_text_file(p):continue
        try:snaps[rel.as_posix()]=p.read_bytes()
        except Exception:pass
    return snaps


# Multi-file direct completion is atomic as a batch. If any changed file fails the same
# central green gate used everywhere else, roll the entire direct-edit batch back.
_v4216_prev_direct_completion_edit=_direct_completion_edit

def _direct_completion_edit(user_request,manifest,criteria,work,completed,unresolved=None,feedback=None,progress_callback=None):
    if not V4216_ATOMIC_DIRECT_EDIT:
        return _v4216_prev_direct_completion_edit(user_request,manifest,criteria,work,completed,unresolved,feedback,progress_callback)
    root=Path(work);snaps=_v4216_snapshot_authored(work);ledger_path=root/V413_ACCEPTED_LEDGER
    ledger_snap=ledger_path.read_bytes() if ledger_path.exists() else None
    result=_v4216_prev_direct_completion_edit(user_request,manifest,criteria,work,completed,unresolved,feedback,progress_callback)
    changed=[_v40_norm_rel(x) for x in (result or {}).get('changed') or []]
    errors=[]
    for rel in changed:
        err=_v401_file_green_error(work,manifest or {},rel)
        if err:errors.append(f'{rel}: {err}')
    if errors:
        for rel in changed:
            p=root/rel
            if rel in snaps:
                p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(snaps[rel])
            else:
                try:p.unlink(missing_ok=True)
                except Exception:pass
        try:
            if ledger_snap is None:ledger_path.unlink(missing_ok=True)
            else:ledger_path.write_bytes(ledger_snap)
        except Exception:pass
        _append_project_event(work,'v4216_direct_edit_batch_rollback','V42.16 rolled back an entire multi-file direct edit because at least one replacement failed the universal commit gate.',errors=errors[:12],files=changed)
        return {'changed':[],'reason':'V42.16 atomic direct-edit rollback: '+'; '.join(errors[:8]),'summary':(result or {}).get('summary','')}
    return result


