# =============================================================================
# V42.17 EXHAUSTED-BLOCKER CONVERGENCE / CONTEXT PARSER / ASSET RECOVERY
# =============================================================================
# Live GearTrack regression (2026-09-01): transactional source protection worked,
# but an exhausted malformed TSX blocker could strand endgame orchestration while
# the language audit repeatedly reparsed unchanged green files.  Rust module
# aggregators were also parsed outside their module tree, producing false failures,
# and required binary Tauri assets could remain absent even though Jarvis already
# owns deterministic PNG/ICO generation.
#
# V42.17 keeps V42.16's transactional gate and adds four stack-agnostic convergence
# rules:
#   1. cache parser results by source + parser-context hash so unchanged green files
#      are not repeatedly executed/logged;
#   2. parse Rust in a preserved module-tree context instead of an orphan temp file;
#   3. recover mechanically obvious duplicated JSX/TSX fragments transactionally;
#   4. when the current blocker is subsystem-exhausted, run one fresh root-cause
#      recovery/build attempt and then boundedly stop with that blocker -- never
#      spend endgame cycles validating unrelated unchanged files.

V4217_VERSION = '42.17.0'
V4217_ENGINE = 'EXHAUSTED_BLOCKER_CONVERGENCE_CONTEXT_PARSER_ASSET_RECOVERY'
V4217_PARSER_CACHE = os.getenv('JARVIS_V4217_PARSER_CACHE','1').strip().lower() not in {'0','false','no','off'}
V4217_MECHANICAL_REPAIR = os.getenv('JARVIS_V4217_MECHANICAL_REPAIR','1').strip().lower() not in {'0','false','no','off'}
V4217_REQUIRED_ASSET_RECOVERY = os.getenv('JARVIS_V4217_REQUIRED_ASSET_RECOVERY','1').strip().lower() not in {'0','false','no','off'}
V4217_EXHAUSTED_ROOT_ATTEMPTS = max(1,min(2,int(os.getenv('JARVIS_V4217_EXHAUSTED_ROOT_ATTEMPTS','1'))))
V4217_EXHAUSTED_CONVERGENCE_ROUNDS = max(1,min(3,int(os.getenv('JARVIS_V4217_EXHAUSTED_CONVERGENCE_ROUNDS','2'))))
V4217_CACHE_FILE = '.jarvis_runtime/v4217_parser_cache.json'
V4217_STATE_FILE = '.jarvis_runtime/v4217_convergence_state.json'


def _v4217_json_state(work, rel, default=None):
    default = {} if default is None else default
    try:
        p = Path(work) / rel
        if p.exists():
            data = json.loads(p.read_text(encoding='utf-8', errors='replace'))
            if isinstance(data, dict): return data
    except Exception: pass
    return dict(default)


def _v4217_save_json_state(work, rel, data):
    try:
        p = Path(work) / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        tmp = p.with_name(p.name + '.tmp')
        tmp.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')
        tmp.replace(p)
    except Exception: pass


def _v4217_component_root(work, manifest, rel):
    try: root = _v362_component_root_for_rel(manifest or {}, rel)
    except Exception: root = '.'
    root = _v40_norm_rel(root) or '.'
    return Path(work) if root == '.' else Path(work) / root


def _v4217_rust_edition(component_root):
    try:
        text = (Path(component_root)/'Cargo.toml').read_text(encoding='utf-8', errors='replace')
        m = re.search(r'(?m)^\s*edition\s*=\s*["\'](2015|2018|2021|2024)["\']', text)
        if m: return m.group(1)
    except Exception: pass
    return '2021'


def _v4217_rust_context_digest(work, manifest, rel, content):
    """Digest the local Rust module tree so cache entries invalidate when siblings change."""
    try:
        root = _v4217_component_root(work, manifest, rel)
        rows=[]
        for i,p in enumerate(sorted(root.rglob('*.rs'))):
            if i >= 600: break
            try:
                rp=p.relative_to(root).as_posix()
                if _v40_norm_rel(str(Path(root).relative_to(Path(work)) / rp)) == _v40_norm_rel(rel):
                    payload=str(content or '').encode('utf-8',errors='replace')
                else: payload=p.read_bytes()
                rows.append((rp,hashlib.sha256(payload).hexdigest()[:16]))
            except Exception: continue
        return hashlib.sha256(repr(rows).encode('utf-8',errors='replace')).hexdigest()[:20]
    except Exception: return 'rust-context-unknown'


def _v4217_parser_cache_key(work, manifest, rel, content):
    ext=Path(rel).suffix.lower()
    body=hashlib.sha256(str(content or '').encode('utf-8',errors='replace')).hexdigest()
    context='isolated'
    if ext=='.rs' and work is not None:
        context=_v4217_rust_context_digest(work,manifest or {},rel,content)
    elif ext in {'.ts','.tsx','.mts','.cts'} and work is not None:
        try:
            root=_v4217_component_root(work,manifest or {},rel)
            pkg=root/'node_modules'/'typescript'/'package.json'
            context=hashlib.sha256(pkg.read_bytes()).hexdigest()[:20] if pkg.exists() else 'typescript-unavailable'
        except Exception: context='typescript-context-unknown'
    material='|'.join((_v40_norm_rel(rel),body,context))
    return hashlib.sha256(material.encode('utf-8',errors='replace')).hexdigest()


def _v4217_rust_context_syntax_error(work, manifest, rel, content):
    """Run rustfmt against a disposable preserved module tree, never an orphan mod.rs."""
    rustfmt=shutil.which('rustfmt')
    if not rustfmt or work is None: return ''
    component=_v4217_component_root(work,manifest or {},rel)
    if not component.exists(): return ''
    try:
        target_abs=Path(work)/_safe_relative(rel)
        target_rel=target_abs.relative_to(component)
    except Exception:
        return ''
    td=tempfile.mkdtemp(prefix='jarvis_v4217_rustctx_')
    try:
        clone=Path(td)/'component'; clone.mkdir(parents=True,exist_ok=True)
        copied=0
        for p in component.rglob('*.rs'):
            if copied>=800: break
            try:
                rp=p.relative_to(component); dst=clone/rp; dst.parent.mkdir(parents=True,exist_ok=True); dst.write_bytes(p.read_bytes()); copied+=1
            except Exception: continue
        staged=clone/target_rel; staged.parent.mkdir(parents=True,exist_ok=True); staged.write_text(str(content or ''),encoding='utf-8')
        edition=_v4217_rust_edition(component)
        ok,out=_run_command([rustfmt,'--edition',edition,'--emit','stdout',str(staged)],clone,V4216_PARSER_TIMEOUT)
        if not ok:
            return f'V42.17 Rust context syntax gate: {rel} failed rustfmt inside its preserved module tree: {str(out or "")[-1800:]}'
        return ''
    except Exception as exc:
        try:_append_project_event(work,'v4217_rust_parser_warning',f'Context-aware Rust parser could not run for {rel}: {exc}',file=rel)
        except Exception:pass
        return ''
    finally:
        shutil.rmtree(td,ignore_errors=True)


_v4217_prev_language_syntax_error = _v4216_language_syntax_error

def _v4216_language_syntax_error(work,manifest,rel,content):
    rel=_v40_norm_rel(rel);text=_extract_single_file_response(content,rel)
    cache_key=None;cache=None
    if V4217_PARSER_CACHE and work is not None:
        cache_key=_v4217_parser_cache_key(work,manifest or {},rel,text)
        cache=_v4217_json_state(work,V4217_CACHE_FILE,{})
        row=cache.get(cache_key)
        if isinstance(row,dict) and row.get('rel')==rel and 'error' in row:
            return str(row.get('error') or '')
    if Path(rel).suffix.lower()=='.rs' and work is not None:
        # Reuse V42.16 transport/config checks but bypass its orphan Rust temp parse.
        contamination=_v4216_source_transport_contamination(rel,text)
        err=contamination or _v4217_rust_context_syntax_error(work,manifest or {},rel,text)
    else:
        err=_v4217_prev_language_syntax_error(work,manifest or {},rel,text)
    if cache_key and cache is not None:
        cache[cache_key]={'rel':rel,'error':str(err or ''),'at':_utc_stamp()}
        # Keep cache bounded; oldest insertion order is sufficient for diagnostics.
        if len(cache)>5000:
            for k in list(cache.keys())[:len(cache)-4000]:cache.pop(k,None)
        _v4217_save_json_state(work,V4217_CACHE_FILE,cache)
    return str(err or '')


def _v4217_jsx_attr_name(line):
    s=str(line or '').strip()
    m=re.match(r'^([A-Za-z_$][\w$:-]*)\s*(?:=|$)',s)
    return m.group(1) if m else ''


def _v4217_mechanical_jsx_candidate(text):
    """Conservatively remove exact duplicate JSX attrs and a duplicated attr-tail after />.

    This targets corruption shaped like GearTrack's repeated <input> body.  It never
    guesses between conflicting attribute values and therefore refuses ambiguous edits.
    """
    lines=str(text or '').splitlines(keepends=True)
    if not lines:return str(text or ''),False
    changed=False;i=0
    while i<len(lines):
        s=lines[i].lstrip()
        if not re.match(r'^<[A-Za-z][\w.:-]*(?:\s|$)',s) or s.startswith('</'):
            i+=1;continue
        start=i;end=None
        for j in range(i,min(len(lines),i+120)):
            st=lines[j].strip()
            if '/>' in st or (j>start and st=='>'):
                end=j;break
        if end is None:i+=1;continue
        seen={};remove=[]
        for j in range(start+1,end):
            name=_v4217_jsx_attr_name(lines[j])
            if not name:continue
            norm=re.sub(r'\s+',' ',lines[j].strip())
            if name in seen:
                prev_j,prev_norm=seen[name]
                if prev_norm==norm:remove.append(j)
                else:
                    # Conflicting duplicate attrs are semantic; leave them for the model/compiler.
                    seen[name]=(j,norm)
            else:seen[name]=(j,norm)
        if remove:
            for j in reversed(remove):lines.pop(j);end-=1
            changed=True
        attrs=[re.sub(r'\s+',' ',x.strip()) for x in lines[start+1:end] if x.strip()]
        # Detect a second dangling copy of a suffix of the just-closed attribute body.
        k=end+1
        while k<len(lines) and not lines[k].strip():k+=1
        if k<len(lines) and not lines[k].lstrip().startswith('<'):
            close2=None
            for j in range(k,min(len(lines),k+120)):
                if lines[j].strip()=='/>':close2=j;break
                if lines[j].lstrip().startswith('<'):break
            if close2 is not None:
                dangling=[re.sub(r'\s+',' ',x.strip()) for x in lines[k:close2] if x.strip()]
                if dangling and len(dangling)<=len(attrs) and attrs[-len(dangling):]==dangling:
                    del lines[k:close2+1];changed=True
                    end=k-1
        i=max(i+1,end+1)
    return ''.join(lines),changed


def _v4217_try_mechanical_source_repair(work,manifest,rel,problems=None):
    if not V4217_MECHANICAL_REPAIR:return False
    ext=Path(rel).suffix.lower()
    if ext not in {'.tsx','.jsx'}:return False
    path=Path(work)/_safe_relative(rel)
    if not path.exists() or not path.is_file():return False
    try:original=path.read_text(encoding='utf-8',errors='replace')
    except Exception:return False
    candidate,changed=_v4217_mechanical_jsx_candidate(original)
    if not changed or candidate==original:return False
    # Mechanical changes are authoritative only when they improve parser evidence.
    before=_v4217_prev_language_syntax_error(work,manifest or {},rel,original)
    after=_v4217_prev_language_syntax_error(work,manifest or {},rel,candidate)
    if after or (not before and after==before):
        _append_project_event(work,'v4217_mechanical_repair_rejected',f'Rejected deterministic JSX de-duplication for {rel}; parser evidence did not become green.',file=rel,before=str(before or '')[-1200:],after=str(after or '')[-1200:])
        return False
    _v36_checkpoint_file(work,rel,original,'before_v4217_mechanical_repair')
    tmp=path.with_name(path.name+'.jarvis_v4217_tmp')
    try:
        tmp.write_text(candidate,encoding='utf-8');tmp.replace(path)
        try:_v413_mark_accepted(work,rel,'v4217_mechanical_duplicate_recovery')
        except Exception:pass
        try:_v36_build_repo_graph(work,manifest,write=True);_v36_build_contract_registry(work,manifest,write=True)
        except Exception:pass
        _append_project_event(work,'v4217_mechanical_repair_committed',f'Deterministically removed mechanically provable duplicated JSX fragments from {rel}.',file=rel)
        return True
    except Exception:
        try:tmp.unlink(missing_ok=True)
        except Exception:pass
        return False


def _v4217_asset_refs(work,manifest):
    """Find missing deterministic PNG/ICO references in known project config files."""
    if not V4217_REQUIRED_ASSET_RECOVERY:return []
    root=Path(work);refs=[]
    # Planned binary assets are always safe deterministic obligations.
    for item in (manifest or {}).get('files') or []:
        if not isinstance(item,dict):continue
        rel=_v40_norm_rel(item.get('path'))
        if rel and Path(rel).suffix.lower() in set(globals().get('V381_BINARY_ASSET_EXTS',{'.png','.ico'})) and not (root/rel).exists():refs.append(rel)
    # Tauri and common desktop config may reference binary assets that planning omitted.
    configs=[]
    for name in ('tauri.conf.json','tauri.conf.json5','package.json'):
        try:configs.extend(root.rglob(name))
        except Exception:pass
    pat=re.compile(r'["\']([^"\']+\.(?:png|ico))["\']',re.I)
    for cfg in configs[:40]:
        try:text=cfg.read_text(encoding='utf-8',errors='replace')
        except Exception:continue
        for raw in pat.findall(text):
            raw=raw.replace('\\','/').strip()
            if '://' in raw or raw.startswith(('data:','http:','https:')):continue
            try:
                cand=(cfg.parent/raw).resolve();rel=cand.relative_to(root.resolve()).as_posix()
            except Exception:continue
            if not cand.exists():refs.append(rel)
    return list(dict.fromkeys(refs))[:32]


def _v4217_recover_required_assets(work,manifest,progress_callback=None):
    changed=[]
    for rel in _v4217_asset_refs(work,manifest or {}):
        try:
            if _v381_materialize_binary_asset(work,rel):changed.append(rel)
        except Exception:continue
    if changed:
        _append_project_event(work,'v4217_required_assets_recovered',f'V42.17 deterministically materialized {len(changed)} missing required binary asset(s) before build.',files=changed)
        _progress(progress_callback,f'V42.17 deterministic asset recovery: created {len(changed)} missing required project asset(s).',stage='V42.17 asset recovery',percent=79)
    return changed


def _v4217_exact_exhausted_entry(work,rel,problems,validation_failure=''):
    try:
        state=_v381_load_repair_state(work);entry=(state.get('files') or {}).get(str(rel)) or {}
        sig=_v381_repair_signature(rel,problems or [],validation_failure or '')
        row=entry.get(sig)
        if isinstance(row,dict) and row.get('subsystem_exhausted'):return sig,row
        # Validation wrappers may normalize evidence differently. Only fall back to
        # another exhausted signature when every recorded signature for this file is exhausted.
        rows=[(k,v) for k,v in entry.items() if isinstance(v,dict)]
        exhausted=[x for x in rows if x[1].get('subsystem_exhausted')]
        if rows and len(exhausted)==len(rows):return exhausted[-1]
    except Exception:pass
    return None,None


def _v4217_fresh_exhausted_recovery(user_request,manifest,work,rel,problems,progress_callback=None,validation_failure=None):
    """One alternate transaction for an exhausted blocker at an unchanged source hash."""
    rel=_v40_norm_rel(rel);path=Path(work)/_safe_relative(rel)
    if not path.exists():return False
    try:content_hash=hashlib.sha256(path.read_bytes()).hexdigest()[:24]
    except Exception:return False
    state=_v4217_json_state(work,V4217_STATE_FILE,{})
    key=hashlib.sha256((rel+'|'+content_hash+'|'+_v381_repair_signature(rel,problems or [],validation_failure or '')).encode()).hexdigest()[:28]
    attempts=int((state.get('exhausted_root_attempts') or {}).get(key) or 0)
    if attempts>=V4217_EXHAUSTED_ROOT_ATTEMPTS:return False
    state.setdefault('exhausted_root_attempts',{})[key]=attempts+1;_v4217_save_json_state(work,V4217_STATE_FILE,state)
    if _v4217_try_mechanical_source_repair(work,manifest,rel,problems):return True
    fresh_problems=list(problems or [])+[\
        'V42.17 FRESH EXHAUSTED-BLOCKER STRATEGY: previous local patch and subsystem transaction are exhausted at this exact accepted revision. '
        'Re-read the complete target and its immediate contracts, discard the previously attempted patch shape, and make one different root-cause correction. '
        'For malformed syntax, reconstruct the smallest complete syntactic construct rather than appending another fragment. The candidate must pass the transactional parser/build gate.'
    ]
    _progress(progress_callback,f'V42.17 exhausted blocker recovery: switching strategy for {rel} instead of validating unrelated green files.',stage='V42.17 exhausted blocker recovery',percent=82,current_file=rel)
    try:
        ok=bool(_v381_base_repair_file_for_issues(user_request,manifest,work,rel,fresh_problems,progress_callback,validation_failure))
    except Exception:ok=False
    _append_project_event(work,'v4217_exhausted_root_attempt',f'V42.17 ran one fresh root-cause transaction for exhausted blocker {rel}; result={ok}.',file=rel,success=ok,content_hash=content_hash)
    return ok


_v4217_prev_repair_file_for_issues = _repair_file_for_issues

def _repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback=None,validation_failure=None):
    rel=_v40_norm_rel(rel)
    sig,row=_v4217_exact_exhausted_entry(work,rel,problems,validation_failure or '')
    if row is not None:
        if _v4217_fresh_exhausted_recovery(user_request,manifest,work,rel,problems,progress_callback,validation_failure):
            return True
        _append_project_event(work,'v4217_exhausted_leaf_suppressed',f'V42.17 kept exhausted blocker {rel} quarantined after alternate recovery was consumed; unrelated leaf validation will not be treated as progress.',file=rel,signature=sig)
        return False
    return bool(_v4217_prev_repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback,validation_failure=validation_failure))


_v4217_prev_real_validation_failure = _repair_real_validation_failure

def _repair_real_validation_failure(user_request,manifest,work,failure,progress_callback=None):
    # Missing deterministic binary assets are build-system obligations, not model work.
    low=str(failure or '').lower()
    if any(ext in low for ext in ('.ico','.png')):
        changed=_v4217_recover_required_assets(work,manifest or {},progress_callback)
        if changed:return True
    return bool(_v4217_prev_real_validation_failure(user_request,manifest,work,failure,progress_callback))


def _v4217_exhausted_audit_rows(work,audit):
    out=[]
    for row in (audit or {}).get('issues') or []:
        rel=_v40_norm_rel((row or {}).get('file'))
        if not rel:continue
        _sig,entry=_v4217_exact_exhausted_entry(work,rel,[str((row or {}).get('problem') or '')],str((row or {}).get('problem') or ''))
        if entry is not None:out.append(row)
    return out


_v4217_prev_whole_project_convergence = _v429_whole_project_convergence

def _v429_whole_project_convergence(user_request,manifest,work,progress_callback=None):
    if not V429_WHOLE_PROJECT_AUDIT:return True,[]
    _v4217_recover_required_assets(work,manifest or {},progress_callback)
    probe=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
    if probe.get('clean'):return True,[]
    exhausted=_v4217_exhausted_audit_rows(work,probe)
    if not exhausted:
        return _v4217_prev_whole_project_convergence(user_request,manifest,work,progress_callback)
    last_sig='';last_token=''
    for round_no in range(1,V4217_EXHAUSTED_CONVERGENCE_ROUNDS+1):
        audit=probe if round_no==1 else _v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
        if audit.get('clean'):return True,[]
        exhausted=_v4217_exhausted_audit_rows(work,audit)
        if not exhausted:
            # The exhausted root was cleared; return to normal root-ordered convergence.
            return _v4217_prev_whole_project_convergence(user_request,manifest,work,progress_callback)
        token_before=_v429_progress_token(work)
        sig=hashlib.sha256(json.dumps([_v429_issue_key(x) for x in exhausted],sort_keys=True,default=str).encode()).hexdigest()[:20]
        _progress(progress_callback,f'V42.17 exhausted-blocker convergence {round_no}/{V4217_EXHAUSTED_CONVERGENCE_ROUNDS}: focusing {len(exhausted)} quarantined blocker(s); unchanged green files are cache-skipped.',stage='V42.17 exhausted blocker convergence',percent=min(94,84+round_no*4))
        changed=False
        for row in sorted(exhausted,key=lambda x:_v429_issue_priority(manifest,x))[:3]:
            rel=_v40_norm_rel(row.get('file'));problem=str(row.get('problem') or '')
            try:
                if _repair_file_for_issues(user_request,manifest,work,rel,[problem],progress_callback,validation_failure=problem):changed=True;break
            except Exception:pass
            # If source-level recovery cannot move, obtain fresh authoritative component build evidence once.
            try:
                comp=_v4216_validate_production_component(work,manifest or {},rel)
                if comp is not None and not comp[0] and _repair_real_validation_failure(user_request,manifest,work,str(comp[1] or ''),progress_callback):changed=True;break
            except Exception:pass
        if changed:
            probe=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
            if probe.get('clean'):return True,[]
            continue
        token_after=_v429_progress_token(work)
        if sig==last_sig and token_after==token_before and token_before==last_token:
            final=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
            _append_project_event(work,'v4217_exhausted_blocker_stop','V42.17 boundedly stopped an unchanged exhausted blocker instead of revalidating unrelated green files.',signature=sig,accepted_token=token_after,blockers=exhausted[:12])
            return False,list(final.get('issues') or [])
        last_sig,last_token=sig,token_after
    final=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
    _append_project_event(work,'v4217_exhausted_blocker_stop','V42.17 consumed the bounded alternate/root-build budget and stopped with exact unresolved evidence.',accepted_token=_v429_progress_token(work),blockers=_v4217_exhausted_audit_rows(work,final)[:12])
    return bool(final.get('clean')),list(final.get('issues') or [])


_v4217_prev_whole_project_audit = _v429_whole_project_audit

def _v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=None):
    # Required binary assets are deterministic substrate and should exist before a real build.
    _v4217_recover_required_assets(work,manifest or {},progress_callback)
    return _v4217_prev_whole_project_audit(work,user_request,manifest,run_components,progress_callback)


