if 'JARVIS_QWEN_TARGETED_REPAIR_ATTEMPTS' not in os.environ:
    TARGETED_REPAIR_ATTEMPTS = min(int(TARGETED_REPAIR_ATTEMPTS), 3)
# Per-file model semantic auditing is expensive and weaker than real build/test
# evidence. Keep it available as an opt-in diagnostic, not a default publish gate.
if 'JARVIS_QWEN_FILE_AUDIT' not in os.environ:
    QWEN_FILE_AUDIT = False


def _v4219_json(path, default=None):
    try:
        d=json.loads(Path(path).read_text(encoding='utf-8',errors='replace'))
        return d if isinstance(d,(dict,list)) else (default if default is not None else {})
    except Exception:
        return default if default is not None else {}


def _v4219_tombstones(work):
    data=_v4219_json(Path(work)/V4219_TOMBSTONE_FILE,{})
    return data if isinstance(data,dict) else {}


def _v4219_save_tombstones(work,data):
    p=Path(work)/V4219_TOMBSTONE_FILE;p.parent.mkdir(parents=True,exist_ok=True)
    payload=dict(data or {});payload['version']='V'+V4219_VERSION;payload['updated_at']=_utc_stamp()
    try:p.write_text(json.dumps(payload,indent=2,ensure_ascii=False,default=str)+'\n',encoding='utf-8')
    except Exception:pass


def _v4219_add_tombstone(work,rel,reason):
    rel=_v40_norm_rel(rel)
    if not rel:return
    data=_v4219_tombstones(work);rows=dict(data.get('paths') or {})
    rows[rel]={'reason':str(reason or '')[:1800],'at':_utc_stamp()};data['paths']=rows
    _v4219_save_tombstones(work,data)


def _v4219_is_tombstoned(work,rel):
    rel=_v40_norm_rel(rel)
    return bool(rel and rel in ((_v4219_tombstones(work).get('paths') or {})))


def _v4219_reconcile_manifest_topology(work,manifest):
    """Make current repo topology authoritative and persist invalid old aliases.

    Rust permits `foo.rs` OR `foo/mod.rs` for one module root. Once the actual
    repository proves the directory module canonical, a historical manifest row
    for the flat alias is retired instead of being regenerated forever.
    """
    if not isinstance(manifest,dict):return []
    changed=[];kept=[];dropped=set()
    for item in list(manifest.get('files') or []):
        if not isinstance(item,dict):continue
        rel=_v40_norm_rel(item.get('path'))
        if not rel:continue
        reason=''
        try:reason=_v4215_flat_aggregate_reason(work,rel,manifest)
        except Exception:reason=''
        if reason:
            dropped.add(rel);changed.append({'path':rel,'reason':reason});_v4219_add_tombstone(work,rel,reason)
            try:
                if (Path(work)/rel).exists():_v4215_backup_and_remove(work,rel,reason,'v4219_topology')
            except Exception:pass
            continue
        if _v4219_is_tombstoned(work,rel):
            # A tombstone is revisitable only if its canonical conflicting topology vanished.
            stem=rel[:-3] if rel.lower().endswith('.rs') else ''
            if stem and (Path(work)/stem/'mod.rs').exists():
                dropped.add(rel);continue
        kept.append(dict(item))
    if dropped:
        for row in kept:
            row['depends_on']=[d for d in (row.get('depends_on') or []) if _v40_norm_rel(d) not in dropped]
        manifest['files']=kept
        manifest['implementation_order']=[x for x in (manifest.get('implementation_order') or []) if _v40_norm_rel(x) not in dropped]
        try:_v4215_prune_accepted_ledger(work,manifest)
        except Exception:pass
        try:_v33_write_architecture(work,manifest)
        except Exception:pass
        _append_project_event(work,'v4219_topology_tombstone',f'V42.19 retired {len(dropped)} stale/competing manifest path(s) from current topology.',paths=sorted(dropped),details=changed[:20])
    return changed


_v4219_prev_missing_manifest_files = _missing_manifest_files

def _missing_manifest_files(work,manifest):
    _v4219_reconcile_manifest_topology(work,manifest)
    rows=[]
    for rel in _v4219_prev_missing_manifest_files(work,manifest):
        rel=_v40_norm_rel(rel)
        if not rel or rel=='.' or _v4219_is_tombstoned(work,rel):continue
        # Missing tests invented by planning are soft unless the user explicitly
        # asked for tests. Existing tests still run through native test commands.
        req=str((manifest or {}).get('_original_user_request') or '')
        if _v4216_is_test_rel(rel) and not _explicit_tests_requested(req):
            continue
        rows.append(rel)
    # Production files always materialize before explicitly requested test files.
    prod=[x for x in rows if not _v4216_is_test_rel(x)]
    return prod if prod else rows


