def _v4210_write_tsconfig_node(work,rel='tsconfig.node.json'):
    p=Path(work)/_safe_relative(rel);p.parent.mkdir(parents=True,exist_ok=True)
    data=_v4218_default_tsconfig_node(p.parent)
