# AUTO routing: routine generation (including acceptance/test source emission) is
# always the 9B worker. The 27B only reasons on true architecture/root-cause work.
_v4219_prev_auto_target = _v426_auto_target

def _v426_auto_target(stage,call_profile,prompt):
    if not V4219_FAST_ROUTING:return _v4219_prev_auto_target(stage,call_profile,prompt)
    s=str(stage or '').lower();p=str(call_profile or 'chat').lower()
    # High-volume exact output never needs the specialist merely because its path
    # or stage contains the word "acceptance".
    if p in {'generate','chat'} or any(x in s for x in ('generating tests/','generating src-tauri/tests/','acceptance.test','acceptance_')):
        _v426_record_stage(stage);return V426_AUTO_WORKER,'V42.19 fast routine source/test emission'
    hard=('root cause','root-cause','architecture collision','architect/debugger','subsystem','contract reconciliation','ownership collision','cross-component integration','global convergence','canonical provider conflict')
    if any(x in s for x in hard):
        _v426_record_stage(stage);return V426_AUTO_SPECIALIST,'V42.19 evidence-backed root-cause specialist'
    # First-pass repair/audit stays cheap; inherited promotion can still use 27B
    # only when a genuinely hard marker above is present.
    if p in {'repair','audit','reasoning'}:
        _v426_record_stage(stage);return V426_AUTO_WORKER,'V42.19 build-first fast diagnostic worker'
    return _v4219_prev_auto_target(stage,call_profile,prompt)


