        comp=_v429_component_for_rel(manifest,rel);cid=str((comp or {}).get('id') or (comp or {}).get('root') or '')
        row=((_v429_live_load(work).get('components') or {}).get(cid) or {})
        if row and row.get('last_ok') is False:return str(row.get('last_output') or '')
