def _v4221_overlay_tsc(work,manifest,rel,content):
    root=Path(work).resolve();comp=_v429_component_for_rel(manifest,rel)
    if not isinstance(comp,dict):return None,''
    adapter=_v361_normalize_component_adapter(comp.get('toolchain_adapter'))
    if adapter not in _V4214_NODE_ADAPTERS:return None,''
    croot=_v40_norm_rel(comp.get('root')) or '.';orig=root if croot=='.' else root/croot
    if not (orig/'tsconfig.json').exists():return None,''
    tsc=orig/'node_modules'/'.bin'/('tsc.cmd' if os.name=='nt' else 'tsc')
    if not tsc.exists():
        found=shutil.which('tsc')
        if not found:return None,''
        tsc=Path(found)
    overlay_parent=root/'.jarvis_runtime'/'v4221_overlay';overlay_parent.mkdir(parents=True,exist_ok=True)
    td=tempfile.mkdtemp(prefix='candidate_',dir=str(overlay_parent));clone=Path(td)/'project'
    ignore_names=set(_ANALYSIS_IGNORE_DIRS)|{'node_modules','target','dist','build','.git','.jarvis_runtime',CANDIDATE_DIR_NAME}
    def ign(_d,names):return [n for n in names if n in ignore_names]
    try:
        copy_source_tree(root,clone,ignore=ign)
        p=clone/_safe_relative(rel);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(_extract_single_file_response(content,rel),encoding='utf-8')
        ccwd=clone if croot=='.' else clone/croot
        ok,out=_run_command([str(tsc),'--noEmit','--pretty','false','-p','tsconfig.json'],ccwd,V4221_TS_DELTA_TIMEOUT)
        return bool(ok),str(out or '')
    except Exception as exc:return None,'V42.21 overlay unavailable: '+str(exc)
    finally:
        try:shutil.rmtree(td,ignore_errors=True)
        except Exception:pass


def _v4221_ts_error_delta_error(work,manifest,rel,content,validation_failure='',target_problems=None):
    if not V4221_TS_ERROR_DELTA_GATE or Path(_v40_norm_rel(rel)).suffix.lower() not in {'.ts','.tsx','.mts','.cts'}:return ''
    evidence=str(validation_failure or '')+'\n'+'\n'.join(str(x) for x in (target_problems or []))
    baseline=_v4221_ts_error_lines(evidence)
    if not baseline:
        baseline=_v4221_ts_error_lines(_v4221_latest_component_diag(work,manifest,rel))
    if not baseline:return ''
    ok,out=_v4221_overlay_tsc(work,manifest,rel,content)
    if ok is None:return ''
    if ok:return ''
    after=_v4221_ts_error_lines(out)
    if not after:return ''
    before_n=len(baseline);after_n=len(after)
    if after_n>before_n:
        return f'V42.21 compiler error-delta gate: candidate increases TypeScript errors from {before_n} to {after_n}; reject and preserve accepted source.'
    if after_n==before_n:
        old=set(baseline);new=set(after)
        target=Path(_v40_norm_rel(rel)).name.lower()
        old_target=sum(1 for x in baseline if target in x.lower());new_target=sum(1 for x in after if target in x.lower())
        if not (old_target and new_target<old_target and old!=new):
            return f'V42.21 compiler error-delta gate: candidate leaves TypeScript error count unchanged at {after_n}; this is not measurable progress.'
    return ''


_v4221_prev_repair_file_for_issues=_repair_file_for_issues

def _repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback=None,validation_failure=None):
    rel=_v40_norm_rel(rel);token=_v429_progress_token(work);sig=_v381_repair_signature(rel,problems or [],validation_failure or '')
    state_path=Path(work)/V4221_STATE_FILE
    try:state=json.loads(state_path.read_text(encoding='utf-8',errors='replace'))
    except Exception:state={}
    key=hashlib.sha256((token+'|'+rel+'|'+sig).encode()).hexdigest()[:28]
    row=(state.setdefault('repair_attempts',{})).setdefault(key,{'file':rel,'token':token,'signature':sig,'attempts':0})
    # Fast deterministic fixes get first refusal and do not consume model budget.
    changed=_v4221_fast_static_recovery(work,manifest,progress_callback,focus_rel=rel)
    if changed:return True
    if int(row.get('attempts') or 0)>=V4221_MAX_SAME_BLOCKER_MODEL_ATTEMPTS:
        _append_project_event(work,'v4221_same_blocker_model_cap',f'V42.21 suppressed another same-strategy model repair for {rel} at an unchanged accepted revision.',file=rel,attempts=row.get('attempts'))
        return False
    row['attempts']=int(row.get('attempts') or 0)+1;row['at']=_utc_stamp();state['updated_at']=_utc_stamp()
    try:state_path.write_text(json.dumps(state,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    except Exception:pass
    return bool(_v4221_prev_repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback,validation_failure=validation_failure))


_v4221_prev_whole_project_audit=_v429_whole_project_audit

