# V42.21.1 hardening: deterministic mechanical repairs use all inherited syntax/
# ownership/semantic gates but do not require a compiler delta from a snapshot that
# may not have dependency substrate. The normal live/whole-project compiler runs
# immediately after and remains authoritative.
def _v4221_commit_fast_fix(work,manifest,rel,candidate,reason):
    rel=_v40_norm_rel(rel);p=Path(work)/rel
    try:
        old=p.read_text(encoding='utf-8',errors='replace')
        if candidate==old:return False
        tx=_v4221_prev_candidate_transaction_error(work,manifest or {},rel,candidate,user_request=(manifest or {}).get('_original_user_request') or '',validation_failure='',target_problems=[])
        if tx:return False
        sem=_v4221_semantic_role_error(work,manifest or {},rel,candidate)
        if sem:return False
        tmp=p.with_name(p.name+'.v4221.tmp');tmp.write_text(candidate,encoding='utf-8');os.replace(tmp,p)
        _v413_mark_accepted(work,rel,'v4221_deterministic_fast_fix')
        _append_project_event(work,'v4221_fast_fix',f'V42.21 deterministically repaired {rel} before model work.',file=rel,reason=reason)
        return True
    except Exception:
        try:(p.with_name(p.name+'.v4221.tmp')).unlink(missing_ok=True)
        except Exception:pass
        return False


_v4221_prev_delta_impl=_v4221_ts_error_delta_error
def _v4221_ts_error_delta_error(work,manifest,rel,content,validation_failure='',target_problems=None):
    if not V4221_TS_ERROR_DELTA_GATE or Path(_v40_norm_rel(rel)).suffix.lower() not in {'.ts','.tsx','.mts','.cts'}:return ''
    evidence=str(validation_failure or '')+'\n'+'\n'.join(str(x) for x in (target_problems or []))
    baseline=_v4221_ts_error_lines(evidence)
    if not baseline:baseline=_v4221_ts_error_lines(_v4221_latest_component_diag(work,manifest,rel))
    if not baseline:return ''
    ok,out=_v4221_overlay_tsc(work,manifest,rel,content)
    if ok is None:return ''
    if ok:return ''
    after=_v4221_ts_error_lines(out)
    if not after:return ''
    # If the overlay lacks dependency substrate, module-resolution noise is not
    # trustworthy candidate evidence. Final/live builds still enforce correctness.
    base_mod=sum(1 for x in baseline if 'cannot find module' in x.lower())
    after_mod=sum(1 for x in after if 'cannot find module' in x.lower())
    if after_mod>base_mod+2:return ''
    before_n=len(baseline);after_n=len(after)
    if after_n>before_n:
        return f'V42.21 compiler error-delta gate: candidate increases TypeScript errors from {before_n} to {after_n}; reject and preserve accepted source.'
    if after_n==before_n:
        old=set(baseline);new=set(after);target=Path(_v40_norm_rel(rel)).name.lower()
        old_target=sum(1 for x in baseline if target in x.lower());new_target=sum(1 for x in after if target in x.lower())
        if not (old_target and new_target<old_target and old!=new):
            return f'V42.21 compiler error-delta gate: candidate leaves TypeScript error count unchanged at {after_n}; this is not measurable progress.'
    return ''

# =============================================================================
# V42.22 CONSUMER-FIRST COMPILER OWNERSHIP + STABLE-PROVIDER PROTECTION
# =============================================================================
# V42.21 proved that transactional rejection protects the repository, but a legacy
# provider-first heuristic could still route ordinary TypeScript consumer errors to
# unrelated, already-valid DTO/type files in the same component. That produced repair
# rotations such as category.ts -> tool.ts -> checkout_record.ts even while the real
# compiler locations were App.tsx/components/hooks. V42.22 makes fresh compiler
# locations the primary ownership evidence, freezes clean semantic contract providers
# against speculative rewrites, applies small deterministic TypeScript hygiene fixes,
# and immediately returns to a fresh real build after every accepted consumer repair.

V4222_VERSION = '42.22.0'
V4222_ENGINE = 'CONSUMER_FIRST_COMPILER_OWNERSHIP_FACTORY'
V4222_STATE_FILE = 'JARVIS_V4222_CONSUMER_FIRST_STATE.json'
V4222_COMPONENT_CACHE_FILE = '.jarvis_build/V4222_COMPONENT_VALIDATION_CACHE.json'
V4222_CONSUMER_FIRST_TS = os.getenv('JARVIS_V4222_CONSUMER_FIRST_TS','1').strip().lower() not in {'0','false','no','off'}
V4222_STABLE_PROVIDER_PROTECTION = os.getenv('JARVIS_V4222_STABLE_PROVIDER_PROTECTION','1').strip().lower() not in {'0','false','no','off'}
V4222_COMPONENT_GREEN_CACHE = os.getenv('JARVIS_V4222_COMPONENT_GREEN_CACHE','1').strip().lower() not in {'0','false','no','off'}
V4222_MAX_TS_TARGETS_PER_FAILURE = max(1,min(4,int(os.getenv('JARVIS_V4222_MAX_TS_TARGETS_PER_FAILURE','2'))))
V4222_MAX_BUILD_CYCLES = max(2,min(10,int(os.getenv('JARVIS_V4222_MAX_BUILD_CYCLES','6'))))
V4222_NO_PROGRESS_BUILDS = max(1,min(3,int(os.getenv('JARVIS_V4222_NO_PROGRESS_BUILDS','2'))))
V4222_CONTRACT_CONTEXT_CHARS = max(3000,min(16000,int(os.getenv('JARVIS_V4222_CONTRACT_CONTEXT_CHARS','9000'))))


def _v4222_ts_contract_provider(manifest, rel):
    rel = _v40_norm_rel(rel)
    ext = Path(rel).suffix.lower()
    if ext not in {'.ts','.tsx','.mts','.cts','.js','.jsx'}:
        return False
    parts = {x.lower() for x in Path(rel).parts[:-1]}
    item = _manifest_file_item(manifest or {}, rel) or {}
    purpose = str(item.get('purpose') or '').lower()
    provider_dirs = {'types','type','contracts','contract','domain','models','model','entities','entity','enums','enum','schema','schemas'}
    return bool(parts & provider_dirs) or any(x in purpose for x in ('type definition','domain type','contract provider','schema','dto','data transfer'))


def _v4222_provider_source_is_stable(work, manifest, rel):
    if not V4222_STABLE_PROVIDER_PROTECTION or not _v4222_ts_contract_provider(manifest, rel):
        return False
    rel = _v40_norm_rel(rel); p = Path(work)/rel
    if not p.is_file() or not _v413_is_accepted(work, rel) or not _v39_file_is_implemented(work, rel):
        return False
    try: text = p.read_text(encoding='utf-8', errors='replace')
    except Exception: return False
    if _content_validation_error(rel, text):
        return False
    low = text.lower()
    if 'defineconfig(' in low or "from 'vite'" in low or 'from "vite"' in low:
        return False
    if re.search(r'<[A-Za-z][^>]*>', text) or re.search(r'\b(?:useState|useEffect|useMemo|useCallback)\s*\(', text):
        return False
    # Clean TS domain providers are normally declarations/enums plus imports/reexports.
    # Do not require a particular domain schema; this is only a stability classification.
    declaration = bool(re.search(r'(?m)^\s*export\s+(?:declare\s+)?(?:interface|type|enum|class)\s+[A-Za-z_$][\w$]*', text))
    return declaration


def _v4222_objective_provider_problem(work, manifest, provider):
    provider = _v40_norm_rel(provider); p = Path(work)/provider
    item = _manifest_file_item(manifest or {}, provider)
    if not item:
        return ''
    if not p.exists() or not p.is_file():
        return 'canonical provider is missing from the workspace'
    if not _v413_is_accepted(work, provider):
        return 'canonical provider exists only as an unaccepted/rejected revision'
    if not _v39_file_is_implemented(work, provider):
        return 'canonical provider is still a skeleton/incomplete implementation'
    try:
        text = p.read_text(encoding='utf-8', errors='replace')
        err = _content_validation_error(provider, text)
        if err: return str(err)
    except Exception as exc:
        return 'canonical provider could not be read: '+str(exc)
    return ''


def _v4222_provider_explicit_in_evidence(manifest, provider, evidence):
    provider = _v40_norm_rel(provider); text = str(evidence or ''); low = text.lower()
    if not provider or not text.strip():
        return False
    norm = provider.lower(); base = Path(provider).name.lower(); stem = Path(provider).stem.lower()
    if norm in low or (base and base in low):
        return True
    item = _manifest_file_item(manifest or {}, provider) or {}
    symbols = _normalize_export_contract(item.get('exports'))
    # Provider mutation is justified by compiler evidence only for import/export/module
    # ownership errors. Ordinary prop/argument/member errors stay on the consumer first.
    provider_codes = {'2305','2307','2459','2614','2724','2306'}
    codes = set(re.findall(r'\bTS(\d{4})\b', text, re.I))
    if codes & provider_codes:
        if stem and re.search(rf"(?:module|from)\s+['\"][^'\"]*{re.escape(stem)}[^'\"]*['\"]", low):
            return True
        if any(sym and re.search(rf'\b{re.escape(str(sym))}\b', text) for sym in symbols):
            return True
    return False


# Remove the old same-component +5 provider bias. A provider is now returned for a
# consumer only when the current compiler/problem text actually identifies it.
_v4222_prev_provider_paths_for_consumer = _v424_provider_paths_for_consumer

def _v424_provider_paths_for_consumer(manifest, rel, problems=None):
    candidates = list(_v4222_prev_provider_paths_for_consumer(manifest, rel, problems) or [])
    evidence = '\n'.join(str(x or '') for x in (problems or []))
    out = []
    for provider in candidates:
        provider = _v40_norm_rel(provider)
        if not provider or provider == _v40_norm_rel(rel):
            continue
        if _v4222_provider_explicit_in_evidence(manifest, provider, evidence):
            if provider not in out: out.append(provider)
    return out


# Stable accepted DTO/type providers are not unhealthy merely because a stale owner map
# says they should also define some unrelated symbol. Real import/export compiler errors
# can still target them through the consumer-first validation path below.
_v4222_prev_provider_state_problem = _v424_provider_state_problem

def _v424_provider_state_problem(work, manifest, provider):
    objective = _v4222_objective_provider_problem(work, manifest, provider)
    if objective:
        return objective
    if _v4222_provider_source_is_stable(work, manifest, provider):
        return ''
    return _v4222_prev_provider_state_problem(work, manifest, provider)


_v4222_prev_fast_provider_problem = _v429_fast_provider_problem

def _v429_fast_provider_problem(work, manifest, provider):
    objective = _v4222_objective_provider_problem(work, manifest, provider)
    if objective:
        return objective
    if _v4222_provider_source_is_stable(work, manifest, provider):
        return ''
    return _v4222_prev_fast_provider_problem(work, manifest, provider)


# Global provider prepass is now limited to objectively broken providers. An accepted,
# parse-clean semantic provider is not sent to Qwen just because it appears in an owner
# table. With a focused consumer failure, only explicitly named provider evidence qualifies.
_v4222_prev_provider_health_prepass = _v424_provider_health_prepass

def _v424_provider_health_prepass(user_request, manifest, work, progress_callback=None, focus_rel='', focus_problems=None):
    if not V424_PROVIDER_FIRST:
        return False
    candidates = []
    evidence = '\n'.join(str(x or '') for x in (focus_problems or []))
    if focus_rel:
        for p in _v424_provider_paths_for_consumer(manifest, focus_rel, focus_problems):
            if _v4222_provider_explicit_in_evidence(manifest, p, evidence) and p not in candidates:
                candidates.append(p)
    for row in _v424_owner_rows(manifest):
        p = _v40_norm_rel(row.get('provider'))
        if not p or p in candidates:
            continue
        if _v4222_objective_provider_problem(work, manifest, p):
            candidates.append(p)
    changed = False
    for provider in candidates[:max(1,min(V424_PROVIDER_PREPASS_MAX,4))]:
        if not _v4222_objective_provider_problem(work, manifest, provider) and not _v4222_provider_explicit_in_evidence(manifest, provider, evidence):
            continue
        if _v424_repair_one_provider(user_request, manifest, work, provider, progress_callback, reason='V42.22 objective/explicit provider evidence'):
            changed = True
            break
    return changed


def _v4222_merge_react_imports(text):
    src = str(text or '')
    pat = re.compile(r'(?m)^\s*import\s+(.+?)\s+from\s+[\'\"]react[\'\"]\s*;?\s*$')
    matches = list(pat.finditer(src))
    if len(matches) < 2:
        return src, False
    default = '' ; names = [] ; namespace = ''
    for m in matches:
        spec = m.group(1).strip()
        ns = re.fullmatch(r'\*\s+as\s+([A-Za-z_$][\w$]*)', spec)
        if ns:
            namespace = namespace or ns.group(1); continue
        br = re.search(r'\{([^}]*)\}', spec)
        if br:
            for raw in br.group(1).split(','):
                name = raw.strip()
                if name and name not in names: names.append(name)
            spec = (spec[:br.start()] + spec[br.end():]).strip().strip(',').strip()
        if spec and re.fullmatch(r'[A-Za-z_$][\w$]*', spec):
            default = default or spec
    if namespace and not default and not names:
        merged = f"import * as {namespace} from 'react';"
    else:
        left = default
        if names:
            left += (', ' if left else '') + '{ ' + ', '.join(names) + ' }'
        if not left:
            return src, False
        merged = f"import {left} from 'react';"
    first = matches[0]
    pieces=[];cursor=0
    for idx,m in enumerate(matches):
        pieces.append(src[cursor:m.start()])
        if idx==0: pieces.append(merged)
        cursor=m.end()
    pieces.append(src[cursor:])
    return ''.join(pieces), True


def _v4222_remove_speculative_contract_fields(text):
    src = str(text or ''); changed = False
    # Only remove generated-looking declaration lines that literally admit they were
    # added to satisfy an unrelated Props contract/workaround. This is deliberately
    # narrow and does not infer business-domain fields from names.
    pat = re.compile(r'(?m)^\s*[A-Za-z_$][\w$]*\??\s*:\s*[^;\n]+;\s*//\s*(?:added|introduced|temporary|workaround)[^\n]*(?:satisfy|props|prop contract)[^\n]*\n?', re.I)
    out, n = pat.subn('', src)
    changed = n > 0
    return out, changed


_v4222_prev_fast_static_recovery = _v4221_fast_static_recovery

def _v4221_fast_static_recovery(work, manifest, progress_callback=None, focus_rel=''):
    inherited = list(_v4222_prev_fast_static_recovery(work, manifest, progress_callback, focus_rel) or [])
    root = Path(work); targets=[]
    if focus_rel and (root/_v40_norm_rel(focus_rel)).is_file():
        targets=[_v40_norm_rel(focus_rel)]
    else:
        for item in (manifest or {}).get('files') or []:
            if not isinstance(item,dict): continue
            rel=_v40_norm_rel(item.get('path')); p=root/rel
            if rel and p.is_file() and p.suffix.lower() in {'.ts','.tsx','.js','.jsx'}: targets.append(rel)
    changed=list(inherited)
    for rel in list(dict.fromkeys(targets))[:1200]:
        p=root/rel
        try: src=p.read_text(encoding='utf-8',errors='replace')
        except Exception: continue
        cand,did=_v4222_merge_react_imports(src)
        if did and _v4221_commit_fast_fix(work,manifest,rel,cand,'merged duplicate React imports'):
            changed.append(rel); src=cand
        if _v4222_ts_contract_provider(manifest,rel):
            cand,did=_v4222_remove_speculative_contract_fields(src)
            if did and _v4221_commit_fast_fix(work,manifest,rel,cand,'removed self-described cross-layer Props workaround field'):
                changed.append(rel); src=cand
    if len(set(changed)) > len(set(inherited)):
        _progress(progress_callback,f'V42.22 deterministic TypeScript hygiene repaired {len(set(changed))-len(set(inherited))} additional blocker(s) before model work.',stage='V42.22 deterministic consumer hygiene',percent=80)
    return list(dict.fromkeys(changed))


def _v4222_diag_rel(work, raw):
    raw=str(raw or '').strip().strip('"\'').replace('\\','/')
    root=Path(work).resolve()
    try:
        p=Path(raw)
        if p.is_absolute(): return p.resolve().relative_to(root).as_posix()
    except Exception: pass
    raw=re.sub(r'^\./','',raw)
    # Compiler output can prepend arbitrary cwd text. Prefer a project suffix that exists.
    parts=raw.split('/')
    for i in range(len(parts)):
        cand='/'.join(parts[i:])
        if (root/cand).is_file(): return _v40_norm_rel(cand)
    return _v40_norm_rel(raw)


def _v4222_parse_ts_diagnostics(work, failure):
    rows=[]; seen=set()
    patterns=[
        re.compile(r'^(?P<file>.+?\.(?:ts|tsx|mts|cts|js|jsx))\((?P<line>\d+),(?P<col>\d+)\):\s*(?:error\s+)?TS(?P<code>\d{4}):\s*(?P<msg>.*)$',re.I),
        re.compile(r'^(?P<file>.+?\.(?:ts|tsx|mts|cts|js|jsx)):(?P<line>\d+):(?P<col>\d+)\s*(?:-|:)??\s*(?:error\s+)?TS(?P<code>\d{4}):\s*(?P<msg>.*)$',re.I),
    ]
    for rawline in str(failure or '').splitlines():
        line=rawline.strip()
        m=None
        for pat in patterns:
            m=pat.match(line)
            if m: break
        if not m: continue
        rel=_v4222_diag_rel(work,m.group('file'))
        if not rel or not (Path(work)/rel).is_file(): continue
        key=(rel,m.group('code'),m.group('line'),m.group('col'),m.group('msg'))
        if key in seen: continue
        seen.add(key); rows.append({'file':rel,'code':m.group('code'),'line':int(m.group('line')),'col':int(m.group('col')),'message':m.group('msg').strip(),'raw':line})
    return rows


def _v4222_ts_target_rank(manifest, rel, rows):
    rel=_v40_norm_rel(rel); low='/'+rel.lower().strip('/')+'/' ; name=Path(rel).name.lower()
    if name in {'app.tsx','app.jsx','main.tsx','main.jsx'}: layer=0
    elif any(x in low for x in ('/components/','/views/','/pages/','/screens/')): layer=1
    elif any(x in low for x in ('/hooks/','/services/','/stores/','/controllers/')): layer=2
    elif _v4222_ts_contract_provider(manifest,rel): layer=7
    elif 'config' in name or name.startswith('vite.'): layer=8
    else: layer=3
    return (layer,-len(rows),rel)


def _v4222_resolve_local_ts_import(work, importer, ref):
    if not str(ref).startswith(('./','../')): return ''
    base=(Path(work)/importer).parent
    q=(base/ref).resolve()
    root=Path(work).resolve()
    cands=[]
    if q.suffix: cands.append(q)
    else:
        for ext in ('.ts','.tsx','.js','.jsx','.mts','.cts'): cands.append(Path(str(q)+ext))
        for ext in ('.ts','.tsx','.js','.jsx'): cands.append(q/('index'+ext))
    for c in cands:
        if c.is_file():
            try:return c.relative_to(root).as_posix()
            except Exception:return ''
    return ''


def _v4222_ts_contract_context(work, rel):
    p=Path(work)/rel
    try: src=p.read_text(encoding='utf-8',errors='replace')
    except Exception:return ''
    refs=[]
    for m in re.finditer(r'(?m)^\s*import\s+(?:type\s+)?(?:[^\n]*?\s+from\s+)?[\'\"]([^\'\"]+)[\'\"]',src):
        target=_v4222_resolve_local_ts_import(work,rel,m.group(1))
        if target and target not in refs: refs.append(target)
    chunks=[];total=0
    for target in refs[:8]:
        tp=Path(work)/target
        try: text=tp.read_text(encoding='utf-8',errors='replace')
        except Exception:continue
        # Front-load public signatures/props/hooks without feeding entire large files.
        lines=text.splitlines(); excerpt='\n'.join(lines[:min(len(lines),140)])
        block=f'===== READ-ONLY CONTRACT {target} =====\n{excerpt}\n===== END CONTRACT =====\n'
        if total+len(block)>V4222_CONTRACT_CONTEXT_CHARS:
            remain=V4222_CONTRACT_CONTEXT_CHARS-total
            if remain>500: chunks.append(block[:remain])
            break
        chunks.append(block);total+=len(block)
    return '\n'.join(chunks)


def _v4222_ts_consumer_targets(work, manifest, failure):
    rows=_v4222_parse_ts_diagnostics(work,failure); grouped={}
    for row in rows: grouped.setdefault(row['file'],[]).append(row)
    ranked=[]
    for rel,rr in grouped.items():
        # A clean semantic provider is a last-resort target unless compiler evidence
        # explicitly points to its own file/import-export ownership.
        if _v4222_provider_source_is_stable(work,manifest,rel):
            own_evidence='\n'.join(x['raw'] for x in rr)
            if not _v4222_provider_explicit_in_evidence(manifest,rel,own_evidence):
                continue
        ranked.append((_v4222_ts_target_rank(manifest,rel,rr),rel,rr))
    ranked.sort(key=lambda x:x[0])
    return [(rel,rr) for _,rel,rr in ranked]


def _v4222_repair_ts_component_failure(user_request, manifest, work, failure, progress_callback=None):
    if not V4222_CONSUMER_FIRST_TS: return None
    targets=_v4222_ts_consumer_targets(work,manifest,failure)
    if not targets: return None
    # Mechanical repairs first; any accepted deterministic change invalidates the
    # stale compiler output, so return immediately for a fresh real build.
    fast=_v4221_fast_static_recovery(work,manifest,progress_callback)
    if fast:
        _append_project_event(work,'v4222_consumer_first_fast_fix','V42.22 changed source deterministically and requires fresh compiler evidence before any further ownership decision.',files=fast[:20])
        return True
    attempted=0
    for rel,rows in targets:
        if attempted>=V4222_MAX_TS_TARGETS_PER_FAILURE: break
        attempted+=1
        exact='\n'.join(x['raw'] for x in rows[:18])
        context=_v4222_ts_contract_context(work,rel)
        problem=(
            'V42.22 CONSUMER-FIRST COMPILER REPAIR. The TypeScript compiler located these errors in THIS target file. '
            'Repair the smallest incorrect consumer/wiring edge in this file first. Do NOT modify DTO/type/provider files merely to make this consumer compile. '
            'Use the read-only imported contracts below as authority. Preserve public component/hook behavior and file role. If props/arguments are missing, wire the real producer/hook/state into the consumer instead of adding unrelated fields to domain records. '
            'This candidate is accepted only if fresh TypeScript compiler errors measurably improve.\n\nEXACT COMPILER ERRORS FOR TARGET:\n'+exact+
            ('\n\n'+context if context else '')
        )
        _progress(progress_callback,f'V42.22 consumer-first repair: compiler ownership points to {rel}; repairing this consumer before any stable provider.',stage='V42.22 consumer-first compiler repair',percent=79,current_file=rel,model_role='worker')
        try:
            repaired=_repair_file_for_issues(user_request,manifest,work,rel,[problem],progress_callback,validation_failure=failure)
        except Exception:
            repaired=False
        if repaired:
            _append_project_event(work,'v4222_consumer_repair_accepted','V42.22 accepted a compiler-located consumer repair and stopped the round so the next decision uses a fresh real build.',file=rel,codes=sorted({x['code'] for x in rows}))
            return True
    _append_project_event(work,'v4222_consumer_repair_no_delta','V42.22 exhausted bounded compiler-located consumer targets without an accepted revision; stable providers were not speculatively rewritten.',targets=[x[0] for x in targets[:V4222_MAX_TS_TARGETS_PER_FAILURE]])
    return False


# Final runtime repair interception: TypeScript compiler locations outrank the inherited
# provider-first runtime diagnosis. If bounded consumer repair cannot improve the build,
# return no-change to the convergence circuit breaker instead of rotating through DTOs.
_v4222_prev_real_validation_failure = _repair_real_validation_failure

def _repair_real_validation_failure(user_request, manifest, work, failure, progress_callback=None):
    tsrows=_v4222_parse_ts_diagnostics(work,failure)
    if tsrows:
        result=_v4222_repair_ts_component_failure(user_request,manifest or {},work,failure,progress_callback)
        if result is not None:
            return bool(result)
    return bool(_v4222_prev_real_validation_failure(user_request,manifest,work,failure,progress_callback))


# Filter stale speculative owner/provider audit debt for stable TS declaration files.
# Real component compiler errors remain untouched and are therefore still authoritative.
_v4222_prev_whole_project_audit = _v429_whole_project_audit

def _v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=None):
    payload=_v4222_prev_whole_project_audit(work,user_request,manifest,run_components,progress_callback)
    kept=[];retired=[]
    for row in list(payload.get('issues') or []):
        rel=_v40_norm_rel((row or {}).get('file'));kind=str((row or {}).get('kind') or '')
        problem=str((row or {}).get('problem') or '')
        speculative=kind in {'canonical_provider','contract','identity','dependency'} and any(x in problem.lower() for x in ('canonical provider','canonical owner','provider health','must define/export','ownership'))
        if rel and speculative and _v4222_provider_source_is_stable(work,manifest,rel) and not _v4222_provider_explicit_in_evidence(manifest,rel,problem):
            retired.append({'file':rel,'kind':kind,'problem':problem[:1200]});continue
        kept.append(row)
    if retired:
        payload['issues']=kept;payload['issue_count']=len(kept);payload['clean']=not kept and all(x.get('ok') for x in (payload.get('components') or []))
        _append_project_event(work,'v4222_speculative_provider_debt_retired','V42.22 retired stale owner-map debt for accepted parse-clean TypeScript contract providers; real compiler/build evidence remains authoritative.',retired=retired[:30])
        try:_v429_write_audit(work,payload)
        except Exception:pass
    return payload


# Repair round order: deterministic -> missing/objective foundation -> exact compiler
# consumers -> other local source. Provider repair is not a blanket prepass anymore.
_v4222_prev_repair_audit_round = _v429_repair_audit_round

def _v429_repair_audit_round(user_request,manifest,work,audit,progress_callback=None,round_no=1):
    fast=_v4221_fast_static_recovery(work,manifest,progress_callback)
    if fast: return True
    issues=list((audit or {}).get('issues') or [])
    # Missing/unaccepted/incomplete planned artifacts are objective and may precede builds.
    for row in sorted(issues,key=lambda x:_v429_issue_priority(manifest,x)):
        kind=str(row.get('kind') or '');rel=_v40_norm_rel(row.get('file'))
        if kind not in {'missing','unaccepted','incomplete','language_syntax'} or not rel: continue
        p=Path(work)/rel
        if kind=='missing' or not p.exists():
            item=_manifest_file_item(manifest or {},rel)
            if item:
                try:
                    ok,_=_generate_planned_file(user_request,manifest,work,item,progress_callback)
                    if ok:return True
                except Exception:pass
        else:
            try:
                if _repair_file_for_issues(user_request,manifest,work,rel,[str(row.get('problem') or '')],progress_callback,validation_failure=str(row.get('problem') or '')):return True
            except Exception:pass
    # Component compiler evidence is stronger than heuristic owner maps.
    for row in issues:
        if str(row.get('kind') or '')!='component_validation':continue
        failure=str(row.get('problem') or '')
        ts=_v4222_repair_ts_component_failure(user_request,manifest,work,failure,progress_callback)
        if ts is True:return True
        if ts is False:continue
        try:
            if _repair_real_validation_failure(user_request,manifest,work,failure,progress_callback):return True
        except Exception:pass
    # Local deterministic/static findings next; stable providers stay frozen unless the
    # issue itself is explicit compiler/import evidence.
    by_file={}
    for row in issues:
        if str(row.get('kind') or '')=='component_validation':continue
        rel=_v40_norm_rel(row.get('file'));problem=str(row.get('problem') or '')
        if not rel or str(row.get('kind') or '') in {'missing','unaccepted','incomplete','language_syntax'}:continue
        if _v4222_provider_source_is_stable(work,manifest,rel) and not _v4222_provider_explicit_in_evidence(manifest,rel,problem):
            continue
        by_file.setdefault(rel,[]).append(problem)
    for rel,problems in sorted(by_file.items(),key=lambda kv:_v4222_ts_target_rank(manifest,kv[0],problems)):
        try:
            if _repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback,validation_failure='\n'.join(problems[:10])):return True
        except Exception:pass
    # Only objectively broken providers are eligible at this late fallback.
    try:
        if _v424_provider_health_prepass(user_request,manifest,work,progress_callback):return True
    except Exception:pass
    return False


def _v4222_component_fingerprint(work,manifest,component):
    adapter=_v361_normalize_component_adapter((component or {}).get('toolchain_adapter'))
    if adapter not in _V422_NODE_ADAPTERS and adapter!='rust': return ''
    rootrel=_v40_norm_rel((component or {}).get('root')) or '.'; root=Path(work) if rootrel=='.' else Path(work)/rootrel
    if not root.is_dir():return ''
    if adapter in _V422_NODE_ADAPTERS:
        exts={'.ts','.tsx','.js','.jsx','.mts','.cts','.json','.html','.css','.scss','.less'};names={'package.json','package-lock.json','pnpm-lock.yaml','yarn.lock'}
    else:
        exts={'.rs','.toml','.json'};names={'Cargo.toml','Cargo.lock','build.rs','tauri.conf.json'}
    rows=[]
    for p in root.rglob('*'):
        if not p.is_file():continue
        try:rel=p.relative_to(root).as_posix()
        except Exception:continue
        parts={x.lower() for x in p.parts}
        if parts & {'node_modules','target','.git','.jarvis_build','.jarvis_runtime','__pycache__'}:continue
        if adapter in _V422_NODE_ADAPTERS and rel.startswith('src-tauri/'):continue
        if p.suffix.lower() not in exts and p.name not in names:continue
        try:h=hashlib.sha256(p.read_bytes()).hexdigest()[:20]
        except Exception:continue
        rows.append((rel,h))
    return hashlib.sha256(json.dumps(sorted(rows),separators=(',',':')).encode()).hexdigest()[:28]


def _v4222_component_cache_load(work):
    p=Path(work)/V4222_COMPONENT_CACHE_FILE
    try:
        x=json.loads(p.read_text(encoding='utf-8',errors='replace'));return x if isinstance(x,dict) else {}
    except Exception:return {}


def _v4222_component_cache_save(work,data):
    p=Path(work)/V4222_COMPONENT_CACHE_FILE;p.parent.mkdir(parents=True,exist_ok=True)
    try:p.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    except Exception:pass


_v4222_prev_validate_component = _v35_validate_component

def _v35_validate_component(work,manifest,component,user_request=''):
    fp=_v4222_component_fingerprint(work,manifest,component) if V4222_COMPONENT_GREEN_CACHE else ''
    cid=str((component or {}).get('id') or (component or {}).get('root') or 'component')
    if fp:
        cache=_v4222_component_cache_load(work);row=(cache.get('green') or {}).get(cid) or {}
        if row.get('fingerprint')==fp and row.get('ok') is True:
            _append_project_event(work,'v4222_component_green_cache_hit',f'V42.22 reused unchanged green component validation for {cid} instead of rebuilding it again.',component=cid,fingerprint=fp)
            return True,str(row.get('output') or '')+'\n[V42.22 unchanged green component validation reused]'
    ok,out=_v4222_prev_validate_component(work,manifest,component,user_request)
    if fp and ok:
        cache=_v4222_component_cache_load(work);green=cache.setdefault('green',{});green[cid]={'fingerprint':fp,'ok':True,'output':str(out or '')[-5000:],'at':_utc_stamp()};_v4222_component_cache_save(work,cache)
    return ok,out


# Build-first bounded convergence for projects that currently have TypeScript compiler
# failures. Every accepted repair forces a new audit/build before another source edit;
# unchanged green sibling components are cached by source fingerprint.
_v4222_prev_whole_project_convergence = _v429_whole_project_convergence

def _v429_whole_project_convergence(user_request,manifest,work,progress_callback=None):
    if not V429_WHOLE_PROJECT_AUDIT:return True,[]
    # Probe once. Non-TypeScript projects retain the established universal convergence path.
    first=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
    has_ts=any(str(x.get('kind') or '')=='component_validation' and _v4222_parse_ts_diagnostics(work,str(x.get('problem') or '')) for x in (first.get('issues') or []))
    if not has_ts:
        if first.get('clean'):return True,[]
        return _v4222_prev_whole_project_convergence(user_request,manifest,work,progress_callback)
    audit=first;last_sig='';last_token='';stalls=0
    for cycle in range(1,V4222_MAX_BUILD_CYCLES+1):
        if cycle>1:
            _progress(progress_callback,f'V42.22 build-first convergence cycle {cycle}/{V4222_MAX_BUILD_CYCLES}: rebuilding from the latest accepted consumer repair.',stage='V42.22 fresh compiler evidence',percent=min(94,80+cycle*2))
            audit=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
        if audit.get('clean'):
            _append_project_event(work,'v4222_whole_project_green','V42.22 reached zero whole-project issues with fresh component build/test evidence.',cycle=cycle)
            return True,[]
        sig=_v4213_audit_signature(audit);token=_v429_progress_token(work)
        if sig==last_sig and token==last_token:stalls+=1
        else:stalls=0
        last_sig,last_token=sig,token
        before=token
        changed=_v429_repair_audit_round(user_request,manifest,work,audit,progress_callback,cycle)
        after=_v429_progress_token(work)
        if changed and after!=before:
            stalls=0
            continue
        stalls+=1
        if stalls>=V4222_NO_PROGRESS_BUILDS:
            final=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
            _append_project_event(work,'v4222_no_progress_stop','V42.22 stopped after repeated fresh builds produced no accepted consumer/root-cause improvement; it did not rotate through unrelated stable providers.',cycle=cycle,issues=(final.get('issues') or [])[:40])
            return False,list(final.get('issues') or [])
    final=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
    return bool(final.get('clean')),list(final.get('issues') or [])


# Consumer-first model instruction applies to every late repair without changing manual
# model selection. The 27B remains available for true architecture/root-cause work.
_v4222_prev_qwen_call = _qwen_call

def _qwen_call(prompt,progress_callback=None,stage='Generating',profile='chat',**kwargs):
    body=str(prompt or '')+(
        '\n\nV42.22 CONSUMER-FIRST OWNERSHIP RULE: Fresh compiler locations outrank heuristic provider/owner maps. '
        'When an error is located in a caller/component/hook, repair that consuming edge first using the provider public contract as read-only authority. '
        'Do not add unrelated fields to DTOs/types merely to satisfy a component prop, and do not rewrite a parse-clean stable contract provider unless the compiler explicitly reports that provider/module/export as wrong. '
        'After one accepted repair Jarvis will rebuild before choosing another target, so make one small root-correct change rather than broad compatibility edits.'
    )
    stage2=str(stage or '')
    for old in ('V42.21','V42.20','V42.19','V42.18','V42.13','V42.9'):
        stage2=stage2.replace(old,'V42.22')
    return _v4222_prev_qwen_call(body,progress_callback,stage2,profile=profile,**kwargs)


