_v4222_prev_progress = _progress

def _progress(callback,text=None,**fields):
    if text is not None:
        text=str(text)
        for old in ('V42.21','V42.20','V42.19','V42.18','V42.17','V42.16','V42.13','V42.9'):
            text=text.replace(old,'V42.22')
    return _v4222_prev_progress(callback,text,**fields)

# =============================================================================
# V42.23 RESUME-POLICY MIGRATION + TYPESCRIPT ERROR BURN-DOWN
# =============================================================================
# V42.22 made fresh compiler locations the primary repair owner, but a resumed project
# can still carry historical architecture_rules from an older checkpoint (notably the
# old "Provider-First Repair" rule).  In addition, one TypeScript build can report dozens
# of diagnostics that share only a few causes; sending each symptom to Qwen wastes time.
# V42.23 migrates checkpoint policy to the current engine, applies only compiler-proven
# mechanical fixes in a bounded batch, enriches consumer repairs with nearby producer/hook
# contracts, and continues while fresh real-build error counts are actually decreasing.

V4223_VERSION = '42.23.0'
V4223_ENGINE = 'RESUME_POLICY_TS_BURNDOWN_CONVERGENCE_FACTORY'
V4223_STATE_FILE = 'JARVIS_V4223_PROGRESS_STATE.json'
V4223_RESUME_MIGRATION_REPORT = 'JARVIS_V4223_RESUME_POLICY_MIGRATION.json'
V4223_BULK_TS_RECOVERY = os.getenv('JARVIS_V4223_BULK_TS_RECOVERY','1').strip().lower() not in {'0','false','no','off'}
V4223_RESUME_POLICY_MIGRATION = os.getenv('JARVIS_V4223_RESUME_POLICY_MIGRATION','1').strip().lower() not in {'0','false','no','off'}
V4223_MAX_BUILD_CYCLES = max(4,min(16,int(os.getenv('JARVIS_V4223_MAX_BUILD_CYCLES','10'))))
V4223_NO_PROGRESS_BUILDS = max(1,min(3,int(os.getenv('JARVIS_V4223_NO_PROGRESS_BUILDS','2'))))
V4223_TS_CONVERGENCE_WALL_SECONDS = max(300,min(3600,int(os.getenv('JARVIS_V4223_TS_CONVERGENCE_WALL_SECONDS','1500'))))
V4223_PRODUCER_CONTEXT_CHARS = max(4000,min(28000,int(os.getenv('JARVIS_V4223_PRODUCER_CONTEXT_CHARS','20000'))))
V4223_MAX_PRODUCER_FILES = max(2,min(12,int(os.getenv('JARVIS_V4223_MAX_PRODUCER_FILES','9'))))


_V4223_STALE_POLICY_RE = re.compile(
    r'(?:provider\s*[- ]?first|providers?/config/dependencies\s+before\s+consumers|'
    r'if\s+a\s+consumer\s+fails.*canonical\s+type\s+definition)', re.I | re.S
)


def _v4223_sanitize_resume_manifest(manifest):
    """Treat old checkpoint orchestration rules as historical input, never current policy."""
    m = dict(manifest or {})
    removed = []
    rules = m.get('architecture_rules')
    if isinstance(rules, str):
        rules = [rules]
    if isinstance(rules, list):
        keep = []
        for rule in rules:
            text = str(rule or '').strip()
            if not text:
                continue
            if _V4223_STALE_POLICY_RE.search(text):
                removed.append(text)
                continue
            keep.append(text)
        current = (
            'Consumer-First Compiler Ownership: fresh compiler locations and the failing '
            'consumer/caller edge outrank historical provider maps. Stable parse-clean DTO/type '
            'providers are read-only unless compiler evidence explicitly identifies their module/export/shape.'
        )
        if current not in keep:
            keep.append(current)
        m['architecture_rules'] = keep
    # Old planner/engine labels are not authoritative when a project is resumed.
    for key in ('planner_mode','repair_policy','engine','engine_version'):
        if key in m and str(m.get(key) or '').lower().find('provider') >= 0:
            removed.append(f'{key}: {m.get(key)}')
            m.pop(key, None)
    m['resume_policy_version'] = 'V'+V4223_VERSION
    m['repair_ownership_policy'] = 'consumer-first-fresh-compiler-evidence'
    return m, removed


_v4223_prev_resume_seed_from_workspace = _resume_seed_from_workspace

def _resume_seed_from_workspace(work, source_zip, user_request):
    seed = dict(_v4223_prev_resume_seed_from_workspace(work, source_zip, user_request) or {})
    if not V4223_RESUME_POLICY_MIGRATION:
        return seed
    manifest, removed = _v4223_sanitize_resume_manifest(seed.get('manifest') or {})
    seed['manifest'] = manifest
    if removed:
        # V42.14/V42.15 may already have materialized derived architecture from the
        # historical checkpoint before this final current-policy migration. Rewrite those
        # derived artifacts now so no later subsystem can read the retired rule from disk.
        try:_v33_write_architecture(work,manifest)
        except Exception:pass
        try:_v40_write_domain_owners(work,manifest)
        except Exception:pass
        try:
            _V36_REPO_CACHE.clear();_V36_CONTRACT_CACHE.clear()
        except Exception:pass
        try:_v36_build_repo_graph(work,manifest,write=True)
        except Exception:pass
        try:_v36_build_contract_registry(work,manifest,write=True)
        except Exception:pass
        try:
            report = {
                'version':'V'+V4223_VERSION,
                'at':_utc_stamp(),
                'source_zip':Path(str(source_zip or '')).name,
                'removed_stale_rules':removed[:80],
                'current_policy':'consumer-first-fresh-compiler-evidence',
            }
            (Path(work)/V4223_RESUME_MIGRATION_REPORT).write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
            _append_project_event(work,'v4223_resume_policy_migrated',
                f'V42.23 migrated {len(removed)} stale checkpoint repair-policy rule(s) to current consumer-first compiler ownership.',
                removed=removed[:20])
        except Exception:
            pass
    return seed


# Checkpoints created by the current engine must not perpetuate obsolete repair policy.
_v4223_prev_package_resume_checkpoint_zip = _package_resume_checkpoint_zip

def _package_resume_checkpoint_zip(
    work, manifest, original_request, latest_instruction, unresolved_issues,
    source_zip_name='', resume_count=1, snapshot=None, stamp=None,
):
    clean_manifest, _ = _v4223_sanitize_resume_manifest(manifest or {})
    return _v4223_prev_package_resume_checkpoint_zip(
        work, clean_manifest, original_request, latest_instruction, unresolved_issues,
        source_zip_name=source_zip_name, resume_count=resume_count, snapshot=snapshot, stamp=stamp,
    )


def _v4223_diag_symbol(row):
    raw = str((row or {}).get('raw') or '')
    m = re.search(r"'([^']+)'\s+is declared but its value is never read", raw, re.I)
    return m.group(1) if m else ''


def _v4223_remove_named_import(line, symbol):
    """Remove one compiler-proven unused binding from a single import statement."""
    if not symbol or 'import ' not in line:
        return line, False
    original = line
    # import React, { useState } from 'react'
    m = re.match(r'^(\s*)import\s+([A-Za-z_$][\w$]*)\s*,\s*\{([^}]*)\}\s+from\s+(.+?)\s*;?\s*$', line)
    if m:
        default = m.group(2); names = [x.strip() for x in m.group(3).split(',') if x.strip()]
        if symbol == default:
            return f"{m.group(1)}import {{ {', '.join(names)} }} from {m.group(4)};", True
        kept = [x for x in names if x.split(' as ')[-1].strip() != symbol and x.split(' as ')[0].strip() != symbol]
        if len(kept) != len(names):
            return f"{m.group(1)}import {default}, {{ {', '.join(kept)} }} from {m.group(4)};", True
    # import { A, B as C } from 'x'
    m = re.match(r'^(\s*)import\s+(type\s+)?\{([^}]*)\}\s+from\s+(.+?)\s*;?\s*$', line)
    if m:
        names = [x.strip() for x in m.group(3).split(',') if x.strip()]
        kept = [x for x in names if x.split(' as ')[-1].strip() != symbol and x.split(' as ')[0].strip() != symbol]
        if len(kept) != len(names):
            if not kept:
                return '', True
            prefix = 'type ' if m.group(2) else ''
            return f"{m.group(1)}import {prefix}{{ {', '.join(kept)} }} from {m.group(4)};", True
    # import Default from 'x'
    m = re.match(r'^(\s*)import\s+([A-Za-z_$][\w$]*)\s+from\s+.+?;?\s*$', line)
    if m and m.group(2) == symbol:
        return '', True
    return original, False


def _v4223_remove_object_binding(line, symbol):
    """Remove an unused object-destructure binding but preserve the RHS/hook invocation."""
    if not symbol or '{' not in line or '}' not in line:
        return line, False
    # const { a, tools: managedTools, b } = useSomething();
    m = re.match(r'^(\s*)(const|let|var)\s+\{([^}]*)\}\s*=\s*(.+?);?\s*$', line)
    if m:
        parts = [x.strip() for x in m.group(3).split(',') if x.strip()]
        def bound_name(part):
            p = part.strip().lstrip('...').strip()
            if ':' in p:
                return p.split(':',1)[1].split('=',1)[0].strip()
            return p.split('=',1)[0].strip()
        kept = [p for p in parts if bound_name(p) != symbol]
        if len(kept) != len(parts):
            if kept:
                return f"{m.group(1)}{m.group(2)} {{ {', '.join(kept)} }} = {m.group(4)};", True
            return f"{m.group(1)}{m.group(4)};", True
    # Destructured React/function parameter on one line: ({ tools, categories }) =>
    # Remove only the compiler-proven unused binding; the Props annotation/contract remains.
    pat = re.compile(r'\{([^{}]*)\}')
    for mm in list(pat.finditer(line)):
        parts = [x.strip() for x in mm.group(1).split(',') if x.strip()]
        if symbol not in [p.split(':',1)[0].split('=',1)[0].strip() for p in parts]:
            continue
        kept = [p for p in parts if p.split(':',1)[0].split('=',1)[0].strip() != symbol]
        rep = '{' + ((' ' + ', '.join(kept) + ' ') if kept else '') + '}'
        return line[:mm.start()] + rep + line[mm.end():], True
    return line, False



def _v4223_remove_all_object_destructure(line):
    m=re.match(r'^(\s*)(const|let|var)\s+\{[^}]+\}\s*=\s*(.+?);?\s*$',line)
    if not m:return line,False
    return f"{m.group(1)}{m.group(3)};",True

def _v4223_replace_null_with_undefined(line, row):
    raw = str((row or {}).get('raw') or '')
    if str((row or {}).get('code') or '') != '2322' or 'null' not in raw.lower() or 'undefined' not in raw.lower():
        return line, False
    if re.search(r'\bnull\b', line):
        return re.sub(r'\bnull\b','undefined',line,count=1), True
    return line, False


def _v4223_fix_tauri2_invoke(work, rel, text, rows):
    if not any(str(r.get('code') or '')=='2339' and '__TAURI__' in str(r.get('raw') or '') for r in rows):
        return text, False
    root=Path(work); pkg=root/'package.json'
    try: data=json.loads(pkg.read_text(encoding='utf-8',errors='replace'))
    except Exception: return text, False
    deps={**(data.get('dependencies') or {}),**(data.get('devDependencies') or {})}
    ver=str(deps.get('@tauri-apps/api') or '')
    if not ver or not re.search(r'(^|[^0-9])2(?:\.|$)',ver):
        return text, False
    src=str(text or '')
    if 'window.__TAURI__.invoke' not in src:
        return src, False
    src=src.replace('window.__TAURI__.invoke','invoke')
    # Preserve the declared response contract for the common generic command-wrapper shape.
    # Tauri 2 invoke<T>() returns Promise<T>; without the type argument a formerly-any
    # window.__TAURI__ call can become Promise<unknown> and create a new error.
    if 'TauriCommandResponse' in src and re.search(r'createTauriCommand\s*=\s*<\s*T\s*,',src):
        src=re.sub(
            r'return\s+invoke\(commandName\s*,\s*args\)\s*;',
            'return invoke<TauriCommandResponse<T>>(commandName, args as Record<string, unknown> | undefined);',
            src, count=1
        )
    if not re.search(r"from\s+['\"]@tauri-apps/api/core['\"]",src):
        src="import { invoke } from '@tauri-apps/api/core';\n"+src
    return src, True


def _v4223_manifest_add_file(manifest, rel, purpose):
    rel=_v40_norm_rel(rel)
    files=(manifest or {}).setdefault('files',[])
    if not any(isinstance(x,dict) and _v40_norm_rel(x.get('path'))==rel for x in files):
        files.append({'path':rel,'purpose':purpose,'exports':[]})


def _v4223_recover_local_style_module(work, manifest, rel, row):
    """Recover local stylesheet substrate and Vite's ambient CSS module typing."""
    if str((row or {}).get('code') or '')!='2307': return []
    raw=str((row or {}).get('raw') or '')
    m=re.search(r"Cannot find module ['\"]([^'\"]+\.(?:css|scss|sass|less))['\"]",raw,re.I)
    if not m or not m.group(1).startswith('.'): return []
    root=Path(work).resolve(); importer=root/_v40_norm_rel(rel);base=importer.parent
    target=(base/m.group(1)).resolve();made=[]
    try: target.relative_to(root)
    except Exception: return []
    if not target.exists():
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_text('/* Jarvis-created stylesheet substrate; add project styles here. */\n',encoding='utf-8')
        r=target.relative_to(root).as_posix();_v4223_manifest_add_file(manifest,r,'Local stylesheet imported by authored source')
        try:_v413_mark_accepted(work,r,'v4223_missing_local_style')
        except Exception:pass
        made.append(r)
    # Vite/TypeScript normally learns *.css modules from vite/client. If the stylesheet
    # exists but TS2307 still fires, the missing substrate is usually vite-env.d.ts.
    pkg=root/'package.json';uses_vite=False
    try:
        data=json.loads(pkg.read_text(encoding='utf-8',errors='replace'))
        deps={**(data.get('dependencies') or {}),**(data.get('devDependencies') or {})}
        uses_vite=bool(deps.get('vite') or deps.get('@vitejs/plugin-react'))
    except Exception:pass
    if uses_vite:
        srcroot=importer.parent
        while srcroot!=root and srcroot.name.lower() not in {'src','app','frontend'}:srcroot=srcroot.parent
        if srcroot==root and (root/'src').is_dir():srcroot=root/'src'
        env=srcroot/'vite-env.d.ts'
        desired='/// <reference types="vite/client" />\n'
        if not env.exists() or 'vite/client' not in env.read_text(encoding='utf-8',errors='replace'):
            env.parent.mkdir(parents=True,exist_ok=True);env.write_text(desired,encoding='utf-8')
            r=env.relative_to(root).as_posix();_v4223_manifest_add_file(manifest,r,'Vite TypeScript ambient declarations')
            try:_v413_mark_accepted(work,r,'v4223_vite_env')
            except Exception:pass
            made.append(r)
    return made


def _v4223_missing_react_hook_import_fix(text, rows):
    hooks={'useState','useEffect','useMemo','useCallback','useRef','useReducer','useContext','useLayoutEffect'}
    missing=[]
    for row in rows or []:
        if str(row.get('code') or '')!='2304':continue
        raw=str(row.get('raw') or '')
        m=re.search(r"Cannot find name ['\"]?([A-Za-z_$][\w$]*)['\"]?",raw,re.I)
        if m and m.group(1) in hooks and m.group(1) not in missing:missing.append(m.group(1))
    if not missing:return str(text or ''),False
    src=str(text or '')
    # Existing named React import.
    m=re.search(r"import\s*\{([^}]*)\}\s*from\s*(['\"]react['\"])\s*;?",src,re.S)
    if m:
        names=[x.strip() for x in m.group(1).split(',') if x.strip()]
        merged=names+[h for h in missing if h not in names]
        rep='import { '+', '.join(merged)+' } from '+m.group(2)+';'
        return src[:m.start()]+rep+src[m.end():],True
    # Default React import.
    m=re.search(r"(?m)^\s*import\s+React\s+from\s+(['\"]react['\"])\s*;?\s*$",src)
    if m:
        return src[:m.start()]+f"import React, {{ {', '.join(missing)} }} from {m.group(1)};"+src[m.end():],True
    return "import { "+', '.join(missing)+" } from 'react';\n"+src,True


def _v4223_redundant_ts_reexport_fix(text):
    src=str(text or '')
    declared=set(re.findall(r'(?m)^\s*export\s+(?:declare\s+)?(?:interface|type|class|enum|function|const|let|var)\s+([A-Za-z_$][\w$]*)',src))
    if not declared:return src,False
    changed=False
    pat=re.compile(r'(?m)^([ \t]*)export\s+(type\s+)?\{([^}\n]+)\}\s*;?\s*$')
    def repl(m):
        nonlocal changed
        parts=[x.strip() for x in m.group(3).split(',') if x.strip()];kept=[]
        for part in parts:
            raw=part.split(' as ',1)[0].strip()
            if raw in declared:changed=True;continue
            kept.append(part)
        if not kept:return ''
        typ='type ' if m.group(2) else ''
        return m.group(1)+'export '+typ+'{ '+', '.join(kept)+' };'
    return pat.sub(repl,src),changed


def _v4223_apply_rows_to_source(work, manifest, rel, rows):
    p=Path(work)/_v40_norm_rel(rel)
    try: src=p.read_text(encoding='utf-8',errors='replace')
    except Exception:return '', []
    lines=src.splitlines(); reasons=[]
    # Compiler-proven line-local hygiene first so original tsc line numbers remain valid.
    for row in sorted(rows,key=lambda r:int(r.get('line') or 0),reverse=True):
        idx=int(row.get('line') or 0)-1
        if idx<0 or idx>=len(lines):continue
        symbol=_v4223_diag_symbol(row);line=lines[idx];new=line;changed=False
        if str(row.get('code') or '')=='6133' and symbol:
            new,changed=_v4223_remove_named_import(line,symbol)
            if not changed:new,changed=_v4223_remove_object_binding(line,symbol)
        if not changed and str(row.get('code') or '')=='6198':
            new,changed=_v4223_remove_all_object_destructure(line)
        if not changed:new,changed=_v4223_replace_null_with_undefined(line,row)
        if changed:
            lines[idx]=new;reasons.append(f"TS{row.get('code')} line {row.get('line')}")
    out='\n'.join(lines)+('\n' if src.endswith('\n') else '')
    # Diagnostic-aware global hygiene that does not depend on stale line numbers.
    out,did=_v4223_missing_react_hook_import_fix(out,rows)
    if did:reasons.append('missing React hook import')
    out,did=_v4223_redundant_ts_reexport_fix(out)
    if did:reasons.append('redundant TypeScript re-export')
    out,did=_v4221_redundant_ts_export_fix(out)
    if did:reasons.append('redundant TypeScript export')
    out,did=_v4223_fix_tauri2_invoke(work,rel,out,rows)
    if did:reasons.append('Tauri 2 invoke API migration')
    return out,reasons

def _v4223_bulk_ts_recovery(work, manifest, failure, progress_callback=None):
    """Burn down mechanically provable TS errors in one bounded pass, then force rebuild."""
    if not V4223_BULK_TS_RECOVERY:return []
    rows=_v4222_parse_ts_diagnostics(work,failure)
    if not rows:return []
    by={}
    for r in rows:by.setdefault(_v40_norm_rel(r.get('file')),[]).append(r)
    changed=[]
    # Missing relative stylesheet/config substrate first.
    for rel,rr in by.items():
        for row in rr:
            for made in _v4223_recover_local_style_module(work,manifest,rel,row):
                if made and made not in changed:changed.append(made)
    # Then source hygiene. Commit each file transactionally; no model token is spent.
    for rel,rr in by.items():
        p=Path(work)/rel
        if not p.is_file() or p.suffix.lower() not in {'.ts','.tsx','.mts','.cts','.js','.jsx'}:continue
        cand,reasons=_v4223_apply_rows_to_source(work,manifest,rel,rr)
        if not reasons:continue
        if _v4221_commit_fast_fix(work,manifest,rel,cand,'; '.join(reasons[:8])):
            changed.append(rel)
    if changed:
        _append_project_event(work,'v4223_ts_burndown',
            f'V42.23 deterministically burned down compiler-proven TypeScript hygiene/substrate blockers in {len(changed)} file(s); a fresh real build is now mandatory.',
            files=changed[:40])
        _progress(progress_callback,f'V42.23 TypeScript burn-down fixed {len(changed)} compiler-proven blocker file(s) without model reasoning; rebuilding now.',stage='V42.23 deterministic TypeScript burn-down',percent=80)
    return list(dict.fromkeys(changed))


def _v4223_error_terms(rows):
    terms=set()
    stop={'type','property','missing','required','argument','expected','string','undefined','null','value','module','cannot','find','declared','never','read'}
    for row in rows or []:
        raw=str(row.get('raw') or '')
        for q in re.findall(r"'([A-Za-z_$][\w$]*)'",raw):
            if q.lower() not in stop:terms.add(q)
        m=re.search(r'following properties from type .*?:\s*([^\n]+)',raw,re.I)
        if m:
            for x in re.findall(r'[A-Za-z_$][\w$]*',m.group(1)):
                if x.lower() not in stop:terms.add(x)
    return terms


def _v4223_nearby_producer_context(work, rel, rows):
    """Expose likely hooks/state producers as read-only context for consumer wiring repairs."""
    root=Path(work);target=root/_v40_norm_rel(rel)
    terms=_v4223_error_terms(rows)
    candidates=[]
    # Prefer the target's source tree, then project src/hooks/services/stores/context.
    srcroot=target.parent
    while srcroot!=root and srcroot.name.lower() not in {'src','app','frontend'}:
        srcroot=srcroot.parent
    if not srcroot.exists():srcroot=root
    for dname in ('hooks','services','stores','store','context','contexts','providers'):
        d=srcroot/dname
        if not d.is_dir():continue
        for p in d.rglob('*'):
            if not p.is_file() or p.suffix.lower() not in {'.ts','.tsx','.js','.jsx'}:continue
            try:text=p.read_text(encoding='utf-8',errors='replace')
            except Exception:continue
            exports=set(re.findall(r'(?m)^\s*export\s+(?:const|function|class|interface|type)\s+([A-Za-z_$][\w$]*)',text))
            low=text.lower();score=0
            for t in terms:
                if t.lower() in low:score+=3
                if p.stem.lower() == ('use'+t.lower()):score+=10
            score+=sum(2 for x in exports if x.startswith('use'))
            if score<=0:continue
            candidates.append((score,p,text))
    candidates.sort(key=lambda x:(-x[0],str(x[1])))
    chunks=[];total=0
    for _,p,text in candidates[:V4223_MAX_PRODUCER_FILES]:
        try:r=p.relative_to(root).as_posix()
        except Exception:r=str(p)
        # Enough implementation to reveal hook arguments/return shape; still read-only.
        block=f'READ-ONLY AVAILABLE PRODUCER {r}:\n{text[:2400]}\n'
        if total+len(block)>V4223_PRODUCER_CONTEXT_CHARS:
            block=block[:max(0,V4223_PRODUCER_CONTEXT_CHARS-total)]
        if not block:break
        chunks.append(block);total+=len(block)
        if total>=V4223_PRODUCER_CONTEXT_CHARS:break
    return '\n'.join(chunks)


_v4223_prev_repair_ts_component_failure = _v4222_repair_ts_component_failure

def _v4222_repair_ts_component_failure(user_request, manifest, work, failure, progress_callback=None):
    rows=_v4222_parse_ts_diagnostics(work,failure)
    if not rows:return _v4223_prev_repair_ts_component_failure(user_request,manifest,work,failure,progress_callback)
    fast=_v4223_bulk_ts_recovery(work,manifest,failure,progress_callback)
    if fast:return True
    targets=_v4222_ts_consumer_targets(work,manifest,failure)
    if not targets:return False
    # One compiler-owned consumer at a time. A fresh build must decide the next owner.
    rel,rr=targets[0]
    exact='\n'.join(x['raw'] for x in rr[:28])
    contract=_v4222_ts_contract_context(work,rel)
    producers=_v4223_nearby_producer_context(work,rel,rr)
    problem=(
        'V42.23 CLUSTERED CONSUMER REPAIR. These diagnostics are symptoms in ONE compiler-owned consumer file. '
        'Fix their shared root cause in this consumer, not one symptom at a time. Keep stable DTO/type providers read-only unless an explicit import/export diagnostic names them. '
        'For missing component props or hook arguments, wire the existing producer hooks/state into this consumer. Do not add convenience fields to unrelated domain records. '
        'Remove/adjust compiler-proven unused consumer bindings when appropriate, preserve behavior, and make the smallest coherent edit. Jarvis will run a fresh real TypeScript build immediately after an accepted change.\n\n'
        'EXACT CURRENT COMPILER DIAGNOSTICS FOR THIS FILE:\n'+exact+
        ('\n\n'+contract if contract else '')+
        ('\n\n'+producers if producers else '')
    )
    _progress(progress_callback,f'V42.23 clustered consumer repair: fresh compiler ownership points to {rel}.',stage='V42.23 clustered consumer wiring repair',percent=79,current_file=rel,model_role='worker')
    try:
        ok=_repair_file_for_issues(user_request,manifest,work,rel,[problem],progress_callback,validation_failure=failure)
    except Exception:
        ok=False
    if ok:
        _append_project_event(work,'v4223_clustered_consumer_repair_accepted',
            'V42.23 accepted one clustered compiler-owned consumer repair; no second source edit is allowed until a fresh real build measures the delta.',
            file=rel,codes=sorted({x['code'] for x in rr}))
        return True
    _append_project_event(work,'v4223_clustered_consumer_repair_rejected',
        'V42.23 rejected/no-op clustered consumer repair; stable providers remain protected and the progress circuit will use fresh build evidence.',file=rel)
    return False


def _v4223_audit_ts_rows(work,audit):
    out=[]
    for row in (audit or {}).get('issues') or []:
        if str((row or {}).get('kind') or '')!='component_validation':continue
        out.extend(_v4222_parse_ts_diagnostics(work,str((row or {}).get('problem') or '')))
    return out


def _v4223_ts_signature(rows):
    norm=[]
    for r in rows or []:
        raw=re.sub(r'\s+',' ',str(r.get('raw') or '')).strip()
        # Line/column movement alone is not progress.
        raw=re.sub(r'\(\d+,\d+\)', '(#,#)', raw)
        norm.append((_v40_norm_rel(r.get('file')),str(r.get('code') or ''),raw))
    return hashlib.sha256(json.dumps(sorted(norm),ensure_ascii=False,separators=(',',':')).encode()).hexdigest()[:28] if norm else ''


_v4223_prev_whole_project_convergence = _v429_whole_project_convergence

def _v429_whole_project_convergence(user_request,manifest,work,progress_callback=None):
    if not V429_WHOLE_PROJECT_AUDIT:return True,[]
    start=time.monotonic()
    audit=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
    rows=_v4223_audit_ts_rows(work,audit)
    if not rows:
        if audit.get('clean'):return True,[]
        return _v4223_prev_whole_project_convergence(user_request,manifest,work,progress_callback)
    best_count=len(rows);best_sig=_v4223_ts_signature(rows);no_progress=0
    _append_project_event(work,'v4223_ts_convergence_start',f'V42.23 TypeScript convergence started with {best_count} compiler diagnostic(s).',count=best_count,signature=best_sig)
    for cycle in range(1,V4223_MAX_BUILD_CYCLES+1):
        if time.monotonic()-start>V4223_TS_CONVERGENCE_WALL_SECONDS:
            _append_project_event(work,'v4223_ts_wall_stop',f'V42.23 stopped TypeScript convergence at the {V4223_TS_CONVERGENCE_WALL_SECONDS}s wall instead of running for hours.',cycle=cycle,best_count=best_count)
            final=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
            return bool(final.get('clean')),list(final.get('issues') or [])
        if audit.get('clean'):
            _append_project_event(work,'v4223_whole_project_green','V42.23 reached zero whole-project issues with fresh build/test evidence.',cycle=cycle)
            return True,[]
        before_token=_v429_progress_token(work)
        changed=_v429_repair_audit_round(user_request,manifest,work,audit,progress_callback,cycle)
        after_token=_v429_progress_token(work)
        accepted_delta=bool(changed and after_token!=before_token)
        _progress(progress_callback,f'V42.23 fresh-build cycle {cycle}/{V4223_MAX_BUILD_CYCLES}: measuring compiler error delta after the latest accepted change.',stage='V42.23 progress-based rebuild',percent=min(94,80+cycle))
        audit=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
        if audit.get('clean'):
            return True,[]
        rows=_v4223_audit_ts_rows(work,audit)
        if not rows:
            # TypeScript is green; hand any remaining non-TS debt back to universal convergence.
            return _v4223_prev_whole_project_convergence(user_request,manifest,work,progress_callback)
        count=len(rows);sig=_v4223_ts_signature(rows)
        if count<best_count:
            _append_project_event(work,'v4223_ts_error_delta',f'V42.23 fresh compiler errors decreased {best_count} -> {count}; continuing automatically.',before=best_count,after=count,cycle=cycle)
            best_count=count;best_sig=sig;no_progress=0
            continue
        if sig!=best_sig and count<=best_count and accepted_delta:
            # One grace build for same-count but materially different diagnostics after an accepted edit.
            no_progress=max(0,no_progress-1);best_sig=sig
        else:
            no_progress+=1
        if no_progress>=V4223_NO_PROGRESS_BUILDS:
            _append_project_event(work,'v4223_true_no_progress_stop',
                f'V42.23 stopped after {no_progress} fresh builds failed to reduce the normalized TypeScript blocker set (best={best_count}, current={count}).',
                cycle=cycle,best_count=best_count,current_count=count,signature=sig)
            return False,list(audit.get('issues') or [])
    final=_v429_whole_project_audit(work,user_request,manifest,run_components=True,progress_callback=progress_callback)
    return bool(final.get('clean')),list(final.get('issues') or [])


# Current-engine instruction always wins over historical checkpoint prose.
_v4223_prev_qwen_call = _qwen_call

def _qwen_call(prompt,progress_callback=None,stage='Generating',profile='chat',**kwargs):
    body=str(prompt or '')+(
        '\n\nV42.23 CURRENT-ENGINE RULE: checkpoint architecture text is historical unless it agrees with this rule. '
        'Use fresh compiler evidence and repair the failing consumer/caller edge before stable provider DTOs. Cluster diagnostics by root cause, prefer existing hooks/services as producers, and do not invent fields or APIs to silence errors. '
        'Jarvis will rebuild immediately and continue only while the real compiler blocker set is shrinking.'
    )
    stage2=str(stage or '')
    for old in ('V42.22','V42.21','V42.20','V42.19','V42.18','V42.13','V42.9'):
        stage2=stage2.replace(old,'V42.23')
    return _v4223_prev_qwen_call(body,progress_callback,stage2,profile=profile,**kwargs)


_v4223_prev_release_identity = _v36_release_identity

