_v4223_prev_progress = _progress

def _progress(callback,text=None,**fields):
    if text is not None:
        text=str(text)
        for old in ('V42.22','V42.21','V42.20','V42.19','V42.18','V42.17','V42.16','V42.13','V42.9'):
            text=text.replace(old,'V42.23')
    return _v4223_prev_progress(callback,text,**fields)

# =============================================================================
# V42.24 COMPILER-DIRECTED MULTI-FILE INTEGRATION TRANSACTIONS
# =============================================================================
# V42.23 successfully retired stale provider-first checkpoint policy and burned down
# simple TypeScript diagnostics, but a remaining integration family could still be
# attacked one file at a time (for example App.tsx -> reject -> subsystem -> App.tsx).
# V42.24 groups fresh compiler-owned consumers by the live local-import graph, repairs
# a bounded set inside one disposable workspace, and promotes the set atomically only
# when the real TypeScript error count falls. Once a cluster is exhausted at an
# unchanged accepted revision, inherited leaf repair is suppressed for those files.

V4224_VERSION = '42.24.0'
V4224_ENGINE = 'COMPILER_DIRECTED_MULTI_FILE_TRANSACTION_FACTORY'
V4224_STATE_FILE = 'JARVIS_V4224_CLUSTER_STATE.json'
V4224_MAX_CLUSTER_FILES = max(2, min(8, int(os.getenv('JARVIS_V4224_MAX_CLUSTER_FILES','6'))))
V4224_MAX_MODEL_FILES_PER_ATTEMPT = max(1, min(V4224_MAX_CLUSTER_FILES, int(os.getenv('JARVIS_V4224_MAX_MODEL_FILES_PER_ATTEMPT','4'))))
V4224_MAX_CLUSTER_ATTEMPTS = max(1, min(3, int(os.getenv('JARVIS_V4224_MAX_CLUSTER_ATTEMPTS','2'))))
V4224_CLUSTER_WALL_SECONDS = max(120, min(1200, int(os.getenv('JARVIS_V4224_CLUSTER_WALL_SECONDS','480'))))
V4224_TS_MEASURE_TIMEOUT = max(30, min(240, int(os.getenv('JARVIS_V4224_TS_MEASURE_TIMEOUT','90'))))
V4224_ENABLE_CLUSTER_REPAIR = os.getenv('JARVIS_V4224_CLUSTER_REPAIR','1').strip().lower() not in {'0','false','no','off'}

# Disable the inherited blanket provider-first prepass under the modern compiler-owner
# engine. Explicit provider/module compiler evidence is still handled by V42.22+.
try:
    V424_PROVIDER_FIRST = False
except Exception:
    pass

_V4224_ROUTE = threading.local() if 'threading' in globals() else _v426_threading.local()
_v4224_prev_auto_target = _v426_auto_target

def _v426_auto_target(stage, call_profile, prompt):
    if getattr(_V4224_ROUTE, 'force_worker', False):
        try:_v426_record_stage(stage)
        except Exception:pass
        return V426_AUTO_WORKER, 'V42.24 coordinated cluster first-pass worker'
    if getattr(_V4224_ROUTE, 'force_specialist', False):
        try:_v426_record_stage(stage)
        except Exception:pass
        return V426_AUTO_SPECIALIST, 'V42.24 coordinated cluster root-cause specialist'
    return _v4224_prev_auto_target(stage, call_profile, prompt)


def _v4224_state_load(work):
    p=Path(work)/V4224_STATE_FILE
    try:
        x=json.loads(p.read_text(encoding='utf-8',errors='replace'))
        return x if isinstance(x,dict) else {}
    except Exception:return {}


def _v4224_state_save(work,data):
    p=Path(work)/V4224_STATE_FILE
    try:p.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    except Exception:pass


def _v4224_norm_diag_signature(rows):
    vals=[]
    for r in rows or []:
        vals.append((_v40_norm_rel(r.get('file')),str(r.get('code') or ''),re.sub(r'\s+',' ',str(r.get('message') or '')).strip().lower()))
    return hashlib.sha256(json.dumps(sorted(vals),separators=(',',':'),ensure_ascii=False).encode('utf-8')).hexdigest()[:24]


def _v4224_project_ts_graph(work, candidates):
    root=Path(work); wanted={_v40_norm_rel(x) for x in candidates if _v40_norm_rel(x)}
    graph={x:set() for x in wanted}
    for rel in list(wanted):
        p=root/rel
        try:src=p.read_text(encoding='utf-8',errors='replace')
        except Exception:continue
        for m in re.finditer(r'(?m)^\s*import\s+(?:type\s+)?(?:[^\n]*?\s+from\s+)?[\'\"]([^\'\"]+)[\'\"]',src):
            target=_v4222_resolve_local_ts_import(work,rel,m.group(1))
            if target in wanted:
                graph[rel].add(target);graph[target].add(rel)
    return graph


def _v4224_select_ts_cluster(work, manifest, failure):
    rows=_v4222_parse_ts_diagnostics(work,failure)
    if not rows:return [],{}
    grouped={}
    for r in rows:grouped.setdefault(r['file'],[]).append(r)
    eligible=[]
    for rel,rr in grouped.items():
        evidence='\n'.join(x['raw'] for x in rr)
        if _v4222_provider_source_is_stable(work,manifest,rel) and not _v4222_provider_explicit_in_evidence(manifest,rel,evidence):
            continue
        eligible.append(rel)
    if not eligible:return [],grouped
    ranked=sorted(eligible,key=lambda x:_v4222_ts_target_rank(manifest,x,grouped.get(x) or []))
    seed=ranked[0];graph=_v4224_project_ts_graph(work,eligible)
    cluster=[];queue=[seed];seen=set()
    while queue and len(cluster)<V4224_MAX_CLUSTER_FILES:
        rel=queue.pop(0)
        if rel in seen:continue
        seen.add(rel);cluster.append(rel)
        nbrs=sorted(graph.get(rel) or [],key=lambda x:_v4222_ts_target_rank(manifest,x,grouped.get(x) or []))
        queue.extend([x for x in nbrs if x not in seen])
    # If the compiler family is obviously integration-shaped but the import parser did
    # not expose every edge, include the next compiler-owned consumers by rank.
    integration_codes={'2322','2339','2345','2554','2739','2741','7006','2304'}
    if any(str(r.get('code')) in integration_codes for r in rows):
        for rel in ranked:
            if len(cluster)>=V4224_MAX_CLUSTER_FILES:break
            if rel not in cluster:cluster.append(rel)
    return cluster,grouped


def _v4224_cluster_key(work, rows, cluster):
    token=_v429_progress_token(work)
    sig=_v4224_norm_diag_signature(rows)
    names='|'.join(sorted(_v40_norm_rel(x) for x in cluster))
    key=hashlib.sha256((token+'|'+sig+'|'+names).encode('utf-8')).hexdigest()[:28]
    return key,token,sig


def _v4224_cluster_row(work, rows, cluster, create=True):
    state=_v4224_state_load(work); key,token,sig=_v4224_cluster_key(work,rows,cluster)
    clusters=state.setdefault('clusters',{})
    row=clusters.get(key)
    if row is None and create:
        row={'token':token,'signature':sig,'files':list(cluster),'attempts':0,'exhausted':False,'created_at':_utc_stamp()};clusters[key]=row
        state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
    return state,key,row


def _v4224_cluster_is_exhausted(work, failure='', rel=''):
    rows=_v4222_parse_ts_diagnostics(work,failure) if failure else []
    token=_v429_progress_token(work);state=_v4224_state_load(work)
    for row in (state.get('clusters') or {}).values():
        if not isinstance(row,dict) or not row.get('exhausted') or row.get('token')!=token:continue
        files={_v40_norm_rel(x) for x in (row.get('files') or [])}
        if rel and _v40_norm_rel(rel) in files:return True
        if rows and any(_v40_norm_rel(r.get('file')) in files for r in rows):return True
    return False


def _v4224_clone_workspace(work):
    root=Path(work).resolve();base=root/'.jarvis_runtime'/'v4224_cluster';base.mkdir(parents=True,exist_ok=True)
    td=Path(tempfile.mkdtemp(prefix='candidate_',dir=str(base)));clone=td/'project'
    ignored=set(_ANALYSIS_IGNORE_DIRS)|{'.git','.jarvis_runtime','node_modules','target','dist','build','.next','.nuxt','__pycache__'}
    def ign(_d,names):return [n for n in names if n in ignored]
    copy_source_tree(root,clone,ignore=ign)
    # A cluster transaction is a new repair strategy. Do not inherit leaf-attempt caps
    # from the accepted workspace into this disposable clone.
    for name in (globals().get('V4221_STATE_FILE',''),globals().get('V4218_STATE_FILE','')):
        if name:
            try:(clone/name).unlink(missing_ok=True)
            except Exception:pass
    return td,clone


def _v4224_tsc_executable(original_root, component_root):
    names=['tsc.cmd','tsc'] if os.name=='nt' else ['tsc','tsc.cmd']
    for base in (component_root,original_root):
        for name in names:
            p=Path(base)/'node_modules'/'.bin'/name
            if p.exists():return str(p)
    return shutil.which('tsc') or ''


def _v4224_measure_typescript(original_work, candidate_work, manifest, hint_rel):
    orig=Path(original_work).resolve();clone=Path(candidate_work).resolve()
    comp=_v429_component_for_rel(manifest,hint_rel) or {}
    adapter=_v361_normalize_component_adapter(comp.get('toolchain_adapter'))
    if adapter not in _V4214_NODE_ADAPTERS:return None,'V42.24: target is not a Node/TypeScript component.'
    rootrel=_v40_norm_rel(comp.get('root')) or '.'
    ocwd=orig if rootrel=='.' else orig/rootrel;ccwd=clone if rootrel=='.' else clone/rootrel
    if not (ccwd/'tsconfig.json').exists():return None,'V42.24: tsconfig.json is unavailable.'
    tsc=_v4224_tsc_executable(orig,ocwd)
    if not tsc:return None,'V42.24: TypeScript compiler is unavailable.'
    outputs=[]
    configs=[]
    if (ccwd/'tsconfig.node.json').exists():configs.append('tsconfig.node.json')
    configs.append('tsconfig.json')
    for cfg in configs:
        ok,out=_run_command([tsc,'-p',cfg,'--pretty','false'],ccwd,V4224_TS_MEASURE_TIMEOUT)
        outputs.append(str(out or ''))
        if not ok and not _v4222_parse_ts_diagnostics(clone,'\n'.join(outputs)):
            return None,'\n'.join(outputs)
    text='\n'.join(outputs)
    return len(_v4222_parse_ts_diagnostics(clone,text)),text


def _v4224_cluster_problem_text(cluster, grouped):
    blocks=[]
    for rel in cluster:
        rows=grouped.get(rel) or []
        if not rows:continue
        blocks.append('### '+rel+'\n'+'\n'.join(x.get('raw') or '' for x in rows[:18]))
    return '\n\n'.join(blocks)


def _v4224_commit_cluster(work, clone, manifest, changed, before_count, after_count):
    root=Path(work);croot=Path(clone);prepared=[]
    for rel in changed:
        rel=_v40_norm_rel(rel);src=croot/rel;dst=root/rel
        try:candidate=src.read_text(encoding='utf-8',errors='replace')
        except Exception:return False,'candidate file unreadable: '+rel
        err=_content_validation_error(rel,candidate)
        if err:return False,f'{rel}: {err}'
        sem=_v4221_semantic_role_error(work,manifest or {},rel,candidate)
        if sem:return False,sem
        try:
            tx=_v4221_prev_candidate_transaction_error(work,manifest or {},rel,candidate,user_request=(manifest or {}).get('_original_user_request') or '',validation_failure='',target_problems=[])
        except Exception as exc:tx=str(exc)
        if tx:return False,f'{rel}: {tx}'
        prepared.append((rel,dst,candidate))
    backups={}
    temps=[]
    try:
        for rel,dst,candidate in prepared:
            backups[rel]=dst.read_bytes() if dst.exists() else None
            dst.parent.mkdir(parents=True,exist_ok=True);tmp=dst.with_name(dst.name+'.v4224.tmp')
            tmp.write_text(candidate,encoding='utf-8');temps.append(tmp)
        for (rel,dst,_),tmp in zip(prepared,temps):os.replace(tmp,dst)
        for rel,_,_ in prepared:_v413_mark_accepted(work,rel,'v4224_atomic_cluster_compiler_delta')
        try:_V36_REPO_CACHE.clear();_V36_CONTRACT_CACHE.clear()
        except Exception:pass
        _append_project_event(work,'v4224_cluster_committed',f'V42.24 atomically committed {len(prepared)} coordinated consumer file(s) after TypeScript diagnostics decreased {before_count} -> {after_count}.',files=[x[0] for x in prepared],before=before_count,after=after_count)
        return True,''
    except Exception as exc:
        for rel,dst,_ in prepared:
            try:
                old=backups.get(rel)
                if old is None:dst.unlink(missing_ok=True)
                else:dst.write_bytes(old)
            except Exception:pass
        return False,'atomic cluster commit rolled back: '+str(exc)
    finally:
        for tmp in temps:
            try:tmp.unlink(missing_ok=True)
            except Exception:pass


def _v4224_repair_ts_cluster(user_request, manifest, work, failure, progress_callback=None):
    if not V4224_ENABLE_CLUSTER_REPAIR:return None
    rows=_v4222_parse_ts_diagnostics(work,failure)
    cluster,grouped=_v4224_select_ts_cluster(work,manifest or {},failure)
    if len(cluster)<2:return None
    state,key,row=_v4224_cluster_row(work,rows,cluster,create=True)
    if row.get('exhausted') or int(row.get('attempts') or 0)>=V4224_MAX_CLUSTER_ATTEMPTS:
        row['exhausted']=True;row['updated_at']=_utc_stamp();state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
        _append_project_event(work,'v4224_cluster_reentry_suppressed','V42.24 suppressed repeated leaf/subsystem reasoning for an exhausted integration cluster at the same accepted revision.',files=cluster)
        return False
    attempt=int(row.get('attempts') or 0)+1;row['attempts']=attempt;row['updated_at']=_utc_stamp();state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
    before_count=len(rows);started=time.monotonic();td=None
    _progress(progress_callback,f'V42.24 coordinated TypeScript cluster attempt {attempt}/{V4224_MAX_CLUSTER_ATTEMPTS}: repairing {len(cluster)} compiler-connected consumer files transactionally before another real build.',stage='V42.24 coordinated consumer integration repair',percent=82,current_file=cluster[0],model_role=('worker' if attempt==1 else 'specialist'))
    try:
        td,clone=_v4224_clone_workspace(work)
        cluster_text=_v4224_cluster_problem_text(cluster,grouped)
        # Candidate patches are allowed to depend on each other in the disposable clone;
        # the global TypeScript delta, not a single-file delta, is the acceptance gate.
        global V4221_TS_ERROR_DELTA_GATE
        old_delta=V4221_TS_ERROR_DELTA_GATE;V4221_TS_ERROR_DELTA_GATE=False
        old_worker=getattr(_V4224_ROUTE,'force_worker',False);old_spec=getattr(_V4224_ROUTE,'force_specialist',False)
        _V4224_ROUTE.force_worker=(attempt==1);_V4224_ROUTE.force_specialist=(attempt>1)
        touched=[]
        try:
            for rel in cluster[:V4224_MAX_MODEL_FILES_PER_ATTEMPT]:
                if time.monotonic()-started>V4224_CLUSTER_WALL_SECONDS:break
                rr=grouped.get(rel) or []
                exact='\n'.join(x.get('raw') or '' for x in rr[:16])
                context=_v4222_ts_contract_context(clone,rel)
                problems=[
                    'V42.24 COORDINATED CLUSTER TRANSACTION. Repair only this file\'s compiler-proven consumer/wiring errors, while respecting the connected cluster diagnostics below. Do not mutate stable DTO/provider contracts unless this file itself is an explicitly compiler-proven provider error. The edits to other cluster files will be validated together before any source is promoted.\n\nTHIS FILE ERRORS:\n'+exact+'\n\nCONNECTED CLUSTER ERRORS:\n'+cluster_text[:9000]+('\n\nREAD-ONLY LOCAL CONTRACTS:\n'+context if context else '')
                ]
                try:
                    cand,err=_v36_patch_repair_candidate(user_request,manifest,clone,rel,problems,failure,1 if attempt==1 else 2,progress_callback)
                except Exception as exc:
                    cand=None;err=str(exc)
                if cand and cand.get('content') is not None:
                    p=Path(clone)/rel;p.write_text(str(cand['content']),encoding='utf-8');touched.append(rel)
                else:
                    _append_project_event(work,'v4224_cluster_file_no_candidate',f'V42.24 cluster attempt produced no safe candidate for {rel}; continuing with other connected consumers inside the disposable transaction.',file=rel,reason=str(err or '')[:1200],attempt=attempt)
        finally:
            V4221_TS_ERROR_DELTA_GATE=old_delta;_V4224_ROUTE.force_worker=old_worker;_V4224_ROUTE.force_specialist=old_spec
        if not touched:
            row['last_result']='no_safe_candidates'
            if attempt>=V4224_MAX_CLUSTER_ATTEMPTS:row['exhausted']=True
            state['clusters'][key]=row;state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
            return False
        changed=[]
        for rel in cluster:
            a=Path(work)/rel;b=Path(clone)/rel
            try:
                if a.read_bytes()!=b.read_bytes():changed.append(rel)
            except Exception:pass
        if not changed:return False
        after_count,measure=_v4224_measure_typescript(work,clone,manifest or {},cluster[0])
        if after_count is None:
            row['last_result']='measurement_unavailable';row['last_measurement']=str(measure or '')[-1600:]
            if attempt>=V4224_MAX_CLUSTER_ATTEMPTS:row['exhausted']=True
            state['clusters'][key]=row;state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
            _append_project_event(work,'v4224_cluster_measurement_unavailable','V42.24 refused to promote a multi-file candidate because trustworthy TypeScript measurement was unavailable.',files=changed,detail=str(measure or '')[-1600:])
            return False
        if int(after_count)>=int(before_count):
            row['last_result']='no_compiler_delta';row['before']=before_count;row['after']=after_count
            if attempt>=V4224_MAX_CLUSTER_ATTEMPTS:row['exhausted']=True
            state['clusters'][key]=row;state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
            _append_project_event(work,'v4224_cluster_rejected_no_delta',f'V42.24 rejected the entire coordinated candidate set because TypeScript diagnostics did not decrease ({before_count} -> {after_count}).',files=changed,before=before_count,after=after_count,attempt=attempt)
            return False
        ok,why=_v4224_commit_cluster(work,clone,manifest or {},changed,before_count,after_count)
        row['last_result']='committed' if ok else 'commit_rejected';row['before']=before_count;row['after']=after_count;row['files_changed']=changed
        if not ok and attempt>=V4224_MAX_CLUSTER_ATTEMPTS:row['exhausted']=True
        state['clusters'][key]=row;state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
        if not ok:_append_project_event(work,'v4224_cluster_commit_rejected','V42.24 preserved the accepted repository because the coordinated candidate failed a final transaction/semantic gate.',files=changed,reason=why)
        return bool(ok)
    finally:
        if td:
            try:shutil.rmtree(td,ignore_errors=True)
            except Exception:pass


# Intercept the authoritative whole-project repair round before V42.22's one-file
# consumer loop. If the cluster is exhausted at this accepted revision, do not fall
# through into the inherited leaf/subsystem path for the same TypeScript family.
_v4224_prev_repair_audit_round=_v429_repair_audit_round

def _v429_repair_audit_round(user_request,manifest,work,audit,progress_callback=None,round_no=1):
    for issue in list((audit or {}).get('issues') or []):
        if str((issue or {}).get('kind') or '')!='component_validation':continue
        failure=str((issue or {}).get('problem') or '')
        if len(_v4222_parse_ts_diagnostics(work,failure))<2:continue
        result=_v4224_repair_ts_cluster(user_request,manifest or {},work,failure,progress_callback)
        if result is True:return True
        if result is False and _v4224_cluster_is_exhausted(work,failure=failure):
            _append_project_event(work,'v4224_exhausted_cluster_stops_leaf_reentry','V42.24 stopped same-revision App/component/hook leaf repair after the coordinated cluster exhausted without compiler improvement.')
            return False
    return bool(_v4224_prev_repair_audit_round(user_request,manifest,work,audit,progress_callback,round_no))


_v4224_prev_real_validation_failure=_repair_real_validation_failure

def _repair_real_validation_failure(user_request,manifest,work,failure,progress_callback=None):
    rows=_v4222_parse_ts_diagnostics(work,failure)
    if len(rows)>=2:
        result=_v4224_repair_ts_cluster(user_request,manifest or {},work,failure,progress_callback)
        if result is not None:return bool(result)
    return bool(_v4224_prev_real_validation_failure(user_request,manifest,work,failure,progress_callback))


# Final leaf guard closes old exhausted-blocker/subsystem recovery paths that may call
# _repair_file_for_issues directly after the cluster transaction has already failed.
_v4224_prev_repair_file_for_issues=_repair_file_for_issues

def _repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback=None,validation_failure=None):
    if _v4224_cluster_is_exhausted(work,failure=str(validation_failure or ''),rel=rel):
        _append_project_event(work,'v4224_leaf_repair_suppressed',f'V42.24 suppressed repeated leaf repair for {rel}; its compiler-connected cluster is already exhausted at this accepted revision.',file=_v40_norm_rel(rel))
        return False
    return bool(_v4224_prev_repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback,validation_failure=validation_failure))


# Make the current policy the final instruction in every modern call. Historical
# checkpoint/provider text is explicitly subordinate to fresh compiler ownership.
_v4224_prev_qwen_call=_qwen_call

def _qwen_call(prompt,progress_callback=None,stage='Generating',profile='chat',**kwargs):
    body=str(prompt or '')+(
        '\n\nV42.24 FINAL REPAIR AUTHORITY: Fresh real compiler/build evidence owns the repair. '
        'For ordinary prop/argument/member/wiring errors, repair the compiler-located consumer and its connected consumers together; do not rewrite stable DTO/type providers just because they are nearby in an owner map. '
        'A provider may change only when fresh compiler evidence explicitly identifies that provider module/export/shape. Multi-file integration candidates are provisional until the whole TypeScript error count decreases. '
        'If a coordinated cluster is exhausted at the unchanged accepted revision, stop that repair family instead of re-entering older leaf/subsystem recovery.'
    )
    stage2=str(stage or '')
    for old in ('V42.23','V42.22','V42.21','V42.20','V42.19','V42.18','V42.17','V42.16','V42.13','V42.9','V42.8','V42.7','V42.6','V42.4'):
        stage2=stage2.replace(old,'V42.24')
    return _v4224_prev_qwen_call(body,progress_callback,stage2,profile=profile,**kwargs)


_v4224_prev_release_identity=_v36_release_identity

def _v36_release_identity():
    data=dict(_v4224_prev_release_identity() or {})
    data.update({
        'version':'V'+V4224_VERSION,
        'engine':V4224_ENGINE,
        'planner_mode':'compiler-directed-multifile-integration-transactions-v42.24',
        'compiler_connected_consumer_clusters':True,
        'atomic_multifile_typescript_commit':True,
        'cluster_commit_requires_global_ts_error_reduction':True,
        'same_revision_exhausted_cluster_blocks_leaf_reentry':True,
        'stable_provider_blanket_prepass_disabled':True,
        'first_cluster_attempt_worker_9b':True,
        'second_cluster_attempt_specialist_27b':True,
        'max_cluster_files':V4224_MAX_CLUSTER_FILES,
        'max_model_files_per_cluster_attempt':V4224_MAX_MODEL_FILES_PER_ATTEMPT,
        'max_cluster_attempts_per_revision':V4224_MAX_CLUSTER_ATTEMPTS,
        'cluster_wall_seconds':V4224_CLUSTER_WALL_SECONDS,
        'v4223_resume_policy_and_ts_burndown_preserved':True,
    })
    return data


_v4224_prev_progress=_progress

def _progress(callback,text=None,**fields):
    if text is not None:
        text=str(text)
        for old in ('V42.23','V42.22','V42.21','V42.20','V42.19','V42.18','V42.17','V42.16','V42.13','V42.9','V42.8','V42.7','V42.6','V42.4'):
            text=text.replace(old,'V42.24')
    return _v4224_prev_progress(callback,text,**fields)

# =============================================================================
# V42.25 SEMANTIC NAVIGATION / EVENT PROJECTION / LOOP HYGIENE / SPILL /
#        PROVISIONAL MULTI-FILE TRANSACTIONS
# =============================================================================
# This pass adopts the highest-value harness patterns without replacing Jarvis's
# universal factory architecture:
#   * narrow read-only semantic navigation (text index + optional installed LSP),
#   * append-only journal events projected into one current convergence view,
#   * a global same-revision repair fingerprint guard,
#   * durable spill files for oversized model context,
#   * strict source/artifact separation for disposable transactions,
#   * and, critically, a provisional multi-file gate that lets mutually-dependent
#     consumer edits accumulate before replaying the whole TypeScript build.
#
# V42.24's cluster transaction still called the ordinary single-file V42.16 replay
# gate while assembling the cluster.  That gate correctly rejected an App.tsx edit
# when the *whole* project failure was unchanged -- but in a coordinated transaction
# the failure may not improve until App.tsx + hooks + views are all staged together.
# V42.25 keeps syntax/semantic safety on every provisional file, defers only the
# no-progress whole-build replay until the complete candidate set exists, then makes
# the real project-wide TypeScript delta the atomic commit authority.

V4225_VERSION='42.25.0'
V4225_ENGINE='SEMANTIC_EVENT_GUARDED_PROVISIONAL_CLUSTER_FACTORY'
V4225_PROJECTION_FILE='JARVIS_V4225_EVENT_PROJECTION.json'
V4225_LOOP_GUARD_FILE='JARVIS_V4225_LOOP_GUARD.json'
V4225_MAX_IDENTICAL_REPAIR_CALLS=max(1,min(5,int(os.getenv('JARVIS_V4225_MAX_IDENTICAL_REPAIR_CALLS','2'))))
V4225_PROMPT_SPILL_CHARS=max(12000,min(200000,int(os.getenv('JARVIS_V4225_PROMPT_SPILL_CHARS','26000'))))
V4225_SEMANTIC_CONTEXT_CHARS=max(4000,min(30000,int(os.getenv('JARVIS_V4225_SEMANTIC_CONTEXT_CHARS','14000'))))
V4225_LSP=os.getenv('JARVIS_V4225_LSP','auto').strip().lower() not in {'0','false','no','off','disabled'}
V4225_MAX_CLUSTER_MODEL_FILES=max(2,min(8,int(os.getenv('JARVIS_V4225_MAX_CLUSTER_MODEL_FILES','4'))))
V4225_CLUSTER_WALL_SECONDS=max(120,min(900,int(os.getenv('JARVIS_V4225_CLUSTER_WALL_SECONDS','420'))))
V4225_EVENT_PROJECTION=True
V4225_SOURCE_ARTIFACT_SEPARATION=True

try:
    from jarvis_v4225_semantic import semantic_context as _v4225_semantic_context_impl
except Exception:
    _v4225_semantic_context_impl=None

_V4225_CTX=threading.local() if 'threading' in globals() else _v426_threading.local()
_V4225_LOCK=threading.RLock() if 'threading' in globals() else _v426_threading.RLock()
_V4225_SEM_CACHE={}


def _v4225_json_load(path,default=None):
    try:
        x=json.loads(Path(path).read_text(encoding='utf-8',errors='replace'))
        return x
    except Exception:return {} if default is None else default


def _v4225_json_save(path,data):
    try:
        p=Path(path);p.parent.mkdir(parents=True,exist_ok=True)
        tmp=p.with_name(p.name+'.tmp')
        tmp.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
        os.replace(tmp,p)
        return True
    except Exception:return False


def _v4225_artifact_root(work):
    root=Path(work).resolve()
    # Keep compiler/model artifacts beside the transactional project directory, not
    # inside authored source.  This prevents checkpoint ZIPs from copying gigabytes
    # of target/node_modules/model spill state into every trial.
    parent=root.parent
    project_key=hashlib.sha256(str(root).encode('utf-8',errors='replace')).hexdigest()[:12]
    base=parent/'.jarvis_artifacts'/project_key
    try:base.mkdir(parents=True,exist_ok=True)
    except Exception:pass
    return base


def _v4225_diag_signature(work,failure):
    try:rows=_v4222_parse_ts_diagnostics(work,failure)
    except Exception:rows=[]
    if rows:
        vals=[(_v40_norm_rel(r.get('file')),str(r.get('code') or ''),re.sub(r'\s+',' ',str(r.get('message') or '')).strip().lower()) for r in rows]
        return hashlib.sha256(json.dumps(sorted(vals),separators=(',',':'),ensure_ascii=False).encode('utf-8')).hexdigest()[:24]
    raw=re.sub(r'\s+',' ',str(failure or '')).strip().lower()
    return hashlib.sha256(raw[-12000:].encode('utf-8',errors='replace')).hexdigest()[:24]


def _v4225_strategy_name(problems):
    text=' '.join(str(x or '') for x in (problems or []))
    first=(text.splitlines()[0] if text else 'repair').strip().lower()
    first=re.sub(r'\s+',' ',first)
    return first[:180]


def _v4225_loop_key(work,rel,problems,failure):
    guard_work=Path(getattr(_V4225_CTX,'guard_work',work) or work)
    try:token=_v429_progress_token(guard_work)
    except Exception:token='unknown'
    payload={'repo':token,'target':_v40_norm_rel(rel),'diag':_v4225_diag_signature(guard_work,failure),'strategy':_v4225_strategy_name(problems)}
    key=hashlib.sha256(json.dumps(payload,sort_keys=True,separators=(',',':')).encode('utf-8')).hexdigest()[:28]
    return key,payload,guard_work


def _v4225_loop_guard_before(work,rel,problems,failure):
    key,payload,guard_work=_v4225_loop_key(work,rel,problems,failure)
    path=guard_work/V4225_LOOP_GUARD_FILE
    with _V4225_LOCK:
        data=_v4225_json_load(path,{'actions':{}})
        actions=data.setdefault('actions',{})
        row=actions.get(key) or {'count':0,'payload':payload,'first_at':_utc_stamp()}
        count=int(row.get('count') or 0)
        if count>=V4225_MAX_IDENTICAL_REPAIR_CALLS:
            row['blocked_at']=_utc_stamp();row['blocked_count']=count+1;actions[key]=row;data['updated_at']=_utc_stamp();_v4225_json_save(path,data)
            try:_append_project_event(guard_work,'v4225_repeat_repair_blocked','V42.25 global loop hygiene blocked another information-free repair call at the same accepted revision; fresh build/semantic evidence or a different target is required.',file=_v40_norm_rel(rel),fingerprint=key,count=count,payload=payload)
            except Exception:pass
            return False,key,payload
        row['count']=count+1;row['last_at']=_utc_stamp();actions[key]=row;data['updated_at']=_utc_stamp();_v4225_json_save(path,data)
    return True,key,payload


# ---- Durable event projection -------------------------------------------------
_v4225_prev_append_project_event=_append_project_event

def _append_project_event(work,event_type,message,**fields):
    # Existing JARVIS_PROJECT_JOURNAL.jsonl remains the durable append-only stream;
    # V42.25 merely gives new events stable sequence/id metadata and derives one
    # compact projection from that stream rather than inventing another policy source.
    root=Path(work)
    seq=0
    proj_path=root/V4225_PROJECTION_FILE
    try:
        proj=_v4225_json_load(proj_path,{})
        seq=int(proj.get('seq') or 0)+1
    except Exception:proj={};seq=1
    enriched=dict(fields)
    enriched.setdefault('event_seq',seq)
    enriched.setdefault('event_id',hashlib.sha256((str(root.resolve())+'|'+str(seq)+'|'+str(event_type)+'|'+str(message)).encode('utf-8',errors='replace')).hexdigest()[:24])
    enriched.setdefault('engine_version','V'+V4225_VERSION)
    event=_v4225_prev_append_project_event(work,event_type,message,**enriched)
