# ---- Semantic code intelligence ------------------------------------------------
_v4225_prev_ts_contract_context=_v4222_ts_contract_context

def _v4222_ts_contract_context(work,rel):
    base=_v4225_prev_ts_contract_context(work,rel)
    if _v4225_semantic_context_impl is None:return base
    grouped=getattr(_V4225_CTX,'semantic_rows',{}) or {}
    rows=grouped.get(_v40_norm_rel(rel),[]) if isinstance(grouped,dict) else []
    use_lsp=bool(V4225_LSP and getattr(_V4224_ROUTE,'force_specialist',False))
    try:
        token=_v429_progress_token(work)
    except Exception:token='unknown'
    key=(str(Path(work).resolve()),token,_v40_norm_rel(rel),bool(use_lsp),_v4224_norm_diag_signature(rows) if rows else '')
    extra=_V4225_SEM_CACHE.get(key)
    if extra is None:
        try:extra=_v4225_semantic_context_impl(work,_v40_norm_rel(rel),rows,use_lsp=use_lsp,max_chars=V4225_SEMANTIC_CONTEXT_CHARS)
        except Exception as exc:extra=''
        if len(_V4225_SEM_CACHE)>160:_V4225_SEM_CACHE.clear()
        _V4225_SEM_CACHE[key]=extra
    if not extra:return base
    room=max(0,V4222_CONTRACT_CONTEXT_CHARS+V4225_SEMANTIC_CONTEXT_CHARS-len(base))
    return (base+'\n\n===== V42.25 READ-ONLY SEMANTIC NAVIGATION =====\n'+str(extra)[:room]).strip()


# ---- Better cluster target leverage --------------------------------------------
_v4225_prev_select_ts_cluster=_v4224_select_ts_cluster

def _v4225_target_leverage(rel,rows):
    r=_v40_norm_rel(rel);name=Path(r).name.lower();low='/'+r.lower().strip('/')+'/'
    count=len(rows or []);codes={str(x.get('code') or '') for x in (rows or [])}
    score=count*12
    if name in {'app.tsx','app.jsx','main.tsx','main.jsx'}:score+=140
    if any(x in low for x in ('/hooks/','/services/','/stores/','/controllers/')):score+=95
    elif any(x in low for x in ('/components/','/views/','/pages/','/screens/')):score+=75
    if codes & {'2339','2345','2554','2739','2741','2322','2304','7006'}:score+=25
    if '/types/' in low:score-=120
    return (-score,r)


def _v4224_select_ts_cluster(work,manifest,failure):
    cluster,grouped=_v4225_prev_select_ts_cluster(work,manifest,failure)
    # V42.24's BFS could fill the bounded cluster with views before high-error hooks
    # such as useCheckouts/useCSVImportExport were ever considered.  Keep the graph
    # discovery, then merge every compiler-owned non-provider consumer from the same
    # diagnostic family and choose the highest-leverage bounded set.
    eligible=[]
    for rel,rr in grouped.items():
        evidence='\n'.join(x.get('raw') or '' for x in rr)
        if _v4222_provider_source_is_stable(work,manifest or {},rel) and not _v4222_provider_explicit_in_evidence(manifest or {},rel,evidence):
            continue
        eligible.append(rel)
    pool=list(dict.fromkeys(list(cluster)+eligible))
    ranked=sorted(pool,key=lambda r:_v4225_target_leverage(r,grouped.get(r) or []))
    # App/main are integration roots; keep one first when compiler evidence points
    # there, then use leverage ordering for the remaining hooks/components.
    roots=[r for r in ranked if Path(r).name.lower() in {'app.tsx','app.jsx','main.tsx','main.jsx'}]
    chosen=[]
    if roots:chosen.append(roots[0])
    for rel in ranked:
        if rel in chosen:continue
        chosen.append(rel)
        if len(chosen)>=V4224_MAX_CLUSTER_FILES:break
    return chosen,grouped


# ---- Source plane / artifact plane ---------------------------------------------
_v4225_prev_clone_workspace=_v4224_clone_workspace

def _v4224_clone_workspace(work):
    if not V4225_SOURCE_ARTIFACT_SEPARATION:return _v4225_prev_clone_workspace(work)
    root=Path(work).resolve();base=_v4225_artifact_root(root)/'transactions';base.mkdir(parents=True,exist_ok=True)
    td=Path(tempfile.mkdtemp(prefix='candidate_',dir=str(base)));clone=td/'project'
    ignored=set(_ANALYSIS_IGNORE_DIRS)|{'.git','.jarvis_runtime','.jarvis_artifacts','node_modules','target','dist','build','.next','.nuxt','__pycache__','.cache','.gradle','.dart_tool'}
    def ign(_d,names):return [n for n in names if n in ignored]
    copy_source_tree(root,clone,ignore=ign)
    for name in (globals().get('V4221_STATE_FILE',''),globals().get('V4218_STATE_FILE',''),V4225_LOOP_GUARD_FILE,V4225_PROJECTION_FILE):
        if name:
            try:(clone/name).unlink(missing_ok=True)
            except Exception:pass
    return td,clone


def _v4225_diff_source_files(work,clone):
    root=Path(work);croot=Path(clone);changed=[]
    ignore={'.git','node_modules','target','dist','build','.next','.nuxt','.jarvis_runtime','.jarvis_artifacts','__pycache__','.cache'}
    for p in croot.rglob('*'):
        if not p.is_file():continue
        try:rel=p.relative_to(croot);parts=set(rel.parts)
        except Exception:continue
        if parts & ignore:continue
        if rel.name.startswith('JARVIS_') or rel.name.startswith('.jarvis_'):continue
        a=root/rel
        try:
            if not a.exists() or a.read_bytes()!=p.read_bytes():changed.append(rel.as_posix())
        except Exception:continue
    return sorted(set(changed))


# ---- Durable prompt spill layered under existing token compaction ---------------
_v4225_prev_qwen_budget_prompt=_qwen_budget_prompt

def _v4225_prompt_diag_index(raw):
    rows=[];seen=set()
    pat=re.compile(r'(?m)^(?P<file>[^\n]+?\.(?:ts|tsx|js|jsx|rs|py|go|java|cs|cpp|c))(?P<loc>\([^\n)]*\)|:\d+:\d+)?[^\n]*?(?:error\s+)?(?:TS\d{4}|error(?:\[[^\]]+\])?):\s*(?P<msg>[^\n]+)',re.I)
    for m in pat.finditer(str(raw or '')):
        line=re.sub(r'\s+',' ',m.group(0)).strip()
        if line in seen:continue
        seen.add(line);rows.append(line[:500])
        if len(rows)>=28:break
    return '\n'.join('- '+x for x in rows)


def _qwen_budget_prompt(prompt,max_tokens=None,progress_callback=None,stage='Generating',profile=None):
    raw=str(prompt or '')
    compacted=_v4225_prev_qwen_budget_prompt(raw,max_tokens=max_tokens,progress_callback=progress_callback,stage=stage,profile=profile)
    if len(raw)<V4225_PROMPT_SPILL_CHARS or compacted==raw:return compacted
    work=getattr(_V4225_CTX,'prompt_work',None)
    try:
        base=(_v4225_artifact_root(work)/'spill') if work else (JARVIS_DIR/'.jarvis_artifacts'/'spill')
        base.mkdir(parents=True,exist_ok=True)
        digest=hashlib.sha256(raw.encode('utf-8',errors='replace')).hexdigest()[:16]
        p=base/f'prompt_{digest}.txt'
        if not p.exists():p.write_text(raw,encoding='utf-8')
        index=_v4225_prompt_diag_index(raw)
        note=(
            '\n\n[V42.25 CONTEXT SPILL]\n'
            f'Full pre-compaction context was retained at: {p}\n'
            'The inline prompt is intentionally bounded. Do not infer missing facts; use the retained artifact only if the available focused evidence is insufficient.\n'
        )
        if index:note+='Compiler diagnostic index from spilled context:\n'+index[:4200]+'\n'
        # Keep the compacted prompt itself bounded; diagnostic index replaces less-useful
        # middle context rather than restoring the original bloat.
        return (compacted+'\n'+note)[:max(len(compacted)+5000,8000)]
    except Exception:return compacted


# ---- V42.25 coordinated cluster transaction ------------------------------------
_v4225_prev_cluster_repair=_v4224_repair_ts_cluster

def _v4224_repair_ts_cluster(user_request,manifest,work,failure,progress_callback=None):
    if not V4224_ENABLE_CLUSTER_REPAIR:return None
    rows=_v4222_parse_ts_diagnostics(work,failure)
    cluster,grouped=_v4224_select_ts_cluster(work,manifest or {},failure)
    if len(cluster)<2:return None
    state,key,row=_v4224_cluster_row(work,rows,cluster,create=True)
    if row.get('exhausted') or int(row.get('attempts') or 0)>=V4224_MAX_CLUSTER_ATTEMPTS:
        row['exhausted']=True;row['updated_at']=_utc_stamp();state['clusters'][key]=row;state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
        _append_project_event(work,'v4225_cluster_reentry_suppressed','V42.25 suppressed a same-revision coordinated cluster after its bounded attempts were already consumed.',files=cluster)
        return False
    attempt=int(row.get('attempts') or 0)+1;row['attempts']=attempt;row['updated_at']=_utc_stamp();state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
    accepted_before=len(rows);started=time.monotonic();td=None
    _progress(progress_callback,f'V42.25 semantic compiler cluster attempt {attempt}/{V4224_MAX_CLUSTER_ATTEMPTS}: staging connected consumer/hook repairs provisionally, then measuring the complete TypeScript candidate once.',stage='V42.25 semantic provisional multi-file repair',percent=82,current_file=cluster[0],model_role=('worker' if attempt==1 else 'specialist'))
    try:
        td,clone=_v4224_clone_workspace(work)
        # First burn down compiler-proven hygiene in the disposable clone.  If that
        # alone improves the project, commit it and force a real rebuild immediately.
        deterministic=[]
        try:deterministic=_v4223_bulk_ts_recovery(clone,manifest or {},failure,None) or []
        except Exception:deterministic=[]
        current_count,current_output=_v4224_measure_typescript(work,clone,manifest or {},cluster[0])
        if current_count is not None and int(current_count)<int(accepted_before):
            changed=_v4225_diff_source_files(work,clone)
            if changed:
                ok,why=_v4224_commit_cluster(work,clone,manifest or {},changed,accepted_before,current_count)
                row.update({'last_result':'deterministic_committed' if ok else 'commit_rejected','before':accepted_before,'after':current_count,'files_changed':changed,'updated_at':_utc_stamp()})
                state['clusters'][key]=row;state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
                if ok:
                    _append_project_event(work,'v4225_deterministic_cluster_committed',f'V42.25 committed deterministic compiler burn-down before any model call ({accepted_before} -> {current_count}); a fresh build is now required.',files=changed,before=accepted_before,after=current_count)
                    return True
                _append_project_event(work,'v4225_deterministic_cluster_commit_rejected','V42.25 deterministic burn-down improved TypeScript but failed final semantic/transaction gates.',files=changed,reason=why)
        # Re-localize against the post-deterministic clone so model prompts do not use
        # stale line numbers or already-fixed diagnostics.
        model_failure=str(current_output or failure)
        model_rows=_v4222_parse_ts_diagnostics(clone,model_failure)
        model_cluster,model_grouped=_v4224_select_ts_cluster(clone,manifest or {},model_failure)
        if len(model_cluster)>=2:
            cluster=model_cluster
            grouped=model_grouped
        cluster_text=_v4224_cluster_problem_text(cluster,grouped)
        global V4221_TS_ERROR_DELTA_GATE
        old_delta=V4221_TS_ERROR_DELTA_GATE;V4221_TS_ERROR_DELTA_GATE=False
        old_worker=getattr(_V4224_ROUTE,'force_worker',False);old_spec=getattr(_V4224_ROUTE,'force_specialist',False)
        old_guard=getattr(_V4225_CTX,'guard_work',None);old_prov=getattr(_V4225_CTX,'provisional_cluster',False);old_rows=getattr(_V4225_CTX,'semantic_rows',None);old_prompt=getattr(_V4225_CTX,'prompt_work',None)
        _V4224_ROUTE.force_worker=(attempt==1);_V4224_ROUTE.force_specialist=(attempt>1)
        _V4225_CTX.guard_work=work;_V4225_CTX.provisional_cluster=True;_V4225_CTX.semantic_rows=grouped;_V4225_CTX.prompt_work=work
        touched=[]
        try:
            targets=_v4226_dependency_order(clone, cluster)[:max(1,min(V4225_MAX_CLUSTER_MODEL_FILES,V4224_MAX_CLUSTER_FILES))]
            for rel in targets:
                if time.monotonic()-started>V4225_CLUSTER_WALL_SECONDS:break
                rr=grouped.get(rel) or []
                if not rr:continue
                exact='\n'.join(x.get('raw') or '' for x in rr[:18])
                context=_v4222_ts_contract_context(clone,rel)
                try:
                    producer=_v4223_nearby_producer_context(clone,rel,rr)
                except Exception:producer=''
                problems=[
                    'V42.25 PROVISIONAL COORDINATED TRANSACTION. This file is one edge of a connected compiler failure. Make the smallest consumer/hook/service repair proven by its diagnostics. Other connected files are being staged in the same disposable workspace, so this provisional file is NOT required to make the whole build green by itself. Preserve stable DTO/provider contracts unless fresh compiler evidence explicitly points to that provider.\n\nTHIS FILE ERRORS:\n'+exact+'\n\nCONNECTED CLUSTER ERRORS:\n'+cluster_text[:7600]+('\n\nREAD-ONLY SEMANTIC CONTRACT/NAVIGATION:\n'+context if context else '')+('\n\nREAD-ONLY AVAILABLE PRODUCERS:\n'+producer if producer else '')
                ]
                try:cand,err=_v36_patch_repair_candidate(user_request,manifest,clone,rel,problems,model_failure,1 if attempt==1 else 2,progress_callback)
                except Exception as exc:cand=None;err=str(exc)
                if cand and cand.get('content') is not None:
                    p=Path(clone)/rel;p.write_text(str(cand['content']),encoding='utf-8');touched.append(rel)
                else:
                    _append_project_event(work,'v4225_cluster_file_no_candidate',f'V42.25 produced no safe provisional candidate for {rel}; the transaction will continue with other compiler-owned files.',file=rel,reason=str(err or '')[:1400],attempt=attempt)
        finally:
            V4221_TS_ERROR_DELTA_GATE=old_delta;_V4224_ROUTE.force_worker=old_worker;_V4224_ROUTE.force_specialist=old_spec
            _V4225_CTX.guard_work=old_guard;_V4225_CTX.provisional_cluster=old_prov;_V4225_CTX.semantic_rows=old_rows;_V4225_CTX.prompt_work=old_prompt
        changed=_v4225_diff_source_files(work,clone)
        if not changed:
            row['last_result']='no_safe_candidates';row['updated_at']=_utc_stamp()
            if attempt>=V4224_MAX_CLUSTER_ATTEMPTS:row['exhausted']=True
            state['clusters'][key]=row;state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
            return False
        after_count,measure=_v4224_measure_typescript(work,clone,manifest or {},cluster[0])
        if after_count is None:
            row['last_result']='measurement_unavailable';row['last_measurement']=str(measure or '')[-1800:];row['updated_at']=_utc_stamp()
            if attempt>=V4224_MAX_CLUSTER_ATTEMPTS:row['exhausted']=True
            state['clusters'][key]=row;state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
            _append_project_event(work,'v4225_cluster_measurement_unavailable','V42.25 refused to promote the provisional multi-file transaction because trustworthy TypeScript measurement was unavailable.',files=changed,detail=str(measure or '')[-1800:])
            return False
        if int(after_count)>=int(accepted_before):
            row.update({'last_result':'no_compiler_delta','before':accepted_before,'after':after_count,'files_changed':changed,'updated_at':_utc_stamp()})
            if attempt>=V4224_MAX_CLUSTER_ATTEMPTS:row['exhausted']=True
            state['clusters'][key]=row;state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
            _append_project_event(work,'v4225_cluster_rejected_no_delta',f'V42.25 rejected the entire provisional transaction because real TypeScript diagnostics did not decrease ({accepted_before} -> {after_count}).',files=changed,before=accepted_before,after=after_count,attempt=attempt)
            return False
        ok,why=_v4224_commit_cluster(work,clone,manifest or {},changed,accepted_before,after_count)
        row.update({'last_result':'committed' if ok else 'commit_rejected','before':accepted_before,'after':after_count,'files_changed':changed,'updated_at':_utc_stamp()})
        if not ok and attempt>=V4224_MAX_CLUSTER_ATTEMPTS:row['exhausted']=True
        state['clusters'][key]=row;state['updated_at']=_utc_stamp();_v4224_state_save(work,state)
        if ok:
            _append_project_event(work,'v4225_semantic_cluster_committed',f'V42.25 atomically committed the connected compiler repair after diagnostics decreased {accepted_before} -> {after_count}.',files=changed,before=accepted_before,after=after_count,attempt=attempt)
        else:
            _append_project_event(work,'v4225_cluster_commit_rejected','V42.25 preserved the accepted source because final transaction/semantic checks rejected the coordinated candidate.',files=changed,reason=why)
        return bool(ok)
    finally:
        if td:
            try:shutil.rmtree(td,ignore_errors=True)
            except Exception:pass


# Current policy must be the final model-visible authority.  Mention semantic evidence
# as a precision aid, not a license for speculative refactors.
_v4225_prev_qwen_call=_qwen_call

def _qwen_call(prompt,progress_callback=None,stage='Generating',profile='chat',**kwargs):
    body=str(prompt or '')+(
        '\n\nV42.25 FINAL CONVERGENCE AUTHORITY: Treat fresh compiler/build output as the source of repair ownership. Use read-only semantic definition/reference/contract evidence to resolve ambiguous wiring before editing. During a coordinated multi-file transaction, an individual provisional file does not have to eliminate the whole project failure; preserve its syntax/semantic role and let Jarvis measure the complete staged set. Never repeat an identical same-revision repair after the global loop guard says it is exhausted. Oversized context may be retained in a spill artifact; the focused inline evidence is authoritative unless additional retained evidence is explicitly needed.'
    )
    stage2=str(stage or '')
    for old in ('V42.24','V42.23','V42.22','V42.21','V42.20','V42.19','V42.18','V42.17','V42.16','V42.13','V42.9','V42.8','V42.7','V42.6','V42.4'):
        stage2=stage2.replace(old,'V42.25')
    return _v4225_prev_qwen_call(body,progress_callback,stage2,profile=profile,**kwargs)


