# =============================================================================
# V42.27 PARSER-SAFE COMPILER DELTA + DETERMINISTIC STRUCTURAL RECOVERY
# =============================================================================
# V42.26 correctly made the complete TypeScript diagnostic delta the authority for
# coordinated commits, but a total-count improvement could still hide a regression:
# a changed file could introduce a brand-new parser/syntax diagnostic while unrelated
# diagnostics disappeared elsewhere (observed as 10 -> 3 while DashboardView.tsx
# acquired TS1128).  Once accepted, that malformed file fell back into bounded model
# repair even though the structural defect was mechanically local.
#
# V42.27 closes both gaps without weakening the transactional gate:
#   * real TypeScript measurement is cached and the atomic cluster commit refuses any
#     candidate whose CHANGED files still contain compiler parser/syntax diagnostics;
#   * compiler parser codes/messages are recognized as syntax failures by the early
#     deterministic ladder;
#   * orphaned top-level TS/TSX fragments (for example a return/body left behind after
#     an unused helper declaration disappeared) are conservatively excised only when
#     the real TypeScript compiler proves that the target syntax blocker disappears;
#   * typed arrow-function locals proven unused by TS6133 are removed as one balanced
#     declaration block, never by a partial line/regex edit;
#   * event/progress identity is advanced consistently so a V42.27 run does not stamp
#     new journal events as V42.25/V42.26.

V4227_VERSION='42.27.0'
V4227_ENGINE='PARSER_SAFE_COMPILER_DELTA_STRUCTURAL_RECOVERY_FACTORY'
V4227_STRUCTURAL_REPORT='JARVIS_V4227_STRUCTURAL_RECOVERY.json'
V4227_ENABLE_STRUCTURAL_RECOVERY=os.getenv('JARVIS_V4227_STRUCTURAL_RECOVERY','1').strip().lower() not in {'0','false','no','off'}
V4227_REQUIRE_CHANGED_FILES_SYNTAX_CLEAN=os.getenv('JARVIS_V4227_CHANGED_FILE_SYNTAX_GATE','1').strip().lower() not in {'0','false','no','off'}

# Common TypeScript parser/syntax-family diagnostics.  This is intentionally limited
# to grammar/lexing failures; semantic/type errors remain eligible for normal compiler
# delta convergence.
V4227_TS_SYNTAX_CODES={
    '1002','1003','1005','1009','1010','1039','1109','1128','1131','1134','1135',
    '1144','1160','1161','1184','1381','1382','17008','17014','17015'
}
V4227_TS_SYNTAX_MESSAGE_RE=re.compile(
    r'(?:declaration or statement expected|expression expected|identifier expected|'
    r"['\"}`)\]]\s+expected|unterminated (?:string|template|regular expression)|"
    r'jsx element .* has no corresponding closing tag|unexpected token|parser|parse error)',
    re.I,
)

_V4227_MEASURE_CACHE={}
_V4227_MEASURE_LOCK=threading.RLock() if 'threading' in globals() else _v426_threading.RLock()


def _v4227_ts_diag_is_syntax(row):
    row=row or {}
    code=str(row.get('code') or '')
    msg=str(row.get('message') or row.get('raw') or '')
    return code in V4227_TS_SYNTAX_CODES or bool(V4227_TS_SYNTAX_MESSAGE_RE.search(msg))


def _v4227_syntax_rows(work,failure,files=None):
    wanted={_v40_norm_rel(x) for x in (files or []) if _v40_norm_rel(x)}
    rows=[]
    try:parsed=_v4222_parse_ts_diagnostics(work,str(failure or ''))
    except Exception:parsed=[]
    for row in parsed:
        if not _v4227_ts_diag_is_syntax(row):continue
        rel=_v40_norm_rel(row.get('file'))
        if wanted and rel not in wanted:continue
        rows.append(row)
    return rows


# Cache the exact compiler output already produced immediately before cluster commit.
# The commit gate can therefore inspect syntax diagnostics without running a redundant
# full TypeScript build on every successful candidate.
_v4227_prev_measure_typescript=_v4224_measure_typescript

def _v4224_measure_typescript(original_work,candidate_work,manifest,hint_rel):
    result=_v4227_prev_measure_typescript(original_work,candidate_work,manifest,hint_rel)
    try:
        count,out=result
        key=str(Path(candidate_work).resolve())
        rows=_v4222_parse_ts_diagnostics(candidate_work,str(out or '')) if out is not None else []
        with _V4227_MEASURE_LOCK:
            _V4227_MEASURE_CACHE[key]={'count':count,'output':str(out or ''),'rows':rows,'at':time.time()}
            if len(_V4227_MEASURE_CACHE)>96:
                oldest=sorted(_V4227_MEASURE_CACHE.items(),key=lambda kv:float((kv[1] or {}).get('at') or 0))[:32]
                for k,_ in oldest:_V4227_MEASURE_CACHE.pop(k,None)
    except Exception:pass
    return result


def _v4227_cached_measure(candidate_work):
    key=str(Path(candidate_work).resolve())
    with _V4227_MEASURE_LOCK:
        row=_V4227_MEASURE_CACHE.get(key)
        return dict(row) if isinstance(row,dict) else {}


# Global error-count improvement is necessary but not sufficient: a coordinated
# candidate is never allowed to promote a changed TS/TSX file that the REAL compiler
# still reports as syntactically malformed.  This specifically prevents a 10 -> 3
# transaction from trading semantic errors for a new TS1128 parser failure.
_v4227_prev_commit_cluster=_v4224_commit_cluster

def _v4224_commit_cluster(work,clone,manifest,changed,before_count,after_count):
    changed_norm=[_v40_norm_rel(x) for x in (changed or [])]
    if V4227_REQUIRE_CHANGED_FILES_SYNTAX_CLEAN:
        measured=_v4227_cached_measure(clone)
        rows=list(measured.get('rows') or [])
        bad=[r for r in rows if _v40_norm_rel(r.get('file')) in set(changed_norm) and _v4227_ts_diag_is_syntax(r)]
        if bad:
            detail='; '.join(str(r.get('raw') or r.get('message') or '')[:500] for r in bad[:8])
            try:_append_project_event(work,'v4227_cluster_syntax_regression_rejected',
                'V42.27 rejected an otherwise improving coordinated transaction because a changed TypeScript file remained parser-invalid under the real compiler.',
                files=changed_norm,syntax_diagnostics=[str(r.get('raw') or '')[:700] for r in bad[:12]],before=before_count,after=after_count)
            except Exception:pass
            return False,'V42.27 changed-file syntax gate rejected compiler parser diagnostics: '+detail
    return _v4227_prev_commit_cluster(work,clone,manifest,changed,before_count,after_count)


# V42.18 originally recognized generic "syntax" wording but TypeScript normally emits
# messages such as "TS1128: Declaration or statement expected."  Make those errors
# first-class deterministic syntax blockers instead of sending them straight to Qwen.
_v4227_prev_is_syntax_problem=_v4218_is_syntax_problem

def _v4218_is_syntax_problem(rel,problems,validation_failure=''):
    if _v4227_prev_is_syntax_problem(rel,problems,validation_failure):return True
    reln=_v40_norm_rel(rel);ext=Path(reln).suffix.lower()
    if ext not in {'.ts','.tsx','.mts','.cts','.js','.jsx'}:return False
    if _v4227_syntax_rows(Path('.'),validation_failure):
        # _v4222 parser requires files to exist under work, so fall through to text
        # matching here when work is unavailable in this legacy signature.
        pass
    text=_v4218_problem_text(problems,validation_failure)
    if re.search(r'\bTS(?:'+ '|'.join(sorted(V4227_TS_SYNTAX_CODES)) +r')\b',text,re.I):return True
    return bool(V4227_TS_SYNTAX_MESSAGE_RE.search(text))


def _v4227_mask_braces_line(line):
    """Mask quoted/template characters enough for conservative top-level brace depth.

    This is not a TypeScript parser.  It is only used to find the very narrow orphan
    shape, and the real TypeScript compiler remains the acceptance authority.
    """
    out=[];quote=None;esc=False;i=0;s=str(line or '')
    while i<len(s):
        ch=s[i]
        if quote:
            if esc:esc=False
            elif ch=='\\':esc=True
            elif ch==quote:quote=None
            out.append(' ');i+=1;continue
        if ch in ('"',"'",'`'):
            quote=ch;out.append(' ');i+=1;continue
        # Drop // comments.  Block comments are harmless for the narrow brace-depth
        # use here; compiler proof catches any bad candidate.
        if ch=='/' and i+1<len(s) and s[i+1]=='/':
            out.extend(' '*(len(s)-i));break
        out.append(ch);i+=1
    return ''.join(out)


def _v4227_line_depths(lines):
    depth=0;before=[]
    for line in lines:
        before.append(depth)
        masked=_v4227_mask_braces_line(line)
        depth+=masked.count('{')-masked.count('}')
    return before


def _v4227_decl_info(line):
    s=str(line or '').strip();exported=bool(re.match(r'^(?:export\b)',s))
    m=re.match(r'(?:(?:export|declare|default)\s+)*(?:interface|type|class|enum|function|const|let|var)\s+([A-Za-z_$][\w$]*)',s)
    return (m.group(1),exported) if m else ('',False)


def _v4227_orphan_top_level_fragment_candidate(text,rows):
    """Remove one provably orphaned top-level return/body fragment.

    A common failed cleanup shape is:
        interface HelperProps {...}
        const helperData = {...};
        const x = helperData[prop] || fallback;
        return (...);
        };
        interface NextThing ...

    The return is at module depth zero, which is never valid in authored TS/TSX.  We
    remove the smallest preceding non-exported declaration chain whose symbols have no
    references outside the malformed region.  A real tsc pass must then prove the
    target parser diagnostics are gone before the edit can be committed.
    """
    src=str(text or '');lines=src.splitlines(keepends=True)
    if not lines:return src,False,{}
    syntax=[r for r in (rows or []) if _v4227_ts_diag_is_syntax(r)]
    if not syntax:return src,False,{}
    diag_lines=[int(r.get('line') or 0) for r in syntax if int(r.get('line') or 0)>0]
    if not diag_lines:return src,False,{}
    depths=_v4227_line_depths(lines)
    # Find a module-level return immediately upstream of one of the parser diagnostics.
    returns=[]
    for i,line in enumerate(lines):
        if depths[i]==0 and re.match(r'^\s*return\b',line):
            if any((i+1)<=d and d-(i+1)<=40 for d in diag_lines):returns.append(i)
    if not returns:return src,False,{}
    ret=returns[-1];diag=max(d for d in diag_lines if d>=ret+1);end=min(len(lines),diag)
    # Include the diagnosed close line and a following blank, but never cross into the
    # next obvious declaration.  The diagnostic line is 1-indexed; `end` is exclusive.
    if end<len(lines) and not lines[end].strip():end+=1
    anchors=[]
    for i in range(0,ret):
        if depths[i]!=0:continue
        sym,exported=_v4227_decl_info(lines[i])
        if sym:anchors.append((i,sym,exported))
    if not anchors:return src,False,{}
    start=anchors[-1][0]
    # Expand backward over adjacent non-exported helper declarations that become dead
    # when the orphan body is removed.  Never delete an exported/public declaration.
    for i,sym,exported in reversed(anchors[:-1]):
        if exported:break
        outside=''.join(lines[:i]+lines[end:])
        if re.search(r'\b'+re.escape(sym)+r'\b',outside):break
        start=i
    if any(lines[i].lstrip().startswith('export ') for i in range(start,end)):
        return src,False,{}
    region=''.join(lines[start:end])
    if not re.search(r'(?m)^\s*return\b',region):return src,False,{}
    candidate=''.join(lines[:start]+lines[end:])
    if candidate==src:return src,False,{}
    return candidate,True,{'start_line':start+1,'end_line':end,'removed_preview':region[:2200]}


def _v4227_balanced_arrow_decl_span(text,symbol):
    """Locate one complete const/let arrow declaration, including typed React.FC form."""
    src=str(text or '');sym=re.escape(str(symbol or ''))
    head=re.compile(r'(?m)^\s*(?:const|let)\s+'+sym+r'\s*(?::[^=\n]+)?=\s*(?:async\s*)?[^\n]*?=>\s*\{')
    m=head.search(src)
    if not m:return None
    arrow_pos=src.find('=>',m.start(),m.end())
    if arrow_pos<0:return None
    # Destructured parameters may contain `{ ... }`; the function body begins only
    # after the arrow token.  Starting at the parameter brace is exactly how a partial
    # helper removal can leave an orphaned body behind.
    open_pos=src.find('{',arrow_pos+2,m.end())
    if open_pos<0:return None
    depth=0;quote=None;esc=False;i=open_pos
    while i<len(src):
        ch=src[i]
        if quote:
            if esc:esc=False
            elif ch=='\\':esc=True
            elif ch==quote:quote=None
            i+=1;continue
        if ch in ('"',"'",'`'):quote=ch;i+=1;continue
        if ch=='/' and i+1<len(src) and src[i+1]=='/':
            j=src.find('\n',i+2);i=len(src) if j<0 else j+1;continue
        if ch=='/' and i+1<len(src) and src[i+1]=='*':
            j=src.find('*/',i+2);i=len(src) if j<0 else j+2;continue
        if ch=='{':depth+=1
        elif ch=='}':
            depth-=1
            if depth==0:
                end=i+1
                while end<len(src) and src[end] in ' \t':end+=1
                if end<len(src) and src[end]==';':end+=1
                if end<len(src) and src[end]=='\r':end+=1
                if end<len(src) and src[end]=='\n':end+=1
                return m.start(),end
        i+=1
    return None


# Replace V42.26's regex-first unused-function cleanup with a balanced declaration
# removal for typed arrows.  The inherited cleaner still handles simpler local forms.
_v4227_prev_remove_unused_function_or_local=_v4226_remove_unused_function_or_local

def _v4226_remove_unused_function_or_local(text,rows):
    src=str(text or '');reasons=[];remaining=[]
    for row in rows or []:
        if str(row.get('code') or '')!='6133':remaining.append(row);continue
        sym=_v4223_diag_symbol(row)
        if not sym:remaining.append(row);continue
        span=_v4227_balanced_arrow_decl_span(src,sym)
        if span:
            src=src[:span[0]]+src[span[1]:]
            reasons.append(f'TS6133 balanced removal of unused arrow function {sym}')
        else:remaining.append(row)
    out,old=_v4227_prev_remove_unused_function_or_local(src,remaining)
    reasons.extend(old)
    return out,reasons


def _v4227_write_structural_report(work,payload):
    try:
        p=Path(work)/V4227_STRUCTURAL_REPORT
        old=_v4225_json_load(p,{'repairs':[]})
        hist=list(old.get('repairs') or []);hist.append(payload);old.update({'version':'V'+V4227_VERSION,'updated_at':_utc_stamp(),'repairs':hist[-80:]})
        _v4225_json_save(p,old)
    except Exception:pass


def _v4227_try_structural_ts_repair(work,manifest,rel,problems,validation_failure,progress_callback=None):
    if not V4227_ENABLE_STRUCTURAL_RECOVERY:return False
    rel=_v40_norm_rel(rel);ext=Path(rel).suffix.lower()
    if ext not in {'.ts','.tsx','.mts','.cts','.js','.jsx'}:return False
    rows=_v4222_parse_ts_diagnostics(work,str(validation_failure or ''))
    target_rows=[r for r in rows if _v40_norm_rel(r.get('file'))==rel and _v4227_ts_diag_is_syntax(r)]
    if not target_rows:return False
    path=Path(work)/rel
    try:original=path.read_text(encoding='utf-8',errors='replace')
    except Exception:return False
    candidate,changed,meta=_v4227_orphan_top_level_fragment_candidate(original,target_rows)
    if not changed:return False
    if _content_validation_error(rel,candidate):return False
    sem=_v4221_semantic_role_error(work,manifest or {},rel,candidate)
    if sem:return False
    td=None
    try:
        td,clone=_v4224_clone_workspace(work)
        cp=Path(clone)/rel;cp.parent.mkdir(parents=True,exist_ok=True);cp.write_text(candidate,encoding='utf-8')
        after_count,output=_v4224_measure_typescript(work,clone,manifest or {},rel)
        if after_count is None:return False
        after_rows=_v4222_parse_ts_diagnostics(clone,str(output or ''))
        after_syntax=[r for r in after_rows if _v40_norm_rel(r.get('file'))==rel and _v4227_ts_diag_is_syntax(r)]
        before_keys={(str(r.get('code')),int(r.get('line') or 0),str(r.get('message') or '')) for r in target_rows}
        if after_syntax or not before_keys:return False
        _v36_checkpoint_file(work,rel,original,'before_v4227_structural_syntax_recovery')
        tmp=path.with_name(path.name+'.v4227.tmp');tmp.write_text(candidate,encoding='utf-8');os.replace(tmp,path)
        try:_v413_mark_accepted(work,rel,'v4227_compiler_proven_structural_syntax_recovery')
        except Exception:pass
        try:_V36_REPO_CACHE.clear();_V36_CONTRACT_CACHE.clear();_V4225_SEM_CACHE.clear()
        except Exception:pass
        payload={'at':_utc_stamp(),'file':rel,'before_syntax':[str(r.get('raw') or '') for r in target_rows[:12]],'after_syntax':[], 'after_total_diagnostics':after_count, **meta}
        _v4227_write_structural_report(work,payload)
        _append_project_event(work,'v4227_structural_syntax_repair_committed',
            f'V42.27 deterministically removed one orphaned TypeScript/TSX structural fragment in {rel}; the real compiler proved the target parser diagnostics are now zero.',
            file=rel,before_syntax=len(target_rows),after_syntax=0,after_total=after_count,span={'start_line':meta.get('start_line'),'end_line':meta.get('end_line')})
        _progress(progress_callback,f'V42.27 parser-safe recovery: compiler-proven structural repair fixed {rel} before another Qwen retry.',stage='V42.27 deterministic structural syntax recovery',percent=80,current_file=rel)
        return True
    except Exception as exc:
        try:_append_project_event(work,'v4227_structural_syntax_repair_rejected',f'V42.27 structural syntax recovery did not obtain trustworthy compiler proof for {rel}; source was preserved.',file=rel,error=str(exc)[:1200])
        except Exception:pass
        return False
    finally:
        if td:
            try:shutil.rmtree(td,ignore_errors=True)
            except Exception:pass


# Deterministic parser repair gets first refusal even when a previous cluster/leaf
# repair family is marked exhausted.  A successful edit changes the accepted revision;
# ordinary loop fingerprints therefore reset naturally on fresh compiler evidence.
_v4227_prev_repair_file_for_issues=_repair_file_for_issues

def _repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback=None,validation_failure=None):
    rel=_v40_norm_rel(rel);failure=str(validation_failure or '')
    if _v4218_is_syntax_problem(rel,problems,failure):
        try:
            if _v4227_try_structural_ts_repair(work,manifest or {},rel,problems,failure,progress_callback):return True
        except Exception:pass
    return bool(_v4227_prev_repair_file_for_issues(user_request,manifest,work,rel,problems,progress_callback,validation_failure=validation_failure))


# Keep current-engine identity consistent in new durable events.  Earlier wrappers used
# setdefault(), which allowed a V42.26 run to stamp V42.25 in newly-created events.
_v4227_prev_append_project_event=_append_project_event

def _append_project_event(work,event_type,message,**fields):
    fields=dict(fields);fields['engine_version']='V'+V4227_VERSION
    event=_v4227_prev_append_project_event(work,event_type,message,**fields)
    try:
        p=Path(work)/globals().get('V4225_PROJECTION_FILE','JARVIS_V4225_EVENT_PROJECTION.json')
        data=_v4225_json_load(p,{})
        if isinstance(data,dict):
            data['version']='V'+V4227_VERSION;data['engine']=V4227_ENGINE;data['updated_at']=_utc_stamp();_v4225_json_save(p,data)
    except Exception:pass
    return event


_v4227_prev_qwen_call=_qwen_call

def _qwen_call(prompt,progress_callback=None,stage='Generating',profile='chat',**kwargs):
    body=str(prompt or '')+(
        '\n\nV42.27 PARSER-SAFE FINAL AUTHORITY: A lower total compiler error count never justifies introducing a parser/syntax regression in a changed file. Changed TypeScript/TSX files must be compiler syntax-clean before a coordinated transaction can commit. For TS1005/TS1109/TS1128 and related parser failures, reconstruct or remove the smallest complete malformed syntactic construct; do not append another fragment. Jarvis attempts conservative compiler-proven structural recovery before model repair, and an exhausted same-revision parser repair must not restart without fresh accepted source or fresh compiler evidence.'
    )
    stage2=str(stage or '')
    for old in ('V42.26','V42.25','V42.24','V42.23','V42.22','V42.21','V42.20','V42.19','V42.18','V42.17','V42.16','V42.13','V42.9','V42.8','V42.7','V42.6','V42.4'):
        stage2=stage2.replace(old,'V42.27')
    return _v4227_prev_qwen_call(body,progress_callback,stage2,profile=profile,**kwargs)


_v4227_prev_release_identity=_v36_release_identity

def _v36_release_identity():
    data=dict(_v4227_prev_release_identity() or {})
    data.update({
        'version':'V'+V4227_VERSION,
        'engine':V4227_ENGINE,
        'planner_mode':'parser-safe-compiler-delta-structural-recovery-v42.27',
        'changed_ts_files_must_be_compiler_syntax_clean':True,
        'global_error_delta_cannot_hide_parser_regression':True,
        'ts1128_and_parser_family_are_deterministic_first':True,
        'orphan_top_level_fragment_compiler_proven_recovery':True,
        'balanced_typed_arrow_unused_cleanup':True,
        'structural_repair_runs_before_exhausted_model_reentry':True,
        'journal_event_engine_identity_current':True,
        'v4226_global_compiler_proof_preserved':True,
        'v4225_loop_guard_event_semantics_preserved':True,
    })
    return data


_v4227_prev_progress=_progress

def _progress(callback,text=None,**fields):
    if text is not None:
        text=str(text)
        for old in ('V42.26','V42.25','V42.24','V42.23','V42.22','V42.21','V42.20','V42.19','V42.18','V42.17','V42.16','V42.13','V42.9','V42.8','V42.7','V42.6','V42.4'):
            text=text.replace(old,'V42.27')
    return _v4227_prev_progress(callback,text,**fields)


# =============================================================================
# V42.28 BEST-VERIFIED RESUME SCORING + ENDGAME TYPESCRIPT CLOSURE
# =============================================================================
# V42.26 proved that coordinated compiler-directed transactions can collapse a large
# TypeScript error set (for example 37 -> 3), but the generic resume scorer historically
# reduced every failed real build to the same coarse score.  That meant a dramatically
# better trial could be discarded simply because both the old and new project still
# returned a non-zero build exit code.  A later parser failure could also look like
# "only one error" even though it blocked TypeScript from revealing semantic debt.
#
# V42.28 keeps the successful V42.26 dependency-first/compiler-proof pipeline and the
# V42.27 parser-safety recovery, then makes compiler evidence part of checkpoint state:
#   * successful build/runtime is best;
#   * a non-TypeScript runtime/integration failure is deeper progress than compile debt;
#   * syntax-clean TypeScript semantic debt is ranked by real diagnostic count;
#   * parser/syntax TypeScript debt is ranked behind syntax-clean semantic debt even if
#     the parser currently prints only one error;
#   * deterministic/static defects remain the earliest/worst phase;
#   * resume sweeps therefore promote 37 -> 3, never lose it, and checkpoint the actual
#     best verified working state;
#   * when acceptance is down to a tiny TypeScript tail, Jarvis gets one bounded
#     deterministic compiler-proven cleanup transaction before spending more model time.

V4228_VERSION='42.28.0'
V4228_ENGINE='BEST_VERIFIED_RESUME_SCORE_ENDGAME_CLOSURE_FACTORY'
V4228_STATE_FILE='JARVIS_V4228_BEST_VERIFIED_STATE.json'
V4228_ENDGAME_MAX_DIAGNOSTICS=max(1,min(12,int(os.getenv('JARVIS_V4228_ENDGAME_MAX_DIAGNOSTICS','6'))))
V4228_ENDGAME_DETERMINISTIC=os.getenv('JARVIS_V4228_ENDGAME_DETERMINISTIC','1').strip().lower() not in {'0','false','no','off'}
V4228_RESUME_SWEEPS=max(2,min(4,int(os.getenv('JARVIS_V4228_RESUME_SWEEPS','3'))))
if 'JARVIS_QWEN_RESUME_SWEEPS' not in os.environ:
    RESUME_SWEEPS=max(int(RESUME_SWEEPS),V4228_RESUME_SWEEPS)


def _v4228_ts_quality(work, real_output):
    """Return compiler quality facts from real validation evidence.

    Lower phase is better:
      0 fully green (assigned by snapshot wrapper)
      1 real/runtime/integration failure with no TypeScript compiler debt
      2 syntax-clean TypeScript semantic/type debt
      3 TypeScript parser/syntax debt (can hide downstream semantic diagnostics)
      4 deterministic/static source defects (assigned by snapshot wrapper)
    """
    try: rows=_v4222_parse_ts_diagnostics(work,str(real_output or ''))
    except Exception: rows=[]
    syntax=[r for r in rows if _v4227_ts_diag_is_syntax(r)]
    return {
        'typescript_diagnostics':len(rows),
        'typescript_syntax_diagnostics':len(syntax),
        'typescript_signature':_v4223_ts_signature(rows) if rows else '',
        'typescript_rows':rows,
    }


_v4228_prev_resume_validation_snapshot=_resume_validation_snapshot

def _resume_validation_snapshot(work,manifest,user_request,include_real=True):
    """Score resumed candidates by *depth of verified compiler progress*, not exit code.

    This is the promotion fix that makes an objectively better 37 -> 3 TypeScript trial
    replace `working` even though neither state is final-green yet.
    """
    snap=dict(_v4228_prev_resume_validation_snapshot(work,manifest,user_request,include_real=include_real) or {})
    deterministic=list(snap.get('deterministic_issues') or [])
    real_ok=snap.get('real_ok')
    q=_v4228_ts_quality(work,snap.get('real_output') or '')
    ts_count=int(q.get('typescript_diagnostics') or 0)
    syntax_count=int(q.get('typescript_syntax_diagnostics') or 0)
    if real_ok is True and not deterministic:
        phase=0;metric=0;label='green'
    elif deterministic:
        # Static/deterministic source defects are less advanced than a source-clean
        # project whose only remaining evidence comes from a real compiler/runtime.
        phase=4;metric=int(snap.get('weighted_issues') or len(deterministic) or 1);label='deterministic-source-debt'
    elif ts_count:
        if syntax_count:
            phase=3;metric=syntax_count*1000+ts_count;label='typescript-parser-debt'
        else:
            phase=2;metric=ts_count;label='typescript-semantic-debt'
    else:
        phase=1;metric=1;label='post-compile-runtime-or-integration-debt'
    # Keep the tuple compact because older resume code compares it lexicographically.
    # The phase prevents "1 parser error" from beating "3 syntax-clean semantic errors".
    snap['score']=(phase,int(metric),len(deterministic))
    snap.update({
        'v4228_phase':phase,
        'v4228_phase_label':label,
        'typescript_diagnostic_count':ts_count,
        'typescript_syntax_diagnostic_count':syntax_count,
        'typescript_diagnostic_signature':q.get('typescript_signature') or '',
    })
    try:
        payload={
            'version':'V'+V4228_VERSION,'engine':V4228_ENGINE,'updated_at':_utc_stamp(),
            'score':list(snap['score']),'phase':phase,'phase_label':label,
            'typescript_diagnostic_count':ts_count,
            'typescript_syntax_diagnostic_count':syntax_count,
            'real_ok':real_ok,'deterministic_issue_count':len(deterministic),
            'repository_token':_v429_progress_token(work),
        }
        _v4225_json_save(Path(work)/V4228_STATE_FILE,payload)
    except Exception:pass
    return snap


_v4228_prev_snapshot_summary=_resume_snapshot_summary

def _resume_snapshot_summary(snapshot):
    out=dict(_v4228_prev_snapshot_summary(snapshot) or {})
    out.update({
        'verified_phase':(snapshot or {}).get('v4228_phase'),
        'verified_phase_label':(snapshot or {}).get('v4228_phase_label'),
        'typescript_diagnostics':int((snapshot or {}).get('typescript_diagnostic_count') or 0),
        'typescript_syntax_diagnostics':int((snapshot or {}).get('typescript_syntax_diagnostic_count') or 0),
        'typescript_signature':str((snapshot or {}).get('typescript_diagnostic_signature') or ''),
    })
    return out


def _v4228_issue_failure_text(issues):
    chunks=[]
    for item in issues or []:
        if isinstance(item,dict):
            chunks.append(str(item.get('problem') or item.get('raw') or item))
        else:chunks.append(str(item or ''))
    return '\n'.join(x for x in chunks if x)


def _v4228_try_endgame_deterministic(user_request,manifest,work,issues,progress_callback=None):
    """One bounded deterministic cleanup transaction for the final small TS tail.

    No source is committed unless a fresh TypeScript compile strictly improves the
    syntax-aware compiler state; the V42.27 changed-file syntax gate still applies.
    """
    if not V4228_ENDGAME_DETERMINISTIC:return False
    failure=_v4228_issue_failure_text(issues)
    rows=_v4222_parse_ts_diagnostics(work,failure)
    if not rows or len(rows)>V4228_ENDGAME_MAX_DIAGNOSTICS:return False
    # Parser blockers get the dedicated structural path first; this is safer than
    # letting the bulk hygiene pass operate around malformed syntax.
    for row in rows:
        if not _v4227_ts_diag_is_syntax(row):continue
        rel=_v40_norm_rel(row.get('file'))
        if not rel:continue
        try:
            if _v4227_try_structural_ts_repair(work,manifest or {},rel,[str(row.get('raw') or row.get('message') or '')],failure,progress_callback):
                _append_project_event(work,'v4228_endgame_structural_progress',
                    f'V42.28 deterministically removed the parser blocker in {rel}; acceptance will rebuild from fresh compiler evidence.',file=rel)
                return True
        except Exception:pass
    td=None
    try:
        # Pick the first compiler-owned file only as the component/root hint.  The bulk
        # doctor may stage fixes across multiple related files inside the clone.
        hint=_v40_norm_rel(rows[0].get('file'))
        td,clone=_v4224_clone_workspace(work)
        before=len(rows)
        try:_v4223_bulk_ts_recovery(clone,manifest or {},failure,None)
        except Exception:return False
        changed=_v4225_diff_source_files(work,clone)
        if not changed:return False
        after,output=_v4224_measure_typescript(work,clone,manifest or {},hint)
        if after is None or int(after)>=int(before):return False
        ok,why=_v4224_commit_cluster(work,clone,manifest or {},changed,before,after)
        if ok:
            _append_project_event(work,'v4228_endgame_deterministic_committed',
                f'V42.28 committed the final compiler-proven deterministic cleanup because TypeScript diagnostics decreased {before} -> {after}.',
                files=changed,before=before,after=after)
            _progress(progress_callback,
                f'V42.28 endgame compiler cleanup reduced TypeScript diagnostics {before} -> {after}; rebuilding acceptance immediately.',
                stage='V42.28 deterministic endgame closure',percent=92,current_file=hint)
            return True
        try:_append_project_event(work,'v4228_endgame_deterministic_rejected','V42.28 preserved source because the final deterministic candidate failed transactional gates.',reason=str(why or '')[:1600],files=changed)
        except Exception:pass
        return False
    finally:
        if td:
            try:shutil.rmtree(td,ignore_errors=True)
            except Exception:pass


# Give a tiny compiler tail one deterministic closure pass after the normal acceptance
# machinery returns.  Only a proven source change earns a second acceptance invocation,
# so this cannot turn into an acceptance-pass loop.
_v4228_prev_acceptance_repair_cycle=_acceptance_repair_cycle

def _acceptance_repair_cycle(user_request,manifest,work,progress_callback=None):
    ok,issues=_v4228_prev_acceptance_repair_cycle(user_request,manifest,work,progress_callback)
    if ok:return ok,issues
    try:changed=_v4228_try_endgame_deterministic(user_request,manifest,work,issues,progress_callback)
    except Exception:changed=False
    if not changed:return ok,issues
    _append_project_event(work,'v4228_acceptance_rebuild_after_endgame_fix',
        'V42.28 obtained a compiler-proven endgame source improvement; running one fresh acceptance cycle instead of returning a stale checkpoint.')
    return _v4228_prev_acceptance_repair_cycle(user_request,manifest,work,progress_callback)


# Checkpoint metadata explicitly records the verified phase/error count that caused the
# current `working` tree to beat its predecessor.  Because _run_resume_sweeps compares
# the V42.28 score, this work directory is now the objectively best promoted source.
