def _package_resume_checkpoint_zip(work,manifest,original_request,latest_instruction,unresolved_issues,source_zip_name='',resume_count=1,snapshot=None,stamp=None):
    snapshot=snapshot or _resume_validation_snapshot(work,manifest,original_request or latest_instruction,include_real=True)
    out,count=_v4228_prev_package_resume_checkpoint_zip(work,manifest,original_request,latest_instruction,unresolved_issues,source_zip_name=source_zip_name,resume_count=resume_count,snapshot=snapshot,stamp=stamp)
    # The inner V42.23 wrapper already writes canonical resume metadata.  Add a small
    # sidecar inside the ZIP so a human can immediately see that the checkpoint really
    # represents the best compiler-verified state rather than an arbitrary `working` dir.
    try:
        proof={
            'version':'V'+V4228_VERSION,'engine':V4228_ENGINE,'created_at':_utc_stamp(),
            'score':list(snapshot.get('score') or []),
            'phase':snapshot.get('v4228_phase_label'),
            'typescript_diagnostics':snapshot.get('typescript_diagnostic_count',0),
            'typescript_syntax_diagnostics':snapshot.get('typescript_syntax_diagnostic_count',0),
            'repository_token':_v429_progress_token(work),
            'policy':'Checkpoint source is the best objectively promoted resume state; failed/worse trials never replace it.',
        }
        with zipfile.ZipFile(out,'a',compression=zipfile.ZIP_DEFLATED) as z:
            z.writestr('JARVIS_V4228_BEST_STATE_PROOF.json',json.dumps(proof,indent=2,ensure_ascii=False))
        count+=1
    except Exception:pass
    return out,count


# Make V42.28 the final visible policy without weakening the successful V42.26/V42.27
