_v4230_prev_progress=_progress

def _progress(callback,text=None,**fields):
    if text is not None:
        text=str(text)
        for old in ('V42.29','V42.28','V42.27','V42.26','V42.25','V42.24','V42.23','V42.22','V42.21','V42.20','V42.19','V42.18','V42.17','V42.16','V42.13','V42.9','V42.8','V42.7','V42.6','V42.4'):
            text=text.replace(old,'V42.30')
    fields=dict(fields);fields['engine_version']='V'+V4230_VERSION
    return _v4230_prev_progress(callback,text,**fields)

# V42.30 identity-chain correction -------------------------------------------------
# Newer event/progress wrappers must not call older wrappers that *overwrite* the
# engine version on the way down the chain.  V42.29's event wrapper called V42.28,
# which called V42.27, so journal rows could incorrectly end up stamped V42.27 even
# while newer logic was executing.  Route directly through the V42.25 durable-event
# projection wrapper (which uses setdefault for engine_version) and the V42.27-era
# progress wrapper (which does not overwrite engine_version).

def _append_project_event(work,event_type,message,**fields):
    fields=dict(fields);fields['engine_version']='V'+V4230_VERSION
    # _v4227_prev_append_project_event is the V42.25 durable projection wrapper.
    event=_v4227_prev_append_project_event(work,event_type,message,**fields)
    try:
        p=Path(work)/globals().get('V4225_PROJECTION_FILE','JARVIS_V4225_EVENT_PROJECTION.json')
        data=_v4225_json_load(p,{})
        if isinstance(data,dict):
            data['version']='V'+V4230_VERSION
            data['engine']=V4230_ENGINE
            data['updated_at']=_utc_stamp()
            _v4225_json_save(p,data)
    except Exception:pass
    return event


def _progress(callback,text=None,**fields):
    if text is not None:
        text=str(text)
        for old in ('V42.29','V42.28','V42.27','V42.26','V42.25','V42.24','V42.23','V42.22','V42.21','V42.20','V42.19','V42.18','V42.17','V42.16','V42.13','V42.9','V42.8','V42.7','V42.6','V42.4'):
            text=text.replace(old,'V42.30')
    fields=dict(fields);fields['engine_version']='V'+V4230_VERSION
    # _v4228_prev_progress is the V42.27 wrapper; it preserves unknown newer labels
    # and does not replace engine_version.
    return _v4228_prev_progress(callback,text,**fields)

# Final V42.30 UI progress dispatch: bypass all historical label-rewrite wrappers.
def _progress(callback,text=None,**fields):
    if text is not None:
        text=str(text)
        for old in ('V42.29','V42.28','V42.27','V42.26','V42.25','V42.24','V42.23','V42.22','V42.21','V42.20','V42.19','V42.18','V42.17','V42.16','V42.15','V42.14','V42.13','V42.12','V42.11','V42.10','V42.9','V42.8','V42.7','V42.6','V42.5','V42.4','V42.3','V42.2','V42.1','V42.0'):
            # Word-ish boundary prevents V42.3 from mutating the prefix of V42.30.
            text=re.sub(re.escape(old)+r'(?!\d)', 'V42.30', text)
    fields=dict(fields);fields['engine_version']='V'+V4230_VERSION
    return _v38_prev_progress(callback,text,**fields)

